// DIAG2: In-Memory Ring Buffer & Telemetry Sink for Sandbox Observation
export interface Diag2EventRecord {
  seq: number;
  timestamp: number;
  name: string;
  payload: Record<string, any>;
  formatted: string;
  isDup: boolean;
}

export const DIAG2_BUFFER_CAPACITY = 40;
export const DIAG2_EVENT_BUFFER: Diag2EventRecord[] = [];
export let diag2SequenceCounter = 0;
export let diag2TotalEventsRecorded = 0;
export let diag2MountCounter = 0;
export let diag2FirstGate1BlockSnapshot: Diag2EventRecord[] | null = null;
let diag2LastEventSig = '';

export const diag2Listeners = new Set<() => void>();

export function notifyDiag2Listeners() {
  for (const listener of diag2Listeners) {
    try {
      listener();
    } catch {
      // safe no-op
    }
  }
}

let copilotWaitingShellRuntimeEnabled = false;
export function setCoPilotWaitingShellRuntimeEnabled(enabled: boolean): void {
  copilotWaitingShellRuntimeEnabled = Boolean(enabled);
  if (!copilotWaitingShellRuntimeEnabled) {
    setCoPilotWaitingShell(false);
  }
}

export function setCoPilotWaitingShell(visible: boolean, actorLabel?: string): void {
  try {
    if (typeof document === 'undefined') return;
    if (visible && !copilotWaitingShellRuntimeEnabled) return;
    let el = document.getElementById('copilot-waiting-shell');
    if (!visible) {
      el?.remove();
      return;
    }
    if (!el) {
      el = document.createElement('div');
      el.id = 'copilot-waiting-shell';
      el.setAttribute('data-testid', 'copilot-waiting-shell');
      el.setAttribute(
        'style',
        'position:fixed;inset:0;z-index:2147483645;background:#0f172a;color:#e2e8f0;padding:32px;font-family:ui-sans-serif,system-ui,sans-serif'
      );
      document.body.appendChild(el);
    }
    const nameRaw = actorLabel && String(actorLabel).trim() ? String(actorLabel) : 'Another player';
    const name = nameRaw.replace(/</g, '&lt;');
    el.innerHTML = `<div style="max-width:560px"><div style="font-size:20px;font-weight:800;color:#93c5fd">Co-Pilot is waiting for other players</div><p style="margin-top:12px;color:#cbd5e1;line-height:1.5">${name} is taking their turn. Adam’s turn will resume automatically. Do not refresh.</p></div>`;
  } catch {
    // shell must never throw
  }
}

/** Full-screen "waiting for other players" overlay. Off by default — the HUD stays visible. */
export function isCoPilotWaitingShellEnabled(settings?: any): boolean {
  const cp = settings?.coPilotSettings || settings;
  return cp?.showWaitingForOtherPlayersShell === true;
}

let diag2RuntimeEnabled = false;
export function setDiag2RuntimeEnabled(enabled: boolean): void {
  diag2RuntimeEnabled = Boolean(enabled);
}

export function isDiag2RuntimeEnabled(): boolean {
  return diag2RuntimeEnabled;
}

let copilotStartPhaseOverlayEnabled = false;
export function setCoPilotStartPhaseOverlayEnabled(enabled: boolean): void {
  copilotStartPhaseOverlayEnabled = Boolean(enabled);
  if (!copilotStartPhaseOverlayEnabled && typeof document !== 'undefined') {
    document.getElementById('copilot-start-phase')?.remove();
  }
}

export function setCoPilotStartPhase(phase: string): void {
  try {
    let prevRunTail = '';
    if (typeof window !== 'undefined') {
      (window as any).__copilotStartPhase = phase;
      // Resume-hang diagnostics: persist the phase sequence in sessionStorage so it survives a
      // main-thread hang + Ctrl+Shift+R. On the first call of a page load, the previous run's log
      // is moved to copilotPhaseLogPrev and its tail is painted under the live label.
      try {
        const w = window as any;
        const ss = window.sessionStorage;
        if (!Array.isArray(w.__copilotPhaseLog)) {
          w.__copilotPhaseLog = [];
          const prev = ss?.getItem('copilotPhaseLog') || '';
          if (prev) ss?.setItem('copilotPhaseLogPrev', prev);
          w.__copilotPhaseLogPrev = prev;
        }
        const log: string[] = w.__copilotPhaseLog;
        const now = typeof performance !== 'undefined' && typeof performance.now === 'function' ? Math.round(performance.now()) : Date.now();
        log.push(`${now}:${phase}`);
        if (log.length > 80) log.splice(0, log.length - 80);
        ss?.setItem('copilotPhaseLog', log.join('\n'));
        const prevLog = String(w.__copilotPhaseLogPrev || '');
        if (prevLog) prevRunTail = prevLog.split('\n').slice(-6).join(' > ');
      } catch {
        // storage may be unavailable; overlay still paints
      }
    }
    if (typeof document === 'undefined' || !copilotStartPhaseOverlayEnabled) return;
    let el = document.getElementById('copilot-start-phase');
    if (!el) {
      el = document.createElement('div');
      el.id = 'copilot-start-phase';
      el.setAttribute(
        'data-testid',
        'copilot-start-phase'
      );
      el.setAttribute(
        'style',
        'position:fixed;left:8px;top:8px;z-index:2147483646;background:#0f172a;color:#7dd3fc;padding:8px 12px;font:12px/1.4 ui-monospace,monospace;border:1px solid #38bdf8;pointer-events:none;max-width:90vw'
      );
      document.body.appendChild(el);
    }
    el.textContent = prevRunTail
      ? `[Co-Pilot Start] ${phase}\n[prev run tail] ${prevRunTail}`
      : `[Co-Pilot Start] ${phase}`;
    if (prevRunTail) el.style.whiteSpace = 'pre-wrap';
  } catch {
    // overlay must never throw
  }
}

export function afterNextPaint(fn: () => void): void {
  if (typeof requestAnimationFrame === 'function') {
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        window.setTimeout(fn, 0);
      });
    });
  } else {
    setTimeout(fn, 32);
  }
}

export const COPILOT_MAX_BLOCKED_CONTINUES = 2;

export function shouldHoldAfterBlockedContinue(blockedContinueCount: number): boolean {
  return blockedContinueCount >= COPILOT_MAX_BLOCKED_CONTINUES;
}

export function hashCoPilotLiveState(stateObj: any): string {
  try {
    if (typeof computeTakeoverFingerprint === 'function') {
      return computeTakeoverFingerprint(stateObj);
    }
  } catch {
    // fall through
  }
  try {
    return typeof computeCanonicalStateHash === 'function' ? computeCanonicalStateHash(stateObj) : '';
  } catch {
    return '00000000';
  }
}

export function formatDiagField(v: any): string {
  if (v === undefined) return 'und';
  if (v === null) return 'null';
  if (v === true) return 'T';
  if (v === false) return 'F';
  return String(v);
}

export function formatDiag2CompactLine(seq: number, name: string, p: Record<string, any>, isDup: boolean): string {
  const dupPrefix = isDup ? '⟳DUP ' : '';
  const seqStr = `#${seq.toString().padStart(2, '0')}`;
  
  if (name === 'SET_TURN') {
    return `${seqStr} ${dupPrefix}SET_TURN ${p.prevActorId}→${p.nextActorId} tc=${p.turnCounter} team=${p.isTeam ? 'T' : 'F'} pay=${p.payloadNextTurn}`;
  }
  if (name === 'SET_CURRENT_ACTOR') {
    return `${seqStr} ${dupPrefix}SET_CURRENT_ACTOR ${p.prevActorId}→${p.nextActorId} tc=${p.turnCounter} team=${p.isTeam ? 'T' : 'F'}`;
  }
  if (name === 'ADVANCE_ACTOR_TURN') {
    return `${seqStr} ${dupPrefix}ADVANCE_ACTOR_TURN ${p.prevActorId}→${p.nextActorId} tc=${p.turnCounter}→${p.nextTurnCounter} team=${p.isTeam ? 'T' : 'F'}`;
  }
  if (name === 'SET_TURN_COUNTER') {
    return `${seqStr} ${dupPrefix}SET_TURN_COUNTER tc ${p.prevTurnCounter}→${p.nextTurnCounter} actor=${p.currentActorId} team=${p.isTeam ? 'T' : 'F'}`;
  }
  if (name === 'RESET_GAME') {
    return `${seqStr} ${dupPrefix}RESET_GAME actor ${p.prevActorId}→${p.nextActorId} tc ${p.prevTurnCounter}→${p.nextTurnCounter}`;
  }
  if (name === 'LOAD_STATE_ACTOR') {
    return `${seqStr} ${dupPrefix}LOAD_STATE_ACTOR ${p.prevActorId}→${p.nextActorId} tc=${p.turnCounter} payTc=${p.payloadTurnCounter} team=${p.isTeam ? 'T' : 'F'}`;
  }
  if (name === 'LOAD_STATE_TC') {
    return `${seqStr} ${dupPrefix}LOAD_STATE_TC tc ${p.prevTurnCounter}→${p.nextTurnCounter} actor=${p.currentActorId} payActor=${p.payloadActorId} team=${p.isTeam ? 'T' : 'F'}`;
  }
  if (name === 'COPILOT_COMMIT_ACTOR') {
    return `${seqStr} ${dupPrefix}COPILOT_COMMIT_ACTOR ${p.prevActorId}→${p.nextActorId} tc=${p.turnCounter} team=${p.isTeam ? 'T' : 'F'}`;
  }
  if (name === 'COPILOT_COMMIT_TC') {
    return `${seqStr} ${dupPrefix}COPILOT_COMMIT_TC tc ${p.prevTurnCounter}→${p.nextTurnCounter} actor=${p.currentActorId} team=${p.isTeam ? 'T' : 'F'}`;
  }
  // DIAG3: Extended commit boundary formatting
  if (name === 'COMMIT_PRE') {
    const plStr = p.livePlayerExists ? `pl[k=${formatDiagField(p.livePlayerKind)} ai=${formatDiagField(p.livePlayerIsAi)} hu=${formatDiagField(p.livePlayerIsHuman)}]` : 'pl[NONE]';
    const payAbpStr = p.payAbpExists ? `payAbp[k=${formatDiagField(p.payAbpKind)} ai=${formatDiagField(p.payAbpIsAi)} hu=${formatDiagField(p.payAbpIsHuman)}]` : 'payAbp[NONE]';
    return `${seqStr} ${dupPrefix}COMMIT_PRE live[act=${p.liveStateCurrentActorId} tc=${p.liveStateTurnCounter} ${plStr}] pay[act=${p.payloadCurrentActorId} tc=${p.payloadTurnCounter} ${payAbpStr} hasAb=${p.hasPayloadActorsById ? 'T' : 'F'} hasPl=${p.hasPayloadPlayer ? 'T' : 'F'}] actType=${p.actionType}`;
  }
  if (name === 'COMMIT_POST') {
    const plStr = p.postPlayerExists ? `postPl[k=${formatDiagField(p.postPlayerKind)} ai=${formatDiagField(p.postPlayerIsAi)} hu=${formatDiagField(p.postPlayerIsHuman)}]` : 'postPl[NONE]';
    const payAbpStr = p.payAbpExists ? `payAbp[k=${formatDiagField(p.payAbpKind)} ai=${formatDiagField(p.payAbpIsAi)} hu=${formatDiagField(p.payAbpIsHuman)}]` : 'payAbp[NONE]';
    return `${seqStr} ${dupPrefix}COMMIT_POST live[act=${p.liveStateCurrentActorId} tc=${p.liveStateTurnCounter} ${plStr}] pay[act=${p.payloadCurrentActorId} tc=${p.payloadTurnCounter} ${payAbpStr} hasAb=${p.hasPayloadActorsById ? 'T' : 'F'} hasPl=${p.hasPayloadPlayer ? 'T' : 'F'}] actType=${p.actionType}`;
  }
  // DIAG3: Gate 1 actor resolution formatting
  if (name === 'ACTOR-RESOLVE') {
    const abpStr = p.abpExists
      ? `abp[k=${formatDiagField(p.abpKind)} ai=${formatDiagField(p.abpIsAi)} hu=${formatDiagField(p.abpIsHuman)} tid=${formatDiagField(p.abpTeamId)}]`
      : 'abp[NONE]';
    const pStr = p.pExists
      ? `p[k=${formatDiagField(p.pKind)} ai=${formatDiagField(p.pIsAi)} hu=${formatDiagField(p.pIsHuman)}]`
      : 'p[NONE]';
    const keysStr = Array.isArray(p.actorKeys) ? p.actorKeys.slice(0, 4).join(',') : '';
    return `${seqStr} ${dupPrefix}ACTOR-RESOLVE keys=[${keysStr}] ${abpStr} ${pStr} isHu=${p.isHuman ? 'T' : 'F'} huId=${formatDiagField(p.humanPlayerId)}`;
  }
  if (name === 'GATE1-TICK') {
    return `${seqStr} ${dupPrefix}GATE1-TICK can=${p.canCoPilotActNow ? 'T' : 'F'} act=${p.currentActorId} turn=${p.currentTurn} tc=${p.turnCounter} team=${p.isTeam ? 'T' : 'F'} sess=${p.sessionStatus} ap=${formatDiagField(p.apRemaining)} used=${formatDiagField(p.actionsUsedThisTurn)} stop=${p.manualStopLatched ? 'T' : 'F'} int=${p.isInterruptedByPlayer ? 'T' : 'F'} resumable=${p.autoResumable ? 'T' : 'F'}`;
  }
  if (name === 'GATE1-WAIT') {
    return `${seqStr} ${dupPrefix}GATE1-WAIT can=F act=${p.currentActorId} tc=${p.turnCounter} team=${p.isTeam ? 'T' : 'F'} sess=${p.sessionStatus} rsn=${p.reason || 'other_actor'}`;
  }
  if (name === 'GATE1-BLOCK') {
    return `${seqStr} ${dupPrefix}GATE1-BLOCK can=F act=${p.currentActorId} tc=${p.turnCounter} team=${p.isTeam ? 'T' : 'F'} mode=${p.selectedMode || p.gameMode} sess=${p.sessionStatus} why=${p.reason || 'unexpected'}`;
  }
  if (name === 'GATE2-OWNERSHIP') {
    return `${seqStr} ${dupPrefix}GATE2-OWNERSHIP can=${p.canCoPilotActNow ? 'T' : 'F'} act=${p.currentActorId} tc=${p.turnCounter} mode=${p.selectedMode}`;
  }
  if (name === 'GATE3-ENDTURN') {
    return `${seqStr} ${dupPrefix}GATE3-ENDTURN can=${p.canCoPilotActNow ? 'T' : 'F'} act=${p.currentActorId} tc=${p.turnCounter} mode=${p.selectedMode}`;
  }
  if (name === 'ADVANCE_ENTRY') {
    return `${seqStr} ${dupPrefix}ADVANCE_ENTRY act=${p.currentActorId} idx=${p.currentIndex}→${p.nextIndex} next=${p.nextActorId} tc=${p.currentTurnCounter}`;
  }
  if (name === 'ADVANCE_EXIT') {
    return `${seqStr} ${dupPrefix}ADVANCE_EXIT next=${p.nextActorId} nextTc=${p.nextTurnCounter} disp[tc=${p.reachedDispatchTurnCounter ? 'T' : 'F'} rnd=${p.reachedDispatchRoundNumber ? 'T' : 'F'} act=${p.reachedDispatchCurrentActor ? 'T' : 'F'} turn=${p.reachedDispatchTurn ? 'T' : 'F'}]`;
  }
  // CPFIX5: Session status transition compact formatting
  if (name === 'SESSION-STATUS') {
    const prev = formatDiagField(p.prevStatus);
    const next = formatDiagField(p.nextStatus);
    const writer = p.writer || 'unknown';
    const act = formatDiagField(p.currentActorId);
    const tc = formatDiagField(p.turnCounter);
    const rsn = p.reason ? ` rsn=${p.reason}` : '';
    const tok = p.sessionToken ? ` tok=..${String(p.sessionToken).slice(-4)}` : '';
    return `${seqStr} ${dupPrefix}SESSION-STATUS ${prev}→${next} w=${writer} act=${act} tc=${tc}${rsn}${tok}`;
  }
  // CPFIX6: AP-CHECK probe compact formatting
  if (name === 'AP-CHECK') {
    const actUsedStr = p.actionsUsedType === 'undefined' ? 'und' : String(p.actionsUsedThisTurn);
    const ovrStr = p.overrideType === 'undefined' ? 'und' : String(p.overrideActionsGranted);
    const apPtsStr = p.actionPointsType === 'undefined' ? 'und' : `${p.actionPoints}(${p.actionPointsType})`;
    const limStr = p.actionLimitsEnabled === false ? 'lim=F' : `lim=T max=${formatDiagField(p.playerActionsPerDay)}`;
    return `${seqStr} ${dupPrefix}AP-CHECK ap=${p.ap} used=${actUsedStr} ovr=${ovrStr} apPts=${apPtsStr} ${limStr} act=${formatDiagField(p.currentActorId)} tc=${formatDiagField(p.turnCounter)} src=${p.resolvedFrom}`;
  }
  if (name === 'APP_MOUNT') {
    return `${seqStr} ${dupPrefix}APP_MOUNT count=${p.mountCount} isStrictModeDoubleMount=${p.isStrictModeDoubleMount ? 'T' : 'F'}`;
  }
  // CPFIX7: CANDIDATE-REJECT probe compact formatting
  if (name === 'CANDIDATE-REJECT') {
    const attStr = p.attempt !== undefined ? ` att=${p.attempt}/${p.maxAttempts || 5}` : '';
    const chkStr = p.failedCheck ? ` chk=${p.failedCheck}` : '';
    return `${seqStr} ${dupPrefix}CANDIDATE-REJECT actType=${p.actionType || p.type}${attStr}${chkStr} rsn=${p.reason || 'unknown'}`;
  }
  if (name === 'COPILOT_LOOP_BEGIN') {
    return `${seqStr} ${dupPrefix}COPILOT_LOOP_BEGIN act=${formatDiagField(p.currentActorId)} tc=${formatDiagField(p.turnCounter)} sess=${formatDiagField(p.sessionStatus)} ap=${formatDiagField(p.ap)} gen=${formatDiagField(p.executionGeneration)}`;
  }
  if (name === 'COPILOT_ACTION_SELECTED') {
    return `${seqStr} ${dupPrefix}COPILOT_ACTION_SELECTED type=${p.actionType || p.type} att=${formatDiagField(p.attempt)}/${formatDiagField(p.maxAttempts)}`;
  }
  if (name === 'COPILOT_ACTION_COMMITTED') {
    return `${seqStr} ${dupPrefix}COPILOT_ACTION_COMMITTED type=${p.actionType || p.type} apLeft=${formatDiagField(p.apRemaining)} turnActs=${formatDiagField(p.actionsThisHumanTurn)} total=${formatDiagField(p.actionsExecutedCount)}`;
  }
  if (name === 'COPILOT_REPLAN') {
    return `${seqStr} ${dupPrefix}COPILOT_REPLAN reason=${p.reason || 'continue'} ap=${formatDiagField(p.ap)} turnActs=${formatDiagField(p.actionsThisHumanTurn)}`;
  }
  if (name === 'COPILOT_END_TURN_REQUEST') {
    return `${seqStr} ${dupPrefix}COPILOT_END_TURN_REQUEST rsn=${p.reason || 'unknown'} act=${formatDiagField(p.currentActorId)} tc=${formatDiagField(p.turnCounter)} once=${p.alreadyIssued ? 'dup' : 'ok'}`;
  }
  if (name === 'COPILOT_CANCELLED_STALE_EXECUTION') {
    return `${seqStr} ${dupPrefix}COPILOT_CANCELLED_STALE_EXECUTION rsn=${p.reason || 'stale'} gen=${formatDiagField(p.executionGeneration)} tok=${p.sessionToken ? '..' + String(p.sessionToken).slice(-4) : 'none'}`;
  }
  if (name === 'COPILOT_RESUME') {
    return `${seqStr} ${dupPrefix}COPILOT_RESUME act=${formatDiagField(p.currentActorId)} tc=${formatDiagField(p.turnCounter)} days=${formatDiagField(p.currentTurnCount)} w=${p.writer || 'unknown'} tok=${p.sessionToken ? '..' + String(p.sessionToken).slice(-4) : 'none'}`;
  }
  if (name === 'COPILOT_CLAIM') {
    return `${seqStr} ${dupPrefix}COPILOT_CLAIM key=${formatDiagField(p.claimedTurnKey)} epoch=${formatDiagField(p.epoch)} w=${p.writer || 'unknown'} act=${formatDiagField(p.currentActorId)}`;
  }
  if (name === 'COPILOT_CLAIM_RELEASE') {
    return `${seqStr} ${dupPrefix}COPILOT_CLAIM_RELEASE key=${formatDiagField(p.claimedTurnKey)} epoch=${formatDiagField(p.epoch)} w=${p.writer || 'unknown'}`;
  }
  if (name === 'COPILOT_CLAIM_BLOCK_ADVANCE') {
    return `${seqStr} ${dupPrefix}COPILOT_CLAIM_BLOCK_ADVANCE act=${formatDiagField(p.currentActorId)} tc=${formatDiagField(p.turnCounter)} key=${formatDiagField(p.claimedTurnKey)}`;
  }
  if (name === 'COPILOT_CLAIM_RESET_AP') {
    return `${seqStr} ${dupPrefix}COPILOT_CLAIM_RESET_AP prevUsed=${formatDiagField(p.prevUsed)} w=${p.writer || 'unknown'}`;
  }
  if (name === 'COPILOT_NO_LEGAL_ACTION') {
    return `${seqStr} ${dupPrefix}COPILOT_NO_LEGAL_ACTION rsn=${p.reason || 'none'} attempts=${formatDiagField(p.attempts)}`;
  }
  return `${seqStr} ${dupPrefix}${name} ${JSON.stringify(p)}`;
}

export function recordDiag2Event(name: string, payload: Record<string, any>) {
  if (!diag2RuntimeEnabled) return;
  diag2SequenceCounter++;
  diag2TotalEventsRecorded++;
  const seq = diag2SequenceCounter;
  
  // Duplicate check with previous event
  let payloadSig = '';
  try {
    payloadSig = JSON.stringify(payload);
  } catch {
    payloadSig = '[unserializable]';
  }
  const sig = `${name}:${payloadSig}`;
  const isDup = sig === diag2LastEventSig;
  diag2LastEventSig = sig;

  const formatted = formatDiag2CompactLine(seq, name, payload, isDup);
  const rec: Diag2EventRecord = {
    seq,
    timestamp: Date.now(),
    name,
    payload,
    formatted,
    isDup
  };

  DIAG2_EVENT_BUFFER.unshift(rec); // Newest at index 0
  if (DIAG2_EVENT_BUFFER.length > DIAG2_BUFFER_CAPACITY) {
    DIAG2_EVENT_BUFFER.pop(); // Drop oldest
  }

  // Latch overlay only on unexpected GATE1-BLOCK (human turn should have been executable).
  // Rival-turn waits use GATE1-WAIT and must not freeze [GATE1-BLOCKED] for the rest of the match.
  if (name === 'GATE1-BLOCK' && payload?.unexpected !== false && !diag2FirstGate1BlockSnapshot) {
    diag2FirstGate1BlockSnapshot = [...DIAG2_EVENT_BUFFER];
  }

  // Keep console.log alongside
  if (typeof console !== 'undefined' && console.log) {
    console.log(`[DIAG2] ${formatted}`, payload);
  }

  notifyDiag2Listeners();
}

