// Dev Assertion: Extract all mastery keys from CHARACTERS and assert presence in consumer map
if (typeof process !== 'undefined' && process?.env?.NODE_ENV !== 'production') {
  const allMasteryKeys = CHARACTERS.flatMap(c => Object.keys(c.masteryTree || {}));
  console.assert(allMasteryKeys.length === 12, `Expected 12 masteries in CHARACTERS, found ${allMasteryKeys.length}`);
  allMasteryKeys.forEach(key => {
    console.assert(
      Boolean(ACTIVE_MASTERY_CONSUMERS[key]),
      `Dev Assertion Error: Mastery "${key}" is missing from registered active consumer map!`
    );
  });
}

