const GRAND_TOUR_FINAL_CHALLENGE = { name: 'National Champion', difficulty: 4, reward: 4, type: 'finale' };

const ALL_CHALLENGE_DIFFICULTIES: Record<string, number> = (() => {
  const map: Record<string, number> = {};
  Object.values(REGIONS).forEach((region: any) => {
    (region.challenges || []).forEach((c: any) => {
      if (c && c.name && typeof c.difficulty === 'number') {
        map[c.name] = c.difficulty;
      }
    });
  });
  if (GRAND_TOUR_FINAL_CHALLENGE?.name && typeof GRAND_TOUR_FINAL_CHALLENGE.difficulty === 'number') {
    map[GRAND_TOUR_FINAL_CHALLENGE.name] = GRAND_TOUR_FINAL_CHALLENGE.difficulty;
  }
  return map;
})();

