      const soloActor = side === 'player' ? player : aiPlayer;
      const soloProtectedDeduction = vaultExclusionActive ? ((soloActor as ActorState)?.protectedCash || 0) : 0;
      return Math.max(0, (soloActor?.money || 0) - soloProtectedDeduction);
