export interface PendingActionPointRequest {
  requestId: string;
  actorId: string;
  teamId?: string;
  actionId: ActionPointActionId;
  source: string;
  configuredCost: number;
  remainingPoints: number;
  missingPoints: number;
  overrideCost: number;
  day: number;
  turn: number;
  payload: any;
}

export function resolveActionPointActor(actorOrId: any, state: any): any {
  if (!actorOrId) return state?.player;
  if (typeof actorOrId === 'string') {
    if (actorOrId === 'player' || actorOrId === state?.player?.id) return state?.player;
    if (actorOrId === 'ai' || actorOrId === state?.aiPlayer?.id) return state?.aiPlayer;
    if (state?.actors && state.actors[actorOrId]) return state.actors[actorOrId];
    return state?.player;
  }
  return actorOrId;
}

export function getActionPointCost(
  actionId: string | ActionPointActionId,
  arg2?: any,
  arg3?: any
): number {
  let settings: any = arg2;
  let isAi: boolean = Boolean(arg3);

  if (arg2 && typeof arg2 === 'object' && ('actionsUsedThisTurn' in arg2 || 'id' in arg2 || 'kind' in arg2 || 'money' in arg2) && !('actionPointConsumptionSettings' in arg2 || 'actionLimitsEnabled' in arg2)) {
    isAi = Boolean(arg2.isAi || arg2.kind === 'ai');
    settings = arg3;
  }

  if (!settings || settings.actionLimitsEnabled === false) return 0;
  const normId = normalizeActionPointId(actionId);
  if (!normId || normId === 'end_turn') return 0;

  const apSettings: ActionPointConsumptionSettings | undefined = settings.actionPointConsumptionSettings;
  if (!apSettings || !apSettings.actionCosts) {
    return DEFAULT_ACTION_POINT_COSTS[normId] ?? 1;
  }

  if (isAi && apSettings.costScope === 'separate' && apSettings.aiActionCosts) {
    return apSettings.aiActionCosts[normId] ?? DEFAULT_ACTION_POINT_COSTS[normId] ?? 1;
  }
  return apSettings.actionCosts[normId] ?? DEFAULT_ACTION_POINT_COSTS[normId] ?? 1;
}

export function getRemainingActionPoints(
  actor: any,
  settings: any
): number {
  // HUD source of truth is actionsUsedThisTurn / playerActionsPerDay (or AI equivalent).
  // Never cap that with a stale actor.actionPoints remaining pool — that caused live 2/3 stops
  // while the banner still showed an unused action.
  if (settings && settings.actionLimitsEnabled === false) {
    if (typeof actor?.actionPoints === 'number') return Math.max(0, actor.actionPoints);
    return Infinity;
  }
  const isAi = Boolean(actor?.isAi || actor?.kind === 'ai');
  const maxActions = isAi ? (settings?.aiActionsPerDay || 3) : (settings?.playerActionsPerDay || 3);
  const used = Number(actor?.actionsUsedThisTurn) || 0;
  const granted = Number(actor?.overrideActionsGranted) || 0;
  return Math.max(0, (maxActions + granted) - used);
}

const NON_GAMEPLAY_ACTION_POINT_TYPES = new Set([
  'copilot_telemetry_noop',
  'copilot_event',
  'copilot_recommendation_accepted',
  'copilot_takeover_started',
  'copilot_takeover_interrupted',
  'copilot_rescue_triggered',
  'end_turn'
]);

export function applyExecutedGameplayActionPointSpend(
  actor: any,
  actionType: string,
  settings: any,
  usedAtStart: number
): void {
  if (!actor) return;
  if (NON_GAMEPLAY_ACTION_POINT_TYPES.has(String(actionType || ''))) return;
  if (settings && settings.actionLimitsEnabled === false) return;
  const alreadySpent = (Number(actor.actionsUsedThisTurn) || 0) > (Number(usedAtStart) || 0);
  if (alreadySpent) return;
  let cost = typeof getActionPointCost === 'function' ? getActionPointCost(actionType, actor, settings) : 1;
  if (!Number.isFinite(cost) || cost <= 0) cost = 1;
  actor.actionsUsedThisTurn = (Number(usedAtStart) || 0) + cost;
  if (typeof actor.actionPoints === 'number') {
    actor.actionPoints = Math.max(0, actor.actionPoints - cost);
  }
}

export function canActorAffordActionPoints(
  actor: any,
  actionId: string | ActionPointActionId,
  settings: any
): { afford: boolean; cost: number; remaining: number } {
  if (!settings || settings.actionLimitsEnabled === false) return { afford: true, cost: 0, remaining: Infinity };
  const isAi = Boolean(actor?.isAi || actor?.kind === 'ai');
  const cost = getActionPointCost(actionId, settings, isAi);
  const remaining = getRemainingActionPoints(actor, settings);
  if (cost <= 0) return { afford: true, cost: 0, remaining };
  return {
    afford: remaining >= cost,
    cost,
    remaining
  };
}

export function calculateActionPointOverrideCost(actor: any, settings: any, overridesUsedToday: number = 0): number {
  const baseCost = settings?.overrideCost ?? settings?.actionOverrideCost ?? 250;
  const count = overridesUsedToday || actor?.overridesUsedToday || 0;
  const netWorth = actor?.netWorth || actor?.money || 1000;
  const scaleFactor = Math.max(1, Math.floor(netWorth / 50000));
  return Math.round(baseCost * Math.pow(1.5, count) * scaleFactor);
}

export function validateActionPointRequest(
  actor: any,
  actionId: string | ActionPointActionId,
  settings: any
): {
  allowed: boolean;
  actionId: ActionPointActionId | null;
  cost: number;
  remaining: number;
  missing: number;
  canOverride: boolean;
  overrideCost: number;
  reason?: string;
} {
  if (!settings || settings.actionLimitsEnabled === false) {
    return { allowed: true, actionId: normalizeActionPointId(actionId), cost: 0, remaining: Infinity, missing: 0, canOverride: false, overrideCost: 0 };
  }
  const normId = normalizeActionPointId(actionId);
  if (!normId || normId === 'end_turn') {
    // CPFIX1: Make fail-open path observable if unmapped actionId passed
    if (!normId && actionId) {
      console.warn(`[validateActionPointRequest] Unmapped action identifier '${actionId}' passed; fail-open fallback returning cost 0.`);
    }
    return { allowed: true, actionId: normId, cost: 0, remaining: getRemainingActionPoints(actor, settings), missing: 0, canOverride: false, overrideCost: 0, reason: !normId ? `Unmapped action identifier '${actionId}'` : undefined };
  }
  const isAi = Boolean(actor?.isAi || actor?.kind === 'ai');
  const cost = getActionPointCost(normId, settings, isAi);
  const remaining = getRemainingActionPoints(actor, settings);

  if (cost <= 0) {
    return { allowed: true, actionId: normId, cost: 0, remaining, missing: 0, canOverride: false, overrideCost: 0 };
  }

  if (remaining >= cost) {
    return { allowed: true, actionId: normId, cost, remaining, missing: 0, canOverride: false, overrideCost: 0 };
  }

  const missing = cost - remaining;
  const allowOverrideSetting = settings?.allowActionOverride !== false;
  const overridesToday = actor?.overridesUsedToday || 0;
  const maxOverrides = settings?.maxDailyOverrides || 3;
  const canOverride = allowOverrideSetting && overridesToday < maxOverrides;
  const overrideCost = calculateActionPointOverrideCost(actor, settings, overridesToday);

  return {
    allowed: false,
    actionId: normId,
    cost,
    remaining,
    missing,
    canOverride,
    overrideCost,
    reason: canOverride ? 'Action point limit reached. Override available.' : 'Action point limit reached.'
  };
}

export function createPendingActionPointRequest(
  actor: any,
  actionId: ActionPointActionId,
  payload: any,
  settings: any,
  day: number = 1,
  turn: number = 1,
  source: string = 'gameplay'
): PendingActionPointRequest {
  const isAi = Boolean(actor?.isAi || actor?.kind === 'ai');
  const cost = getActionPointCost(actionId, settings, isAi);
  const remaining = getRemainingActionPoints(actor, settings);
  const missing = Math.max(0, cost - remaining);
  const overrideCost = calculateActionPointOverrideCost(actor, settings, actor?.overridesUsedToday || 0);

  return {
    requestId: `ap_req_${Date.now()}_${(queryIdCounter++).toString(36)}`,
    actorId: actor?.id || 'player',
    teamId: actor?.teamId,
    actionId,
    source,
    configuredCost: cost,
    remainingPoints: remaining,
    missingPoints: missing,
    overrideCost,
    day,
    turn,
    payload
  };
}

export function sanitizeActionPointConsumptionSettings(raw: unknown): ActionPointConsumptionSettings {
  const defaults: ActionPointConsumptionSettings = {
    costScope: 'shared',
    actionCosts: { ...DEFAULT_ACTION_POINT_COSTS },
    aiActionCosts: { ...DEFAULT_ACTION_POINT_COSTS },
    activePresetId: 'default'
  };
  if (!raw || typeof raw !== 'object') return defaults;
  const src = raw as Partial<ActionPointConsumptionSettings>;
  const costScope = src.costScope === 'separate' ? 'separate' : 'shared';
  const sanitizeCosts = (mapRaw: unknown): Record<ActionPointActionId, ActionPointCost> => {
    const result = { ...DEFAULT_ACTION_POINT_COSTS };
    if (mapRaw && typeof mapRaw === 'object') {
      for (const [key, val] of Object.entries(mapRaw as Record<string, unknown>)) {
        const normId = normalizeActionPointId(key);
        if (normId && typeof val === 'number' && [0, 1, 2, 3].includes(val)) {
          result[normId] = val as ActionPointCost;
        }
      }
    }
    return result;
  };
  const actionCosts = sanitizeCosts(src.actionCosts);
  const aiActionCosts = sanitizeCosts(src.aiActionCosts);
  const validPresets = ['default', 'free_all', 'standard_all', 'core_only', 'strategic_only', 'custom'];
  const activePresetId = typeof src.activePresetId === 'string' && validPresets.includes(src.activePresetId)
    ? src.activePresetId as ActionPointConsumptionSettings['activePresetId']
    : 'default';

  return {
    costScope,
    actionCosts,
    aiActionCosts,
    activePresetId
  };
}

