export function getExpeditionRunState(gameState: Partial<GameStateSnapshot> | any): ExpeditionRunState {
  if (!gameState) return createDefaultExpeditionRunState();
  const activeDict = gameState.activeExpeditions || {};
  const activeList: ExpeditionLog[] = Array.isArray(activeDict) ? activeDict : Object.values(activeDict);
  const activeRun = activeList.find(e => e && (e.status === 'exploring' || e.status === 'in_transit' || e.status === 'preparing')) || activeList[0] || null;
  return {
    active: Boolean(activeRun),
    mode: activeRun?.mode || 'standalone_solo',
    activeRun,
    history: activeList.filter(e => e && (e.status === 'completed' || e.status === 'aborted' || e.status === 'failed')),
    currentLeg: (activeRun?.currentLeg || 1) as 1 | 2 | 3,
    supplies: activeRun?.supplies ?? 100,
    hazardRisk: activeRun?.hazardRisk ?? 0,
    condition: activeRun?.condition || 'healthy',
    pendingBeat: activeRun?.pendingBeat || null,
  };
}

export interface ExpeditionRunState {
  active: boolean;
  mode: ExpeditionModeId;
  activeRun: ExpeditionLog | null;
  history: ExpeditionLog[];
  currentLeg: 1 | 2 | 3;
  supplies: number;
  hazardRisk: number;
  condition: 'healthy' | 'strained' | 'critical';
  pendingBeat: ExpeditionBeat | null;
}

export function createDefaultExpeditionRunState(): ExpeditionRunState {
  return {
    active: false,
    mode: 'standalone_solo',
    activeRun: null,
    history: [],
    currentLeg: 1,
    supplies: 100,
    hazardRisk: 0,
    condition: 'healthy',
    pendingBeat: null,
  };
}

export function sanitizeExpeditionRunState(data: any): ExpeditionRunState {
  if (!data || typeof data !== 'object') {
    return createDefaultExpeditionRunState();
  }
  const mode: ExpeditionModeId = ['standalone_solo', 'standalone_rival', 'mid_match_solo', 'mid_match_rival'].includes(data.mode)
    ? data.mode
    : 'standalone_solo';
  const condition: 'healthy' | 'strained' | 'critical' = ['healthy', 'strained', 'critical'].includes(data.condition)
    ? data.condition
    : 'healthy';
  const currentLeg: 1 | 2 | 3 = (data.currentLeg === 1 || data.currentLeg === 2 || data.currentLeg === 3)
    ? data.currentLeg
    : 1;

  return {
    active: Boolean(data.active),
    mode,
    activeRun: (data.activeRun && typeof data.activeRun === 'object') ? data.activeRun : null,
    history: Array.isArray(data.history) ? data.history : [],
    currentLeg,
    supplies: typeof data.supplies === 'number' && !isNaN(data.supplies) ? data.supplies : 100,
    hazardRisk: typeof data.hazardRisk === 'number' && !isNaN(data.hazardRisk) ? data.hazardRisk : 0,
    condition,
    pendingBeat: (data.pendingBeat && typeof data.pendingBeat === 'object') ? data.pendingBeat : null,
  };
}

export function recordExpeditionForkBranch(
  state: CanonicalGameState,
  expeditionId: string,
  beatId: string,
  choiceId: string,
  label: string
): void {
  if (!state.replayBranchTree) {
    state.replayBranchTree = {
      treeId: 'tree_main',
      matchId: state.match?.matchId || 'match_main',
      rootNodeId: 'root',
      activeNodeId: 'root',
      nodesById: {
        root: {
          nodeId: 'root',
          parentNodeId: null,
          branchTurn: 1,
          branchDay: 1,
          branchSequence: 0,
          label: 'Main Timeline',
          triggerReason: 'expedition_fork',
          stateSnapshot: JSON.parse(JSON.stringify(state)),
          actionsTaken: [],
          childNodeIds: [],
          createdAtTimestamp: Date.now(),
          rngRegistryState: globalRngRegistry.exportStreamStates(),
          deterministicCounters: { ...globalDeterministicCounters }
        }
      },
      createdTimestamp: Date.now()
    };
  } else if (!state.replayBranchTree.nodesById['root']) {
    state.replayBranchTree.nodesById['root'] = {
      nodeId: 'root',
      parentNodeId: null,
      branchTurn: 1,
      branchDay: 1,
      branchSequence: 0,
      label: 'Main Timeline',
      triggerReason: 'expedition_fork',
      stateSnapshot: JSON.parse(JSON.stringify(state)),
      actionsTaken: [],
      childNodeIds: [],
      createdAtTimestamp: Date.now(),
      rngRegistryState: globalRngRegistry.exportStreamStates(),
      deterministicCounters: { ...globalDeterministicCounters }
    };
  }
  const parentId = state.replayBranchTree.activeNodeId || 'root';
  const newBranchId = `fork_${expeditionId}_${beatId}_${nextBranchId(globalDeterministicCounters, 'fork')}`;
  state.replayBranchTree.nodesById[newBranchId] = {
    nodeId: newBranchId,
    parentNodeId: parentId,
    branchTurn: state.turn || 1,
    branchDay: state.day || 1,
    branchSequence: state.replay?.actions?.length || 0,
    label: `Expedition Fork: ${label}`,
    triggerReason: 'expedition_fork',
    stateSnapshot: JSON.parse(JSON.stringify(state)),
    actionsTaken: [],
    childNodeIds: [],
    createdAtTimestamp: Date.now(),
    rngRegistryState: globalRngRegistry.exportStreamStates(),
    deterministicCounters: { ...globalDeterministicCounters }
  };
  if (state.replayBranchTree.nodesById[parentId]) {
    state.replayBranchTree.nodesById[parentId].childNodeIds.push(newBranchId);
  }
  state.replayBranchTree.activeNodeId = newBranchId;
}

export function checkExpeditionBeatChoiceRequirements(
  state: CanonicalGameState,
  actorId: string,
  expId: string,
  choice: ExpeditionBeatChoice
): RequirementCheckResult {
  const unmetReasons: string[] = [];
  const actor = state.actorsById?.[actorId] || (actorId === 'player' ? state.player : state.aiPlayer);
  const exp = state.activeExpeditions?.[expId];
  const target = exp ? state.expeditionTargets?.[exp.expeditionTargetId] : null;

  if (!actor) {
    return { satisfied: false, unmetReasons: ['Actor not found'] };
  }

  if (choice.requirements && Array.isArray(choice.requirements)) {
    for (const req of choice.requirements) {
      switch (req.type) {
        case 'min_cash':
          if ((actor.money ?? 0) < Number(req.value)) {
            unmetReasons.push(`Requires at least $${req.value} (current: $${actor.money ?? 0}).`);
          }
          break;
        case 'min_supplies':
          if ((actor.currentSupplies ?? 100) < Number(req.value)) {
            unmetReasons.push(`Requires at least ${req.value} supplies (current: ${actor.currentSupplies ?? 100}).`);
          }
          break;
        case 'required_equipment': {
          const reqEq = String(req.targetKey || req.value);
          const hasEquip = actor.equipment && actor.equipment.includes(reqEq);
          if (!hasEquip) {
            unmetReasons.push(`Missing required equipment: ${reqEq}.`);
          }
          break;
        }
        case 'required_relic': {
          const relicId = String(req.targetKey || req.value);
          const hasRelic = (exp?.collectedRelics || []).some(r => r.id === relicId) ||
            (state.relicInventoryByActor?.[actorId] || []).some(r => r.id === relicId);
          if (!hasRelic) {
            unmetReasons.push(`Missing required relic: ${relicId}.`);
          }
          break;
        }
        case 'min_standing': {
          const territoryId = req.targetKey || target?.externalTerritoryId || 'AAT';
          const standing = state.standingPerActor?.[actorId]?.[territoryId] ?? 0;
          if (standing < Number(req.value)) {
            unmetReasons.push(`Requires standing of ${req.value} in ${territoryId} (current: ${standing}).`);
          }
          break;
        }
        case 'has_flag': {
          const flagName = String(req.targetKey || req.value);
          const hasFlag = Boolean(exp?.narrativeFlags?.[flagName]);
          if (!hasFlag) {
            unmetReasons.push(`Prerequisite narrative flag missing: ${flagName}.`);
          }
          break;
        }
        case 'actor_condition': {
          const requiredCond = String(req.value);
          if ((actor.condition ?? 'healthy') !== requiredCond) {
            unmetReasons.push(`Condition '${actor.condition}' does not match required '${requiredCond}'.`);
          }
          break;
        }
        case 'required_risk': {
          const reqRisk = String(req.value) as ExpeditionRiskChoice;
          if (exp && exp.riskChoice !== reqRisk) {
            unmetReasons.push(`Requires risk profile ${reqRisk} (current: ${exp.riskChoice}).`);
          }
          break;
        }
      }
    }
  }

  return {
    satisfied: unmetReasons.length === 0,
    unmetReasons
  };
}

export function canSelectExpeditionChoice(
  choice: ExpeditionBeatChoice,
  actor: ActorState,
  exp: ExpeditionLog,
  gameState: CanonicalGameState
): { allowed: boolean; reason?: string } {
  const result = checkExpeditionBeatChoiceRequirements(gameState, actor.id || 'player', exp.id, choice);
  return {
    allowed: result.satisfied,
    reason: result.unmetReasons.join(' ')
  };
}

export function checkExpeditionBeatTrigger(
  exp: ExpeditionLog,
  campaign: ExpeditionCampaign | undefined,
  triggerType: ExpeditionBeatTriggerType,
  turnInLeg: number,
  hazardRating: number = 0
): ExpeditionBeat | null {
  if (!campaign || !campaign.legs) return null;
  const currentLegIndex = (exp.currentLeg || 1) - 1;
  const leg = campaign.legs[currentLegIndex];
  if (!leg || !leg.beats) return null;

  const completed = new Set(exp.completedBeatIds || []);

  for (const beat of leg.beats) {
    if (beat.triggerType !== triggerType) continue;
    if (completed.has(beat.id)) continue;

    const cond = beat.triggerCondition;
    if (cond) {
      if (cond.turnNumber !== undefined && turnInLeg !== cond.turnNumber) continue;
      if (cond.hazardRatingMin !== undefined && hazardRating < cond.hazardRatingMin) continue;
      if (cond.requiredFlag && (!exp.narrativeFlags || !exp.narrativeFlags[cond.requiredFlag])) continue;
    }

    return beat;
  }

  return null;
}

