// PRESETS CATALOG: 8 SCENARIO PRESETS, 5 CAMPAIGN CHAPTERS, 4 CRISIS CHAINS

export function convertCustomScenarioToGameScenario(custom: CustomScenarioConfig): ScenarioDefinition {
  const forcedSettings = {
    ...(custom.customSettings || {}),
    ...(custom.forcedSettings || {})
  };
  return {
    id: custom.id,
    title: custom.title || 'Custom Scenario',
    description: custom.description || 'User-created custom scenario.',
    category: 'custom',
    difficulty: custom.difficulty || 'Medium',
    forcedSeed: custom.forcedSeed,
    startingMoney: custom.startingMoney ?? 10000,
    startingRegions: custom.startingRegions || ['new_south_wales'],
    startingItems: custom.startingItems || [],
    startingLoans: custom.startingLoans || [],
    startingStanding: custom.startingStanding || {},
    forcedSettings: forcedSettings,
    objectives: custom.objectives || [],
    modifiers: custom.modifiers || [],
    narrativeIntro: (custom as FlexibleScenarioConfig).narrativeIntro || `Custom scenario: ${custom.title || 'Custom Scenario'}`,
    narrativeOutro: (custom as FlexibleScenarioConfig).narrativeOutro || 'Custom scenario completed.',
    badgeId: (custom as FlexibleScenarioConfig).badgeId || 'custom_badge',
    unlockedByDefault: true,
  };
}

export function getUnifiedPlayableScenarios(savedScenarios?: CustomScenarioConfig[]): ScenarioDefinition[] {
  const customConverted = (savedScenarios || []).map(convertCustomScenarioToGameScenario);
  return [...PRESET_GAME_SCENARIOS, ...customConverted];
}

export function findActiveScenario(selectedScenarioId?: string, savedScenarios?: CustomScenarioConfig[]): ScenarioDefinition {
  const unified = getUnifiedPlayableScenarios(savedScenarios);
  return unified.find(s => s.id === selectedScenarioId) || unified[0];
}

