export function evaluateScenarioObjective(
  objective: ScenarioObjective,
  context: {
    player: any;
    aiPlayer: any;
    gameState: GameStateSnapshot;
    gameSettings: GameSettingsState;
    teamsById?: Record<string, any>;
  }
): ScenarioObjectiveProgress {
  let currentValue = 0;
  const isPrimary = objective.isPrimary ?? true;
  const { player, aiPlayer, gameState, gameSettings } = context;

  switch (objective.targetType) {
    case 'money':
    case 'money_accumulated':
      currentValue = player?.money || 0;
      break;

    case 'regions':
    case 'regions_controlled': {
      const soloStats = computeRegionControlStats(
        sanitizeRegionDeposits(gameState.regionDeposits),
        gameState.regionControlStats?.controlHistory || []
      );
      currentValue = soloStats.totalControlled?.[player?.id || 'player'] || 0;
      break;
    }

    case 'netWorth':
      currentValue = calculateNetWorth(player, gameState.resourcePrices);
      break;

    case 'daysPassed':
    case 'turns_survived':
      currentValue = gameState.day || 1;
      break;

    case 'standing_reached':
    case 'regionalStanding': {
      const standingData = player?.regionalStanding || {};
      const standingValues = Object.values(standingData) as number[];
      currentValue = standingValues.length > 0 ? Math.max(...standingValues) : 0;
      break;
    }

    case 'ai_eliminated': {
      const aiMoney = aiPlayer?.money || 0;
      const aiBroke = aiMoney < BANKRUPTCY_THRESHOLD;
      const aiStreak = gameState.bankruptcyTracker?.ai || 0;
      const isEliminated = aiBroke && aiStreak >= BANKRUPTCY_STREAK_DAYS;
      currentValue = isEliminated ? 1 : 0;
      break;
    }

    case 'challenges':
    case 'challenges_completed': {
      const masteryCount = Object.keys(player?.challengeMastery || {}).length;
      const completedListCount = Array.isArray(player?.challengesCompleted) ? player.challengesCompleted.length : 0;
      currentValue = Math.max(masteryCount, completedListCount);
      break;
    }

    case 'public_stability':
      currentValue = gameState.publicStabilityState?.nationalStability || 100;
      break;

    case 'crisis_resolved':
      currentValue = (gameState.crisisChainState?.activeCrisisChains || []).filter(c => c.status === 'resolved').length;
      break;

    case 'territory_controlled':
      currentValue = (player?.visitedRegions || []).filter((r: string) => ['EXTERNAL_NORFOLK', 'EXTERNAL_CHRISTMAS', 'EXTERNAL_LORD_HOWE', 'EXTERNAL_MACQUARIE'].includes(r)).length;
      break;

    case 'debt_cleared':
      currentValue = (player?.loans || []).length === 0 ? 1 : 0;
      break;

    case 'investments_count':
      currentValue = (player?.investments || []).length;
      break;

    case 'standing_threshold': {
      const standingData = player?.regionalStanding || {};
      const maxStanding = Math.max(0, ...(Object.values(standingData) as number[]));
      currentValue = maxStanding;
      break;
    }

    case 'specific_region_controlled': {
      const targetReg = objective.targetRegionId || 'QLD';
      const regStats = computeRegionControlStats(
        sanitizeRegionDeposits(gameState.regionDeposits),
        gameState.regionControlStats?.controlHistory || []
      );
      currentValue = (regStats.totalControlled?.[player?.id || 'player'] || 0) > 0 && player?.currentRegion === targetReg ? 1 : 0;
      break;
    }

    case 'zero_sabotage_taken':
      currentValue = (player?.sabotageTargetedCount || 0) === 0 ? 1 : 0;
      break;

    case 'governance_proposals_passed':
      currentValue = (gameState.proposals || []).filter((p: any) => p.status === 'passed').length;
      break;

    case 'multi_actor_standing_avg': {
      const standingData = player?.regionalStanding || {};
      const vals = Object.values(standingData) as number[];
      currentValue = vals.length > 0 ? vals.reduce((a, b) => a + b, 0) / vals.length : 0;
      break;
    }

    default:
      currentValue = 0;
      break;
  }

  const completed = currentValue >= objective.targetValue;
  return {
    objectiveId: objective.id,
    label: objective.label,
    description: objective.description,
    targetType: objective.targetType,
    currentValue,
    targetValue: objective.targetValue,
    completed,
    isPrimary
  };
}

export function evaluateScenarioOutcome(
  scenario: GameScenario,
  context: {
    player: any;
    aiPlayer: any;
    gameState: GameStateSnapshot;
    gameSettings: GameSettingsState;
    teamsById?: Record<string, any>;
  }
): ScenarioOutcome {
  const objectivesProgress: Record<string, ScenarioObjectiveProgress> = {};
  let primaryCount = 0;
  let primaryCompletedCount = 0;
  let totalCompletedCount = 0;

  for (const obj of scenario.objectives) {
    const prog = evaluateScenarioObjective(obj, context);
    objectivesProgress[obj.id] = prog;
    const isPrimary = obj.isPrimary ?? true;
    if (isPrimary) {
      primaryCount++;
      if (prog.completed) primaryCompletedCount++;
    }
    if (prog.completed) totalCompletedCount++;
  }

  const allPrimaryCompleted = primaryCount > 0 && primaryCompletedCount === primaryCount;
  const allOptionalCompleted = totalCompletedCount === scenario.objectives.length;

  const playerBroke = (context.player?.money ?? 0) < BANKRUPTCY_THRESHOLD;
  const playerBankrupt = playerBroke && (context.gameState.bankruptcyTracker?.player || 0) >= BANKRUPTCY_STREAK_DAYS;
  const maxDaysReached = context.gameState.day >= context.gameSettings.totalDays;

  let isGameOver = false;
  let isVictory = false;
  let isDefeat = false;
  let reason = '';

  if (allPrimaryCompleted) {
    isGameOver = true;
    isVictory = true;
    reason = `Scenario Victory! All primary objectives completed on Day ${context.gameState.day}.`;
  } else if (playerBankrupt) {
    isGameOver = true;
    isDefeat = true;
    reason = `Scenario Failed: Player went bankrupt on Day ${context.gameState.day}.`;
  } else if (maxDaysReached) {
    isGameOver = true;
    isDefeat = true;
    reason = `Scenario Failed: Reached day limit (${context.gameSettings.totalDays} days) before completing all primary objectives.`;
  }

  return {
    isGameOver,
    isVictory,
    isDefeat,
    reason,
    objectivesProgress,
    allPrimaryCompleted,
    allOptionalCompleted,
    completedOnDay: context.gameState.day
  };
}
