  aiStrategicLearningStrength: { key: 'aiStrategicLearningStrength', tab: 'aiTeams', label: 'Strategic Learning Strength', description: 'How strongly learned opponent models can adjust AI scores. Learning never overrides legality, survival, or current team orders.', tags: ['AI', 'Advanced'] },
