export function resetStartScreenProtectionSettings(settings?: GameSettingsState): GameSettingsState {
  const base = settings || DEFAULT_GAME_SETTINGS;
  return {
    ...base,
    startScreenConflictProtection: true,
    showFloatingControlsOnStartScreen: false,
    startScreenFloatingLayout: 'hidden',
    restoreEligibleFloatingControlsAfterMatchStarts: true,
    hideGameplaySidePanelsOnStartScreen: true,
  };
}

export function evaluateStartScreenFloatingControlsVisibility(
  gameState: { gameMode?: string } | any,
  uiState: { showCampaignSelect?: boolean } | any,
  gameSettings: GameSettingsState
): { isStartScreenActive: boolean; shouldShowFloatingControls: boolean; isDockedSafeArea: boolean } {
  const isStartScreenActive = gameState?.gameMode === 'menu' || gameState?.gameMode === 'start_screen' || Boolean(uiState?.showCampaignSelect) || Boolean(uiState?.showStartScreen) || gameState?.gameStarted === false;
  const startScreenConflictProtection = gameSettings.startScreenConflictProtection ?? true;
  const showFloatingControlsOnStartScreen = gameSettings.showFloatingControlsOnStartScreen ?? false;
  const startScreenFloatingLayout = gameSettings.startScreenFloatingLayout ?? 'hidden';
  const restoreEligibleFloatingControlsAfterMatchStarts = gameSettings.restoreEligibleFloatingControlsAfterMatchStarts ?? true;

  const shouldShowFloatingControls = isStartScreenActive
    ? (startScreenConflictProtection
        ? (showFloatingControlsOnStartScreen && startScreenFloatingLayout !== 'hidden')
        : true)
    : (restoreEligibleFloatingControlsAfterMatchStarts
        ? true
        : (showFloatingControlsOnStartScreen && startScreenFloatingLayout !== 'hidden'));

  const isDockedSafeArea = isStartScreenActive && startScreenConflictProtection && showFloatingControlsOnStartScreen && startScreenFloatingLayout === 'docked_safe_area';

  return { isStartScreenActive, shouldShowFloatingControls, isDockedSafeArea };
}


export class GameplayRngRegistry {
  public activeRngScope: RngScopeDomain | null = null;
  public scopeStack: RngScopeDomain[] = [];
  public masterSeed: number = 1337;
  public isDeterministic: boolean = true;
  public strictAuditMode: boolean = true;
  public auditPolicy: RngAuditPolicy = 'strict';
  public isReplayCertified: boolean = true;
  public streams: Record<RngScopeDomain, RngStreamState>;
  public incidentLog: UnscopedRngIncident[] = [];
  private ledgerDispatcher?: (event: any) => void;
  private auditorDispatcher?: (event: any) => void;

  constructor(initialMasterSeed: number = 1337) {
    this.masterSeed = initialMasterSeed;
    this.streams = {} as Record<RngScopeDomain, RngStreamState>;
    this.initStreams(initialMasterSeed);
  }

  public initStreams(masterSeed: number) {
    this.masterSeed = masterSeed;
    for (const domain of RNG_STREAM_NAMES) {
      const streamSeed = deriveDomainSeed(masterSeed, domain);
      this.streams[domain] = {
        domain,
        streamSeed,
        drawCount: 0,
        rollingHash: 0,
        currentState: streamSeed,
        xoshiroState: [
          streamSeed,
          (streamSeed ^ 0x9E3779B9) >>> 0,
          Math.imul(streamSeed, 31) >>> 0,
          Math.imul(streamSeed, 17) >>> 0
        ]
      };
    }
  }

  public setAuditPolicy(policy: RngAuditPolicy) {
    this.auditPolicy = policy;
    this.strictAuditMode = (policy === 'strict');
  }

  public markReplayUncertified(reason?: string) {
    this.isReplayCertified = false;
  }

  public exportStreamStates(): Record<string, RngStreamState> {
    const exported: Record<string, RngStreamState> = {};
    for (const domain of RNG_STREAM_NAMES) {
      const s = this.streams[domain];
      if (s) {
        const item: RngStreamState = {
          domain: s.domain,
          streamSeed: s.streamSeed,
          drawCount: s.drawCount,
          rollingHash: s.rollingHash,
          currentState: s.currentState,
          state: s.currentState,
          xoshiroState: s.xoshiroState ? [...s.xoshiroState] as [number, number, number, number] : undefined
        };
        exported[domain] = item;
        exported[domain.toLowerCase()] = item;
      }
    }
    if (exported['world']) {
      exported['map'] = exported['world'];
      exported['player'] = exported['world'];
    }
    if (exported['aireasoning']) {
      exported['ai'] = exported['aireasoning'];
    }
    if (exported['randomevents']) {
      exported['event'] = exported['randomevents'];
    }
    return exported;
  }

  public importStreamStates(saved: Record<string, RngStreamState>) {
    if (!saved || typeof saved !== 'object') return;
    for (const domain of RNG_STREAM_NAMES) {
      let src = saved[domain] || saved[domain.toLowerCase()];
      if (!src) {
        if (domain === 'World') src = saved['map'] || saved['player'];
        else if (domain === 'AIReasoning') src = saved['ai'];
        else if (domain === 'RandomEvents') src = saved['event'];
      }
      if (src) {
        const st = (src.currentState !== undefined) ? src.currentState : (src.state !== undefined ? src.state : src.streamSeed);
        this.streams[domain] = {
          domain,
          streamSeed: src.streamSeed,
          drawCount: src.drawCount,
          rollingHash: src.rollingHash,
          currentState: st,
          state: st,
          xoshiroState: src.xoshiroState ? [...src.xoshiroState] as [number, number, number, number] : undefined
        };
      }
    }
  }

  public reseedMaster(seed: number) {
    this.initStreams(seed);
  }

  public serializeState(): Record<string, RngStreamState> {
    return this.exportStreamStates();
  }

  public deserializeState(saved: Record<string, RngStreamState>) {
    this.importStreamStates(saved);
  }

  public registerDispatchers(ledger?: (event: any) => void, auditor?: (event: any) => void) {
    this.ledgerDispatcher = ledger;
    this.auditorDispatcher = auditor;
  }

  public draw(domain?: RngScopeDomain): number {
    const currentScope = this.activeRngScope;
    const requestedDomain = currentScope || domain;

    if (this.activeRngScope === null && !domain) {
      this.markReplayUncertified('Unscoped RNG draw attempted without activeRngScope or explicit domain.');
      this.logUnscopedIncident(domain);
      if (this.auditPolicy === 'strict' || this.strictAuditMode) {
        throw new Error(`Critical RNG Audit Error: RNG draw attempted with no domain specified and activeRngScope is null! Fallback to World is strictly prohibited in strict mode.`);
      }
    }

    if (!requestedDomain) {
      this.markReplayUncertified('RNG draw attempted with undefined stream domain.');
      this.logUnscopedIncident(undefined);
      throw new Error(`Critical RNG Error: RNG draw attempted with no domain specified or active RNG scope! Fallback to World is strictly prohibited.`);
    }

    let targetDomain: RngScopeDomain | undefined = requestedDomain;
    if (!this.streams[targetDomain]) {
      const lower = String(requestedDomain).toLowerCase();
      const match = RNG_STREAM_NAMES.find(s => s.toLowerCase() === lower);
      if (match) {
        targetDomain = match;
      } else if (lower === 'ai') {
        targetDomain = 'AIReasoning';
      } else if (lower === 'event' || lower === 'events') {
        targetDomain = 'RandomEvents';
      } else if (lower === 'map' || lower === 'player' || lower === 'auditor' || lower === 'general') {
        targetDomain = 'World';
      }
    }

    if (!targetDomain || !this.streams[targetDomain]) {
      this.markReplayUncertified(`Requested RNG stream '${requestedDomain}' is not initialized.`);
      this.logUnscopedIncident(requestedDomain);
      throw new Error(`Critical RNG Error: Requested stream '${requestedDomain}' is invalid or not initialized! Fallback to World is strictly prohibited.`);
    }

    const stream = this.streams[targetDomain];
    let val: number;

    if (!this.isDeterministic) {
      val = NATIVE_MATH_RANDOM();
    } else {
      const stepM32 = mulberry32Next(stream.currentState);
      stream.currentState = stepM32.nextState;

      if (!stream.xoshiroState) {
        stream.xoshiroState = [
          stream.streamSeed,
          (stream.streamSeed ^ 0x9E3779B9) >>> 0,
          Math.imul(stream.streamSeed, 31) >>> 0,
          Math.imul(stream.streamSeed, 17) >>> 0
        ];
      }
      const stepX256 = xoshiro256starstarNext(stream.xoshiroState);
      stream.xoshiroState = stepX256.nextState;

      val = (stepM32.value + stepX256.value) % 1.0;
    }

    stream.drawCount++;
    stream.rollingHash = (Math.imul(stream.rollingHash, 31) + Math.floor(val * 0xFFFFFFFF)) >>> 0;
    return val;
  }

  public logUnscopedIncident(requestedDomain?: RngScopeDomain) {
    this.markReplayUncertified('Unscoped RNG Incident logged.');
    const incidentId = nextDecisionId(globalDeterministicCounters, 'rng_incident');
    const incident: UnscopedRngIncident = {
      id: incidentId,
      timestamp: Date.now(),
      requestedDomain,
      activeScope: this.activeRngScope,
      stack: new Error().stack
    };
    this.incidentLog.push(incident);
    if (this.incidentLog.length > 100) this.incidentLog.shift();

    console.warn(`[RNG Scope Guard Critical Incident] Gameplay random draw attempted while activeRngScope is null! Requested domain: ${requestedDomain || 'none'}.`);

    const rootEvent = incidentId;
    const parentEvent = incidentId;
    const correlationChain = [incidentId];
    const correlationChainId = incidentId;

    if (this.ledgerDispatcher) {
      this.ledgerDispatcher({
        type: 'rng_unscoped_draw_incident',
        id: incidentId,
        timestamp: incident.timestamp,
        requestedDomain,
        activeScope: null,
        message: 'Un-scoped RNG draw attempt detected (activeRngScope was null).',
        rootEvent,
        parentEvent,
        correlationChain,
        correlationChainId
      });
    }

    if (this.auditorDispatcher) {
      this.auditorDispatcher({
        type: 'RNG_UNSCOPED_DRAW_ALERT',
        id: incidentId,
        timestamp: incident.timestamp,
        requestedDomain,
        activeScope: null,
        rootEvent,
        parentEvent,
        correlationChain,
        correlationChainId
      });
    }
  }

  public withScope<T>(domain: RngScopeDomain, callback: () => T): T {
    const previousScope = this.activeRngScope;
    this.scopeStack.push(domain);
    this.activeRngScope = domain;

    try {
      const result = callback();
      if (
        result !== null &&
        typeof result === 'object' &&
        typeof (result as unknown as PromiseLike<unknown>).then === 'function'
      ) {
        throw new Error('Deterministic RNG scopes must be synchronous.');
      }
      return result;
    } finally {
      this.scopeStack.pop();
      this.activeRngScope = this.scopeStack.length > 0 ? this.scopeStack[this.scopeStack.length - 1] : previousScope;
    }
  }

  public getAuditSnapshot(): RngAuditSnapshot {
    const streamsSnapshot: Record<string, { streamSeed: number; drawCount: number; rollingHash: number; currentState: number }> = {};
    let totalDraws = 0;
    for (const domainKey in this.streams) {
      const s = this.streams[domainKey as RngScopeDomain];
      if (s) {
        streamsSnapshot[domainKey] = {
          streamSeed: s.streamSeed,
          drawCount: s.drawCount,
          rollingHash: s.rollingHash,
          currentState: s.currentState
        };
        totalDraws += s.drawCount;
      }
    }
    return {
      activeScope: this.activeRngScope,
      totalDrawCount: totalDraws,
      streams: streamsSnapshot
    };
  }

  public drawString(domain?: RngScopeDomain, length: number = 6): string {
    let str = '';
    while (str.length < length) {
      const floatVal = this.draw(domain);
      const piece = floatVal.toString(36).slice(2);
      str += piece;
    }
    return str.slice(0, length);
  }
}

export const globalRngRegistry = new GameplayRngRegistry(1337);

// Add Gameplay Execution Context
interface GameplayExecutionContext {
  active?: boolean;
  operation?: string;
  actionAttemptId?: string;
  actorId?: string;
  teamId?: string;
  day?: number;
  turn?: number;
}

class GameplayContextManager {
  private currentContext: GameplayExecutionContext = { active: false };

  public getContext(): GameplayExecutionContext {
    return { ...this.currentContext };
  }

  public runWithContext<T>(ctx: GameplayExecutionContext | undefined, callback: () => T): T {
    const prev = this.currentContext;
    this.currentContext = { ...(ctx || {}), active: true };
    try {
      return callback();
    } finally {
      this.currentContext = prev;
    }
  }
}

const gameplayContextManager = new GameplayContextManager();

function withGameplayExecutionContext<T>(ctx: GameplayExecutionContext | undefined, callback: () => T): T {
  return gameplayContextManager.runWithContext(ctx, callback);
}

const NATIVE_MATH_RANDOM = Math.random.bind(Math);

function cosmeticRandom(): number {
  return NATIVE_MATH_RANDOM();
}

export class RngAuditError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'RngAuditError';
  }
}

function isCosmeticHostRandom(): boolean {
  try {
    const stack = new Error().stack || '';
    return /cdn\.tailwindcss\.com|tailwindcss|__vite_client|vite\/client/i.test(stack);
  } catch {
    return false;
  }
}

class GameplayRandomRouter {
  public random(): number {
    if (isCosmeticHostRandom()) {
      return NATIVE_MATH_RANDOM();
    }
    const scope = globalRngRegistry.activeRngScope;
    const context = gameplayContextManager.getContext();

    if (scope) {
      return globalRngRegistry.draw(scope);
    }
    if (context.active) {
      globalRngRegistry.markReplayUncertified('Unscoped random draw attempted during active gameplay context.');
      globalRngRegistry.logUnscopedIncident(undefined);
      throw new RngAuditError('Critical RNG Audit Error: Unscoped random draw detected inside active gameplay execution context! Wrap in withRngScope() or call drawGameplayRandom(domain).');
    }
    if (globalRngRegistry.auditPolicy === 'strict' || globalRngRegistry.strictAuditMode) {
      globalRngRegistry.markReplayUncertified('Unscoped random draw attempted in strict audit mode outside active context.');
      globalRngRegistry.logUnscopedIncident(undefined);
      throw new RngAuditError('Critical RNG Audit Error: Native Math.random() or unscoped draw attempted in strict mode!');
    }
    return NATIVE_MATH_RANDOM();
  }
}

const gameplayRandomRouter = new GameplayRandomRouter();

if (typeof window !== 'undefined' || typeof globalThis !== 'undefined') {
  const g = typeof window !== 'undefined' ? (window as unknown as Record<string, any>) : (globalThis as unknown as Record<string, any>);
  g.Math.random = () => {
    return gameplayRandomRouter.random();
  };
}

function drawGameplayRandomChoice<T>(domain: RngScopeDomain, array: readonly T[]): T {
  if (!array || array.length === 0) return (array ? array[0] : undefined) as T;
  const index = Math.floor(globalRngRegistry.draw(domain) * array.length);
  return array[Math.min(index, array.length - 1)];
}

export type RandomnessMode = 'deterministic' | 'hybrid' | 'legacy_random' | 'recorded_chaos';

export interface RecordedRandomDraw {
  timestamp: number;
  step: number;
  scope: string;
  seed?: number | string;
  state?: unknown;
  value: number;
  stream?: string;
  context?: string;
  id?: string;
  mode?: string;
  system?: string;
  actorId?: string;
  teamId?: string;
  day?: number;
  turn?: number;
  seq?: number;
  source?: string;
}

const pendingReplayRandomDraws: RecordedRandomDraw[] = [];
const pendingReplayDirectorEvents: Array<{ category: ReplayEventCategory; summary: string; payload: Record<string, unknown> }> = [];

function flushPendingReplaySideChannels(
  recording: ReplayFile,
  day: number,
  turn: number,
  maxEvents: number,
  detailLevel?: string
): void {
  if (pendingReplayRandomDraws.length > 0) {
    const draws = pendingReplayRandomDraws.splice(0, pendingReplayRandomDraws.length);
    recording.randomDraws = [...(recording.randomDraws || []), ...draws];
    const emitDrawEvents = (detailLevel || 'standard') !== 'standard' || draws.some(d => d.mode === 'recorded_chaos' || d.mode === 'hybrid');
    if (emitDrawEvents) {
      draws.forEach((draw, i) => {
        if (recording.events.length >= maxEvents) return;
        const seq = (recording.events[recording.events.length - 1]?.sequence ?? -1) + 1;
        recording.events.push({
          id: `rngdraw_${seq}_${i}`,
          sequence: seq,
          category: 'rng_draw',
          day: draw.day ?? day,
          turn: draw.turn ?? turn,
          actorId: draw.actorId || null,
          teamId: draw.teamId || null,
          summary: `RNG ${draw.stream || draw.scope} = ${draw.value}`,
          payload: { ...draw },
          timestamp: draw.timestamp || Date.now()
        });
      });
    }
  }
  if (pendingReplayDirectorEvents.length > 0) {
    const queued = pendingReplayDirectorEvents.splice(0, pendingReplayDirectorEvents.length);
    queued.forEach((item, i) => {
      if (recording.events.length >= maxEvents) return;
      const seq = (recording.events[recording.events.length - 1]?.sequence ?? -1) + 1;
      recording.events.push({
        id: `director_${seq}_${i}`,
        sequence: seq,
        category: item.category,
        day,
        turn,
        actorId: typeof item.payload.targetActorId === 'string' ? item.payload.targetActorId : null,
        summary: item.summary,
        payload: item.payload,
        timestamp: Date.now()
      });
    });
  }
}

export interface DrawGameRandomOptions {
  domain?: RngScopeDomain;
  mode?: RandomnessMode;
  recordedQueue?: number[];
  recordedValues?: number[];
  fallbackToLegacy?: boolean;
}

export function drawGameplayRandom(domain?: RngScopeDomain): number {
  return globalRngRegistry.draw(domain);
}

export function drawGameRandom(
  domainOrOptionsOrState?: RngScopeDomain | DrawGameRandomOptions | GameState | ExtendedGameState | any,
  modeOrScope?: RandomnessMode | string,
  recordedValuesOrMode?: number[] | RandomnessMode,
  recordedValues?: number[]
): number {
  let domain: RngScopeDomain | undefined = undefined;
  let selectedMode: RandomnessMode = 'deterministic';
  let queue: number[] | undefined = undefined;
  let gameStateRef: ExtendedGameState | undefined = undefined;

  if (domainOrOptionsOrState && typeof domainOrOptionsOrState === 'object') {
    if (!('domain' in domainOrOptionsOrState) || 'turn' in domainOrOptionsOrState || 'day' in domainOrOptionsOrState || 'autoModeRuntime' in domainOrOptionsOrState || 'deterministicCounters' in domainOrOptionsOrState) {
      gameStateRef = domainOrOptionsOrState as ExtendedGameState;
      if (typeof modeOrScope === 'string') {
        if (modeOrScope === 'deterministic' || modeOrScope === 'legacy_random' || modeOrScope === 'recorded_chaos' || modeOrScope === 'hybrid') {
          selectedMode = modeOrScope as RandomnessMode;
        } else {
          domain = modeOrScope as RngScopeDomain;
        }
      }
      if (typeof recordedValuesOrMode === 'string') selectedMode = recordedValuesOrMode as RandomnessMode;
      if (Array.isArray(recordedValues)) queue = recordedValues;
    } else {
      domain = (domainOrOptionsOrState as DrawGameRandomOptions).domain;
      if ((domainOrOptionsOrState as DrawGameRandomOptions).mode) selectedMode = (domainOrOptionsOrState as DrawGameRandomOptions).mode!;
      queue = (domainOrOptionsOrState as DrawGameRandomOptions).recordedQueue || (domainOrOptionsOrState as DrawGameRandomOptions).recordedValues || (Array.isArray(recordedValuesOrMode) ? recordedValuesOrMode : recordedValues);
    }
  } else if (typeof domainOrOptionsOrState === 'string') {
    domain = domainOrOptionsOrState as RngScopeDomain;
    if (typeof modeOrScope === 'string') selectedMode = modeOrScope as RandomnessMode;
    if (Array.isArray(recordedValuesOrMode)) queue = recordedValuesOrMode as number[];
  }

  let resultVal: number;
  switch (selectedMode) {
    case 'legacy_random':
      resultVal = Math.random();
      break;

    case 'recorded_chaos':
      if (queue && queue.length > 0) {
        const nextVal = queue.shift();
        if (typeof nextVal === 'number' && !isNaN(nextVal)) {
          resultVal = nextVal;
          break;
        }
      }
      if (gameStateRef?.autoModeRuntime) {
        gameStateRef.autoModeRuntime.recordedChaosDivergence = true;
      }
      const allowFallback = Boolean(
        (domainOrOptionsOrState && typeof domainOrOptionsOrState === 'object' && (domainOrOptionsOrState as Record<string, any>).allowFallback) ||
        (typeof recordedValuesOrMode === 'object' && (recordedValuesOrMode as Record<string, any>)?.allowFallback) ||
        (typeof recordedValues === 'object' && (recordedValues as Record<string, any>)?.allowFallback)
      );
      if (allowFallback) {
        resultVal = drawGameplayRandom(domain);
        break;
      }
      const domainName = String(domain || 'World');
      throw new Error(`[Recorded Chaos Error] Random draw queue exhausted for domain '${domainName}'. Queue is empty.`);

    case 'hybrid':
      try {
        resultVal = drawGameplayRandom(domain);
      } catch {
        resultVal = Math.random();
      }
      break;

    case 'deterministic':
    default:
      resultVal = drawGameplayRandom(domain);
      break;
  }

  const streamState = domain && typeof getRngStreamState === 'function' ? getRngStreamState(domain) : undefined;
  const drawRecord: RecordedRandomDraw = {
    timestamp: Date.now(),
    step: gameStateRef?.turn ?? gameStateRef?.day ?? 1,
    scope: String(domain || 'default'),
    seed: streamState ? (streamState.seed ?? streamState.streamSeed) : undefined,
    state: streamState ? String(streamState.step ?? streamState.drawCount) : undefined,
    value: resultVal,
    stream: String(domain || 'default'),
    context: String(domain || 'default'),
    mode: selectedMode,
    system: String(domain || 'default'),
    day: gameStateRef?.day ?? 1,
    turn: gameStateRef?.turn ?? 1
  };
  if (selectedMode === 'recorded_chaos' || selectedMode === 'hybrid') {
    pendingReplayRandomDraws.push(drawRecord);
  }
  const activeReplay = gameStateRef?.autoModeRuntime?.replayEvents?.[gameStateRef.autoModeRuntime.replayEvents.length - 1];
  if (activeReplay) {
    if (!activeReplay.rngDraws) activeReplay.rngDraws = [];
    activeReplay.rngDraws.push(drawRecord);
  }

  return resultVal;
}

export function drawGameRandomChoice<T>(
  array: readonly T[],
  domain?: RngScopeDomain,
  mode: RandomnessMode = 'deterministic'
): T {
  if (!array || array.length === 0) return (array ? array[0] : undefined) as T;
  const rand = drawGameRandom(domain, mode);
  const index = Math.floor(rand * array.length);
  return array[Math.min(index, array.length - 1)];
}

export function drawGameRandomInt(
  min: number,
  max: number,
  domain?: RngScopeDomain,
  mode: RandomnessMode = 'deterministic'
): number {
  const rand = drawGameRandom(domain, mode);
  return Math.floor(min + rand * (max - min + 1));
}



export interface ReplayDrawValidationResult {
  valid: boolean;
  status: 'valid' | 'missing' | 'additional' | 'reordered' | 'mismatched' | 'exhausted';
  totalExpected: number;
  totalRecorded: number;
  divergenceIndex?: number;
  divergenceDetails?: string;
  mismatches: Array<{
    index: number;
    expected: RecordedRandomDraw;
    actual?: RecordedRandomDraw;
    reason: string;
  }>;
}

export function validateReplayRandomDraws(
  expectedDraws: RecordedRandomDraw[],
  actualDraws: RecordedRandomDraw[]
): ReplayDrawValidationResult {
  const mismatches: ReplayDrawValidationResult['mismatches'] = [];
  const expectedCount = expectedDraws ? expectedDraws.length : 0;
  const actualCount = actualDraws ? actualDraws.length : 0;

  if (expectedCount === 0 && actualCount === 0) {
    return { valid: true, status: 'valid', totalExpected: 0, totalRecorded: 0, mismatches: [] };
  }

  if (expectedCount > 0 && actualCount === 0) {
    return {
      valid: false,
      status: 'missing',
      totalExpected: expectedCount,
      totalRecorded: 0,
      divergenceIndex: 0,
      divergenceDetails: `All expected random draws missing during replay: expected ${expectedCount}, got 0`,
      mismatches: [{
        index: 0,
        expected: expectedDraws[0],
        reason: 'Random draw queue missing completely'
      }]
    };
  }

  const minCount = Math.min(expectedCount, actualCount);

  for (let i = 0; i < minCount; i++) {
    const exp = expectedDraws[i];
    const act = actualDraws[i];

    if (exp.id && act.id && exp.id !== act.id) {
      mismatches.push({
        index: i,
        expected: exp,
        actual: act,
        reason: `ID mismatch at index ${i}: expected '${exp.id}', actual '${act.id}'`
      });
    } else if (exp.system && act.system && exp.system !== act.system) {
      mismatches.push({
        index: i,
        expected: exp,
        actual: act,
        reason: `System domain mismatch at index ${i}: expected '${exp.system}', actual '${act.system}'`
      });
    } else if (Math.abs(exp.value - act.value) > 1e-6) {
      mismatches.push({
        index: i,
        expected: exp,
        actual: act,
        reason: `Value mismatch at index ${i}: expected ${exp.value}, actual ${act.value}`
      });
    } else if (exp.seq !== undefined && act.seq !== undefined && exp.seq !== act.seq) {
      mismatches.push({
        index: i,
        expected: exp,
        actual: act,
        reason: `Draw sequence reordered at index ${i}: expected seq ${exp.seq}, actual seq ${act.seq}`
      });
    }
  }

  if (mismatches.length > 0) {
    const first = mismatches[0];
    return {
      valid: false,
      status: first.reason.includes('reordered') ? 'reordered' : 'mismatched',
      totalExpected: expectedCount,
      totalRecorded: actualCount,
      divergenceIndex: first.index,
      divergenceDetails: first.reason,
      mismatches
    };
  }

  if (actualCount < expectedCount) {
    return {
      valid: false,
      status: 'exhausted',
      totalExpected: expectedCount,
      totalRecorded: actualCount,
      divergenceIndex: actualCount,
      divergenceDetails: `Exhausted random draws during replay: expected ${expectedCount}, got ${actualCount}`,
      mismatches: [{
        index: actualCount,
        expected: expectedDraws[actualCount],
        reason: `Random draw queue exhausted at index ${actualCount}`
      }]
    };
  }

  if (actualCount > expectedCount) {
    return {
      valid: false,
      status: 'additional',
      totalExpected: expectedCount,
      totalRecorded: actualCount,
      divergenceIndex: expectedCount,
      divergenceDetails: `Additional unexpected random draws generated during replay: expected ${expectedCount}, got ${actualCount}`,
      mismatches: [{
        index: expectedCount,
        expected: actualDraws[expectedCount],
        reason: `Additional unexpected draw at index ${expectedCount}`
      }]
    };
  }

  return {
    valid: true,
    status: 'valid',
    totalExpected: expectedCount,
    totalRecorded: actualCount,
    mismatches: []
  };
}

export function withRngScope<T>(domain: RngScopeDomain, callback: () => T): T {
  return globalRngRegistry.withScope(domain, callback);
}

function getActiveRngScope(): RngScopeDomain | null {
  return globalRngRegistry.activeRngScope;
}

export function getRngStreamState(domain: RngScopeDomain): RngStreamState {
  let targetDomain: RngScopeDomain | undefined = domain;
  if (!globalRngRegistry.streams[targetDomain]) {
    const lower = String(domain).toLowerCase();
    targetDomain = (Object.keys(globalRngRegistry.streams) as RngScopeDomain[]).find(
      d => d.toLowerCase() === lower
    );
  }
  return globalRngRegistry.streams[targetDomain || domain] || {
    domain,
    streamSeed: 1337,
    drawCount: 0,
    rollingHash: 0,
    currentState: 1337
  };
}

function setRngStreamState(domain: RngScopeDomain, state: Partial<RngStreamState>): void {
  let targetDomain: RngScopeDomain | undefined = domain;
  if (!globalRngRegistry.streams[targetDomain]) {
    const lower = String(domain).toLowerCase();
    targetDomain = (Object.keys(globalRngRegistry.streams) as RngScopeDomain[]).find(
      d => d.toLowerCase() === lower
    );
  }
  const key = targetDomain || domain;
  if (globalRngRegistry.streams[key]) {
    globalRngRegistry.streams[key] = { ...globalRngRegistry.streams[key], ...state };
  }
}
export function reseedMasterRng(seed: number): void {
  globalRngRegistry.reseedMaster(seed);
}

interface RngStreamController {
  nextFloat: () => number;
  nextInt: (min: number, max: number) => number;
  choice: <T>(arr: readonly T[]) => T;
  nextRange: (min: number, max: number) => number;
  getState: () => RngStreamState;
}

export function getRngStream(domain: RngScopeDomain): RngStreamController {
  return {
    nextFloat: () => drawGameplayRandom(domain),
    nextInt: (min: number, max: number) => Math.floor(min + drawGameplayRandom(domain) * (max - min + 1)),
    choice: <T,>(arr: readonly T[]) => drawGameplayRandomChoice(domain, arr),
    nextRange: (min: number, max: number) => min + drawGameplayRandom(domain) * (max - min),
    getState: () => getRngStreamState(domain)
  };
}

export function captureRngState(domain?: RngScopeDomain): any {
  if (domain) {
    return getRngStreamState(domain);
  }
  return serializeRngRegistry();
}

export function restoreRngState(domainOrSnapshot: any, state?: Partial<RngStreamState>): void {
  if (typeof domainOrSnapshot === 'string') {
    if (globalRngRegistry.streams[domainOrSnapshot as RngScopeDomain]) {
      globalRngRegistry.streams[domainOrSnapshot as RngScopeDomain] = {
        ...globalRngRegistry.streams[domainOrSnapshot as RngScopeDomain],
        ...state
      };
    }
  } else if (domainOrSnapshot && typeof domainOrSnapshot === 'object') {
    deserializeRngRegistry(domainOrSnapshot);
  }
}

export function serializeRngRegistry(): Record<string, RngStreamState> {
  return globalRngRegistry.exportStreamStates();
}

export function deserializeRngRegistry(states: Record<string, RngStreamState>): void {
  globalRngRegistry.importStreamStates(states);
}

// Phase F: Deterministic Counters and ID Generation
export interface DeterministicCounters {
  actionAttempt: number;
  replayActionsExecuted?: number;
  ledgerEvent: number;
  replayEvent: number;
  checkpoint: number;
  branch: number;
  approval: number;
  treasuryRequest: number;
  decision: number;
  correlation: number;
}
export function createInitialDeterministicCounters(): DeterministicCounters {
  return {
    actionAttempt: 0,
    replayActionsExecuted: 0,
    ledgerEvent: 0,
    replayEvent: 0,
    checkpoint: 0,
    branch: 0,
    approval: 0,
    treasuryRequest: 0,
    decision: 0,
    correlation: 0
  };
}
export const globalDeterministicCounters: DeterministicCounters = createInitialDeterministicCounters();

export function resetGlobalDeterministicCounters(): void {
  const fresh = createInitialDeterministicCounters();
  Object.assign(globalDeterministicCounters, fresh);
}

export function setGlobalDeterministicCounters(saved?: DeterministicCounters): void {
  if (saved) {
    Object.assign(globalDeterministicCounters, saved);
  } else {
    resetGlobalDeterministicCounters();
  }
}

export function incrementDeterministicCounter(counterName: keyof DeterministicCounters, delta: number = 1): void {
  if (counterName in globalDeterministicCounters) {
    (globalDeterministicCounters as unknown as Record<string, number>)[counterName] = ((globalDeterministicCounters as unknown as Record<string, number>)[counterName] || 0) + delta;
  }
}
export function nextActionAttemptId(counters: DeterministicCounters = globalDeterministicCounters, matchId: string = 'match'): string {
  counters.actionAttempt += 1;
  return `${matchId}:action:${counters.actionAttempt}`;
}

export function nextLedgerEventId(counters: DeterministicCounters = globalDeterministicCounters, matchId: string = 'match'): string {
  counters.ledgerEvent += 1;
  return `${matchId}:glevt:${counters.ledgerEvent}`;
}

export function nextReplayEventId(counters: DeterministicCounters = globalDeterministicCounters, matchId: string = 'match'): string {
  counters.replayEvent += 1;
  return `${matchId}:replayevt:${counters.replayEvent}`;
}

export function nextDeterministicId(
  prefixOrCountersOrState: string | DeterministicCounters | GameState | ExtendedGameState = 'det',
  countersOrPrefixOrState: DeterministicCounters | string | GameState | ExtendedGameState = globalDeterministicCounters
): string {
  let counters = globalDeterministicCounters;
  let prefix = 'det';

  if (typeof prefixOrCountersOrState === 'string') {
    prefix = prefixOrCountersOrState;
    if (countersOrPrefixOrState && typeof countersOrPrefixOrState === 'object') {
      if ('deterministicCounters' in countersOrPrefixOrState || 'turn' in countersOrPrefixOrState || 'day' in countersOrPrefixOrState) {
        const stateObj = countersOrPrefixOrState as { deterministicCounters?: DeterministicCounters };
        if (!stateObj.deterministicCounters) {
          stateObj.deterministicCounters = createInitialDeterministicCounters();
        }
        counters = stateObj.deterministicCounters;
      } else {
        counters = countersOrPrefixOrState as DeterministicCounters;
      }
    }
  } else if (prefixOrCountersOrState && typeof prefixOrCountersOrState === 'object') {
    if ('deterministicCounters' in prefixOrCountersOrState || 'turn' in prefixOrCountersOrState || 'day' in prefixOrCountersOrState) {
      const stateObj = prefixOrCountersOrState as { deterministicCounters?: DeterministicCounters };
      if (!stateObj.deterministicCounters) {
        stateObj.deterministicCounters = createInitialDeterministicCounters();
      }
      counters = stateObj.deterministicCounters;
      if (typeof countersOrPrefixOrState === 'string') {
        prefix = countersOrPrefixOrState;
      }
    } else {
      counters = prefixOrCountersOrState as DeterministicCounters;
      if (typeof countersOrPrefixOrState === 'string') {
        prefix = countersOrPrefixOrState;
      }
    }
  }

  counters.replayEvent = (counters.replayEvent || 0) + 1;
  return `${prefix}:${counters.replayEvent}`;
}

export function generateDeterministicId(
  stateOrPrefix?: GameState | ExtendedGameState | string | DeterministicCounters,
  prefixOrState?: string | GameState | ExtendedGameState
): string {
  if (stateOrPrefix !== undefined && prefixOrState !== undefined) {
    return nextDeterministicId(stateOrPrefix, prefixOrState);
  }
  if (stateOrPrefix !== undefined) {
    return nextDeterministicId(stateOrPrefix);
  }
  return nextDeterministicId();
}

export function nextCheckpointId(counters: DeterministicCounters = globalDeterministicCounters, matchId: string = 'match'): string {
  counters.checkpoint += 1;
  return `${matchId}:chk:${counters.checkpoint}`;
}

export function nextBranchId(counters: DeterministicCounters = globalDeterministicCounters, matchId: string = 'match'): string {
  counters.branch += 1;
  return `${matchId}:branch:${counters.branch}`;
}

function nextApprovalId(counters: DeterministicCounters = globalDeterministicCounters, matchId: string = 'match'): string {
  counters.approval += 1;
  return `${matchId}:approval:${counters.approval}`;
}

function nextTreasuryRequestId(counters: DeterministicCounters = globalDeterministicCounters, matchId: string = 'match'): string {
  counters.treasuryRequest += 1;
  return `${matchId}:treasury:${counters.treasuryRequest}`;
}

export function nextDecisionId(counters: DeterministicCounters = globalDeterministicCounters, matchId: string = 'match'): string {
  counters.decision += 1;
  return `${matchId}:decision:${counters.decision}`;
}

export function nextCorrelationId(counters: DeterministicCounters = globalDeterministicCounters, matchId: string = 'match'): string {
  counters.correlation += 1;
  return `${matchId}:corr:${counters.correlation}`;
}
export function setRngMasterSeed(seed: number, isDeterministic: boolean = true) {
  globalRngRegistry.isDeterministic = isDeterministic;
  globalRngRegistry.setAuditPolicy(isDeterministic ? 'strict' : 'monitor');
  globalRngRegistry.initStreams(seed);
  resetGlobalDeterministicCounters();
}


