export type UISurfaceCategory = 'modal' | 'drawer' | 'panel' | 'widget' | 'overlay' | 'toast' | 'launcher';
export type UIScreenZone = 'fullscreen' | 'center-modal' | 'side-drawer' | 'bottom-right' | 'bottom-left' | 'top-bar' | 'toast-lane';

export interface UISurfaceDefinition {
  id: string;
  name: string;
  tier: UISurfaceTier;
  priorityTier?: UISurfaceTier;
  isBlocking: boolean;
  hasBackdrop: boolean;
  category: UISurfaceCategory;
  reservedZone?: UIScreenZone;
  allowEscapeClose?: boolean;
}

export function isInputFocused(target: EventTarget | null): boolean {
  if (!target || typeof target !== 'object') return false;
  if (typeof Element !== 'undefined' && !(target instanceof Element)) {
    return false;
  }
  const element = target as any;
  const tagName = element.tagName ? String(element.tagName).toLowerCase() : '';
  if (tagName === 'input' || tagName === 'textarea' || tagName === 'select') {
    return true;
  }
  if (element.isContentEditable || element.getAttribute?.('contenteditable') === 'true' || element.getAttribute?.('role') === 'textbox') {
    return true;
  }
  if (typeof element.closest === 'function' && element.closest('[contenteditable="true"], [role="textbox"]')) {
    return true;
  }
  return false;
}

