// MILESTONE 5 (R6): UNIFIED LAUNCHER, DOCK, PRESETS, AUTO-HIDE & SIZE MODES

// --- 1. Unified Interface Launcher Settings ---
export interface UnifiedInterfaceLauncherSettings {
  enabled: boolean;
  position: { x: number; y: number };
  allowDragging: boolean;
  rememberPosition: boolean;
  showUnreadBadge: boolean;
  autoCollapse: boolean;
}

export function sanitizeLauncherSettings(input: unknown): UnifiedInterfaceLauncherSettings {
  const defaults = createDefaultLauncherSettings();
  if (!input || typeof input !== 'object' || input === null) return defaults;
  const src = input as Record<string, unknown>;
  const rawPos = typeof src.position === 'object' && src.position !== null ? src.position as Record<string, unknown> : {};
  return {
    enabled: typeof src.enabled === 'boolean' ? src.enabled : defaults.enabled,
    position: {
      x: typeof rawPos.x === 'number' && !isNaN(rawPos.x) ? rawPos.x : defaults.position.x,
      y: typeof rawPos.y === 'number' && !isNaN(rawPos.y) ? rawPos.y : defaults.position.y
    },
    allowDragging: typeof src.allowDragging === 'boolean' ? src.allowDragging : defaults.allowDragging,
    rememberPosition: typeof src.rememberPosition === 'boolean' ? src.rememberPosition : defaults.rememberPosition,
    showUnreadBadge: typeof src.showUnreadBadge === 'boolean' ? src.showUnreadBadge : defaults.showUnreadBadge,
    autoCollapse: typeof src.autoCollapse === 'boolean' ? src.autoCollapse : defaults.autoCollapse
  };
}

// --- 2. Floating Widget Dock Settings ---
export type FloatingWidgetDockPositionMode =
  | 'free'
  | 'snap_to_edge'
  | 'left_vertical'
  | 'right_vertical'
  | 'top_horizontal'
  | 'bottom_horizontal'
  | 'single_button_stack'
  | 'auto_collapsing_dock';

export interface FloatingWidgetDockSettings {
  enabled: boolean;
  positionMode: FloatingWidgetDockPositionMode;
  autoCollapseTimerMs: number;
  allowDrag: boolean;
  dockOpacity: number;
  activeWidgets: string[];
}

export function sanitizeDockSettings(input: unknown): FloatingWidgetDockSettings {
  const defaults = createDefaultDockSettings();
  if (!input || typeof input !== 'object' || input === null) return defaults;
  const src = input as Record<string, unknown>;
  const validModes: FloatingWidgetDockPositionMode[] = [
    'free', 'snap_to_edge', 'left_vertical', 'right_vertical',
    'top_horizontal', 'bottom_horizontal', 'single_button_stack', 'auto_collapsing_dock'
  ];
  const posMode = typeof src.positionMode === 'string' && validModes.includes(src.positionMode as any)
    ? (src.positionMode as FloatingWidgetDockPositionMode)
    : defaults.positionMode;
  return {
    enabled: typeof src.enabled === 'boolean' ? src.enabled : defaults.enabled,
    positionMode: posMode,
    autoCollapseTimerMs: typeof src.autoCollapseTimerMs === 'number' && src.autoCollapseTimerMs >= 0 ? src.autoCollapseTimerMs : defaults.autoCollapseTimerMs,
    allowDrag: typeof src.allowDrag === 'boolean' ? src.allowDrag : defaults.allowDrag,
    dockOpacity: typeof src.dockOpacity === 'number' && src.dockOpacity >= 0.1 && src.dockOpacity <= 1 ? src.dockOpacity : defaults.dockOpacity,
    activeWidgets: Array.isArray(src.activeWidgets) ? src.activeWidgets.filter(w => typeof w === 'string') : defaults.activeWidgets
  };
}

// --- 3. Interface Layout Presets Settings ---
export type InterfaceLayoutPreset = 'Clean' | 'Assisted' | 'Advanced' | 'Developer' | 'Current/Custom';

export interface LayoutPresetSettings {
  activePreset: InterfaceLayoutPreset;
  lastSelectedPreset?: InterfaceLayoutPreset;
}

export function sanitizePresetSettings(input: unknown): LayoutPresetSettings {
  const defaults = createDefaultPresetSettings();
  if (!input || typeof input !== 'object' || input === null) return defaults;
  const src = input as Record<string, unknown>;
  const validPresets: InterfaceLayoutPreset[] = ['Clean', 'Assisted', 'Advanced', 'Developer', 'Current/Custom'];
  const activePreset = typeof src.activePreset === 'string' && validPresets.includes(src.activePreset as any)
    ? (src.activePreset as InterfaceLayoutPreset)
    : defaults.activePreset;
  return {
    activePreset,
    lastSelectedPreset: typeof src.lastSelectedPreset === 'string' && validPresets.includes(src.lastSelectedPreset as any)
      ? (src.lastSelectedPreset as InterfaceLayoutPreset)
      : activePreset
  };
}

export function applyLayoutPreset(
  preset: InterfaceLayoutPreset,
  currentSettings: GameSettingsState
): GameSettingsState {
  const next = { ...currentSettings };
  const updatedPresetSettings: LayoutPresetSettings = {
    ...sanitizePresetSettings(next.presetSettings),
    activePreset: preset,
    lastSelectedPreset: preset
  };
  next.presetSettings = updatedPresetSettings;

  if (preset === 'Clean') {
    next.launcherSettings = { ...sanitizeLauncherSettings(next.launcherSettings), enabled: false, autoCollapse: true };
    next.dockSettings = { ...sanitizeDockSettings(next.dockSettings), enabled: true, positionMode: 'auto_collapsing_dock', dockOpacity: 0.8 };
    next.autoHideSettings = { ...sanitizeAutoHideSettings(next.autoHideSettings), contextualFloatingUiVisibility: true, alwaysShowEnabledWidgets: false };
    next.notificationLaneSettings = { ...sanitizeNotificationLaneSettings(next.notificationLaneSettings), anchor: 'top_right', autoCollapseRoutine: true };
  } else if (preset === 'Assisted') {
    next.launcherSettings = { ...sanitizeLauncherSettings(next.launcherSettings), enabled: false, autoCollapse: true };
    next.dockSettings = { ...sanitizeDockSettings(next.dockSettings), enabled: true, positionMode: 'bottom_horizontal', activeWidgets: ['ask_game', 'guardian', 'strategy_planner'] };
    next.autoHideSettings = { ...sanitizeAutoHideSettings(next.autoHideSettings), contextualFloatingUiVisibility: true, alwaysShowEnabledWidgets: false };
    next.modalSizeSettings = { ...sanitizeModalSizeSettings(next.modalSizeSettings), globalSizeMode: 'standard' };
  } else if (preset === 'Advanced') {
    next.launcherSettings = { ...sanitizeLauncherSettings(next.launcherSettings), enabled: true, autoCollapse: false };
    next.dockSettings = { ...sanitizeDockSettings(next.dockSettings), enabled: true, positionMode: 'bottom_horizontal', activeWidgets: ['ask_game', 'guardian', 'ai_command', 'strategy_planner', 'quick_actions'] };
    next.autoHideSettings = { ...sanitizeAutoHideSettings(next.autoHideSettings), contextualFloatingUiVisibility: true, alwaysShowEnabledWidgets: true };
    next.modalSizeSettings = { ...sanitizeModalSizeSettings(next.modalSizeSettings), globalSizeMode: 'wide' };
  } else if (preset === 'Developer') {
    next.launcherSettings = { ...sanitizeLauncherSettings(next.launcherSettings), enabled: true, autoCollapse: false };
    next.dockSettings = { ...sanitizeDockSettings(next.dockSettings), enabled: true, positionMode: 'left_vertical', activeWidgets: ['ask_game', 'guardian', 'ai_command', 'strategy_planner', 'quick_actions', 'dev_diagnostics'] };
    next.autoHideSettings = { ...sanitizeAutoHideSettings(next.autoHideSettings), contextualFloatingUiVisibility: false, alwaysShowEnabledWidgets: true, autoHideDevWidgetsOutsideDevLayout: false };
    next.modalSizeSettings = { ...sanitizeModalSizeSettings(next.modalSizeSettings), globalSizeMode: 'wide' };
  }
  return next;
}

