// --- 6. Consistent Modal Size Settings ---
export type ModalSizeMode = 'compact' | 'standard' | 'wide' | 'fullscreen';

export interface ModalSizeSettings {
  globalSizeMode: ModalSizeMode;
  surfaceSizeOverrides: Record<string, ModalSizeMode>;
}

export function sanitizeModalSizeSettings(input: unknown): ModalSizeSettings {
  const defaults = createDefaultModalSizeSettings();
  if (!input || typeof input !== 'object' || input === null) return defaults;
  const src = input as Record<string, unknown>;
  const validSizes: ModalSizeMode[] = ['compact', 'standard', 'wide', 'fullscreen'];
  const globalSizeMode = typeof src.globalSizeMode === 'string' && validSizes.includes(src.globalSizeMode as any)
    ? (src.globalSizeMode as ModalSizeMode)
    : defaults.globalSizeMode;
  const surfaceSizeOverrides: Record<string, ModalSizeMode> = {};
  if (typeof src.surfaceSizeOverrides === 'object' && src.surfaceSizeOverrides !== null) {
    Object.entries(src.surfaceSizeOverrides as Record<string, unknown>).forEach(([k, v]) => {
      if (typeof v === 'string' && validSizes.includes(v as any)) {
        surfaceSizeOverrides[k] = v as ModalSizeMode;
      }
    });
  }
  return {
    globalSizeMode,
    surfaceSizeOverrides
  };
}

export function getEffectiveModalSizeMode(surfaceId: string, settings?: GameSettingsState): ModalSizeMode {
  const modalSettings = sanitizeModalSizeSettings(settings?.modalSizeSettings);
  return modalSettings.surfaceSizeOverrides[surfaceId] || modalSettings.globalSizeMode || 'standard';
}

export function getModalSizeClasses(mode: ModalSizeMode): { container: string; body: string } {
  switch (mode) {
    case 'compact':
      return {
        container: 'max-w-[480px] w-full max-h-[50vh]',
        body: 'max-h-[calc(50vh-120px)] overflow-y-auto break-words'
      };
    case 'wide':
      return {
        container: 'max-w-[900px] w-full max-h-[calc(100dvh-2rem)]',
        body: 'max-h-[calc(85vh-120px)] overflow-y-auto break-words'
      };
    case 'fullscreen':
      return {
        container: 'w-screen h-screen max-w-none max-h-none rounded-none',
        body: 'h-[calc(100vh-120px)] overflow-y-auto break-words'
      };
    case 'standard':
    default:
      return {
        container: 'max-w-[640px] w-full max-h-[70vh]',
        body: 'max-h-[calc(70vh-120px)] overflow-y-auto break-words'
      };
  }
}

