export type RescueHotkeyCombo = 'shift+escape' | 'ctrl+shift+r' | 'alt+shift+escape';

export interface UiRescueSettings {
  enableEscapeKeyClosing: boolean;
  enableShiftEscapeRescueHotkey: boolean;
  preserveApprovalModalsDuringRescue: boolean;
  restoreDefaultScaleOnRescue: boolean;
  resetDockOnRescue: boolean;
  rescueHotkeyCombo?: RescueHotkeyCombo;
  autoResetOffscreenWidgetsOnResize?: boolean;
  notifyOnRescueExecution?: boolean;
  // Aliases for backwards compatibility:
  escapeKeyRescueEnabled?: boolean;
  emergencyRescueHotkeyEnabled?: boolean;
}

export function sanitizeRescueSettings(input: unknown): UiRescueSettings {
  const defaults = createDefaultUiRescueSettings();
  if (!input || typeof input !== 'object' || input === null) return defaults;
  const src = input as Record<string, unknown>;
  const validCombos: RescueHotkeyCombo[] = ['shift+escape', 'ctrl+shift+r', 'alt+shift+escape'];
  const enableEscapeKeyClosing = typeof src.enableEscapeKeyClosing === 'boolean'
    ? src.enableEscapeKeyClosing
    : (typeof src.escapeKeyRescueEnabled === 'boolean' ? src.escapeKeyRescueEnabled : defaults.enableEscapeKeyClosing);
  const enableShiftEscapeRescueHotkey = typeof src.enableShiftEscapeRescueHotkey === 'boolean'
    ? src.enableShiftEscapeRescueHotkey
    : (typeof src.emergencyRescueHotkeyEnabled === 'boolean' ? src.emergencyRescueHotkeyEnabled : defaults.enableShiftEscapeRescueHotkey);

  return {
    enableEscapeKeyClosing,
    enableShiftEscapeRescueHotkey,
    preserveApprovalModalsDuringRescue: typeof src.preserveApprovalModalsDuringRescue === 'boolean' ? src.preserveApprovalModalsDuringRescue : defaults.preserveApprovalModalsDuringRescue,
    restoreDefaultScaleOnRescue: typeof src.restoreDefaultScaleOnRescue === 'boolean' ? src.restoreDefaultScaleOnRescue : defaults.restoreDefaultScaleOnRescue,
    resetDockOnRescue: typeof src.resetDockOnRescue === 'boolean' ? src.resetDockOnRescue : defaults.resetDockOnRescue,
    rescueHotkeyCombo: typeof src.rescueHotkeyCombo === 'string' && validCombos.includes(src.rescueHotkeyCombo as any)
      ? (src.rescueHotkeyCombo as RescueHotkeyCombo)
      : defaults.rescueHotkeyCombo,
    autoResetOffscreenWidgetsOnResize: typeof src.autoResetOffscreenWidgetsOnResize === 'boolean' ? src.autoResetOffscreenWidgetsOnResize : defaults.autoResetOffscreenWidgetsOnResize,
    notifyOnRescueExecution: typeof src.notifyOnRescueExecution === 'boolean' ? src.notifyOnRescueExecution : defaults.notifyOnRescueExecution,
    escapeKeyRescueEnabled: enableEscapeKeyClosing,
    emergencyRescueHotkeyEnabled: enableShiftEscapeRescueHotkey,
  };
}

export function sanitizeUiRescueSettings(input: unknown): UiRescueSettings {
  return sanitizeRescueSettings(input);
}

