// --- 7. Standardized Game Phase & Contextual Hiding Engine ---
export type StandardizedGamePhase =
  | 'main_menu'
  | 'setup'
  | 'human_turn'
  | 'ai_turn'
  | 'approval_waiting'
  | 'paused'
  | 'save_load'
  | 'replay'
  | 'post_match';

export function resolveCurrentGamePhase(
  gameState: any,
  uiState: any,
  surfaceManagerState: GlobalUISurfaceManagerState
): StandardizedGamePhase {
  if (uiState?.showStartScreen || gameState?.gameMode === 'start_screen' || gameState?.gameMode === 'menu' || gameState?.gameStarted === false) {
    return uiState?.showCampaignSelect ? 'setup' : 'main_menu';
  }
  if (surfaceManagerState?.activeBlockingModal === 'save_load_modal' || uiState?.showSaveLoadModal) {
    return 'save_load';
  }
  if (surfaceManagerState?.activeBlockingModal === 'replay_viewer' || uiState?.showReplayViewer) {
    return 'replay';
  }
  if (surfaceManagerState?.activeBlockingModal === 'approval_dialog' || uiState?.isApprovalWaiting) {
    return 'approval_waiting';
  }
  if (uiState?.isPaused || gameState?.isPaused) {
    return 'paused';
  }
  if (gameState?.isGameOver || uiState?.showEndGameModal) {
    return 'post_match';
  }
  if (gameState?.isAiTurn || gameState?.currentActorId?.startsWith('ai_')) {
    return 'ai_turn';
  }
  return 'human_turn';
}

export function shouldShowWidgetContextually(
  widgetId: string,
  phase: StandardizedGamePhase,
  gameState: any,
  gameSettings: GameSettingsState,
  surfaceManagerState: GlobalUISurfaceManagerState,
  activeLayoutPreset: InterfaceLayoutPreset = 'Current/Custom'
): boolean {
  // Absolute Exemption: Critical Emergency Warnings & Rescue Overlays NEVER hidden
  if (widgetId === 'rescue_emergency_overlay' || widgetId === 'guardian_warning_modal' || widgetId === 'critical_notifications') {
    return true;
  }

  // Tier 6+ Safe-Area Suppression: when any Tier 6+ blocking modal is active, contextually suppress non-critical floating widgets
  if (surfaceManagerState?.activeBlockingModal !== null && surfaceManagerState?.activeBlockingModal !== undefined) {
    return false;
  }
  if (surfaceManagerState?.isBackgroundBlocked || (surfaceManagerState?.suppressedFloatingWidgets && surfaceManagerState.suppressedFloatingWidgets.includes(widgetId))) {
    return false;
  }

  const autoHide = sanitizeAutoHideSettings(gameSettings?.autoHideSettings);

  if (autoHide.alwaysShowEnabledWidgets) {
    return true;
  }

  if (!autoHide.contextualFloatingUiVisibility) {
    return true;
  }

  if (phase === 'main_menu' || phase === 'setup') {
    const startScreenProtection = gameSettings?.startScreenConflictProtection ?? true;
    const hidePanels = gameSettings?.hideGameplaySidePanelsOnStartScreen ?? true;
    const userOverride = Boolean(gameSettings?.showFloatingControlsOnStartScreen);
    if ((startScreenProtection || hidePanels) && !userOverride) {
      if (widgetId === 'quick_actions' || widgetId === 'quick_actions_reopen_handle' || widgetId === 'ai_command_center_widget' || widgetId === 'strategy_planner_widget' || widgetId === 'guardian_floating_button' || widgetId === 'ask_game_floating_button') {
        return false;
      }
    }
  }

  if (phase === 'save_load') {
    if (autoHide.autoHideGameplayWidgetsDuringSaveLoad && (widgetId === 'quick_actions' || widgetId === 'quick_actions_reopen_handle' || widgetId === 'strategy_planner_widget' || widgetId === 'ai_command_center_widget')) {
      return false;
    }
  }

  if (phase === 'approval_waiting') {
    if (autoHide.autoHideAskGameDuringApproval && (widgetId === 'ask_game_floating_button' || widgetId === 'ask_game_ai')) {
      return false;
    }
  }

  if (surfaceManagerState.activeBlockingModal !== null && autoHide.autoHideQuickActionsDuringModal && (widgetId === 'quick_actions' || widgetId === 'quick_actions_reopen_handle')) {
    return false;
  }

  if (widgetId === 'strategy_planner_widget' || widgetId === 'strategy_planner') {
    if (autoHide.autoHideStrategyPlannerNoPlan) {
      const activePlan = gameState?.activeStrategyPlan;
      if (!activePlan || (Array.isArray(activePlan.steps) && activePlan.steps.length === 0)) {
        return false;
      }
    }
  }

  if (widgetId === 'guardian_floating_button' || widgetId === 'guardian_status_panel') {
    if (autoHide.autoHideGuardianDisabled) {
      const guardianEnabled = gameSettings?.guardianAiSettings?.enabled ?? true;
      if (!guardianEnabled) {
        return false;
      }
    }
  }

  if (widgetId === 'ai_command_center_widget' || widgetId === 'ai_command_center_modal') {
    const evalRes = evaluateAiCommandCenterGamePhaseVisibility(phase, gameState, gameSettings, surfaceManagerState);
    if (!evalRes.shouldShow) {
      return false;
    }
  }

  if (widgetId === 'developer_diagnostics_widget') {
    if (autoHide.autoHideDevWidgetsOutsideDevLayout && activeLayoutPreset !== 'Developer') {
      return false;
    }
  }

  return true;
}

