export interface FloatingUIConflictControlSettings {
  enabled: boolean;                 // Master toggle (default: true)
  allowRelocation: boolean;         // Relocate lower priority widgets (default: true)
  returnToPreferred: boolean;       // Return to preferred coords when clear (default: true)
  showConflictExplanations: boolean;// Display "ℹ️ Moved" info badges (default: false)
  customPriorityOrder?: Record<string, number>; // Custom tier overrides [1..11]
}

export interface PriorityTierDefinition {
  tier: number; // 1..11
  name: string;
  category: string;
  collisionRank: number;
  canonicalZIndex?: number;
  relocationRule: string;
  defaultSurfaces: string[];
}

export function sanitizeConflictControlSettings(input: unknown): FloatingUIConflictControlSettings {
  const defaults = createDefaultConflictControlSettings();
  if (!input || typeof input !== 'object') return defaults;
  const src = input as Record<string, unknown>;
  return {
    enabled: typeof src.enabled === 'boolean' ? src.enabled : defaults.enabled,
    allowRelocation: typeof src.allowRelocation === 'boolean' ? src.allowRelocation : defaults.allowRelocation,
    returnToPreferred: typeof src.returnToPreferred === 'boolean' ? src.returnToPreferred : defaults.returnToPreferred,
    showConflictExplanations: typeof src.showConflictExplanations === 'boolean' ? src.showConflictExplanations : defaults.showConflictExplanations,
    customPriorityOrder: sanitizePriorityMatrix(src.customPriorityOrder as Record<string, number>)
  };
}

export function clampToViewport(
  pos: { x: number; y: number },
  dim: { width: number; height: number } = { width: 280, height: 180 },
  viewport?: { width: number; height: number },
  margin: number = 16
): { x: number; y: number } {
  const vpWidth = viewport?.width || (typeof window !== 'undefined' ? window.innerWidth : 1920);
  const vpHeight = viewport?.height || (typeof window !== 'undefined' ? window.innerHeight : 1080);

  const minX = margin;
  const minY = margin;
  const maxX = Math.max(minX, vpWidth - dim.width - margin);
  const maxY = Math.max(minY, vpHeight - dim.height - margin);

  const clampedX = Math.min(Math.max(pos.x, minX), maxX);
  const clampedY = Math.min(Math.max(pos.y, minY), maxY);

  return { x: clampedX, y: clampedY };
}

export function checkAABBOverlap(
  rectA: { x: number; y: number; width: number; height: number },
  rectB: { x: number; y: number; width: number; height: number },
  margin: number = 16
): boolean {
  return (
    rectA.x < rectB.x + rectB.width + margin &&
    rectA.x + rectA.width + margin > rectB.x &&
    rectA.y < rectB.y + rectB.height + margin &&
    rectA.y + rectA.height + margin > rectB.y
  );
}

