export function evaluateAutoModeBoundaries(
  profile: SmartSettingsProfile,
  currentSettings?: GameSettingsState
): Partial<AutoModeGlobalSettings> {
  const explicitPermMode = (profile as any)?.autoModePermissionMode || (profile as any)?.permissionMode;
  const explicitEnabled = (profile as any)?.autoModeEnabled;

  const targetAutoModeEnabled = explicitEnabled !== undefined
    ? Boolean(explicitEnabled)
    : profile?.automation !== 'manual';

  const permModeRaw: AutoModePermission = (explicitPermMode && targetAutoModeEnabled)
    ? (explicitPermMode as AutoModePermission)
    : (!targetAutoModeEnabled || profile?.automation === 'manual')
    ? 'disabled'
    : profile?.automation === 'recommendations' ? 'recommend_only'
    : profile?.automation === 'assisted' ? 'assist_only'
    : profile?.automation === 'mostly_automatic' ? 'auto_apply_non_intrusive'
    : 'full_adaptive';
  const validBoundaryPerms: AutoModePermission[] = ['locked', 'observe', 'recommend', 'assist_only', 'challenge_only', 'full_adaptive', 'disabled', 'recommend_only', 'auto_apply_non_intrusive', 'full_auto'];
  const permMode: AutoModePermission = validBoundaryPerms.includes(permModeRaw) ? permModeRaw : (targetAutoModeEnabled ? 'recommend_only' : 'disabled');

  return {
    autoModeEnabled: targetAutoModeEnabled,
    permissionMode: permMode,
    allowNumericalModifiers: profile?.aiFairness === 'fully_adaptive',
    allowStrategyChanges: true,
    allowEconomyChanges: profile?.complexity !== 'simple',
    allowActionManagementChanges: profile?.complexity !== 'simple',
    allowDifficultyAdjustments: profile?.aiFairness === 'fully_adaptive'
  };
}

/**
 * Rules Engine Translation: generateSmartSettingsPlan
 * Translates a high-level SmartSettingsProfile into concrete technical GameSettingsState modifications.
 * Enforces locks, Fairness Guardrails (Req 11), live-match safety, and autoMode boundaries.
 */
export function generateSmartSettingsPlan(
  profileOrContextOrText: string | SmartSettingsProfile | SmartSettingsTranslationContext,
  currentSettingsArg?: GameSettingsState,
  isLiveMatchArg?: boolean
): SmartSettingsPlan {
  let profile: SmartSettingsProfile;
  let currentSettings: GameSettingsState;
  let isLiveMatch: boolean;
  let parsedIntent: ParsedGameExperienceIntent | undefined;

  if (typeof profileOrContextOrText === 'string') {
    parsedIntent = parseMultiClauseExperienceIntent(profileOrContextOrText);
    currentSettings = currentSettingsArg || DEFAULT_GAME_SETTINGS;
    isLiveMatch = Boolean(isLiveMatchArg);

    profile = {
      enabled: true,
      interfaceLevel: 'guided',
      experienceStyle: parsedIntent.detectedStyle || 'custom',
      gamePace: parsedIntent.detectedPace || 'normal',
      aiIntelligence: parsedIntent.detectedIntelligence || 'capable',
      aiFairness: parsedIntent.detectedFairness || 'smarter_decisions_only',
      complexity: parsedIntent.detectedComplexity || 'guided',
      automation: parsedIntent.detectedAutomation || 'recommendations',
      randomness: parsedIntent.detectedRandomness || 'balanced',
      teamCoordination: parsedIntent.detectedTeamCoordination || 'cooperative',
      guidance: parsedIntent.detectedGuidance || 'guided',
      lockedCategories: currentSettings.smartSettingsProfile?.lockedCategories || [],
      lockedSettingKeys: currentSettings.smartSettingsProfile?.lockedSettingKeys || [],
      activePresetId: 'custom',
      derivedFromNaturalLanguage: true,
      originalIntentText: profileOrContextOrText,
      customOverridesDetected: true
    };
  } else if (profileOrContextOrText && typeof profileOrContextOrText === 'object' && 'profile' in profileOrContextOrText && 'currentSettings' in profileOrContextOrText) {
    const ctx = profileOrContextOrText as SmartSettingsTranslationContext;
    profile = ctx.profile;
    currentSettings = ctx.currentSettings;
    isLiveMatch = Boolean(ctx.isLiveMatch);
  } else {
    profile = profileOrContextOrText as SmartSettingsProfile;
    currentSettings = currentSettingsArg || DEFAULT_GAME_SETTINGS;
    isLiveMatch = Boolean(isLiveMatchArg);
  }

  const changes: SmartSettingsChange[] = [];
  const conflicts: SmartSettingsConflict[] = [];

  const lockedCategoriesSet = new Set<SmartSettingsCategory>(profile?.lockedCategories || []);
  const lockedKeysSet = new Set<string>(profile?.lockedSettingKeys || []);
  const protectedDimensionsSet = new Set<string>(parsedIntent?.protectedDimensions || []);
  for (const protDim of Array.from(protectedDimensionsSet)) {
    conflicts.push({
      settingKey: protDim,
      reason: `Dimension '${protDim}' is protected by user constraint.`,
      winningPriority: 'Explicit Protection Constraint',
      losingPriority: `Override Request (${protDim})`,
      resolutionAction: 'Preserved current setting value'
    });
  }

  const dimensionsToTranslate: { key: keyof SmartSettingsProfile; dimName: SmartSettingsRule['dimension'] }[] = [
    { key: 'aiIntelligence', dimName: 'aiIntelligence' },
    { key: 'aiFairness', dimName: 'aiFairness' },
    { key: 'gamePace', dimName: 'gamePace' },
    { key: 'complexity', dimName: 'complexity' },
    { key: 'automation', dimName: 'automation' },
    { key: 'coPilotMode', dimName: 'coPilotMode' },
    { key: 'randomness', dimName: 'randomness' },
    { key: 'teamCoordination', dimName: 'teamCoordination' },
    { key: 'guidance', dimName: 'guidance' }
  ];

  for (const dimInfo of dimensionsToTranslate) {
    if (dimInfo.key === 'coPilotMode') {
      const currentEffAuthMode = currentSettings.coPilotSettings?.authorityMode ?? currentSettings.coPilotAuthorityMode ?? 'off';
      const currentEffEnabled = currentSettings.coPilotSettings?.coPilotEnabled ?? currentSettings.coPilotEnabled ?? (currentEffAuthMode !== 'off');
      const currentConceptual = mapTechnicalSettingsToConceptualMode(currentEffEnabled, currentEffAuthMode);
      const currentAuthConceptual = mapTechnicalSettingsToConceptualMode(true, currentEffAuthMode);
      if (profile.coPilotMode === currentConceptual || (currentEffAuthMode !== 'off' && profile.coPilotMode === currentAuthConceptual)) {
        continue;
      }
    }
    if (protectedDimensionsSet.has(dimInfo.dimName)) {
      conflicts.push({
        settingKey: dimInfo.dimName,
        reason: `Dimension '${dimInfo.dimName}' is protected by user constraint.`,
        winningPriority: 'Explicit Protection Constraint',
        losingPriority: `Profile Preference (${dimInfo.dimName})`,
        resolutionAction: 'Preserved current setting value'
      });
      continue;
    }

    const prefValue = profile[dimInfo.key] as string | undefined;
    if (!prefValue) continue;

    const rule = SMART_SETTINGS_RULES.find(r => r.dimension === dimInfo.dimName && r.preferenceValue === prefValue);
    if (!rule) continue;

    for (const [settingKey, rawTargetVal] of Object.entries(rule.targetSettings)) {
      let proposedValue = rawTargetVal;
      const regEntry = SMART_CONTROLLABLE_SETTINGS_REGISTRY.find(s => s.key === settingKey);
      const category = regEntry?.category || 'ai';

      if (lockedKeysSet.has(settingKey)) {
        conflicts.push({
          settingKey,
          reason: `Setting '${settingKey}' is locked by explicit setting lock.`,
          winningPriority: 'Explicit Setting Lock',
          losingPriority: `Profile Preference (${dimInfo.dimName}:${prefValue})`,
          resolutionAction: 'Preserved current locked setting value'
        });
        continue;
      }
      if (lockedCategoriesSet.has(category)) {
        conflicts.push({
          settingKey,
          reason: `Setting '${settingKey}' (category '${category}') is locked by explicit category lock.`,
          winningPriority: 'Explicit Category Lock',
          losingPriority: `Profile Preference (${dimInfo.dimName}:${prefValue})`,
          resolutionAction: 'Preserved current locked setting value'
        });
        continue;
      }

      if (profile.aiFairness === 'strictly_equal' || profile.aiFairness === 'smarter_decisions_only') {
        if (settingKey === 'allowNumericalModifiers' && proposedValue === true) {
          proposedValue = false;
          conflicts.push({
            settingKey: 'allowNumericalModifiers',
            reason: `Numerical handicaps disabled under ${profile.aiFairness} fairness policy. AI decision depth increased without numerical cheats.`,
            winningPriority: 'Fairness Guardrail',
            losingPriority: 'Numerical Modifier Request',
            resolutionAction: 'Enforced allowNumericalModifiers = false'
          });
        }
        if (settingKey === 'aiFairnessLevel' && typeof proposedValue === 'number' && proposedValue !== 1.0) {
          proposedValue = 1.0;
        }
      }

      let safetyStatus: 'safe' | 'unsafe_deferred' = 'safe';
      if (isLiveMatch && regEntry && regEntry.isLiveSafe === false) {
        safetyStatus = 'unsafe_deferred';
      }

      const previousValue = (currentSettings as Record<string, unknown>)[settingKey];
      if (previousValue !== proposedValue) {
        changes.push({
          settingKey,
          category,
          previousValue,
          proposedValue,
          sourcePreference: `${dimInfo.dimName}:${prefValue}`,
          safetyStatus
        });
      }
    }
  }

  if (profile.askGameAiUiEnabled !== undefined && !changes.some(c => c.settingKey === 'askGameAiUiEnabled')) {
    const regEntry = SMART_CONTROLLABLE_SETTINGS_REGISTRY.find(s => s.key === 'askGameAiUiEnabled');
    const previousValue = currentSettings.askGameAiUiEnabled ?? false;
    if (previousValue !== profile.askGameAiUiEnabled) {
      changes.push({
        settingKey: 'askGameAiUiEnabled',
        category: regEntry?.category || 'interface',
        previousValue,
        proposedValue: profile.askGameAiUiEnabled,
        sourcePreference: 'profile:askGameAiUiEnabled',
        safetyStatus: 'safe'
      });
    }
  }

  if (parsedIntent && parsedIntent.targetDimensions) {
    for (const [settingKey, proposedVal] of Object.entries(parsedIntent.targetDimensions)) {
      if (changes.some(c => c.settingKey === settingKey)) continue;
      const regEntry = SMART_CONTROLLABLE_SETTINGS_REGISTRY.find(s => s.key === settingKey);
      const category = regEntry?.category || 'ai';

      if (lockedKeysSet.has(settingKey) || lockedCategoriesSet.has(category)) {
        conflicts.push({
          settingKey,
          reason: `Setting '${settingKey}' is locked by explicit lock.`,
          winningPriority: 'Explicit Lock',
          losingPriority: 'Intent Target Setting',
          resolutionAction: 'Preserved current locked setting value'
        });
        continue;
      }

      let safetyStatus: 'safe' | 'unsafe_deferred' = 'safe';
      if (isLiveMatch && regEntry && regEntry.isLiveSafe === false) {
        safetyStatus = 'unsafe_deferred';
      }

      const previousValue = (currentSettings as Record<string, unknown>)[settingKey];
      if (previousValue !== proposedVal) {
        changes.push({
          settingKey,
          category,
          previousValue,
          proposedValue: proposedVal,
          sourcePreference: 'intentTargetDimension',
          safetyStatus
        });
      }
    }
  }

  const autoModeBoundaries = evaluateAutoModeBoundaries(profile, currentSettings);
  const targetAutoModeEnabled = autoModeBoundaries.autoModeEnabled!;
  const permMode = autoModeBoundaries.permissionMode!;

  const hasAutoModeEnabledChange = changes.some(c => c.settingKey === 'autoModeEnabled');
  if (!hasAutoModeEnabledChange) {
    const regEntry = SMART_CONTROLLABLE_SETTINGS_REGISTRY.find(s => s.key === 'autoModeEnabled');
    const autoCategory = regEntry?.category || 'automation';
    if (lockedKeysSet.has('autoModeEnabled') || lockedCategoriesSet.has(autoCategory)) {
      if (!conflicts.some(c => c.settingKey === 'autoModeEnabled')) {
        conflicts.push({
          settingKey: 'autoModeEnabled',
          reason: `Setting 'autoModeEnabled' (category '${autoCategory}') is locked by explicit lock.`,
          winningPriority: 'Explicit Lock',
          losingPriority: 'Fallback Auto Mode Setting',
          resolutionAction: 'Preserved current locked setting value'
        });
      }
    } else {
      if (currentSettings.autoModeEnabled !== targetAutoModeEnabled) {
        changes.push({
          settingKey: 'autoModeEnabled',
          category: autoCategory,
          previousValue: currentSettings.autoModeEnabled,
          proposedValue: targetAutoModeEnabled,
          sourcePreference: `automation:${profile.automation}`,
          safetyStatus: 'safe'
        });
      }
    }
  }

  const hasPermissionModeChange = changes.some(c => c.settingKey === 'permissionMode');
  if (!hasPermissionModeChange) {
    const previousPerm = (currentSettings as any).autoModeSettings?.permissionMode || (currentSettings as any).permissionMode;
    if (previousPerm !== permMode) {
      changes.push({
        settingKey: 'permissionMode',
        category: 'automation',
        previousValue: previousPerm,
        proposedValue: permMode,
        sourcePreference: `automation:${profile.automation}`,
        safetyStatus: 'safe'
      });
    }
  }

  let fairnessSummary = '';
  if (profile.aiFairness === 'strictly_equal') {
    fairnessSummary = 'Fairness Guardrail: Strictly Equal. All players operate under identical numerical rules with zero AI cheats.';
  } else if (profile.aiFairness === 'smarter_decisions_only') {
    fairnessSummary = 'Fairness Guardrail: Smarter Decisions Only. AI difficulty scaled purely through search depth and planning lookahead without numerical handicaps.';
  } else if (profile.aiFairness === 'limited_adaptation') {
    fairnessSummary = 'Fairness Guardrail: Limited Adaptation. Minor tactical adjustments allowed, numerical modifiers restricted.';
  } else {
    fairnessSummary = 'Fairness Guardrail: Fully Adaptive. Full dynamic match handicap adjustments enabled.';
  }

  const summary = `Smart Settings Plan generated for style '${profile.experienceStyle}' (${profile.gamePace} pace, ${profile.aiIntelligence} AI, ${profile.aiFairness} fairness). ${changes.length} change(s) proposed, ${conflicts.length} conflict(s) resolved.`;

  smartSettingsPlanIdCounter += 1;
  const planId = `plan_${Date.now()}_${smartSettingsPlanIdCounter}`;

  const updatedSettings: GameSettingsState = { ...currentSettings };
  for (const c of changes) {
    if (c.safetyStatus === 'safe') {
      (updatedSettings as any)[c.settingKey] = c.proposedValue;
    }
  }
  updatedSettings.smartSettingsProfile = { ...profile };

  return {
    planId,
    timestamp: Date.now(),
    profile: { ...profile },
    changes,
    conflicts,
    autoModeBoundaries,
    fairnessSummary,
    summary,
    targetDimensions: parsedIntent?.targetDimensions,
    changedKeys: changes.map(c => c.settingKey),
    updatedSettings,
    confidence: parsedIntent?.confidence ?? 0.85,
    protectedDimensions: parsedIntent?.protectedDimensions || Array.from(protectedDimensionsSet),
    clauseBreakdown: parsedIntent?.clauseBreakdown,
    undoableBaseline: { ...(currentSettings as any), _undoStack: undefined }
  };
}

