/**
 * Persistence, Import/Export & Migration (Req 24).
 */
export function buildSaveData(
  gameState: any = {},
  gameSettings: GameSettingsState = DEFAULT_GAME_SETTINGS,
  smartSettingsProfile?: SmartSettingsProfile,
  metadataOverride?: any
): SaveGameData {
  const profile = smartSettingsProfile || gameSettings.smartSettingsProfile || createDefaultSmartSettingsProfile();
  return {
    version: '7.1',
    schemaVersion: '7.1',
    smartSettingsSchemaVersion: SMART_SETTINGS_SCHEMA_VERSION,
    timestamp: Date.now(),
    metadata: metadataOverride || { saveId: `save_${Date.now()}` },
    gameState: gameState || {},
    gameSettings: {
      ...gameSettings,
      smartSettingsProfile: profile
    },
    smartSettingsProfile: profile,
    autoModeGlobalSettings: gameSettings.autoModeSettings
  } as SaveGameData;
}

export function applyLoadedState(saveData: unknown): {
  gameState: any;
  gameSettings: GameSettingsState;
  smartSettingsProfile: SmartSettingsProfile;
  smartSettingsSchemaVersion: string;
} {
  if (!saveData || typeof saveData !== 'object') {
    const defaultSettings = { ...DEFAULT_GAME_SETTINGS };
    const defaultProfile = createDefaultSmartSettingsProfile();
    return {
      gameState: {},
      gameSettings: defaultSettings,
      smartSettingsProfile: defaultProfile,
      smartSettingsSchemaVersion: SMART_SETTINGS_SCHEMA_VERSION
    };
  }

  const raw = saveData as Record<string, any>;
  const rawProfile = raw.smartSettingsProfile || raw.gameSettings?.smartSettingsProfile;
  const sanitizedProfile = sanitizeSmartSettingsProfile(rawProfile);

  const rawSettings = raw.gameSettings || raw.settings || {};
  const gameSettings: GameSettingsState = {
    ...DEFAULT_GAME_SETTINGS,
    ...rawSettings,
    smartSettingsProfile: sanitizedProfile
  };

  const schemaVersion = typeof raw.smartSettingsSchemaVersion === 'string'
    ? raw.smartSettingsSchemaVersion
    : SMART_SETTINGS_SCHEMA_VERSION;

  return {
    gameState: raw.gameState || {},
    gameSettings,
    smartSettingsProfile: sanitizedProfile,
    smartSettingsSchemaVersion: schemaVersion
  };
}

let smartLedgerSeqCounter = 0;

/**
 * Activity Ledger Integration (Req 25).
 * Log smart settings actions into the activity ledger.
 */
export function appendSmartSettingsLedgerEvent(
  dispatchLedgerEvent: any,
  eventType: string,
  summary: string,
  payload: any = {}
): any {
  const planId = payload?.planId || payload?.plan?.planId || undefined;
  const transactionId = payload?.transactionId || payload?.transaction?.transactionId || undefined;
  const locks = payload?.locks || payload?.profile?.lockedCategories || payload?.lockedCategories || [];
  const turn = typeof payload?.turn === 'number' ? payload.turn : (payload?.profile?.lastAppliedTurn || 1);
  const day = typeof payload?.day === 'number' ? payload.day : (payload?.profile?.lastAppliedDay || 1);

  smartLedgerSeqCounter++;
  const event = {
    id: `smart_ledger_${Date.now()}_${smartLedgerSeqCounter}`,
    type: eventType,
    eventType,
    category: 'smart_settings',
    summary,
    planId,
    transactionId,
    locks,
    turn,
    day,
    timestamp: Date.now(),
    payload: {
      ...payload,
      planId,
      transactionId,
      locks,
      summary,
      turn,
      day
    }
  };

  if (typeof dispatchLedgerEvent === 'function') {
    dispatchLedgerEvent(event);
  }

  return event;
}

/**
 * Replay & Determinism Integration (Req 26).
 */
export interface SmartSettingsReplayEvent {
  type: 'smart_settings_event';
  eventAction: string;
  planId?: string;
  transactionId?: string;
  stateHashBefore: string;
  stateHashAfter: string;
  profile: SmartSettingsProfile;
  timestamp: number;
  turn: number;
  day: number;
}

export function appendSmartSettingsReplayEvent(
  dispatchReplayEvent: any,
  eventAction: string,
  planId?: string,
  transactionId?: string,
  stateHashBefore: string = '00000000',
  stateHashAfter: string = '00000000',
  profile?: SmartSettingsProfile,
  turn: number = 1,
  day: number = 1
): SmartSettingsReplayEvent {
  const eventProfile = profile || createDefaultSmartSettingsProfile();
  const event: SmartSettingsReplayEvent = {
    type: 'smart_settings_event',
    eventAction,
    planId,
    transactionId,
    stateHashBefore: stateHashBefore || '00000000',
    stateHashAfter: stateHashAfter || '00000000',
    profile: eventProfile,
    timestamp: Date.now(),
    turn,
    day
  };

  if (typeof dispatchReplayEvent === 'function') {
    dispatchReplayEvent(event);
  }

  return event;
}

