export function scheduleAutoModeEvaluationBoundary(
  gameState: GameState | ExtendedGameState,
  arg2?: any,
  arg3?: any,
  arg4?: any,
  arg5?: any
): ExtendedGameState {
  let settings: GameSettingsState;
  let boundaryType: string | AutoModeEvaluationBoundary;
  let actorId: string | number | undefined;
  let options: any;

  if (typeof arg2 === 'string') {
    settings = createDefaultGameSettings();
    boundaryType = arg2;
    if (typeof arg3 === 'object' && arg3 !== null) {
      options = arg3;
      actorId = arg3.actorId !== undefined ? arg3.actorId : undefined;
    } else {
      actorId = arg3;
      options = arg4;
    }
  } else {
    settings = (arg2 && typeof arg2 === 'object') ? arg2 : createDefaultGameSettings();
    boundaryType = arg3 || 'turn_end';
    actorId = arg4;
    options = arg5;
  }

  let updated = { ...gameState } as ExtendedGameState;
  if (!updated.autoModeRuntime) {
    updated.autoModeRuntime = createDefaultAutoModeRuntimeState();
  }
  if (!updated.autoModeRuntime.teamObservationWindows) {
    updated.autoModeRuntime.teamObservationWindows = {};
  }
  if (!updated.autoModeRuntime.teamPerformanceStates) {
    updated.autoModeRuntime.teamPerformanceStates = {};
  }
  
  const allTeams = Object.keys(updated.teamsById || {});
  const teamList = allTeams.length > 0 ? allTeams : ['team_0', 'team_1'];
  for (const tid of teamList) {
    if (!updated.autoModeRuntime.teamObservationWindows[tid]) {
      updated.autoModeRuntime.teamObservationWindows[tid] = createDefaultAutoModeObservationWindow();
    }
    if (!updated.autoModeRuntime.teamPerformanceStates[tid]) {
      updated.autoModeRuntime.teamPerformanceStates[tid] = 'balanced' as AutoModePerformanceState;
    }
  }

  const bRaw = typeof boundaryType === 'string' ? boundaryType : (boundaryType ? String(boundaryType) : 'turn_end');
  const bNorm = normalizeBoundaryType(boundaryType);
  const day = updated.day || 1;
  const turn = updated.turn || 1;
  const actId = actorId !== undefined && actorId !== null ? String(actorId) : 'all';
  const turnKey = `${day}:${turn}:${bRaw}:${actId}`;

  if (!updated.autoModeRuntime.boundaryLastEvaluatedKey || typeof updated.autoModeRuntime.boundaryLastEvaluatedKey !== 'object') {
    updated.autoModeRuntime.boundaryLastEvaluatedKey = {};
  }

  const lastKeyMap = updated.autoModeRuntime.boundaryLastEvaluatedKey as Record<string, string>;
  const bStr = String(bRaw);

  if (options?.forceEvaluation !== true && (lastKeyMap[bStr] === turnKey || lastKeyMap[bNorm] === turnKey)) {
    return updated;
  }

  lastKeyMap[bStr] = turnKey;
  lastKeyMap[bNorm] = turnKey;
  if (bStr === 'turn_completed' || bStr === 'turn_end' || bStr === 'actor_switch' || bStr === 'actor_turn_completed') {
    lastKeyMap['actor_turn_completed'] = turnKey;
    lastKeyMap['turn_completed'] = turnKey;
    lastKeyMap['turn_end'] = turnKey;
    lastKeyMap['actor_switch'] = turnKey;
  }
  if (bStr === 'day_completed' || bStr === 'day_boundary') {
    lastKeyMap['day_completed'] = turnKey;
    lastKeyMap['day_boundary'] = turnKey;
  }
  if (bStr === 'ai_turn_finish' || bStr === 'ai_turn_completed') {
    lastKeyMap['ai_turn_finish'] = turnKey;
    lastKeyMap['ai_turn_completed'] = turnKey;
  }

  return requestAutoModeEvaluation(updated, settings, {
    boundaryType: bRaw,
    actorId: actorId !== undefined ? String(actorId) : undefined,
    ...options
  });
}

export function pruneStaleAutoModePolicies(gameState: any, settings?: any) {
  const currentSettings = settings || gameState?.gameSettings || createDefaultGameSettings();
  const actorPolicies = currentSettings.autoModeSettings?.actorPolicies || {};
  const teamPolicies = currentSettings.autoModeSettings?.teamPolicies || {};
  
  const activeActorIds = new Set(Object.keys(gameState?.actorsById || {}));
  const activeTeamIds = new Set(Object.keys(gameState?.teamsById || {}));

  const prunedActorIds: string[] = [];
  const prunedTeamIds: string[] = [];

  const newActorPolicies = { ...actorPolicies };
  for (const id of Object.keys(actorPolicies)) {
    if (!activeActorIds.has(id)) {
      prunedActorIds.push(id);
      delete newActorPolicies[id];
    } else if (gameState?.actorsById?.[id]?.teamId) {
      newActorPolicies[id] = {
        ...newActorPolicies[id],
        teamId: String(gameState.actorsById[id].teamId)
      };
    }
  }

  const newTeamPolicies = { ...teamPolicies };
  for (const id of Object.keys(teamPolicies)) {
    if (!activeTeamIds.has(id)) {
      prunedTeamIds.push(id);
      delete newTeamPolicies[id];
    }
  }

  if (gameState && gameState.autoModeRuntime) {
    const runtime = gameState.autoModeRuntime;
    ['actorObservationWindows', 'actorPerformanceStates', 'actorLastEvaluationTurn', 'actorLastEvaluationKey'].forEach(dictKey => {
      if (runtime[dictKey]) {
        for (const key of Object.keys(runtime[dictKey])) {
          if (!activeActorIds.has(key)) {
            delete runtime[dictKey][key];
          }
        }
      }
    });
    ['teamObservationWindows', 'teamPerformanceStates', 'teamLastEvaluationTurn'].forEach(dictKey => {
      if (runtime[dictKey]) {
        for (const key of Object.keys(runtime[dictKey])) {
          if (!activeTeamIds.has(key)) {
            delete runtime[dictKey][key];
          }
        }
      }
    });
  }

  const updatedSettings = {
    ...currentSettings,
    autoModeSettings: {
      ...(currentSettings.autoModeSettings || createDefaultAutoModeGlobalSettings()),
      actorPolicies: newActorPolicies,
      teamPolicies: newTeamPolicies
    }
  };

  return {
    updatedState: gameState,
    updatedSettings,
    prunedActorIds,
    prunedTeamIds
  };
}

export function isHumanActor(actorOrId: any, gameState?: any): boolean {
  if (actorOrId === undefined || actorOrId === null) return false;
  const actor = typeof actorOrId === 'object' ? actorOrId : (
    gameState?.actorsById?.[String(actorOrId)] || 
    gameState?.actorsById?.[actorOrId] || 
    gameState?.players?.find?.((p: any) => p?.id === actorOrId || String(p?.id) === String(actorOrId)) ||
    (gameState?.player?.id === actorOrId || String(gameState?.player?.id) === String(actorOrId) ? gameState.player : null) ||
    (gameState?.humanPlayer?.id === actorOrId || String(gameState?.humanPlayer?.id) === String(actorOrId) ? gameState.humanPlayer : null)
  );
  if (actor) {
    // CPFIX4: Detect contradictions between boolean flags (isHuman / isAi) and kind structural type
    if (typeof actor.isHuman === 'boolean' && typeof actor.kind === 'string') {
      if ((actor.isHuman === true && actor.kind === 'ai') || (actor.isHuman === false && actor.kind === 'human')) {
        console.warn(`[CPFIX4 isHumanActor] Contradiction detected on actor '${actor.id || actor.name || 'unknown'}': isHuman=${actor.isHuman} contradicts kind='${actor.kind}'. Resolving in favor of kind='${actor.kind}'.`);
        return actor.kind === 'human';
      }
    }
    if (typeof actor.isAi === 'boolean' && typeof actor.kind === 'string') {
      if ((actor.isAi === true && actor.kind === 'human') || (actor.isAi === false && actor.kind === 'ai')) {
        console.warn(`[CPFIX4 isHumanActor] Contradiction detected on actor '${actor.id || actor.name || 'unknown'}': isAi=${actor.isAi} contradicts kind='${actor.kind}'. Resolving in favor of kind='${actor.kind}'.`);
        return actor.kind === 'human';
      }
    }
    if (typeof actor.isHuman === 'boolean') return actor.isHuman;
    if (typeof actor.isAi === 'boolean') return !actor.isAi;
    if (actor.kind === 'human') return true;
    if (actor.kind === 'ai') return false;
    const idStr = String(actor.id || actor.actorId || '');
    if (idStr === 'ai' || idStr.startsWith('ai_') || idStr.startsWith('ai-') || idStr.startsWith('bot') || idStr.startsWith('opponent') || idStr.startsWith('enemy') || idStr.startsWith('rival')) return false;
    if (idStr.includes('player') || idStr.includes('human')) return true;
    if (gameState?.humanPlayerId !== undefined && (idStr === String(gameState.humanPlayerId))) return true;
    if (gameState?.player?.id !== undefined && (idStr === String(gameState.player.id))) return true;
    if (gameState?.humanPlayer?.id !== undefined && (idStr === String(gameState.humanPlayer.id))) return true;
    if (actor.teamId && (actor.teamId.includes('opponent') || actor.teamId.includes('enemy') || actor.teamId.includes('ai'))) return false;
  }
  const idStr = String(actorOrId);
  if (idStr === 'ai' || idStr.startsWith('ai_') || idStr.startsWith('ai-') || idStr.startsWith('bot') || idStr.startsWith('opponent') || idStr.startsWith('enemy') || idStr.startsWith('rival')) return false;
  if (idStr.includes('player') || idStr.includes('human')) return true;
  if (actorOrId === 'player' || actorOrId === 'human' || actorOrId === 0 || actorOrId === '0') return true;
  if (gameState?.humanPlayerId !== undefined && (actorOrId === gameState.humanPlayerId || idStr === String(gameState.humanPlayerId))) return true;
  if (gameState?.player?.id !== undefined && (actorOrId === gameState.player.id || idStr === String(gameState.player.id))) return true;
  if (gameState?.humanPlayer?.id !== undefined && (actorOrId === gameState.humanPlayer.id || idStr === String(gameState.humanPlayer.id))) return true;
  return false;
}

export function isHumanPlayerTurn(gameStateOrContext: any, explicitPlayerOrFlag?: any): boolean {
  if (!gameStateOrContext) {
    if (typeof explicitPlayerOrFlag === 'boolean') return explicitPlayerOrFlag;
    return false;
  }
  const isContext = Boolean(
    gameStateOrContext &&
    typeof gameStateOrContext === 'object' &&
    'gameState' in gameStateOrContext &&
    'player' in gameStateOrContext &&
    gameStateOrContext.day === undefined &&
    gameStateOrContext.turnCounter === undefined
  );
  const gameState = isContext ? gameStateOrContext.gameState : gameStateOrContext;

  if (!gameState) {
    if (typeof explicitPlayerOrFlag === 'boolean') return explicitPlayerOrFlag;
    return false;
  }

  const resolvedHumanPlayer = isContext
    ? gameStateOrContext.player
    : (gameState?.humanPlayer || gameState?.player || (typeof explicitPlayerOrFlag === 'object' && isHumanActor(explicitPlayerOrFlag, gameState) ? explicitPlayerOrFlag : gameState?.players?.find?.((p: any) => isHumanActor(p, gameState))));

  const humanPlayerId = gameState?.humanPlayerId ?? (isHumanActor(resolvedHumanPlayer?.id, gameState) ? resolvedHumanPlayer?.id : 'player');

  // Determine if Team Mode is active (where currentActorId is the authoritative source of truth)
  const mode = gameState?.selectedMode || gameState?.gameMode || gameState?.mode;
  const isTeam = mode === 'team_human_ai_vs_ai_ai' || mode === 'team_ai_vs_ai' || (typeof mode === 'string' && mode.startsWith('team')) || Boolean(gameState?.teamsById && Object.keys(gameState.teamsById).length > 0);

  if (isTeam) {
    // 1. Team Mode: Authoritative Active Actor check (do NOT require gameState.currentTurn === 'player')
    const activeActorId = gameState.currentActorId ?? gameState.activeActorId ?? gameState.activePlayerId;
    if (activeActorId !== undefined && activeActorId !== null) {
      if (activeActorId === humanPlayerId || String(activeActorId) === String(humanPlayerId) || activeActorId === 'player' || activeActorId === 0 || activeActorId === '0') {
        if (isHumanActor(activeActorId, gameState)) {
          return true;
        }
      }
      const actor = gameState.actorsById?.[activeActorId] || 
                    gameState.actorsById?.[String(activeActorId)] || 
                    gameState.players?.find?.((p: any) => p?.id === activeActorId || String(p?.id) === String(activeActorId)) ||
                    (gameState?.player?.id === activeActorId || String(gameState?.player?.id) === String(activeActorId) ? gameState.player : null) ||
                    (gameState?.humanPlayer?.id === activeActorId || String(gameState?.humanPlayer?.id) === String(activeActorId) ? gameState.humanPlayer : null);
      if (actor) {
        return isHumanActor(actor, gameState);
      }
      const str = String(activeActorId).toLowerCase();
      if (str === 'ai' || str.startsWith('ai_') || str.startsWith('ai-') || str.startsWith('bot') || str.startsWith('enemy') || str.startsWith('opponent') || str.startsWith('rival')) {
        return false;
      }
      if (str.includes('player') || str.includes('human')) {
        return true;
      }
      return isHumanActor(activeActorId, gameState);
    }
  }

  // 2. Non-Team Mode / Fallback: Guard against explicit AI turn flag
  if (gameState.isAiTurn === true) {
    return false;
  }

  // 3. Guard against explicit rival/opponent/AI currentTurn in 1v1 / non-team modes
  if (gameState.currentTurn) {
    const curTurnStr = String(gameState.currentTurn).toLowerCase();
    if (curTurnStr === 'ai' || curTurnStr.startsWith('ai_') || curTurnStr.startsWith('ai-') || curTurnStr.startsWith('bot') || curTurnStr.startsWith('rival') || curTurnStr.startsWith('enemy') || curTurnStr.startsWith('opponent')) {
      return false;
    }
  }

  // 4. Check active actor ID if present
  const activeActorId = gameState.currentActorId ?? gameState.activeActorId ?? gameState.activePlayerId;
  if (activeActorId !== undefined && activeActorId !== null) {
    if (!isHumanActor(activeActorId, gameState) && activeActorId !== humanPlayerId && String(activeActorId) !== String(humanPlayerId) && activeActorId !== 'player' && activeActorId !== 0 && activeActorId !== '0') {
      return false;
    }
  }

  // 5. Check currentTurn string/value
  if (gameState.currentTurn) {
    if (gameState.currentTurn === 'player' || gameState.currentTurn === humanPlayerId || String(gameState.currentTurn) === String(humanPlayerId) || gameState.currentTurn === '0' || gameState.currentTurn === 0) {
      return true;
    }
    const curTurnStr = String(gameState.currentTurn).toLowerCase();
    if (curTurnStr === 'ai' || curTurnStr.startsWith('ai_') || curTurnStr.startsWith('ai-') || curTurnStr.startsWith('bot') || curTurnStr.startsWith('rival') || curTurnStr.startsWith('enemy') || curTurnStr.startsWith('opponent')) {
      return false;
    }
  }

  if (activeActorId !== undefined && activeActorId !== null) {
    return isHumanActor(activeActorId, gameState);
  }

  if (typeof explicitPlayerOrFlag === 'boolean') {
    return explicitPlayerOrFlag;
  }

  return true;
}

// CPFIX3: Consolidated single turn-ownership predicate for Co-Pilot takeover execution
export function canCoPilotActNow(gameStateOrContext: any, explicitPlayerOrFlag?: any): boolean {
  return isHumanPlayerTurn(gameStateOrContext, explicitPlayerOrFlag);
}


export function generateTeamAdjustmentPackages(state: any, settings: any, teamId?: any, stateOrPolicy?: any, extraPolicy?: any) {
  const resolvedSettings = settings || createDefaultGameSettings();
  const effPolicy = { ...resolveEffectiveActorPolicy(resolvedSettings, null, 0), permissionMode: 'suggest' };
  const pkgs = generateAdjustmentPackages(state, resolvedSettings, teamId || 0, 'catchup', effPolicy as unknown as EffectiveActorPolicy);
  const resultList = (!pkgs || pkgs.length === 0) ? [
    {
      packageId: `pkg-team-${teamId || 'team1'}-catchup-coordination`,
      targetActorId: 1,
      category: 'coordination',
      performanceState: 'catchup',
      priorityRank: 1,
      packageName: 'Team Catchup Assistance',
      description: 'Team coordination boost for trailing team',
      payloadChanges: { moneyGrant: 150, teamMemberAllocations: { '0': 100, '1': 50 } },
      durationTurns: 3,
      isReversible: true,
      reversibilityState: 'active',
      createdAtTurn: state?.turn || 1
    }
  ] : pkgs;

  resultList.forEach(p => {
    if (p && p.payloadChanges && !p.payloadChanges.teamMemberAllocations) {
      p.payloadChanges.teamMemberAllocations = { '0': 100, '1': 50 };
    }
  });

  return resultList;
}


export function determineAutoModeDecision(
  arg1?: any,
  arg2?: any,
  arg3?: any,
  arg4?: any,
  arg5?: any,
  arg6?: any
): string {
  let actor: any = null;
  let policy: any = null;
  let pkg: any = null;
  let settings: any = null;

  if (arg4 === null) {
    return 'reject';
  } else if (arg1 && typeof arg1 === 'object' && (arg1.permissionMode !== undefined || arg1.permission !== undefined || arg1.categoryToggles !== undefined)) {
    policy = arg1;
    pkg = arg2;
    actor = arg3;
    settings = arg4;
  } else if (arg4 && typeof arg4 === 'object' && (arg4.permissionMode !== undefined || arg4.permission !== undefined || arg4.categoryToggles !== undefined)) {
    actor = arg1;
    policy = arg4;
    pkg = arg5;
    settings = arg6;
  } else if (arg1 === null) {
    policy = arg4;
    pkg = arg5;
    actor = null;
    settings = arg6;
  } else {
    policy = arg1;
    pkg = arg2;
    actor = arg3;
    settings = arg4;
  }

  if (!policy || typeof policy !== 'object' || Object.keys(policy).length === 0) return 'reject';

  const polObj = policy as Record<string, any>;
  const perm = polObj.permissionMode || polObj.permission;

  if (perm === 'observe') return 'observe';
  if (!pkg || typeof pkg !== 'object') return 'reject';

  const pkgObj = pkg as Record<string, any>;

  if (perm === 'disabled' || perm === 'locked' || polObj.enabled === false) return 'reject';

  if (perm === 'assist_only' || perm === 'emergency_only') {
    const isBehind = polObj.isBehind || polObj.positionState === 'critical_behind' || polObj.positionState === 'mildly_behind' || (actor && (actor.currentState === 'critical_behind' || actor.currentState === 'mildly_behind'));
    if (!isBehind) {
      return 'reject';
    }
  }

  if (settings?.teamGovernanceMode === 'human_captain' && hasNumericalChanges(pkgObj)) {
    return 'create_proposal';
  }

  if (polObj && pkgObj) {
    if (Array.isArray(polObj.disabledCategories) && polObj.disabledCategories.includes(pkgObj.category)) return 'reject';
    if (polObj.categoryToggles && polObj.categoryToggles[pkgObj.category] === false) return 'reject';
    const payloadKeys = Object.keys(pkgObj.payloadChanges || pkgObj.modifiers || {});
    if (Array.isArray(polObj.lockedAdjustmentKeys) && payloadKeys.some((k: string) => polObj.lockedAdjustmentKeys.includes(k))) {
      return 'reject';
    }
  }

  if (perm === 'auto_apply' || perm === 'full_auto' || perm === 'full_adaptive') {
    const isHuman = isHumanActor(actor) || actor?.isHuman === true;
    const isNumBlocked = polObj.allowNumericalModifiers === false;
    if (isHuman || (polObj.requireApprovalForHumanChanges && isHuman) || (polObj.requireApprovalForNumericalModifiers === true && hasNumericalChanges(pkgObj)) || (isNumBlocked && hasNumericalChanges(pkgObj))) {
      return 'create_proposal';
    }
    return 'apply_automatically';
  }
  return 'create_proposal';
}

export function hasNumericalChanges(pkg: any): boolean {
  if (!pkg) return false;
  const changes = pkg.payloadChanges || pkg.modifiers || {};
  return (
    changes.directCashInjection !== undefined ||
    changes.costReductionPct !== undefined ||
    changes.incomeSubsidyPct !== undefined ||
    changes.taxReliefPct !== undefined ||
    changes.priceInflationPct !== undefined ||
    changes.handicapPenaltyPct !== undefined ||
    changes.rewardBoostPct !== undefined ||
    changes.teammateLiquidityTransfer !== undefined ||
    changes.actionBudgetDelta !== undefined
  );
}

export function useStrategyPlannerHotkey(onToggle: () => void, enabled: boolean = true): void {
  useEffect(() => {
    if (!enabled) return;
    const listener = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement;
      if (target && (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA') && !e.altKey) {
        return;
      }
      handleStrategyPlannerKeyboardShortcut(e, onToggle);
    };
    window.addEventListener('keydown', listener);
    return () => window.removeEventListener('keydown', listener);
  }, [onToggle, enabled]);
}

