        planId: testPlan.id,
        currentTurnNumber: 5,
        currentActionIndex: 0,
        completedActionIds: [],
        failedActionIds: [],
        actualCashAchieved: 5000,
        actualNetWorthAchieved: 12000,
        completionPercentage: 10,
        isOnTrack: false,
        lastEvaluatedTurn: 5,
