interface NormalizedEventPayload {
  actionType?: string;
  targetRegion?: string;
  item?: string;
  price?: number;
  investmentAmount?: number;
  targetActorId?: string;
  decisionId?: string;
  overrideCode?: string;
  [key: string]: unknown;
}

function extractCanonicalActionPayload(payload: Record<string, unknown> | any, evRoot?: any): NormalizedEventPayload {
  const p = payload || {};
  const rawType = String(
    p.actionType || p.type || p.chosenAction || p.action ||
    evRoot?.actionType || evRoot?.type || evRoot?.chosenAction || evRoot?.action || ''
  ).toLowerCase();
  const actionType = rawType || undefined;
  
  const targetRegion = (p.targetRegion || p.destination || p.regionCode || p.region) as string | undefined;
  const item = (p.item || p.output || p.recipeId || p.equipment || p.resource || p.itemId) as string | undefined;
  
  const price = typeof p.price === 'number' ? p.price : (typeof p.cost === 'number' ? p.cost : (typeof p.wage === 'number' ? p.wage : (typeof p.unitPrice === 'number' ? p.unitPrice : (typeof p.amount === 'number' ? p.amount : undefined))));
  const investmentAmount = typeof p.investmentAmount === 'number' ? p.investmentAmount : (typeof p.amount === 'number' ? p.amount : price);
  const targetActorId = (p.targetActorId || p.targetId) as string | undefined;
  const decisionId = (p.decisionId || evRoot?.decisionId) as string | undefined;
  const overrideCode = (p.overrideCode || evRoot?.overrideCode) as string | undefined;

  return {
    ...p,
    actionType,
    targetRegion,
    item,
    price,
    investmentAmount,
    targetActorId,
    decisionId,
    overrideCode
  };
}
