// Deterministic, dependency-free FNV-1a-style hash — genuinely new (no checksum/hash utility existed
// anywhere in the file before this). Used only to detect accidental corruption/truncation of an
// exported replay file, never as a security mechanism.
export const computeReplayChecksum = (file: Omit<ReplayFile, 'checksum'>): string => {
  const serialized = JSON.stringify({
    schemaVersion: file.schemaVersion,
    matchId: file.matchId,
    events: file.events,
    checkpoints: file.checkpoints,
    finalResult: file.finalResult,
    truncated: file.truncated,
    truncatedAtSequence: file.truncatedAtSequence,
    randomDraws: file.randomDraws || [],
    bookmarks: file.bookmarks || [],
    branches: file.branches || []
  });
  let hash = 0x811c9dc5;
  for (let i = 0; i < serialized.length; i += 1) {
    hash ^= serialized.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
};

// RP2's own migrator — deliberately NOT a reuse of validateSaveData, since a replay file has a
// different lifecycle contract (append-only history, never re-hydrated into live game state this
// phase) and needs real version-branching. Only schemaVersion 1 exists today; a future RP phase adds
// real migration logic here rather than replacing this function.
const emptyReplayCompatibility = (): ReplayCompatibilityReport => ({
  status: 'unsupported',
  warnings: [],
  migrationsApplied: [],
  unavailableFeatures: [],
  canRecordedPlayback: false,
  canDeterministicReexecute: false,
  canBranch: false,
  canCompare: false,
  integrityStatus: 'Unsupported'
});

const migrateReplaySchema1To2 = (file: ReplayFile): ReplayFile => ({
  ...file,
  schemaVersion: 2,
  gameVersion: file.gameVersion || 'unknown',
  createdAt: typeof file.createdAt === 'number' ? file.createdAt : Date.now()
});

const migrateReplaySchema2To3 = (file: ReplayFile): ReplayFile => ({
  ...file,
  schemaVersion: 3,
  checkpoints: (file.checkpoints || []).map(cp => ({
    ...cp,
    kind: cp.kind || (cp.label === 'Match start' ? 'match_start' : cp.label === 'Match end' ? 'match_end' : 'day')
  }))
});

const migrateReplaySchema3To4 = (file: ReplayFile): ReplayFile => ({
  ...file,
  schemaVersion: 4,
  randomDraws: Array.isArray(file.randomDraws) ? file.randomDraws : [],
  bookmarks: Array.isArray(file.bookmarks) ? file.bookmarks : [],
  branches: Array.isArray(file.branches) ? file.branches : [],
  turningPoints: Array.isArray(file.turningPoints) ? file.turningPoints : [],
  chapters: Array.isArray(file.chapters) ? file.chapters : []
});

export function migrateReplayFileWithReport(raw: unknown): ReplayMigrationResult {
  const compatibility = emptyReplayCompatibility();
  if (!raw || typeof raw !== 'object') {
    compatibility.warnings.push('Replay payload is not an object.');
    compatibility.integrityStatus = 'Unsupported';
    return { file: null, compatibility };
  }
  const data = raw as Partial<ReplayFile> & { schemaVersion?: unknown };
  const sourceSchema = typeof data.schemaVersion === 'number' ? data.schemaVersion : 0;
  if (sourceSchema < 1) {
    compatibility.warnings.push('Missing or invalid schemaVersion.');
    return { file: null, compatibility };
  }
  if (sourceSchema > REPLAY_SCHEMA_VERSION) {
    compatibility.warnings.push(`Unsupported future schema ${sourceSchema} (current ${REPLAY_SCHEMA_VERSION}).`);
    compatibility.unavailableFeatures.push('recorded_playback', 'deterministic_reexecution', 'branching');
    return { file: null, compatibility };
  }
  if (typeof data.matchId !== 'string' || !Array.isArray(data.events) || !Array.isArray(data.checkpoints)) {
    compatibility.warnings.push('Replay is missing matchId, events, or checkpoints.');
    compatibility.integrityStatus = 'Corrupted';
    return { file: null, compatibility };
  }
  if (!data.initialConfig || typeof data.initialConfig !== 'object') {
    compatibility.warnings.push('Missing initialConfig — recorded playback may be incomplete.');
    compatibility.unavailableFeatures.push('deterministic_reexecution', 'branching');
  }

  const seenSequences = new Set<number>();
  const seenIds = new Set<string>();
  const dedupedEvents: ReplayEvent[] = [];
  let duplicateSequences = 0;
  let duplicateIds = 0;
  for (const ev of data.events) {
    if (!ev || typeof (ev as ReplayEvent).sequence !== 'number') continue;
    const typed = ev as ReplayEvent;
    if (seenSequences.has(typed.sequence)) {
      duplicateSequences += 1;
      continue;
    }
    if (typed.id && seenIds.has(typed.id)) {
      duplicateIds += 1;
    }
    if (typed.id) seenIds.add(typed.id);
    seenSequences.add(typed.sequence);
    dedupedEvents.push(typed);
  }
  if (duplicateSequences > 0) compatibility.warnings.push(`Dropped ${duplicateSequences} duplicate event sequence(s).`);
  if (duplicateIds > 0) compatibility.warnings.push(`Detected ${duplicateIds} duplicate event id(s).`);

  const originalCandidate: Omit<ReplayFile, 'checksum'> = {
    schemaVersion: sourceSchema,
    gameVersion: typeof data.gameVersion === 'string' ? data.gameVersion : 'unknown',
    matchId: data.matchId,
    createdAt: typeof data.createdAt === 'number' ? data.createdAt : Date.now(),
    initialConfig: data.initialConfig as ReplayInitialConfigSnapshot,
    events: dedupedEvents,
    checkpoints: data.checkpoints as ReplayCheckpoint[],
    finalResult: (data.finalResult as ReplayFinalResult) || null,
    truncated: data.truncated,
    truncatedAtSequence: data.truncatedAtSequence,
    randomDraws: Array.isArray(data.randomDraws) ? data.randomDraws : [],
    bookmarks: Array.isArray(data.bookmarks) ? data.bookmarks : [],
    branches: Array.isArray(data.branches) ? data.branches : []
  };
  const checksumCheck = verifyReplayChecksum({ ...originalCandidate, checksum: typeof data.checksum === 'string' ? data.checksum : undefined });
  const checksumOk = typeof data.checksum === 'string' && checksumCheck.ok;
  if (!checksumOk) {
    compatibility.warnings.push(typeof data.checksum === 'string'
      ? 'Checksum mismatch — file may be truncated or edited.'
      : 'Checksum missing — integrity cannot be verified.');
    compatibility.integrityStatus = 'Corrupted';
    compatibility.unavailableFeatures.push('deterministic_reexecution');
  }

  let migrated: ReplayFile = {
    ...originalCandidate,
    checksum: checksumCheck.expected,
    branchedFromMatchId: typeof data.branchedFromMatchId === 'string' ? data.branchedFromMatchId : undefined,
    randomDraws: Array.isArray(data.randomDraws) ? data.randomDraws : [],
    bookmarks: Array.isArray(data.bookmarks) ? data.bookmarks : [],
    branches: Array.isArray(data.branches) ? data.branches : [],
    turningPoints: Array.isArray(data.turningPoints) ? data.turningPoints : [],
    chapters: Array.isArray(data.chapters) ? data.chapters : [],
    policy: data.policy
  };
  if (sourceSchema < 2) {
    migrated = migrateReplaySchema1To2(migrated);
    compatibility.migrationsApplied.push('schema1_to_schema2');
  }
  if ((migrated.schemaVersion || sourceSchema) < 3) {
    migrated = migrateReplaySchema2To3(migrated);
    compatibility.migrationsApplied.push('schema2_to_schema3');
  }
  if ((migrated.schemaVersion || sourceSchema) < 4) {
    migrated = migrateReplaySchema3To4(migrated);
    compatibility.migrationsApplied.push('schema3_to_schema4');
  }
  migrated.schemaVersion = REPLAY_SCHEMA_VERSION;
  migrated.migrationsApplied = compatibility.migrationsApplied;
  const migratedChecksum = computeReplayChecksum(migrated);
  migrated.checksum = migratedChecksum;

  const hasSnapshots = migrated.checkpoints.some(cp => Boolean(cp.fullStateSnapshot));
  const hasInitialConfig = Boolean(migrated.initialConfig && migrated.initialConfig.actorsById);
  compatibility.canRecordedPlayback = migrated.events.length > 0 || hasSnapshots;
  compatibility.canDeterministicReexecute = checksumOk && hasInitialConfig && !migrated.truncated;
  compatibility.canBranch = hasSnapshots || hasInitialConfig;
  compatibility.canCompare = migrated.events.length > 0;
  if (compatibility.migrationsApplied.length > 0) {
    compatibility.status = checksumOk ? 'requires_migration' : 'partial';
  } else if (!checksumOk) {
    compatibility.status = 'partial';
  } else if (compatibility.warnings.length > 0) {
    compatibility.status = 'compatible';
  } else {
    compatibility.status = 'exact';
  }
  if (compatibility.integrityStatus !== 'Corrupted' && compatibility.integrityStatus !== 'Unsupported') {
    compatibility.integrityStatus = migrated.truncated
      ? 'Warning'
      : compatibility.status === 'exact'
        ? 'Healthy'
        : compatibility.status === 'partial'
          ? 'Partially Compatible'
          : 'Warning';
  }
  if (migrated.truncated) {
    compatibility.warnings.push(`Replay is truncated at sequence ${migrated.truncatedAtSequence ?? 'unknown'}.`);
    compatibility.canDeterministicReexecute = false;
  }
  if (!hasSnapshots) {
    compatibility.unavailableFeatures.push('fast_checkpoint_seek');
    compatibility.warnings.push('No full-state checkpoints — seeking falls back to event roll-forward.');
  }
  return { file: migrated, compatibility };
}

const migrateReplayFile = (raw: unknown): ReplayFile | null => {
  return migrateReplayFileWithReport(raw).file;
};

export interface ReplayIntegrityDashboard {
  schemaVersion: number;
  gameVersion: string;
  checksumStatus: 'valid' | 'missing' | 'mismatch' | 'recomputed';
  eventCount: number;
  checkpointCount: number;
  truncated: boolean;
  missingSequences: number[];
  duplicateSequences: number[];
  invalidEvents: number;
  unsupportedEventTypes: string[];
  rngDrawCount: number;
  stateHashCoverage: number;
  firstDivergence?: { day: number; turn: number; sequence: number; explanation: string };
  compatibility: ReplayCompatibilityReport;
  checkpointEntries: ReplayIntegrityReportEntry[];
}

const classifyReplayIntegrityDashboard = (file: ReplayFile, compatibility?: ReplayCompatibilityReport): ReplayIntegrityDashboard => {
  const sequences = file.events.map(ev => ev.sequence).sort((a, b) => a - b);
  const seen = new Set<number>();
  const duplicateSequences: number[] = [];
  sequences.forEach(seq => {
    if (seen.has(seq)) duplicateSequences.push(seq);
    seen.add(seq);
  });
  const missingSequences: number[] = [];
  if (sequences.length > 0) {
    const minSeq = sequences[0];
    const maxSeq = sequences[sequences.length - 1];
    for (let s = minSeq; s <= maxSeq; s++) {
      if (!seen.has(s)) missingSequences.push(s);
    }
  }
  const hashed = file.events.filter(ev => ev.stateHash || ev.stateHashAfter).length;
  const unknownCats = Array.from(new Set(file.events
    .map(ev => ev.category)
    .filter(cat => typeof cat !== 'string' || !cat)));
  return {
    schemaVersion: file.schemaVersion || REPLAY_SCHEMA_VERSION,
    gameVersion: file.gameVersion || 'unknown',
    checksumStatus: file.checksum ? 'recomputed' : 'missing',
    eventCount: file.events.length,
    checkpointCount: file.checkpoints.length,
    truncated: Boolean(file.truncated),
    missingSequences: missingSequences.slice(0, 50),
    duplicateSequences,
    invalidEvents: file.events.filter(ev => typeof ev.sequence !== 'number' || !ev.id).length,
    unsupportedEventTypes: unknownCats.map(String),
    rngDrawCount: file.randomDraws?.length || 0,
    stateHashCoverage: file.events.length > 0 ? hashed / file.events.length : 0,
    compatibility: compatibility || emptyReplayCompatibility(),
    checkpointEntries: classifyReplayFileIntegrity(file)
  };
};

const readActorMoney = (actor: IsolatedReplayActorView | ActorState | Record<string, unknown> | undefined): number => {
  if (!actor || typeof actor !== 'object') return 0;
  const rec = actor as Record<string, unknown>;
  return typeof rec.money === 'number' ? rec.money : 0;
};

const readActorRegion = (actor: IsolatedReplayActorView | ActorState | Record<string, unknown> | undefined): string => {
  if (!actor || typeof actor !== 'object') return '';
  const rec = actor as Record<string, unknown>;
  return String(rec.region || rec.currentRegion || '');
};

const readActorInventory = (actor: IsolatedReplayActorView | ActorState | Record<string, unknown> | undefined): Record<string, number> => {
  if (!actor || typeof actor !== 'object') return {};
  const rec = actor as Record<string, unknown>;
  const inv = rec.inventory;
  if (!inv || typeof inv !== 'object') return {};
  return { ...(inv as Record<string, number>) };
};

export function computeReplayStateDelta(
  sequence: number,
  before: IsolatedReplayRuntime | Record<string, unknown> | null | undefined,
  after: IsolatedReplayRuntime | Record<string, unknown> | null | undefined
): ReplayStateDelta {
  const delta: ReplayStateDelta = { sequence, actorChanges: {}, teamChanges: {}, worldChanges: {}, changedPaths: [] };
  if (!before || !after) return delta;
  const beforeActors = ((before as IsolatedReplayRuntime).actors || (before as Record<string, unknown>).actorsById || {}) as Record<string, IsolatedReplayActorView>;
  const afterActors = ((after as IsolatedReplayRuntime).actors || (after as Record<string, unknown>).actorsById || {}) as Record<string, IsolatedReplayActorView>;
  const actorIds = new Set([...Object.keys(beforeActors), ...Object.keys(afterActors)]);
  actorIds.forEach(id => {
    const b = beforeActors[id];
    const a = afterActors[id];
    const moneyDelta = readActorMoney(a) - readActorMoney(b);
    const regionBefore = readActorRegion(b);
    const regionAfter = readActorRegion(a);
    const invBefore = readActorInventory(b);
    const invAfter = readActorInventory(a);
    const inventoryAdded = Object.keys(invAfter).filter(k => (invAfter[k] || 0) > (invBefore[k] || 0));
    const inventoryRemoved = Object.keys(invBefore).filter(k => (invAfter[k] || 0) < (invBefore[k] || 0));
    const xpDelta = ((a as IsolatedReplayActorView)?.xp || 0) - ((b as IsolatedReplayActorView)?.xp || 0);
    const actionsDelta = ((a as IsolatedReplayActorView)?.actionsUsedThisTurn || 0) - ((b as IsolatedReplayActorView)?.actionsUsedThisTurn || 0);
    const netWorthDelta = ((a as IsolatedReplayActorView)?.netWorth || 0) - ((b as IsolatedReplayActorView)?.netWorth || 0);
    if (moneyDelta || regionBefore !== regionAfter || inventoryAdded.length || inventoryRemoved.length || xpDelta || actionsDelta || netWorthDelta) {
      delta.actorChanges[id] = {
        moneyDelta: moneyDelta || undefined,
        regionBefore: regionBefore !== regionAfter ? regionBefore : undefined,
        regionAfter: regionBefore !== regionAfter ? regionAfter : undefined,
        inventoryAdded: inventoryAdded.length ? inventoryAdded : undefined,
        inventoryRemoved: inventoryRemoved.length ? inventoryRemoved : undefined,
        xpDelta: xpDelta || undefined,
        actionsDelta: actionsDelta || undefined,
        netWorthDelta: netWorthDelta || undefined
      };
      if (moneyDelta) delta.changedPaths.push(`actors.${id}.money`);
      if (regionBefore !== regionAfter) delta.changedPaths.push(`actors.${id}.region`);
      if (inventoryAdded.length || inventoryRemoved.length) delta.changedPaths.push(`actors.${id}.inventory`);
      if (netWorthDelta) delta.changedPaths.push(`actors.${id}.netWorth`);
    }
  });
  const beforeTeams = ((before as IsolatedReplayRuntime).teams || (before as Record<string, unknown>).teamsById || {}) as Record<string, IsolatedReplayTeamView>;
  const afterTeams = ((after as IsolatedReplayRuntime).teams || (after as Record<string, unknown>).teamsById || {}) as Record<string, IsolatedReplayTeamView>;
  const teamIds = new Set([...Object.keys(beforeTeams), ...Object.keys(afterTeams)]);
  teamIds.forEach(id => {
    const b = beforeTeams[id];
    const a = afterTeams[id];
    const moneyDelta = (a?.money || 0) - (b?.money || 0);
    const treasuryDelta = (a?.treasuryBalance || 0) - (b?.treasuryBalance || 0);
    const scoreDelta = (a?.netWorth || 0) - (b?.netWorth || 0);
    if (moneyDelta || treasuryDelta || scoreDelta) {
      if (!delta.teamChanges) delta.teamChanges = {};
      delta.teamChanges[id] = {
        moneyDelta: moneyDelta || undefined,
        treasuryDelta: treasuryDelta || undefined,
        scoreDelta: scoreDelta || undefined
      };
      if (moneyDelta) delta.changedPaths.push(`teams.${id}.money`);
      if (treasuryDelta) delta.changedPaths.push(`teams.${id}.treasury`);
      if (scoreDelta) delta.changedPaths.push(`teams.${id}.netWorth`);
    }
  });
  const dayBefore = (before as IsolatedReplayRuntime).day;
  const dayAfter = (after as IsolatedReplayRuntime).day;
  const turnBefore = (before as IsolatedReplayRuntime).turn;
  const turnAfter = (after as IsolatedReplayRuntime).turn;
  const weatherBefore = (before as IsolatedReplayRuntime).weather;
  const weatherAfter = (after as IsolatedReplayRuntime).weather;
  const marketBefore = (before as IsolatedReplayRuntime).marketTrend;
  const marketAfter = (after as IsolatedReplayRuntime).marketTrend;
  if (dayBefore !== dayAfter || turnBefore !== turnAfter || weatherBefore !== weatherAfter || marketBefore !== marketAfter) {
    delta.worldChanges = {
      dayBefore: dayBefore !== dayAfter ? dayBefore : undefined,
      dayAfter: dayBefore !== dayAfter ? dayAfter : undefined,
      turnBefore: turnBefore !== turnAfter ? turnBefore : undefined,
      turnAfter: turnBefore !== turnAfter ? turnAfter : undefined,
      weatherBefore: weatherBefore !== weatherAfter ? weatherBefore : undefined,
      weatherAfter: weatherBefore !== weatherAfter ? weatherAfter : undefined,
      marketTrendBefore: marketBefore !== marketAfter ? marketBefore : undefined,
      marketTrendAfter: marketBefore !== marketAfter ? marketAfter : undefined
    };
    if (dayBefore !== dayAfter) delta.changedPaths.push('world.day');
    if (turnBefore !== turnAfter) delta.changedPaths.push('world.turn');
    if (weatherBefore !== weatherAfter) delta.changedPaths.push('world.weather');
    if (marketBefore !== marketAfter) delta.changedPaths.push('world.market');
  }
  return delta;
}

export function extractIsolatedRuntimeFromSnapshot(
  snapshot: SaveGameData | CanonicalGameState | Record<string, unknown> | null | undefined,
  sequence = 0
): IsolatedReplayRuntime {
  const snap = (snapshot || {}) as Record<string, unknown>;
  const gameState = (snap.gameState && typeof snap.gameState === 'object' ? snap.gameState : snap) as Record<string, unknown>;
  const rawActors = (snap.actorsById || gameState.actorsById || {}) as Record<string, Record<string, unknown>>;
  const player = (snap.player || gameState.player || rawActors.player) as Record<string, unknown> | undefined;
  const aiPlayer = (snap.aiPlayer || gameState.aiPlayer || rawActors.ai) as Record<string, unknown> | undefined;
  const actors: Record<string, IsolatedReplayActorView> = {};
  Object.keys(rawActors).forEach(id => {
    const a = rawActors[id] || {};
    actors[id] = {
      id,
      name: typeof a.name === 'string' ? a.name : (typeof (a.character as Record<string, unknown> | undefined)?.name === 'string' ? String((a.character as Record<string, unknown>).name) : id),
      money: typeof a.money === 'number' ? a.money : 0,
      netWorth: typeof a.netWorth === 'number' ? a.netWorth : (typeof a.money === 'number' ? a.money : 0),
      region: String(a.region || a.currentRegion || ''),
      inventory: a.inventory && typeof a.inventory === 'object' ? { ...(a.inventory as Record<string, number>) } : {},
      actionsUsedThisTurn: typeof a.actionsUsedThisTurn === 'number' ? a.actionsUsedThisTurn : 0,
      xp: typeof a.xp === 'number' ? a.xp : (typeof a.experience === 'number' ? a.experience : 0),
      kind: typeof a.kind === 'string' ? a.kind : undefined,
      teamId: typeof a.teamId === 'string' ? a.teamId : undefined
    };
  });
  if (player && !actors.player) {
    actors.player = {
      id: 'player',
      name: typeof player.name === 'string' ? player.name : 'Player',
      money: typeof player.money === 'number' ? player.money : 0,
      netWorth: typeof player.netWorth === 'number' ? player.netWorth : 0,
      region: String(player.region || player.currentRegion || 'NSW'),
      inventory: player.inventory && typeof player.inventory === 'object' ? { ...(player.inventory as Record<string, number>) } : {},
      actionsUsedThisTurn: typeof player.actionsUsedThisTurn === 'number' ? player.actionsUsedThisTurn : 0,
      teamId: typeof player.teamId === 'string' ? player.teamId : 'team_player'
    };
  }
  if (aiPlayer && !actors.ai) {
    actors.ai = {
      id: 'ai',
      name: typeof aiPlayer.name === 'string' ? aiPlayer.name : 'AI',
      money: typeof aiPlayer.money === 'number' ? aiPlayer.money : 0,
      netWorth: typeof aiPlayer.netWorth === 'number' ? aiPlayer.netWorth : 0,
      region: String(aiPlayer.region || aiPlayer.currentRegion || 'VIC'),
      inventory: aiPlayer.inventory && typeof aiPlayer.inventory === 'object' ? { ...(aiPlayer.inventory as Record<string, number>) } : {},
      teamId: typeof aiPlayer.teamId === 'string' ? aiPlayer.teamId : 'team_ai'
    };
  }
  const rawTeams = (snap.teamsById || gameState.teamsById || gameState.teamStateMap || {}) as Record<string, Record<string, unknown>>;
  const teams: Record<string, IsolatedReplayTeamView> = {};
  Object.keys(rawTeams).forEach(id => {
    const t = rawTeams[id] || {};
    teams[id] = {
      id,
      name: typeof t.name === 'string' ? t.name : id,
      money: typeof t.money === 'number' ? t.money : 0,
      netWorth: typeof t.netWorth === 'number' ? t.netWorth : 0,
      treasuryBalance: typeof t.treasuryBalance === 'number' ? t.treasuryBalance : 0,
      controlledRegions: Array.isArray(t.controlledRegions) ? [...(t.controlledRegions as string[])] : []
    };
  });
  const rawRegions = (gameState.regions || gameState.territoryStateMap || {}) as Record<string, Record<string, unknown>>;
  const regions: Record<string, { ownerId?: string; developmentLevel?: number; standing?: number }> = {};
  Object.keys(rawRegions).forEach(id => {
    const r = rawRegions[id] || {};
    regions[id] = {
      ownerId: typeof r.ownerId === 'string' ? r.ownerId : (typeof r.controllerId === 'string' ? r.controllerId : undefined),
      developmentLevel: typeof r.developmentLevel === 'number' ? r.developmentLevel : undefined,
      standing: typeof r.standing === 'number' ? r.standing : (typeof r.regionalStanding === 'number' ? r.regionalStanding : undefined)
    };
  });
  const namedList = (value: unknown): string[] => {
    if (!Array.isArray(value)) return [];
    return value.map(item => {
      if (typeof item === 'string') return item;
      if (item && typeof item === 'object') {
        const rec = item as Record<string, unknown>;
        return String(rec.name || rec.title || rec.id || rec.contractId || rec.projectId || '');
      }
      return '';
    }).filter(Boolean).slice(0, 8);
  };
  const contractNames = namedList(gameState.completedContracts || gameState.contracts || gameState.activeContracts);
  const infrastructureNames = namedList(gameState.completedInfrastructure || gameState.infrastructure || gameState.infrastructureProjects);
  const expeditionNames = namedList(gameState.activeExpeditions || gameState.expeditions || gameState.completedExpeditions);
  const stabilityState = (gameState.publicStabilityState && typeof gameState.publicStabilityState === 'object'
    ? gameState.publicStabilityState as Record<string, unknown>
    : null);
  const publicStability = typeof stabilityState?.nationalStability === 'number'
    ? stabilityState.nationalStability
    : (typeof gameState.publicStability === 'number' ? gameState.publicStability : undefined);
  const currentTurn = String(gameState.currentTurn || gameState.activePlayer || '');
  const aiStatus = typeof gameState.aiStatus === 'string'
    ? gameState.aiStatus
    : (currentTurn === 'ai' ? 'acting' : (currentTurn ? 'idle' : undefined));
  const campaignStatus = typeof gameState.campaignStatus === 'string'
    ? gameState.campaignStatus
    : (gameState.campaignModeEnabled ? 'campaign active' : (gameState.selectedMode === 'scenario' ? 'scenario' : undefined));
  const victory = gameState.scenarioOutcome && typeof gameState.scenarioOutcome === 'object'
    ? gameState.scenarioOutcome as Record<string, unknown>
    : null;
  const victoryProgress = typeof gameState.victoryProgress === 'string'
    ? gameState.victoryProgress
    : (victory ? String(victory.reason || (victory.isVictory ? 'victory' : 'defeat')) : undefined);
  const day = typeof gameState.day === 'number' ? gameState.day : 1;
  const turn = typeof gameState.turnCounter === 'number' ? gameState.turnCounter : (typeof gameState.turn === 'number' ? gameState.turn : 1);
  const runtime: IsolatedReplayRuntime = {
    day,
    turn,
    weather: typeof gameState.weather === 'string' ? gameState.weather : undefined,
    marketTrend: typeof gameState.marketTrend === 'string' ? gameState.marketTrend : undefined,
    season: typeof gameState.season === 'string' ? gameState.season : undefined,
    actors,
    teams,
    regions,
    activeEvents: Array.isArray(gameState.activeEvents) ? [...(gameState.activeEvents as unknown[])] : [],
    stateHash: computeCanonicalStateHash({ day, turnCounter: turn, actorsById: actors, teamsById: teams, regions, activeEvents: gameState.activeEvents }),
    rngRegistryState: (snap.rngRegistryState as Record<string, RngStreamState> | undefined),
    deterministicCounters: snap.deterministicCounters as DeterministicCounters | undefined,
    fullSnapshot: snapshot as SaveGameData | undefined,
    sequence,
    contractsCompleted: contractNames.length || undefined,
    infrastructureCompleted: infrastructureNames.length || undefined,
    expeditionsActive: expeditionNames.length || undefined,
    contractNames,
    infrastructureNames,
    expeditionNames,
    publicStability,
    aiStatus,
    campaignStatus,
    victoryProgress
  };
  return runtime;
}

export function hydrateIsolatedReplayRuntimeFromConfig(config: ReplayInitialConfigSnapshot | undefined, sequence = 0): IsolatedReplayRuntime {
  if (!config) {
    return {
      day: 1,
      turn: 1,
      actors: {},
      teams: {},
      regions: {},
      activeEvents: [],
      stateHash: '00000000',
      sequence
    };
  }
  return extractIsolatedRuntimeFromSnapshot({
    actorsById: config.actorsById,
    teamsById: config.teamsById,
    gameState: { day: 1, turnCounter: 1, selectedMode: config.selectedMode },
    rngRegistryState: config.rngRegistryState,
    deterministicCounters: config.deterministicCounters
  } as unknown as SaveGameData, sequence);
}

export function applyReplayStateDeltaToRuntime(runtime: IsolatedReplayRuntime, delta: ReplayStateDelta | undefined): IsolatedReplayRuntime {
  if (!delta) return runtime;
  const next: IsolatedReplayRuntime = {
    ...runtime,
    actors: { ...runtime.actors },
    teams: { ...runtime.teams },
    regions: { ...runtime.regions },
    sequence: delta.sequence
  };
  Object.keys(delta.actorChanges || {}).forEach(id => {
    const change = delta.actorChanges[id];
    const prev = next.actors[id] || { id, money: 0, netWorth: 0, region: '', inventory: {} };
    const inventory = { ...prev.inventory };
    (change.inventoryAdded || []).forEach(item => { inventory[item] = (inventory[item] || 0) + 1; });
    (change.inventoryRemoved || []).forEach(item => { inventory[item] = Math.max(0, (inventory[item] || 0) - 1); });
    next.actors[id] = {
      ...prev,
      money: prev.money + (change.moneyDelta || 0),
      netWorth: prev.netWorth + (change.netWorthDelta || 0),
      region: change.regionAfter || prev.region,
      inventory,
      xp: (prev.xp || 0) + (change.xpDelta || 0),
      actionsUsedThisTurn: (prev.actionsUsedThisTurn || 0) + (change.actionsDelta || 0)
    };
  });
  Object.keys(delta.teamChanges || {}).forEach(id => {
    const change = delta.teamChanges![id];
    const prev = next.teams[id] || { id, money: 0, netWorth: 0 };
    next.teams[id] = {
      ...prev,
      money: prev.money + (change.moneyDelta || 0),
      netWorth: prev.netWorth + (change.scoreDelta || 0),
      treasuryBalance: (prev.treasuryBalance || 0) + (change.treasuryDelta || 0)
    };
  });
  if (delta.worldChanges) {
    if (typeof delta.worldChanges.dayAfter === 'number') next.day = delta.worldChanges.dayAfter;
    if (typeof delta.worldChanges.turnAfter === 'number') next.turn = delta.worldChanges.turnAfter;
    if (delta.worldChanges.weatherAfter) next.weather = delta.worldChanges.weatherAfter;
    if (delta.worldChanges.marketTrendAfter) next.marketTrend = delta.worldChanges.marketTrendAfter;
  }
  next.stateHash = computeCanonicalStateHash({
    day: next.day,
    turnCounter: next.turn,
    actorsById: next.actors,
    teamsById: next.teams,
    regions: next.regions,
    activeEvents: next.activeEvents
  });
  return next;
}

const applyReplayEventToIsolatedRuntime = (runtime: IsolatedReplayRuntime, ev: ReplayEvent): IsolatedReplayRuntime => {
  if (ev.stateDelta && ev.stateDelta.changedPaths && ev.stateDelta.changedPaths.length > 0) {
    return applyReplayStateDeltaToRuntime(runtime, ev.stateDelta);
  }
  const next: IsolatedReplayRuntime = {
    ...runtime,
    actors: { ...runtime.actors },
    teams: { ...runtime.teams },
    day: ev.day || runtime.day,
    turn: ev.turn || runtime.turn,
    sequence: ev.sequence
  };
  const payload = ev.payload || {};
  const canonical = extractCanonicalActionPayload(payload, ev);
  const actorId = ev.actorId || 'player';
  if (next.actors[actorId]) {
    const actor = { ...next.actors[actorId] };
    if (typeof canonical.price === 'number' && (ev.category === 'market' || ev.category === 'human_action' || ev.category === 'ai_execution')) {
      const summary = (ev.summary || '').toLowerCase();
      if (summary.includes('sold') || summary.includes('sell')) actor.money += canonical.price;
      else if (summary.includes('bought') || summary.includes('buy') || summary.includes('purchas') || summary.includes('travel')) actor.money = Math.max(0, actor.money - canonical.price);
    }
    if (canonical.targetRegion) actor.region = canonical.targetRegion;
    next.actors[actorId] = actor;
  }
  if (ev.stateHashAfter) next.stateHash = ev.stateHashAfter;
  return next;
};

export function findNearestReplayCheckpoint(file: ReplayFile, targetSequence: number): ReplayCheckpoint | null {
  const eligible = file.checkpoints
    .filter(cp => cp.sequence <= targetSequence)
    .sort((a, b) => b.sequence - a.sequence);
  const withSnap = eligible.find(cp => Boolean(cp.fullStateSnapshot));
  return withSnap || eligible[0] || null;
}

export function seekReplayToSequence(file: ReplayFile, targetSequence: number): IsolatedReplayRuntime {
  return seekReplayToSequenceWithPolicy(file, targetSequence, 'force_reconstruction').runtime;
}

export function replayWatchFailureIsFatal(
  policy: ReplayPolicy | string | undefined,
  mode: ReplayReconstructionMode,
  deterministicValidationEnabled?: boolean
): boolean {
  if (mode === 'deterministic_reexecution' && deterministicValidationEnabled !== false) return true;
  return (policy || 'adaptive_fallback') === 'strict';
}

export function seekReplayToSequenceWithPolicy(
  file: ReplayFile,
  targetSequence: number,
  policy: ReplayPolicy = 'adaptive_fallback'
): { runtime: IsolatedReplayRuntime; error?: string } {
  const checkpoint = findNearestReplayCheckpoint(file, targetSequence);
  let runtime: IsolatedReplayRuntime;
  if (checkpoint?.fullStateSnapshot) {
    runtime = extractIsolatedRuntimeFromSnapshot(checkpoint.fullStateSnapshot, checkpoint.sequence);
    runtime.lastCheckpointId = checkpoint.id;
  } else {
    runtime = hydrateIsolatedReplayRuntimeFromConfig(file.initialConfig, 0);
    if (checkpoint) runtime.lastCheckpointId = checkpoint.id;
  }
  const startSeq = checkpoint ? checkpoint.sequence : -1;
  const eventsToApply = file.events
    .filter(ev => ev.sequence > startSeq && ev.sequence <= targetSequence)
    .sort((a, b) => a.sequence - b.sequence);
  let error: string | undefined;
  for (const ev of eventsToApply) {
    try {
      runtime = applyReplayEventToIsolatedRuntime(runtime, ev);
    } catch (err) {
      error = `Recorded playback failed at sequence ${ev.sequence}: ${err instanceof Error ? err.message : String(err)}`;
      if (policy === 'strict') break;
    }
  }
  runtime.sequence = targetSequence;
  return { runtime, error };
}

export function seekReplayToSequenceDeterministic(
  file: ReplayFile,
  targetSequence: number,
  policy: ReplayPolicy = 'strict',
  validateHashes = true
): { runtime: IsolatedReplayRuntime; error?: string; divergedSequence?: number } {
  const checkpoint = findNearestReplayCheckpoint(file, targetSequence);
  const localRng = new GameplayRngRegistry(file.initialConfig?.worldSeed || 1337);
  localRng.initStreams(file.initialConfig?.worldSeed || 1337);
  if (file.initialConfig?.rngRegistryState && typeof localRng.importStreamStates === 'function') {
    localRng.importStreamStates(file.initialConfig.rngRegistryState);
  }
  const snapshot = checkpoint?.fullStateSnapshot;
  let currentSimState: Record<string, unknown>;
  if (snapshot) {
    currentSimState = JSON.parse(JSON.stringify((snapshot as SaveGameData).gameState || snapshot));
  } else {
    const hydrated = hydrateIsolatedReplayRuntimeFromConfig(file.initialConfig, checkpoint?.sequence ?? 0);
    currentSimState = {
      day: hydrated.day,
      turnCounter: hydrated.turn,
      actorsById: hydrated.actors,
      teamsById: hydrated.teams,
      regions: hydrated.regions,
      activeEvents: hydrated.activeEvents
    };
  }
  const simCtx: ReplaySimulationStateContext = {
    currentSimState,
    simTeams: (currentSimState.teamsById || {}) as ReplaySimulationStateContext['simTeams'],
    simActors: (currentSimState.actorsById || {}) as ReplaySimulationStateContext['simActors'],
    simTerritories: (currentSimState.regions || {}) as ReplaySimulationStateContext['simTerritories'],
    simRng: localRng
  };
  const startSeq = checkpoint ? checkpoint.sequence : -1;
  const eventsToApply = file.events
    .filter(ev => ev.sequence > startSeq && ev.sequence <= targetSequence)
    .sort((a, b) => a.sequence - b.sequence);
  let error: string | undefined;
  let divergedSequence: number | undefined;
  for (const ev of eventsToApply) {
    try {
      applyReplayEventReducer(simCtx, ev);
      const actualHash = computeCanonicalStateHash(simCtx.currentSimState);
      const expectedHash = ev.stateHashAfter || ev.stateHash;
      if (validateHashes && expectedHash && expectedHash !== actualHash) {
        divergedSequence = ev.sequence;
        error = `Deterministic reconstruction diverged at sequence ${ev.sequence}. Recorded playback remains available.`;
        if (policy === 'strict') break;
        if (policy === 'skip_invalid') continue;
      }
    } catch (err) {
      divergedSequence = ev.sequence;
      error = `Deterministic reconstruction failed at sequence ${ev.sequence}: ${err instanceof Error ? err.message : String(err)}`;
      if (policy === 'strict') break;
    }
  }
  const runtime = extractIsolatedRuntimeFromSnapshot({
    ...(snapshot || {}),
    gameState: simCtx.currentSimState,
    actorsById: simCtx.currentSimState.actorsById || simCtx.simActors,
    teamsById: simCtx.currentSimState.teamsById || simCtx.simTeams
  } as SaveGameData, targetSequence);
  runtime.lastCheckpointId = checkpoint?.id;
  runtime.sequence = targetSequence;
  runtime.rngRegistryState = typeof localRng.exportStreamStates === 'function' ? localRng.exportStreamStates() : runtime.rngRegistryState;
  return { runtime, error, divergedSequence };
}

export function detectReplayTurningPoints(file: ReplayFile): ReplayTurningPoint[] {
  const points: ReplayTurningPoint[] = [];
  const leadChanges = file.checkpoints.filter(cp => cp.kind === 'lead_change');
  leadChanges.forEach((cp, idx) => {
    points.push({
      id: `tp_lead_${cp.id}`,
      sequence: cp.sequence,
      day: cp.day,
      turn: cp.turn,
      type: idx === 0 ? 'first_lead_change' : 'lead_change',
      importance: idx === 0 ? 90 : 70,
      title: idx === 0 ? 'First lead change' : 'Lead change',
      explanation: cp.label,
      teamId: cp.relatedId
    });
  });
  let largestSwing = 0;
  let largestSwingEvent: ReplayEvent | null = null;
  file.events.forEach(ev => {
    const money = ev.stateDelta?.actorChanges
      ? Object.values(ev.stateDelta.actorChanges).reduce((sum, ch) => sum + Math.abs(ch.moneyDelta || 0), 0)
      : 0;
    if (money > largestSwing) {
      largestSwing = money;
      largestSwingEvent = ev;
    }
    const cat = ev.category;
    const summary = (ev.summary || '').toLowerCase();
    if (cat === 'failed_action' || summary.includes('failed') || summary.includes('denied')) {
      if (!points.some(p => p.type === 'first_failed_action')) {
        points.push({
          id: `tp_fail_${ev.id}`,
          sequence: ev.sequence,
          day: ev.day,
          turn: ev.turn,
          type: 'first_failed_action',
          importance: 60,
          title: 'First failed action',
          explanation: ev.summary,
          actorId: ev.actorId || undefined,
          teamId: ev.teamId || undefined
        });
      }
    }
    if (cat === 'contract' || summary.includes('contract')) {
      if (summary.includes('complete')) {
        points.push({
          id: `tp_contract_${ev.id}`,
          sequence: ev.sequence,
          day: ev.day,
          turn: ev.turn,
          type: 'contract_completion',
          importance: 75,
          title: 'Contract completion',
          explanation: ev.summary,
          actorId: ev.actorId || undefined
        });
      }
    }
    if (cat === 'infrastructure' || summary.includes('infrastructure')) {
      if (summary.includes('complete')) {
        points.push({
          id: `tp_infra_${ev.id}`,
          sequence: ev.sequence,
          day: ev.day,
          turn: ev.turn,
          type: 'infrastructure_completion',
          importance: 80,
          title: 'Infrastructure completion',
          explanation: ev.summary,
          actorId: ev.actorId || undefined
        });
      }
    }
    if (cat === 'expedition' || summary.includes('expedition')) {
      points.push({
        id: `tp_exp_${ev.id}`,
        sequence: ev.sequence,
        day: ev.day,
        turn: ev.turn,
        type: summary.includes('fail') ? 'major_expedition_failure' : 'expedition',
        importance: 72,
        title: summary.includes('fail') ? 'Expedition failure' : 'Expedition event',
        explanation: ev.summary,
        actorId: ev.actorId || undefined
      });
    }
    if (cat === 'auto_mode_package_applied') {
      points.push({
        id: `tp_auto_${ev.id}`,
        sequence: ev.sequence,
        day: ev.day,
        turn: ev.turn,
        type: 'auto_mode_intervention',
        importance: 68,
        title: 'Auto Mode intervention',
        explanation: ev.summary,
        actorId: ev.actorId || undefined
      });
    }
  });
  if (largestSwingEvent && largestSwing > 0) {
    const ev = largestSwingEvent;
    points.push({
      id: `tp_swing_${ev.id}`,
      sequence: ev.sequence,
      day: ev.day,
      turn: ev.turn,
      type: 'largest_economic_swing',
      importance: 85,
      title: 'Largest economic swing',
      explanation: `${ev.summary} (Δ$${largestSwing.toLocaleString()})`,
      actorId: ev.actorId || undefined,
      stateImpact: ev.stateDelta
    });
  }
  const endgame = file.checkpoints.find(cp => cp.kind === 'endgame_start');
  if (endgame) {
    points.push({
      id: `tp_endgame_${endgame.id}`,
      sequence: endgame.sequence,
      day: endgame.day,
      turn: endgame.turn,
      type: 'endgame_start',
      importance: 88,
      title: 'Endgame begins',
      explanation: endgame.label
    });
  }
  if (file.finalResult) {
    const last = file.events[file.events.length - 1];
    points.push({
      id: 'tp_match_end',
      sequence: last?.sequence ?? 0,
      day: file.finalResult.day,
      turn: file.finalResult.turn,
      type: 'game_winning_action',
      importance: 100,
      title: 'Match result',
      explanation: file.finalResult.reason,
      teamId: file.finalResult.winnerTeamId || undefined,
      actorId: file.finalResult.winnerActorId || undefined
    });
  }
  return points.sort((a, b) => b.importance - a.importance || a.sequence - b.sequence);
}

export function detectReplayChapters(file: ReplayFile): ReplayChapter[] {
  const events = file.events;
  if (events.length === 0) {
    return [{ id: 'ch_empty', title: 'Opening', startSequence: 0, endSequence: 0, startDay: 1, endDay: 1, explanation: 'No events recorded.' }];
  }
  const maxDay = Math.max(...events.map(ev => ev.day || 1), file.finalResult?.day || 1);
  const chapters: ReplayChapter[] = [];
  const pushChapter = (title: string, startDay: number, endDay: number, explanation: string) => {
    const slice = events.filter(ev => ev.day >= startDay && ev.day <= endDay);
    if (slice.length === 0 && chapters.length > 0) return;
    const startSeq = slice[0]?.sequence ?? (chapters[chapters.length - 1]?.endSequence || 0);
    const endSeq = slice[slice.length - 1]?.sequence ?? startSeq;
    chapters.push({
      id: `ch_${title.toLowerCase().replace(/\s+/g, '_')}`,
      title,
      startSequence: startSeq,
      endSequence: endSeq,
      startDay,
      endDay,
      explanation
    });
  };
  const firstLead = file.checkpoints.find(cp => cp.kind === 'lead_change');
  const endgame = file.checkpoints.find(cp => cp.kind === 'endgame_start');
  const hasExpedition = events.some(ev => ev.category === 'expedition' || (ev.summary || '').toLowerCase().includes('expedition'));
  const hasCrisis = events.some(ev => (ev.summary || '').toLowerCase().includes('crisis') || ev.category === 'failed_action');
  pushChapter('Opening', 1, Math.min(3, maxDay), 'Match opening and first positioning.');
  if (maxDay > 3) pushChapter('Early Expansion', 4, Math.min(8, maxDay), 'Early expansion and economy.');
  if (maxDay > 8) pushChapter('Economic Development', 9, Math.min(14, maxDay), 'Contracts, markets, and infrastructure.');
  if (hasExpedition) {
    const exp = events.find(ev => ev.category === 'expedition' || (ev.summary || '').toLowerCase().includes('expedition'));
    if (exp) pushChapter('Expedition Phase', exp.day, Math.min(exp.day + 3, maxDay), 'Expedition activity.');
  }
  if (hasCrisis) {
    const crisis = events.find(ev => (ev.summary || '').toLowerCase().includes('crisis') || ev.category === 'failed_action');
    if (crisis) pushChapter('Crisis', crisis.day, crisis.day, crisis.summary);
  }
  if (firstLead) pushChapter('Lead Change', firstLead.day, firstLead.day, firstLead.label);
  if (endgame) {
    pushChapter('Endgame', endgame.day, Math.max(endgame.day, maxDay - 1), 'Endgame pressure.');
    pushChapter('Final Push', Math.max(endgame.day, maxDay - 1), maxDay, 'Final decisive actions.');
  } else if (maxDay > 14) {
    pushChapter('Midgame Competition', 15, Math.max(15, maxDay - 2), 'Midgame competition.');
    pushChapter('Final Push', Math.max(1, maxDay - 1), maxDay, 'Closing phase.');
  }
  return chapters;
}

export function buildReplayMatchSummary(file: ReplayFile): string {
  const points = file.turningPoints && file.turningPoints.length > 0 ? file.turningPoints : detectReplayTurningPoints(file);
  const winner = file.finalResult
    ? (file.finalResult.winnerTeamId || file.finalResult.winnerActorId || 'Unknown')
    : 'unfinished';
  const duration = file.finalResult?.day || (file.events[file.events.length - 1]?.day || 1);
  const firstLead = points.find(p => p.type === 'first_lead_change');
  const biggest = points.find(p => p.type === 'largest_economic_swing' || p.importance >= 80);
  const auto = points.find(p => p.type === 'auto_mode_intervention');
  const parts = [
    file.finalResult
      ? `${winner} won on Day ${duration}${firstLead ? ` after a lead change on Day ${firstLead.day}` : ''}.`
      : `Match in progress through Day ${duration}.`
  ];
  if (biggest) parts.push(`The largest turning point was ${biggest.title.toLowerCase()}: ${biggest.explanation}`);
  if (auto) parts.push(`Auto Mode intervened on Day ${auto.day}.`);
  if (file.finalResult?.reason) parts.push(`Decisive result: ${file.finalResult.reason}`);
  return parts.join(' ');
}

export const REPLAY_CRITICAL_LEDGER_CATEGORIES: ReadonlySet<string> = new Set([
  'action', 'decision', 'approval', 'treasury', 'match_lifecycle', 'copilot_action', 'copilot_event', 'guardian_event'
]);

export function mapLedgerCategoryToReplay(category: string, eventType?: string): ReplayEventCategory {
  const t = `${category} ${eventType || ''}`.toLowerCase();
  if (t.includes('travel')) return 'travel';
  if (t.includes('challenge')) return 'challenge';
  if (t.includes('contract')) return 'contract';
  if (t.includes('infra')) return 'infrastructure';
  if (t.includes('expedition') || t.includes('relic')) return 'expedition';
  if (t.includes('sabotage')) return 'sabotage';
  if (t.includes('market') || t.includes('buy') || t.includes('sell')) return 'market';
  if (t.includes('govern')) return 'governance';
  if (category === 'treasury') return 'treasury_event';
  if (category === 'approval') return 'approval_event';
  if (category === 'decision') return 'ai_decision';
  if (category === 'copilot_event' || category === 'copilot_action') return 'copilot_event';
  if (category === 'guardian_event') return 'guardian_event';
  if (category === 'match_lifecycle') return 'day_transition';
  if (t.includes('director')) return 'director_event';
  if (t.includes('fail')) return 'failed_action';
  if (category === 'action') return 'human_action';
  return 'human_action';
}

export function replayActionAttemptAlreadyRecorded(events: ReplayEvent[], actionAttemptId?: string | null): boolean {
  if (!actionAttemptId) return false;
  return events.some(ev => ev.actionAttemptId === actionAttemptId);
}

export function mapActionAttemptToReplayRecord(attempt: {
  actionType?: string;
  actorId?: string;
  teamId?: string;
  actionAttemptId?: string;
  error?: string;
  status?: string;
  parameters?: Record<string, unknown>;
  delta?: { moneyDelta?: number } | null;
}): { category: ReplayEventCategory; summary: string; result: string; payload: Record<string, unknown>; actionAttemptId?: string; actorId?: string | null; teamId?: string | null } {
  const failed = Boolean(attempt.error) || /fail|reject/i.test(attempt.status || '');
  const actionType = attempt.actionType || 'action';
  const category = failed ? 'failed_action' : mapLedgerCategoryToReplay('action', actionType);
  const params = attempt.parameters || {};
  return {
    category,
    summary: failed ? `Failed ${actionType}: ${attempt.error || 'failed'}` : `${actionType} by ${attempt.actorId || 'actor'}`,
    result: failed ? 'failed' : 'success',
    actionAttemptId: attempt.actionAttemptId,
    actorId: attempt.actorId || null,
    teamId: attempt.teamId || null,
    payload: {
      actionType,
      cost: params.cost ?? params.price,
      price: params.price ?? params.cost,
      alternatives: params.alternatives ?? params.availableAlternatives ?? params.alternativeActions,
      warnings: params.warnings,
      confirmation: params.confirmation,
      region: params.region ?? params.targetRegion,
      moneyDelta: attempt.delta?.moneyDelta
    }
  };
}

const REPLAY_DIFFICULTY_CYCLE = ['easy', 'medium', 'hard', 'expert'] as const;
const REPLAY_RANDOMNESS_CYCLE: RandomnessMode[] = ['deterministic', 'hybrid', 'recorded_chaos', 'legacy_random'];

export interface ReplayBranchSnapshotMutation {
  acceptContract?: boolean;
  rejectContract?: boolean;
  removeSabotage?: boolean;
}

export interface ReplayBranchExperimentPlan {
  label: string;
  branchReason: ReplayBranchMetadata['branchReason'];
  branchSeedPolicy: ReplayBranchMetadata['branchSeedPolicy'];
  modifiedSettings: Record<string, unknown>;
  title: string;
  snapshotMutation?: ReplayBranchSnapshotMutation;
  unavailableReason?: string;
}

export function buildReplayBranchExperiment(label: string, current?: Record<string, unknown> | Partial<GameSettingsState> | null): ReplayBranchExperimentPlan {
  const settings = (current || {}) as Record<string, unknown>;
  const difficulty = String(settings.aiDifficulty || 'medium');
  const nextDifficulty = REPLAY_DIFFICULTY_CYCLE[(Math.max(0, REPLAY_DIFFICULTY_CYCLE.indexOf(difficulty as typeof REPLAY_DIFFICULTY_CYCLE[number])) + 1) % REPLAY_DIFFICULTY_CYCLE.length];
  const currentMode = (typeof settings.randomnessMode === 'string' ? settings.randomnessMode : 'deterministic') as RandomnessMode;
  const nextMode = REPLAY_RANDOMNESS_CYCLE[(Math.max(0, REPLAY_RANDOMNESS_CYCLE.indexOf(currentMode)) + 1) % REPLAY_RANDOMNESS_CYCLE.length];
  const worldSeed = typeof settings.worldSeed === 'number' ? settings.worldSeed : 1337;
  switch (label) {
    case 'Let AI Choose':
      return { label, branchReason: 'auto_mode', branchSeedPolicy: 'preserve_original', title: 'Let AI Choose', modifiedSettings: { autoModeEnabled: true, coPilotEnabled: true } };
    case 'Change AI Difficulty':
      return { label, branchReason: 'ai_strategy', branchSeedPolicy: 'preserve_original', title: `Change AI Difficulty to ${nextDifficulty}`, modifiedSettings: { aiDifficulty: nextDifficulty } };
    case 'Enable Auto Mode':
      return { label, branchReason: 'auto_mode', branchSeedPolicy: 'preserve_original', title: 'Enable Auto Mode', modifiedSettings: { autoModeEnabled: true } };
    case 'Disable Auto Mode':
      return { label, branchReason: 'auto_mode', branchSeedPolicy: 'preserve_original', title: 'Disable Auto Mode', modifiedSettings: { autoModeEnabled: false } };
    case 'Change Seed':
      return { label, branchReason: 'randomness', branchSeedPolicy: 'new_seed', title: 'Change Seed', modifiedSettings: { worldSeed: worldSeed + 1, aiSeed: (typeof settings.aiSeed === 'number' ? settings.aiSeed : worldSeed) + 1 } };
    case 'Change Randomness Mode':
      return { label, branchReason: 'randomness', branchSeedPolicy: 'preserve_original', title: `Change Randomness Mode to ${nextMode}`, modifiedSettings: { randomnessMode: nextMode } };
    case 'Change AI Strategy': {
      const presets = ['classic', 'balanced', 'smarter_teammate', 'aggressive_opponent', 'safe_saver', 'resource_trader', 'challenge_hunter', 'chaos_mode'];
      const currentPreset = String(settings.aiStrategyLabPreset || 'classic');
      const nextPreset = presets[(Math.max(0, presets.indexOf(currentPreset)) + 1) % presets.length];
      return { label, branchReason: 'ai_strategy', branchSeedPolicy: 'preserve_original', title: `Change AI Strategy to ${nextPreset}`, modifiedSettings: { aiStrategyLabPreset: nextPreset, aiStrategy: nextPreset } };
    }
    case 'Change Auto Mode Intensity': {
      const modes = ['recommend', 'assist_only', 'full_auto'];
      const currentPerm = String(settings.permissionMode || 'recommend');
      const nextPerm = modes[(Math.max(0, modes.indexOf(currentPerm)) + 1) % modes.length];
      return { label, branchReason: 'auto_mode', branchSeedPolicy: 'preserve_original', title: `Change Auto Mode Intensity to ${nextPerm}`, modifiedSettings: { permissionMode: nextPerm } };
    }
    case 'Change Team Strategy': {
      const modes = ['earn', 'recovery', 'attack', 'defense', 'challenge', 'resource', 'control', 'support'];
      const currentTeam = String(settings.teamStrategyMode || 'earn');
      const nextTeam = modes[(Math.max(0, modes.indexOf(currentTeam)) + 1) % modes.length];
      return { label, branchReason: 'ai_strategy', branchSeedPolicy: 'preserve_original', title: `Change Team Strategy to ${nextTeam}`, modifiedSettings: { teamStrategyMode: nextTeam } };
    }
    case 'Change Expedition Risk': {
      const currentTravel = String(settings.territoryTravelMode || 'transit');
      const nextTravel = currentTravel === 'committed' ? 'transit' : 'committed';
      return { label, branchReason: 'settings_change', branchSeedPolicy: 'preserve_original', title: `Change Expedition Risk (${nextTravel})`, modifiedSettings: { territoryTravelMode: nextTravel, expeditionModeEnabled: true, forcedRetreatEnabled: nextTravel === 'committed' } };
    }
    case 'Accept Contract':
      return { label, branchReason: 'human_decision', branchSeedPolicy: 'preserve_original', title: 'Accept Contract', modifiedSettings: {}, snapshotMutation: { acceptContract: true } };
    case 'Reject Contract':
      return { label, branchReason: 'human_decision', branchSeedPolicy: 'preserve_original', title: 'Reject Contract', modifiedSettings: {}, snapshotMutation: { rejectContract: true } };
    case 'Change Infrastructure Investment': {
      const current = typeof settings.aiInfrastructurePriority === 'number' ? settings.aiInfrastructurePriority : 1;
      const next = current >= 1.5 ? 0.5 : Math.round((current + 0.5) * 10) / 10;
      return { label, branchReason: 'settings_change', branchSeedPolicy: 'preserve_original', title: `Change Infrastructure Investment to ${next}`, modifiedSettings: { investmentsEnabled: true, aiInfrastructurePriority: next } };
    }
    case 'Remove Sabotage':
      return { label, branchReason: 'settings_change', branchSeedPolicy: 'preserve_original', title: 'Remove Sabotage', modifiedSettings: { sabotageEnabled: false }, snapshotMutation: { removeSabotage: true } };
    case 'Change Governance Policy':
      return { label, branchReason: 'settings_change', branchSeedPolicy: 'preserve_original', title: settings.governanceControlSurfaceEnabled ? 'Disable Governance Policy' : 'Enable Governance Policy', modifiedSettings: { governanceControlSurfaceEnabled: !settings.governanceControlSurfaceEnabled } };
    default:
      return { label, branchReason: 'human_decision', branchSeedPolicy: 'preserve_original', title: 'Try Different Human Action', modifiedSettings: {} };
  }
}

export function updateReplayBookmark(file: ReplayFile, bookmarkId: string, patch: { title?: string; note?: string }): ReplayFile {
  const bookmarks = (file.bookmarks || []).map(bm => bm.id === bookmarkId ? { ...bm, ...patch } : bm);
  return { ...file, bookmarks };
}

export function replaySnapshotHasPendingContract(snapshot?: SaveGameData | Record<string, unknown> | null): boolean {
  if (!snapshot) return false;
  const rec = snapshot as Record<string, unknown>;
  const gs = (rec.gameState && typeof rec.gameState === 'object' ? rec.gameState : rec) as Record<string, unknown>;
  const byActor = gs.activeContractsByActor || rec.activeContractsByActor;
  if (byActor && typeof byActor === 'object' && Object.values(byActor as Record<string, unknown>).some(v => Array.isArray(v) && v.length > 0)) return true;
  const pending = gs.pendingContracts || rec.pendingContracts || gs.contracts || rec.contracts;
  return Array.isArray(pending) && pending.length > 0;
}

export function replaySnapshotHasSabotage(snapshot?: SaveGameData | Record<string, unknown> | null, settings?: Record<string, unknown> | null): boolean {
  if (settings && settings.sabotageEnabled === true) return true;
  if (!snapshot) return false;
  const rec = snapshot as Record<string, unknown>;
  const gs = (rec.gameState && typeof rec.gameState === 'object' ? rec.gameState : rec) as Record<string, unknown>;
  const actors = (rec.actorsById || gs.actorsById || {}) as Record<string, { debuffs?: unknown }>;
  return Object.values(actors).some(a => Array.isArray(a?.debuffs) && a.debuffs.length > 0);
}

export function applyReplayBranchSnapshotMutations(
  save: SaveGameData,
  mutation?: ReplayBranchSnapshotMutation
): { save: SaveGameData; applied: boolean; reason?: string } {
  if (!mutation) return { save, applied: true };
  const next = JSON.parse(JSON.stringify(save)) as SaveGameData & Record<string, unknown>;
  const gs = ((next as Record<string, unknown>).gameState && typeof (next as Record<string, unknown>).gameState === 'object'
    ? (next as Record<string, unknown>).gameState
    : next) as Record<string, unknown>;
  if (mutation.acceptContract || mutation.rejectContract) {
    if (!replaySnapshotHasPendingContract(next)) {
      return { save, applied: false, reason: 'No pending contract on this checkpoint.' };
    }
    const byActor = (gs.activeContractsByActor || (next as Record<string, unknown>).activeContractsByActor) as Record<string, string[]> | undefined;
    if (byActor) {
      Object.keys(byActor).forEach(id => {
        if (!Array.isArray(byActor[id]) || byActor[id].length === 0) return;
        if (mutation.rejectContract) byActor[id] = byActor[id].slice(1);
        if (mutation.acceptContract) gs.lastAcceptedContractId = byActor[id][0];
      });
    }
    const list = (gs.pendingContracts || gs.contracts) as unknown[] | undefined;
    if (Array.isArray(list) && list.length > 0) {
      if (mutation.rejectContract) list.shift();
      if (mutation.acceptContract) gs.lastAcceptedContractId = list[0];
    }
  }
  if (mutation.removeSabotage) {
    const actors = ((next as Record<string, unknown>).actorsById || gs.actorsById || {}) as Record<string, { debuffs?: unknown[] }>;
    Object.values(actors).forEach(actor => {
      if (Array.isArray(actor.debuffs)) actor.debuffs = [];
    });
    if (next.gameSettings) next.gameSettings = { ...next.gameSettings, sabotageEnabled: false };
  }
  return { save: next, applied: true };
}

export function mapAutoModeOutcomeToReplayCategory(outcome?: string): ReplayEventCategory {
  switch (String(outcome || '')) {
    case 'applied': return 'auto_mode_package_applied';
    case 'proposed': return 'auto_mode_proposal_submitted';
    case 'resolved': return 'auto_mode_proposal_resolved';
    case 'rolled_back':
    case 'expired':
    case 'reverse': return 'auto_mode_package_rolled_back';
    default: return 'auto_mode_evaluation';
  }
}

export function buildAutoModeReplayPayload(evt: {
  decisionOutcome?: string;
  classifications?: unknown;
  selectedAdjustments?: unknown;
  candidateAdjustments?: unknown;
  actorScores?: unknown;
  teamScores?: unknown;
  settingsBefore?: Record<string, unknown>;
  settingsAfter?: Record<string, unknown>;
  appliedPackages?: unknown;
  rngDraws?: unknown;
}): Record<string, unknown> {
  return {
    adaptationKind: 'actor',
    decisionOutcome: evt.decisionOutcome,
    classifications: evt.classifications,
    competitivePositionScores: evt.actorScores,
    teamScores: evt.teamScores,
    selectedAdjustments: evt.selectedAdjustments,
    candidateAdjustments: evt.candidateAdjustments,
    settingsBefore: evt.settingsBefore || {},
    settingsAfter: evt.settingsAfter || {},
    appliedPackages: evt.appliedPackages,
    rngDraws: evt.rngDraws
  };
}

export function mapDirectorRequestToReplay(request: { id?: string; requestType?: string; actorId?: string; urgency?: number }, queued: boolean): { category: ReplayEventCategory; payload: Record<string, unknown>; summary: string } {
  return {
    category: queued ? 'director_event' : 'director_evaluation',
    summary: queued ? `Director world event ${request.requestType || request.id || 'queued'}` : `Director evaluation ${request.requestType || request.id || ''}`,
    payload: {
      adaptationKind: 'world',
      requestId: request.id,
      requestType: request.requestType,
      targetActorId: request.actorId,
      urgency: request.urgency,
      queued
    }
  };
}

export function collectReplayActionLifecycle(events: ReplayEvent[], selected: ReplayEvent): ReplayEvent[] {
  const attemptId = selected.actionAttemptId || selected.correlationId || selected.id;
  return events.filter(ev =>
    ev.id === selected.id ||
    ev.parentEventId === selected.id ||
    selected.parentEventId === ev.id ||
    (attemptId && (ev.actionAttemptId === attemptId || ev.correlationId === attemptId || ev.parentEventId === attemptId))
  ).sort((a, b) => a.sequence - b.sequence);
}

export function replayCategoryToCheckpointKind(category: ReplayEventCategory): ReplayCheckpointKind | null {
  switch (category) {
    case 'auto_mode_package_applied':
    case 'auto_mode_evaluation':
    case 'auto_mode_proposal_submitted':
    case 'auto_mode_proposal_resolved':
    case 'auto_mode_package_rolled_back': return 'auto_mode';
    case 'director_event':
    case 'director_evaluation': return 'director';
    case 'contract': return 'contract';
    case 'infrastructure': return 'infrastructure';
    case 'expedition': return 'expedition';
    case 'governance': return 'governance';
    case 'turn_transition': return 'turn';
    case 'ai_execution':
    case 'human_action': return 'major_action';
    case 'challenge':
    case 'sabotage': return 'post_risky_action';
    default: return null;
  }
}

export function shouldThrottleReplayDetail(detailLevel: string | undefined, usage: number, isCritical: boolean): boolean {
  return usage >= 0.9 && !isCritical && (detailLevel || 'standard') === 'standard';
}

export function computeReplayChecksumLegacy(file: Omit<ReplayFile, 'checksum'>): string {
  const serialized = JSON.stringify({
    schemaVersion: file.schemaVersion,
    matchId: file.matchId,
    events: file.events,
    checkpoints: file.checkpoints,
    finalResult: file.finalResult,
    truncated: file.truncated,
    truncatedAtSequence: file.truncatedAtSequence
  });
  let hash = 0x811c9dc5;
  for (let i = 0; i < serialized.length; i += 1) {
    hash ^= serialized.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
}

export function verifyReplayChecksum(file: ReplayFile): { ok: boolean; expected: string; legacyOk: boolean } {
  const expected = computeReplayChecksum(file);
  const legacy = computeReplayChecksumLegacy(file);
  const actual = file.checksum || '';
  return { ok: actual === expected || actual === legacy, expected, legacyOk: actual === legacy };
}

export function findFirstReplayRngDivergence(fileA: ReplayFile, fileB: ReplayFile): { sequence: number; day: number; turn: number; explanation: string } | null {
  const drawsA = fileA.randomDraws || [];
  const drawsB = fileB.randomDraws || [];
  const n = Math.min(drawsA.length, drawsB.length);
  for (let i = 0; i < n; i++) {
    const a = drawsA[i];
    const b = drawsB[i];
    if (a.value !== b.value || a.stream !== b.stream || a.context !== b.context) {
      return {
        sequence: typeof a.seq === 'number' ? a.seq : i,
        day: typeof a.day === 'number' ? a.day : 1,
        turn: typeof a.turn === 'number' ? a.turn : 1,
        explanation: `RNG draw ${i} differed (${a.value} vs ${b.value}).`
      };
    }
  }
  if (drawsA.length !== drawsB.length) {
    const extra = drawsA.length > drawsB.length ? drawsA[n] : drawsB[n];
    return {
      sequence: typeof extra?.seq === 'number' ? extra.seq : n,
      day: typeof extra?.day === 'number' ? extra.day : 1,
      turn: typeof extra?.turn === 'number' ? extra.turn : 1,
      explanation: `Recorded draw count differs (${drawsA.length} vs ${drawsB.length}).`
    };
  }
  return null;
}

export function replayEventImportance(ev: ReplayEvent): number {
  switch (ev.category) {
    case 'match_result': return 100;
    case 'lead_change_event': return 90;
    case 'auto_mode_package_applied': return 80;
    case 'director_event': return 78;
    case 'expedition': return 75;
    case 'contract':
    case 'infrastructure': return 72;
    case 'failed_action': return 70;
    case 'ai_decision':
    case 'ai_execution': return 60;
    case 'human_action': return 55;
    case 'day_transition':
    case 'turn_transition': return 40;
    default: return 30;
  }
}

