export function cloneReplayFileImmutable(file: ReplayFile): ReplayFile {
  return JSON.parse(JSON.stringify(file)) as ReplayFile;
}

const lastCheckpointMoneyByTeam = (file: ReplayFile): Record<string, number> => {
  for (let i = file.checkpoints.length - 1; i >= 0; i--) {
    const money = file.checkpoints[i]?.expectedState?.moneyByTeam;
    if (money && Object.keys(money).length > 0) return money;
  }
  if (file.finalResult?.scoresByTeam) return file.finalResult.scoresByTeam;
  return {};
};

const countReplayCategory = (file: ReplayFile, cats: ReplayEventCategory[]): number =>
  file.events.filter(ev => cats.includes(ev.category)).length;

// RP4: structural classification — per-checkpoint sequence-range/referential integrity.
type ReplayDivergenceStatus = 'exact_match' | 'equivalent' | 'diverged' | 'recovered' | 'unsupported';
interface ReplayIntegrityReportEntry {
  checkpointId: string;
  status: ReplayDivergenceStatus;
  note: string;
}
function classifyReplayFileIntegrity(file: ReplayFile): ReplayIntegrityReportEntry[] {
  const eventSequences = new Set(file.events.map(ev => ev.sequence));
  const checkpointIds = new Set(file.checkpoints.map(cp => cp.id));
  return file.checkpoints.map(cp => {
    if (cp.sequence < 0 || (file.events.length > 0 && cp.sequence > (file.events[file.events.length - 1]?.sequence ?? file.events.length))) {
      return { checkpointId: cp.id, status: 'unsupported', note: `Sequence ${cp.sequence} is out of range for this file's recorded events.` };
    }
    if (cp.sequence > 0 && file.events.length > 0 && !eventSequences.has(cp.sequence) && !eventSequences.has(cp.sequence - 1)) {
      return { checkpointId: cp.id, status: 'unsupported', note: `Sequence ${cp.sequence} does not correspond to any nearby recorded event.` };
    }
    if (cp.relatedId && !checkpointIds.has(cp.relatedId) && !file.events.some(ev => ev.decisionId === cp.relatedId || ev.id === cp.relatedId)) {
      return { checkpointId: cp.id, status: 'unsupported', note: `relatedId "${cp.relatedId}" was not found anywhere else in this file.` };
    }
    if (cp.fullStateSnapshot) {
      return { checkpointId: cp.id, status: 'exact_match', note: 'Checkpoint has a full state snapshot and resolves within this file.' };
    }
    return { checkpointId: cp.id, status: 'exact_match', note: 'Sequence and relatedId (if any) both resolve within this file.' };
  });
};

interface ReplayComparisonResult {
  winnerChanged: boolean;
  originalWinnerLabel: string;
  branchWinnerLabel: string;
  matchLengthDeltaDays: number | null;
  totalActionsDelta: number;
  majorDecisionDifferences: string[];
  moneyNetWorthNote: string;
  originalMoneyByTeam: Record<string, number>;
  branchMoneyByTeam: Record<string, number>;
  contractsDelta: number;
  infrastructureDelta: number;
  expeditionsDelta: number;
  failedActionsDelta: number;
  originalTeamNetWorth: number;
  branchTeamNetWorth: number;
  teamNetWorthDelta: number;
  originalVictoryScore: number;
  branchVictoryScore: number;
  victoryScoreDelta: number;
  originalTeamEfficiency: number;
  branchTeamEfficiency: number;
  teamEfficiencyDelta: number;
  originalPassiveIncome: number;
  branchPassiveIncome: number;
  originalRelics: number;
  branchRelics: number;
  originalSabotage: number;
  branchSabotage: number;
  originalLoans: number;
  branchLoans: number;
  originalBankruptcy: number;
  branchBankruptcy: number;
  originalAiEfficiency: number;
  branchAiEfficiency: number;
  originalAutoModeInterventions: number;
  branchAutoModeInterventions: number;
  originalDirectorInterventions: number;
  branchDirectorInterventions: number;
  rngDivergenceNote: string;
}

const compareReplayFinalResults = (original: ReplayFile, branch: ReplayFile): ReplayComparisonResult => {
  const winnerLabel = (file: ReplayFile) => file.finalResult
    ? (file.finalResult.winnerTeamId || file.finalResult.winnerActorId || 'n/a')
    : 'match not finished';
  const originalWinnerLabel = winnerLabel(original);
  const branchWinnerLabel = winnerLabel(branch);
  const matchLengthDeltaDays = (original.finalResult && branch.finalResult)
    ? branch.finalResult.day - original.finalResult.day
    : null;
  const countActionEvents = (file: ReplayFile) => file.events.filter(ev =>
    ev.category === 'ai_decision' || ev.category === 'ai_execution' || ev.category === 'human_action'
  ).length;
  const totalActionsDelta = countActionEvents(branch) - countActionEvents(original);
  const countByChosenType = (file: ReplayFile): Record<string, number> => file.events
    .filter(ev => ev.category === 'ai_decision' || ev.category === 'human_action')
    .reduce((acc, ev) => {
      const type = String((ev.payload as { chosenAction?: unknown })?.chosenAction ?? ev.payload?.actionType ?? ev.category);
      acc[type] = (acc[type] || 0) + 1;
      return acc;
    }, {} as Record<string, number>);
  const originalCounts = countByChosenType(original);
  const branchCounts = countByChosenType(branch);
  const allTypes = new Set([...Object.keys(originalCounts), ...Object.keys(branchCounts)]);
  const majorDecisionDifferences: string[] = [];
  allTypes.forEach(type => {
    const o = originalCounts[type] || 0;
    const b = branchCounts[type] || 0;
    if (o !== b) majorDecisionDifferences.push(`${type}: original ${o}, branch ${b}`);
  });
  const originalMoneyByTeam = lastCheckpointMoneyByTeam(original);
  const branchMoneyByTeam = lastCheckpointMoneyByTeam(branch);
  const moneyKeys = new Set([...Object.keys(originalMoneyByTeam), ...Object.keys(branchMoneyByTeam)]);
  const moneyNotes: string[] = [];
  moneyKeys.forEach(id => {
    const o = originalMoneyByTeam[id] || 0;
    const b = branchMoneyByTeam[id] || 0;
    if (o !== b) moneyNotes.push(`${id}: ${o} → ${b} (${b - o >= 0 ? '+' : ''}${b - o})`);
  });
  const sumValues = (rec: Record<string, number>) => Object.values(rec).reduce((sum, n) => sum + n, 0);
  const originalTeamNetWorth = sumValues(originalMoneyByTeam);
  const branchTeamNetWorth = sumValues(branchMoneyByTeam);
  const originalVictoryScore = sumValues(original.finalResult?.scoresByTeam || {});
  const branchVictoryScore = sumValues(branch.finalResult?.scoresByTeam || {});
  const actionCount = (file: ReplayFile) => countActionEvents(file);
  const failedCount = (file: ReplayFile) => countReplayCategory(file, ['failed_action']);
  const efficiency = (file: ReplayFile) => {
    const attempted = actionCount(file);
    return attempted > 0 ? (attempted - failedCount(file)) / attempted : 0;
  };
  const originalTeamEfficiency = efficiency(original);
  const branchTeamEfficiency = efficiency(branch);
  const countKeyword = (file: ReplayFile, cats: ReplayEventCategory[], keywords: string[]) =>
    file.events.filter(ev => cats.includes(ev.category) || keywords.some(k => (ev.summary || '').toLowerCase().includes(k) || String(ev.payload?.actionType || '').toLowerCase().includes(k))).length;
  const aiAttempted = (file: ReplayFile) => file.events.filter(ev => ev.category === 'ai_decision' || ev.category === 'ai_execution').length;
  const aiFailed = (file: ReplayFile) => file.events.filter(ev => ev.category === 'failed_action' && ev.actorId !== 'player').length;
  const aiEfficiency = (file: ReplayFile) => {
    const n = aiAttempted(file);
    return n > 0 ? (n - aiFailed(file)) / n : 0;
  };
  const rngDiv = findFirstReplayRngDivergence(original, branch);
  return {
    winnerChanged: originalWinnerLabel !== branchWinnerLabel,
    originalWinnerLabel,
    branchWinnerLabel,
    matchLengthDeltaDays,
    totalActionsDelta,
    majorDecisionDifferences,
    moneyNetWorthNote: moneyNotes.length > 0 ? moneyNotes.join('; ') : 'No money/net-worth delta between last checkpoints.',
    originalMoneyByTeam,
    branchMoneyByTeam,
    contractsDelta: countReplayCategory(branch, ['contract']) - countReplayCategory(original, ['contract']),
    infrastructureDelta: countReplayCategory(branch, ['infrastructure']) - countReplayCategory(original, ['infrastructure']),
    expeditionsDelta: countReplayCategory(branch, ['expedition']) - countReplayCategory(original, ['expedition']),
    failedActionsDelta: countReplayCategory(branch, ['failed_action']) - countReplayCategory(original, ['failed_action']),
    originalTeamNetWorth,
    branchTeamNetWorth,
    teamNetWorthDelta: branchTeamNetWorth - originalTeamNetWorth,
    originalVictoryScore,
    branchVictoryScore,
    victoryScoreDelta: branchVictoryScore - originalVictoryScore,
    originalTeamEfficiency,
    branchTeamEfficiency,
    teamEfficiencyDelta: branchTeamEfficiency - originalTeamEfficiency,
    originalPassiveIncome: countKeyword(original, ['market'], ['passive', 'yield', 'income']),
    branchPassiveIncome: countKeyword(branch, ['market'], ['passive', 'yield', 'income']),
    originalRelics: countKeyword(original, ['expedition'], ['relic']),
    branchRelics: countKeyword(branch, ['expedition'], ['relic']),
    originalSabotage: countReplayCategory(original, ['sabotage']),
    branchSabotage: countReplayCategory(branch, ['sabotage']),
    originalLoans: countKeyword(original, ['treasury_event', 'human_action'], ['loan']),
    branchLoans: countKeyword(branch, ['treasury_event', 'human_action'], ['loan']),
    originalBankruptcy: countKeyword(original, ['failed_action', 'match_result'], ['bankrupt']),
    branchBankruptcy: countKeyword(branch, ['failed_action', 'match_result'], ['bankrupt']),
    originalAiEfficiency: aiEfficiency(original),
    branchAiEfficiency: aiEfficiency(branch),
    originalAutoModeInterventions: countReplayCategory(original, ['auto_mode_package_applied', 'auto_mode_evaluation', 'auto_mode_proposal_submitted', 'auto_mode_proposal_resolved', 'auto_mode_package_rolled_back']),
    branchAutoModeInterventions: countReplayCategory(branch, ['auto_mode_package_applied', 'auto_mode_evaluation', 'auto_mode_proposal_submitted', 'auto_mode_proposal_resolved', 'auto_mode_package_rolled_back']),
    originalDirectorInterventions: countReplayCategory(original, ['director_event', 'director_evaluation']),
    branchDirectorInterventions: countReplayCategory(branch, ['director_event', 'director_evaluation']),
    rngDivergenceNote: rngDiv ? rngDiv.explanation : 'No RNG divergence'
  };
};

// MILESTONE 5: HEADLESS REPLAY ENGINE, STATE HASHING & MATCH BRANCHING

export interface ReplayDivergencePoint {
  turn: number;
  day: number;
  actionAttemptId: string;
  expectedStateHash?: string;
  actualStateHash?: string;
  mismatchedField?: string;
  expectedHash?: string;
  actualHash?: string;
  summary?: string;
  eventIndex?: number;
  policy?: ReplayPolicy | string;
}
export interface ReplayExecutionReport {
  success: boolean;
  matchId?: string;
  policy?: ReplayPolicy | string;
  totalEventsProcessed?: number;
  totalEventsReexecuted?: number;
  firstDivergence: ReplayDivergencePoint | null;
  allDivergencePoints: ReplayDivergencePoint[];
  divergencePoints?: ReplayDivergencePoint[];
  finalStateHash: string;
  executionTimeMs?: number;
  reconstructedCheckpoints: any[];
  executionLogs?: string[];
  summary?: any;
}

export interface ReplaySimulationStateContext {
  currentSimState: any;
  simTeams: Record<string, any>;
  simActors: Record<string, any>;
  simTerritories: Record<string, any>;
  simRng?: GameplayRngRegistry;
  counters?: DeterministicCounters;
}

function createGameActionFromReplayEvent(ev: ReplayEvent | any): GameAction {
  const payload = ev?.payload || {};
  const canonicalPayload = extractCanonicalActionPayload(payload, ev);

  let rawType = canonicalPayload.actionType || '';
  const cat = ev?.category || payload?.category || '';
  const eventType = ev?.eventType || payload?.eventType || '';
  if (!rawType) {
    if (eventType === 'copilot_takeover_action_executed' || cat === 'copilot_takeover_action_executed') {
      rawType = payload?.actionExecutedDetails?.actionType || canonicalPayload.actionType || 'copilot_action';
    } else if (
      cat === 'copilot_event' ||
      eventType.startsWith('copilot_') ||
      cat.startsWith('copilot_')
    ) {
      rawType = 'copilot_telemetry_noop';
    } else if (cat === 'day_transition' || cat === 'turn_lifecycle' || String(ev?.summary || '').toLowerCase().includes('day transition') || String(ev?.summary || '').toLowerCase().includes('turn start')) {
      rawType = 'end_turn';
    } else if (cat === 'ai_decision' || cat === 'ai_execution') {
      rawType = 'ai_action';
    } else if (cat) {
      rawType = cat;
    } else {
      rawType = 'unknown';
    }
  }

  const actorId = ev?.actorId || payload.actorId || 'player';
  const teamId = ev?.teamId || payload.teamId || (actorId === 'player' ? 'team_player' : 'team_ai');
  return {
    type: rawType,
    actorId,
    teamId,
    payload: canonicalPayload,
    parameters: { ...canonicalPayload },
    targetRegion: canonicalPayload.targetRegion,
    investmentAmount: canonicalPayload.investmentAmount,
    item: canonicalPayload.item,
    price: canonicalPayload.price,
    targetActorId: canonicalPayload.targetActorId,
    decisionId: canonicalPayload.decisionId,
    overrideCode: canonicalPayload.overrideCode
  };
}

export function applyReplayEventReducer(
  ctx: ReplaySimulationStateContext | any,
  ev: ReplayEvent | GameAction | any
): any {
  let simCtx: ReplaySimulationStateContext;
  if (ctx && typeof ctx === 'object' && 'currentSimState' in ctx && ctx.currentSimState) {
    simCtx = ctx as ReplaySimulationStateContext;
  } else {
    simCtx = {
      currentSimState: ctx,
      simTeams: ctx?.teamsById || ctx?.teamStateMap || {},
      simActors: ctx?.actorsById || {},
      simTerritories: ctx?.regions || ctx?.territoryStateMap || {}
    };
  }

  const action = (ev?.type && ev?.actorId && !ev?.category) ? (ev as GameAction) : createGameActionFromReplayEvent(ev);
  // AUDIT-BUG-014: Ensure action.payload is never undefined to prevent TypeError in sub-reducers
  if (action && !action.payload) {
    (action as FlexibleAction).payload = {};
  }

  if (ev?.day && ev.day > (simCtx.currentSimState.day || 0)) {
    simCtx.currentSimState.day = ev.day;
  }
  if (ev?.turn && ev.turn > (simCtx.currentSimState.turnCounter || simCtx.currentSimState.turn || 0)) {
    simCtx.currentSimState.turn = ev.turn;
    simCtx.currentSimState.turnCounter = ev.turn;
  }

  const simExecCtx: ActionExecutionContext = {
    active: true,
    operation: action.type,
    actionAttemptId: (ev?.payload?.actionAttemptId as string) || (ev?.payload?.decisionId as string) || ev?.id || 'replay_event',
    actorId: action.actorId,
    teamId: action.teamId
  };

  const result = reduceGameAction(simCtx.currentSimState, action, simExecCtx);
  simCtx.currentSimState = result.nextState;
  incrementDeterministicCounter('replayActionsExecuted');

  if (simCtx.simTeams && result.nextState.teamsById) {
    Object.assign(simCtx.simTeams, result.nextState.teamsById);
  }
  if (simCtx.simActors && result.nextState.actorsById) {
    Object.assign(simCtx.simActors, result.nextState.actorsById);
  }
  if (simCtx.simTerritories && result.nextState.regions) {
    Object.assign(simCtx.simTerritories, result.nextState.regions);
  }

  return simCtx;
}

function runReplaySimulationStep(
  currentState: ReplaySimulationStateContext | any,
  action: ReplayEvent | GameAction | any
): any {
  return applyReplayEventReducer(currentState, action);
}

function simulateReplayHead(
  initialStateOrCtx: any,
  events: (ReplayEvent | any)[],
  targetIndex?: number
): ReplaySimulationStateContext | any {
  let simCtx: ReplaySimulationStateContext;
  if (initialStateOrCtx && typeof initialStateOrCtx === 'object' && 'currentSimState' in initialStateOrCtx && initialStateOrCtx.currentSimState) {
    simCtx = initialStateOrCtx as ReplaySimulationStateContext;
  } else {
    simCtx = {
      currentSimState: initialStateOrCtx,
      simTeams: initialStateOrCtx?.teamsById || initialStateOrCtx?.teamStateMap || {},
      simActors: initialStateOrCtx?.actorsById || {},
      simTerritories: initialStateOrCtx?.regions || initialStateOrCtx?.territoryStateMap || {}
    };
  }

  const limit = typeof targetIndex === 'number' && targetIndex >= 0 ? Math.min(events.length, targetIndex) : events.length;
  for (let i = 0; i < limit; i++) {
    simCtx = applyReplayEventReducer(simCtx, events[i]);
  }
  return simCtx;
}

export function reexecuteReplayMatch(
  replayData: ReplayFile | string | unknown,
  policyInput?: ReplayPolicy | string
): ReplayExecutionReport {
  let file: ReplayFile | null = null;
  if (typeof replayData === 'string') {
    try {
      file = migrateReplayFile(JSON.parse(replayData));
    } catch {
      file = null;
    }
  } else if (replayData && typeof replayData === 'object') {
    file = migrateReplayFile(replayData) || (replayData as ReplayFile);
  }

  const policyStr = String(policyInput || 'strict').toLowerCase();
  let policy: ReplayPolicy = 'strict';
  if (policyStr.includes('skip')) policy = 'skip_invalid';
  else if (policyStr.includes('adaptive')) policy = 'adaptive_fallback';
  else if (policyStr.includes('force')) policy = 'force_reconstruction';
  else policy = 'strict';

  if (!file || !file.matchId || !Array.isArray(file.events)) {
    return {
      success: false,
      matchId: file?.matchId || 'invalid_file',
      policy,
      totalEventsProcessed: 0,
      firstDivergence: {
        day: 0,
        turn: 0,
        actionAttemptId: 'init',
        expectedHash: 'valid_replay_file',
        actualHash: 'invalid_or_corrupt_replay_file',
        eventIndex: -1,
        summary: 'Replay file format invalid or failed checksum verification.',
        policy
      },
      allDivergencePoints: [],
      finalStateHash: '00000000',
      reconstructedCheckpoints: [],
      executionLogs: ['Failed to load replay file for re-execution.']
    };
  }

  const logs: string[] = [];
  logs.push(`Starting headless re-execution engine for Match ${file.matchId} under policy "${policy}".`);

  const config = file.initialConfig;
  const simRng = new GameplayRngRegistry(config?.worldSeed || 1337);
  simRng.initStreams(config?.worldSeed || 1337);
  if (config?.rngRegistryState && typeof simRng.importStreamStates === 'function') {
    simRng.importStreamStates(config.rngRegistryState);
  }
  const recordedChaosQueue = (file.randomDraws || []).map(draw => draw.value).filter((v): v is number => typeof v === 'number');
  if (recordedChaosQueue.length > 0) {
    logs.push(`Loaded ${recordedChaosQueue.length} recorded random draws for recorded-chaos / hybrid playback.`);
  }

  const simTeams: Record<string, { money: number; netWorth: number; treasuryBalance: number; vaultProtectedCash: number; controlledRegions: string[] }> = {};
  if (config?.teamsById && Object.keys(config.teamsById).length > 0) {
    Object.keys(config.teamsById).forEach(tId => {
      const t = config.teamsById[tId] as FlexibleTeamState;
      simTeams[tId] = {
        money: t?.money ?? 10000,
        netWorth: t?.netWorth ?? 10000,
        treasuryBalance: t?.treasuryBalance ?? 0,
        vaultProtectedCash: t?.vaultProtectedCash ?? 0,
        controlledRegions: Array.isArray(t?.controlledRegions) ? [...t.controlledRegions] : []
      };
    });
  } else {
    simTeams['team_player'] = { money: 10000, netWorth: 10000, treasuryBalance: 0, vaultProtectedCash: 0, controlledRegions: ['NSW'] };
    simTeams['team_ai'] = { money: 10000, netWorth: 10000, treasuryBalance: 0, vaultProtectedCash: 0, controlledRegions: ['VIC'] };
  }

  const simActors: Record<string, { money: number; netWorth: number; region: string; actionsUsedThisTurn: number; riskScore: number; creditScore: number; inventory: Record<string, number> }> = {};
  if (config?.actorsById && Object.keys(config.actorsById).length > 0) {
    Object.keys(config.actorsById).forEach(aId => {
      const a = config.actorsById[aId] as ActorState;
      simActors[aId] = {
        money: a?.money ?? 10000,
        netWorth: a?.netWorth ?? 10000,
        region: a?.region || (aId === 'ai' ? 'VIC' : 'NSW'),
        actionsUsedThisTurn: 0,
        riskScore: a?.riskScore ?? 0,
        creditScore: a?.creditScore ?? 700,
        inventory: a?.inventory ? { ...(a.inventory as unknown as Record<string, number>) } : {}
      };
    });
  } else {
    simActors['player'] = { money: 10000, netWorth: 10000, region: 'NSW', actionsUsedThisTurn: 0, riskScore: 0, creditScore: 700, inventory: {} };
    simActors['ai'] = { money: 10000, netWorth: 10000, region: 'VIC', actionsUsedThisTurn: 0, riskScore: 0, creditScore: 700, inventory: {} };
  }

  const simTerritories: Record<string, { ownerId: string; developmentLevel: number; buildingCount: number }> = {};
  ['NSW', 'VIC', 'QLD', 'SA', 'WA', 'TAS', 'NT', 'ACT'].forEach(rId => {
    simTerritories[rId] = {
      ownerId: rId === 'NSW' ? 'team_player' : (rId === 'VIC' ? 'team_ai' : ''),
      developmentLevel: 1,
      buildingCount: 0
    };
  });

  let currentSimState: any = {
    day: 1,
    turnCounter: 1,
    currentTurn: 'player',
    activePlayer: 'player',
    season: 'Summer',
    economicPhase: 'normal',
    teamStateMap: simTeams,
    teamsById: simTeams,
    actorsById: simActors,
    player: simActors['player'] || { money: 10000, netWorth: 10000, region: 'NSW', actionsUsedThisTurn: 0 },
    territoryStateMap: simTerritories,
    regions: simTerritories,
    activeEvents: []
  };

  const simCtx: ReplaySimulationStateContext = {
    currentSimState,
    simTeams,
    simActors,
    simTerritories,
    simRng
  };

  const allDivergencePoints: ReplayDivergencePoint[] = [];
  const reconstructedCheckpoints: any[] = [];
  let totalEventsProcessed = 0;
  let halted = false;

  for (let idx = 0; idx < file.events.length; idx++) {
    if (halted) break;
    const ev = file.events[idx];
    totalEventsProcessed++;

    // Pre-event snapshot for SKIP_INVALID rollback (State + PRNG Streams)
    const preSimStateSnapshot = JSON.parse(JSON.stringify(currentSimState));
    const preRngStreamSnapshot: Record<string, { drawCount: number; currentState: number; xoshiroState: [number, number, number, number]; rollingHash: number }> = {};

    if (simRng && simRng.streams) {
      for (const domainKey in simRng.streams) {
        const st = simRng.streams[domainKey as RngScopeDomain];
        if (st) {
          preRngStreamSnapshot[domainKey] = {
            drawCount: st.drawCount,
            currentState: st.currentState,
            xoshiroState: st.xoshiroState ? [...st.xoshiroState] as [number, number, number, number] : [0, 0, 0, 0],
            rollingHash: st.rollingHash
          };
        }
      }
    }

    const action = createGameActionFromReplayEvent(ev);
    const actorId = action.actorId;
    const payload = ev.payload || {};

    applyReplayEventReducer(simCtx, ev);
    currentSimState = simCtx.currentSimState;

    const actualHash = computeCanonicalStateHash(currentSimState);
    const expectedHash = ev.stateHash || (payload.stateHash as string) || '';

    let isDivergent = false;
    let expectedHashForComparison = expectedHash;

    if (expectedHash && expectedHash !== actualHash) {
      isDivergent = true;
         const divPoint: ReplayDivergencePoint = {
        day: ev.day,
        turn: ev.turn,
        actionAttemptId: (payload.actionAttemptId as string) || (payload.decisionId as string) || ev.id,
        expectedStateHash: expectedHashForComparison || 'expected_hash_unspecified',
        actualStateHash: actualHash,
        expectedHash: expectedHashForComparison || 'expected_hash_unspecified',
        actualHash,
        mismatchedField: ev.summary || 'state_hash_mismatch',
        eventIndex: idx,
        summary: ev.summary || `Divergence at sequence ${ev.sequence}`,
        policy
      };
    }

    const matchingCheckpoint = file.checkpoints.find(cp => cp.sequence === ev.sequence);
    if (matchingCheckpoint) {
      if (matchingCheckpoint.expectedStateHash && matchingCheckpoint.expectedStateHash !== actualHash) {
        isDivergent = true;
        if (!expectedHashForComparison) expectedHashForComparison = matchingCheckpoint.expectedStateHash;
      }
      if (matchingCheckpoint.expectedState?.moneyByTeam) {
        const expTeamMoney = matchingCheckpoint.expectedState.moneyByTeam;
        for (const tId in expTeamMoney) {
          if (simTeams[tId] && Math.abs(simTeams[tId].money - expTeamMoney[tId]) > 1.0) {
            isDivergent = true;
            if (!expectedHashForComparison) expectedHashForComparison = `team_${tId}_exp_$${expTeamMoney[tId]}`;
          }
        }
      }
    }

    if (isDivergent) {
      const divPoint: ReplayDivergencePoint = {
        day: ev.day,
        turn: ev.turn,
        actionAttemptId: (payload.actionAttemptId as string) || (payload.decisionId as string) || ev.id,
        expectedHash: expectedHashForComparison || 'expected_hash_unspecified',
        actualHash,
        eventIndex: idx,
        summary: ev.summary || `Divergence at sequence ${ev.sequence}`,
        policy
      };
      allDivergencePoints.push(divPoint);
      logs.push(`[${policy.toUpperCase()}] Divergence at Day ${ev.day}, Turn ${ev.turn} (Action: ${divPoint.actionAttemptId}): expected [${divPoint.expectedHash}], actual [${divPoint.actualHash}].`);

      if (policy === 'strict') {
        logs.push(`STRICT policy active. Halting re-execution at event index ${idx}.`);
        halted = true;
        break;
      } 
      else if (policy === 'skip_invalid') {
        logs.push(`SKIP_INVALID policy active. Reverting partial event mutations and PRNG stream states, skipping event index ${idx}.`);
        currentSimState = preSimStateSnapshot;
        Object.assign(simTeams, currentSimState.teamStateMap);
        Object.assign(simActors, currentSimState.actorsById);
        Object.assign(simTerritories, currentSimState.territoryStateMap);
        
        // Revert PRNG stream draw counts and internal states
        if (simRng && simRng.streams) {
          for (const domainKey in preRngStreamSnapshot) {
            const snap = preRngStreamSnapshot[domainKey];
            const st = simRng.streams[domainKey as RngScopeDomain];
            if (st && snap) {
              st.drawCount = snap.drawCount;
              st.currentState = snap.currentState;
              st.xoshiroState = [...snap.xoshiroState];
              st.rollingHash = snap.rollingHash;
            }
          }
        }
      } 
      else if (policy === 'adaptive_fallback') {
        logs.push(`ADAPTIVE_FALLBACK policy active. Synchronizing simulation state and all PRNG stream draw counts to recorded expected deltas at event index ${idx}.`);
        if (matchingCheckpoint?.expectedState?.moneyByTeam) {
          for (const tId in matchingCheckpoint.expectedState.moneyByTeam) {
            if (simTeams[tId]) simTeams[tId].money = matchingCheckpoint.expectedState.moneyByTeam[tId];
          }
        }
        if (payload.expectedMoney !== undefined && simActors[actorId]) {
          simActors[actorId].money = Number(payload.expectedMoney);
        }
        
        // Resynchronize ALL PRNG streams present in ev.rngAudit.streamAuditSnapshots
        if (ev.rngAudit?.streamAuditSnapshots) {
          for (const streamName of Object.keys(ev.rngAudit.streamAuditSnapshots)) {
            const snap = ev.rngAudit.streamAuditSnapshots[streamName];
            if (snap && typeof snap.drawCount === 'number') {
              const expectedDraws = snap.drawCount;
              const stream = simRng.streams[streamName as RngScopeDomain];
              if (stream) {
                while (stream.drawCount < expectedDraws) {
                  simRng.draw(streamName as RngScopeDomain);
                }
              }
            }
          }
        }
      } 
      else if (policy === 'force_reconstruction') {
        logs.push(`FORCE_RECONSTRUCTION policy active. Forcing full state and PRNG stream hydration from nearest recorded checkpoint.`);
        const nearestCheckpoint = [...file.checkpoints]
          .filter(cp => cp.sequence <= ev.sequence)
          .sort((a, b) => b.sequence - a.sequence)[0];

        if (nearestCheckpoint?.fullStateSnapshot) {
          const snap = nearestCheckpoint.fullStateSnapshot;
          if (snap.actorsById) Object.assign(simActors, snap.actorsById);
          if (snap.teamsById) Object.assign(simTeams, snap.teamsById);
          if ((snap.gameState as ExtendedGameState)?.regions) Object.assign(simTerritories, (snap.gameState as ExtendedGameState).regions);
          currentSimState.day = snap.gameState?.day || nearestCheckpoint.day || currentSimState.day;
          currentSimState.turnCounter = snap.gameState?.turnCounter || nearestCheckpoint.turn || currentSimState.turnCounter;
          if (snap.aiRuntime) {
            simRng.initStreams(config?.worldSeed || 1337);
            const aiDraws = snap.aiRuntime.rngState || 0;
            for (let i = 0; i < aiDraws; i++) simRng.draw('AIReasoning');
            const worldDraws = snap.aiRuntime.worldRngState || 0;
            for (let i = 0; i < worldDraws; i++) simRng.draw('World');
          }
        } else if (matchingCheckpoint?.expectedState?.moneyByTeam) {
          for (const tId in matchingCheckpoint.expectedState.moneyByTeam) {
            if (simTeams[tId]) simTeams[tId].money = matchingCheckpoint.expectedState.moneyByTeam[tId];
          }
        } else if (payload.moneyByTeam && typeof payload.moneyByTeam === 'object') {
          Object.assign(simTeams, payload.moneyByTeam as Record<string, any>);
        }
      }
    }

    if (matchingCheckpoint) {
      reconstructedCheckpoints.push({
        ...matchingCheckpoint,
        expectedStateHash: actualHash
      });
    }
  }

  const finalStateHash = computeCanonicalStateHash(currentSimState);
  logs.push(`Re-execution finished. Processed ${totalEventsProcessed} / ${file.events.length} events. Final state hash: [${finalStateHash}].`);

  return {
    success: allDivergencePoints.length === 0,
    policy,
    matchId: file.matchId,
    totalEventsProcessed,
    firstDivergence: allDivergencePoints[0] || null,
    allDivergencePoints,
    finalStateHash,
    reconstructedCheckpoints,
    executionLogs: logs
  };
}

export function createMatchCheckpoint(
  gameState: any,
  kind: ReplayCheckpointKind = 'day',
  label?: string,
  relatedId?: string
): ReplayCheckpoint {
  const day = gameState?.day ?? gameState?.gameState?.day ?? 1;
  const turn = gameState?.turnCounter ?? gameState?.turn ?? gameState?.gameState?.turnCounter ?? 1;
  const moneyByTeam: Record<string, number> = {};
  if (gameState?.teamStateMap) {
    Object.keys(gameState.teamStateMap).forEach(tId => {
      moneyByTeam[tId] = gameState.teamStateMap[tId]?.money ?? 0;
    });
  } else if (gameState?.teamsById) {
    Object.keys(gameState.teamsById).forEach(tId => {
      moneyByTeam[tId] = gameState.teamsById[tId]?.money ?? 0;
    });
  } else if (gameState?.player) {
    moneyByTeam['team_player'] = gameState.player.money ?? 0;
  }

  const expectedStateHash = computeCanonicalStateHash(gameState);
  const counters: DeterministicCounters = JSON.parse(
    JSON.stringify(gameState?.deterministicCounters || gameState?.counters || globalDeterministicCounters)
  );
  const cpId = nextCheckpointId(counters);

  const rngRegistry = gameState?.rngRegistry || globalRngRegistry;
  const rngMasterSeed = rngRegistry?.masterSeed ?? gameState?.rng?.masterSeed ?? 1337;
  const streamStates = (rngRegistry && typeof rngRegistry.exportStreamStates === 'function') ? rngRegistry.exportStreamStates() : globalRngRegistry.exportStreamStates();

  const fullStateSnapshot: SaveGameData = canonicalStateFromLiveRuntime(gameState) as unknown as SaveGameData;
  if (!fullStateSnapshot.metadata) {
    fullStateSnapshot.metadata = {
      timestamp: Date.now(),
      gameVersion: VERSION_CONSTANTS.GAME_VERSION,
      saveDescription: label || `Checkpoint Day ${day} (Turn ${turn})`,
      schemaVersion: VERSION_CONSTANTS.SAVE_SCHEMA_VERSION,
      versionConstants: VERSION_CONSTANTS
    };
  }
  fullStateSnapshot.rngRegistryState = streamStates;
  fullStateSnapshot.deterministicCounters = counters;
  fullStateSnapshot.aiRuntime = {
    queue: [],
    currentAction: null,
    rngMasterSeed,
    streamStates,
    rngState: streamStates['AIReasoning']?.currentState || streamStates['AIReasoning']?.streamSeed || 0,
    worldRngState: streamStates['World']?.currentState || streamStates['World']?.streamSeed || 0
  };

  return {
    id: cpId,
    sequence: gameState?.gameActivityLedger?.events?.length ?? 0,
    day,
    turn,
    label: label || `Checkpoint Day ${day} (Turn ${turn})`,
    kind,
    relatedId,
    expectedState: {
      moneyByTeam,
      day,
      turn
    },
    expectedStateHash,
    fullStateSnapshot,
    timestamp: Date.now()
  };
}

export function spawnMatchBranchFromCheckpoint(
  checkpoint: ReplayCheckpoint,
  sourceReplayFile?: ReplayFile,
  overrides?: Partial<GameSettingsState>
): SaveGameData {
  const day = checkpoint.day || 1;
  const turn = checkpoint.turn || 1;
  const config = sourceReplayFile?.initialConfig;

  // PRIORITY 1: Direct Snapshot Hydration from checkpoint.fullStateSnapshot
  if (checkpoint.fullStateSnapshot) {
    const saveData: SaveGameData = JSON.parse(JSON.stringify(checkpoint.fullStateSnapshot));
    saveData.metadata = {
      ...saveData.metadata,
      timestamp: Date.now(),
      gameVersion: VERSION_CONSTANTS.GAME_VERSION,
      saveDescription: `Branch from checkpoint ${checkpoint.id} (Day ${day}, Turn ${turn})`,
      schemaVersion: VERSION_CONSTANTS.SAVE_SCHEMA_VERSION,
      versionConstants: VERSION_CONSTANTS
    };
    if (sourceReplayFile?.matchId) {
      saveData.metadata.branchedFromMatchId = sourceReplayFile.matchId;
    }
    if (overrides) {
      saveData.gameSettings = { ...(saveData.gameSettings || {}), ...overrides };
    }
    return saveData;
  }

  // PRIORITY 2: Fast-forward roll-forward re-simulation from sequence 0 up to checkpoint.sequence
  if (sourceReplayFile && Array.isArray(sourceReplayFile.events)) {
    const simRng = new GameplayRngRegistry(config?.worldSeed || 1337);
    simRng.initStreams(config?.worldSeed || 1337);

    const simTeams: Record<string, TeamState> = {};
    if (config?.teamsById && Object.keys(config.teamsById).length > 0) {
      Object.keys(config.teamsById).forEach(tId => {
        const t = config.teamsById[tId];
        simTeams[tId] = JSON.parse(JSON.stringify(t));
      });
    } else {
      simTeams['team_player'] = { id: 'team_player', name: 'Player Team', money: 10000, netWorth: 10000, treasuryBalance: 0, vaultProtectedCash: 0, controlledRegions: ['NSW'] } as unknown as TeamState;
      simTeams['team_ai'] = { id: 'team_ai', name: 'AI Team', money: 10000, netWorth: 10000, treasuryBalance: 0, vaultProtectedCash: 0, controlledRegions: ['VIC'] } as unknown as TeamState;
    }

    const simActors: Record<string, ActorState> = {};
    if (config?.actorsById && Object.keys(config.actorsById).length > 0) {
      Object.keys(config.actorsById).forEach(aId => {
        const a = config.actorsById[aId] as ActorState;
        simActors[aId] = JSON.parse(JSON.stringify(a));
      });
    } else {
      simActors['player'] = { id: 'player', name: 'Player', money: 10000, netWorth: 10000, region: 'NSW', actionsUsedThisTurn: 0, riskScore: 0, creditScore: 700, inventory: {} } as unknown as ActorState;
      simActors['ai'] = { id: 'ai', name: 'AI Opponent', money: 10000, netWorth: 10000, region: 'VIC', actionsUsedThisTurn: 0, riskScore: 0, creditScore: 700, inventory: {} } as unknown as ActorState;
    }

    const simTerritories: Record<string, any> = {};
    ['NSW', 'VIC', 'QLD', 'SA', 'WA', 'TAS', 'NT', 'ACT'].forEach(rId => {
      simTerritories[rId] = {
        id: rId,
        name: rId,
        ownerId: rId === 'NSW' ? 'team_player' : (rId === 'VIC' ? 'team_ai' : ''),
        developmentLevel: 1,
        buildingCount: 0,
        buildings: []
      } as unknown as ReplayCheckpoint;
    });

    let simDay = 1;
    let simTurn = 1;

    let currentSimState: any = {
      day: simDay,
      turnCounter: simTurn,
      currentTurn: simTurn,
      activePlayer: 'player',
      season: 'Summer',
      economicPhase: 'normal',
      teamStateMap: simTeams,
      teamsById: simTeams,
      actorsById: simActors,
      player: simActors['player'],
      territoryStateMap: simTerritories,
      regions: simTerritories,
      activeEvents: []
    };

    const simCtx: ReplaySimulationStateContext = {
      currentSimState,
      simTeams,
      simActors,
      simTerritories,
      simRng,
      counters: config?.deterministicCounters ? { ...createInitialDeterministicCounters(), ...config.deterministicCounters } : undefined
    };

    const targetSeq = checkpoint.sequence ?? Infinity;
    const eventsToSimulate = sourceReplayFile.events.filter(ev => ev.sequence <= targetSeq);
    simulateReplayHead(simCtx, eventsToSimulate);
    currentSimState = simCtx.currentSimState;

    if (checkpoint.expectedState?.moneyByTeam) {
      for (const tId in checkpoint.expectedState.moneyByTeam) {
        if (simTeams[tId]) {
          (simTeams[tId] as FlexibleTeamState).money = checkpoint.expectedState.moneyByTeam[tId];
        }
      }
    }

    const playerState = simActors['player'] || { id: 'player', name: 'Player', money: 10000, netWorth: 10000, region: 'NSW', actionsUsedThisTurn: 0, riskScore: 0, creditScore: 700, inventory: {} } as unknown as ActorState;
    const aiState = simActors['ai'] || { id: 'ai', name: 'AI Opponent', money: 10000, netWorth: 10000, region: 'VIC', actionsUsedThisTurn: 0, riskScore: 0, creditScore: 700, inventory: {} } as unknown as ActorState;

    const saveData: SaveGameData = {
      metadata: {
        timestamp: Date.now(),
        gameVersion: VERSION_CONSTANTS.GAME_VERSION,
        saveDescription: `Branch from checkpoint ${checkpoint.id} (Day ${day})`,
        schemaVersion: VERSION_CONSTANTS.SAVE_SCHEMA_VERSION,
        versionConstants: VERSION_CONSTANTS,
        branchedFromMatchId: sourceReplayFile.matchId
      },
      player: playerState,
      aiPlayer: aiState,
      actorsById: simActors,
      teamsById: simTeams,
      gameState: {
        ...initialGameState,
        day,
        turnCounter: checkpoint.turn || simTurn || 1,
        selectedMode: config?.selectedMode || 'solo',
        aiDifficulty: config?.aiDifficulty || 'medium',
        regions: simTerritories
      } as GameStateSnapshot,
      gameSettings: { ...(config?.gameSettings || {}), ...overrides } as GameSettingsState,
      notifications: [],
      personalRecords: { ...DEFAULT_PERSONAL_RECORDS },
      dontAskAgain: { ...DEFAULT_DONT_ASK },
      humanAutomations: [],
      uiPreferences: { theme: 'dark' },
      aiRuntime: {
        queue: [],
        currentAction: null,
        rngState: simRng.streams['AIReasoning']?.drawCount || normalizeAiSeed(config?.aiSeed || 1337),
        worldRngState: simRng.streams['World']?.drawCount || normalizeAiSeed(config?.worldSeed || 1337)
      },
      rngRegistryState: simRng ? simRng.exportStreamStates() : undefined,
      deterministicCounters: simCtx?.counters ? { ...createInitialDeterministicCounters(), ...simCtx.counters } : undefined
    };

    return saveData;
  }

  // FALLBACK (If sourceReplayFile is not provided)
  let playerState: any = config?.actorsById?.player || { money: 10000, netWorth: 10000, region: 'NSW' };
  let aiState: any = config?.actorsById?.ai || { money: 10000, netWorth: 10000, region: 'VIC' };

  if (checkpoint.expectedState?.moneyByTeam) {
    const pMoney = checkpoint.expectedState.moneyByTeam['team_player'];
    if (typeof pMoney === 'number') playerState = { ...playerState, money: pMoney };
    const aiMoney = checkpoint.expectedState.moneyByTeam['team_ai'];
    if (typeof aiMoney === 'number') aiState = { ...aiState, money: aiMoney };
  }

  const saveData: SaveGameData = {
    metadata: {
      timestamp: Date.now(),
      gameVersion: VERSION_CONSTANTS.GAME_VERSION,
      saveDescription: `Branch from checkpoint ${checkpoint.id} (Day ${day})`,
      schemaVersion: VERSION_CONSTANTS.SAVE_SCHEMA_VERSION,
      versionConstants: VERSION_CONSTANTS,
      branchedFromMatchId: sourceReplayFile?.matchId
    },
    player: playerState,
    aiPlayer: aiState,
    actorsById: config?.actorsById || { player: playerState, ai: aiState },
    teamsById: config?.teamsById || {},
    gameState: {
      ...initialGameState,
      day,
      turnCounter: checkpoint.turn || 1,
      selectedMode: config?.selectedMode || 'solo',
      aiDifficulty: config?.aiDifficulty || 'medium'
    } as GameStateSnapshot,
    gameSettings: { ...(config?.gameSettings || {}), ...overrides } as GameSettingsState,
    notifications: [],
    personalRecords: { ...DEFAULT_PERSONAL_RECORDS },
    dontAskAgain: { ...DEFAULT_DONT_ASK },
    humanAutomations: [],
    uiPreferences: { theme: 'dark' },
    aiRuntime: {
      queue: [],
      currentAction: null,
      rngState: normalizeAiSeed(config?.aiSeed || 1337),
      worldRngState: normalizeAiSeed(config?.worldSeed || 1337)
    },
    rngRegistryState: globalRngRegistry.exportStreamStates(),
    deterministicCounters: { ...globalDeterministicCounters }
  };

  return saveData;
}

// MILESTONE 6: PHASES 15, 17, 18 TYPES & PURE LOGIC FUNCTIONS

// --- Phase 15: Replay Comparison ---
export type DivergenceReasonCategory =
  | 'deterministic_desync'
  | 'seed_mismatch'
  | 'version_incompatibility'
  | 'rule_divergence'
  | 'state_corruption'
  | 'unknown';

export interface NormalizedComparisonEvent {
  id?: string;
  actionType?: string;
  payloadSummary?: string;
  rawEvent?: any;
  sequence: number;
  day: number;
  turn: number;
  actorId: string | null;
  category: string;
  summary?: string;
  payloadHash?: string;
}

interface ReplayComparisonDiff {
  sequence: number;
  field: string;
  fileAValue: unknown;
  fileBValue: unknown;
  severity: 'minor' | 'major' | 'critical';
}

interface ReplayComparisonReport {
  matchIdA: string;
  matchIdB: string;
  isIdentical: boolean;
  firstDivergenceSequence: number | null;
  divergenceCategory: DivergenceReasonCategory;
  totalEventsA: number;
  totalEventsB: number;
  diffs: ReplayComparisonDiff[];
  summaryText: string;
}

export interface EventDivergenceDetail {
  sequence: number;
  day: number;
  turn: number;
  severity: 'minor' | 'major' | 'critical';
  category: ReplayDivergenceCategory;
  primaryEventSummary: string;
  secondaryEventSummary: string;
  divergenceExplanation: string;
}

interface ReplayComparisonOptions {
  toleranceThreshold?: number;
  ignoreMinorTiming?: boolean;
}

export interface StreamComparisonReport {
  matchAId: string;
  rngRegistryDivergence?: boolean;
  deterministicCountersDivergence?: boolean;
  matchBId: string;
  totalEventsCompared: number;
  divergenceCount: number;
  maxDivergenceSeverity: 'none' | 'minor' | 'major' | 'critical';
  divergenceDetails?: EventDivergenceDetail[];
  summaryScore?: number;
  isIdentical?: boolean;
  isWithinTolerance?: boolean;
  divergenceRate?: number;
  toleranceThreshold?: number;
  ignoreMinorTiming?: boolean;
  firstDivergenceSequence?: number | null;
  divergenceCategory?: string;
  totalEventsA?: number;
  totalEventsB?: number;
  diffs?: any[];
  summaryText?: string;
}

const normalizeLedgerEvent = (event: GameActivityLedgerEvent): NormalizedComparisonEvent => {
  const canonicalPayload = extractCanonicalActionPayload(event.payload, event);
  const actionType = String(canonicalPayload.actionType || event.eventType || (event.payload as Record<string, unknown>)?.actionType || 'unknown');
  return {
    id: event.id || `ledger-${event.sequenceId}`,
    sequence: event.sequenceId || 0,
    day: event.day || 1,
    turn: event.turn || 1,
    actorId: event.participants?.actorId || event.actorId || null,
    category: event.category || 'action',
    actionType,
    summary: event.summary || '',
    payloadHash: actionType
  };
};

export const normalizeReplayEvent = (event: ReplayEvent): NormalizedComparisonEvent => {
  const actionType = String(
    (event as unknown as Record<string, any>).actionType ||
    (event as unknown as Record<string, any>).type ||
    event.payload?.actionType ||
    'unknown'
  );
  return {
    id: event.id,
    sequence: event.sequence,
    day: event.day || 1,
    turn: event.turn || 1,
    actorId: event.actorId || null,
    category: event.category || 'action',
    actionType,
    summary: event.summary || '',
    payloadHash: actionType
  };
};

export const classifyEventDivergence = (
  evA: NormalizedComparisonEvent,
  evB: NormalizedComparisonEvent
): EventDivergenceDetail | null => {
  const rngRelated = evA.category === 'rng_draw' || evB.category === 'rng_draw' || String(evA.actionType).includes('rng') || String(evB.actionType).includes('rng');
  if (evA.category === evB.category && evA.actionType === evB.actionType && evA.actorId === evB.actorId) {
    if (evA.day !== evB.day || evA.turn !== evB.turn) {
      return {
        sequence: evA.sequence,
        day: evA.day,
        turn: evA.turn,
        severity: 'minor',
        category: 'timing_drift',
        primaryEventSummary: evA.summary || '',
        secondaryEventSummary: evB.summary || '',
        divergenceExplanation: `Timing drift: Event A (Day ${evA.day}, Turn ${evA.turn}) vs Event B (Day ${evB.day}, Turn ${evB.turn}).`
      };
    }
    if (rngRelated && evA.payloadHash !== evB.payloadHash) {
      return {
        sequence: evA.sequence,
        day: evA.day,
        turn: evA.turn,
        severity: 'major',
        category: 'rng_divergence',
        primaryEventSummary: evA.summary || '',
        secondaryEventSummary: evB.summary || '',
        divergenceExplanation: `RNG mismatch at sequence ${evA.sequence}.`
      };
    }
    return null;
  }

  let severity: 'minor' | 'major' | 'critical' = 'minor';
  let category: ReplayDivergenceCategory = 'payload_divergence';
  let explanation = '';

  if (evA.category !== evB.category) {
    severity = 'major';
    category = rngRelated ? 'rng_divergence' : 'action_divergence';
    explanation = `Category mismatch: Event A is '${evA.category}' while Event B is '${evB.category}'.`;
  } else if (evA.actorId !== evB.actorId) {
    severity = 'major';
    category = 'actor_divergence';
    explanation = `Actor mismatch: Event A actor '${evA.actorId || 'none'}' vs Event B actor '${evB.actorId || 'none'}'.`;
  } else if (evA.actionType !== evB.actionType) {
    severity = 'critical';
    category = rngRelated ? 'rng_divergence' : 'action_divergence';
    explanation = `Action divergence: Event A chose '${evA.actionType || 'N/A'}' while Event B chose '${evB.actionType || 'N/A'}'.`;
  } else {
    explanation = `Minor payload divergence between sequence ${evA.sequence} and ${evB.sequence}.`;
  }

  return {
    sequence: evA.sequence,
    day: evA.day,
    turn: evA.turn,
    severity,
    category,
    primaryEventSummary: evA.summary || '',
    secondaryEventSummary: evB.summary || '',
    divergenceExplanation: explanation
  };
};

export const compareLedgerEventStreams = (
  streamA: NormalizedComparisonEvent[],
  streamB: NormalizedComparisonEvent[],
  options?: ReplayComparisonOptions
): StreamComparisonReport => {
  const toleranceThreshold = options?.toleranceThreshold ?? 0.1;
  const ignoreMinorTiming = options?.ignoreMinorTiming ?? false;

  const comparedCount = Math.min(streamA.length, streamB.length);
  const divergenceDetails: EventDivergenceDetail[] = [];
  let maxDivergenceSeverity: 'none' | 'minor' | 'major' | 'critical' = 'none';

  const bump = (detail: EventDivergenceDetail) => {
    if (ignoreMinorTiming && (detail.severity === 'minor' || detail.category === 'timing_drift')) return;
    divergenceDetails.push(detail);
    if (detail.severity === 'critical') maxDivergenceSeverity = 'critical';
    else if (detail.severity === 'major' && maxDivergenceSeverity !== 'critical') maxDivergenceSeverity = 'major';
    else if (detail.severity === 'minor' && maxDivergenceSeverity === 'none') maxDivergenceSeverity = 'minor';
  };

  for (let i = 0; i < comparedCount; i++) {
    const detail = classifyEventDivergence(streamA[i], streamB[i]);
    if (detail) bump(detail);
  }
  if (streamA.length > streamB.length) {
    for (let i = comparedCount; i < streamA.length; i++) {
      bump({
        sequence: streamA[i].sequence,
        day: streamA[i].day,
        turn: streamA[i].turn,
        severity: 'major',
        category: 'event_missing',
        primaryEventSummary: streamA[i].summary || '',
        secondaryEventSummary: '',
        divergenceExplanation: `Event missing in Replay B at sequence ${streamA[i].sequence}: ${streamA[i].summary || streamA[i].category}.`
      });
    }
  } else if (streamB.length > streamA.length) {
    for (let i = comparedCount; i < streamB.length; i++) {
      bump({
        sequence: streamB[i].sequence,
        day: streamB[i].day,
        turn: streamB[i].turn,
        severity: 'major',
        category: 'event_extra',
        primaryEventSummary: '',
        secondaryEventSummary: streamB[i].summary || '',
        divergenceExplanation: `Extra event in Replay B at sequence ${streamB[i].sequence}: ${streamB[i].summary || streamB[i].category}.`
      });
    }
  }

  const matchAId = streamA[0]?.id || 'stream_a';
  const matchBId = streamB[0]?.id || 'stream_b';
  const divergenceCount = divergenceDetails.length;
  const divergenceRate = comparedCount > 0 ? divergenceCount / comparedCount : 0;
  const isWithinTolerance = divergenceRate <= toleranceThreshold;
  const summaryScore = comparedCount > 0 ? Math.max(0, Math.round(((comparedCount - divergenceCount) / comparedCount) * 100)) : 100;

  const summaryText = divergenceCount === 0
    ? 'Replay streams are identical.'
    : isWithinTolerance
      ? `Found ${divergenceCount} divergence(s) across ${comparedCount} events (within ${(toleranceThreshold * 100).toFixed(0)}% tolerance).`
      : `Found ${divergenceCount} divergence(s) across ${comparedCount} events (EXCEEDS ${(toleranceThreshold * 100).toFixed(0)}% tolerance threshold!).`;

  return {
    matchAId,
    matchBId,
    isIdentical: divergenceCount === 0,
    isWithinTolerance,
    divergenceRate,
    toleranceThreshold,
    ignoreMinorTiming,
    firstDivergenceSequence: divergenceDetails[0]?.sequence ?? null,
    divergenceCategory: divergenceDetails[0]?.category ?? 'unknown',
    totalEventsA: streamA.length,
    totalEventsB: streamB.length,
    totalEventsCompared: comparedCount,
    divergenceCount,
    maxDivergenceSeverity,
    divergenceDetails,
    summaryScore,
    diffs: divergenceDetails.map(d => ({
      sequence: d.sequence,
      field: d.category,
      fileAValue: d.primaryEventSummary,
      fileBValue: d.secondaryEventSummary,
      severity: d.severity
    })),
    summaryText
  };
};

// --- Phase 17: AI Effectiveness Scorecard ---
export interface AiComplianceRecord {
  totalDecisions: number;
  compliantCount: number;
  violationCount: number;
  complianceRate: number;
}

export interface AiDecisionOutcomeScore {
  day: number;
  turn: number;
  actorId: string;
  expectedRoi: number;
  actualRoi: number;
  roiDelta: number;
  classification: 'blunder' | 'suboptimal' | 'optimal' | 'brilliant';
}

export interface AiActorScorecard {
  actorId: string;
  actorName?: string;
  displayName: string;
  totalDecisions: number;
  overallEffectivenessScore: number;
  averageRoiDelta: number;
  blunderCount: number;
  brilliantCount: number;
  compliance: AiComplianceRecord;
  decisionScores: AiDecisionOutcomeScore[];
}

export interface AiScorecardSummaryReport {
  scorecardsByActor: Record<string, AiActorScorecard>;
  matchWideEffectivenessScore: number;
  topPerformingActorId: string | null;
  mostImprovedActorId: string | null;
}

export const classifyDecisionOutcome = (
  expectedRoi: number,
  actualRoi: number,
  blunderThreshold: number = -50
): 'blunder' | 'suboptimal' | 'optimal' | 'brilliant' => {
  const delta = actualRoi - expectedRoi;
  if (delta <= blunderThreshold) return 'blunder';
  if (delta < 0) return 'suboptimal';
  if (delta >= 50) return 'brilliant';
  return 'optimal';
};

export const calculateActorScorecard = (
  actorId: string,
  actorName: string,
  events: GameActivityLedgerEvent[]
): AiActorScorecard => {
  const safeEvents = Array.isArray(events) ? events : [];
  const actorEvents = safeEvents.filter(e => e.actorId === actorId || e.participants?.actorId === actorId || (e.actorId && e.actorId.startsWith(actorId)));

  if (actorEvents.length === 0) {
    return {
      actorId,
      actorName: actorName || actorId,
      displayName: actorName || actorId,
      totalDecisions: 0,
      overallEffectivenessScore: 0,
      averageRoiDelta: 0,
      blunderCount: 0,
      brilliantCount: 0,
      compliance: {
        totalDecisions: 0,
        compliantCount: 0,
        violationCount: 0,
        complianceRate: 0
      },
      decisionScores: []
    };
  }

  const decisionScores: AiDecisionOutcomeScore[] = actorEvents.map((ev, idx) => {
    const payload = (ev.payload as Record<string, unknown>) || {};
    const expectedRoi = typeof payload.expectedRoi === 'number' ? payload.expectedRoi : (typeof payload.confidence === 'number' ? payload.confidence : 50);
    const actualRoi = typeof payload.actualRoi === 'number' ? payload.actualRoi : (typeof payload.score === 'number' ? payload.score : (typeof payload.outcomeRoi === 'number' ? payload.outcomeRoi : expectedRoi));
    const roiDelta = actualRoi - expectedRoi;
    const classification = classifyDecisionOutcome(expectedRoi, actualRoi);

    return {
      day: ev.day || 1,
      turn: ev.turn || idx + 1,
      actorId,
      expectedRoi,
      actualRoi,
      roiDelta,
      classification
    };
  });

  const blunderCount = decisionScores.filter(s => s.classification === 'blunder').length;
  const brilliantCount = decisionScores.filter(s => s.classification === 'brilliant').length;
  const totalRoiDelta = decisionScores.reduce((sum, s) => sum + s.roiDelta, 0);
  const averageRoiDelta = Math.round(totalRoiDelta / decisionScores.length);

  const nonViolations = actorEvents.filter(e => !(e as unknown as Record<string, any>).isViolation && !(e.payload as unknown as Record<string, any>)?.isViolation);
  const compliantCount = nonViolations.length;
  const violationCount = actorEvents.length - compliantCount;
  const complianceRate = Math.round((compliantCount / actorEvents.length) * 100);

  const baseEffectiveness = Math.max(0, Math.min(100, Math.round(50 + averageRoiDelta * 0.5 + (brilliantCount * 10) - (blunderCount * 15))));
  const overallEffectivenessScore = Math.max(0, Math.min(100, Math.round((baseEffectiveness * 0.6) + (complianceRate * 0.4))));

  return {
    actorId,
    actorName: actorName || actorId,
    displayName: actorName || actorId,
    totalDecisions: actorEvents.length,
    overallEffectivenessScore,
    averageRoiDelta,
    blunderCount,
    brilliantCount,
    compliance: {
      totalDecisions: actorEvents.length,
      compliantCount,
      violationCount,
      complianceRate
    },
    decisionScores
  };
};

export const generateScorecardSummaryReport = (
  actors: Record<string, ActorState>,
  events: GameActivityLedgerEvent[],
  blunderThreshold: number = -50
): AiScorecardSummaryReport => {
  const scorecardsByActor: Record<string, AiActorScorecard> = {};
  let totalScore = 0;
  let actorCount = 0;
  let topActorId: string | null = null;
  let topScore = -1;

  Object.entries(actors || {}).forEach(([id, actor]) => {
    const sc = calculateActorScorecard(id, actor.displayName || actor.name || id, events);
    scorecardsByActor[id] = sc;
    totalScore += sc.overallEffectivenessScore;
    actorCount++;
    if (sc.overallEffectivenessScore > topScore) {
      topScore = sc.overallEffectivenessScore;
      topActorId = id;
    }
  });

  return {
    scorecardsByActor,
    matchWideEffectivenessScore: actorCount > 0 ? Math.round(totalScore / actorCount) : 100,
    topPerformingActorId: topActorId,
    mostImprovedActorId: topActorId
  };
};

// --- Phase 18: Balance Lab ---
export interface BalanceStressIndex {
  overallStressIndex: number;
  economicVolatiltyScore: number;
  runawayLeaderRisk: number;
  comebackFeasibilityScore: number;
  stalemateProbability: number;
}

export interface BalanceSandboxConfig {
  baselineId: string;
  rewardMultiplier: number;
  penaltyMultiplier: number;
  catchupBonusMultiplier: number;
  loanInterestMultiplier: number;
}

export interface BalanceSimulationResult {
  config: BalanceSandboxConfig;
  projectedWinTurnDelta: number;
  predictedRunawayReduction: number;
  predictedComebackIncrease: number;
  stressIndexDelta: number;
}

interface BalanceComparisonDelta {
  stressIndex: BalanceStressIndex;
  simulation: BalanceSimulationResult;
}

export const calculateBalanceStressIndex = (
  events: GameActivityLedgerEvent[],
  actors: Record<string, ActorState>
): BalanceStressIndex => {
  const actorList = Object.values(actors || {});
  if (actorList.length === 0) {
    return {
      overallStressIndex: 20,
      economicVolatiltyScore: 15,
      runawayLeaderRisk: 10,
      comebackFeasibilityScore: 75,
      stalemateProbability: 10
    };
  }

  const moneys = actorList.map(a => a.money || 1000);
  const maxM = Math.max(...moneys);
  const minM = Math.min(...moneys);
  const spread = maxM - Math.max(1, minM);
  const runawayRisk = Math.min(100, Math.round((spread / Math.max(1, maxM)) * 100));

  return {
    overallStressIndex: Math.round((runawayRisk + 30) / 2),
    economicVolatiltyScore: 25,
    runawayLeaderRisk: runawayRisk,
    comebackFeasibilityScore: Math.max(10, 100 - runawayRisk),
    stalemateProbability: 15
  };
};

const simulateBalanceSandbox = (
  config: BalanceSandboxConfig,
  events: GameActivityLedgerEvent[],
  actors: Record<string, ActorState>
): BalanceSimulationResult => {
  const currentStress = calculateBalanceStressIndex(events, actors);
  const catchupFactor = config.catchupBonusMultiplier || 1.0;
  const runawayRed = Math.min(50, Math.round((catchupFactor - 1.0) * 40));

  return {
    config,
    projectedWinTurnDelta: -2,
    predictedRunawayReduction: runawayRed,
    predictedComebackIncrease: Math.round(runawayRed * 1.2),
    stressIndexDelta: -Math.round(runawayRed * 0.5)
  };
};

export const simulateBalanceAdjustment = (config: any, events: any[] = [], actors: any = {}): BalanceSimulationResult => simulateBalanceSandbox(config, Array.isArray(events) ? events : [], Array.isArray(actors) ? {} : actors);

