  // Safe Mode, this one never auto-clears on its own — resuming always requires an explicit call to
  // resumeAuditorFromSafeMode (mandatory user confirmation to resume, per the roadmap's own
  // requirement), never a daily hysteresis re-check.
  teamAiAuditorSafeModeEnabled: boolean;
  teamAiAuditorSafeModeEscalatedIncidentThreshold: number;
  // AE2 (AI Thinking & Algorithm System): per-side/opponent algorithm selection. All default
  // 'classic_layered' — today's exact behavior, byte-identical until AE3 wires the resolver into
  // any real turn-execution path. Applies to Team Mode (friendly/enemy) and solo Human vs AI
  // (opponent) alike — this feature is not Team-Mode-only, unlike most teamAi* settings above.
  aiAlgorithmForFriendlyTeam: AiDecisionEngineId;
  aiAlgorithmForEnemyTeam: AiDecisionEngineId;
  aiAlgorithmForOpponent: AiDecisionEngineId;
  // Fast/Balanced/Deep thinking depth — reserved for the End-to-End Strategic Planner (AE7+:
  // Balanced evaluates up to 2-step plans, Deep up to 3-step). Inert until then.
  aiThinkingDepth: AiThinkingDepth;
  // AI Thinking/Algorithm Builder Phase AB1: master toggle, off by default — inert this phase
  // since no config can be created yet (AB6). Default editor mode governs the starting
  // editorMode of a newly-created config; inert until AB2+ builds a stage editor that varies its
  // own field visibility by this value.
  aiAlgorithmBuilderEnabled: boolean;
  aiAlgorithmBuilderDefaultEditorMode: AiAlgorithmEditorMode;
  // Human Player Automation and Action Rules System, Phase HA1: master toggle, off by default —
  // pure scaffolding this phase, inert since no automation can be created yet (HA2 builds CRUD).
  // Deliberately not Team-Mode-scoped: applies to the human player in every game mode.
  humanAutomationEnabled: boolean;
  humanAutomationTransparencyEnabled: boolean;
  automationSequenceLaunchEnabled: boolean;
  automationSlotProgressionEnabled: boolean;
  automationRunHistoryEnabled: boolean;
  automationExtendedTriggersEnabled: boolean;
  automationExtendedActionsEnabled: boolean;
  automationConflictWarningsEnabled: boolean;
  automationDailyDigestEnabled: boolean;
  automationImportExportEnabled: boolean;
  // Milestone 6 Phase 15: Replay Comparison
  replayComparisonEnabled: boolean;
  replayComparisonToleranceThreshold: number;
  replayComparisonIgnoreMinorTiming: boolean;
  // Milestone 6 Phase 17: AI Effectiveness Scorecard
  aiEffectivenessScorecardEnabled: boolean;
  aiEffectivenessBlunderThresholdRoi: number;
  aiEffectivenessTrackCompliance: boolean;
  // Milestone 6 Phase 18: Balance Lab
  balanceLabEnabled: boolean;
  balanceLabAutoStressTracking: boolean;
  balanceLabSandboxMode: boolean;
  // Milestone 7 Phase 19/20: Settings Hub, Diagnostics & Bundle Export
  ledgerDiagnosticsEnabled: boolean;
  ledgerPruneRetentionLimit: number;
  ledgerAutoPruneEnabled: boolean;
  ledgerExportCompressionEnabled: boolean;
  // Milestone 4: AI Learning, Opponent Models, Plan Stability & Governance Settings
  enableAiCalibrationLearning: boolean;
  aiCalibrationLearningRate: number;
  enableCounterfactualEvaluation: boolean;
  enablePersistentOpponentModels: boolean;
  planSwitchingCost: number;
  teamGovernanceMode: TeamGovernanceMode | string;
  aiTacticalIntelligence: AiTacticalIntelligenceParams;
  aiEconomicCheats: AiEconomicCheatBonuses;
  teamOverviewDensity: 'compact' | 'comfortable';
  // Phase 7: Projected Outcome Settings (Defaults OFF)
  projectedOutcomeEnabled: boolean;
  projectedOutcomeHorizon: number;
  projectedOutcomeMode: 'auto' | 'simulation_only' | 'extrapolation_only';
  deterministicMode: boolean;
  governanceControlSurfaceEnabled: boolean;
  humanGovernanceVetoEnabled: boolean;
  teamGovernanceModeOverrides: Record<string, TeamGovernanceOverrideMode>;
  governanceWeightSettings: GovernanceWeightSettings;
  governanceLeaderVoteWeight: number;
  governanceMemberVoteWeight: number;
  governanceVoteThreshold: number;
  governanceConsensusThreshold: number;
  governanceVetoUsesPerMatch: number;
  autoModeSettings: AutoModeGlobalSettings;
  coPilotSettings: CoPilotSettings;
