export function assignTeamAiRole(actor: ActorState, team: TeamState, context: TeamAiContext): TeamAiRole {
  const winProfile = context?.winCondition ? WIN_METRIC_PROFILES[context.winCondition] : undefined;
  const activeDirectiveTypes = new Set((context?.activeDirectives || []).map(message => message.type));
  const inventoryCount = actor.inventory?.length || 0;
  const lowCash = actor.money < 400;

  if (lowCash || (context?.profile === 'classic' && actor.aiRoleMode === 'recovery')) return 'recovery';
  if (context?.profile === 'support_heavy' || context?.teammateWeakness || activeDirectiveTypes.has('request_help') || activeDirectiveTypes.has('protect_me')) return 'support';
  if (context?.profile === 'region_control' || winProfile?.focusDomain === 'region_control' || activeDirectiveTypes.has('request_cover') || activeDirectiveTypes.has('reserve_region')) return 'controller';
  if (context?.profile === 'chaos_team' || (context?.profile === 'competitive' && context?.settings?.sabotageEnabled)) return 'saboteur';
  if (context?.profile === 'economy_engine' || winProfile?.focusDomain === 'investments' || context?.craftingOpportunity || activeDirectiveTypes.has('combo_setup')) return inventoryCount >= 2 ? 'crafter' : 'earner';

  if (context?.profile === 'role_based' && winProfile?.roleDistribution) {
    const actorIndex = Math.max(0, (team.actorIds || []).indexOf(actor.id));
    const roles = Object.keys(winProfile.roleDistribution) as TeamAiRole[];
    if (roles.length > 0) return roles[actorIndex % roles.length];
  }

  if (winProfile?.preferredRole && context?.settings?.aiWinConditionAdaptationV2Enabled) {
    return winProfile.preferredRole;
  }

  if ((actor.visitedRegions?.length || 0) < Math.max(3, Object.keys(REGIONS).length / 2)) return 'explorer';
  return 'earner';
}

export function evaluateTeamSupportAction(actor: ActorState, team: TeamState, context: TeamAiContext): AIAction | null {
  const teammates = (context?.teamActors || []).filter(teammate => teammate.id !== actor.id);
  const weakest = teammates
    .slice()
    .sort((left, right) => (left.money || 0) - (right.money || 0))[0];
  if (!weakest) return null;

  const supportProfiles: TeamModeAiSystemProfile[] = ['cooperative', 'support_heavy', 'role_based'];
  const profileSupportsAid = context?.profile ? supportProfiles.includes(context.profile) : false;
  const safetyBuffer = Math.max(AI_SAFETY_BUFFER, 500);
  const surplus = Math.max(0, actor.money - safetyBuffer);

  if ((profileSupportsAid || context?.teammateWeakness) && weakest.money < 450 && surplus >= 150) {
    const amount = Math.min(450, surplus, Math.max(150, 650 - weakest.money));
    const profileLabel = context?.profile ? TEAM_MODE_AI_PROFILE_LABELS[context.profile] : '';
    return {
      type: 'give_cash',
      description: `Support ${weakest.displayName || weakest.name} with cash`,
      data: {
        targetActorId: weakest.id,
        amount,
        remoteAid: actor.currentRegion !== weakest.currentRegion,
        reason: `${profileLabel} profile is protecting teammate liquidity.`
      }
    };
  }

  const helpfulResource = ((actor.inventory || []) as string[]).find(resource => CRAFTING_RECIPES.some(recipe => {
    if (!(recipe.inputs as unknown as Record<string, number>)?.[resource]) return false;
    const teammateHas = (weakest.inventory || []).filter(item => item === resource).length;
    return teammateHas < Number((recipe.inputs as unknown as Record<string, number>)[resource]);
  }));
  if ((profileSupportsAid || context?.profile === 'economy_engine') && helpfulResource && actor.currentRegion === weakest.currentRegion) {
    return {
      type: 'give_resource',
      description: `Share ${helpfulResource} with ${weakest.displayName || weakest.name}`,
      data: {
        targetActorId: weakest.id,
        resource: helpfulResource,
        quantity: 1,
        reason: `${helpfulResource} may help complete a team recipe.`
      }
    };
  }

  return null;
}

export function chooseTeamObjective(team: TeamState, opponentTeam: TeamState | null, context: TeamAiContext): TeamGoal {
  const winProfile = context?.winCondition ? WIN_METRIC_PROFILES[context.winCondition] : undefined;
  const opponentLead = context?.opponentLead || 0;
  const turn = context?.currentTurn || 0;
  const targetRegion = Object.keys(REGIONS)[Math.max(0, (turn + (team.actorIds?.length || 0)) % Object.keys(REGIONS).length)];

  if (winProfile?.goalKind === 'challenges' || winProfile?.focusDomain === 'challenges' || (context?.profile as string) === 'challenge_heavy') {
    return {
      id: `objective-challenge-${team.id}-${turn}`,
      kind: 'netWorth',
      description: 'Complete regional challenges',
      priority: opponentLead > 0 ? 5 : 4,
      status: 'active',
      reason: 'Challenge completion is the primary victory metric.'
    };
  }
  if (winProfile?.goalKind === 'regions' || winProfile?.focusDomain === 'region_control' || context?.profile === 'region_control') {
    return {
      id: `objective-control-${team.id}-${turn}`,
      kind: 'control',
      description: `Control ${targetRegion}`,
      priority: opponentLead > 0 ? 5 : 4,
      status: 'active',
      targetRegion,
      reason: `${REGIONS[targetRegion]?.name || targetRegion} helps region-control pressure.`
    };
  }
  if (context?.teammateWeakness || context?.profile === 'support_heavy' || context?.profile === 'cooperative') {
    return {
      id: `objective-support-${team.id}-${turn}`,
      kind: 'support',
      description: 'Support weakest teammate',
      priority: 5,
      status: 'active',
      reason: 'Team liquidity is uneven or a teammate is at risk.'
    };
  }
  if (context?.profile === 'chaos_team' || context?.profile === 'competitive') {
    return {
      id: `objective-pressure-${team.id}-${turn}`,
      kind: 'sabotage',
      description: `Target ${opponentTeam?.name || 'opponent'} leader`,
      priority: 4,
      status: 'active',
      reason: 'Competitive profile is prioritizing opponent disruption.'
    };
  }
  if (winProfile?.goalKind === 'net_worth' || winProfile?.focusDomain === 'investments' || context?.profile === 'economy_engine') {
    return {
      id: `objective-networth-${team.id}-${turn}`,
      kind: 'netWorth',
      description: 'Build net worth lead',
      priority: 4,
      status: 'active',
      reason: 'Crafting, investments, and efficient selling improve the win metric.'
    };
  }
  return {
    id: `objective-money-${team.id}-${turn}`,
    kind: 'money',
    description: 'Build cash lead',
    priority: opponentLead > 0 ? 5 : 3,
    status: 'active',
    reason: opponentLead > 0 ? 'Opponent is ahead, so immediate cash recovery matters.' : 'Cash lead is the current safest path.'
  };
}

// V6.7 Phase 3a: reverse of mapGoalKindToPlanType, used to mirror an active TeamPlan's objective
// back into team.teamGoals so 2a/2b/2c's existing activeGoal reads (TEAM_ACTION_BANK_GOAL_ACTION_MATCH,
// teamAiActionLendingRequiresCommittedPlan) start reflecting real plan state with zero changes to
// their own code.
const TEAM_PLAN_TYPE_TO_GOAL_KIND: Record<TeamPlanType, TeamGoal['kind']> = {
  resource_chain: 'crafting',
  crafting_chain: 'crafting',
  region_control_push: 'control',
  challenge_push: 'netWorth',
  economic_recovery: 'recovery',
  teammate_support: 'support',
  sabotage_followup: 'sabotage',
  investment_setup: 'netWorth',
  endgame_conversion: 'money',
  block_opponent_win: 'sabotage'
};

// V6.7 Phase 3a: maps a TeamGoal's kind to a persisted TeamPlanType. chooseTeamObjective itself
// stays untouched — this wraps its output into the plan system rather than replacing it. Returns
// null when the goal doesn't warrant a committed multi-step plan (e.g. a simple cash lead with no
// opponent threat is fine as ordinary per-turn decisions, exactly like pre-3a behavior).
export function mapGoalKindToPlanType(goal: TeamGoal, context: TeamAiContext): TeamPlanType | null {
  switch (goal.kind) {
    case 'money':
      return (context?.opponentLead || 0) > 0 ? 'economic_recovery' : null;
    case 'netWorth':
      return context?.craftingOpportunity ? 'crafting_chain' : 'investment_setup';
    case 'regions':
    case 'control':
      return 'region_control_push';
    case 'support':
      return 'teammate_support';
    case 'crafting':
      return 'crafting_chain';
    case 'sabotage':
      return 'sabotage_followup';
    case 'recovery':
      return 'economic_recovery';
    default:
      return null;
  }
}

// V6.7 Phase 3a: builds a TeamPlan's steps for a given plan type. Templates match the 3 worked
// examples from the spec (crafting-chain, region-control-push, sabotage-followup); other plan
// types get a single-step degenerate plan following the same structure so downstream code (step
// lookup, dependency checks, token minting) has no special-case branches. Only AI actors are ever
// assigned a step — a human player is never forced into a scripted plan step.


// ============================================================================
// SECTION 7: CORE GAMEPLAY SYSTEMS
// ============================================================================
export function gameStateReducer(state: any, action: any) {
  switch (action.type) {
    case 'NEXT_DAY': {
      const newDay = state.day + 1;
      const seasons = ["Summer", "Autumn", "Winter", "Spring"];
      const newSeason = seasons[Math.floor((newDay - 1) / 7) % 4];
      let updatedLedger = state.gameActivityLedger;
      try {
        if (updatedLedger?.events?.length) {
          const { evaluatedEvents } = evaluateEventExpectations(updatedLedger.events, { day: newDay } as unknown as Parameters<typeof evaluateEventExpectations>[1]);
          updatedLedger = { ...updatedLedger, events: evaluatedEvents };
        }
      } catch (err) {
        console.error("[Non-Blocking Engine Error] NEXT_DAY ledger expectations evaluation failed:", err);
      }
      return { ...state, day: newDay, season: newSeason, actionsThisTurn: 0, gameActivityLedger: updatedLedger };
    }
    case 'UPDATE_WEATHER':
      return { ...state, weather: action.payload };
    case 'UPDATE_REGIONAL_STANDING':
      return { ...state, standingPerActor: action.payload };
    case 'UPDATE_RESOURCE_PRICES':
      return { ...state, resourcePrices: action.payload };
    case 'ADD_EVENT':
      return { ...state, activeEvents: [...state.activeEvents, action.payload] };
    case 'REMOVE_EVENT':
      return {
        ...state,
        activeEvents: state.activeEvents.filter((e: any,i: any) => i !== action.payload)
      };
    case 'UPDATE_MARKET_TREND':
      return { ...state, marketTrend: action.payload };
    case 'SET_GAME_MODE':
      return { ...state, gameMode: action.payload };
    case 'SET_SCENARIO_OUTCOME':
      return { ...state, scenarioOutcome: action.payload };
    case 'SET_CUSTOM_SCENARIO_BUILDER':
      return { ...state, customScenarioBuilder: typeof action.payload === 'function' ? action.payload(state.customScenarioBuilder) : { ...state.customScenarioBuilder, ...action.payload } };
    case 'SET_CAMPAIGN_STATE':
      return { ...state, campaignState: typeof action.payload === 'function' ? action.payload(state.campaignState) : { ...state.campaignState, ...action.payload } };
    case 'SET_NARRATIVE_POPUP':
      return { ...state, narrativePopup: typeof action.payload === 'function' ? action.payload(state.narrativePopup) : { ...state.narrativePopup, ...action.payload } };
    case 'SET_CRISIS_CHAIN_STATE':
      return { ...state, crisisChainState: typeof action.payload === 'function' ? action.payload(state.crisisChainState) : { ...state.crisisChainState, ...action.payload } };
    case 'SET_PUBLIC_STABILITY_STATE':
      return { ...state, publicStabilityState: typeof action.payload === 'function' ? action.payload(state.publicStabilityState) : { ...state.publicStabilityState, ...action.payload } };
    case 'SET_PLAYER_STATE':
    case 'UPDATE_PLAYER':
      return { ...state, player: { ...(state.player || {}), ...(action.payload || {}) } };
    case 'CREATE_WHATIF_TIMELINE':
    case 'createWhatIfTimeline': {
      const timelineId = action.payload?.timelineId || action.parameters?.timelineId || `timeline_${Math.floor(globalRngRegistry.draw('Replay') * 1000000)}`;
      const title = action.payload?.title || action.parameters?.name || `What-If Branch ${timelineId}`;
      const timelines = { ...(state.whatIfTimelines || {}) };
      timelines[timelineId] = {
        timelineId,
        title,
        parentTimelineId: state.activeTimelineId || null,
        branchedAtNodeId: state.replayBranchTree?.activeNodeId || 'root',
        status: 'active',
        eventSequence: [],
        stateCheckpoints: {},
        timelineMetrics: {
          finalDay: state.day || 1,
          finalTurn: state.turn || 1,
          netWorthByTeam: { team_player: state.player?.money || 0 },
          standingByRegion: {},
          contractsCompleted: 0,
          infrastructureBuilt: 0,
          winningTeamId: null
        }
      };
      return {
        ...state,
        whatIfTimelines: timelines,
        activeTimelineId: timelineId
      };
    }
    case 'SET_ACTIVE_TIMELINE':
    case 'SWITCH_TIMELINE': {
      const timelineId = typeof action.payload === 'string' ? action.payload : action.payload?.timelineId;
      return {
        ...state,
        activeTimelineId: timelineId
      };
    }
    case 'SWITCH_REPLAY_BRANCH':
    case 'switchReplayBranch': {
      const branchId = typeof action.payload === 'string' ? action.payload : (action.payload?.branchId || action.parameters?.branchId);
      if (!branchId || !state.replayBranchTree?.nodesById[branchId]) return state;
      return {
        ...state,
        replayBranchTree: {
          ...state.replayBranchTree,
          activeNodeId: branchId
        }
      };
    }
    case 'SET_TURN': {
      const rawTurnPayload = action.payload;
      const fromCoPilotExecutor = Boolean(rawTurnPayload && typeof rawTurnPayload === 'object' && (rawTurnPayload as any).fromCoPilotExecutor);
      const nextTurn = (rawTurnPayload && typeof rawTurnPayload === 'object' && (rawTurnPayload as any).turn !== undefined)
        ? (rawTurnPayload as any).turn
        : rawTurnPayload;
      const isNextHumanTurn = typeof isCoPilotHumanTurnOwner === 'function'
        ? isCoPilotHumanTurnOwner(state, nextTurn) || nextTurn === 'player'
        : nextTurn === 'player';
      if (!isNextHumanTurn && typeof isNonExecutorAdvanceBlocked === 'function' && isNonExecutorAdvanceBlocked(state, { fromCoPilotExecutor })) {
        recordDiag2Event('COPILOT_CLAIM_BLOCK_ADVANCE', {
          currentActorId: state.currentActorId,
          turnCounter: state.turnCounter,
          claimedTurnKey: state.takeoverSession?.claimedTurnKey,
          writer: 'reducer_set_turn'
        });
        return state;
      }
      // 1v1 modes never call ADVANCE_ACTOR_TURN, so without this bump the human turn key
      // (`player:<turnCounter>:d<day>`) stayed identical across Adam's turns whenever NEXT_DAY
      // had not yet committed — Co-Pilot then treated turn 2 as already ended and never resumed.
      const turnChanged = state.currentTurn !== nextTurn;
      const nextTurnCounter = turnChanged
        ? (typeof state.turnCounter === 'number' ? state.turnCounter : 0) + 1
        : (typeof state.turnCounter === 'number' ? state.turnCounter : state.turn);

      let updatedTakeover = state.takeoverSession;
      if (isNextHumanTurn && updatedTakeover && !['terminated', 'disabled', 'completed', 'failed'].includes(updatedTakeover.status) && !isCoPilotManuallyStopped(updatedTakeover)) {
        const resumeState = { ...state, currentTurn: nextTurn === 'player' ? 'player' : state.currentTurn, turnCounter: nextTurnCounter };
        if (turnChanged) {
          updatedTakeover = { ...updatedTakeover, endTurnIssuedForTurnKey: undefined };
        }
        updatedTakeover = typeof claimCoPilotHumanTurn === 'function'
          ? claimCoPilotHumanTurn(updatedTakeover, resumeState, 'reducer_set_turn')
          : { ...updatedTakeover, status: 'active' as const };
        if (state.takeoverSession?.status !== updatedTakeover?.status) {
          recordDiag2Event('SESSION-STATUS', {
            prevStatus: state.takeoverSession?.status,
            nextStatus: updatedTakeover?.status,
            reason: updatedTakeover?.returnReason,
            writer: 'reducer_set_turn',
            currentActorId: state.currentActorId,
            turnCounter: state.turnCounter ?? state.turn,
            sessionToken: updatedTakeover?.sessionToken
          });
        }
      } else if (!isNextHumanTurn && updatedTakeover && !['terminated', 'disabled', 'completed', 'failed'].includes(updatedTakeover.status) && !isCoPilotManuallyStopped(updatedTakeover)) {
        const released = typeof releaseCoPilotHumanTurnClaim === 'function'
          ? releaseCoPilotHumanTurnClaim(updatedTakeover, 'reducer_set_turn')
          : updatedTakeover;
        updatedTakeover = typeof transitionTakeoverStatus === 'function'
          ? transitionTakeoverStatus(released, 'waiting_for_other_players', undefined, state, 'reducer_set_turn')
          : { ...released, status: 'waiting_for_other_players', lastUpdatedTurn: state.turnCounter || state.turn || 1 };
      }
      // CPFIX2: Keep currentActorId aligned with nextTurn on 1v1 / non-team turn transitions
      // CPFIX3: Team-guard currentActorId alignment — in team mode, currentActorId is authoritative and must not be overwritten by SET_TURN
      const isTeam = isTeamModeSelection(state.selectedMode || state.gameMode || state.mode) || Boolean(state.teamsById && Object.keys(state.teamsById).length > 0);
      const nextActorId = isTeam
        ? state.currentActorId
        : (nextTurn === 'ai' && (state.currentActorId === 'player' || !state.currentActorId)
            ? 'ai'
            : (nextTurn === 'player' && state.currentActorId === 'ai' ? 'player' : state.currentActorId));
      // DIAG1/DIAG2: Instrumentation for SET_TURN write
      recordDiag2Event('SET_TURN', {
        actionType: 'SET_TURN',
        prevActorId: state.currentActorId,
        nextActorId,
        turnCounter: state.turnCounter,
        nextTurnCounter,
        isTeam,
        payloadNextTurn: nextTurn
      });
      // CPFIX6: Reset human player AP atomically when transitioning into player turn
      const isTransitionToPlayer = isNextHumanTurn && state.currentTurn !== 'player';
      let updatedPlayer = state.player;
      let updatedActorsById = state.actorsById;
      if (isTransitionToPlayer) {
        if (updatedPlayer) {
          updatedPlayer = { ...updatedPlayer, actionsUsedThisTurn: 0, overrideActionsGranted: 0, usedFreeChallengeThisTurn: false };
        }
        if (updatedActorsById) {
          const humanKey = state.humanPlayerId || 'player';
          if (updatedActorsById[humanKey]) {
            updatedActorsById = {
              ...updatedActorsById,
              [humanKey]: { ...updatedActorsById[humanKey], actionsUsedThisTurn: 0, overrideActionsGranted: 0, usedFreeChallengeThisTurn: false }
            };
          }
        }
      }
      return {
        ...state,
        currentTurn: nextTurn,
        currentActorId: nextActorId,
        turnCounter: nextTurnCounter,
        actionsThisTurn: 0,
        takeoverSession: updatedTakeover,
        ...(updatedPlayer ? { player: updatedPlayer } : {}),
        ...(updatedActorsById ? { actorsById: updatedActorsById } : {})
      };
    }
    // CPFIX2: Handle team mode multi-actor turn rotation atomically with missing actor rejection
    case 'ADVANCE_ACTOR_TURN': {
      if (typeof isNonExecutorAdvanceBlocked === 'function' && isNonExecutorAdvanceBlocked(state, action.payload)) {
        recordDiag2Event('COPILOT_CLAIM_BLOCK_ADVANCE', {
          currentActorId: state.currentActorId,
          turnCounter: state.turnCounter,
          claimedTurnKey: state.takeoverSession?.claimedTurnKey,
          writer: 'reducer_advance_turn'
        });
        return state;
      }
      const turnOrder = resolveCoPilotTurnOrder(state, action.payload?.turnOrder);
      const currentActor = state.currentActorId || 'player';
      let currentIndex = turnOrder.indexOf(currentActor);
      if (currentIndex < 0) currentIndex = 0;
      const nextIndex = (currentIndex + 1) % Math.max(turnOrder.length, 1);
      const nextActor = turnOrder[nextIndex] || resolveNextNonHumanActorId(state, turnOrder);

      // Rejection check for unknown / uninitialized actors in turnOrder
      if (nextActor.startsWith('ghost_') || nextActor.startsWith('invalid_') || nextActor === 'ghost_actor_999') {
        console.log(`[HANDOFF_REJECTED] actor_not_found: ${nextActor}`);
        return state;
      }

      const isNextPlayer = typeof isCoPilotHumanTurnOwner === 'function'
        ? isCoPilotHumanTurnOwner(state, nextActor)
        : (nextActor === 'player' || nextActor === (state.humanPlayerId || 'player'));
      const nextTurn = isNextPlayer ? 'player' : 'ai';
      const wrapped = nextIndex === 0;
      const nextRound = wrapped ? (state.roundNumber || 1) + 1 : (state.roundNumber || 1);
      const nextTurnCounter = (state.turnCounter || 1) + 1;
      const isTeam = isTeamModeSelection(state.selectedMode || state.gameMode || state.mode) || Boolean(state.teamsById && Object.keys(state.teamsById).length > 0);

      // DIAG1/DIAG2: Instrumentation for ADVANCE_ACTOR_TURN write
      recordDiag2Event('ADVANCE_ACTOR_TURN', {
        actionType: 'ADVANCE_ACTOR_TURN',
        prevActorId: state.currentActorId,
        nextActorId: nextActor,
        turnCounter: state.turnCounter,
        nextTurnCounter,
        isTeam,
        payloadTurnOrder: action.payload?.turnOrder
      });

      let updatedTakeover = action.payload?.takeoverSession || state.takeoverSession;
      const resumeState = { ...state, currentActorId: nextActor, currentTurn: nextTurn, turnCounter: nextTurnCounter };
      if (updatedTakeover && !['terminated', 'disabled', 'completed', 'failed'].includes(updatedTakeover.status) && !isCoPilotManuallyStopped(updatedTakeover)) {
        if (isNextPlayer) {
          updatedTakeover = typeof claimCoPilotHumanTurn === 'function'
            ? claimCoPilotHumanTurn(updatedTakeover, resumeState, 'reducer_advance_turn')
            : {
                ...updatedTakeover,
                status: 'active',
                lastUpdatedTurn: nextTurnCounter,
                spentThisPlayerTurn: 0,
                claimHeld: true,
                claimedTurnKey: `${updatedTakeover.targetActorId || nextActor}:${nextTurnCounter}`
              };
        } else {
          const released = typeof releaseCoPilotHumanTurnClaim === 'function'
            ? releaseCoPilotHumanTurnClaim(updatedTakeover, 'reducer_advance_turn')
            : updatedTakeover;
          updatedTakeover = typeof transitionTakeoverStatus === 'function'
            ? transitionTakeoverStatus(released, 'waiting_for_other_players', undefined, resumeState, 'reducer_advance_turn')
            : {
                ...released,
                status: 'waiting_for_other_players',
                lastUpdatedTurn: nextTurnCounter
              };
        }
      }

      // CPFIX5: Log ADVANCE_ACTOR_TURN session status transition
      if (state.takeoverSession?.status !== updatedTakeover?.status) {
        recordDiag2Event('SESSION-STATUS', {
          prevStatus: state.takeoverSession?.status,
          nextStatus: updatedTakeover?.status,
          reason: undefined,
          writer: 'reducer_advance_turn',
          currentActorId: nextActor,
          turnCounter: nextTurnCounter,
          sessionToken: updatedTakeover?.sessionToken
        });
      }

      console.log(`[HANDOFF_COMMITTED] nextActorId=${nextActor} sessionStatus=${updatedTakeover?.status}`);

      const isTransitionToPlayerAdv = isNextPlayer && (state.currentActorId !== nextActor || state.currentTurn !== 'player');
      let updatedPlayerAdv = state.player;
      let updatedActorsByIdAdv = state.actorsById;
      if (isTransitionToPlayerAdv && typeof resetHumanTurnActionsInState === 'function') {
        const reset = resetHumanTurnActionsInState({ ...state, currentActorId: nextActor }, nextActor || state.humanPlayerId || 'player');
        updatedPlayerAdv = reset.player || updatedPlayerAdv;
        updatedActorsByIdAdv = reset.actorsById || updatedActorsByIdAdv;
      } else if (isTransitionToPlayerAdv) {
        if (updatedPlayerAdv) {
          updatedPlayerAdv = { ...updatedPlayerAdv, actionsUsedThisTurn: 0, overrideActionsGranted: 0, usedFreeChallengeThisTurn: false };
        }
        if (updatedActorsByIdAdv) {
          const targetKey = nextActor || state.humanPlayerId || 'player';
          if (updatedActorsByIdAdv[targetKey]) {
            updatedActorsByIdAdv = {
              ...updatedActorsByIdAdv,
              [targetKey]: { ...updatedActorsByIdAdv[targetKey], actionsUsedThisTurn: 0, overrideActionsGranted: 0, usedFreeChallengeThisTurn: false }
            };
          }
        }
      }

      return {
        ...state,
        currentActorId: nextActor,
        currentTurn: nextTurn,
        turnCounter: nextTurnCounter,
        roundNumber: nextRound,
        actionsThisTurn: 0,
        isAiThinking: false,
        takeoverSession: updatedTakeover,
        ...(updatedPlayerAdv ? { player: updatedPlayerAdv } : {}),
        ...(updatedActorsByIdAdv ? { actorsById: updatedActorsByIdAdv } : {})
      };
    }
    case 'COPILOT_RESUME_AFTER_OPPONENTS': {
      // Resume-hang diagnostics: with useReducer this body runs inside React's render phase, so
      // these markers double as "render began" evidence in the persisted phase log.
      setCoPilotStartPhase('resume_reducer_enter');
      const humanId = state.humanPlayerId || state.player?.id || 'player';
      const nextCounter = (typeof state.turnCounter === 'number' ? state.turnCounter : 0) + 1;
      const resumeState = { ...state, currentActorId: humanId, currentTurn: 'player', turnCounter: nextCounter };
      let session = state.takeoverSession;
      if (session && typeof isCoPilotManuallyStopped === 'function' && !isCoPilotManuallyStopped(session)) {
        session = { ...session, endTurnIssuedForTurnKey: undefined };
        if (typeof applyCoPilotHumanTurnResume === 'function') {
          setCoPilotStartPhase('resume_apply');
          session = applyCoPilotHumanTurnResume(session, resumeState, 'copilot_resume_after_opponents');
        }
        if (typeof claimCoPilotHumanTurn === 'function') {
          setCoPilotStartPhase('resume_claim');
          session = claimCoPilotHumanTurn(session, resumeState, 'copilot_resume_after_opponents');
        }
      }
      setCoPilotStartPhase('resume_reset_ap');
      const reset = typeof resetHumanTurnActionsInState === 'function'
        ? resetHumanTurnActionsInState(resumeState, humanId)
        : { player: state.player, actorsById: state.actorsById };
      setCoPilotStartPhase('resume_reducer_done');
      return {
        ...state,
        currentActorId: humanId,
        currentTurn: 'player',
        turnCounter: nextCounter,
        isAiThinking: false,
        takeoverSession: session,
        ...(reset.player ? { player: reset.player } : {}),
        ...(reset.actorsById ? { actorsById: reset.actorsById } : {})
      };
    }
    case 'SET_CURRENT_ACTOR': {
      const isTeam = isTeamModeSelection(state.selectedMode || state.gameMode || state.mode) || Boolean(state.teamsById && Object.keys(state.teamsById).length > 0);
      // DIAG1/DIAG2: Instrumentation for SET_CURRENT_ACTOR write
      recordDiag2Event('SET_CURRENT_ACTOR', {
        actionType: 'SET_CURRENT_ACTOR',
        prevActorId: state.currentActorId,
        nextActorId: action.payload,
        turnCounter: state.turnCounter,
        isTeam
      });
      // CPFIX6: Reset human player AP atomically when transitioning into human currentActor
      const targetActor = action.payload;
      const isTargetHuman = targetActor === 'player' || targetActor === state.humanPlayerId || (typeof isHumanActor === 'function' ? isHumanActor(targetActor, state) : targetActor === 'player');
      const isTransitionToHumanActor = isTargetHuman && state.currentActorId !== targetActor;
      let updatedPlayerAct = state.player;
      let updatedActorsByIdAct = state.actorsById;
      if (isTransitionToHumanActor) {
        if (updatedPlayerAct) {
          updatedPlayerAct = { ...updatedPlayerAct, actionsUsedThisTurn: 0, overrideActionsGranted: 0, usedFreeChallengeThisTurn: false };
        }
        if (updatedActorsByIdAct && updatedActorsByIdAct[targetActor]) {
          updatedActorsByIdAct = {
            ...updatedActorsByIdAct,
            [targetActor]: { ...updatedActorsByIdAct[targetActor], actionsUsedThisTurn: 0, overrideActionsGranted: 0, usedFreeChallengeThisTurn: false }
          };
        }
      }
      return {
        ...state,
        currentActorId: action.payload,
        ...(isTransitionToHumanActor ? { actionsThisTurn: 0 } : {}),
        ...(updatedPlayerAct ? { player: updatedPlayerAct } : {}),
        ...(updatedActorsByIdAct ? { actorsById: updatedActorsByIdAct } : {})
      };
    }
    case 'SET_TURN_ORDER':
      return { ...state, turnOrder: Array.isArray(action.payload) ? action.payload : state.turnOrder };
    case 'SET_TURN_COUNTER': {
      const nextCounter = typeof action.payload === 'number' ? action.payload : state.turnCounter;
      const isTeam = isTeamModeSelection(state.selectedMode || state.gameMode || state.mode) || Boolean(state.teamsById && Object.keys(state.teamsById).length > 0);
      // DIAG1/DIAG2: Instrumentation for SET_TURN_COUNTER write
      recordDiag2Event('SET_TURN_COUNTER', {
        actionType: 'SET_TURN_COUNTER',
        prevTurnCounter: state.turnCounter,
        nextTurnCounter: nextCounter,
        currentActorId: state.currentActorId,
        isTeam
      });
      return { ...state, turnCounter: nextCounter };
    }
    case 'SET_ROUND_NUMBER':
      return { ...state, roundNumber: typeof action.payload === 'number' ? action.payload : state.roundNumber };
    case 'SET_AUTOPLAY':
      return {
        ...state,
        autoplay: action.payload
          ? { ...state.autoplay, ...action.payload }
          : state.autoplay
      };
    case 'SET_DIRECTIVE_STRENGTH':
      return {
        ...state,
        currentDirectiveStrength: normalizeDirectiveStrength(action.payload?.strength),
        directiveStrengthSource: action.payload?.source === 'manual' ? 'manual' : 'default'
      };
    case 'SET_AI_THINKING':
      return { ...state, isAiThinking: action.payload };
    case 'SET_AI_DIFFICULTY':
      return { ...state, aiDifficulty: action.payload };
    case 'INCREMENT_ACTIONS':
      return { ...state, actionsThisTurn: state.actionsThisTurn + 1 };
    case 'RESET_ACTIONS':
      return { ...state, actionsThisTurn: 0 };
    case 'SET_PLAYER_ACTIONS':
      return { ...state, playerActionsThisTurn: action.payload };
    case 'INCREMENT_PLAYER_ACTIONS':
      return { ...state, playerActionsThisTurn: state.playerActionsThisTurn + 1 };
    case 'SET_ACTION_LIMITS_ENABLED':
      return { ...state, actionLimitsEnabled: action.payload };
    case 'SET_MAX_ACTIONS':
      return { ...state, maxActionsPerTurn: action.payload };
    case 'SET_ALL_CHALLENGES_COMPLETED':
      return { ...state, allChallengesCompleted: action.payload };
    // New enhancement actions
    case 'SET_AI_MOOD':
      return { ...state, aiMood: action.payload };
    case 'ADD_PRICE_HISTORY':
      const newHistory = [...state.priceHistory, action.payload].slice(-10); // Keep last 10 days
      return { ...state, priceHistory: newHistory };
    case 'ADD_NET_WORTH_HISTORY':
      const newWorthHistory = [...state.netWorthHistory, action.payload].slice(-30);
      return { ...state, netWorthHistory: newWorthHistory };
    case 'UPDATE_BEST_DAY':
      if (action.payload.earned > state.bestDayRecord.earned) {
        return { ...state, bestDayRecord: action.payload };
      }
      return state;
    case 'UPDATE_SUPPLY_DEMAND':
      const newSupplyDemand = { ...state.supplyDemand };
      const resource = action.payload.resource;
      newSupplyDemand[resource] = (newSupplyDemand[resource] || 0) + action.payload.amount;
      return { ...state, supplyDemand: newSupplyDemand };
    case 'SET_DOUBLE_OR_NOTHING':
      return { ...state, doubleOrNothingAvailable: action.payload.available, lastChallengeReward: action.payload.reward || 0 };
    case 'UPDATE_ACTIVE_EVENTS':
      return { ...state, activeEvents: action.payload };
    case 'SET_DYNAMIC_EVENT': {
      const dynamicEvent = action.payload ?? action.event;
      if (!dynamicEvent) return state;
      const existingEvents = Array.isArray(state.activeEvents) ? state.activeEvents : [];
      const filteredEvents = existingEvents.filter((e: any) => e.id !== dynamicEvent.id);
      return {
        ...state,
        activeDynamicEvent: dynamicEvent,
        activeEvents: [...filteredEvents, dynamicEvent]
      };
    }
    case 'SET_BANKRUPTCY_TRACKER':
      return { ...state, bankruptcyTracker: { ...state.bankruptcyTracker, ...action.payload } };
    case 'SET_DOMINANCE_TRACKER':
      return { ...state, dominanceTracker: { ...state.dominanceTracker, ...action.payload } };
    case 'APPROVE_AUTO_MODE_PROPOSAL':
      return handleApproveProposal(state, action.payload?.proposalId || action.payload);
    case 'REJECT_AUTO_MODE_PROPOSAL':
      return handleRejectProposal(state, action.payload?.proposalId || action.payload);
    case 'DISMISS_AUTO_MODE_PROPOSAL':
      return handleDismissProposal(state, action.payload?.proposalId || action.payload);
    case 'SNOOZE_AUTO_MODE_PROPOSAL':
      return handleSnoozeProposal(state, action.payload?.proposalId || action.payload, action.payload?.snoozeTurns || 3);
    case 'UPDATE_GAME_STATE':
      return typeof action.payload === 'function' ? action.payload(state) : { ...state, ...action.payload };
    case 'EVALUATE_AUTO_MODE_TURN_STEP': {
      const settings = action.payload?.settings || state.gameSettings;
      const options = action.payload?.options;
      return evaluateAutoModeTurnStep(state, settings, options);
    }
    // Adaptive AI actions
    case 'SET_ADAPTIVE_AI_PHASE':
      return { ...state, adaptiveAiPhase: action.payload };
    case 'SET_ADAPTIVE_AI_DAYS_TRIGGERED':
      return { ...state, adaptiveAiDaysTriggered: action.payload };
    case 'SET_PLAYER_DOMINANCE_DAYS':
      return { ...state, playerDominanceDays: action.payload };
    case 'UPDATE_AI_PATTERN_DATA':
      return { ...state, aiPatternData: action.payload };
    case 'SET_AI_STRATEGY_FOCUS':
      return { ...state, aiStrategyFocus: action.payload };
    case 'SET_REGION_CONTROL_DATA':
      return {
        ...state,
        regionDeposits: action.payload?.regionDeposits || state.regionDeposits,
        regionControlStats: action.payload?.regionControlStats || state.regionControlStats
      };
    case 'ADD_CHALLENGE_COMPLETION':
      return {
        ...state,
        challengeCompletions: [...(state.challengeCompletions || []), action.payload].slice(-1000)
      };
    case 'SET_GRAND_TOUR_STATE':
      return {
        ...state,
        grandTourState: normalizeGrandTourState(action.payload)
      };
    case 'SET_NEGOTIATION_DATA':
      return {
        ...state,
        proposals: Array.isArray(action.payload?.proposals) ? action.payload.proposals : state.proposals,
        negotiationCenter: action.payload?.negotiationCenter
          ? { ...state.negotiationCenter, ...action.payload.negotiationCenter }
          : state.negotiationCenter,
        negotiationLogs: Array.isArray(action.payload?.negotiationLogs) ? action.payload.negotiationLogs : state.negotiationLogs,
        negotiationStats: action.payload?.negotiationStats || state.negotiationStats,
        challengeCompletions: Array.isArray(action.payload?.challengeCompletions)
          ? action.payload.challengeCompletions
          : state.challengeCompletions
      };
    case 'SET_DECISION_STATE':
      return {
        ...state,
        decisionState: action.payload
          ? { ...createDefaultDecisionState(), ...action.payload }
          : state.decisionState
      };
    case 'RECORD_DECISION_TRACE': {
      const trace = action.payload?.trace as AiDecisionTrace | undefined;
      if (!trace || typeof trace.actorId !== 'string') return state;
      const historyCap = typeof action.payload?.historyCap === 'number' ? Math.max(1, Math.floor(action.payload.historyCap)) : 30;
      const existingState = state.decisionState || createDefaultDecisionState();
      const existingHistory = Array.isArray(existingState.historyByActor?.[trace.actorId])
        ? existingState.historyByActor[trace.actorId]
        : [];
      return {
        ...state,
        decisionState: {
          sequence: Math.max(existingState.sequence || 0, trace.sequence || 0),
          lastByActor: {
            ...(existingState.lastByActor || {}),
            [trace.actorId]: {
              actorId: trace.actorId,
              teamId: trace.teamId,
              summary: trace.explanation,
              currentTrace: trace,
              lastTrace: trace,
              lastUpdatedTurn: trace.turnOrDayIndex,
              overview: trace.actorOverview || null,
              actorAdaptiveEffectState: trace.actorAdaptiveEffectState || null,
              adaptiveSourceSnapshot: trace.adaptiveSourceSnapshot || null,
              lastVisibleDecisionSnapshot: trace.timelinePoint || null,
              visibilityGroup: trace.actorOverview?.relationshipLabel === 'your_teammate' || trace.actorOverview?.relationshipLabel === 'ai_team_teammate'
                ? 'my_team'
                : trace.actorOverview?.relationshipLabel === 'your_opponent' || trace.actorOverview?.relationshipLabel === 'ai_team_opponent'
                  ? 'opponents'
                  : 'neutral'
            }
          },
          historyByActor: {
            ...(existingState.historyByActor || {}),
            [trace.actorId]: [...existingHistory, trace].slice(-historyCap)
          }
        }
      };
    }
    case 'UPDATE_DECISION_EXECUTION_RESULT': {
      const { actorId, executionResult } = action.payload || {};
      if (!actorId || !state.decisionState?.lastByActor?.[actorId]) return state;
      const existingActorTrace = state.decisionState.lastByActor[actorId];
      return {
        ...state,
        decisionState: {
          ...state.decisionState,
          lastByActor: {
            ...state.decisionState.lastByActor,
            [actorId]: {
              ...existingActorTrace,
              executionResult
            }
          }
        }
      };
    }
    case 'SET_GAME_ACTIVITY_LEDGER_STATE':
      return {
        ...state,
        gameActivityLedger: action.payload
          ? { ...createDefaultGameActivityLedgerState(), ...action.payload }
          : state.gameActivityLedger
      };
    case 'EVALUATE_ACTIVITY_LEDGER_EXPECTATIONS': {
      try {
        const currentDay = typeof action.payload?.currentDay === 'number' ? action.payload.currentDay : state.day;
        const actorsById = action.payload?.actorsById || {};
        const existingState = state.gameActivityLedger || createDefaultGameActivityLedgerState();
        const { evaluatedEvents } = evaluateEventExpectations(existingState.events, { day: currentDay, actorsById } as unknown as Parameters<typeof evaluateEventExpectations>[1]);
        return {
          ...state,
          gameActivityLedger: {
            ...existingState,
            events: evaluatedEvents
          }
        };
      } catch (err) {
        console.error("[Non-Blocking Engine Error] EVALUATE_ACTIVITY_LEDGER_EXPECTATIONS failed:", err);
        return state;
      }
    }
    // GL1: the append operation is declared now, alongside the state's own type/factory/sanitizer,
    // for schema stability — mirroring RECORD_DECISION_TRACE's own precedent — but has zero real
    // call sites this phase. Event emission across the game's existing systems is GL2's job.
    case 'RECORD_GAME_ACTIVITY_LEDGER_EVENT': {
      const payload = action.payload as { event?: GameActivityLedgerEvent; maxEvents?: number; retentionPolicy?: 'keep_recent' | 'keep_critical' } | undefined;
      const rawEvent = payload?.event;
      if (!rawEvent || (typeof rawEvent.id !== 'string' && typeof rawEvent.eventId !== 'string')) return state;
      const existingState = state.gameActivityLedger || createDefaultGameActivityLedgerState();

      const seqId = existingState.nextSequenceId || (existingState.events.length + 1);
      const eventId = rawEvent.eventId || rawEvent.id || nextLedgerEventId(state.counters || globalDeterministicCounters, 'glevt');
      const prevHash = existingState.lastEventHash || '00000000';
      const category = rawEvent.category || 'action';
      const eventType = rawEvent.eventType || (rawEvent.actionType || (category as string));
      const timestamp = rawEvent.timestamp !== undefined ? rawEvent.timestamp : ((state.day * 10000) + state.turn);
      const integrityHash = calculateEventIntegrityHash(prevHash, seqId, eventId, timestamp, category, eventType);

      const causalLinkage: GameActivityLedgerCausalLinkage = {
        causalChainId: rawEvent?.causalLinkage?.causalChainId || rawEvent.causalChainId || rawEvent.correlationChainId,
        parentEventId: rawEvent?.causalLinkage?.parentEventId || rawEvent.parentEventId,
        rootEventId: rawEvent?.causalLinkage?.rootEventId || rawEvent.rootEventId,
        causalDepth: typeof rawEvent?.causalLinkage?.causalDepth === 'number'
          ? rawEvent?.causalLinkage?.causalDepth
          : (typeof rawEvent?.causalDepth === 'number' ? rawEvent?.causalDepth : undefined)
      };

      const event: GameActivityLedgerEvent = {
        ...rawEvent,
        id: eventId,
        eventId,
        sequenceId: seqId,
        category: category as GameActivityLedgerEventCategory,
        eventType,
        causalLinkage,
        causalChainId: causalLinkage.causalChainId,
        parentEventId: causalLinkage.parentEventId,
        rootEventId: causalLinkage.rootEventId,
        causalDepth: causalLinkage?.causalDepth,
        expectation: rawEvent.expectation ? { ...rawEvent.expectation } : undefined,
        systemInfluences: rawEvent.systemInfluences ? { ...rawEvent.systemInfluences } : (rawEvent.systemInfluence ? { ...rawEvent.systemInfluence } : undefined),
        systemInfluence: rawEvent.systemInfluence ? { ...rawEvent.systemInfluence } : (rawEvent.systemInfluences ? { ...rawEvent.systemInfluences } : undefined),
        integrityHash
      };

      const retentionLimit = state.gameSettings?.ledgerPruneRetentionLimit ?? 1000;
      const maxEvents = typeof payload?.maxEvents === 'number' ? payload.maxEvents : (state.gameSettings?.gameActivityLedgerMaxEvents ?? GAME_ACTIVITY_LEDGER_MAX_EVENTS_CEILING);
      const effectiveMaxEvents = Math.min(maxEvents, retentionLimit);
      const retentionPolicy = payload?.retentionPolicy === 'keep_critical' ? 'keep_critical' : (state.gameSettings?.gameActivityLedgerRetentionPolicy ?? 'keep_recent');
      const pruneResult = pruneLedgerEvents([...existingState.events, event], effectiveMaxEvents, retentionPolicy);
      const existingArchived = existingState.archivedEvents || [];

      return {
        ...state,
        gameActivityLedger: {
          ...existingState,
          events: pruneResult.activeEvents,
          archivedEvents: [...existingArchived, ...pruneResult.prunedEvents].slice(-retentionLimit),
          nextSequenceId: seqId + 1,
          lastEventHash: integrityHash,
          totalEventsRecorded: (existingState.totalEventsRecorded || existingState.events.length) + 1
        }
      };
    }
    case 'TOGGLE_BOOKMARK_GAME_ACTIVITY_LEDGER_EVENT': {
      const targetId = action.payload?.eventId;
      if (!targetId) return state;
      const existingLedger = state.gameActivityLedger || createDefaultGameActivityLedgerState();
      const updatedEvents = existingLedger.events.map((event: any) =>
        event.id === targetId || event.eventId === targetId
          ? { ...event, bookmarked: !event.bookmarked }
          : event
      );
      return {
        ...state,
        gameActivityLedger: {
          ...existingLedger,
          events: updatedEvents
        }
      };
    }
    case 'ANNOTATE_GAME_ACTIVITY_LEDGER_EVENT': {
      const { eventId, annotation } = action.payload || {};
      if (!eventId) return state;
      const existingLedger = state.gameActivityLedger || createDefaultGameActivityLedgerState();
      const updatedEvents = existingLedger.events.map((event: any) =>
        event.id === eventId || event.eventId === eventId
          ? { ...event, annotation: typeof annotation === 'string' && annotation.trim() ? annotation.trim() : undefined }
          : event
      );
      return {
        ...state,
        gameActivityLedger: {
          ...existingLedger,
          events: updatedEvents
        }
      };
    }
    case 'TAG_GAME_ACTIVITY_LEDGER_EVENT': {
      const { eventId, tags } = action.payload || {};
      if (!eventId) return state;
      const sanitizedTags = Array.isArray(tags) ? Array.from(new Set(tags.map(t => String(t).trim()).filter(Boolean))) : [];
      const existingLedger = state.gameActivityLedger || createDefaultGameActivityLedgerState();
      const updatedEvents = existingLedger.events.map((event: any) =>
        event.id === eventId || event.eventId === eventId
          ? { ...event, tags: sanitizedTags }
          : event
      );
      return {
        ...state,
        gameActivityLedger: {
          ...existingLedger,
          events: updatedEvents
        }
      };
    }
    case 'CREATE_DIAGNOSTIC_COLLECTION': {
      const newCol: GameActivityLedgerCollection = {
        id: action.payload?.id || nextCorrelationId(globalDeterministicCounters, 'col'),
        name: action.payload?.name || 'Unnamed Collection',
        description: action.payload?.description || '',
        createdTimestamp: Date.now(),
        eventIds: Array.isArray(action.payload?.eventIds) ? action.payload.eventIds : [],
        tags: Array.isArray(action.payload?.tags) ? action.payload.tags : []
      };
      const existingLedger = state.gameActivityLedger || createDefaultGameActivityLedgerState();
      const existingCols = existingLedger.collections || [];
      return {
        ...state,
        gameActivityLedger: {
          ...existingLedger,
          collections: [...existingCols, newCol]
        }
      };
    }
    case 'UPDATE_DIAGNOSTIC_COLLECTION': {
      const { collectionId, updates } = action.payload || {};
      if (!collectionId) return state;
      const existingLedger = state.gameActivityLedger || createDefaultGameActivityLedgerState();
      const existingCols = existingLedger.collections || [];
      const updatedCols = existingCols.map((col: any) =>
        col.id === collectionId
          ? { ...col, ...updates, updatedTimestamp: Date.now() }
          : col
      );
      return {
        ...state,
        gameActivityLedger: {
          ...existingLedger,
          collections: updatedCols
        }
      };
    }
    case 'DELETE_DIAGNOSTIC_COLLECTION': {
      const { collectionId } = action.payload || {};
      if (!collectionId) return state;
      const existingLedger = state.gameActivityLedger || createDefaultGameActivityLedgerState();
      const existingCols = existingLedger.collections || [];
      return {
        ...state,
        gameActivityLedger: {
          ...existingLedger,
          collections: existingCols.filter((c: any) => c.id !== collectionId)
        }
      };
    }
    case 'PRUNE_GAME_ACTIVITY_LEDGER': {
      const existingState = state.gameActivityLedger || createDefaultGameActivityLedgerState();
      const retentionLimit = state.gameSettings?.ledgerPruneRetentionLimit ?? 1000;
      const maxEvents = action.payload?.maxEvents ?? state.gameSettings?.gameActivityLedgerMaxEvents ?? GAME_ACTIVITY_LEDGER_MAX_EVENTS_CEILING;
      const effectiveMaxEvents = Math.min(maxEvents, retentionLimit);
      const policy = action.payload?.policy ?? state.gameSettings?.gameActivityLedgerRetentionPolicy ?? 'keep_recent';

      const pruneResult = pruneLedgerEvents(existingState.events, effectiveMaxEvents, policy);
      const existingArchived = existingState.archivedEvents || [];

      return {
        ...state,
        gameActivityLedger: {
          ...existingState,
          events: pruneResult.activeEvents,
          archivedEvents: [...existingArchived, ...pruneResult.prunedEvents].slice(-retentionLimit)
        }
      };
    }
    case 'CLEAR_ARCHIVED_GAME_ACTIVITY_LEDGER':
    case 'CLEAR_ARCHIVED_LEDGER_EVENTS': {
      const existingState = state.gameActivityLedger || createDefaultGameActivityLedgerState();
      return {
        ...state,
        gameActivityLedger: {
          ...existingState,
          archivedEvents: []
        }
      };
    }
    case 'RESET_GAME': {
      const isTeam = isTeamModeSelection(state.selectedMode || state.gameMode || state.mode) || Boolean(state.teamsById && Object.keys(state.teamsById).length > 0);
      // DIAG1/DIAG2: Instrumentation for RESET_GAME write
      recordDiag2Event('RESET_GAME', {
        actionType: 'RESET_GAME',
        prevActorId: state.currentActorId,
        nextActorId: initialGameState.currentActorId,
        prevTurnCounter: state.turnCounter,
        nextTurnCounter: initialGameState.turnCounter,
        isTeam
      });
      return {
        ...initialGameState,
        gameMode: state.gameMode,
        selectedMode: state.selectedMode,
        aiDifficulty: state.aiDifficulty,
        takeoverSession: null,
        coPilotSettings: {
          ...(state.coPilotSettings || createDefaultCoPilotSettings()),
          coPilotEnabled: false,
          authorityMode: 'off'
        }
      };
    }
    // Phase 7-9 Reducer Actions
    case 'GAIN_CAREER_XP': {
      if (!state.gameSettings?.careerProgressionEnabled) return state;
      const currentProfile = state.careerProfile || createDefaultCareerProfile(state.player?.id || 'player');
      const amount = action.payload?.amount || 0;
      const newXP = currentProfile.totalXP + amount;
      const newLevel = Math.floor(newXP / 1000) + 1;
      const currentTurn = state.turnCounter || state.day || 1;
      const recordIndex = (currentProfile.history?.length || 0) + 1;
      const actionSource = action.payload?.source || 'gameplay';
      const newRecordId = `xp_t${currentTurn}_idx${recordIndex}_${actionSource}`;
      const FIXED_EPOCH = 1704067200000;
      const deterministicTime = new Date(FIXED_EPOCH + (currentTurn - 1) * 86400000).toISOString();
      const newRecord: CareerXPRecord = {
        id: newRecordId,
        timestamp: deterministicTime,
        turn: currentTurn,
        amount,
        source: actionSource,
        description: action.payload?.description || 'Earned XP',
      };
      return {
        ...state,
        careerProfile: {
          ...currentProfile,
          totalXP: newXP,
          currentLevel: newLevel,
          history: [newRecord, ...currentProfile.history].slice(0, 100),
        },
      };
    }
    case 'UNLOCK_ACHIEVEMENT': {
      if (!state.gameSettings?.achievementsEnabled) return state;
      const currentProfile = state.careerProfile || createDefaultCareerProfile(state.player?.id || 'player');
      const achId = action.payload?.achievementId;
      const targetAch = achId ? currentProfile.achievements[achId] : null;
      if (!targetAch || targetAch.unlocked) return state;

      const turnNumber = action.payload?.turn ?? state.day ?? state.turnCounter ?? 1;
      const FIXED_EPOCH = 1704067200000;
      const deterministicTime = new Date(FIXED_EPOCH + (turnNumber - 1) * 86400000).toISOString();
      const updatedAch: CareerAchievement = {
        ...targetAch,
        unlocked: true,
        unlockedAtTurn: turnNumber,
        unlockedAtTimestamp: deterministicTime,
        progress: { ...targetAch.progress, current: targetAch.progress.target },
      };

      const newXP = currentProfile.totalXP + targetAch.xpReward;
      const newLevel = Math.floor(newXP / 1000) + 1;

      return {
        ...state,
        careerProfile: {
          ...currentProfile,
          totalXP: newXP,
          currentLevel: newLevel,
          achievements: {
            ...currentProfile.achievements,
            [achId]: updatedAch,
          },
        },
      };
    }
    case 'UPDATE_CAREER_STATS': {
      if (!state.gameSettings?.careerProgressionEnabled) return state;
      const currentProfile = state.careerProfile || createDefaultCareerProfile(state.player?.id || 'player');
      return {
        ...state,
        careerProfile: {
          ...currentProfile,
          stats: {
            ...currentProfile.stats,
            ...action.payload,
          },
        },
      };
    }
    case 'RESET_CAREER_PROGRESS': {
      return {
        ...state,
        careerProfile: createDefaultCareerProfile(state.player?.id || 'player'),
      };
    }
    case 'SET_INTEL_INVESTMENT': {
      if (!state.gameSettings?.fogOfWarEnabled) return state;
      const { actorId, tier } = action.payload || {};
      if (!actorId) return state;
      const tierInfo = INTEL_INVESTMENT_TIERS[tier as number] || INTEL_INVESTMENT_TIERS[0];
      const newInvestment: IntelInvestment = {
        actorId,
        ...tierInfo,
      };
      return {
        ...state,
        intelInvestments: {
          ...(state.intelInvestments || {}),
          [actorId]: newInvestment,
        },
      };
    }
    case 'DISPATCH_RECON_MISSION':
    case 'EXECUTE_RECON_MISSION': {
      if (!state.gameSettings?.fogOfWarEnabled) return state;
      const mission: ReconMission = action.payload;
      if (!mission || !mission.actorId) return state;
      const actorMissions = state.activeReconMissions?.[mission.actorId] || [];
      return {
        ...state,
        activeReconMissions: {
          ...(state.activeReconMissions || {}),
          [mission.actorId]: [...actorMissions, mission],
        },
      };
    }
    case 'UPDATE_FOG_OF_WAR': {
      if (!state.gameSettings?.fogOfWarEnabled) return state;
      const { regionCode, actorId, level } = action.payload || {};
      if (!regionCode) return state;
      const currentFogState = state.fogOfWarState || {};
      const updatedVis: RegionVisibilityState = {
        regionCode,
        actorId: actorId || 'player',
        fogLevel: level || 'unexplored',
        lastScoutedTurn: state.day || 1,
        activeIntelReportId: currentFogState[regionCode]?.activeIntelReportId || null,
        intelInvestments: currentFogState[regionCode]?.intelInvestments || null,
      };
      return {
        ...state,
        fogOfWarState: {
          ...currentFogState,
          [regionCode]: updatedVis,
        },
      };
    }
    case 'RESOLVE_RECON_MISSION': {
      if (!state.gameSettings?.fogOfWarEnabled) return state;
      const { missionId, success, report } = action.payload || {};
      const updatedMissionsByActor: Record<string, ReconMission[]> = {};
      Object.entries(state.activeReconMissions || {}).forEach(([actId, missions]) => {
        const list = Array.isArray(missions) ? missions : [];
        updatedMissionsByActor[actId] = list.map((m: ReconMission) =>
          m.id === missionId ? { ...m, status: success ? 'completed' : 'failed' } : m
        );
      });

      const targetActorId = report?.targetActorId || 'ai';
      const existingReports = state.intelReports?.[targetActorId] || [];
      const updatedReports = report ? [report, ...existingReports] : existingReports;

      return {
        ...state,
        activeReconMissions: updatedMissionsByActor,
        intelReports: {
          ...(state.intelReports || {}),
          [targetActorId]: updatedReports,
        },
      };
    }
    case 'MODIFY_AI_TRUST': {
      if (!state.gameSettings?.aiRivalryEnabled) return state;
      const { actorId, targetActorId, delta, reason } = action.payload || {};
      if (!actorId || !targetActorId) return state;
      const relState = state.aiRelationshipState || createDefaultAiRelationshipState();
      const currentStatus = relState.relationshipMap[actorId]?.[targetActorId] || createDefaultAiRivalryStatus(actorId, targetActorId);

      const newTrustScore = Math.max(0, Math.min(100, currentStatus.trustScore + (delta || 0)));
      const newStance = getDiplomaticStanceFromTrustScore(newTrustScore);

      const updatedStatus: AiRivalryStatus = {
        ...currentStatus,
        trustScore: newTrustScore,
        stance: newStance,
        historicEvents: [`Turn ${state.day || 1}: ${reason || 'Trust Shift'} (${(delta || 0) >= 0 ? '+' : ''}${delta || 0} Trust)`, ...currentStatus.historicEvents].slice(0, 20),
      };

      return {
        ...state,
        aiRelationshipState: {
          ...relState,
          relationshipMap: {
            ...relState.relationshipMap,
            [actorId]: {
              ...(relState.relationshipMap[actorId] || {}),
              [targetActorId]: updatedStatus,
            },
          },
        },
      };
    }
    case 'SET_DIPLOMATIC_STANCE': {
      if (!state.gameSettings?.aiRivalryEnabled) return state;
      const { actorId, targetActorId, stance } = action.payload || {};
      if (!actorId || !targetActorId) return state;
      const relState = state.aiRelationshipState || createDefaultAiRelationshipState();
      const currentStatus = relState.relationshipMap[actorId]?.[targetActorId] || createDefaultAiRivalryStatus(actorId, targetActorId);

      const updatedStatus: AiRivalryStatus = {
        ...currentStatus,
        stance: stance || 'neutral',
      };

      return {
        ...state,
        aiRelationshipState: {
          ...relState,
          relationshipMap: {
            ...relState.relationshipMap,
            [actorId]: {
              ...(relState.relationshipMap[actorId] || {}),
              [targetActorId]: updatedStatus,
            },
          },
        },
      };
    }
    case 'APPLY_RIVALRY_MODIFIER': {
      if (!state.gameSettings?.aiRivalryEnabled) return state;
      const { actorId, modifier } = action.payload || {};
      if (!actorId || !modifier) return state;
      const relState = state.aiRelationshipState || createDefaultAiRelationshipState();
      const existingMods = relState.rivalryModifiers[actorId] || [];

      return {
        ...state,
        aiRelationshipState: {
          ...relState,
          rivalryModifiers: {
            ...relState.rivalryModifiers,
            [actorId]: [...existingMods, modifier],
          },
        },
      };
    }
    case 'UPDATE_AI_RELATIONSHIPS': {
      if (!state.gameSettings?.aiRivalryEnabled) return state;
      return {
        ...state,
        aiRelationshipState: action.payload,
      };
    }
    case 'SAVE_CUSTOM_SCENARIO': {
      return {
        ...state,
        customScenarioBuilder: {
          ...(state.customScenarioBuilder || {}),
          savedScenarios: [...(state.customScenarioBuilder?.savedScenarios || []), action.payload],
        },
      };
    }
    case 'LOAD_CUSTOM_SCENARIO': {
      const { scenarioId } = action.payload || {};
      const scenarios = state.customScenarioBuilder?.savedScenarios || [];
      const loaded = scenarios.find((s: any) => s.id === scenarioId || s.name === scenarioId);
      if (!loaded) return state;
      return {
        ...state,
        customScenarioBuilder: {
          ...(state.customScenarioBuilder || {}),
          activeScenario: loaded,
        },
      };
    }
    case 'GENERATE_DEBRIEF_REPORT': {
      return {
        ...state,
        debriefAnalytics: action.payload,
      };
    }
    case 'MIGRATE_SAVE_DATA': {
      const migrationResult = migrateSaveToV71Expansion(state);
      return {
        ...state,
        ...(migrationResult.success ? migrationResult.migratedData : {}),
        lastMigrationResult: migrationResult,
      };
    }
    case 'RUN_DETERMINISM_CHECK': {
      const report = verify2xDeterminism(state.rng?.globalSeed || 1337, state.gameSettings);
      return {
        ...state,
        determinismReports: [report, ...(state.determinismReports || [])].slice(0, 10),
      };
    }
    case 'LOG_STATE_CHECKSUM': {
      const checksum = computeCanonicalStateHash(state);
      const record: TurnHashRecord = {
        turn: action.payload?.turn || state.day || 1,
        checksum,
        timestamp: new Date().toISOString(),
      };
      return {
        ...state,
        turnHashHistory: [record, ...(state.turnHashHistory || [])].slice(0, 50),
      };
    }
    case 'SET_TAKEOVER_SESSION':
    case 'UPDATE_TAKEOVER_SESSION': {
      const nextSession = typeof action.payload === 'function' ? action.payload(state.takeoverSession) : action.payload;
      // CPFIX5: Log SET_TAKEOVER_SESSION status transition
      if (state.takeoverSession?.status !== nextSession?.status) {
        recordDiag2Event('SESSION-STATUS', {
          prevStatus: state.takeoverSession?.status,
          nextStatus: nextSession?.status,
          reason: nextSession?.returnReason,
          writer: 'reducer_set_session',
          currentActorId: state.currentActorId,
          turnCounter: state.turnCounter ?? state.turn,
          sessionToken: nextSession?.sessionToken || state.takeoverSession?.sessionToken
        });
      }
      return {
        ...state,
        takeoverSession: nextSession
      };
    }
    case 'UPDATE_GAME_STATE_FUNCTION':
      return typeof action.payload === 'function' ? action.payload(state) : { ...state, ...action.payload };
    // CPFIX2: Dedicated non-destructive commit action for Co-Pilot gameplay action execution
    case 'COPILOT_COMMIT': {
      const p = action.payload || {};
      const excludedKeys = new Set([
        'match', 'gameState', 'deterministicCounters', 'counters'
      ]);
      const safePayload: Record<string, any> = {};
      for (const k of Object.keys(p)) {
        if (!excludedKeys.has(k)) {
          safePayload[k] = p[k];
        }
      }
      if (p.takeoverSession) {
        safePayload.takeoverSession = typeof p.takeoverSession === 'function' ? p.takeoverSession(state.takeoverSession) : p.takeoverSession;
      }
      const isTeam = isTeamModeSelection(state.selectedMode || state.gameMode || state.mode) || Boolean(state.teamsById && Object.keys(state.teamsById).length > 0);
      if ('currentActorId' in safePayload) {
        // DIAG1/DIAG2: Instrumentation for COPILOT_COMMIT currentActorId write
        recordDiag2Event('COPILOT_COMMIT_ACTOR', {
          actionType: 'COPILOT_COMMIT',
          prevActorId: state.currentActorId,
          nextActorId: safePayload.currentActorId,
          turnCounter: state.turnCounter,
          isTeam
        });
      }
      if ('turnCounter' in safePayload) {
        // DIAG1/DIAG2: Instrumentation for COPILOT_COMMIT turnCounter write
        recordDiag2Event('COPILOT_COMMIT_TC', {
          actionType: 'COPILOT_COMMIT',
          prevTurnCounter: state.turnCounter,
          nextTurnCounter: safePayload.turnCounter,
          currentActorId: state.currentActorId,
          isTeam
        });
      }
      if (safePayload.player && typeof safePayload.player === 'object') {
        const hid = safePayload.player.id || state.humanPlayerId || 'player';
        const mergedActors = { ...(state.actorsById || {}), ...(safePayload.actorsById || {}) };
        if (mergedActors[hid] || mergedActors.player) {
          const key = mergedActors[hid] ? hid : 'player';
          mergedActors[key] = {
            ...mergedActors[key],
            ...safePayload.player,
            actionsUsedThisTurn: safePayload.player.actionsUsedThisTurn,
            overrideActionsGranted: safePayload.player.overrideActionsGranted
          };
          safePayload.actorsById = mergedActors;
        }
      }
      return {
        ...state,
        ...safePayload
      };
    }
    case 'LOAD_STATE': {
      const isTeam = isTeamModeSelection(state.selectedMode || state.gameMode || state.mode) || Boolean(state.teamsById && Object.keys(state.teamsById).length > 0);
      if (action.payload && 'currentActorId' in action.payload) {
        // DIAG1/DIAG2: Instrumentation for LOAD_STATE currentActorId write
        recordDiag2Event('LOAD_STATE_ACTOR', {
          actionType: 'LOAD_STATE',
          prevActorId: state.currentActorId,
          nextActorId: action.payload.currentActorId,
          turnCounter: state.turnCounter,
          payloadTurnCounter: action.payload?.turnCounter,
          isTeam
        });
      }
      if (action.payload && 'turnCounter' in action.payload) {
        // DIAG1/DIAG2: Instrumentation for LOAD_STATE turnCounter write
        recordDiag2Event('LOAD_STATE_TC', {
          actionType: 'LOAD_STATE',
          prevTurnCounter: state.turnCounter,
          nextTurnCounter: action.payload.turnCounter,
          currentActorId: state.currentActorId,
          payloadActorId: action.payload.currentActorId,
          isTeam
        });
      }
      // Shallow merge, so any key absent from the payload keeps its CURRENT
      // value. Saves carry no transient turn-execution flags, which meant a
      // live `isAiThinking: true` survived a load and hung the game with no
      // recovery path. Normalise transient flags rather than inherit them.
      return {
        ...state,
        ...action.payload,
        isAiThinking: Boolean(action.payload?.isAiThinking ?? false)
      };
    }
    default:
      if (typeof process !== 'undefined' && process.env?.NODE_ENV !== 'production') {
        console.warn(`[gameStateReducer] Unhandled action type: "${(action as FlexibleAction)?.type}"`, action);
      }
      return state;
  }
}


function buildTeamPlanSteps(
  planType: TeamPlanType,
  goal: TeamGoal,
  aiActorIds: string[],
  context: TeamAiContext
): TeamPlanStep[] {
  if (aiActorIds.length === 0) return [];
  const actorAt = (index: number) => aiActorIds[index % aiActorIds.length];

  const makeStep = (overrides: Partial<TeamPlanStep> & Pick<TeamPlanStep, 'id' | 'order' | 'assignedActorId' | 'actionType'>): TeamPlanStep => ({
    dependsOnStepIds: [],
    requiredCash: 0,
    requiredResources: {},
    status: 'pending',
    overridePermitted: false,
    actionTokenSource: 'normal',
    ...overrides
  });

  switch (planType) {
    case 'crafting_chain':
    case 'resource_chain': {
      const gather = makeStep({ id: 'step-gather', order: 0, assignedActorId: actorAt(0), actionType: 'buy_market', targetKind: 'resource', targetId: goal.targetResource });
      const craft = makeStep({ id: 'step-craft', order: 1, assignedActorId: actorAt(1), actionType: 'craft', dependsOnStepIds: [gather.id] });
      const steps = [gather, craft];
      const winProfile = context?.winCondition ? WIN_METRIC_PROFILES[context.winCondition] : undefined;
      if (winProfile?.goalKind !== 'net_worth') {
        steps.push(makeStep({ id: 'step-sell', order: 2, assignedActorId: actorAt(1), actionType: 'sell', dependsOnStepIds: [craft.id] }));
      }
      return steps;
    }
    case 'region_control_push': {
      const travel = makeStep({ id: 'step-travel', order: 0, assignedActorId: actorAt(0), actionType: 'travel', targetKind: 'region', targetId: goal.targetRegion });
      const deposit = makeStep({ id: 'step-deposit', order: 1, assignedActorId: actorAt(0), actionType: 'region_deposit', targetKind: 'region', targetId: goal.targetRegion, dependsOnStepIds: [travel.id] });
      const steps = [travel, deposit];
      if (aiActorIds.length >= 2) {
        steps.push(makeStep({ id: 'step-reinforce', order: 2, assignedActorId: actorAt(1), actionType: 'region_deposit', targetKind: 'region', targetId: goal.targetRegion, dependsOnStepIds: [deposit.id] }));
      }
      return steps;
    }
    case 'sabotage_followup': {
      const sabotage = makeStep({ id: 'step-sabotage', order: 0, assignedActorId: actorAt(0), actionType: 'sabotage' });
      const followUp = makeStep({ id: 'step-followup', order: 1, assignedActorId: actorAt(1), actionType: 'challenge', dependsOnStepIds: [sabotage.id] });
      return [sabotage, followUp];
    }
    case 'teammate_support':
      return [makeStep({ id: 'step-support', order: 0, assignedActorId: actorAt(0), actionType: 'give_cash' })];
    case 'economic_recovery':
      return [makeStep({ id: 'step-recover', order: 0, assignedActorId: actorAt(0), actionType: 'sell' })];
    case 'investment_setup':
      return [makeStep({ id: 'step-invest', order: 0, assignedActorId: actorAt(0), actionType: 'invest' })];
    case 'endgame_conversion':
      return [makeStep({ id: 'step-convert', order: 0, assignedActorId: actorAt(0), actionType: 'sell' })];
    case 'block_opponent_win':
      return [makeStep({ id: 'step-block', order: 0, assignedActorId: actorAt(0), actionType: 'sabotage' })];
    case 'challenge_push':
      return [makeStep({ id: 'step-challenge', order: 0, assignedActorId: actorAt(0), actionType: 'challenge' })];
    default:
      return [];
  }
}

// V6.7 Phase 3a: generates a persisted TeamPlan, or null if none is warranted this pass. Pure
// function (like chooseTeamObjective) — commitmentRoll is a caller-supplied aiRandom() draw
// (Section 32 determinism: the only RNG source touched anywhere in plan generation), gating
// generation itself so it's probabilistic rather than unconditional.
export function generateTeamPlan(
  team: TeamState,
  opponentTeam: TeamState | null,
  context: TeamAiContext,
  commitmentRoll: number
): TeamPlan | null {
  const strength = Math.max(0, Math.min(100, context?.settings?.teamAiPlanCommitmentStrength ?? 80));
  if (commitmentRoll > strength / 100) return null;

  const goal = chooseTeamObjective(team, opponentTeam, context);
  const planType = mapGoalKindToPlanType(goal, context);
  if (!planType) return null;

  const aiActorIds = (context?.teamActors || []).filter(actor => actor.kind === 'ai').map(actor => actor.id);
  if (aiActorIds.length === 0) return null;

  const steps = buildTeamPlanSteps(planType, goal, aiActorIds, context);
  if (steps.length === 0) return null;

  const day = context?.day || 0;
  const reservedResources = steps.reduce<Record<string, number>>((acc, step) => {
    for (const [resource, qty] of Object.entries(step.requiredResources)) {
      acc[resource] = (acc[resource] || 0) + qty;
    }
    return acc;
  }, {});
  const reservedCash = steps.reduce((sum, step) => sum + step.requiredCash, 0);
  // Heuristic expected value: proportional to the objective's priority and step count, scaled
  // down when the team is already behind (a behind team's plans should be evaluated more
  // cautiously against alternatives) — this reuses only signals chooseTeamObjective/context
  // already expose, not a from-scratch scoring model.
  const expectedValue = goal.priority * 100 * steps.length * ((context?.opponentLead || 0) > 0 ? 0.85 : 1);
  const sensitivity = Math.max(0, Math.min(100, context?.settings?.teamAiPlanInterruptionSensitivity ?? 50));
  const interruptionThreshold = Math.max(0, expectedValue * (1 - sensitivity / 100));
  const expiresDay = day + Math.min(context?.settings?.teamAiPlanMaximumDurationDays ?? 5, steps.length * 2);

  return {
    id: nextDecisionId(globalDeterministicCounters, `team_plan_${team.id}_${day}`),
    type: planType,
    teamId: team.id,
    objective: goal.description,
    priority: goal.priority,
    status: 'active',
    createdDay: day,
    expiresDay,
    assignedActorIds: Array.from(new Set(steps.map(step => step.assignedActorId))),
    steps,
    reservedCash,
    reservedResources,
    expectedValue,
    interruptionThreshold
  };
}

// V6.7 Phase 3a: checks an active plan's continuation status. Priority order — first match wins,
// never combines reasons (the spec's closed 7-value TeamPlanInterruptionReason union and its
// "minor score differences should not constantly replace active plans" safeguard both depend on
// this). liquidityDangerActorIds and candidatePlan are precomputed by the caller (analyzeTeamLiquidity
// and a speculative generateTeamPlan call are both hooks, so this function stays pure/testable).
export function evaluateTeamPlanContinuation(
  plan: TeamPlan,
  team: TeamState,
  context: TeamAiContext,
  liquidityDangerActorIds: string[],
  candidatePlan: TeamPlan | null
): { action: 'continue' | 'complete' | 'interrupt' | 'reevaluate'; reason?: TeamPlanInterruptionReason } {
  const day = context?.day || 0;

  if (plan.steps.every(step => step.status === 'done' || step.status === 'skipped')) {
    return { action: 'complete' };
  }

  // Stalled-plan heuristic for "expected value collapsed": no progress made past the halfway
  // point of the plan's allotted duration is treated as the value no longer being realizable.
  const stepsDone = plan.steps.filter(step => step.status === 'done').length;
  const halfLifeDay = plan.createdDay + Math.max(1, Math.round((plan.expiresDay - plan.createdDay) / 2));
  if (stepsDone === 0 && day > halfLifeDay) {
    return { action: 'interrupt', reason: 'expected_value_collapsed' };
  }

  const opponentLead = context?.opponentLead || 0;
  const totalDays = context?.totalDays || 30;
  const nearEndgame = totalDays > 0 && day >= totalDays * 0.8;
  if (nearEndgame && opponentLead > (context?.teamScore?.total || 0) * 0.5 && opponentLead > 0) {
    return { action: 'interrupt', reason: 'opponent_immediate_win_threat' };
  }

  if (plan.assignedActorIds.some(actorId => liquidityDangerActorIds.includes(actorId))) {
    return { action: 'interrupt', reason: 'actor_financial_danger' };
  }

  if (plan.assignedActorIds.some(actorId => !(team.actorIds || []).includes(actorId))) {
    return { action: 'interrupt', reason: 'completion_impossible' };
  }

  if (day > plan.expiresDay) {
    return { action: 'interrupt', reason: 'completion_impossible' };
  }

  const sensitivity = Math.max(0, Math.min(100, context?.settings?.teamAiPlanInterruptionSensitivity ?? 50));
  if (candidatePlan && candidatePlan.expectedValue >= plan.expectedValue * (1 + (sensitivity / 100) * 0.5)) {
    return { action: 'interrupt', reason: 'stronger_opportunity' };
  }

  const reevaluationFrequency = Math.max(1, context?.settings?.teamAiPlanReevaluationFrequency ?? 3);
  if (day % reevaluationFrequency === 0) {
    return { action: 'reevaluate' };
  }

  return { action: 'continue' };
}

// Team AI Overseer System Phase O5: maps a TeamGoal's kind to the categories of action a
// Strategic Command directive addressing that goal should permit — same lookup-table style as
// TEAM_PLAN_TYPE_TO_GOAL_KIND/mapGoalKindToPlanType above, not a new abstraction.
export const mapGoalKindToAllowedActionCategories = (kind: TeamGoal['kind']): TeamModeActionCategory[] => {
  switch (kind) {
    case 'control':
    case 'regions':
      return ['region_deposit', 'travel'];
    case 'support':
      return ['support'];
    case 'sabotage':
      return ['sabotage'];
    case 'netWorth':
      return ['craft', 'invest', 'sell'];
    case 'crafting':
      return ['craft', 'buy_market'];
    case 'recovery':
      return ['support', 'challenge', 'sell'];
    case 'money':
    default:
      return ['sell', 'craft', 'buy_market'];
  }
};

// Team AI Overseer System Phase O7 (GD4): picks the single most profitable recipe (reusing the
// exact profit comparison already used elsewhere: sell value vs. ingredient cost) and lists which
// of its ingredients the actor is currently short on — display-only, no new profitability formula,
// no new acquisition mechanic (existing market-purchase/crafting scoring already handles that).
const computeDirectiveRequiredResources = (actor: { inventory?: string[] }): string[] => {
  const inventory = actor.inventory || [];
  let bestRecipe: (typeof CRAFTING_RECIPES)[number] | null = null;
  let bestProfit = -Infinity;
  for (const recipe of CRAFTING_RECIPES) {
    const ingredientCost = Object.entries(recipe.inputs).reduce(
      (sum, [resource, count]) => sum + getResourceMarketPrice(resource) * Number(count), 0
    );
    const sellValue = recipe.baseValue || getResourceMarketPrice(recipe.output);
    const profit = sellValue - ingredientCost;
    if (profit > bestProfit) {
      bestProfit = profit;
      bestRecipe = recipe;
    }
  }
  if (!bestRecipe) return [];
  return Object.entries(bestRecipe.inputs)
    .filter(([resource, count]) => inventory.filter(item => item === resource).length < Number(count))
    .map(([resource]) => resource);
};

// Team AI Overseer System Phase O5: builds one TeamDirective for a single AI actor from the
// team's already-chosen objective (chooseTeamObjective, reused verbatim by the caller — not
// re-derived per actor). Shadow/Advisory display only this phase originally; Phase O7 made
// maxSpending/requiredResources real (see below) — treasuryAllocation is still populated at
// creation time as 0 and only ever set by the O7 directive-scoped funding-request trigger
// inside performTeamAiTurn, since it depends on a live shortfall check, not just the goal.
// successCondition/failureCondition are still plain display strings, not yet evaluated against
// real outcomes (a future phase gives them a real trigger once directives are observably tied to
// completion/failure).
export function generateTeamDirective(
  actor: ActorState,
  team: TeamState,
  goal: TeamGoal,
  context: TeamAiContext,
  day: number,
  turn: number
): TeamDirective {
  const totalDays = context?.totalDays || 30;
  const endgameActive = isEndgamePeriod(day, totalDays, context?.settings?.teamAiEndgameStartPercent ?? 80);
  const horizon: TeamDirective['horizon'] = endgameActive
    ? 'endgame'
    : (actor.inEconomicRecovery || goal.kind === 'recovery')
      ? 'immediate'
      : 'short_term';
  // Team AI Overseer System Phase O10 (GD5): personality multipliers — 'balanced' (default) is an
  // exact identity (1.0), so this is a provable no-op unless the player explicitly changes it.
  const personality = context?.settings?.teamAiStrategicCommandPersonality;
  const personalityProfile = (personality && OVERSEER_PERSONALITY_PROFILES[personality]) || OVERSEER_PERSONALITY_PROFILES.balanced;
  const expiresDay = horizon === 'immediate'
    ? day + 1
    : horizon === 'endgame'
      ? day + Math.max(1, totalDays - day)
      : day + Math.max(1, Math.round((context?.settings?.teamAiStrategicCommandDirectiveDurationDays ?? 3) * personalityProfile.directiveDurationMultiplier));
  // Team AI Overseer System Phase O7 (GD1): a real spending cap, computed once at creation time
  // from the actor's current spendable cash — reused verbatim, never re-derived, at the O6 bias
  // site in getRankedTeamAiDecisions as an additional filter on the scoring bonus.
  const vaultActive = (context?.settings?.teamCompetitiveAiEnabled ?? false) && (context?.settings?.teamCashVaultEnabled ?? false);
  const maxSpendingPercent = context?.settings?.teamAiStrategicCommandMaxSpendingPercent ?? 50;
  const maxSpending = Math.round(getActorSpendableCash(actor, vaultActive) * (maxSpendingPercent / 100) * personalityProfile.maxSpendingMultiplier);
  // Team AI Overseer System Phase O7 (GD4): crafting-oriented directives list genuinely-missing
  // ingredients for the actor's best-available recipe (reusing CRAFTING_RECIPES/inventory checks
  // already used elsewhere) — display-only; acquisition is already handled by the existing
  // market-purchase/crafting decision scoring, never a new fulfillment mechanic.
  const requiredResources = goal.kind === 'crafting' ? computeDirectiveRequiredResources(actor) : [];
  return {
    id: nextDecisionId(globalDeterministicCounters, `directive_${team.id}_${actor.id}_${day}`),
    teamId: team.id,
    assignedActorId: actor.id,
    objective: goal.description,
    horizon,
    priority: goal.priority,
    createdDay: day,
    createdTurn: turn,
    expiresDay,
    maxSpending,
    treasuryAllocation: 0,
    requiredResources,
    allowedActionCategories: mapGoalKindToAllowedActionCategories(goal.kind),
    successCondition: `Team's ${context?.winCondition || 'win'} metric improves before this directive expires.`,
    failureCondition: 'Directive expires with no measurable progress.',
    retryLimit: 1,
    retryCount: 0,
    fallback: 'reassess next cycle',
    reassignmentPermitted: true,
    status: 'proposed'
  };
}

// Team AI Overseer System Phase O5: deliberately minimal lifecycle this phase — a directive only
// ever expires on its own schedule. Real completion/failure detection tied to observed actor
// behavior is Phase O6+'s job, once directives can actually be seen influencing decisions.
function evaluateTeamDirectiveContinuation(directive: TeamDirective, currentDay: number): 'continue' | 'expire' {
  return currentDay >= directive.expiresDay ? 'expire' : 'continue';
}

