export interface ExpeditionLegEvaluationResult {
  eligible: boolean;
  score: number;
  reason: string;
  projectedSupplyCost: number;
  supplyRatio: number;
  recommendedRestockAmount?: number;
}

export function evaluateExpeditionLegStart(
  actor: any,
  campaign: ExpeditionCampaign,
  leg: ExpeditionLeg,
  gameState: any,
  settings: any,
  difficultyKey: string = 'medium'
): ExpeditionLegEvaluationResult {
  const currentSupplies = actor?.currentSupplies ?? 100;
  const maxSupplies = actor?.maxSupplies ?? 100;
  const dailyBurn = settings?.dailySupplyConsumptionRate ?? 10;
  
  // 1. Projected Supply Requirement
  const transitCost = (leg.distanceTurns || 3) * dailyBurn;
  const dangerBuffer = (leg.baseDangerRating || 3) * 8;
  const projectedSupplyCost = transitCost + dangerBuffer;
  const minSafeSupplies = Math.ceil(maxSupplies * 0.20) + projectedSupplyCost;
  
  const supplyRatio = currentSupplies / Math.max(1, projectedSupplyCost);

  // 2. Unsafe / Supply Starvation Check
  if (currentSupplies < projectedSupplyCost || (currentSupplies - projectedSupplyCost) / maxSupplies <= 0.15) {
    const neededRestock = Math.min(maxSupplies - currentSupplies, minSafeSupplies - currentSupplies);
    return {
      eligible: false,
      score: -1000,
      reason: `Insufficient supplies (${currentSupplies}/${projectedSupplyCost} needed). Risk of forced retreat.`,
      projectedSupplyCost,
      supplyRatio,
      recommendedRestockAmount: neededRestock > 0 ? neededRestock : undefined
    };
  }

  // 3. Reward & Strategic Value
  const rewardMoney = campaign.completionReward?.bonusMoney || 50000;
  const rewardStanding = campaign.completionReward?.bonusStanding || 40;
  let baseScore = (rewardMoney / 1000) + (rewardStanding * 2.5);

  // Leg progression weighting (higher legs offer bigger climax rewards)
  baseScore += (leg.legNumber || 1) * 25;

  // 4. Supply Comfort Bonus / Penalty
  if (supplyRatio >= 1.5) {
    baseScore += 35; // Well-provisioned
  } else if (supplyRatio >= 1.2) {
    baseScore += 15;
  }

  // 5. Danger & Equipment Mitigation
  let dangerPenalty = (leg.baseDangerRating || 3) * 12;
  const hasSubAntarcticGear = (actor?.equipment || []).includes('Sub-Antarctic Gear') || (actor?.inventory || []).includes('Sub-Antarctic Gear');
  const hasThermalGear = (actor?.equipment || []).includes('Thermal Survival Gear') || (actor?.inventory || []).includes('Thermal Survival Gear');
  if (hasSubAntarcticGear || hasThermalGear) {
    dangerPenalty *= 0.5; // 50% danger reduction from protective gear
  }
  baseScore -= dangerPenalty;

  // 6. Difficulty Profile Scaling
  const profile = (AI_DIFFICULTY_PROFILES as unknown as Record<string, any>)[difficultyKey] || AI_DIFFICULTY_PROFILES.medium;
  const finalScore = Math.max(0, baseScore * (profile?.decisionQuality || 1.0) * (profile?.riskTolerance || 1.0));

  return {
    eligible: true,
    score: finalScore,
    reason: `Viable leg candidate. Projected supply cost: ${projectedSupplyCost}, ratio: ${supplyRatio.toFixed(2)}`,
    projectedSupplyCost,
    supplyRatio
  };
}

export function determineAiExpeditionRiskChoice(
  actor: any,
  team: any = null,
  context: Partial<TeamAiContext> = {},
  target?: ExpeditionTarget
): ExpeditionRiskChoice {
  const teamAiProfile = context.settings?.teamModeAiSystemProfile
    ? normalizeTeamModeAiSystemProfile(context.settings.teamModeAiSystemProfile)
    : 'classic';
  
  const assignedTeamAiRole = (context as Record<string, unknown>)?.assignedTeamAiRole || actor?.assignedTeamRole || 'explorer';

  // Base profile score B_profile
  let bProfile = 0.50;
  if (teamAiProfile === 'chaos_team') {
    bProfile = 0.95;
  } else if (teamAiProfile === 'competitive') {
    bProfile = 0.80;
  } else if (teamAiProfile === 'role_based') {
    switch (assignedTeamAiRole) {
      case 'saboteur': bProfile = 0.90; break;
      case 'explorer': bProfile = 0.75; break;
      case 'controller': bProfile = 0.60; break;
      case 'earner':
      case 'crafter': bProfile = 0.50; break;
      case 'support': bProfile = 0.30; break;
      case 'recovery': bProfile = 0.25; break;
      default: bProfile = 0.50;
    }
  } else if (teamAiProfile === 'region_control') {
    bProfile = 0.65;
  } else if (teamAiProfile === 'economy_engine') {
    bProfile = 0.50;
  } else if (teamAiProfile === 'cooperative') {
    bProfile = 0.35;
  } else if (teamAiProfile === 'support_heavy') {
    bProfile = 0.20;
  } else {
    bProfile = 0.50;
  }

  // Modifiers
  let deltaPosture = 0;
  const dynamicRiskPosture = getDynamicRiskPosture(actor, team || null, null, context);
  if (dynamicRiskPosture === 'desperate') deltaPosture = 0.25;
  else if (dynamicRiskPosture === 'aggressive') deltaPosture = 0.15;
  else if (dynamicRiskPosture === 'conservative') deltaPosture = -0.20;

  let deltaStrategy = 0;
  const aiStrategy = actor?.character?.aiStrategy;
  if (aiStrategy === 'challenge-focused') deltaStrategy = 0.10;
  else if (aiStrategy === 'money-focused') deltaStrategy = -0.10;

  let deltaTarget = 0;
  if (target && (target.dangerRating ?? 0) >= 4) {
    deltaTarget = -0.10;
  }

  let deltaVariance = 0;
  if (context.winCondition && WIN_METRIC_PROFILES[context.winCondition]) {
    const winRisk = WIN_METRIC_PROFILES[context.winCondition]?.riskPosture;
    if (winRisk) {
      const vApp = winRisk.varianceAppetite ?? 1.0;
      const lAv = winRisk.lossAversion ?? 1.0;
      deltaVariance = ((vApp - 1.0) * 0.25) - ((lAv - 1.0) * 0.25);
    }
  }

  const compositeBoldness = bProfile + deltaPosture + deltaStrategy + deltaTarget + deltaVariance;

  if (compositeBoldness >= 0.80) return 'extreme';
  if (compositeBoldness >= 0.55) return 'aggressive';
  if (compositeBoldness >= 0.30) return 'balanced';
  return 'cautious';
}

