// ============================================================================
// SECTION 8: ECONOMY AND TEAM SYSTEMS
// ============================================================================
const calculateCreditScore = (player: any, gameState: any): number => {
  let score = 50; // Base score

  const loanHistory = player.loanHistory || { totalTaken: 0, totalRepaid: 0, defaultCount: 0, earlyRepaymentCount: 0 };
  const advancedLoans = player.advancedLoans || [];

  // Repayment history (±30 points)
  if (loanHistory.totalTaken > 0) {
    const repaymentRate = loanHistory.totalRepaid / loanHistory.totalTaken;
    score += Math.floor(repaymentRate * 30) - 15;
  }

  // Early repayments (+10 max)
  score += Math.min(10, loanHistory.earlyRepaymentCount * 2);

  // Defaults (-20 per default)
  score -= loanHistory.defaultCount * 20;

  // Net worth (±20 points)
  const netWorth = player.money + (player.inventory?.length || 0) * 50;
  if (netWorth > 5000) score += 20;
  else if (netWorth > 3000) score += 10;
  else if (netWorth > 1000) score += 0;
  else if (netWorth > 500) score -= 10;
  else score -= 20;

  // Active loans penalty (-5 per loan)
  score -= advancedLoans.length * 5;

  // Days without bankruptcy (+1 per 3 days, max +10)
  const daysSinceBankruptcy = player.daysSinceLastBankruptcy || 0;
  score += Math.min(10, Math.floor(daysSinceBankruptcy / 3));

  // Challenge completion rate (+10 max)
  const totalChallenges = Object.values(REGIONS).reduce((sum: number, region: any) => sum + region.challenges.length, 0);
  const completedChallenges = player.challengesCompleted?.length || 0;
  if (completedChallenges > 0) {
    const completionRate = completedChallenges / totalChallenges;
    score += Math.min(10, Math.floor(completionRate * 10));
  }

  // Clamp to 0-100
  return Math.max(0, Math.min(100, score));
};

const getCreditScoreRange = (score: number) => {
  return CREDIT_SCORE_RANGES.find(range => score >= range.min && score <= range.max) || CREDIT_SCORE_RANGES[4];
};

const calculateLoanInterest = (loan: AdvancedLoan, creditScoreMultiplier: number, accrualRate: number): number => {
  const dailyRate = loan.actualInterestRate / loan.term;
  return loan.amount * dailyRate * accrualRate;
};

const getEarlyRepaymentDiscount = (): number => {
  return 0.5; // 50% discount on interest for early repayment
};

const checkLoanEvent = (player: any, settings: GameSettingsState): typeof LOAN_EVENTS[0] | null => {
  if (!settings.loanEventsEnabled) return null;

  for (const event of LOAN_EVENTS) {
    if (event.triggerCondition(player)) {
      // Random chance to trigger (30% when conditions met)
      if (drawGameplayRandom('RandomEvents') < 0.3) {
        return event;
      }
    }
  }
  return null;
};

// =========================================
// ADAPTIVE AI HELPER FUNCTIONS
// =========================================

function calculateItemPrices(
  baseCost: number,
  itemCategory: string,
  turnCounter: number,
  regionId?: string,
  weather?: string,
  season?: string,
  eventMultiplier?: number,
  isRegionControlled?: boolean
): number {
  if (typeof baseCost !== 'number' || !Number.isFinite(baseCost) || baseCost <= 0) {
    return 0;
  }
  const turn = typeof turnCounter === 'number' && Number.isFinite(turnCounter) ? Math.max(0, turnCounter) : 0;
  const turnInflation = 1 + turn * 0.01;

  const categoryLower = (itemCategory || '').toLowerCase();
  let categoryDemand = 1.0;
  if (categoryLower === 'luxury') categoryDemand = 1.2;
  else if (categoryLower === 'energy') categoryDemand = 1.15;
  else if (categoryLower === 'consumable') categoryDemand = 1.05;
  else if (categoryLower === 'food') categoryDemand = 0.95;
  else if (categoryLower === 'gear' || categoryLower === 'equipment') categoryDemand = 1.0;

  let weatherMod = 1.0;
  if (weather && WEATHER_EFFECTS[weather]) {
    weatherMod = WEATHER_EFFECTS[weather].travelCostModifier || 1.0;
  }

  let seasonMod = 1.0;
  if (season && SEASON_EFFECTS[season]) {
    const resMod = SEASON_EFFECTS[season].resourcePriceModifier;
    if (resMod && typeof resMod[categoryLower] === 'number') {
      seasonMod = resMod[categoryLower];
    }
  }

  const eventMod = typeof eventMultiplier === 'number' && Number.isFinite(eventMultiplier) && eventMultiplier > 0
    ? eventMultiplier
    : 1.0;

  const controlled = isRegionControlled ?? (typeof regionId === 'string' && (regionId.toLowerCase().includes('controlled') || regionId.toLowerCase().includes('team')));
  const regionDiscount = controlled ? 0.85 : 1.0;

  const finalPrice = baseCost * turnInflation * categoryDemand * weatherMod * seasonMod * eventMod * regionDiscount;
  return Math.max(0, Math.round(finalPrice));
}

/**
 * Calculates the effective item cost for a given item and actor, incorporating game state factors
 * such as turn inflation, item category demand, weather effects, season price modifiers, active event
 * price multipliers, and region control discounts via `calculateItemPrices`.
 */
function getEffectiveItemCost(
  item: any,
  actor?: any,
  gameState?: any
): number {
  if (!item) return 0;

  let itemObj = item;
  if (typeof item === 'string') {
    itemObj = SHOP_ITEMS.find(c => c.id === item) || { cost: 0, category: 'gear' };
  }

  const baseCost = typeof itemObj === 'number'
    ? itemObj
    : (itemObj.cost ?? itemObj.baseCost ?? itemObj.price ?? 0);

  if (baseCost <= 0) return 0;

  const category = (typeof itemObj === 'object' && (itemObj.category || (itemObj.tags && itemObj.tags[0]))) || 'gear';
  const turnCounter = gameState?.turnCounter ?? gameState?.day ?? actor?.turnCount ?? 0;
  const regionId = actor?.currentRegion ?? actor?.location ?? gameState?.currentRegion;
  const weather = gameState?.weather ?? gameState?.currentWeather;
  const season = gameState?.season ?? gameState?.currentSeason;
  const eventMultiplier = gameState?.eventMultiplier ?? gameState?.activeEvent?.priceMultiplier;
  const isRegionControlled = gameState?.regionControl && regionId && actor?.teamId
    ? Boolean(gameState.regionControl[regionId] === actor.teamId)
    : undefined;

  let cost = calculateItemPrices(
    baseCost,
    category,
    turnCounter,
    regionId,
    weather,
    season,
    eventMultiplier,
    isRegionControlled
  );

  if (gameState?.gameSettings?.regionalStandingEnabled && actor?.id && regionId) {
    const standing = getActorRegionalStanding(gameState, actor.id, regionId);
    const standingMult = getRegionalStandingMultipliers(standing).itemDiscount;
    cost = Math.max(0, Math.round(cost * (1 - standingMult)));
  }

  if (actor?.masteryUnlocks?.includes("Negotiator")) {
    cost = Math.floor(cost * 0.8);
  }

  if (actor?.costReductionPct || actor?.priceInflationPct) {
    const costRed = actor?.costReductionPct ?? 0;
    const priceInf = actor?.priceInflationPct ?? 0;
    const modifierMult = Math.max(0, 1 - costRed + priceInf);
    cost = Math.max(0, Math.round(cost * modifierMult));
  }

  return cost;
}

function getEffectiveInvestmentCost(cost: number, actor?: any): number {
  if (typeof cost !== 'number' || cost <= 0) return 0;
  let finalCost = cost;
  if (actor?.masteryUnlocks?.includes("Negotiator")) {
    finalCost = Math.floor(finalCost * 0.8);
  }
  if (actor?.costReductionPct || actor?.priceInflationPct) {
    const costRed = actor?.costReductionPct ?? 0;
    const priceInf = actor?.priceInflationPct ?? 0;
    const modifierMult = Math.max(0, 1 - costRed + priceInf);
    finalCost = Math.max(0, Math.round(finalCost * modifierMult));
  }
  return finalCost;
}

function getActorStats(actor: any): { strength: number; charisma: number; luck: number; intelligence: number } {
  const baseStats = actor?.stats || actor?.startingStats || { strength: 3, charisma: 3, luck: 3, intelligence: 3 };
  const str = typeof baseStats.strength === 'number' ? baseStats.strength : 3;
  const cha = typeof baseStats.charisma === 'number' ? baseStats.charisma : 3;
  const luk = typeof baseStats.luck === 'number' ? baseStats.luck : 3;
  const int = typeof baseStats.intelligence === 'number' ? baseStats.intelligence : 3;
  const isMastermind = Boolean(actor?.masteryUnlocks?.includes("Mastermind"));
  const bonus = isMastermind ? 2 : 0;
  return {
    strength: str + bonus,
    charisma: cha + bonus,
    luck: luk + bonus,
    intelligence: int + bonus
  };
}

function applyInvestmentReturn(
  baseYield: number,
  turnCounter: number,
  actorLevel: number,
  isEntrepreneur: boolean,
  weather?: string,
  season?: string,
  eventYieldMultiplier?: number
): number {
  if (typeof baseYield !== 'number' || !Number.isFinite(baseYield) || baseYield <= 0) {
    return 0;
  }

  const turn = typeof turnCounter === 'number' && Number.isFinite(turnCounter) ? Math.max(0, turnCounter) : 0;
  const turnMarketFactor = 1 + turn * 0.005;

  const level = typeof actorLevel === 'number' && Number.isFinite(actorLevel) ? Math.max(1, actorLevel) : 1;
  const levelScaling = 1 + (level - 1) * 0.04;

  const entrepreneurBonus = isEntrepreneur ? 1.2 : 1.0;

  let weatherMod = 1.0;
  if (weather && WEATHER_EFFECTS[weather]) {
    weatherMod = 1 + (WEATHER_EFFECTS[weather].resourceBonus || 0);
  }

  let seasonMod = 1.0;
  if (season && SEASON_EFFECTS[season]) {
    seasonMod = 1 + (SEASON_EFFECTS[season].bonusResourceChance || 0);
  }

  const eventMod = typeof eventYieldMultiplier === 'number' && Number.isFinite(eventYieldMultiplier) && eventYieldMultiplier > 0
    ? eventYieldMultiplier
    : 1.0;

  const finalYield = baseYield * turnMarketFactor * levelScaling * entrepreneurBonus * weatherMod * seasonMod * eventMod;
  return Math.max(0, Math.round(finalYield));
}

/**
 * Calculates actor-scaled investment returns, incorporating level scaling, entrepreneur trait bonuses,
 * weather modifiers, seasonal multipliers, and active event yield multipliers via `applyInvestmentReturn`.
 */
function getActorScaledInvestmentReturn(
  baseYield: number,
  actor: any,
  turnCounter: number,
  weather?: string,
  season?: string,
  activeEvents?: any[],
  gameState?: any
): number {
  let eventYieldMultiplier = 1.0;
  if (Array.isArray(activeEvents)) {
    activeEvents.forEach((ev: any) => {
      if (ev?.effect?.investmentYieldMultiplier && typeof ev.effect.investmentYieldMultiplier === 'number') {
        eventYieldMultiplier *= ev.effect.investmentYieldMultiplier;
      }
    });
  }

  let relicIncomeMultiplier = 1.0;
  if (actor?.equippedRelics) {
    Object.values(actor.equippedRelics).forEach((relic: any) => {
      if (relic && Array.isArray(relic.passiveEffects)) {
        relic.passiveEffects.forEach((eff: RelicPassiveEffect) => {
          if (eff.statKey === 'income_multiplier') {
            relicIncomeMultiplier += eff.modifierValue;
          }
        });
      }
    });
  }

  let infraIncomeMultiplier = 1.0;
  if (gameState?.infrastructureProjects) {
    Object.values(gameState.infrastructureProjects).forEach((proj: any) => {
      if ((proj.status === 'active' || proj.status === 'upgraded') && proj.providedBonuses) {
        proj.providedBonuses.forEach((eff: InfrastructureBonusEffect) => {
          if (eff.type === 'income_boost') {
            infraIncomeMultiplier += eff.magnitude;
          }
        });
      }
    });
  }

  const isEntrepreneur = Boolean(
    actor?.isEntrepreneur ||
    actor?.character?.name === 'Entrepreneur' ||
    actor?.character?.name === 'Businessman' ||
    actor?.role === 'Entrepreneur'
  );
  const actorLevel = typeof actor?.level === 'number' && Number.isFinite(actor.level) ? actor.level : 1;

  let autoModeIncomeMultiplier = 1.0;
  if (actor?.incomeSubsidyPct) {
    autoModeIncomeMultiplier += actor.incomeSubsidyPct;
  }
  if (actor?.handicapPenaltyPct) {
    autoModeIncomeMultiplier -= actor.handicapPenaltyPct;
  }
  autoModeIncomeMultiplier = Math.max(0, autoModeIncomeMultiplier);

  const totalMultiplier = eventYieldMultiplier * relicIncomeMultiplier * infraIncomeMultiplier * autoModeIncomeMultiplier;

  return applyInvestmentReturn(
    baseYield,
    turnCounter,
    actorLevel,
    isEntrepreneur,
    weather,
    season,
    totalMultiplier
  );
}



export const calculateNetWorth = (player: any, resourcePrices?: Record<string, number> | null): number => {
  if (!player) return 0;
  const money = typeof player.money === 'number' && Number.isFinite(player.money) ? player.money : 0;
  const inventory = Array.isArray(player.inventory) ? player.inventory : [];
  const inventoryValue = calculateInventoryMarketValue(inventory, resourcePrices);
  const investments = Array.isArray(player.investments) ? player.investments : [];
  const investmentsValue = investments.reduce((sum: number, regionCode: string) => {
    return sum + (REGIONAL_INVESTMENTS[regionCode]?.cost || 0);
  }, 0);
  const equipment = Array.isArray(player.equipment) ? player.equipment : [];
  const equipmentValue = equipment.reduce((sum: number, itemId: string) => {
    return sum + (SHOP_ITEMS.find(item => item.id === itemId || item.name === itemId)?.cost || 0);
  }, 0);
  const loans = Array.isArray(player.loans) ? player.loans : [];
  const advancedLoans = Array.isArray(player.advancedLoans) ? player.advancedLoans : [];

  const simpleLoanDebt = loans.reduce((sum: number, loan: any) => {
    if (typeof loan === 'number') return sum + (Number.isFinite(loan) ? loan : 0);
    const amount = typeof loan?.amount === 'number' && Number.isFinite(loan.amount) ? loan.amount : 0;
    const accrued = typeof loan?.accrued === 'number' && Number.isFinite(loan.accrued) ? loan.accrued : 0;
    const totalOwed = typeof loan?.totalOwed === 'number' && Number.isFinite(loan.totalOwed) ? loan.totalOwed : 0;
    const val = totalOwed || (amount + accrued) || 0;
    return sum + val;
  }, 0);

  const advancedLoanDebt = advancedLoans.reduce((sum: number, loan: any) => {
    if (typeof loan === 'number') return sum + (Number.isFinite(loan) ? loan : 0);
    const amount = typeof loan?.amount === 'number' && Number.isFinite(loan.amount) ? loan.amount : 0;
    const accrued = typeof loan?.accruedInterest === 'number' && Number.isFinite(loan.accruedInterest) ? loan.accruedInterest : (typeof loan?.accrued === 'number' && Number.isFinite(loan.accrued) ? loan.accrued : 0);
    const totalOwed = typeof loan?.totalOwed === 'number' && Number.isFinite(loan.totalOwed) ? loan.totalOwed : 0;
    const val = totalOwed || (amount + accrued) || 0;
    return sum + val;
  }, 0);

  const totalDebt = (simpleLoanDebt + advancedLoanDebt) > 0
    ? (simpleLoanDebt + advancedLoanDebt)
    : (typeof player.debt === 'number' && Number.isFinite(player.debt) ? player.debt : (typeof player.loans === 'number' && Number.isFinite(player.loans) ? player.loans : 0));
  const rawWorth = money + inventoryValue + investmentsValue + equipmentValue - totalDebt;
  return Number.isFinite(rawWorth) ? rawWorth : 0;
};

// V6.8 Phase B: Ratcheting Cash Vault. Base milestone ladder matching the spec's examples
// ($2k/$5k/$10k/$20k/$40k), extended indefinitely by doubling the last value, all scaled by
// vaultMilestoneSizeMultiplier so the whole ladder can shift without redefining its shape.
const getVaultMilestoneLadder = (multiplier: number, tierCount: number = 12): number[] => {
  const scale = isFinite(multiplier) && multiplier > 0 ? multiplier : 1.0;
  const ladder = VAULT_BASE_MILESTONES.map(value => value * scale);
  while (ladder.length < tierCount) {
    ladder.push(ladder[ladder.length - 1] * 2);
  }
  return ladder;
};

// Protected cash is a soft floor on the same actor.money field, never a second balance — this is
// the sole accessor voluntary AI spending gates should consult for affordability once the Vault is
// enabled. Returns raw money unchanged (byte-identical to today) when vaultActive is false.
const getActorSpendableCash = (actor: { money: number; protectedCash?: number }, vaultActive: boolean): number => {
  if (!vaultActive) return actor.money;
  return Math.max(0, actor.money - Math.min(actor.protectedCash || 0, actor.money));
};

// V6.8 Phase C: Team Economy Governor. All three helpers below are plain, module-level pure
// functions (not hooks) specifically so they can be called from existing functions declared at
// any point in the file — including ones declared long before the component's other Team AI
// checker cluster — without any forward-reference/TDZ concern.

// Reuses the same percentElapsed concept Phase 3b's computeEndgameAccelerationState established,
// but as a standalone calculation independent of that feature's own teamAiEndgameAccelerationEnabled
// toggle — the Governor's Endgame phase is a distinct concept that can be active even when Phase
// 3b's Endgame Acceleration feature itself is off.
const isEndgamePeriod = (day: number, totalDays: number, startPercent: number): boolean => {
  const percentElapsed = totalDays > 0 ? day / totalDays : 0;
  return percentElapsed >= startPercent;
};

// Four economic phases, computed on demand (never persisted) — only the recovery flag itself
// (ActorState.inEconomicRecovery) is persisted; everything else is derived fresh each call.
const computeTeamTreasuryReserve = (
  teamActors: { inEconomicRecovery?: boolean }[],
  settings: GameSettingsState,
  day: number,
  endgameActive: boolean
): number => {
  if (!settings.teamTreasuryDynamicReserveEnabled) return settings.teamTreasuryReserve;
  const teammateCountFactor = 1 + Math.max(0, teamActors.length - 1) * 0.15;
  const dayRatioFactor = 1 + Math.min(0.5, (day / Math.max(1, settings.totalDays)) * 0.3);
  const recoveryActorFactor = 1 + teamActors.filter(a => a.inEconomicRecovery).length * 0.25;
  const endgameFactor = endgameActive ? 0.7 : 1.0;
  return Math.round(settings.teamTreasuryReserve * teammateCountFactor * dayRatioFactor * recoveryActorFactor * endgameFactor);
};

export const evaluateEconomySpendingApproval = (
  actor: { money: number; protectedCash?: number; inEconomicRecovery?: boolean; id?: string; currentRegion?: string },
  category: EconomySpendCategory,
  cost: number,
  settings: GameSettingsState,
  currentDay: number,
  context?: { expectedReturn?: number; gameState?: any },
  gameStateParam?: any
): { approved: boolean; reason: string; phase: EconomicPhase } => {
  if (!settings.teamCompetitiveAiEnabled || !settings.teamEconomyGovernorEnabled) {
    return { approved: true, reason: 'Economy Governor is off.', phase: 'accumulation' };
  }
  const spendableCash = getActorSpendableCash(actor, settings.teamCashVaultEnabled);
  const endgameActive = isEndgamePeriod(currentDay, settings.totalDays, settings.teamAiEndgameStartPercent);
  const phase = computeEconomicPhase(actor, spendableCash, settings, endgameActive);
  const reserve = computeDynamicReserve(phase, spendableCash, settings);
  if ((spendableCash - cost) < reserve) {
    return { approved: false, reason: `${phase} phase reserve of $${reserve} would be breached.`, phase };
  }

  // Task 5.2: Governor win-condition category policy check
  if (settings.governorCategoryPolicy && settings.governorCategoryPolicy !== 'off') {
    const winProfile = WIN_METRIC_PROFILES[settings.winCondition] || WIN_METRIC_PROFILES.money;
    const isCategoryAligned = (
      (winProfile.goalKind === 'regions' && (category === 'region_deposit' || category === 'travel')) ||
      ((winProfile.goalKind === 'money' || winProfile.goalKind === 'net_worth') && (category === 'investment' || category === 'equipment')) ||
      (winProfile.goalKind === 'challenges' && (category === 'travel' || category === 'support'))
    );

    if (settings.governorCategoryPolicy === 'strict_win_condition' && !isCategoryAligned && phase !== 'compounding') {
      if (!context?.expectedReturn || context.expectedReturn < cost * 2.0) {
        return {
          approved: false,
          reason: `Governor strict category policy restricts ${category} spending unaligned with ${settings.winCondition} win condition.`,
          phase
        };
      }
    } else if (settings.governorCategoryPolicy === 'win_condition_aligned' && !isCategoryAligned && phase === 'survival') {
      if (!context?.expectedReturn || context.expectedReturn < cost * 1.5) {
        return {
          approved: false,
          reason: `Governor aligned category policy restricts unaligned ${category} spending during survival phase.`,
          phase
        };
      }
    } else if (settings.governorCategoryPolicy === 'dynamic_metric' && !isCategoryAligned && phase !== 'compounding' && phase !== 'endgame') {
      if (!context?.expectedReturn || context.expectedReturn < cost * 1.75) {
        const actorObj = actor as ActorState;
        const stateObj = gameStateParam || context?.gameState;
        if (settings.regionalStandingEnabled && actorObj?.currentRegion && stateObj?.standingPerActor && getActorRegionalStanding(stateObj, actorObj.id || 'player', actorObj.currentRegion) >= 50) {
          // High regional standing bypasses strict category policy check
        } else {
          return {
            approved: false,
            reason: `Governor dynamic metric policy requires higher ROI for ${category} spending unaligned with ${settings.winCondition}.`,
            phase
          };
        }
      }
    }
  }

  const strictnessMultiplier = settings.economySpendingApprovalStrictness === 'strict' ? 1.5 : settings.economySpendingApprovalStrictness === 'low' ? 0.6 : 1.0;
  const hasProfitableReturn = Boolean(context?.expectedReturn && context.expectedReturn > cost * (1.15 * strictnessMultiplier));
  switch (phase) {
    case 'survival':
      if (category === 'equipment' || category === 'investment') {
        return { approved: false, reason: 'Survival phase blocks long-payback spending.', phase };
      }
      if (category === 'sabotage') {
        return { approved: false, reason: 'Survival phase blocks ordinary sabotage spending.', phase };
      }
      if (category === 'region_deposit' && WIN_METRIC_PROFILES[settings.winCondition]?.goalKind !== 'regions') {
        return { approved: false, reason: 'Survival phase blocks speculative region deposits.', phase };
      }
      if (category === 'travel' && !hasProfitableReturn) {
        return { approved: false, reason: 'Survival phase requires a clearly profitable travel objective.', phase };
      }
      break;
    case 'accumulation':
      if ((category === 'equipment' || category === 'investment') && !hasProfitableReturn) {
        return { approved: false, reason: 'Accumulation phase requires a clearly profitable return before committing cash.', phase };
      }
      break;
    case 'endgame':
      if ((category === 'equipment' || category === 'investment') && !(context?.expectedReturn && context.expectedReturn > cost * 2)) {
        return { approved: false, reason: 'Endgame phase deprioritizes long-payback spending.', phase };
      }
      break;
    case 'compounding':
    default:
      break;
  }
  return { approved: true, reason: `${phase} phase: approved.`, phase };
};

// Team Treasury Phase T4 (GD1): a small allow-list eligibility check for the Productive Recovery
// Ladder — never a new scoring system, and never an auto-approval. Every real gate (Governor,
// Requirements) still fully re-evaluates probability/expected-return/downside/reserve-breach for
// whichever candidate this returns true for; this only decides which candidates are worth trying.
const processAdvancedLoans = (
  player: any,
  gameSettings: GameSettingsState,
  currentDay: number
): { updatedPlayer: any; notifications: Array<{ message: string; type: string }> } => {
  if (!gameSettings.advancedLoansEnabled) {
    return { updatedPlayer: player, notifications: [] };
  }

  const notifications: Array<{ message: string; type: string }> = [];
  let updatedPlayer = { ...player };
  let advancedLoans = [...(player.advancedLoans || [])];
  let loanHistory = { ...(player.loanHistory || { totalTaken: 0, totalRepaid: 0, defaultCount: 0, earlyRepaymentCount: 0 }) };

  const creditScore = gameSettings.creditScoreEnabled ? calculateCreditScore(player, { day: currentDay }) : 50;
  const creditRange = getCreditScoreRange(creditScore);

  // Process each loan
  const loansToRemove: string[] = [];

  advancedLoans = advancedLoans.map(loan => {
    const updatedLoan = { ...loan };

    // Decrease days remaining
    updatedLoan.daysRemaining -= 1;

    // Accrue interest
    const interestAmount = calculateLoanInterest(
      updatedLoan,
      gameSettings.creditScoreEnabled ? creditRange.multiplier : 1.0,
      gameSettings.interestAccrualRate
    );
    updatedLoan.accrued += interestAmount;

    // Check for default (term expired)
    if (updatedLoan.daysRemaining <= 0) {
      const totalOwed = updatedLoan.amount + updatedLoan.accrued;
      const penalty = totalOwed * (gameSettings.defaultPenaltyMultiplier - 1.0);

      updatedPlayer.money -= (totalOwed + penalty);
      loanHistory.defaultCount += 1;

      notifications.push({
        message: `Loan defaulted! Paid $${Math.floor(totalOwed + penalty)} (includes ${Math.floor(penalty)} penalty)`,
        type: 'error'
      });

      loansToRemove.push(loan.id);

      // Update bankruptcy tracking
      if (updatedPlayer.money < BANKRUPTCY_THRESHOLD) {
        updatedPlayer.daysSinceLastBankruptcy = 0;
      }
    }

    return updatedLoan;
  });

  // Remove defaulted loans
  advancedLoans = advancedLoans.filter(loan => !loansToRemove.includes(loan.id));

  // Update player state
  updatedPlayer.advancedLoans = advancedLoans;
  updatedPlayer.loanHistory = loanHistory;
  updatedPlayer.creditScore = creditScore;

  // Increment days since last bankruptcy
  if (updatedPlayer.money >= BANKRUPTCY_THRESHOLD) {
    updatedPlayer.daysSinceLastBankruptcy = (updatedPlayer.daysSinceLastBankruptcy || 0) + 1;
  }

  return { updatedPlayer, notifications };
};

// Weather effects on gameplay
export function selectTeamMoney(state: CanonicalGameState, teamId: string): number {
  if (!state) return 0;
  const teamMap = state.teamsById || state.teamStateMap;
  const team = teamMap?.[teamId];
  if (!team) return 0;
  const actorMap = state.actorsById || {};
  const actorCash = (team.actorIds || []).reduce((sum: number, aId: string) => {
    const actor = actorMap?.[aId];
    return sum + (actor?.money || 0);
  }, 0);
  const treasuryCash = team.treasury?.balance || 0;
  return actorCash + treasuryCash;
}

export function selectTeamNetWorth(state: CanonicalGameState, teamId: string): number {
  if (!state) return 0;
  const teamMap = state.teamsById || state.teamStateMap;
  const team = teamMap?.[teamId];
  if (!team) return 0;
  const actorMap = state.actorsById || {};
  const resourcePrices = state.gameState?.resourcePrices || state.markets?.resourcePrices || {};
  const actorsNetWorth = (team.actorIds || []).reduce((sum: number, aId: string) => {
    const actor = actorMap?.[aId];
    if (!actor) return sum;
    const invValue = (actor.inventory || []).reduce((invSum: number, item: string) => {
      return invSum + ((resourcePrices as Record<string, number>)[item] || 100);
    }, 0);
    return sum + (actor.money || 0) + invValue;
  }, 0);
  return actorsNetWorth + (team.treasury?.balance || 0);
}

export function selectControlledRegions(state: CanonicalGameState, teamId: string): string[] {
  const regDeposits = state?.gameState?.regionDeposits || state?.regions;
  if (!state || !regDeposits) return [];
  const controlled: string[] = [];
  for (const regionCode in regDeposits) {
    const entry = regDeposits[regionCode] || {};
    const teamDeposit = entry[teamId] ?? (teamId === 'team_player' ? entry.player : (teamId === 'team_ai' ? entry.ai : 0)) ?? 0;
    if (teamDeposit > 0) {
      let isLeader = true;
      for (const k in entry) {
        if (k === teamId) continue;
        const otherVal = entry[k] || 0;
        if (typeof otherVal === 'number' && otherVal >= teamDeposit) {
          isLeader = false;
          break;
        }
      }
      if (isLeader) {
        controlled.push(regionCode);
      }
    }
  }
  return controlled;
}

export function selectTreasuryBalance(state: CanonicalGameState, teamId: string): number {
  return state?.teamsById?.[teamId]?.treasury?.balance || 0;
}

// Phase K: Pure Synchronous Transition Engine Types & Reducer


// ============================================================================
// SECTION 9: CORE AI SYSTEMS
// ============================================================================
const createDefaultDecisionState = (): DecisionState => ({
  sequence: 0,
  lastByActor: {},
  historyByActor: {}
});

// GL1: Game Activity Ledger — Foundations. A genuinely separate, optional, disabled-by-default,
// append-only, ID-linked history of match activity, distinct from the AI Operations Auditor's own
// eventLog (which detects operational problems) and from Decision Transparency's own per-actor
// trace history above (which only ever keeps the LATEST/a capped recent history per actor, not a
// full cross-referenced timeline). Modeled after AiOperationsEvent's own discriminated-fields
// shape, but genuinely new structure: one flat event record carrying every ID a later phase might
// need to cross-reference (decision/action/plan/config/approval/treasury-request/setting-change/
// auditor-incident/parent-event/correlation-chain), rather than a closed per-type union — GL1's own
// scope is schema + bounded storage only, so no emission call sites exist yet (GL2's job).
type GameActivityLedgerCategory =
  | 'action'
  | 'decision'
  | 'approval'
  | 'treasury'
  | 'settings_change'
  | 'auditor_incident'
  | 'plan'
  | 'config'
  | 'match_lifecycle'
  | 'system_health'
  | 'anomaly'
  | 'copilot_action'
  | 'copilot_event'
  | 'guardian_event';

type GameActivityLedgerEventCategory = GameActivityLedgerCategory;

export const GAME_ACTIVITY_LEDGER_EVENT_CATEGORIES: GameActivityLedgerEventCategory[] = [
  'action', 'decision', 'approval', 'treasury', 'settings_change', 'auditor_incident', 'plan', 'config', 'match_lifecycle', 'system_health', 'anomaly', 'copilot_action', 'copilot_event', 'guardian_event'
];

type GameActivityLedgerSeverity = 'info' | 'warning' | 'critical' | 'diagnostic';

interface GameActivityLedgerParticipants {
  actorId?: string;
  teamId?: string;
  targetActorId?: string;
  targetTeamId?: string;
  sourceSystemId?: string;
}
interface GameActivityLedgerCausalLinkage {
  causalChainId?: string;
  parentEventId?: string;
  rootEventId?: string;
  causalDepth?: number;
}

export type ExpectationOutcomeCategory =
  | 'met_expectations'
  | 'underperformed'
  | 'catastrophic_failure';

export interface ExpectationAnalysis {
  expectedUtility: number;
  expectedRoi: number;
  expectedCashChange: number;
  evaluationTurnTarget: number;
  evaluated?: boolean;
  evaluationDay?: number;
  actualCashChange?: number;
  utilityDelta?: number;
  outcomeCategory?: ExpectationOutcomeCategory;
  notes?: string;
}

export interface SystemInfluenceBreakdown {
  economyGovernorWeight: number;
  overseerPriority: number;
  sequenceBias: number;
}
type GameActivityLedgerExpectationStatus = ExpectationOutcomeCategory;
type GameActivityLedgerExpectation = ExpectationAnalysis;
type GameActivityLedgerSystemInfluence = SystemInfluenceBreakdown;

export function createGameActivityLedgerEvent(
  category: GameActivityLedgerEventCategory,
  summary: string,
  options?: Partial<GameActivityLedgerEvent> & { counters?: DeterministicCounters; turn?: number; day?: number }
): GameActivityLedgerEvent {
  const counters = options?.counters || globalDeterministicCounters;
  const eventId = options?.id || options?.eventId || nextLedgerEventId(counters, options?.matchId || 'match');
  const timestamp = options?.timestamp !== undefined
    ? options.timestamp
    : ((options?.day !== undefined && options?.turn !== undefined)
        ? options.day * 10000 + options.turn
        : 0);
  const causalChainId = options?.causalLinkage?.causalChainId || options?.causalChainId || options?.correlationChainId;
  const parentEventId = options?.causalLinkage?.parentEventId || options?.parentEventId;
  const rootEventId = options?.causalLinkage?.rootEventId || options?.rootEventId;
  const causalDepth = options?.causalLinkage?.causalDepth ?? options?.causalDepth;

  return {
    id: eventId,
    eventId,
    sequenceId: options?.sequenceId || 0,
    matchId: options?.matchId || 'unknown_match',
    category,
    eventType: options?.eventType || options?.actionType || category,
    severity: options?.severity || 'info',
    participants: options?.participants || {
      actorId: options?.actorId || undefined,
      teamId: options?.teamId || undefined,
    },
    causalLinkage: {
      causalChainId,
      parentEventId,
      rootEventId,
      causalDepth
    },
    causalChainId,
    parentEventId,
    rootEventId,
    causalDepth,
    expectation: options?.expectation ? { ...options.expectation } : undefined,
    systemInfluences: options?.systemInfluences ? { ...options.systemInfluences } : (options?.systemInfluence ? { ...options.systemInfluence } : undefined),
    systemInfluence: options?.systemInfluence ? { ...options.systemInfluence } : (options?.systemInfluences ? { ...options.systemInfluences } : undefined),
    payload: options?.payload || {},
    day: options?.day || 1,
    turn: options?.turn || 0,
    teamId: options?.teamId || null,
    actorId: options?.actorId || null,
    summary,
    bookmarked: typeof options?.bookmarked === 'boolean' ? options.bookmarked : undefined,
    annotation: typeof options?.annotation === 'string' ? options.annotation : undefined,
    tags: Array.isArray(options?.tags) ? options.tags.filter((t): t is string => typeof t === 'string' && t.trim() !== '') : undefined,
    decisionId: options?.decisionId,
    actionType: options?.actionType,
    planId: options?.planId,
    configId: options?.configId,
    configRevision: options?.configRevision,
    approvalRequestId: options?.approvalRequestId,
    treasuryRequestId: options?.treasuryRequestId,
    settingKey: options?.settingKey,
    source: options?.source,
    auditorIncidentId: options?.auditorIncidentId,
    diagnostics: options?.diagnostics,
    timestamp,
    integrityHash: '',
    rngAudit: options?.rngAudit || (typeof globalRngRegistry !== 'undefined' ? globalRngRegistry.getAuditSnapshot() : undefined)
  };
}

export function addActivityLedgerEntry(
  gameState: any,
  entry: Partial<GameActivityLedgerEvent> & { summary: string; category?: GameActivityLedgerEventCategory }
): any {
  if (!gameState || typeof gameState !== 'object') return gameState;
  const updatedState = gameState as ExtendedGameState;
  if (!updatedState.gameActivityLedger) {
    updatedState.gameActivityLedger = createDefaultGameActivityLedgerState();
  }
  if (!Array.isArray(updatedState.gameActivityLedger.events)) {
    updatedState.gameActivityLedger.events = [];
  }

  const turn = updatedState.turn || updatedState.day || updatedState.turnCounter || 1;
  const day = updatedState.day || 1;
  const category = entry.category || 'approval';
  const eventId = entry.id || entry.eventId || `evt_ledger_${Date.now()}_${cosmeticRandom().toString(36).substring(2, 7)}`;

  const ledgerEvent: GameActivityLedgerEvent = createGameActivityLedgerEvent(
    category,
    entry.summary,
    {
      ...entry,
      id: eventId,
      eventId,
      turn,
      day,
      timestamp: entry.timestamp || Date.now(),
      severity: entry.severity || 'info',
      eventType: entry.eventType || 'activity_ledger_entry',
      payload: entry.payload || {}
    }
  );

  updatedState.gameActivityLedger.events.unshift(ledgerEvent);
  if (updatedState.gameActivityLedger.events.length > 500) {
    updatedState.gameActivityLedger.events = updatedState.gameActivityLedger.events.slice(0, 500);
  }
  updatedState.eventLogs = updatedState.gameActivityLedger.events;
  return updatedState;
}

export type ProposalLifecycleStage =
  | 'created'
  | 'updated'
  | 'consolidated'
  | 'dismissed'
  | 'snoozed'
  | 'superseded'
  | 'expired'
  | 'escalated'
  | 'approved'
  | 'rejected';

export function recordProposalLifecycleEvent(
  gameState: ExtendedGameState,
  stage: ProposalLifecycleStage,
  proposal: AutoModeProposal,
  details?: Record<string, unknown>
): ExtendedGameState {
  const turn = gameState.turn || gameState.day || gameState.turnCounter || 1;
  const day = gameState.day || 1;
  const actorIdStr = String(proposal.actorId ?? proposal.targetActorId ?? 0);

  const stageTitles: Record<ProposalLifecycleStage, string> = {
    created: `Auto Mode Proposal Created: ${proposal.title || 'Proposal'}`,
    updated: `Auto Mode Proposal Updated: ${proposal.title || 'Proposal'}`,
    consolidated: `Auto Mode Proposals Consolidated: ${proposal.title || 'Plan'}`,
    dismissed: `Auto Mode Proposal Dismissed: ${proposal.title || 'Proposal'}`,
    snoozed: `Auto Mode Proposal Snoozed: ${proposal.title || 'Proposal'}`,
    superseded: `Auto Mode Proposal Superseded: ${proposal.title || 'Proposal'}`,
    expired: `Auto Mode Proposal Expired: ${proposal.title || 'Proposal'}`,
    escalated: `Auto Mode Proposal Escalated: ${proposal.title || 'Proposal'}`,
    approved: `Auto Mode Proposal Approved: ${proposal.title || 'Proposal'}`,
    rejected: `Auto Mode Proposal Rejected: ${proposal.title || 'Proposal'}`
  };

  const eventType = `automode_proposal_${stage}`;
  const summary = stageTitles[stage] || `Auto Mode Proposal ${stage}: ${proposal.title || proposal.id}`;

  let detailCtx = '';
  if (details) {
    if (details.snoozedTurns !== undefined && details.dismissedUntilTurn !== undefined) {
      detailCtx = ` (snoozed for ${details.snoozedTurns} turns until turn ${details.dismissedUntilTurn})`;
    } else if (details.dismissedUntilTurn !== undefined) {
      detailCtx = ` (dismissed until turn ${details.dismissedUntilTurn})`;
    } else if (details.reason) {
      detailCtx = ` (${details.reason})`;
    } else if (details.supersededBy) {
      detailCtx = ` (superseded by ${details.supersededBy})`;
    } else if (details.consolidatedCount) {
      detailCtx = ` (consolidated ${details.consolidatedCount} packages)`;
    }
  }

  if (gameState.autoModeRuntime) {
    if (!gameState.autoModeRuntime.ledgerLog) gameState.autoModeRuntime.ledgerLog = [];
    gameState.autoModeRuntime.ledgerLog.unshift(`[${eventType.toUpperCase()}] ${summary}${detailCtx} (Actor ${actorIdStr}, Turn ${turn})`);
    if (gameState.autoModeRuntime.ledgerLog.length > 500) {
      gameState.autoModeRuntime.ledgerLog = gameState.autoModeRuntime.ledgerLog.slice(0, 500);
    }
  }

  return addActivityLedgerEntry(gameState, {
    category: 'approval',
    eventType,
    severity: (proposal.severity === 'critical' ? 'critical' : proposal.severity === 'important' ? 'warning' : 'info') as GameActivityLedgerSeverity,
    summary,
    actorId: actorIdStr,
    teamId: proposal.targetTeam || proposal.targetTeamId,
    timestamp: Date.now(),
    payload: {
      proposalId: proposal.id,
      stage,
      actorId: actorIdStr,
      category: proposal.category,
      family: proposal.family || (typeof deriveProposalFamily === 'function' ? deriveProposalFamily(proposal) : proposal.category),
      fingerprint: proposal.fingerprint,
      severity: proposal.severity,
      packageId: proposal.packageId || proposal.proposedPackage?.packageId || proposal.actionPackage?.packageId,
      turn,
      day,
      ...(details || {})
    }
  });
}

const globalGameActivityLedgerEvents: GameActivityLedgerEvent[] = [];

export function getGameActivityLedgerEvents(): GameActivityLedgerEvent[] {
  return [...globalGameActivityLedgerEvents];
}

export function recordGameActivityLedgerEvent(
  arg1: any,
  arg2?: any,
  arg3?: any,
  arg4?: any,
  arg5?: any,
  arg6?: any
): any {
  if (typeof arg1 === 'string') {
    const kind = arg1;
    const category = arg2 || 'anomaly';
    const severity = arg3 || 'info';
    const summary = arg4 || '';
    const details = arg5 || {};
    const meta = arg6 || {};
    const eventId = meta.id || meta.eventId || nextLedgerEventId(globalDeterministicCounters, 'evt');
    const eventObj: any = {
      id: eventId,
      eventId,
      kind,
      category,
      severity,
      summary,
      payload: details,
      details,
      timestamp: typeof meta.timestamp === 'number' ? meta.timestamp : (1704067200000 + (meta.turn || 1) * 1000),
      day: meta.day || 1,
      turn: meta.turn || 0,
      actorId: meta.actorId || 'auditor',
      correlationId: meta.correlationId,
      correlationChainId: meta.correlationId,
      participants: { actorId: meta.actorId || 'auditor' },
      causalLinkage: { causalChainId: meta.correlationId }
    };
    globalGameActivityLedgerEvents.push(eventObj);
    return eventObj;
  }

  const state = arg1;
  const event = arg2;
  const maxEvents = arg3 || 1000;
  if (event) {
    globalGameActivityLedgerEvents.push(event);
  }
  return playerReducer(state, {
    type: 'RECORD_GAME_ACTIVITY_LEDGER_EVENT',
    payload: {
      event,
      maxEvents,
      retentionPolicy: 'trim_oldest'
    }
  });
}

// GL9: the enumerated set of "why did this setting change" sources, exactly as specified — used
// by updateGameSetting (below) so every settings_change ledger event can distinguish a direct
