export type GameStateSnapshot = typeof initialGameState;
export type GameState = GameStateSnapshot;

// MILESTONE 2: COMPETITIVE POSITION SCORING ENGINE

// (Duplicate CompetitivePositionComponents & CompetitivePositionScore unified in Auto Mode types)

type NetWorthHistoryEntry = number | { day?: number; playerWorth?: number; aiWorth?: number; worth?: number; [key: string]: unknown };

const getWorthFromHistory = (entry: unknown, id: string, fallbackWorth: number): number => {
  if (!entry) return fallbackWorth;
  if (typeof entry === 'number') return entry;
  if (typeof entry === 'object' && entry !== null) {
    const obj = entry as Record<string, unknown>;
    if (id === 'player' && typeof obj.playerWorth === 'number') return obj.playerWorth;
    if (id === 'ai' && typeof obj.aiWorth === 'number') return obj.aiWorth;
    const dynamicKey = id + 'Worth';
    if (typeof obj[dynamicKey] === 'number') return obj[dynamicKey] as number;
    if (typeof obj.worth === 'number') return obj.worth;
    if (typeof obj.playerWorth === 'number') return obj.playerWorth;
  }
  return fallbackWorth;
};

export type ExtendedActorState = ActorState & {
  [key: string]: any;
  autoModePolicy?: ActorAutoModePolicy;
  activeTreasuryFundingRequestId?: string | null;
  netWorth?: number;
  actionsLent?: number;
  actionsReceived?: number;
  overridesUsedToday?: number;
  actionsUsedThisTurn?: number;
  xp?: number;
  netWorthHistory?: NetWorthHistoryEntry[];
  loans?: Array<{ amount?: number; accrued?: number }>;
  advancedLoans?: Array<{ amount?: number; accruedInterest?: number; actualInterestRate?: number }>;
  loanHistory?: { defaultCount?: number };
  inEconomicRecovery?: boolean;
  contributionStats?: {
    craftedValue?: number;
    supportGiven?: number;
    cashTransferred?: number;
    resourcesTransferred?: number;
    actionsLent?: number;
    comboBonusValue?: number;
    resolvedSupportRequests?: number;
  };
  actionBudgetDelta?: number;
  maxActionsPerTurn?: number;
  costReductionPct?: number;
  incomeSubsidyPct?: number;
  taxReliefPct?: number;
  priceInflationPct?: number;
  handicapPenaltyPct?: number;
  rewardBoostPct?: number;
  diceFavorabilityBonus?: number;
  cooldownReductionTurns?: number;
  objectiveWeights?: Record<string, number>;
  aiStrategyPreset?: string;
  aiFactorWeights?: Record<string, number>;
  yieldMultipliers?: Record<string, number>;
  luckMitigationMinFloor?: number;
};

type ExtendedGameSettings = GameSettingsState & {
  advancedLoansEnabled?: boolean;
  loansEnabled?: boolean;
  equipmentShopEnabled?: boolean;
  equipmentEnabled?: boolean;
  regionalContractsEnabled?: boolean;
  contractsEnabled?: boolean;
  expeditionsRelicsEnabled?: boolean;
  expeditionsEnabled?: boolean;
  stateInfrastructureEnabled?: boolean;
  infrastructureEnabled?: boolean;
  objectivesEnabled?: boolean;
  investmentsEnabled?: boolean;
  actionLimitsEnabled?: boolean;
  playerActionsPerDay?: number;
  aiActionsPerDay?: number;
};

type ExtendedObjective = ScenarioObjective & {
  currentValue?: number;
};

export type ExtendedGameState = GameState & Partial<CanonicalGameState> & {
  [key: string]: any;
  lastComputedBranchDelta?: any;
  careerProfile?: any;
  gameState?: any;
  actorsById?: Record<string, FlexibleActorState>;
  player?: FlexibleActorState;
  aiPlayer?: FlexibleActorState;
  turn?: number;
  day?: number;
  yieldMultipliers?: Record<string, number>;
  luckMitigationMinFloor?: number;
  autoModeRuntime?: AutoModeRuntimeState;
  markets?: { resourcePrices?: Record<string, number> };
  bankruptcyTracker?: Record<string, number>;
  takeoverSession?: CoPilotTakeoverSession | null;
  activeScenarioConfig?: {
    forcedSettings?: Partial<ExtendedGameSettings>;
    customSettings?: Partial<ExtendedGameSettings>;
    objectives?: ExtendedObjective[];
  };
  scenarioObjectives?: ExtendedObjective[];
  regionalDevLevels?: Record<string, RegionalDevelopmentLevel>;
  activeDynamicEvent?: unknown;
};

export function evaluateCompetitivePositionScore(
  gameState: GameState,
  settings: GameSettingsState,
  actorId: string,
  _isBenchmarkCalc = false
): CompetitivePositionScore {
  const gs = gameState as ExtendedGameState;
  const actorMap = gs?.actorsById || {};
  const actorRaw = actorMap[actorId] || (actorId === 'player' ? gs?.player : (actorId === 'ai' ? gs?.aiPlayer : null)) || gs?.player || null;
  const actor = actorRaw as ActorState | null;

  const activeScenario = gs?.activeScenarioConfig || null;
  const forced = activeScenario?.forcedSettings || {};
  const custom = activeScenario?.customSettings || {};
  const s: ExtendedGameSettings = { ...settings, ...forced, ...custom };

  const isTeamMode = gs?.mode === 'team_human_ai_vs_ai_ai' || gs?.mode === 'team_ai_vs_ai' || actor?.teamId !== undefined;

  const isLoansExcluded = (s as Record<string, unknown>).loanSystemEnabled === false || (s as Record<string, unknown>).advancedLoansEnabled === false || s.loansEnabled === false;
  const isEquipmentExcluded = s.equipmentEnabled === false || s.equipmentShopEnabled === false;
  const isContractsExcluded = s.contractsEnabled === false || s.regionalContractsEnabled === false;
  const isExpeditionsExcluded = (s as Record<string, unknown>).expeditionSystemEnabled === false || (s as Record<string, unknown>).expeditionsRelicsEnabled === false || s.expeditionsEnabled === false || (s as Record<string, unknown>).expeditionModeEnabled === false;
  const isInfrastructureExcluded = s.infrastructureEnabled === false || s.stateInfrastructureEnabled === false || s.investmentsEnabled === false;
  const isObjectivesExcluded = s.objectivesEnabled === false;

  const excludedFeatures: string[] = [];
  if (isContractsExcluded) excludedFeatures.push('contracts');
  if (isExpeditionsExcluded) excludedFeatures.push('expeditionProgress');
  if (isInfrastructureExcluded) excludedFeatures.push('infrastructure');
  if (isLoansExcluded) excludedFeatures.push('debtPressure');
  if (isEquipmentExcluded) excludedFeatures.push('equipmentReadiness');
  if (!isTeamMode) excludedFeatures.push('teamContribution');
  if (isObjectivesExcluded) excludedFeatures.push('objectives');

  const baseWeights: Record<keyof CompetitivePositionComponents, number> = {
    economy: 0.10,
    progression: 0.10,
    objectives: 0.08,
    regionalControl: 0.10,
    infrastructure: 0.08,
    contracts: 0.08,
    expeditionProgress: 0.07,
    equipmentReadiness: 0.07,
    resourceReadiness: 0.05,
    actionEfficiency: 0.07,
    teamContribution: 0.08,
    momentum: 0.07,
    debtPressure: 0.05,
    riskExposure: 0.05,
    estimatedWinProbability: 0.05,
    recentMomentum: 0,
    expeditions: 0,
    equipment: 0,
    debt: 0,
    risk: 0,
    economicPower: 0,
    territoryControl: 0,
    militaryDominance: 0,
    techDevelopment: 0,
  };

  const isExcluded: Record<keyof CompetitivePositionComponents, boolean> = {
    economy: false,
    progression: false,
    objectives: isObjectivesExcluded,
    regionalControl: false,
    infrastructure: isInfrastructureExcluded,
    contracts: isContractsExcluded,
    expeditionProgress: isExpeditionsExcluded,
    equipmentReadiness: isEquipmentExcluded,
    resourceReadiness: false,
    actionEfficiency: false,
    teamContribution: !isTeamMode,
    momentum: false,
    debtPressure: isLoansExcluded,
    riskExposure: false,
    estimatedWinProbability: false,
    recentMomentum: false,
    expeditions: isExpeditionsExcluded,
    equipment: isEquipmentExcluded,
    debt: isLoansExcluded,
    risk: false,
    economicPower: true,
    territoryControl: true,
    militaryDominance: true,
    techDevelopment: true,
  };

  let activeWeightSum = 0;
  (Object.keys(baseWeights) as Array<keyof CompetitivePositionComponents>).forEach(key => {
    if (!isExcluded[key]) {
      activeWeightSum += baseWeights[key];
    }
  });

  const activeWeights = {} as Record<keyof CompetitivePositionComponents, number>;
  (Object.keys(baseWeights) as Array<keyof CompetitivePositionComponents>).forEach(key => {
    if (isExcluded[key]) {
      activeWeights[key] = 0;
    } else {
      activeWeights[key] = activeWeightSum > 0 ? baseWeights[key] / activeWeightSum : 1 / 15;
    }
  });

  // 1. Economy
  const sCash = Math.min(100, Math.max(0, ((actor?.money || 0) / 10000) * 100));
  const prices: Record<string, number> = gs?.resourcePrices || (gs as { markets?: { resourcePrices?: Record<string, number> } })?.markets?.resourcePrices || {};
  const netWorth = calculateNetWorth(actor, prices);
  const sAssets = Math.min(100, Math.max(0, (netWorth / 25000) * 100));
  let dailyIncome = 0;
  if (Array.isArray(actor?.investments)) {
    actor.investments.forEach((invKey: string) => {
      const invData = REGIONAL_INVESTMENTS[invKey];
      if (invData?.dailyIncome) dailyIncome += invData.dailyIncome;
    });
  }
  const sRev = Math.min(100, Math.max(0, (dailyIncome / 1000) * 100));
  const holdingsVal = ((actor?.investments?.length || 0) * 2000) + (actor?.contributionStats?.craftedValue || 0);
  const sHoldings = Math.min(100, Math.max(0, (holdingsVal / 10000) * 100));
  const economyScore = Math.min(100, Math.max(0, 0.30 * sCash + 0.35 * sAssets + 0.20 * sRev + 0.15 * sHoldings));

  // 2. Progression
  const actorLevel = actor?.level || 1;
  const sLevel = Math.min(100, Math.max(0, ((actorLevel - 1) / 6) * 100));
  const sVp = Math.min(100, Math.max(0, (netWorth / 50000) * 100));
  const masteryCount = Array.isArray(actor?.masteryUnlocks) ? actor.masteryUnlocks.length : 0;
  const sTech = Math.min(100, Math.max(0, (masteryCount / 3) * 100));
  const challengeScoreVal = typeof computeActorChallengeScore === 'function' ? computeActorChallengeScore(actor) : 0;
  const sChallengeProg = Math.min(100, Math.max(0, (challengeScoreVal / 50) * 100));
  const progressionScore = Math.min(100, Math.max(0, 0.25 * sLevel + 0.35 * sVp + 0.25 * sTech + 0.15 * sChallengeProg));

  // 3. Objectives
  let primaryCount = 0;
  let primaryProgressSum = 0;
  let optionalCount = 0;
  let optionalProgressSum = 0;
  const objectivesList: ExtendedObjective[] = gs?.activeScenarioConfig?.objectives || gs?.scenarioObjectives || [];
  if (Array.isArray(objectivesList) && objectivesList.length > 0) {
    objectivesList.filter(Boolean).forEach((obj: ExtendedObjective) => {
      const target = obj.targetValue || 1;
      const current = obj.currentValue || 0;
      const ratio = Math.min(1, Math.max(0, current / target));
      if (obj.isPrimary !== false) {
        primaryCount++;
        primaryProgressSum += ratio;
      } else {
        optionalCount++;
        optionalProgressSum += ratio;
      }
    });
  }
  const sPrimary = primaryCount > 0 ? (primaryProgressSum / primaryCount) * 100 : 100;
  const sSecondary = optionalCount > 0 ? (optionalProgressSum / optionalCount) * 100 : 100;
  let completedContractsCount = 0;
  const rawContracts: RegionalContract[] = Object.values(gs?.regionalContracts || {});
  rawContracts.filter(Boolean).forEach((c: RegionalContract) => {
    if (c.assignedActorId === actorId && c.status === 'completed') completedContractsCount++;
  });
  const sContractsCount = Math.min(100, Math.max(0, (completedContractsCount / 5) * 100));
  const sMissionProg = Math.min(100, Math.max(0, sPrimary * 0.5 + sSecondary * 0.5));
  const objectivesScore = Math.min(100, Math.max(0, 0.45 * sPrimary + 0.25 * sSecondary + 0.15 * sContractsCount + 0.15 * sMissionProg));

  // 4. Regional Control
  const regionDepositsSanitized = sanitizeRegionDeposits(gs?.regionDeposits || (gs as { regions?: unknown })?.regions || {});
  const regControlStats = computeRegionControlStats(regionDepositsSanitized, gs?.regionControlStats?.controlHistory || []);
  const controlledRegionsCount = regControlStats?.totalControlled?.[actorId] || 0;
  const sTerritory = Math.min(100, Math.max(0, (controlledRegionsCount / 8) * 100));
  const totalDeposits = regControlStats?.totalInvested?.[actorId] || 0;
  const sDeposits = Math.min(100, Math.max(0, (totalDeposits / 15000) * 100));
  const coreRegions = ['QLD', 'NSW', 'VIC', 'TAS', 'SA', 'WA', 'NT', 'ACT'];
  let standingSum = 0;
  coreRegions.forEach(r => {
    standingSum += getActorRegionalStanding(gameState, actorId, r);
  });
  const avgStanding = standingSum / coreRegions.length;
  const sStanding = Math.max(0, Math.min(100, (avgStanding + 100) / 2));
  const supportGivenCount = actor?.contributionStats?.supportGiven || 0;
  const sStrategic = Math.min(100, Math.max(0, ((controlledRegionsCount * 400 + supportGivenCount * 75) / 3600) * 100));
  const regionalControlScore = Math.min(100, Math.max(0, 0.40 * sTerritory + 0.25 * sDeposits + 0.20 * sStanding + 0.15 * sStrategic));

  // 5. Infrastructure
  const infraProjects: InfrastructureProject[] = Object.values(gs?.infrastructureProjects || {});
  let activeProjectsCount = 0;
  let activeGridCount = 0;
  infraProjects.filter(Boolean).forEach((proj: InfrastructureProject) => {
    const isAssigned = Array.isArray(proj.assignedWorkers) && proj.assignedWorkers.includes(actorId);
    const isActive = proj.status === 'active' || proj.status === 'upgraded';
    if (isAssigned && isActive) {
      activeProjectsCount++;
      if (['offshore_wind_farm', 'green_hydrogen_terminal', 'hydro_expansion', 'subsea_cable_hub'].includes(proj.projectType)) {
        activeGridCount++;
      }
    }
  });
  const sProj = Math.min(100, Math.max(0, (activeProjectsCount / 8) * 100));
  const sGrid = Math.min(100, Math.max(0, (activeGridCount / 4) * 100));
  let devTierSum = 0;
  const regionalDevs: RegionalDevelopmentLevel[] = Object.values(gs?.regionalDevLevels || {});
  regionalDevs.filter(Boolean).forEach((dev: RegionalDevelopmentLevel) => {
    devTierSum += dev.tier || 0;
  });
  const sDev = Math.min(100, Math.max(0, (devTierSum / 40) * 100));
  const infrastructureScore = Math.min(100, Math.max(0, 0.45 * sProj + 0.30 * sGrid + 0.25 * sDev));

  // 6. Contracts
  let nComp = 0;
  let nActive = 0;
  let nFailed = 0;
  let nCancelled = 0;
  rawContracts.filter(Boolean).forEach((c: RegionalContract) => {
    if (c.assignedActorId === actorId) {
      if (c.status === 'completed') nComp++;
      else if (c.status === 'active') nActive++;
      else if (c.status === 'failed') nFailed++;
      else if (c.status === 'cancelled') nCancelled++;
    }
  });
  const sComp = Math.min(100, Math.max(0, (nComp / 5) * 100));
  const nAccepted = nComp + nActive + nFailed + nCancelled;
  const sFulfill = nAccepted === 0 ? 50 : (nComp / nAccepted) * 100;
  const sPen = Math.max(0, 100 - (nFailed + nCancelled) * 20);
  const contractsScore = Math.min(100, Math.max(0, 0.40 * sComp + 0.35 * sFulfill + 0.25 * sPen));

  // 7. Expeditions
  const expRun = gs?.expeditionRun || null;
  const completedExpRuns = Array.isArray(expRun?.history) ? expRun.history.length : 0;
  const sRuns = Math.min(100, Math.max(0, (completedExpRuns / 4) * 100));
  let sActiveRun = 40;
  if (expRun?.active) {
    const legVal = expRun.currentLeg === 3 ? 100 : expRun.currentLeg === 2 ? 66.6 : 33.3;
    const supplyRatio = (expRun.supplies || 100) / 100;
    const condMult = expRun.condition === 'healthy' ? 1.0 : expRun.condition === 'strained' ? 0.75 : 0.40;
    sActiveRun = legVal * supplyRatio * condMult;
  }
  const relicsInven: RelicRewardItem[] = gs?.relicInventoryByActor?.[actorId] || [];
  const relicsEquipMap = gs?.equippedRelicsByActor?.[actorId] || {};
  const equippedRelicIds = new Set(
    Object.values(relicsEquipMap)
      .filter((r): r is RelicRewardItem => Boolean(r))
      .map(r => r.id)
  );
  const rarityPointsMap: Record<string, number> = { common: 10, uncommon: 20, rare: 35, epic: 55, legendary: 80 };
  let totalRelicPts = 0;
  relicsInven.filter(Boolean).forEach((relic: RelicRewardItem) => {
    const pts = rarityPointsMap[relic.rarity || 'common'] || 10;
    const isEquipped = equippedRelicIds.has(relic.id);
    totalRelicPts += pts * (isEquipped ? 1.2 : 1.0);
  });
  const sRelics = Math.min(100, Math.max(0, (totalRelicPts / 200) * 100));
  const expeditionsScore = Math.min(100, Math.max(0, 0.35 * sRuns + 0.25 * sActiveRun + 0.40 * sRelics));

  // 8. Equipment / Resource Readiness
  let invenValue = 0;
  if (Array.isArray(actor?.inventory)) {
    actor.inventory.forEach((itemKey: string) => {
      invenValue += prices[itemKey] || 150;
    });
  }
  const sMat = Math.min(100, Math.max(0, (invenValue / 25000) * 100));
  let equipPts = 0;
  const equipTierMap: Record<string, number> = {
    'Hiking Boots': 10, 'Smart Watch': 10, 'Surfboard': 10, 'Outback Map': 10, 'Field Journal': 10, 'High-Lumen Torch': 10, 'Pioneer Compass': 10,
    'Diving Gear': 20, 'Spelunking Kit': 20, 'Geological Sampler': 20, 'Thermal Survival Gear': 20, 'Sonar Scanner': 20, 'Heat Shielding Suit': 20, 'Navigation Chart': 20,
    'Solar Array Kit': 35, 'Ice Core Drilling Rig': 35, 'Heavy Transport Rig': 35, 'Light Patrol Boat': 35, 'Pressure Hull Reinforcement': 35,
    'Cargo Vessel License': 55, 'Deepsea Submersible': 55
  };
  if (Array.isArray(actor?.equipment)) {
    actor.equipment.forEach((eq: string) => {
      equipPts += equipTierMap[eq] || 15;
    });
  }
  const sEquip = Math.min(100, Math.max(0, (equipPts / 120) * 100));
  const actorCondMult = actor?.condition === 'critical' ? 0.4 : actor?.condition === 'strained' ? 0.75 : 1.0;
  const currentSupplies = typeof actor?.currentSupplies === 'number' ? actor.currentSupplies : 100;
  const maxSupplies = typeof actor?.maxSupplies === 'number' ? actor.maxSupplies : 100;
  const sSupplies = Math.min(100, (currentSupplies / (maxSupplies || 100)) * 100 * actorCondMult);
  const equipmentScore = Math.min(100, Math.max(0, 0.35 * sMat + 0.40 * sEquip + 0.25 * sSupplies));

  // 9. Action Efficiency
  const isHuman = actor?.kind === 'human' || actorId === 'player';
  const baseApBudget = (s.actionLimitsEnabled !== false ? (isHuman ? (s.playerActionsPerDay || 3) : (s.aiActionsPerDay || 3)) : 3)
    + (actor?.actionsLent || 0) + (actor?.actionsReceived || 0) + (actor?.overridesUsedToday || 0);
  const apUsed = actor?.actionsUsedThisTurn || 0;
  const sUtil = Math.min(1.0, apUsed / Math.max(1, baseApBudget)) * 100;
  const unusedApRatio = Math.max(0, (baseApBudget - apUsed) / baseApBudget);
  const sWaste = Math.max(0, 100 - unusedApRatio * 70);
  const valPerAp = (netWorth + (actor?.xp || 0) * 10) / Math.max(1, apUsed || 1);
  const sVal = Math.min(100, Math.max(0, (valPerAp / 500) * 100));
  const actionEfficiencyScore = Math.min(100, Math.max(0, 0.40 * sUtil + 0.35 * sWaste + 0.25 * sVal));

  // 10. Team Contribution
  let sTreasury = 0;
  let sSupport = 0;
  let sSynergy = 0;
  const teamId = actor?.teamId;
  const team: TeamState | null = teamId ? (gs?.teamsById?.[teamId] || gs?.teamStateMap?.[teamId] || null) : null;
  if (team) {
    const actorContrib = team.treasury?.contributionTotalsByActor?.[actorId] || 0;
    const teamTotalContrib = team.treasury?.totalContributed || 1;
    const expectedShare = teamTotalContrib / Math.max(1, team.actorIds?.length || 2);
    sTreasury = Math.min(100, (actorContrib / Math.max(1, expectedShare)) * 50);

    const stats = actor?.contributionStats;
    const supportVal = (stats?.supportGiven || 0) * 150 + (stats?.cashTransferred || 0) * 0.5 + (stats?.resourcesTransferred || 0) * 100 + (stats?.actionsLent || 0) * 200;
    sSupport = Math.min(100, (supportVal / 2000) * 100);

    const synergyVal = (stats?.comboBonusValue || 0) + ((stats as unknown as Record<string, unknown>)?.resolvedSupportRequests as number || 0) * 75;
    sSynergy = Math.min(100, (synergyVal / 1000) * 100);
  }
  const teamContributionScore = Math.min(100, Math.max(0, 0.35 * sTreasury + 0.35 * sSupport + 0.30 * sSynergy));

  // 11. Momentum
  const rawNwHist = gs?.netWorthHistory || actor?.netWorthHistory || [];
  const nwHist = Array.isArray(rawNwHist) ? rawNwHist.filter(Boolean) : [];
  let sGrowth = 50;
  let sSlope = 50;
  let sAccel = 50;
  if (nwHist.length >= 2) {
    const latest = getWorthFromHistory(nwHist[nwHist.length - 1], actorId, netWorth);
    const prev = getWorthFromHistory(nwHist[nwHist.length - 2], actorId, netWorth);
    const g1 = (latest - prev) / Math.max(100, prev);
    sGrowth = Math.min(100, Math.max(0, 50 + g1 * 250));

    if (nwHist.length >= 4) {
      const y = nwHist.slice(-4).map((h: unknown) => getWorthFromHistory(h, actorId, netWorth));
      const sumX = 6;
      const sumY = y.reduce((a: number, b: number) => a + b, 0);
      const sumXY = y[0] * 0 + y[1] * 1 + y[2] * 2 + y[3] * 3;
      const slope = (4 * sumXY - sumX * sumY) / 20;
      sSlope = Math.min(100, Math.max(0, 50 + (slope / Math.max(50, latest * 0.05)) * 50));
    }

    if (nwHist.length >= 3) {
      const prevPrev = getWorthFromHistory(nwHist[nwHist.length - 3], actorId, netWorth);
      const gPrev = (prev - prevPrev) / Math.max(100, prevPrev);
      const deltaG = g1 - gPrev;
      sAccel = Math.min(100, Math.max(0, 50 + deltaG * 200));
    }
  }
  const momentumScore = Math.min(100, Math.max(0, 0.40 * sGrowth + 0.45 * sSlope + 0.15 * sAccel));

  // 12. Debt
  interface SimpleLoanLike { amount?: number; accrued?: number; }
  interface AdvLoanLike { amount?: number; accruedInterest?: number; actualInterestRate?: number; }
  const actorLoans = Array.isArray(actor?.loans) ? actor.loans.filter(Boolean) : [];
  const actorAdvLoans = Array.isArray(actor?.advancedLoans) ? actor.advancedLoans.filter(Boolean) : [];
  const simpleDebt = actorLoans.reduce((sum: number, l: SimpleLoanLike) => sum + (l.amount || 0) + (l.accrued || 0), 0);
  const advDebt = actorAdvLoans.reduce((sum: number, l: AdvLoanLike) => sum + (l.amount || 0) + (l.accruedInterest || 0), 0);
  const totalDebtRaw = simpleDebt + advDebt;
  const totalDebt = Number.isFinite(totalDebtRaw) ? Math.max(0, totalDebtRaw) : 0;
  const grossAssetsRaw = (actor?.money || 0) + invenValue + ((actor?.investments?.length || 0) * 2000) + equipPts * 100;
  const grossAssets = Number.isFinite(grossAssetsRaw) ? Math.max(0, grossAssetsRaw) : 0;
  const daRatioRaw = (totalDebt > 0 && grossAssets > 0) ? totalDebt / grossAssets : (totalDebt > 0 ? 1 : 0);
  const daRatio = Number.isFinite(daRatioRaw) ? daRatioRaw : 0;
  const iTurn = actorAdvLoans.reduce((sum: number, l: AdvLoanLike) => sum + (l.amount || 0) * (l.actualInterestRate || 0.05), 0);
  const iBurdenRaw = (iTurn > 0 && grossAssets > 0) ? iTurn / (grossAssets * 0.10) : 0;
  const iBurden = Number.isFinite(iBurdenRaw) ? iBurdenRaw : 0;
  const defaultsCount = actor?.loanHistory?.defaultCount || 0;
  const debtScoreRaw = totalDebt === 0 ? 100 : Math.max(0, Math.min(100, 100 - daRatio * 70 - iBurden * 20 - defaultsCount * 15));
  const debtScore = Number.isFinite(debtScoreRaw) ? debtScoreRaw : 100;

  // 13. Risk & Vulnerability
  interface CrisisChainLike { status?: string; active?: boolean; }
  const rawActiveCrises = gs?.crisisChainState?.activeCrisisChains || [];
  let activeCrisesCount = 0;
  if (Array.isArray(rawActiveCrises)) {
    activeCrisesCount = rawActiveCrises.filter(Boolean).filter((c: CrisisChainLike) => c.status === 'active' || c.status === 'escalated' || c.active === true).length;
  }
  const rCrisis = Math.min(1.0, activeCrisesCount * 0.4);
  const vCondition = actor?.condition === 'critical' ? 1.0 : actor?.condition === 'strained' ? 0.4 : 0.0;
  const vSupply = 1.0 - currentSupplies / (maxSupplies || 100);
  const vCash = actor?.inEconomicRecovery ? 0.8 : ((actor?.money || 0) < 500 ? 0.4 : 0.0);
  const rVuln = Math.min(1.0, 0.4 * vCondition + 0.3 * vSupply + 0.3 * vCash);
  let rThreat = 0.2;
  if (gs?.activeDynamicEvent || activeCrisesCount > 0) rThreat += 0.3;
  const totalRiskIdx = 0.35 * rCrisis + 0.40 * rVuln + 0.25 * rThreat;
  const riskScore = Math.max(0, Math.min(100, 100 - totalRiskIdx * 100));

  // Preliminary 14 component scores
  const prelimComponents: Record<keyof CompetitivePositionComponents, number> = {
    economy: Math.round(economyScore * 100) / 100,
    progression: Math.round(progressionScore * 100) / 100,
    objectives: Math.round(objectivesScore * 100) / 100,
    regionalControl: Math.round(regionalControlScore * 100) / 100,
    infrastructure: Math.round(infrastructureScore * 100) / 100,
    contracts: Math.round(contractsScore * 100) / 100,
    expeditionProgress: Math.round(expeditionsScore * 100) / 100,
    equipmentReadiness: Math.round(equipmentScore * 100) / 100,
    resourceReadiness: Math.round(equipmentScore * 100) / 100,
    actionEfficiency: Math.round(actionEfficiencyScore * 100) / 100,
    teamContribution: Math.round(teamContributionScore * 100) / 100,
    momentum: Math.round(momentumScore * 100) / 100,
    debtPressure: Math.round(debtScore * 100) / 100,
    riskExposure: Math.round(riskScore * 100) / 100,
    estimatedWinProbability: 50,
    recentMomentum: Math.round(momentumScore * 100) / 100,
    expeditions: Math.round(expeditionsScore * 100) / 100,
    equipment: Math.round(equipmentScore * 100) / 100,
    debt: Math.round(debtScore * 100) / 100,
    risk: Math.round(riskScore * 100) / 100,
    economicPower: Math.round(economyScore * 100) / 100,
    territoryControl: Math.round(regionalControlScore * 100) / 100,
    militaryDominance: Math.round(momentumScore * 100) / 100,
    techDevelopment: Math.round(progressionScore * 100) / 100,
  };

  let prelimSum = 0;
  let prelimWeightSum = 0;
  const canonical14Keys: Array<keyof CompetitivePositionComponents> = [
    'economy', 'progression', 'objectives', 'regionalControl', 'infrastructure',
    'contracts', 'expeditionProgress', 'equipmentReadiness', 'resourceReadiness',
    'actionEfficiency', 'teamContribution', 'momentum', 'debtPressure', 'riskExposure'
  ];

  canonical14Keys.forEach(key => {
    if (!isExcluded[key]) {
      prelimSum += activeWeights[key] * prelimComponents[key];
      prelimWeightSum += activeWeights[key];
    }
  });

  const currentTurn = gs?.turn || gs?.day || 1;
  const expectedScoreForGameStage = Math.min(100, Math.max(10, 30 + currentTurn * 2));
  const preliminaryActorScore = prelimWeightSum > 0 ? prelimSum / prelimWeightSum : 50;

  // 14. Real Win Probability Calculation (softmax across actors or logistic against benchmark)
  let realWinProb = 0.5;
  if (_isBenchmarkCalc) {
    const scoreDiff = preliminaryActorScore - expectedScoreForGameStage;
    realWinProb = 1 / (1 + Math.exp(-scoreDiff / 15));
  } else {
    const activeActorIds = Object.keys(actorMap).length > 0
      ? Object.keys(actorMap)
      : (gs?.player || gs?.aiPlayer ? [gs?.player ? 'player' : '', gs?.aiPlayer ? 'ai' : ''].filter(Boolean) : [actorId]);

    if (activeActorIds.length <= 1) {
      const scoreDiff = preliminaryActorScore - expectedScoreForGameStage;
      realWinProb = 1 / (1 + Math.exp(-scoreDiff / 15));
    } else {
      const allActorScores = activeActorIds.map(id => {
        if (id === actorId) return preliminaryActorScore;
        const otherRes = evaluateCompetitivePositionScore(gameState, settings, id, true);
        return otherRes.overallScore ?? 50;
      });

      const expScores = allActorScores.map(score => Math.exp(score / 15));
      const totalExp = expScores.reduce((a, b) => a + b, 0);
      realWinProb = Math.exp(preliminaryActorScore / 15) / (totalExp || 1);
    }
  }

  realWinProb = Math.min(0.99, Math.max(0.01, realWinProb));

  const components: CompetitivePositionComponents = {
    economy: Math.round(economyScore * 100) / 100,
    progression: Math.round(progressionScore * 100) / 100,
    objectives: Math.round(objectivesScore * 100) / 100,
    regionalControl: Math.round(regionalControlScore * 100) / 100,
    infrastructure: Math.round(infrastructureScore * 100) / 100,
    contracts: Math.round(contractsScore * 100) / 100,
    expeditionProgress: Math.round(expeditionsScore * 100) / 100,
    equipmentReadiness: Math.round(equipmentScore * 100) / 100,
    resourceReadiness: Math.round(equipmentScore * 100) / 100,
    actionEfficiency: Math.round(actionEfficiencyScore * 100) / 100,
    teamContribution: Math.round(teamContributionScore * 100) / 100,
    momentum: Math.round(momentumScore * 100) / 100,
    debtPressure: Math.round((100 - debtScore) * 100) / 100,
    riskExposure: Math.round((100 - riskScore) * 100) / 100,
    estimatedWinProbability: Math.round(realWinProb * 100) / 100,
    recentMomentum: Math.round(momentumScore * 100) / 100,
    expeditions: Math.round(expeditionsScore * 100) / 100,
    equipment: Math.round(equipmentScore * 100) / 100,
    debt: Math.round(debtScore * 100) / 100,
    risk: Math.round(riskScore * 100) / 100,
    economicPower: Math.round(economyScore * 100) / 100,
    territoryControl: Math.round(regionalControlScore * 100) / 100,
    militaryDominance: Math.round(momentumScore * 100) / 100,
    techDevelopment: Math.round(progressionScore * 100) / 100,
  };

  const rawOverall = prelimSum + activeWeights.estimatedWinProbability * (realWinProb * 100);
  const overallScore = Math.round(Math.min(100, Math.max(0, rawOverall)) * 100) / 100;

  let benchmark = expectedScoreForGameStage;
  if (!_isBenchmarkCalc) {
    const activeActorIds = Object.keys(actorMap).length > 0
      ? Object.keys(actorMap)
      : (gs?.player || gs?.aiPlayer ? [gs?.player ? 'player' : '', gs?.aiPlayer ? 'ai' : ''].filter(Boolean) : [actorId]);

    if (activeActorIds.length > 0) {
      const sumOfActorOverallScores = activeActorIds.reduce((sum, id) => {
        if (id === actorId) {
          return sum + overallScore;
        }
        const otherScore = evaluateCompetitivePositionScore(gameState, settings, id, true);
        return sum + (otherScore.overallScore ?? 0);
      }, 0);
      const avgOverallScore = sumOfActorOverallScores / activeActorIds.length;
      if (avgOverallScore > 0) {
        benchmark = avgOverallScore;
      }
    }
  }

  const relativeScore = benchmark > 0 ? Math.round((overallScore / benchmark) * 100) / 100 : 1.0;
  const confidence = Math.min(1.0, Math.max(0.75, Math.round((1.0 - (excludedFeatures.length * 0.02)) * 100) / 100));

  return {
    actorId,
    overallScore,
    rawScore: rawOverall,
    normalizedScore: overallScore,
    expectedScoreForGameStage,
    relativeScore,
    confidence,
    sampleTurns: currentTurn,
    components,
    activeWeights,
    excludedFeatures,
    timestamp: (currentTurn * 86400000),
  };
}

export function evaluateTeamCompetitivePositionScore(
  gameState: GameState,
  settings: GameSettingsState,
  teamId: string,
  _isBenchmarkCalc = false
): CompetitivePositionScore {
  const gs = gameState as ExtendedGameState;
  const team: TeamState | null = teamId ? (gs?.teamsById?.[teamId] || gs?.teamStateMap?.[teamId] || null) : null;
  const memberActorIds: string[] = team?.actorIds || (team as { members?: string[] } | null)?.members || [];

  if (!memberActorIds || memberActorIds.length === 0) {
    const dummyComponents: CompetitivePositionComponents = {
      economy: 0, progression: 0, objectives: 0, regionalControl: 0,
      infrastructure: 0, contracts: 0, expeditions: 0, equipment: 0,
      actionEfficiency: 0, teamContribution: 0, momentum: 0, debt: 0, risk: 0,
      debtPressure: 0, equipmentReadiness: 0, estimatedWinProbability: 0, expeditionProgress: 0,
      resourceReadiness: 0, recentMomentum: 0, riskExposure: 0
    };
    const defaultWeights: Record<keyof CompetitivePositionComponents, number> = {
      economy: 0.10, progression: 0.10, objectives: 0.08, regionalControl: 0.10,
      infrastructure: 0.08, contracts: 0.08, expeditions: 0.07, equipment: 0.07,
      actionEfficiency: 0.07, teamContribution: 0.08, momentum: 0.07, debt: 0.05, risk: 0.05,
      debtPressure: 0.05, equipmentReadiness: 0.07, estimatedWinProbability: 0.05, expeditionProgress: 0.07,
      resourceReadiness: 0.05, recentMomentum: 0.07, riskExposure: 0.05,
      economicPower: 0, territoryControl: 0, militaryDominance: 0, techDevelopment: 0
    };
    return {
      actorId: teamId,
      teamId,
      overallScore: 0,
      rawScore: 0,
      normalizedScore: 0,
      expectedScoreForGameStage: 50,
      relativeScore: 1.0,
      confidence: 0.0,
      sampleTurns: 0,
      components: dummyComponents,
      activeWeights: defaultWeights,
      excludedFeatures: [],
      timestamp: 1704067200000
    };
  }

  const memberScores = memberActorIds.map(mId => evaluateCompetitivePositionScore(gameState, settings, mId));

  const teamComponents: CompetitivePositionComponents = { ...memberScores[0].components };

  (Object.keys(teamComponents) as Array<keyof CompetitivePositionComponents>).forEach(key => {
    const avgScore = memberScores.reduce((sum, s) => sum + (s.components[key] ?? 0), 0) / memberScores.length;
    teamComponents[key] = Math.round(avgScore * 100) / 100;
  });

  const treasuryBalance = team?.treasury?.balance || 0;
  const treasuryBonus = Math.min(20, (treasuryBalance / 10000) * 20);
  teamComponents.economy = Math.min(100, Math.round((teamComponents.economy + treasuryBonus) * 100) / 100);

  const totalContributed = team?.treasury?.totalContributed || 0;
  const treasuryContribScore = Math.min(100, (totalContributed / 5000) * 100);
  teamComponents.teamContribution = Math.min(100, Math.max(teamComponents.teamContribution, Math.round((treasuryContribScore * 0.6 + (treasuryBalance / 2000) * 20) * 100) / 100));

  const regionDepositsSanitized = sanitizeRegionDeposits(gs?.regionDeposits || (gs as { regions?: unknown })?.regions || {});
  const regControlStats = computeRegionControlStats(regionDepositsSanitized, gs?.regionControlStats?.controlHistory || []);
  let teamControlledCount = 0;
  memberActorIds.forEach(mId => {
    teamControlledCount += regControlStats?.totalControlled?.[mId] || 0;
  });
  const teamTerritoryScore = Math.min(100, (teamControlledCount / 8) * 100);
  teamComponents.regionalControl = Math.min(100, Math.max(teamComponents.regionalControl, Math.round(teamTerritoryScore * 100) / 100));

  const activeWeights = memberScores[0].activeWeights;
  const excludedFeatures = memberScores[0].excludedFeatures;

  const rawOverall = (Object.keys(teamComponents) as Array<keyof CompetitivePositionComponents>).reduce((sum, key) => {
    return sum + (activeWeights[key] ?? 0) * (teamComponents[key] ?? 0);
  }, 0);

  const overallScore = Math.round(Math.min(100, Math.max(0, rawOverall)) * 100) / 100;

  const currentTurn = gs?.turn || gs?.day || 1;
  const expectedScoreForGameStage = Math.min(100, Math.max(10, 30 + currentTurn * 2));

  let benchmark = expectedScoreForGameStage;
  if (!_isBenchmarkCalc) {
    const teamMap = gs?.teamsById || gs?.teamStateMap || {};
    let activeTeamIds = Object.keys(teamMap);
    if (activeTeamIds.length === 0 && teamId) {
      activeTeamIds = [teamId];
    }

    if (activeTeamIds.length > 0) {
      const sumOfTeamOverallScores = activeTeamIds.reduce((sum, tid) => {
        if (tid === teamId) {
          return sum + overallScore;
        }
        const otherScore = evaluateTeamCompetitivePositionScore(gameState, settings, tid, true);
        return sum + (otherScore.overallScore ?? 0);
      }, 0);
      const avgTeamOverallScore = sumOfTeamOverallScores / activeTeamIds.length;
      if (avgTeamOverallScore > 0) {
        benchmark = avgTeamOverallScore;
      }
    }
  }

  const relativeScore = benchmark > 0 ? Math.round((overallScore / benchmark) * 100) / 100 : 1.0;
  const teamConfidence = memberScores.length > 0
    ? Math.round((memberScores.reduce((sum, s) => sum + s.confidence, 0) / memberScores.length) * 100) / 100
    : 0.9;

  return {
    actorId: teamId,
    teamId,
    overallScore,
    rawScore: rawOverall,
    normalizedScore: overallScore,
    expectedScoreForGameStage,
    relativeScore,
    confidence: teamConfidence,
    sampleTurns: currentTurn,
    components: teamComponents,
    activeWeights,
    excludedFeatures,
    timestamp: (currentTurn * 86400000)
  };
}

/** @deprecated Use evaluateCompetitivePositionScore instead. */
export function legacyEvaluateCompetitivePositionScore(
  gameState: GameState | ExtendedGameState,
  settings: GameSettingsState,
  actorId: string | number
): CompetitivePositionScore {
  return evaluateCompetitivePositionScore(gameState as GameState, settings, String(actorId));
}

// AI COMMAND CENTER ANALYTICAL EVALUATION ENGINES (Milestone 2)


// R4 & M6: AI APPROVAL PROPOSE AGAIN DEADLOCK PREVENTION & SIGNATURE TRACKING & SESSION INVARIANTS
export const APPROVAL_MAX_REVISED_PROPOSALS = 3;

export const globalRejectedProposalSignatures: Record<string, Set<string>> = {};

export function getRejectedProposalSignatures(actorId: string, turnNumber?: number | string): Set<string> {
  const combined = new Set<string>();
  const actorSet = globalRejectedProposalSignatures[actorId];
  if (actorSet) {
    for (const sig of actorSet) combined.add(sig);
  }
  if (turnNumber !== undefined && turnNumber !== null) {
    const key = `${actorId}_${turnNumber}`;
    const turnSet = globalRejectedProposalSignatures[key];
    if (turnSet) {
      for (const sig of turnSet) combined.add(sig);
    }
  } else {
    const prefix = `${actorId}_`;
    for (const [k, v] of Object.entries(globalRejectedProposalSignatures)) {
      if (k.startsWith(prefix) && v) {
        for (const sig of v) combined.add(sig);
      }
    }
  }
  return combined;
}

export function recordRejectedProposalSignature(
  actorId: string,
  turnNumberOrSig: number | string | null,
  actionTypeOrSig?: string | null,
  signature?: string | null
): void {
  let turnNumber: number | string | null = null;
  let sig: string = '';

  if (signature !== undefined && signature !== null) {
    turnNumber = turnNumberOrSig;
    sig = String(signature);
  } else if (actionTypeOrSig !== undefined && actionTypeOrSig !== null && typeof turnNumberOrSig === 'number') {
    turnNumber = turnNumberOrSig;
    sig = String(actionTypeOrSig);
  } else {
    sig = String(turnNumberOrSig || '');
  }

  if (turnNumber !== null && turnNumber !== undefined) {
    const turnKey = `${actorId}_${turnNumber}`;
    if (!globalRejectedProposalSignatures[turnKey]) {
      globalRejectedProposalSignatures[turnKey] = new Set<string>();
    }
    globalRejectedProposalSignatures[turnKey].add(sig);
  } else {
    if (!globalRejectedProposalSignatures[actorId]) {
      globalRejectedProposalSignatures[actorId] = new Set<string>();
    }
    globalRejectedProposalSignatures[actorId].add(sig);
  }
}

export function clearRejectedProposalSignatures(actorId: string, turnNumber?: number | string): void {
  if (turnNumber !== undefined && turnNumber !== null) {
    delete globalRejectedProposalSignatures[`${actorId}_${turnNumber}`];
  }
  delete globalRejectedProposalSignatures[actorId];
  const prefix = `${actorId}_`;
  for (const k of Object.keys(globalRejectedProposalSignatures)) {
    if (k.startsWith(prefix)) {
      delete globalRejectedProposalSignatures[k];
    }
  }
}

/**
 * Task 21: Approval Session Invariant Enforcement
 * Asserts structural consistency for AI approval turn sessions before/after key state transitions.
 * Returns true if valid or successfully auto-healed.
 */
export function assertApprovalSessionInvariants(
  session?: ActiveAiTurnSession | null,
  context?: string
): boolean {
  if (!session) return true;

  // Invariant 1: If session is paused for approval, it MUST have a current proposal and request ID.
  if (session.isPausedForApproval) {
    if (!session.currentProposal || !session.currentApprovalRequestId) {
      session.isPausedForApproval = false;
      session.currentProposal = null;
      session.currentApprovalRequestId = undefined;
      return false;
    }
  }

  // Invariant 2: If session is NOT paused for approval, currentProposal and request ID must be clean.
  if (!session.isPausedForApproval) {
    if (session.currentProposal !== null || session.currentApprovalRequestId !== undefined) {
      session.currentProposal = null;
      session.currentApprovalRequestId = undefined;
    }
  }

  // Invariant 3: If session is finished, it MUST NOT be paused for approval.
  if (session.isFinished) {
    if (session.isPausedForApproval || session.currentProposal !== null || session.currentApprovalRequestId !== undefined) {
      session.isPausedForApproval = false;
      session.currentProposal = null;
      session.currentApprovalRequestId = undefined;
    }
  }

  return true;
}

export function processProposeAgainRejection(
  actorId: string,
  sessionOrTurnNumber: any,
  proposalOrCurrentProp?: any,
  requestIdOrProposal?: any,
  approvalRevisionCountMap: Record<string, number> = {},
  maxRevisions: number = APPROVAL_MAX_REVISED_PROPOSALS,
  candidateList: any[] = []
): {
  isTerminal: boolean;
  revisionCount: number;
  rejectedSignature: string | null;
  nextCandidate: any | null;
} {
  let session: any = null;
  let currentProposal: any = null;
  let requestId: string = 'req_default';
  let revisionMap = approvalRevisionCountMap;
  let maxRev = maxRevisions;
  let candidates = candidateList;
  let turnNumber: number | string | null = null;

  if (typeof sessionOrTurnNumber === 'number' || (typeof sessionOrTurnNumber === 'string' && !isNaN(Number(sessionOrTurnNumber)))) {
    turnNumber = sessionOrTurnNumber;
    currentProposal = proposalOrCurrentProp || requestIdOrProposal;
  } else {
    session = sessionOrTurnNumber;
    currentProposal = proposalOrCurrentProp;
    if (typeof requestIdOrProposal === 'string') {
      requestId = requestIdOrProposal;
    }
  }

  if (session) {
    assertApprovalSessionInvariants(session, 'processProposeAgainRejection:pre');
  }

  let rejectedSignature: string | null = null;
  if (currentProposal) {
    rejectedSignature = typeof getDecisionSignature === 'function' ? getDecisionSignature(currentProposal) : (currentProposal.signature || currentProposal.id || JSON.stringify(currentProposal));
    recordRejectedProposalSignature(actorId, turnNumber, null, rejectedSignature);
  }

  const currentRevisions = (revisionMap[actorId] || 0) + 1;
  revisionMap[actorId] = currentRevisions;

  if (session) {
    session.currentProposal = null;
    session.currentApprovalRequestId = undefined;
    session.isPausedForApproval = false;
  }

  const isTerminal = currentRevisions >= maxRev;
  let nextCandidate: any | null = null;

  if (!isTerminal && candidates.length > 0) {
    const rejectedSigs = getRejectedProposalSignatures(actorId, turnNumber ?? undefined);
    nextCandidate = candidates.find(c => {
      const sig = typeof getDecisionSignature === 'function' ? getDecisionSignature(c) : (c.signature || c.id || JSON.stringify(c));
      return !rejectedSigs.has(sig);
    }) || null;
    if (!nextCandidate) {
      if (session) {
        assertApprovalSessionInvariants(session, 'processProposeAgainRejection:post_no_candidate');
      }
      return {
        isTerminal: true,
        revisionCount: currentRevisions,
        rejectedSignature,
        nextCandidate: null
      };
    }
  }

  if (session && nextCandidate) {
    session.currentProposal = nextCandidate;
    session.currentApprovalRequestId = requestId || `req_rev_${actorId}_${Date.now()}`;
    session.isPausedForApproval = true;
    assertApprovalSessionInvariants(session, 'processProposeAgainRejection:post_replacement');
  } else if (session) {
    assertApprovalSessionInvariants(session, 'processProposeAgainRejection:post_terminal');
  }

  return {
    isTerminal,
    revisionCount: currentRevisions,
    rejectedSignature,
    nextCandidate
  };
}

// M4: AI COMMAND CENTER GAME-PHASE VISIBILITY EVALUATOR & DEV TESTS RUNNER

export function sanitizeGuardianAiSettings(src: unknown): GuardianAiSettings {
  const defaults = createDefaultGuardianAiSettings();
  if (!src || typeof src !== 'object' || src === null) return defaults;
  const obj = src as Record<string, unknown>;

  const protectionLevel = (
    typeof obj.protectionLevel === 'string' &&
    ['off', 'critical_only', 'major_mistakes', 'strategic_caution', 'maximum_protection'].includes(obj.protectionLevel)
  ) ? (obj.protectionLevel as GuardianAiProtectionLevel) : defaults.protectionLevel;

  const responseMode = (
    typeof obj.responseMode === 'string' &&
    ['notify_only', 'warn_before_action', 'require_confirmation', 'adaptive'].includes(obj.responseMode)
  ) ? (obj.responseMode as GuardianAiResponseMode) : defaults.responseMode;

  return {
    enabled: typeof obj.enabled === 'boolean' ? obj.enabled : false,
    protectionLevel,
    responseMode,
    evaluators: typeof obj.evaluators === 'object' && obj.evaluators !== null
      ? { ...defaults.evaluators, ...(obj.evaluators as Partial<GuardianEvaluatorToggles>) }
      : defaults.evaluators,
    thresholds: typeof obj.thresholds === 'object' && obj.thresholds !== null
      ? { ...defaults.thresholds, ...(obj.thresholds as Partial<GuardianRiskThresholds>) }
      : defaults.thresholds,
    ignoredCategories: Array.isArray(obj.ignoredCategories)
      ? obj.ignoredCategories.filter((cat): cat is GuardianRiskCategory => typeof cat === 'string' && GUARDIAN_RISK_CATEGORIES.includes(cat as GuardianRiskCategory))
      : defaults.ignoredCategories,
    sessionOverrides: typeof obj.sessionOverrides === 'object' && obj.sessionOverrides !== null
      ? { ...defaults.sessionOverrides, ...(obj.sessionOverrides as Partial<GuardianSessionOverrideControls>) }
      : defaults.sessionOverrides,
    deduplication: typeof obj.deduplication === 'object' && obj.deduplication !== null
      ? { ...defaults.deduplication, ...(obj.deduplication as Partial<GuardianDeduplicationSettings>) }
      : defaults.deduplication,
    recordReplayEvents: typeof obj.recordReplayEvents === 'boolean' ? obj.recordReplayEvents : defaults.recordReplayEvents,
    logToActivityLedger: typeof obj.logToActivityLedger === 'boolean' ? obj.logToActivityLedger : defaults.logToActivityLedger,
    strictDeterminism: typeof obj.strictDeterminism === 'boolean' ? obj.strictDeterminism : defaults.strictDeterminism,
  };
}

