export function addGuardianSessionOverride(
  state: Record<string, unknown>,
  override: GuardianActiveSessionOverride
): Record<string, unknown> {
  const existing = Array.isArray(state.activeSessionOverrides)
    ? (state.activeSessionOverrides as readonly GuardianActiveSessionOverride[])
    : [];
  const currentTurn = typeof state.turn === 'number' ? state.turn : 1;
  const processedOverride: GuardianActiveSessionOverride = {
    ...override,
    expiresTurn: override.scope === 'turn' && override.expiresTurn === undefined
      ? currentTurn
      : override.expiresTurn,
  };
  return {
    ...state,
    activeSessionOverrides: [...existing, processedOverride],
  };
}

export function clearGuardianSessionOverrides(
  state: Record<string, unknown>,
  currentTurn: number
): Record<string, unknown> {
  const existing = Array.isArray(state.activeSessionOverrides)
    ? (state.activeSessionOverrides as readonly GuardianActiveSessionOverride[])
    : [];
  const active = existing.filter((ov) => {
    if (ov.scope === 'once') return false;
    const expTurn = ov.expiresTurn ?? currentTurn;
    if (ov.scope === 'turn' && currentTurn > expTurn) return false;
    return true;
  });
  return {
    ...state,
    activeSessionOverrides: active,
  };
}

export function isGuardianRiskOverridden(
  category: GuardianRiskCategory,
  actionType: string,
  state: Record<string, unknown> | undefined | null,
  turn: number
): boolean {
  if (!state || !Array.isArray(state.activeSessionOverrides)) return false;
  const overrides = state.activeSessionOverrides as GuardianActiveSessionOverride[];
  const matchIdx = overrides.findIndex((ov) => {
    const catMatch = ov.riskCategory === category || (ov.riskCategory as string) === 'all';
    const actionMatch = ov.actionType === actionType || ov.actionType === '*';
    if (!catMatch || !actionMatch) return false;
    const expTurn = ov.expiresTurn ?? (typeof state.turn === 'number' ? (state.turn as number) : turn);
    if (ov.scope === 'turn' && turn > expTurn) return false;
    return true;
  });

  if (matchIdx < 0) return false;

  const matched = overrides[matchIdx];
  if (matched.scope === 'once') {
    overrides.splice(matchIdx, 1);
  }

  return true;
}

