export function sanitizeCommandCenterSettings(src: unknown): CommandCenterSettings {
  const defaults = createDefaultCommandCenterSettings();
  if (!src || typeof src !== 'object' || src === null) return defaults;
  const obj = src as Record<string, unknown>;

  const defaultViewMode = (
    typeof obj.defaultViewMode === 'string' &&
    ['simple', 'detailed', 'developer'].includes(obj.defaultViewMode)
  ) ? (obj.defaultViewMode as CommandCenterViewMode) : defaults.defaultViewMode;

  const rawThresholds = (typeof obj.alertThresholds === 'object' && obj.alertThresholds !== null)
    ? (obj.alertThresholds as Record<string, unknown>)
    : {};

  const sanitizeNonNegativeNumber = (val: unknown, fallback: number): number => {
    return (typeof val === 'number' && Number.isFinite(val) && val >= 0) ? val : fallback;
  };

  const alertThresholds: Record<string, number> = {
    ...defaults.alertThresholds,
    minLiquidityReserve: sanitizeNonNegativeNumber(rawThresholds.minLiquidityReserve, defaults.alertThresholds.minLiquidityReserve),
    maxDebtRatio: sanitizeNonNegativeNumber(rawThresholds.maxDebtRatio, defaults.alertThresholds.maxDebtRatio),
    highRiskThreshold: sanitizeNonNegativeNumber(rawThresholds.highRiskThreshold, defaults.alertThresholds.highRiskThreshold),
  };

  for (const [key, val] of Object.entries(rawThresholds)) {
    if (!(key in alertThresholds)) {
      if (typeof val === 'number' && Number.isFinite(val) && val >= 0) {
        alertThresholds[key] = val;
      }
    }
  }

  const autoRefreshIntervalMs = (typeof obj.autoRefreshIntervalMs === 'number' && Number.isFinite(obj.autoRefreshIntervalMs) && obj.autoRefreshIntervalMs > 0)
    ? obj.autoRefreshIntervalMs
    : defaults.autoRefreshIntervalMs;

  const maxTelemetryLogEntries = (typeof obj.maxTelemetryLogEntries === 'number' && Number.isFinite(obj.maxTelemetryLogEntries) && obj.maxTelemetryLogEntries >= 0)
    ? obj.maxTelemetryLogEntries
    : undefined;

  const preferredPosition = (
    typeof obj.preferredPosition === 'object' &&
    obj.preferredPosition !== null &&
    typeof (obj.preferredPosition as Record<string, unknown>).x === 'number' &&
    Number.isFinite((obj.preferredPosition as Record<string, unknown>).x) &&
    typeof (obj.preferredPosition as Record<string, unknown>).y === 'number' &&
    Number.isFinite((obj.preferredPosition as Record<string, unknown>).y)
  ) ? {
    x: (obj.preferredPosition as Record<string, unknown>).x as number,
    y: (obj.preferredPosition as Record<string, unknown>).y as number
  } : undefined;

  return {
    ...defaults,
    enabled: typeof obj.enabled === 'boolean' ? obj.enabled : defaults.enabled,
    hideWidgetOnStartScreen: typeof obj.hideWidgetOnStartScreen === 'boolean' ? obj.hideWidgetOnStartScreen : defaults.hideWidgetOnStartScreen,
    showInPlayerStatusHeader: typeof obj.showInPlayerStatusHeader === 'boolean' ? obj.showInPlayerStatusHeader : defaults.showInPlayerStatusHeader,
    showCompactFloatingWidget: typeof obj.showCompactFloatingWidget === 'boolean' ? obj.showCompactFloatingWidget : defaults.showCompactFloatingWidget,
    allowDragging: typeof obj.allowDragging === 'boolean' ? obj.allowDragging : defaults.allowDragging,
    rememberPosition: typeof obj.rememberPosition === 'boolean' ? obj.rememberPosition : defaults.rememberPosition,
    allowMinimization: typeof obj.allowMinimization === 'boolean' ? obj.allowMinimization : defaults.allowMinimization,
    rememberMinimizedState: typeof obj.rememberMinimizedState === 'boolean' ? obj.rememberMinimizedState : defaults.rememberMinimizedState,
    hideFloatingWidgetWhileModalIsOpen: typeof obj.hideFloatingWidgetWhileModalIsOpen === 'boolean' ? obj.hideFloatingWidgetWhileModalIsOpen : defaults.hideFloatingWidgetWhileModalIsOpen,
    defaultViewMode,
    autoRefreshIntervalMs,
    alertThresholds,
    showOnTurnStart: typeof obj.showOnTurnStart === 'boolean' ? obj.showOnTurnStart : defaults.showOnTurnStart,
    compactWidgetDefault: typeof obj.compactWidgetDefault === 'boolean' ? obj.compactWidgetDefault : defaults.compactWidgetDefault,
    ...(preferredPosition !== undefined ? { preferredPosition } : {}),
    ...(maxTelemetryLogEntries !== undefined ? { maxTelemetryLogEntries } : {}),
  } as CommandCenterSettings;
}

export function sanitizeAiCommandCenterTelemetry(input: unknown): CommandCenterTelemetry {
  const defaults: CommandCenterTelemetry = {
    lastEvaluatedTimestamp: 0,
    evaluationDurationMs: 0,
    turnNumber: 0,
    dayNumber: 0,
    actorId: 'player',
    competitivePositionScore: 0,
    winProbabilityEstimate: 0,
    activeAlertsCount: 0,
    metricSnapshots: {},
    cacheHitRate: 0,
  };

  if (!input || typeof input !== 'object' || input === null) {
    return defaults;
  }

  const obj = input as Record<string, unknown>;

  const sanitizeNumber = (val: unknown, fallback: number): number => {
    if (typeof val === 'number' && Number.isFinite(val) && !Number.isNaN(val)) {
      return val;
    }
    return fallback;
  };

  const sanitizeString = (val: unknown, fallback: string): string => {
    if (typeof val === 'string' && val.trim() !== '') {
      return val;
    }
    return fallback;
  };

  const sanitizeMetricSnapshots = (val: unknown): Record<string, number> => {
    if (!val || typeof val !== 'object' || val === null) return {};
    const res: Record<string, number> = {};
    for (const [k, v] of Object.entries(val as Record<string, unknown>)) {
      if (typeof v === 'number' && Number.isFinite(v) && !Number.isNaN(v)) {
        res[k] = v;
      } else {
        res[k] = 0;
      }
    }
    return res;
  };

  return {
    lastEvaluatedTimestamp: Math.max(0, sanitizeNumber(obj.lastEvaluatedTimestamp, 0)),
    evaluationDurationMs: Math.max(0, sanitizeNumber(obj.evaluationDurationMs, 0)),
    turnNumber: Math.max(0, sanitizeNumber(obj.turnNumber, 0)),
    dayNumber: Math.max(0, sanitizeNumber(obj.dayNumber, 0)),
    actorId: sanitizeString(obj.actorId, 'player'),
    competitivePositionScore: Math.max(0, Math.min(100, sanitizeNumber(obj.competitivePositionScore, 0))),
    winProbabilityEstimate: Math.max(0, Math.min(1, sanitizeNumber(obj.winProbabilityEstimate, 0))),
    activeAlertsCount: Math.max(0, sanitizeNumber(obj.activeAlertsCount, 0)),
    metricSnapshots: sanitizeMetricSnapshots(obj.metricSnapshots),
    cacheHitRate: Math.max(0, Math.min(1, sanitizeNumber(obj.cacheHitRate, 0))),
  };
}

export function sanitizeCommandCenterState(src: unknown): CommandCenterState {
  const defaults = createDefaultCommandCenterState();
  if (!src || typeof src !== 'object' || src === null) return defaults;
  const obj = src as Record<string, unknown>;

  const activeTab = (
    typeof obj.activeTab === 'string' &&
    ['overview', 'next_move', 'priorities', 'risks', 'opportunities', 'team', 'opponents', 'ai_activity', 'explain', 'history', 'settings'].includes(obj.activeTab)
  ) ? (obj.activeTab as CommandCenterTab) : defaults.activeTab;

  const viewMode = (
    typeof obj.viewMode === 'string' &&
    ['simple', 'detailed', 'developer'].includes(obj.viewMode)
  ) ? (obj.viewMode as CommandCenterViewMode) : defaults.viewMode;

  const rawRecs = Array.isArray(obj.recommendations) ? obj.recommendations : [];
  const sanitizedRecs: CommandCenterRecommendation[] = rawRecs.map((rec: any, idx: number) => {
    if (!rec || typeof rec !== 'object') return { ...DEFAULT_SAFE_PLACEHOLDER_RECOMMENDATION, id: `rec_fallback_${idx}` };
    const conf = typeof rec.confidence === 'number' && Number.isFinite(rec.confidence) && !Number.isNaN(rec.confidence)
      ? Math.max(0, Math.min(1, rec.confidence))
      : 0;
    const prio = typeof rec.priority === 'number' && Number.isFinite(rec.priority) && !Number.isNaN(rec.priority)
      ? rec.priority
      : 1;
    const delta = typeof rec.counterfactualDelta === 'number' && Number.isFinite(rec.counterfactualDelta) && !Number.isNaN(rec.counterfactualDelta)
      ? rec.counterfactualDelta
      : 0;

    return {
      id: typeof rec.id === 'string' && rec.id.trim() ? rec.id : `rec_sanitized_${idx}`,
      title: typeof rec.title === 'string' && rec.title.trim() ? rec.title : DEFAULT_SAFE_PLACEHOLDER_RECOMMENDATION.title,
      category: typeof rec.category === 'string' && rec.category.trim() ? rec.category : DEFAULT_SAFE_PLACEHOLDER_RECOMMENDATION.category,
      description: typeof rec.description === 'string' && rec.description.trim() ? rec.description : DEFAULT_SAFE_PLACEHOLDER_RECOMMENDATION.description,
      expectedImpact: typeof rec.expectedImpact === 'string' && rec.expectedImpact.trim() ? rec.expectedImpact : DEFAULT_SAFE_PLACEHOLDER_RECOMMENDATION.expectedImpact,
      confidence: conf,
      priority: prio,
      counterfactualDelta: delta,
      suggestedAction: rec.suggestedAction
    };
  });

  const finalRecommendations = sanitizedRecs.length > 0 ? sanitizedRecs : [DEFAULT_SAFE_PLACEHOLDER_RECOMMENDATION];

  const rawRisks = Array.isArray(obj.risks) ? obj.risks : [];
  const sanitizedRisks: CommandCenterRisk[] = rawRisks.map((risk: any, idx: number) => {
    if (!risk || typeof risk !== 'object') {
      return {
        id: `risk_fallback_${idx}`,
        title: 'Operational Caution',
        category: 'economy',
        severity: 'low',
        severityScore: 10,
        probability: 0.1,
        description: 'Standard operational risk monitoring active.',
        mitigationSuggestion: 'Maintain liquid capital reserve.'
      };
    }
    const sevScore = typeof risk.severityScore === 'number' && Number.isFinite(risk.severityScore) && !Number.isNaN(risk.severityScore)
      ? Math.max(0, Math.min(100, risk.severityScore))
      : 0;
    const prob = typeof risk.probability === 'number' && Number.isFinite(risk.probability) && !Number.isNaN(risk.probability)
      ? Math.max(0, Math.min(1, risk.probability))
      : 0;

    return {
      id: typeof risk.id === 'string' && risk.id.trim() ? risk.id : `risk_sanitized_${idx}`,
      title: typeof risk.title === 'string' && risk.title.trim() ? risk.title : 'Operational Caution',
      category: typeof risk.category === 'string' && risk.category.trim() ? risk.category : 'economy',
      severity: ['low', 'medium', 'high', 'critical'].includes(risk.severity) ? risk.severity : 'low',
      severityScore: sevScore,
      probability: prob,
      description: typeof risk.description === 'string' && risk.description.trim() ? risk.description : 'Standard operational risk monitoring active.',
      mitigationSuggestion: typeof risk.mitigationSuggestion === 'string' ? risk.mitigationSuggestion : 'Maintain liquid capital reserve.'
    };
  });

  const telemetry = obj.telemetry !== undefined ? sanitizeAiCommandCenterTelemetry(obj.telemetry) : undefined;

  return {
    activeTab,
    viewMode,
    recommendations: finalRecommendations,
    priorities: Array.isArray(obj.priorities) ? obj.priorities : defaults.priorities,
    risks: sanitizedRisks,
    opportunities: Array.isArray(obj.opportunities) ? obj.opportunities : defaults.opportunities,
    teamSummary: typeof obj.teamSummary === 'object' && obj.teamSummary !== null ? obj.teamSummary as CommandCenterTeamSummary : undefined,
    opponents: Array.isArray(obj.opponents) ? obj.opponents : defaults.opponents,
    explanations: Array.isArray(obj.explanations) ? obj.explanations : defaults.explanations,
    blockers: Array.isArray(obj.blockers) ? obj.blockers : defaults.blockers,
    activities: Array.isArray(obj.activities) ? obj.activities : defaults.activities,
    telemetry,
    lastEvaluatedTurn: (
    typeof obj.lastEvaluatedTurn === 'number' &&
    Number.isFinite(obj.lastEvaluatedTurn) &&
    obj.lastEvaluatedTurn >= 0
  ) ? obj.lastEvaluatedTurn : defaults.lastEvaluatedTurn,
    isEvaluating: typeof obj.isEvaluating === 'boolean' ? obj.isEvaluating : false,
  };
}

