// Default Factories


export function normalizeAutoModeIntensity(input: unknown): AutoModeIntensity {
  const str = String(input || '');
  if (str === 'subtle' || str === 'gentle') return 'gentle';
  if (str === 'standard' || str === 'balanced') return 'balanced';
  if (str === 'aggressive' || str === 'responsive') return 'responsive';
  if (str === 'dynamic' || str === 'director') return 'director';
  return 'balanced';
}

export function canonicalizeAutoBalanceState(state: AutoModePerformanceState | string | undefined): AutoModePerformanceState {
  if (state === 'struggling' || state === 'critical' || state === 'distressed') return 'critical_behind';
  if (state === 'vulnerable' || state === 'recovery') return 'far_behind';
  if (state === 'strong') return 'slightly_ahead';
  if (
    state === 'critical_behind' ||
    state === 'far_behind' ||
    state === 'slightly_behind' ||
    state === 'balanced' ||
    state === 'slightly_ahead' ||
    state === 'far_ahead' ||
    state === 'dominant'
  ) {
    return state;
  }
  return 'balanced';
}

export function detectActiveAutoModePreset(settings: AutoModeGlobalSettings): AutoModePresetId {
  if (!settings) return 'custom';

  const activePerm = (settings.permissionMode || settings.permission) as string;
  if (activePerm === 'locked' || activePerm === 'disabled') return 'off';

  for (const [presetId, preset] of Object.entries(AUTO_MODE_PRESETS)) {
    if (presetId === 'off' || presetId === 'custom') continue;
    const isIntensityMatch = settings.intensity === preset.intensity;
    const isPermMatch = !activePerm || activePerm === preset.permissionMode;

    let isLimitsMatch = true;
    if (settings.numericalLimits && preset.numericalLimits) {
      if (settings.numericalLimits.maxStatModifierPct !== undefined &&
          preset.numericalLimits.maxStatModifierPct !== undefined &&
          settings.numericalLimits.maxStatModifierPct !== preset.numericalLimits.maxStatModifierPct) {
        isLimitsMatch = false;
      }
      if (settings.numericalLimits.maxResourceMultiplier !== undefined &&
          preset.numericalLimits.maxResourceMultiplier !== undefined &&
          settings.numericalLimits.maxResourceMultiplier !== preset.numericalLimits.maxResourceMultiplier) {
        isLimitsMatch = false;
      }
    }

    if (isIntensityMatch && isPermMatch && isLimitsMatch) {
      return presetId as AutoModePresetId;
    }
  }

  if ((settings.enabled as boolean) === false && (settings.autoModeEnabled as boolean) === false && !settings._fromSanitize) {
    if ((settings.intensity === 'standard' || settings.intensity === 'balanced') && (activePerm === 'recommend_only' || activePerm === 'recommend' || !activePerm)) {
      return 'off';
    }
  }

  return 'custom';
}

export function sanitizeAutoModeGlobalSettings(input: unknown): AutoModeGlobalSettings {
  const defaults = createDefaultAutoModeGlobalSettings();
  if (!input || typeof input !== 'object') {
    defaults._fromSanitize = true;
    return defaults;
  }
  const src = input as Record<string, unknown>;

  const validIntensities: AutoModeIntensity[] = ['gentle', 'balanced', 'responsive', 'director', 'subtle', 'standard', 'aggressive', 'dynamic'];
  const validPermissions: AutoModePermission[] = ['locked', 'observe', 'recommend', 'assist_only', 'challenge_only', 'full_adaptive', 'disabled', 'recommend_only', 'auto_apply_non_intrusive', 'full_auto'];
  const validTransparencies: AutoModeTransparency[] = ['minimal', 'standard', 'detailed', 'developer', 'silent', 'ledger_only', 'toast_notifications', 'modal_approvals', 'full_diagnostics'];

  const categoryTogglesSrc = (src['categoryToggles'] && typeof src['categoryToggles'] === 'object')
    ? (src['categoryToggles'] as Record<string, unknown>)
    : {};
  const categoryToggles: AutoModeCategoryToggles = {
    economic: typeof categoryTogglesSrc['economic'] === 'boolean' ? (categoryTogglesSrc['economic'] as boolean) : true,
    progression: typeof categoryTogglesSrc['progression'] === 'boolean' ? (categoryTogglesSrc['progression'] as boolean) : true,
    regional: typeof categoryTogglesSrc['regional'] === 'boolean' ? (categoryTogglesSrc['regional'] as boolean) : true,
    infrastructure: typeof categoryTogglesSrc['infrastructure'] === 'boolean' ? (categoryTogglesSrc['infrastructure'] as boolean) : true,
    expedition: typeof categoryTogglesSrc['expedition'] === 'boolean' ? (categoryTogglesSrc['expedition'] as boolean) : true,
    equipment: typeof categoryTogglesSrc['equipment'] === 'boolean' ? (categoryTogglesSrc['equipment'] as boolean) : true,
    risk_management: typeof categoryTogglesSrc['risk_management'] === 'boolean' ? (categoryTogglesSrc['risk_management'] as boolean) : true
  };

  const rawIntensity = typeof src['intensity'] === 'string' && (validIntensities as string[]).includes(src['intensity'] as string)
    ? (src['intensity'] as AutoModeIntensity)
    : defaults.intensity;
  const intensity = normalizeAutoModeIntensity(rawIntensity);
  const rawPermission = typeof src['permissionMode'] === 'string' && (validPermissions as string[]).includes(src['permissionMode'] as string)
    ? (src['permissionMode'] as AutoModePermission)
    : (typeof src['permission'] === 'string' && (validPermissions as string[]).includes(src['permission'] as string)
      ? (src['permission'] as AutoModePermission)
      : defaults.permissionMode);
  const permission = normalizePermissionMode(rawPermission);

  const enabled = typeof src['enabled'] === 'boolean' ? src['enabled'] : (typeof src['autoModeEnabled'] === 'boolean' ? src['autoModeEnabled'] : false);

  const numLimitsSrc = (src['numericalLimits'] && typeof src['numericalLimits'] === 'object')
    ? (src['numericalLimits'] as Record<string, unknown>)
    : {};

  const numericalLimits: AutoModeNumericalLimits = {
    maxChallengeSuccessBonus: typeof numLimitsSrc['maxChallengeSuccessBonus'] === 'number' ? (numLimitsSrc['maxChallengeSuccessBonus'] as number) : defaults.numericalLimits.maxChallengeSuccessBonus,
    maxTravelDiscount: typeof numLimitsSrc['maxTravelDiscount'] === 'number' ? (numLimitsSrc['maxTravelDiscount'] as number) : defaults.numericalLimits.maxTravelDiscount,
    maxResourceYieldBonus: typeof numLimitsSrc['maxResourceYieldBonus'] === 'number' ? (numLimitsSrc['maxResourceYieldBonus'] as number) : defaults.numericalLimits.maxResourceYieldBonus,
    maxContractRewardBonus: typeof numLimitsSrc['maxContractRewardBonus'] === 'number' ? (numLimitsSrc['maxContractRewardBonus'] as number) : defaults.numericalLimits.maxContractRewardBonus,
    maxTemporaryCashGrant: typeof numLimitsSrc['maxTemporaryCashGrant'] === 'number' ? (numLimitsSrc['maxTemporaryCashGrant'] as number) : defaults.numericalLimits.maxTemporaryCashGrant,
    maxActionPointGrant: typeof numLimitsSrc['maxActionPointGrant'] === 'number' ? (numLimitsSrc['maxActionPointGrant'] as number) : defaults.numericalLimits.maxActionPointGrant,
    maxDurationTurns: typeof numLimitsSrc['maxDurationTurns'] === 'number' ? (numLimitsSrc['maxDurationTurns'] as number) : defaults.numericalLimits.maxDurationTurns,

    maxStatModifierPct: typeof numLimitsSrc['maxStatModifierPct'] === 'number' ? (numLimitsSrc['maxStatModifierPct'] as number) : defaults.numericalLimits.maxStatModifierPct,
    maxResourceMultiplier: typeof numLimitsSrc['maxResourceMultiplier'] === 'number' ? (numLimitsSrc['maxResourceMultiplier'] as number) : defaults.numericalLimits.maxResourceMultiplier,
    maxCostReductionPct: typeof numLimitsSrc['maxCostReductionPct'] === 'number' ? (numLimitsSrc['maxCostReductionPct'] as number) : defaults.numericalLimits.maxCostReductionPct,
    maxCooldownReductionTurns: typeof numLimitsSrc['maxCooldownReductionTurns'] === 'number' ? (numLimitsSrc['maxCooldownReductionTurns'] as number) : defaults.numericalLimits.maxCooldownReductionTurns,
    maxAutoActionsPerTurn: typeof numLimitsSrc['maxAutoActionsPerTurn'] === 'number' ? (numLimitsSrc['maxAutoActionsPerTurn'] as number) : defaults.numericalLimits.maxAutoActionsPerTurn
  };

  return {
    enabled,
    autoModeEnabled: enabled,
    intensity,
    permission,
    permissionMode: permission,
    transparency: typeof src['transparency'] === 'string' && (validTransparencies as string[]).includes(src['transparency'] as string) ? (src['transparency'] as AutoModeTransparency) : defaults.transparency,
    transparencyMode: (typeof src['transparencyMode'] === 'string' && (validTransparencies as string[]).includes(src['transparencyMode'] as string) ? (src['transparencyMode'] as AutoModeTransparency) : (typeof src['transparency'] === 'string' && (validTransparencies as string[]).includes(src['transparency'] as string) ? (src['transparency'] as AutoModeTransparency) : (defaults.transparencyMode || defaults.transparency || 'detailed'))) as AutoModeTransparency,

    observationWindowTurns: typeof src['observationWindowTurns'] === 'number' ? src['observationWindowTurns'] : (typeof src['observationWindow'] === 'number' ? src['observationWindow'] : 3),
    observationWindow: typeof src['observationWindowTurns'] === 'number' ? src['observationWindowTurns'] : (typeof src['observationWindow'] === 'number' ? src['observationWindow'] : 3),
    adjustmentCooldownTurns: Math.max(0, typeof src['adjustmentCooldownTurns'] === 'number' ? src['adjustmentCooldownTurns'] : (typeof src['cooldownTurns'] === 'number' ? src['cooldownTurns'] : 4)),
    cooldownTurns: Math.max(0, typeof src['cooldownTurns'] === 'number' ? src['cooldownTurns'] : (typeof src['adjustmentCooldownTurns'] === 'number' ? src['adjustmentCooldownTurns'] : 4)),
    minimumConfidence: typeof src['minimumConfidence'] === 'number' ? src['minimumConfidence'] : (typeof src['minConfidenceThreshold'] === 'number' ? src['minConfidenceThreshold'] : 0.70),
    minimumConfidenceThreshold: typeof src['minimumConfidenceThreshold'] === 'number' ? src['minimumConfidenceThreshold'] : (typeof src['minimumConfidence'] === 'number' ? src['minimumConfidence'] : (typeof src['minConfidenceThreshold'] === 'number' ? src['minConfidenceThreshold'] : 0.70)),
    minConfidenceThreshold: typeof src['minimumConfidence'] === 'number' ? src['minimumConfidence'] : 0.70,
    maximumChangesPerEvaluation: typeof src['maximumChangesPerEvaluation'] === 'number' ? src['maximumChangesPerEvaluation'] : (typeof src['maxChangesPerEvaluation'] === 'number' ? src['maxChangesPerEvaluation'] : 3),
    maxChangesPerEvaluation: typeof src['maximumChangesPerEvaluation'] === 'number' ? src['maximumChangesPerEvaluation'] : 3,

    allowStrategyChanges: typeof src['allowStrategyChanges'] === 'boolean' ? src['allowStrategyChanges'] : true,
    allowEconomyChanges: typeof src['allowEconomyChanges'] === 'boolean' ? src['allowEconomyChanges'] : true,
    allowActionManagementChanges: typeof src['allowActionManagementChanges'] === 'boolean' ? src['allowActionManagementChanges'] : true,
    allowOpportunityGeneration: typeof src['allowOpportunityGeneration'] === 'boolean' ? src['allowOpportunityGeneration'] : true,
    allowNumericalModifiers: typeof src['allowNumericalModifiers'] === 'boolean' ? src['allowNumericalModifiers'] : false,
    allowDifficultyAdjustments: typeof src['allowDifficultyAdjustments'] === 'boolean' ? src['allowDifficultyAdjustments'] : true,
    allowHumanAutopilot: typeof src['allowHumanAutopilot'] === 'boolean' ? src['allowHumanAutopilot'] : false,

    requireApprovalForHumanChanges: typeof src['requireApprovalForHumanChanges'] === 'boolean' ? src['requireApprovalForHumanChanges'] : true,
    requireApprovalForNumericalModifiers: typeof src['requireApprovalForNumericalModifiers'] === 'boolean' ? src['requireApprovalForNumericalModifiers'] : true,
    preserveReplayDeterminism: typeof src['preserveReplayDeterminism'] === 'boolean' ? src['preserveReplayDeterminism'] : true,
    autoModeAllowedInAlgorithmComparison: typeof src['autoModeAllowedInAlgorithmComparison'] === 'boolean' ? src['autoModeAllowedInAlgorithmComparison'] : false,
    autoModeOnboardingComplete: typeof src['autoModeOnboardingComplete'] === 'boolean' ? src['autoModeOnboardingComplete'] : false,
    appliedPresetId: typeof src['appliedPresetId'] === 'string' ? (src['appliedPresetId'] as AutoModePresetId) : undefined,

    recommendationNotificationLevel: (['critical_only', 'important_and_critical', 'all', 'off'].includes(src['recommendationNotificationLevel'] as string)
      ? (src['recommendationNotificationLevel'] as AutoModeRecommendationNotificationLevel)
      : 'critical_only'),
    categoryToggles,
    numericalLimits,
    actorPolicies: (() => {
      const raw = (src['actorPolicies'] && typeof src['actorPolicies'] === 'object') ? (src['actorPolicies'] as Record<string | number, unknown>) : {};
      const res: Record<string | number, ActorAutoModePolicy> = {};
      for (const [k, v] of Object.entries(raw)) {
        if (v && typeof v === 'object') {
          res[k] = sanitizeActorAutoModePolicy(v);
        }
      }
      return res;
    })(),
    teamPolicies: (() => {
      const raw = (src['teamPolicies'] && typeof src['teamPolicies'] === 'object') ? (src['teamPolicies'] as Record<string, unknown>) : {};
      const res: Record<string, TeamAutoModePolicy> = {};
      for (const [k, v] of Object.entries(raw)) {
        if (v && typeof v === 'object') {
          res[k] = sanitizeTeamAutoModePolicy(v);
        }
      }
      return res;
    })()
  };
}

export function deriveProposalFamily(proposal: Partial<AutoModeProposal>): string {
  if (proposal.family && typeof proposal.family === 'string' && proposal.family.trim().length > 0) {
    return proposal.family.toLowerCase().replace(/[^a-z0-9_]+/g, '_').replace(/^_+|_+$/g, '');
  }
  const pkg = proposal.proposedPackage || proposal.actionPackage;
  let family = '';
  if (proposal.packageId) {
    family = proposal.packageId.replace(/^pkg-[^-]+-[^-]+-/, '').replace(/^pkg_/, '');
  } else if (pkg?.packageId) {
    family = pkg.packageId.replace(/^pkg-[^-]+-[^-]+-/, '').replace(/^pkg_/, '');
  } else if (pkg?.packageName) {
    family = pkg.packageName.toLowerCase().replace(/[^a-z0-9]+/g, '_');
  } else if (proposal.title) {
    family = proposal.title.toLowerCase().replace(/[^a-z0-9]+/g, '_');
  } else {
    family = proposal.category || 'default_family';
  }
  return family.toLowerCase().replace(/[^a-z0-9_]+/g, '_').replace(/^_+|_+$/g, '') || 'default_family';
}

export function sanitizeAutoModeRuntimeState(input: unknown, parentState?: any): AutoModeRuntimeState {
  const defaults = createDefaultAutoModeRuntimeState();
  if (!input || typeof input !== 'object') {
    return defaults;
  }
  const src = input as Record<string, unknown>;

  const rawPerfHist = (src['performanceHistory'] && typeof src['performanceHistory'] === 'object') ? (src['performanceHistory'] as Record<string | number, AutoModePerformanceHistory>) : {};
  const sanitizedPerfHist: Record<string | number, AutoModePerformanceHistory> = {};
  for (const [k, v] of Object.entries(rawPerfHist)) {
    if (v && typeof v === 'object') {
      sanitizedPerfHist[k] = {
        ...v,
        classifications: Array.isArray(v.classifications) ? v.classifications.slice(-20) : [],
        scores: Array.isArray(v.scores) ? v.scores.slice(-20) : [],
        confidenceValues: Array.isArray(v.confidenceValues) ? v.confidenceValues.slice(-20) : []
      };
    }
  }

  const activePackages = Array.isArray(src['activePackages']) ? (src['activePackages'] as AutoModeAdjustmentRecord[]) : [];
  const activeCategoriesByActor: Record<string, Set<string>> = {};
  for (const actPkg of activePackages) {
    if (actPkg.status === 'active' || actPkg.reversibilityState === 'active' || !actPkg.status) {
      const actId = String(actPkg.targetActorId ?? actPkg.actorId ?? 0);
      if (!activeCategoriesByActor[actId]) activeCategoriesByActor[actId] = new Set();
      if (actPkg.category) activeCategoriesByActor[actId].add(normalizeAutoModeCategory(actPkg.category));
    }
  }

  const perfStates = (src['actorPerformanceStates'] && typeof src['actorPerformanceStates'] === 'object')
    ? (src['actorPerformanceStates'] as Record<string | number, AutoModePerformanceState>)
    : {};

  const existingHistory = Array.isArray(src['proposalHistory']) ? (src['proposalHistory'] as AutoModeProposal[]) : [];

  const rawPendingProposals = [
    ...(Array.isArray(src['pendingProposals']) ? (src['pendingProposals'] as AutoModeProposal[]) : []),
    ...(Array.isArray(src['proposalQueue']) ? (src['proposalQueue'] as AutoModeProposal[]) : [])
  ];

  const seenRawIds = new Set<string>();
  const uniqueRawProposals: AutoModeProposal[] = [];
  for (const p of rawPendingProposals) {
    if (!p || typeof p !== 'object') continue;
    const pId = p.id || `prop_sanitized_${cosmeticRandom().toString(36).substr(2, 5)}`;
    if (!seenRawIds.has(pId)) {
      seenRawIds.add(pId);
      uniqueRawProposals.push({ ...p, id: pId });
    }
  }

  const normalizedProposals: AutoModeProposal[] = uniqueRawProposals.map(p => {
    const actorId = p.actorId ?? p.targetActorId ?? 0;
    const targetActorId = p.targetActorId ?? actorId;
    const cat = p.category || 'economic';
    const pkg = p.proposedPackage || p.actionPackage || {
      packageId: p.packageId || `pkg_${p.id}`,
      targetActorId: actorId,
      category: cat,
      performanceState: p.performanceState || 'slightly_behind',
      priorityRank: p.priorityRank || 1,
      packageName: p.title || 'Auto Mode Proposal',
      description: p.description || '',
      payloadChanges: (p.payload as AutoModePayloadChanges) || {},
      durationTurns: 3,
      isReversible: true,
      reversibilityState: 'active'
    };
    const family = deriveProposalFamily(p);
    const fp = p.fingerprint || computeProposalFingerprint(actorId, cat, pkg);
    const sev = p.severity || deriveProposalSeverity(p.performanceState, p.priorityRank);
    const turnCreated = p.turnCreated ?? p.proposedTurn ?? 1;
    const proposedTurn = p.proposedTurn ?? turnCreated;
    const expiresTurn = p.expiresTurn ?? p.turnExpires ?? (proposedTurn + 10);
    const turnExpires = p.turnExpires ?? expiresTurn;
    const snoozeUntilTurn = p.snoozeUntilTurn ?? p.dismissedUntilTurn;
    const dismissedUntilTurn = p.dismissedUntilTurn ?? snoozeUntilTurn;

    return {
      ...p,
      actorId,
      targetActorId,
      category: cat,
      family,
      fingerprint: fp,
      severity: sev,
      packageId: p.packageId || pkg.packageId,
      proposedPackage: pkg,
      actionPackage: pkg,
      turnCreated,
      proposedTurn,
      expiresTurn,
      turnExpires,
      snoozeUntilTurn,
      dismissedUntilTurn,
      status: p.status || 'pending',
      isConsolidatedPlan: Boolean(p.isConsolidatedPlan),
      microAdjustments: Array.isArray(p.microAdjustments) ? p.microAdjustments : []
    };
  });

  const additionalHistory: AutoModeProposal[] = [];
  const validPendingMap: Record<string, AutoModeProposal[]> = {};

  for (const prop of normalizedProposals) {
    if (prop.status && prop.status !== 'pending') {
      additionalHistory.push(prop);
      continue;
    }

    const actorIdStr = String(prop.actorId ?? 0);
    const normCat = normalizeAutoModeCategory(prop.category);
    const actorPerf = perfStates[actorIdStr] || 'balanced';

    // Active package coverage purge
    const activeCats = activeCategoriesByActor[actorIdStr];
    if (activeCats && normCat && activeCats.has(normCat)) {
      prop.status = 'expired';
      additionalHistory.push(prop);
      if (parentState) {
        recordProposalLifecycleEvent(parentState, 'expired', prop, { reason: 'active_package_coverage' });
      }
      continue;
    }

    // Performance recovery purge
    const isCatchupAtCreation = ['critical', 'critical_behind', 'far_behind', 'distressed'].includes(
      String(prop.performanceStateAtCreation || prop.performanceState || '').toLowerCase()
    );
    const isCurrentlyRecovered = ['balanced', 'stable', 'slightly_ahead', 'dominant', 'far_ahead'].includes(
      String(actorPerf).toLowerCase()
    );
    if (isCatchupAtCreation && isCurrentlyRecovered) {
      prop.status = 'expired';
      additionalHistory.push(prop);
      if (parentState) {
        recordProposalLifecycleEvent(parentState, 'expired', prop, { reason: 'performance_recovered' });
      }
      continue;
    }

    const semKey = prop.fingerprint || `${actorIdStr}_${normCat}_${prop.family}`;
    if (!validPendingMap[semKey]) validPendingMap[semKey] = [];
    validPendingMap[semKey].push(prop);
  }

  const severityRankMap: Record<string, number> = { critical: 4, important: 3, suggestion: 2, info: 1 };
  const collapsedPending: AutoModeProposal[] = [];

  for (const [, group] of Object.entries(validPendingMap)) {
    if (group.length === 1) {
      collapsedPending.push(group[0]);
    } else {
      group.sort((a, b) => {
        const aSev = severityRankMap[a.severity || 'info'] || 1;
        const bSev = severityRankMap[b.severity || 'info'] || 1;
        if (bSev !== aSev) return bSev - aSev;

        const aRank = a.priorityRank ?? 99;
        const bRank = b.priorityRank ?? 99;
        if (aRank !== bRank) return aRank - bRank;

        return (b.proposedTurn || 0) - (a.proposedTurn || 0);
      });

      const winner = group[0];
      const mergedPkgs: AutoModeAdjustmentPackage[] = [
        ...(winner.microAdjustments || []),
        ...(winner.proposedPackage ? [winner.proposedPackage] : [])
      ];

      for (let i = 1; i < group.length; i++) {
        const loser = group[i];
        loser.status = 'superseded';
        loser.supersededBy = winner.id;
        additionalHistory.push(loser);
        if (parentState) {
          recordProposalLifecycleEvent(parentState, 'superseded', loser, { supersededBy: winner.id });
        }

        if (loser.proposedPackage) {
          mergedPkgs.push(loser.proposedPackage);
        }
        if (loser.microAdjustments) {
          mergedPkgs.push(...loser.microAdjustments);
        }
      }

      if (mergedPkgs.length > 1) {
        winner.isConsolidatedPlan = true;
        winner.microAdjustments = mergedPkgs;
        if (parentState) {
          recordProposalLifecycleEvent(parentState, 'consolidated', winner, { consolidatedCount: mergedPkgs.length });
        }
      }
      collapsedPending.push(winner);
    }
  }

  const proposalsByActor: Record<string, AutoModeProposal[]> = {};
  for (const p of collapsedPending) {
    const actId = String(p.actorId ?? 0);
    if (!proposalsByActor[actId]) proposalsByActor[actId] = [];
    proposalsByActor[actId].push(p);
  }

  const finalPendingList: AutoModeProposal[] = [];
  for (const [, actorList] of Object.entries(proposalsByActor)) {
    actorList.sort((a, b) => {
      const aSev = severityRankMap[a.severity || 'info'] || 1;
      const bSev = severityRankMap[b.severity || 'info'] || 1;
      if (bSev !== aSev) return bSev - aSev;

      const aRank = a.priorityRank ?? 99;
      const bRank = b.priorityRank ?? 99;
      if (aRank !== bRank) return aRank - bRank;

      return (b.proposedTurn || 0) - (a.proposedTurn || 0);
    });

    const kept = actorList.slice(0, 5); // Capped at max 5 per actor
    const overflow = actorList.slice(5);
    for (const ov of overflow) {
      ov.status = 'expired';
      additionalHistory.push(ov);
      if (parentState) {
        recordProposalLifecycleEvent(parentState, 'expired', ov, { reason: 'queue_overflow' });
      }
    }
    finalPendingList.push(...kept);
  }

  const combinedHistory = [...additionalHistory, ...existingHistory];
  const uniqueHistoryIds = new Set<string>();
  const sanitizedHistory: AutoModeProposal[] = [];
  for (const h of combinedHistory) {
    if (h && h.id && !uniqueHistoryIds.has(h.id)) {
      uniqueHistoryIds.add(h.id);
      sanitizedHistory.push(h);
    }
  }

  return {
    activePackages,
    proposalQueue: finalPendingList,
    pendingProposals: finalPendingList,
    proposalHistory: sanitizedHistory.slice(0, 500),
    actorObservationWindows: (src['actorObservationWindows'] && typeof src['actorObservationWindows'] === 'object') ? (src['actorObservationWindows'] as Record<string | number, AutoModeObservationWindow>) : {},
    teamObservationWindows: (src['teamObservationWindows'] && typeof src['teamObservationWindows'] === 'object') ? (src['teamObservationWindows'] as Record<string, AutoModeObservationWindow>) : {},
    actorPerformanceStates: perfStates,
    teamPerformanceStates: (src['teamPerformanceStates'] && typeof src['teamPerformanceStates'] === 'object') ? (src['teamPerformanceStates'] as Record<string, AutoModePerformanceState>) : {},
    actorLastEvaluationTurn: (src['actorLastEvaluationTurn'] && typeof src['actorLastEvaluationTurn'] === 'object') ? (src['actorLastEvaluationTurn'] as Record<string | number, number>) : {},
    teamLastEvaluationTurn: (src['teamLastEvaluationTurn'] && typeof src['teamLastEvaluationTurn'] === 'object') ? (src['teamLastEvaluationTurn'] as Record<string, number>) : {},
    actorLastEvaluationKey: (src['actorLastEvaluationKey'] && typeof src['actorLastEvaluationKey'] === 'object') ? (src['actorLastEvaluationKey'] as Record<string | number, string>) : {},
    evaluatedTurnKeys: (src['evaluatedTurnKeys'] && typeof src['evaluatedTurnKeys'] === 'object') ? (src['evaluatedTurnKeys'] as Record<string, boolean>) : {},
    boundaryLastEvaluatedKey: (src['boundaryLastEvaluatedKey'] && typeof src['boundaryLastEvaluatedKey'] === 'object') ? (src['boundaryLastEvaluatedKey'] as Record<string, string>) : {},
    ledgerLog: Array.isArray(src['ledgerLog']) ? (src['ledgerLog'] as string[]).slice(-500) : [],
    directorRequests: Array.isArray(src['directorRequests']) ? (src['directorRequests'] as AutoModeDirectorRequest[]) : [],
    adjustmentOutcomes: Array.isArray(src['adjustmentOutcomes']) ? (src['adjustmentOutcomes'] as AutoModeAdjustmentOutcome[]) : [],
    replayEvents: Array.isArray(src['replayEvents']) ? (src['replayEvents'] as AutoModeReplayEvent[]).slice(-500) : [],
    performanceHistory: sanitizedPerfHist,
    appliedPackageHistory: Array.isArray(src['appliedPackageHistory']) ? (src['appliedPackageHistory'] as AutoModeAdjustmentRecord[]).slice(-50) : [],
    rollbackHistory: Array.isArray(src['rollbackHistory']) ? (src['rollbackHistory'] as AutoModeAdjustmentRecord[]).slice(-50) : [],
    systemAuditTrail: Array.isArray(src['systemAuditTrail']) ? (src['systemAuditTrail'] as string[]).slice(-500) : [],
    decisionTrail: Array.isArray(src['decisionTrail']) ? (src['decisionTrail'] as string[]).slice(-500) : [],
    lastTickedTurnKey: (src['lastTickedTurnKey'] !== undefined) ? (src['lastTickedTurnKey'] as string | Record<string | number, string>) : defaults.lastTickedTurnKey,
    recordedChaosDivergence: typeof src['recordedChaosDivergence'] === 'boolean' ? src['recordedChaosDivergence'] : false
  };
}

export function sanitizeSaveData(rawData: unknown): any {
  if (!rawData || typeof rawData !== 'object' || rawData === null) {
    return rawData;
  }
  const saveObj = JSON.parse(JSON.stringify(rawData)) as Record<string, any>;

  if (saveObj.autoModeRuntime) {
    saveObj.autoModeRuntime = sanitizeAutoModeRuntimeState(saveObj.autoModeRuntime, saveObj);
  }
  if (saveObj.autoModeRuntimeState) {
    saveObj.autoModeRuntimeState = sanitizeAutoModeRuntimeState(saveObj.autoModeRuntimeState, saveObj);
  }
  if (saveObj.gameState) {
    if (saveObj.gameState.autoModeRuntime) {
      saveObj.gameState.autoModeRuntime = sanitizeAutoModeRuntimeState(saveObj.gameState.autoModeRuntime, saveObj.gameState);
    }
    if (saveObj.gameState.autoModeRuntimeState) {
      saveObj.gameState.autoModeRuntimeState = sanitizeAutoModeRuntimeState(saveObj.gameState.autoModeRuntimeState, saveObj.gameState);
    }
  }
  if (saveObj.gameSettings) {
    saveObj.gameSettings = sanitizeGameSettings(saveObj.gameSettings);
  }

  return saveObj;
}

// CO-PILOT SYSTEM: DATA STRUCTURES, AUTHORITY MODES, SETTINGS & VALIDATION (MILESTONE 1)

/**
 * 7 Co-Pilot Authority Modes defining operational autonomy and user override boundaries.
 */
export type CoPilotAuthorityMode =
  | 'off'
  | 'monitor_only'
  | 'warnings'
  | 'recommendations'
  | 'ask_before_acting'
  | 'automatic_rescue'
  | 'full_co_pilot';

export const COPILOT_AUTHORITY_MODES: readonly CoPilotAuthorityMode[] = [
  'off',
  'monitor_only',
  'warnings',
  'recommendations',
  'ask_before_acting',
  'automatic_rescue',
  'full_co_pilot'
] as const;

export type CoPilotUiConceptualMode = 'off' | 'advisor' | 'active_assistant' | 'takeover_requested' | 'autonomous_takeover';

/**
 * Central bidirectional mapping from UI conceptual mode to technical Co-Pilot settings (Requirement R1).
 */
export function mapConceptualModeToTechnicalSettings(conceptualMode: string): { coPilotEnabled: boolean; authorityMode: CoPilotAuthorityMode } {
  switch (conceptualMode) {
    case 'off':
      return { coPilotEnabled: false, authorityMode: 'off' };
    case 'advisor':
      return { coPilotEnabled: true, authorityMode: 'recommendations' };
    case 'active_assistant':
      return { coPilotEnabled: true, authorityMode: 'ask_before_acting' };
    case 'takeover_requested':
      return { coPilotEnabled: true, authorityMode: 'automatic_rescue' };
    case 'autonomous_takeover':
      return { coPilotEnabled: true, authorityMode: 'full_co_pilot' };
    default:
      return { coPilotEnabled: true, authorityMode: 'recommendations' };
  }
}

/**
 * Central bidirectional mapping from technical Co-Pilot settings to UI conceptual mode (Requirement R1).
 */
export function mapTechnicalSettingsToConceptualMode(coPilotEnabled?: boolean, authorityMode?: CoPilotAuthorityMode | string): CoPilotUiConceptualMode {
  if (!coPilotEnabled || authorityMode === 'off') {
    return 'off';
  }
  switch (authorityMode) {
    case 'monitor_only':
    case 'warnings':
    case 'recommendations':
      return 'advisor';
    case 'ask_before_acting':
      return 'active_assistant';
    case 'automatic_rescue':
      return 'takeover_requested';
    case 'full_co_pilot':
      return 'autonomous_takeover';
    default:
      return 'advisor';
  }
}

export const mapCoPilotUiModeToTechnical = mapConceptualModeToTechnicalSettings;
export const mapTechnicalToCoPilotUiMode = mapTechnicalSettingsToConceptualMode;


