export interface AskGameResolvedEntities {
  regions: string[];
  resources: string[];
  actors: string[];
  contractIds: string[];
  infrastructureTypes: string[];
  relicNames: string[];
  settingKeys: string[];
  rawMatches: Record<string, string[]>;
}

// AskGameEvidenceBundle is declared in Section 4 below

export interface AskGameMessage {
  id: string;
  sender: 'user' | 'system' | 'ai_assistant';
  timestamp: number;
  text: string;
  normalizedQuery?: string;
  classifiedIntent?: AskGameIntent;
  confidence?: number;
  resolvedEntities?: AskGameResolvedEntities;
  answerCard?: AskGameAnswerCard;
  response?: AskGameResponse;
  isError?: boolean;
}

export interface AskGameConversationState {
  conversationId: string;
  activeTurn: number;
  messages: AskGameMessage[];
  lastClassifiedIntent?: AskGameIntent;
  lastResolvedEntities?: AskGameResolvedEntities;
  isProcessing: boolean;
  activeFilterCategory?: AskGameIntentCategory;
  quickPromptChips: string[];
}

export interface AskGameNormalizedQuery {
  originalQuery: string;
  normalizedQuery: string;
  tokens: string[];
  cleanedString: string;
}

export interface AskGameClassificationResult {
  intent: AskGameIntent;
  confidence: number;
  matchedKeywords: string[];
  secondaryIntents: Array<{ intent: AskGameIntent; confidence: number }>;
  fallback: boolean;
}

export type AskGameIntentClassificationResult = AskGameClassificationResult;

// === ASK THE GAME AI: INTENT CLASSIFIER & ENTITY RESOLVER ===

/**
 * QueryNormalizer: Standardizes punctuation, casing, whitespace, and game terms/aliases.
 */
export function normalizeAskGameQuery(rawQuery: string): string {
  const originalQuery = rawQuery || '';
  let cleaned = originalQuery.toLowerCase().trim();

  // Strip decorative punctuation preserving spaces and alphanumeric characters
  cleaned = cleaned.replace(/[^\w\s-]/g, ' ');
  cleaned = cleaned.replace(/\s+/g, ' ').trim();

  // Alias & Term Normalization
  const aliasMap: Record<string, string> = {
    'queensland': 'qld',
    'new south wales': 'nsw',
    'victoria': 'vic',
    'south australia': 'sa',
    'western australia': 'wa',
    'northern territory': 'nt',
    'tasmania': 'tas',
    'action points': 'ap',
    'action point': 'ap',
    'loans': 'credit',
    'debt': 'credit',
    'emergency loans': 'credit',
    'gold mine': 'gold',
    'coal mine': 'coal'
  };

  for (const [alias, replacement] of Object.entries(aliasMap)) {
    const escapedAlias = alias.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const regex = new RegExp(`\\b${escapedAlias}\\b`, 'gi');
    cleaned = cleaned.replace(regex, replacement);
  }

  return cleaned;
}

export function parseAskGameNormalizedQuery(rawQuery: string): AskGameNormalizedQuery {
  const cleaned = normalizeAskGameQuery(rawQuery);
  const tokens = cleaned.split(' ').filter(Boolean);
  return {
    originalQuery: rawQuery || '',
    normalizedQuery: cleaned,
    tokens,
    cleanedString: cleaned
  };
}

/**
 * EntityResolver: Parses named entities (regions, resources, actors, contracts, infrastructure, relics, settings).
 */
export function resolveAskGameEntities(
  rawQuery: string | AskGameNormalizedQuery,
  gameState?: any,
  playerState?: any
): AskGameResolvedEntities {
  const norm = typeof rawQuery === 'string' ? parseAskGameNormalizedQuery(rawQuery) : rawQuery;
  const cleaned = norm.cleanedString;

  const result: AskGameResolvedEntities = {
    regions: [],
    resources: [],
    actors: [],
    contractIds: [],
    infrastructureTypes: [],
    relicNames: [],
    settingKeys: [],
    rawMatches: {}
  };

  // Regions (QLD, NSW, VIC, SA, WA, NT, TAS)
  const regionMap: Record<string, string> = {
    'qld': 'QLD', 'queensland': 'QLD',
    'nsw': 'NSW', 'new south wales': 'NSW',
    'vic': 'VIC', 'victoria': 'VIC',
    'sa': 'SA', 'south australia': 'SA',
    'wa': 'WA', 'western australia': 'WA',
    'nt': 'NT', 'northern territory': 'NT',
    'tas': 'TAS', 'tasmania': 'TAS'
  };
  const matchedRegions = new Set<string>();
  for (const [key, code] of Object.entries(regionMap)) {
    if (new RegExp(`\\b${key}\\b`, 'i').test(cleaned)) {
      matchedRegions.add(code);
    }
  }
  result.regions = Array.from(matchedRegions);

  // Resources (Gold, Water, Coal, Wheat, Livestock, Iron, Opal, Timber)
  const resourceMap: Record<string, string> = {
    'gold': 'Gold', 'water': 'Water', 'coal': 'Coal',
    'wheat': 'Wheat', 'livestock': 'Livestock', 'cattle': 'Livestock',
    'iron': 'Iron', 'opal': 'Opal', 'timber': 'Timber', 'wood': 'Timber'
  };
  const matchedResources = new Set<string>();
  for (const [key, canon] of Object.entries(resourceMap)) {
    if (new RegExp(`\\b${key}\\b`, 'i').test(cleaned)) {
      matchedResources.add(canon);
    }
  }
  result.resources = Array.from(matchedResources);

  // Actors (player, ai, teammates)
  const matchedActors = new Set<string>();
  if (/\b(me|my|i|player|human)\b/i.test(cleaned)) matchedActors.add('player');
  if (/\b(ai|bot|rival|opponent|computer)\b/i.test(cleaned)) matchedActors.add('ai');
  if (/\b(teammate|partner|ally|team|coop)\b/i.test(cleaned)) matchedActors.add('teammates');
  result.actors = Array.from(matchedActors);

  // Contracts (IDs or keywords)
  const contractIdMatches = cleaned.match(/\b(contract[-\s]?\d+|bounty[-\s]?\d+)\b/gi);
  if (contractIdMatches) {
    result.contractIds = contractIdMatches.map(c => c.toUpperCase().replace(/\s+/g, '-'));
  }

  // Infrastructure Types
  const infraKeywords = ['mine', 'port', 'rail', 'solar', 'water treatment', 'power grid', 'factory', 'infrastructure'];
  const matchedInfra = new Set<string>();
  for (const infra of infraKeywords) {
    if (new RegExp(`\\b${infra}\\b`, 'i').test(cleaned)) {
      matchedInfra.add(infra);
    }
  }
  result.infrastructureTypes = Array.from(matchedInfra);

  // Relics
  const relicKeywords = ['artifact', 'opal compass', 'relic', 'ancient relic'];
  const matchedRelics = new Set<string>();
  for (const relic of relicKeywords) {
    if (new RegExp(`\\b${relic}\\b`, 'i').test(cleaned)) {
      matchedRelics.add(relic);
    }
  }
  result.relicNames = Array.from(matchedRelics);

  // Settings Keywords
  const settingKeywords = ['ap cost', 'difficulty', 'ai personality', 'auto end turn', 'randomness', 'setting', 'config'];
  const matchedSettings = new Set<string>();
  for (const setKey of settingKeywords) {
    if (new RegExp(`\\b${setKey}\\b`, 'i').test(cleaned)) {
      matchedSettings.add(setKey);
    }
  }
  result.settingKeys = Array.from(matchedSettings);

  if (gameState) {
    if (gameState.activeRegion && result.regions.length === 0) {
      result.regions.push(gameState.activeRegion);
    }
  }
  if (playerState) {
    if (playerState.currentLocation && result.regions.length === 0) {
      result.regions.push(playerState.currentLocation);
    }
  }

  result.rawMatches = {
    regions: result.regions,
    resources: result.resources,
    actors: result.actors,
    contractIds: result.contractIds,
    infrastructureTypes: result.infrastructureTypes,
    relicNames: result.relicNames,
    settingKeys: result.settingKeys
  };

  return result;
}

/**
 * IntentClassifier: Classifies a query to AskGameIntent with confidence score (0.0 - 1.0) and fallback.
 */
export function classifyAskGameIntent(rawQuery: string | AskGameNormalizedQuery): AskGameClassificationResult {
  const norm = typeof rawQuery === 'string' ? parseAskGameNormalizedQuery(rawQuery) : rawQuery;
  const cleaned = norm.cleanedString;
  const tokens = norm.tokens;

  const scores: Array<{ intent: AskGameIntent; score: number; matchedKeywords: string[] }> = [];

  for (const [intentKey, metadata] of Object.entries(ASK_GAME_INTENT_REGISTRY) as Array<[AskGameIntent, AskGameIntentMetadata]>) {
    let rawScore = 0;
    const matched: string[] = [];

    // Check exact keyword / multi-word phrase matches using regex word boundaries \b
    for (const kw of metadata.keywords) {
      const kwLower = kw.toLowerCase();
      const escapedKw = kwLower.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      const kwRegex = new RegExp(`\\b${escapedKw}\\b`, 'i');

      if (kwRegex.test(cleaned)) {
        if (kwLower.includes(' ')) {
          rawScore += 0.60;
        } else {
          rawScore += 0.50;
        }
        matched.push(kw);
      }
    }

    // Intent specific regex boosters
    if (intentKey === 'AFFORDABILITY_CHECK' && /\b(can i afford|do i have enough|how much does)\b/i.test(cleaned)) {
      rawScore += 0.4;
    }
    if (intentKey === 'ACTION_RECOMMEND' && /\b(best move|what should i do|recommend|suggest)\b/i.test(cleaned)) {
      rawScore += 0.4;
    }
    if (intentKey === 'MARKET_PRICES' && /\b(price|cost of|buy rate|sell rate|market)\b/i.test(cleaned)) {
      rawScore += 0.3;
    }
    if (intentKey === 'CREDIT_LOAN_STATUS' && /\b(loan|credit|debt|interest)\b/i.test(cleaned)) {
      rawScore += 0.4;
    }
    if (intentKey === 'MEMORY_RECALL' && /\b(remember|memory of me|what do you remember)\b/i.test(cleaned)) {
      rawScore += 0.65;
    }
    if (intentKey === 'RIVAL_RECENT' && /\b(rival done recently|what has this rival|recent rival)\b/i.test(cleaned)) {
      rawScore += 0.6;
    }
    if (intentKey === 'RELATIONSHIP_EXPLAIN' && /\b(distrust|respect|relationship)\b/i.test(cleaned)) {
      rawScore += 0.55;
    }
    if (intentKey === 'STRATEGIC_PATTERN' && /\b(strategic pattern|observed pattern|tendencies)\b/i.test(cleaned)) {
      rawScore += 0.6;
    }
    if (intentKey === 'RIVAL_PREDICT' && /\b(predict|i predict|will the rival)\b/i.test(cleaned)) {
      rawScore += 0.6;
    }
    if (intentKey === 'PLAN_STATUS' && /\b(current plan|what is your plan|plan status)\b/i.test(cleaned)) {
      rawScore += 0.55;
    }
    if (intentKey === 'PLAN_CHANGE' && /\b(what changed|changed since|why did you change)\b/i.test(cleaned)) {
      rawScore += 0.55;
    }
    if (intentKey === 'DECISION_MEMORY' && /\b(why did you choose|memories influenced|latest decision)\b/i.test(cleaned)) {
      rawScore += 0.6;
    }
    if (intentKey === 'PLAYSTYLE_LEARNED' && /\b(playstyle|learned about my)\b/i.test(cleaned)) {
      rawScore += 0.6;
    }
    if (intentKey === 'TEAM_PLAN_UPDATE' && /\b(help me win|focus on defending|team plan|keep enough money)\b/i.test(cleaned)) {
      rawScore += 0.7;
    }
    if (intentKey === 'NEXT_STEP' && /\bwhat should we do\b/i.test(cleaned)) {
      rawScore += 0.7;
    }
    if (intentKey === 'WHY_REGION' && /\bwhy is\b/i.test(cleaned) && /\b(qld|nsw|vic|sa|wa|nt|tas|victoria|queensland)\b/i.test(cleaned)) {
      rawScore += 0.55;
    }
    if (intentKey === 'CURRENT_PLAN' && /\bwhat is your current plan\b/i.test(cleaned)) {
      rawScore += 0.65;
    }
    // V9 Game Intelligence phrasing boosters: common natural questions that previously fell through
    // to GENERAL_HELP. They only steer to an existing grounded intent and its existing tools.
    if (intentKey === 'ECONOMY_DIAGNOSE' && (/\b(hurting|wrong with|problem with|problems with|draining|diagnose)\b.*\b(economy|finances|money|cash|income)\b/i.test(cleaned) || /\b(economy|finances)\b.*\b(hurting|problem|wrong|struggling)\b/i.test(cleaned))) {
      rawScore += 0.6;
    }
    if (intentKey === 'AI_BEHAVIOR_EXPLAIN' && (/\bwhy did (the )?(ai|rival|opponent|bot)\b/i.test(cleaned) || /\b(opponent|rival)\b.*\b(threaten|threatening|threat|planning|up to)\b/i.test(cleaned))) {
      rawScore += 0.6;
    }
    if (intentKey === 'SETTINGS_INSPECT' && (/\b(which|what) setting\b/i.test(cleaned) || /\bsetting\b.*\b(blocking|controlling|controls|prevents|preventing)\b/i.test(cleaned) || /\bopen the setting\b/i.test(cleaned))) {
      rawScore += 0.6;
    }

    // Normalize confidence between 0.0 and 1.0
    const confidence = Math.min(1.0, Math.max(0.0, rawScore));

    scores.push({
      intent: intentKey,
      score: confidence,
      matchedKeywords: matched
    });
  }

  // Sort descending by score
  scores.sort((a, b) => b.score - a.score);

  const topMatch = scores[0];
  const FALLBACK_THRESHOLD = 0.25;

  if (!topMatch || topMatch.score < FALLBACK_THRESHOLD) {
    return {
      intent: 'GENERAL_HELP',
      confidence: topMatch ? Number(topMatch.score.toFixed(2)) : 0.0,
      matchedKeywords: topMatch ? topMatch.matchedKeywords : [],
      secondaryIntents: scores.slice(0, 3).map(s => ({ intent: s.intent, confidence: Number(s.score.toFixed(2)) })),
      fallback: true
    };
  }

  return {
    intent: topMatch.intent,
    confidence: Number(topMatch.score.toFixed(2)),
    matchedKeywords: topMatch.matchedKeywords,
    secondaryIntents: scores.slice(1, 4).map(s => ({ intent: s.intent, confidence: Number(s.score.toFixed(2)) })),
    fallback: false
  };
}

