// ============================================================================
// SECTION 10: GOVERNANCE, APPROVALS, AND OVERSIGHT
// ============================================================================
export function computeGuardianRiskDeduplicationKey(
  riskCategory: GuardianRiskCategory,
  actionType: string,
  actorId: string
): string {
  return `${actorId}:${actionType}:${riskCategory}`;
}

export function shouldSuppressGuardianWarning(
  dedupKey: string,
  state: Record<string, unknown> | undefined | null,
  settings: GuardianAiSettings,
  currentTurn: number,
  currentTimestamp: number = Date.now()
): boolean {
  if (!state || !state.guardianWarningHistory || !settings.deduplication) return false;
  const historyMap = state.guardianWarningHistory as Record<string, GuardianWarningDeduplicationRecord>;
  const record = historyMap[dedupKey];
  if (!record) return false;

  const turnsPassed = currentTurn - record.turn;
  const secondsPassed = (currentTimestamp - record.timestamp) / 1000;

  const cooldownTurns = settings.deduplication.cooldownTurns ?? 1;
  const cooldownSeconds = settings.deduplication.cooldownSeconds ?? 30;

  if (turnsPassed < cooldownTurns && secondsPassed < cooldownSeconds) {
    return true;
  }

  return false;
}

export function recordGuardianWarningFired(
  dedupKey: string,
  state: Record<string, unknown>,
  turn: number,
  timestamp: number = Date.now()
): Record<string, unknown> {
  const existingHistory = { ...((state.guardianWarningHistory || {}) as Record<string, GuardianWarningDeduplicationRecord>) };
  existingHistory[dedupKey] = {
    riskKey: dedupKey,
    turn,
    timestamp,
  };

  const keys = Object.keys(existingHistory);
  const maxHistory = 100;
  if (keys.length > maxHistory) {
    const entries = Object.values(existingHistory).sort((a, b) => a.timestamp - b.timestamp);
    const toRemove = entries.slice(0, keys.length - maxHistory);
    for (const entry of toRemove) {
      delete existingHistory[entry.riskKey];
    }
  }

  return {
    ...state,
    guardianWarningHistory: existingHistory,
  };
}

// ----------------------------------------------------------------------------
// 3. False-Positive Feedback Loop Helpers (Req #30)
// ----------------------------------------------------------------------------

export function recordGuardianFalsePositiveFeedback(
  state: Record<string, unknown>,
  category: GuardianRiskCategory,
  actionType: string,
  timestamp: number = Date.now()
): Record<string, unknown> {
  const logs = Array.isArray(state.guardianFalsePositiveFeedbackLogs)
    ? [...(state.guardianFalsePositiveFeedbackLogs as readonly GuardianFalsePositiveFeedback[])]
    : [];
  const key = `${category}:${actionType}`;
  const idx = logs.findIndex((item) => `${item.category}:${item.actionType}` === key);

  if (idx >= 0) {
    logs[idx] = {
      ...logs[idx],
      count: logs[idx].count + 1,
      lastFeedbackTimestamp: timestamp,
    };
  } else {
    logs.push({
      feedbackId: `fp_${key}_${timestamp}`,
      category,
      actionType,
      count: 1,
      lastFeedbackTimestamp: timestamp,
    });
  }

  return {
    ...state,
    guardianFalsePositiveFeedbackLogs: logs,
  };
}

export function getGuardianFalsePositiveSensitivityAdjustment(
  state: Record<string, unknown> | undefined | null,
  category: GuardianRiskCategory,
  actionType: string
): number {
  if (!state || !Array.isArray(state.guardianFalsePositiveFeedbackLogs)) return 1.0;
  const logs = state.guardianFalsePositiveFeedbackLogs as readonly GuardianFalsePositiveFeedback[];
  const entry = logs.find((item) => item.category === category && item.actionType === actionType);
  if (!entry) return 1.0;

  if (entry.count >= 5) return 0.0;
  if (entry.count >= 3) return 0.3;
  if (entry.count >= 1) return 0.6;
  return 1.0;
}

// ----------------------------------------------------------------------------
// 8. Deep-Linked Notifications Integration Helper (Req #36)
// ----------------------------------------------------------------------------

export function dispatchGuardianNotification(
  state: Record<string, unknown> | undefined | null,
  addNotificationFn?: (notif: Notification) => void,
  risk?: GuardianDetectedRisk,
  evaluationResult?: GuardianEvaluationResult,
  deepLink?: GuardianNotificationDeepLink
): Notification {
  const notifId = `notif_g_${risk?.id || evaluationResult?.evaluationId || Date.now()}`;
  const day = typeof state?.day === 'number' ? state.day : 1;
  const notification: Notification = {
    id: notifId,
    type: 'warning',
    notificationType: 'warning' as NotificationType,
    message: risk ? `[Guardian AI] ${risk.title}: ${risk.description}` : (evaluationResult?.summary || 'Guardian AI Safety Notice'),
    timestamp: Date.now(),
    day,
    read: false,
    persistent: risk?.severity === 'critical',
    guardianRiskId: risk?.id,
    guardianEvaluationId: evaluationResult?.evaluationId,
    ledgerEventId: `evt_${notifId}`,
    ...(deepLink ? (deepLink as unknown as Record<string, unknown>) : {}),
  };

  if (addNotificationFn) {
    addNotificationFn(notification);
  }

  return notification;
}

// ----------------------------------------------------------------------------
// 9. Activity Ledger Integration Helper (Req #37)
// ----------------------------------------------------------------------------

export function dispatchGuardianLedgerEvent(
  state: Record<string, unknown>,
  eventType: string,
  evaluationResult: GuardianEvaluationResult,
  action?: Record<string, unknown>,
  token?: GuardianConfirmationToken
): Record<string, unknown> {
  if (!state) return state;

  const severity: GameActivityLedgerSeverity =
    evaluationResult.highestSeverity === 'critical'
      ? 'critical'
      : evaluationResult.highestSeverity === 'serious'
      ? 'warning'
      : 'info';

  const summary = `[Guardian AI] Event '${eventType}' for actor '${evaluationResult.actorId}': ${evaluationResult.summary}`;

  const ledgerEvent = createGameActivityLedgerEvent(
    'guardian_event' as GameActivityLedgerEventCategory,
    summary,
    {
      actorId: evaluationResult.actorId,
      eventType: `GUARDIAN_${eventType.toUpperCase()}`,
      severity,
      payload: {
        eventType,
        evaluationId: evaluationResult.evaluationId,
        actorId: evaluationResult.actorId,
        actionType: evaluationResult.actionType,
        highestSeverity: evaluationResult.highestSeverity,
        risksCount: evaluationResult.risks.length,
        allowedToProceed: evaluationResult.allowedToProceed,
        confirmationRequired: evaluationResult.confirmationRequired,
        tokenId: token?.id,
        action,
        failureMode: evaluationResult.failureMode,
      },
    }
  );

  const targetState = state as unknown as { gameActivityLedger?: GameActivityLedgerState; eventLogs?: GameActivityLedgerEvent[] };
  if (!targetState.gameActivityLedger) {
    targetState.gameActivityLedger = createDefaultGameActivityLedgerState();
  }
  if (!Array.isArray(targetState.gameActivityLedger.events)) {
    targetState.gameActivityLedger.events = [];
  }
  targetState.gameActivityLedger.events.unshift(ledgerEvent);
  if (targetState.gameActivityLedger.events.length > 500) {
    targetState.gameActivityLedger.events.pop();
  }
  targetState.eventLogs = targetState.gameActivityLedger.events;

  return state;
}

// ----------------------------------------------------------------------------
// 10. Replay Integration Helpers (Req #38)
// ----------------------------------------------------------------------------

export function recordGuardianReplayEvent(
  state: Record<string, unknown>,
  event: GuardianReplayEvent
): Record<string, unknown> {
  if (!state) return state;
  const existing = Array.isArray(state.guardianReplayEvents)
    ? [...(state.guardianReplayEvents as readonly GuardianReplayEvent[])]
    : [];
  existing.push(event);
  if (existing.length > 500) {
    existing.shift();
  }
  return {
    ...state,
    guardianReplayEvents: existing,
  };
}

export function verifyGuardianReplayEventDeterminism(
  recordedEvent: GuardianReplayEvent,
  replayedEvent: GuardianReplayEvent
): { deterministic: boolean; discrepancies: readonly string[] } {
  const discrepancies: string[] = [];

  if (recordedEvent.evaluationId !== replayedEvent.evaluationId) {
    discrepancies.push(`evaluationId mismatch: recorded '${recordedEvent.evaluationId}', replayed '${replayedEvent.evaluationId}'`);
  }
  if (recordedEvent.actorId !== replayedEvent.actorId) {
    discrepancies.push(`actorId mismatch: recorded '${recordedEvent.actorId}', replayed '${replayedEvent.actorId}'`);
  }
  if (recordedEvent.actionType !== replayedEvent.actionType) {
    discrepancies.push(`actionType mismatch: recorded '${recordedEvent.actionType}', replayed '${replayedEvent.actionType}'`);
  }
  if (recordedEvent.day !== replayedEvent.day) {
    discrepancies.push(`day mismatch: recorded '${recordedEvent.day}', replayed '${replayedEvent.day}'`);
  }
  if (recordedEvent.turn !== replayedEvent.turn) {
    discrepancies.push(`turn mismatch: recorded '${recordedEvent.turn}', replayed '${replayedEvent.turn}'`);
  }
  if (recordedEvent.highestSeverity !== replayedEvent.highestSeverity) {
    discrepancies.push(`highestSeverity mismatch: recorded '${recordedEvent.highestSeverity}', replayed '${replayedEvent.highestSeverity}'`);
  }
  if (recordedEvent.decisionTaken !== replayedEvent.decisionTaken) {
    discrepancies.push(`decisionTaken mismatch: recorded '${recordedEvent.decisionTaken}', replayed '${replayedEvent.decisionTaken}'`);
  }
  if (recordedEvent.stateHashBefore !== replayedEvent.stateHashBefore) {
    discrepancies.push(`stateHashBefore mismatch: recorded '${recordedEvent.stateHashBefore}', replayed '${replayedEvent.stateHashBefore}'`);
  }
  if (recordedEvent.stateHashAfter !== replayedEvent.stateHashAfter) {
    discrepancies.push(`stateHashAfter mismatch: recorded '${recordedEvent.stateHashAfter}', replayed '${replayedEvent.stateHashAfter}'`);
  }

  const recCats = (recordedEvent.detectedRiskCategories || []).slice().sort().join(',');
  const repCats = (replayedEvent.detectedRiskCategories || []).slice().sort().join(',');
  if (recCats !== repCats) {
    discrepancies.push(`detectedRiskCategories mismatch: recorded [${recCats}], replayed [${repCats}]`);
  }

  return {
    deterministic: discrepancies.length === 0,
    discrepancies,
  };
}

// ----------------------------------------------------------------------------
// 11. Failure Safety GuardianFailureMode Helper (Req #42)
// ----------------------------------------------------------------------------

export function safeExecuteGuardianEvaluator(
  evaluatorFn: () => readonly GuardianDetectedRisk[],
  context: GuardianEvaluationContext,
  evaluatorId: string,
  fallbackBehavior: 'allow_with_warning' | 'allow_silent' | 'block_safety' = 'allow_with_warning'
): { risks: readonly GuardianDetectedRisk[]; failureMode?: GuardianFailureMode } {
  try {
    const risks = evaluatorFn();
    return { risks };
  } catch (err: unknown) {
    const errorMessage = err instanceof Error ? err.message : String(err);
    const errorName = err instanceof Error ? err.name : 'GuardianEvaluatorError';
    const evaluatorName = evaluatorId;
    const failureMode: GuardianFailureMode = {
      failed: true,
      errorName,
      errorMessage,
      fallbackBehavior,
      timestamp: Date.now(),
      evaluatorId,
      evaluatorName,
    };

    console.warn(`[Guardian AI Safety Boundary] Evaluator '${evaluatorId}' failed safely: ${errorMessage}`);

    let fallbackRisks: GuardianDetectedRisk[] = [];
    if (fallbackBehavior === 'block_safety') {
      fallbackRisks = [{
        id: `risk_fallback_${evaluatorName}_${Date.now()}`,
        category: 'rule_conflict',
        severity: 'critical',
        title: `Guardian AI Evaluator Error (${evaluatorName})`,
        description: `Evaluator '${evaluatorName}' threw an exception: ${errorMessage}. Action blocked under block_safety mode.`,
        evidence: [errorMessage],
        assumptions: [],
        probability: 1.0,
        estimatedImpact: 1.0,
        confidence: 1.0,
        reversible: true,
        immediate: true,
        triggeredSettingKeys: [],
        systemIds: ['guardian_ai'],
      }];
    } else if (fallbackBehavior === 'allow_with_warning') {
      fallbackRisks = [{
        id: `risk_fallback_${evaluatorName}_${Date.now()}`,
        category: 'system_error',
        severity: 'caution',
        title: `Guardian AI Evaluator Warning (${evaluatorName})`,
        description: `Evaluator '${evaluatorName}' threw an exception: ${errorMessage}. Action permitted with warning.`,
        evidence: [errorMessage],
        assumptions: [],
        probability: 0.5,
        estimatedImpact: 0.5,
        confidence: 0.5,
        reversible: true,
        immediate: true,
        triggeredSettingKeys: [],
        systemIds: ['guardian_ai'],
      }];
    }

    return { risks: fallbackRisks, failureMode };
  }
}

// =========================================
// CONFIRMATION TOKEN ENGINE
// =========================================

function normalizeValue(
  val: unknown,
  seenAncestors: Set<object>
): unknown {
  if (val === undefined || typeof val === 'function' || typeof val === 'symbol') {
    return undefined;
  }
  if (val === null || typeof val !== 'object') {
    return val;
  }
  if (seenAncestors.has(val as object)) {
    return '[Circular]';
  }
  seenAncestors.add(val as object);
  try {
    if (Array.isArray(val)) {
      return val.map(item => {
        const norm = normalizeValue(item, seenAncestors);
        return norm === undefined ? null : norm;
      });
    }
    const obj = val as Record<string, unknown>;
    const keys = Object.keys(obj).sort();
    const normalized: Record<string, unknown> = {};
    for (const k of keys) {
      const v = obj[k];
      const normV = normalizeValue(v, seenAncestors);
      if (normV !== undefined) {
        normalized[k] = normV;
      }
    }
    return normalized;
  } finally {
    seenAncestors.delete(val as object);
  }
}

export function normalizePayloadString(
  payload: Record<string, unknown> | undefined,
  seenAncestorsParam?: WeakSet<object> | Set<object>
): string {
  if (!payload || typeof payload !== 'object' || payload === null) return '{}';
  const seenAncestors = new Set<object>();
  try {
    const normalized = normalizeValue(payload, seenAncestors);
    if (typeof normalized === 'string') return normalized;
    return JSON.stringify(normalized ?? {});
  } catch {
    return '{}';
  }
}


export function computeDeterministicHash(input: string): string {
  let hash = 0x811c9dc5;
  for (let i = 0; i < input.length; i++) {
    hash ^= input.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
}

export function hashNormalizedPayload(payload: Record<string, unknown> | undefined): string {
  return computeDeterministicHash(normalizePayloadString(payload));
}

export function computeStateHash(state: {
  day: number;
  turn: number;
  actorId?: string;
  currentCash?: number;
  currentActionTokens?: number;
}): string {
  const summary = `${state.day}_${state.turn}_${state.actorId ?? 'anon'}_${state.currentCash ?? 0}_${state.currentActionTokens ?? 0}`;
  return computeDeterministicHash(summary);
}

export function createGuardianConfirmationToken(params: {
  evaluationId: string;
  actorId: string;
  actionType: string;
  payload: Record<string, unknown> | undefined;
  state: { day: number; turn: number; actorId?: string; currentCash?: number; currentActionTokens?: number };
  createdTurn: number;
  ttlTurns?: number;
}): GuardianConfirmationToken {
  const normalizedPayloadHash = hashNormalizedPayload(params.payload);
  const stateHash = computeStateHash(params.state);
  const ttl = params.ttlTurns ?? 1;
  const tokenId = `gct_${params.evaluationId}_${params.createdTurn}_${computeDeterministicHash(params.actorId + params.actionType)}`;

  return {
    id: tokenId,
    evaluationId: params.evaluationId,
    actorId: params.actorId,
    actionType: params.actionType,
    normalizedPayloadHash,
    stateHash,
    createdTurn: params.createdTurn,
    expiresTurn: params.createdTurn + ttl,
    consumed: false,
  };
}

export interface GuardianTokenValidationResult {
  readonly valid: boolean;
  readonly code?: 'MISSING_TOKEN' | 'ALREADY_CONSUMED' | 'ACTOR_MISMATCH' | 'ACTION_MISMATCH' | 'PAYLOAD_HASH_MISMATCH' | 'STATE_DRIFT' | 'EXPIRED';
  readonly reason?: string;
}

export const CONSUMED_GUARDIAN_TOKENS = new Set<string>();

export function clearConsumedGuardianTokens(): void {
  CONSUMED_GUARDIAN_TOKENS.clear();
}

export function validateGuardianConfirmationToken(params: {
  token: GuardianConfirmationToken | null | undefined;
  currentActorId: string;
  currentActionType: string;
  currentPayload: Record<string, unknown> | undefined;
  currentState: { day: number; turn: number; actorId?: string; currentCash?: number; currentActionTokens?: number };
  currentTurn: number;
}): GuardianTokenValidationResult {
  const { token, currentActorId, currentActionType, currentPayload, currentState, currentTurn } = params;

  if (!token) {
    return { valid: false, code: 'MISSING_TOKEN', reason: 'No confirmation token provided for action execution.' };
  }

  if (token.consumed || (token.id && CONSUMED_GUARDIAN_TOKENS.has(token.id))) {
    return { valid: false, code: 'ALREADY_CONSUMED', reason: 'Confirmation token has already been consumed.' };
  }

  if (token.actorId !== currentActorId) {
    return { valid: false, code: 'ACTOR_MISMATCH', reason: `Actor mismatch: token issued for ${token.actorId}, requested by ${currentActorId}.` };
  }

  if (token.actionType !== currentActionType) {
    return { valid: false, code: 'ACTION_MISMATCH', reason: `Action type mismatch: token issued for ${token.actionType}, requested ${currentActionType}.` };
  }

  const currentPayloadHash = hashNormalizedPayload(currentPayload);
  if (token.normalizedPayloadHash !== currentPayloadHash) {
    return { valid: false, code: 'PAYLOAD_HASH_MISMATCH', reason: 'Payload modified after warning confirmation.' };
  }

  const currentStateHash = computeStateHash(currentState);
  if (token.stateHash !== currentStateHash) {
    return { valid: false, code: 'STATE_DRIFT', reason: 'Game state drift detected since token issuance.' };
  }

  if (currentTurn < token.createdTurn) {
    return { valid: false, code: 'EXPIRED', reason: `Confirmation token created on future turn ${token.createdTurn} (current: ${currentTurn}).` };
  }

  if (currentTurn > token.expiresTurn) {
    return { valid: false, code: 'EXPIRED', reason: `Confirmation token expired on turn ${token.expiresTurn} (current: ${currentTurn}).` };
  }

  return { valid: true };
}

export function consumeGuardianConfirmationToken(token: GuardianConfirmationToken): GuardianConfirmationToken {
  if (token) {
    (token as any).consumed = true;
    if (token.id) {
      CONSUMED_GUARDIAN_TOKENS.add(token.id);
    }
  }
  return token;
}

