// ----------------------------------------------------------------------------
// DEFENSIVE STATE EXTRACTOR HELPERS (ZERO BROAD ANY)
// ----------------------------------------------------------------------------

function extractActorState(context: GuardianEvaluationContext): Record<string, unknown> | null {
  const gs = context.gameState as Record<string, unknown>;
  if (!gs || typeof gs !== 'object') return null;

  const actorMap = gs.actorsById as Record<string, Record<string, unknown>> | undefined;
  if (actorMap && actorMap[context.actorId]) {
    return actorMap[context.actorId];
  }

  if (context.actorId === 'player' && gs.player && typeof gs.player === 'object') {
    return gs.player as Record<string, unknown>;
  }

  if (context.actorId === 'ai' && gs.aiPlayer && typeof gs.aiPlayer === 'object') {
    return gs.aiPlayer as Record<string, unknown>;
  }

  if (gs.player && typeof gs.player === 'object') {
    return gs.player as Record<string, unknown>;
  }

  return null;
}

function extractActorDebt(actor: Record<string, unknown> | null): {
  simpleLoansDebt: number;
  advLoansDebt: number;
  totalDebt: number;
  dailyLoanInterest: number;
} {
  if (!actor) {
    return { simpleLoansDebt: 0, advLoansDebt: 0, totalDebt: 0, dailyLoanInterest: 0 };
  }

  const loans = Array.isArray(actor.loans) ? actor.loans : [];
  const advLoans = Array.isArray(actor.advancedLoans) ? actor.advancedLoans : [];

  let simpleLoansDebt = 0;
  loans.forEach((l: unknown) => {
    if (l && typeof l === 'object') {
      const loanObj = l as Record<string, unknown>;
      const amount = typeof loanObj.amount === 'number' ? loanObj.amount : 0;
      const accrued = typeof loanObj.accrued === 'number' ? loanObj.accrued : 0;
      simpleLoansDebt += amount + accrued;
    }
  });

  let advLoansDebt = 0;
  advLoans.forEach((l: unknown) => {
    if (l && typeof l === 'object') {
      const loanObj = l as Record<string, unknown>;
      const amount = typeof loanObj.amount === 'number' ? loanObj.amount : 0;
      const accruedInterest = typeof loanObj.accruedInterest === 'number' ? loanObj.accruedInterest : 0;
      advLoansDebt += amount + accruedInterest;
    }
  });

  const totalDebt = simpleLoansDebt + advLoansDebt;
  const dailyLoanInterest = simpleLoansDebt * 0.05 + advLoansDebt * 0.08;

  return { simpleLoansDebt, advLoansDebt, totalDebt, dailyLoanInterest };
}

function extractActorSupplies(actor: Record<string, unknown> | null): {
  currentSupplies: number;
  maxSupplies: number;
  ratio: number;
} {
  if (!actor) return { currentSupplies: 100, maxSupplies: 100, ratio: 1.0 };
  const currentSupplies = typeof actor.currentSupplies === 'number' ? actor.currentSupplies : 100;
  const maxSupplies = typeof actor.maxSupplies === 'number' ? actor.maxSupplies : 100;
  const ratio = maxSupplies > 0 ? currentSupplies / maxSupplies : 1.0;
  return { currentSupplies, maxSupplies, ratio };
}

function extractActorCondition(actor: Record<string, unknown> | null): 'healthy' | 'strained' | 'critical' {
  if (!actor) return 'healthy';
  const cond = typeof actor.condition === 'string' ? actor.condition : 'healthy';
  if (cond === 'critical') return 'critical';
  if (cond === 'strained') return 'strained';
  return 'healthy';
}

function extractActorInventory(actor: Record<string, unknown> | null): readonly string[] {
  if (!actor || !Array.isArray(actor.inventory)) return [];
  return actor.inventory.filter((item): item is string => typeof item === 'string');
}

function extractActorEquipment(actor: Record<string, unknown> | null): readonly string[] {
  if (!actor || !Array.isArray(actor.equipment)) return [];
  return actor.equipment.filter((item): item is string => typeof item === 'string');
}

// ----------------------------------------------------------------------------
// 1. MAJOR COMMITMENT CLASSIFIER (Req #13)
// ----------------------------------------------------------------------------

export function classifyGuardianCommitment(
  actionType: string,
  actionPayload: Record<string, unknown> | undefined,
  context: GuardianEvaluationContext
): GuardianCommitmentClassification {
  const normAction = (actionType || '').toLowerCase().trim();
  const payload = actionPayload || {};
  const currentCash = context.currentCash;

  let isMajorCommitment = false;
  let commitmentType: GuardianCommitmentType = 'none';
  let financialCommitmentAmount = 0;
  let turnDuration = 1;
  let lockedResources: readonly string[] = [];
  let isIrreversible = false;
  let riskLevel: GuardianRiskSeverity = 'informational';
  let summary = 'Standard routine action without major commitment.';

  if (['contract_accept', 'accept_regional_contract', 'accept_contract', 'contract_sign'].includes(normAction)) {
    isMajorCommitment = true;
    commitmentType = 'contract_sign';
    financialCommitmentAmount = typeof payload.deposit === 'number' ? payload.deposit : 0;
    turnDuration = typeof payload.durationTurns === 'number' ? payload.durationTurns : 5;
    if (Array.isArray(payload.requiredResources)) {
      lockedResources = payload.requiredResources.filter((r): r is string => typeof r === 'string');
    }
    isIrreversible = true;
    riskLevel = 'serious';
    summary = 'Accepting a regional contract binds resources and subjects actor to default penalties upon failure.';
  } else if (['sell_resources', 'sell'].includes(normAction)) {
    const resName = typeof payload.resource === 'string' ? payload.resource : typeof payload.resourceType === 'string' ? payload.resourceType : '';
    if (resName && context.activeContracts.length > 0) {
      isMajorCommitment = true;
      commitmentType = 'contract_resource_sale';
      lockedResources = [resName];
      riskLevel = 'critical';
      summary = `Selling '${resName}' risks breaching active contract fulfillment requirements.`;
    }
  } else if (['infrastructure_project', 'start_infrastructure_project', 'startinfrastructure', 'upgrade_regional_dev_level', 'infrastructure_build'].includes(normAction)) {
    isMajorCommitment = true;
    commitmentType = 'infrastructure_build';
    financialCommitmentAmount = typeof payload.cost === 'number' ? payload.cost : typeof payload.investmentAmount === 'number' ? payload.investmentAmount : 3000;
    isIrreversible = true;
    riskLevel = 'serious';
    summary = 'Constructing regional infrastructure commits major cash and increases recurring upkeep.';
  } else if (['expedition_begin', 'launch_expedition', 'launchexpedition', 'expedition_launch'].includes(normAction)) {
    isMajorCommitment = true;
    commitmentType = 'expedition_launch';
    financialCommitmentAmount = typeof payload.prepCost === 'number' ? payload.prepCost : 3000;
    turnDuration = typeof payload.durationTurns === 'number' ? payload.durationTurns : 3;
    isIrreversible = true;
    riskLevel = 'critical';
    summary = 'Launching an expedition locks supplies, health, and multi-turn movement trajectory.';
  } else if (['take_advanced_loan', 'loan', 'loan_take', 'borrow'].includes(normAction)) {
    isMajorCommitment = true;
    commitmentType = 'loan_take';
    financialCommitmentAmount = typeof payload.amount === 'number' ? payload.amount : 5000;
    riskLevel = 'serious';
    summary = 'Taking a loan increases immediate debt liabilities and recurring daily interest.';
  } else if (normAction === 'travel' && (typeof payload.travelDays === 'number' && payload.travelDays > 1 || context.currentActionTokens === 1)) {
    isMajorCommitment = true;
    commitmentType = 'multi_turn_lock';
    turnDuration = typeof payload.travelDays === 'number' ? payload.travelDays : 2;
    riskLevel = 'caution';
    summary = 'Multi-turn travel locks actor location and prevents region-bound operations.';
  } else if (typeof payload.cost === 'number' && payload.cost > 2000 || typeof payload.amount === 'number' && payload.amount > Math.max(1000, currentCash * 0.3)) {
    isMajorCommitment = true;
    commitmentType = 'large_expenditure';
    financialCommitmentAmount = typeof payload.cost === 'number' ? payload.cost : Number(payload.amount);
    riskLevel = 'caution';
    summary = 'Large cash expenditure significantly draws down liquid cash reserves.';
  } else if (normAction === 'end_turn' || context.currentActionTokens === 1) {
    isMajorCommitment = context.currentActionTokens === 1;
    commitmentType = 'final_action_token';
    riskLevel = 'caution';
    summary = 'Final action point of the turn; no remaining AP after execution.';
  } else if (['vote', 'propose_law', 'governance_approval', 'governance_vote'].includes(normAction)) {
    isMajorCommitment = true;
    commitmentType = 'governance_vote';
    riskLevel = 'caution';
    summary = 'Governance action commits team stance on legislation.';
  } else if (normAction === 'scenario_choice') {
    isMajorCommitment = true;
    commitmentType = 'scenario_choice';
    isIrreversible = true;
    riskLevel = 'serious';
    summary = 'Scenario choice permanently alters narrative branches and strategic posture.';
  }

  return {
    isMajorCommitment,
    commitmentType,
    financialCommitmentAmount,
    turnDuration,
    lockedResources,
    isIrreversible,
    riskLevel,
    summary,
  };
}

