// 2. DOMAIN RISK EVALUATORS (Reqs #14–#22, #31)
// ----------------------------------------------------------------------------

/**
 * Requirement #14: Bankruptcy & Liquidity Evaluator
 */
export function evaluateBankruptcyLiquidityRisk(
  context: GuardianEvaluationContext
): readonly GuardianDetectedRisk[] {
  const risks: GuardianDetectedRisk[] = [];
  const actor = extractActorState(context);
  const currentCash = context.currentCash;
  const debtInfo = extractActorDebt(actor);

  const payload = context.actionPayload || {};
  let actionCost = 0;
  if (typeof payload.cost === 'number') actionCost = payload.cost;
  else if (typeof payload.amount === 'number' && context.actionType !== 'take_advanced_loan' && context.actionType !== 'loan') {
    actionCost = payload.amount;
  } else if (typeof payload.price === 'number') actionCost = payload.price;

  const postActionCash = currentCash - actionCost;

  // 1-turn mandatory obligations
  const dailyMaintenance = typeof actor?.maintenanceCost === 'number' ? actor.maintenanceCost : (typeof actor?.dailyMaintenance === 'number' ? actor.dailyMaintenance : 0);
  const mandatoryObligations1Turn = dailyMaintenance + debtInfo.dailyLoanInterest;

  // Rule 1: Imminent Bankruptcy Risk
  if (actionCost > 0 && postActionCash < mandatoryObligations1Turn) {
    risks.push({
      id: `risk_bankruptcy_${context.actorId}_t${context.turn}_${context.actionType}`,
      category: 'bankruptcy',
      severity: 'critical',
      title: 'Imminent Bankruptcy Threat',
      description: 'Executing this action reduces liquid cash reserves below mandatory 1-turn maintenance and debt interest servicing requirements.',
      evidence: [
        `Current cash: ${Math.round(currentCash)}`,
        `Action cost: ${Math.round(actionCost)}`,
        `Post-action cash: ${Math.round(postActionCash)}`,
        `1-turn mandatory obligations: ${Math.round(mandatoryObligations1Turn)} (Upkeep: ${dailyMaintenance}, Debt Interest: ${Math.round(debtInfo.dailyLoanInterest)})`,
      ],
      assumptions: ['Turn end will deduct mandatory daily maintenance and debt interest.'],
      probability: 0.95,
      estimatedImpact: mandatoryObligations1Turn - postActionCash,
      confidence: 0.95,
      reversible: false,
      immediate: true,
      triggeredSettingKeys: ['evaluators.bankruptcy'],
      systemIds: ['economy', 'banking'],
    });
  }

  // Rule 2: Severe Liquidity Margin Breach (2-turn reserve)
  const mandatoryObligations2Turn = mandatoryObligations1Turn * 2;
  if (postActionCash >= mandatoryObligations1Turn && postActionCash < mandatoryObligations2Turn) {
    risks.push({
      id: `risk_liquidity_${context.actorId}_t${context.turn}_${context.actionType}`,
      category: 'liquidity',
      severity: 'serious',
      title: 'Liquidity Reserve Deficit',
      description: 'Post-action cash provides less than 2 turns of mandatory operating expenses, leaving zero buffer against unexpected events.',
      evidence: [
        `Post-action cash: ${Math.round(postActionCash)}`,
        `2-turn reserve threshold: ${Math.round(mandatoryObligations2Turn)}`,
      ],
      assumptions: ['Operating expenses remain constant over the next 2 turns.'],
      probability: 0.75,
      estimatedImpact: mandatoryObligations2Turn - postActionCash,
      confidence: 0.85,
      reversible: true,
      immediate: false,
      triggeredSettingKeys: ['evaluators.liquidity'],
      systemIds: ['economy'],
    });
  }

  // Rule 3: Excessive Debt Burden on New Borrowing
  if (['take_advanced_loan', 'loan', 'borrow'].includes(context.actionType.toLowerCase())) {
    const borrowAmount = typeof payload.amount === 'number' ? payload.amount : 5000;
    const postBorrowDebt = debtInfo.totalDebt + borrowAmount;
    const netWorth = typeof actor?.netWorth === 'number' ? actor.netWorth : Math.max(1000, currentCash);
    const debtRatio = postBorrowDebt / Math.max(1, netWorth);

    const limit = context.settings.thresholds?.debtToEquityRatioLimit ?? 2.5;
    if (debtRatio > limit) {
      risks.push({
        id: `risk_debt_${context.actorId}_t${context.turn}`,
        category: 'debt',
        severity: 'serious',
        title: 'Excessive Debt-to-Equity Ratio',
        description: `Taking this loan increases total debt (${Math.round(postBorrowDebt)}) to ${debtRatio.toFixed(2)}x net worth, exceeding safe limit (${limit}x).`,
        evidence: [
          `Post-borrow total debt: ${Math.round(postBorrowDebt)}`,
          `Net worth: ${Math.round(netWorth)}`,
          `Debt ratio: ${debtRatio.toFixed(2)}x (Threshold: ${limit}x)`,
        ],
        assumptions: ['Interest rate remains fixed.'],
        probability: 0.80,
        estimatedImpact: borrowAmount * 0.08 * 5,
        confidence: 0.90,
        reversible: false,
        immediate: false,
        triggeredSettingKeys: ['evaluators.debt', 'thresholds.debtToEquityRatioLimit'],
        systemIds: ['banking'],
      });
    }
  }

  // Rule 4: Protected Cash Reserve Breach
  const protectedCash = typeof actor?.protectedCash === 'number' ? actor.protectedCash : 0;
  if (protectedCash > 0 && postActionCash < protectedCash) {
    risks.push({
      id: `risk_cash_reserve_${context.actorId}_t${context.turn}`,
      category: 'cash_reserve',
      severity: 'caution',
      title: 'Protected Cash Reserve Intrusion',
      description: `Action spends cash designated as protected reserve (${protectedCash}).`,
      evidence: [
        `Post-action cash: ${Math.round(postActionCash)}`,
        `Protected cash limit: ${protectedCash}`,
      ],
      assumptions: ['Protected cash was set for emergency contingency.'],
      probability: 0.60,
      estimatedImpact: protectedCash - postActionCash,
      confidence: 0.80,
      reversible: true,
      immediate: true,
      triggeredSettingKeys: ['evaluators.cashReserve'],
      systemIds: ['economy'],
    });
  }

  return risks;
}

