export function lockSmartSettingCategory(profile: SmartSettingsProfile, category: SmartSettingsCategory): SmartSettingsProfile {
  const current = profile.lockedCategories || [];
  if (current.includes(category)) {
    return { ...profile };
  }
  return {
    ...profile,
    lockedCategories: [...current, category]
  };
}

/**
 * Unlock category in Smart Settings profile.
 */
export function unlockSmartSettingCategory(profile: SmartSettingsProfile, category: SmartSettingsCategory): SmartSettingsProfile {
  const current = profile.lockedCategories || [];
  if (!current.includes(category)) {
    return { ...profile };
  }
  return {
    ...profile,
    lockedCategories: current.filter(c => c !== category)
  };
}

/**
 * Lock setting key in Smart Settings profile.
 */
export function lockSmartSettingKey(profile: SmartSettingsProfile, key: string): SmartSettingsProfile {
  const current = profile.lockedSettingKeys || [];
  if (current.includes(key)) {
    return { ...profile };
  }
  return {
    ...profile,
    lockedSettingKeys: [...current, key]
  };
}

/**
 * Unlock setting key in Smart Settings profile.
 */
export function unlockSmartSettingKey(profile: SmartSettingsProfile, key: string): SmartSettingsProfile {
  const current = profile.lockedSettingKeys || [];
  if (!current.includes(key)) {
    return { ...profile };
  }
  return {
    ...profile,
    lockedSettingKeys: current.filter(k => k !== key)
  };
}

/**
 * Live Match Safety Check (Req 19).
 * Checks if modifying settingKey during an active match is safe according to SMART_CONTROLLABLE_SETTINGS_REGISTRY.
 */
export function checkLiveMatchSafety(
  settingKey: string,
  newValue: any,
  isLiveMatch: boolean
): { isSafe: boolean; reason: string } {
  if (!isLiveMatch) {
    return {
      isSafe: true,
      reason: `Setting '${settingKey}' modification is safe because match is not currently live.`
    };
  }

  const regEntry = SMART_CONTROLLABLE_SETTINGS_REGISTRY.find(s => s.key === settingKey);
  if (regEntry && regEntry.isLiveSafe === false) {
    return {
      isSafe: false,
      reason: `Setting '${settingKey}' is marked unsafe for live match modifications and must be deferred.`
    };
  }

  return {
    isSafe: true,
    reason: `Setting '${settingKey}' is safe for live match modifications.`
  };
}

/**
 * Manual Override Detection (Req 15).
 * Marks profile as having custom overrides detected and updates experienceStyle to 'custom'.
 */
export function detectAndHandleManualOverride(
  key: string,
  newValue: any,
  currentSettings: GameSettingsState
): GameSettingsState {
  const updatedSettings: GameSettingsState = { ...currentSettings };
  const baseProfile = updatedSettings.smartSettingsProfile || createDefaultSmartSettingsProfile();

  let presetValue: any = undefined;
  if (baseProfile.activePresetId && baseProfile.activePresetId !== 'custom') {
    const preset = SMART_SETTINGS_PRESETS.find(p => p.id === baseProfile.activePresetId);
    if (preset && preset.profile) {
      presetValue = (preset.profile as any)[key];
    }
  }
  if (presetValue === undefined) {
    presetValue = (DEFAULT_GAME_SETTINGS as any)[key];
  }

  const existingOverrides = baseProfile.manualOverrides ? [...baseProfile.manualOverrides] : [];
  const existingIdx = existingOverrides.findIndex(o => o.settingKey === key);

  if (typeof settingsValuesEqual === 'function' ? settingsValuesEqual(newValue, presetValue) : newValue === presetValue) {
    if (existingIdx !== -1) {
      existingOverrides.splice(existingIdx, 1);
    }
  } else {
    if (existingIdx !== -1) {
      existingOverrides[existingIdx] = { settingKey: key, presetValue, overrideValue: newValue };
    } else {
      existingOverrides.push({ settingKey: key, presetValue, overrideValue: newValue });
    }
  }

  const customOverridesDetected = existingOverrides.length > 0;
  const experienceStyle = customOverridesDetected ? 'custom' : (baseProfile.experienceStyle || 'custom');

  const updatedProfile: SmartSettingsProfile = {
    ...baseProfile,
    manualOverrides: existingOverrides,
    experienceStyle,
    customOverridesDetected,
    activePresetId: customOverridesDetected ? 'custom' : baseProfile.activePresetId
  };

  (updatedSettings as Record<string, unknown>)[key] = newValue;
  updatedSettings.smartSettingsProfile = updatedProfile;

  return updatedSettings;
}

let smartSettingsTransactionIdCounter = 0;

/**
 * Transactional Apply Engine (Req 14 & 19).
 * Applies a SmartSettingsPlan transactionally to GameSettingsState.
 * Saves exact priorValues for 100% reversible undo.
 * Defers live-unsafe changes when isLiveMatch is true.
 */
export function applySmartSettingsPlan(
  planOrSettings: any,
  settingsOrPlan: any,
  isLiveMatchOrUpdateFn?: boolean | ((s: GameSettingsState) => void),
  undoStackArg?: SmartSettingsTransaction[]
): { updatedSettings: GameSettingsState; transaction: SmartSettingsTransaction; undoStack: SmartSettingsTransaction[] } {
  let plan: SmartSettingsPlan;
  let currentSettings: GameSettingsState;

  if (planOrSettings && planOrSettings.planId) {
    plan = planOrSettings;
    currentSettings = settingsOrPlan;
  } else if (settingsOrPlan && settingsOrPlan.planId) {
    plan = settingsOrPlan;
    currentSettings = planOrSettings;
  } else {
    plan = planOrSettings || {};
    currentSettings = settingsOrPlan || {};
  }
  let isLiveMatch = false;
  let updateFn: ((s: GameSettingsState) => void) | undefined;

  if (typeof isLiveMatchOrUpdateFn === 'function') {
    updateFn = isLiveMatchOrUpdateFn;
  } else if (typeof isLiveMatchOrUpdateFn === 'boolean') {
    isLiveMatch = isLiveMatchOrUpdateFn;
  }

  smartSettingsTransactionIdCounter += 1;
  const transactionId = `tx_${Date.now()}_${smartSettingsTransactionIdCounter}`;
  const timestamp = Date.now();

  const profileBefore: SmartSettingsProfile = {
    ...(currentSettings.smartSettingsProfile || plan.profile)
  };

  const updatedSettings: GameSettingsState = { ...currentSettings };
  const priorValues: Record<string, any> = {};
  const appliedValues: Record<string, any> = {};

  let hasDeferredChanges = false;

  const cloneSubsystem = <T,>(value: T | undefined, fallback: T): T => {
    if (!value) return fallback;
    try {
      return JSON.parse(JSON.stringify(value));
    } catch {
      return fallback;
    }
  };
  const priorSubsystemValues: {
    coPilotSettings?: CoPilotSettings;
    autoModeSettings?: AutoModeGlobalSettings;
    guardianAiSettings?: GuardianAiSettings;
  } = {
    coPilotSettings: cloneSubsystem(currentSettings.coPilotSettings, createDefaultCoPilotSettings()),
    autoModeSettings: cloneSubsystem(currentSettings.autoModeSettings, createDefaultAutoModeGlobalSettings()),
    guardianAiSettings: cloneSubsystem(currentSettings.guardianAiSettings, createDefaultGuardianAiSettings()),
  };

  const planChanges = plan?.changes || [];
  for (const change of planChanges) {
    const { settingKey, proposedValue } = change;
    const currentVal = (currentSettings as Record<string, unknown>)[settingKey];

    const safetyCheck = checkLiveMatchSafety(settingKey, proposedValue, isLiveMatch);

    if (!safetyCheck.isSafe) {
      hasDeferredChanges = true;
      const scope = getSettingDeferralScope(settingKey);
      const deferredTx: DeferredTransactionItem = {
        id: `def_tx_${Date.now()}_${(Date.now() % 100000).toString(36)}`,
        settingKey,
        value: proposedValue,
        deferralScope: scope,
        reason: scope === 'next_match' ? 'Applies next match' : 'Deferred until safe point',
        timestamp: Date.now()
      };
      const existingDeferred = (updatedSettings as any).deferredTransactions || [];
      (updatedSettings as any).deferredTransactions = [...existingDeferred, deferredTx];
      continue;
    }

    priorValues[settingKey] = currentVal;
    appliedValues[settingKey] = proposedValue;
    if (settingKey !== 'permissionMode') {
      (updatedSettings as Record<string, unknown>)[settingKey] = proposedValue;
    }

    if (settingKey === 'guardianAiEnabled') {
      updatedSettings.guardianAiSettings = { ...(updatedSettings.guardianAiSettings || createDefaultGuardianAiSettings()), enabled: Boolean(proposedValue) };
    } else if (settingKey === 'guardianAiProtectionLevel') {
      updatedSettings.guardianAiSettings = { ...(updatedSettings.guardianAiSettings || createDefaultGuardianAiSettings()), protectionLevel: proposedValue as GuardianAiProtectionLevel };
    } else if (settingKey === 'guardianAiResponseMode') {
      updatedSettings.guardianAiSettings = { ...(updatedSettings.guardianAiSettings || createDefaultGuardianAiSettings()), responseMode: proposedValue as GuardianAiResponseMode };
    } else if (settingKey === 'coPilotEnabled') {
      updatedSettings.coPilotSettings = { ...(updatedSettings.coPilotSettings || createDefaultCoPilotSettings()), coPilotEnabled: Boolean(proposedValue) };
    } else if (settingKey === 'coPilotAuthorityMode') {
      updatedSettings.coPilotSettings = { ...(updatedSettings.coPilotSettings || createDefaultCoPilotSettings()), authorityMode: proposedValue as CoPilotAuthorityMode };
    } else if (settingKey === 'autoModeEnabled') {
      updatedSettings.autoModeSettings = { ...(updatedSettings.autoModeSettings || createDefaultAutoModeGlobalSettings()), autoModeEnabled: Boolean(proposedValue) };
    } else if (settingKey === 'autoModePermission' || settingKey === 'permissionMode') {
      updatedSettings.autoModeSettings = { ...(updatedSettings.autoModeSettings || createDefaultAutoModeGlobalSettings()), permissionMode: proposedValue as AutoModePermission, permission: proposedValue as AutoModePermission };
    }
  }

  const profileAfter: SmartSettingsProfile = {
    ...profileBefore,
    ...plan.profile,
    lastAppliedPlanId: plan.planId
  };

  const effEnabled = updatedSettings.coPilotSettings?.coPilotEnabled ?? updatedSettings.coPilotEnabled ?? false;
  const effAuthMode = updatedSettings.coPilotSettings?.authorityMode ?? updatedSettings.coPilotAuthorityMode ?? 'off';
  profileAfter.coPilotMode = mapTechnicalSettingsToConceptualMode(effEnabled, effAuthMode);
  updatedSettings.smartSettingsProfile = profileAfter;
  if (currentSettings.coPilotEnabled !== undefined || appliedValues['coPilotEnabled'] !== undefined) {
    updatedSettings.coPilotEnabled = effEnabled;
  }
  if (currentSettings.coPilotAuthorityMode !== undefined || appliedValues['coPilotAuthorityMode'] !== undefined) {
    updatedSettings.coPilotAuthorityMode = effAuthMode as CoPilotAuthorityMode;
  }

  const status: SmartSettingsTransaction['status'] =
    hasDeferredChanges ? 'partially_overridden' : 'applied';

  const transaction: SmartSettingsTransaction = {
    transactionId,
    timestamp,
    planId: plan.planId,
    priorValues,
    appliedValues,
    profileBefore,
    profileAfter,
    status,
    priorSubsystemValues
  };

  const priorUndo = Array.isArray(undoStackArg)
    ? undoStackArg
    : (Array.isArray((currentSettings as any)._undoStack) ? (currentSettings as any)._undoStack : []);
  const undoStack = [...priorUndo, transaction];
  (updatedSettings as any)._undoStack = undoStack;

  if (typeof updateFn === 'function') {
    updateFn(updatedSettings);
  }

  return {
    updatedSettings,
    transaction,
    undoStack
  };
}

export interface DeferredTransactionItem {
  id: string;
  settingKey: string;
  value: any;
  deferralScope: 'turn_end' | 'next_match';
  reason: string;
  timestamp: number;
}


export function flushDeferredTransactionsOnBoundary(
  currentSettings: GameSettingsState,
  boundaryType: 'turn_end' | 'next_match',
  updateFn?: (newSettings: GameSettingsState) => void
): { updatedSettings: GameSettingsState; appliedCount: number; remainingCount: number } {
  const deferredList: DeferredTransactionItem[] = (currentSettings as any).deferredTransactions || [];
  if (!deferredList.length) {
    return { updatedSettings: currentSettings, appliedCount: 0, remainingCount: 0 };
  }

  const updatedSettings: GameSettingsState = JSON.parse(JSON.stringify(currentSettings));
  const remaining: DeferredTransactionItem[] = [];
  let appliedCount = 0;

  for (const item of deferredList) {
    if (item.deferralScope === boundaryType || boundaryType === 'next_match') {
      (updatedSettings as any)[item.settingKey] = item.value;
      appliedCount++;
    } else {
      remaining.push(item);
    }
  }

  (updatedSettings as any).deferredTransactions = remaining;

  if (appliedCount > 0 && typeof updateFn === 'function') {
    updateFn(updatedSettings);
  }

  return { updatedSettings, appliedCount, remainingCount: remaining.length };
}

export function getSettingDeferralScope(settingKey: string): 'turn_end' | 'next_match' {
  const matchWideKeys = [
    'randomnessMode', 'worldRngMode', 'aiDeterministic', 'deterministicRngActive',
    'worldRngSeed', 'aiDeterministicSeed', 'winCondition', 'selectedMode',
    'scenarioModeEnabled', 'selectedScenarioId', 'totalDays'
  ];
  if (matchWideKeys.includes(settingKey)) {
    return 'next_match';
  }
  return 'turn_end';
}

export function flushTurnEndDeferredSettings(currentSettings: GameSettingsState): {
  updatedSettings: GameSettingsState;
  flushedCount: number;
} {
  const currentDeferred: DeferredTransactionItem[] = (currentSettings as any).deferredTransactions || [];
  if (currentDeferred.length === 0) {
    return { updatedSettings: currentSettings, flushedCount: 0 };
  }

  const updatedSettings: GameSettingsState = { ...currentSettings };
  const turnEndItems = currentDeferred.filter(item => item.deferralScope === 'turn_end');
  const remainingItems = currentDeferred.filter(item => item.deferralScope !== 'turn_end');

  for (const item of turnEndItems) {
    (updatedSettings as Record<string, unknown>)[item.settingKey] = item.value;
  }

  (updatedSettings as any).deferredTransactions = remainingItems;

  return {
    updatedSettings,
    flushedCount: turnEndItems.length
  };
}

export function flushMatchWideDeferredSettings(currentSettings: GameSettingsState): {
  updatedSettings: GameSettingsState;
  flushedCount: number;
} {
  const currentDeferred: DeferredTransactionItem[] = (currentSettings as any).deferredTransactions || [];
  if (currentDeferred.length === 0) {
    return { updatedSettings: currentSettings, flushedCount: 0 };
  }

  const updatedSettings: GameSettingsState = { ...currentSettings };
  const matchItems = currentDeferred.filter(item => item.deferralScope === 'next_match');
  const remainingItems = currentDeferred.filter(item => item.deferralScope !== 'next_match');

  for (const item of matchItems) {
    (updatedSettings as Record<string, unknown>)[item.settingKey] = item.value;
  }

  (updatedSettings as any).deferredTransactions = remainingItems;

  return {
    updatedSettings,
    flushedCount: matchItems.length
  };
}

export function undoSmartSettingsTransaction(
  transactionOrStack: SmartSettingsTransaction | SmartSettingsTransaction[],
  currentSettings: GameSettingsState,
  updateFn?: (s: GameSettingsState) => void
): GameSettingsState {
  let transaction: SmartSettingsTransaction | undefined;
  let undoStack: SmartSettingsTransaction[] | undefined;

  if (Array.isArray(transactionOrStack)) {
    undoStack = transactionOrStack;
    transaction = undoStack.pop();
  } else {
    transaction = transactionOrStack;
  }

  if (!transaction) return currentSettings;

  const revertedSettings: GameSettingsState = { ...currentSettings };

  for (const [key, priorVal] of Object.entries(transaction.priorValues)) {
    if (priorVal !== undefined) {
      (revertedSettings as Record<string, unknown>)[key] = priorVal;
    } else {
      delete (revertedSettings as Record<string, unknown>)[key];
    }
  }

  if (transaction.priorSubsystemValues) {
    if (transaction.priorSubsystemValues.coPilotSettings) {
      revertedSettings.coPilotSettings = JSON.parse(JSON.stringify(transaction.priorSubsystemValues.coPilotSettings));
    }
    if (transaction.priorSubsystemValues.autoModeSettings) {
      revertedSettings.autoModeSettings = JSON.parse(JSON.stringify(transaction.priorSubsystemValues.autoModeSettings));
    }
    if (transaction.priorSubsystemValues.guardianAiSettings) {
      revertedSettings.guardianAiSettings = JSON.parse(JSON.stringify(transaction.priorSubsystemValues.guardianAiSettings));
    }
  } else {
    for (const [key, priorVal] of Object.entries(transaction.priorValues)) {
      if (key === 'guardianAiEnabled') {
        const base = revertedSettings.guardianAiSettings || createDefaultGuardianAiSettings();
        revertedSettings.guardianAiSettings = { ...base, enabled: priorVal !== undefined ? Boolean(priorVal) : base.enabled };
      } else if (key === 'guardianAiProtectionLevel') {
        const base = revertedSettings.guardianAiSettings || createDefaultGuardianAiSettings();
        revertedSettings.guardianAiSettings = { ...base, protectionLevel: (priorVal as GuardianAiProtectionLevel) || base.protectionLevel || 'major_mistakes' };
      } else if (key === 'guardianAiResponseMode') {
        const base = revertedSettings.guardianAiSettings || createDefaultGuardianAiSettings();
        revertedSettings.guardianAiSettings = { ...base, responseMode: (priorVal as GuardianAiResponseMode) || base.responseMode || 'adaptive' };
      } else if (key === 'coPilotEnabled') {
        const base = revertedSettings.coPilotSettings || createDefaultCoPilotSettings();
        revertedSettings.coPilotSettings = { ...base, coPilotEnabled: priorVal !== undefined ? Boolean(priorVal) : base.coPilotEnabled };
      } else if (key === 'coPilotAuthorityMode') {
        const base = revertedSettings.coPilotSettings || createDefaultCoPilotSettings();
        revertedSettings.coPilotSettings = { ...base, authorityMode: (priorVal as CoPilotAuthorityMode) || base.authorityMode || 'off' };
      } else if (key === 'autoModeEnabled') {
        const base = revertedSettings.autoModeSettings || createDefaultAutoModeGlobalSettings();
        revertedSettings.autoModeSettings = { ...base, autoModeEnabled: priorVal !== undefined ? Boolean(priorVal) : base.autoModeEnabled };
      } else if (key === 'autoModePermission' || key === 'permissionMode') {
        const base = revertedSettings.autoModeSettings || createDefaultAutoModeGlobalSettings();
        const pMode = (priorVal as AutoModePermission) || base.permissionMode || 'recommend_only';
        revertedSettings.autoModeSettings = { ...base, permissionMode: pMode, permission: pMode };
      }
    }
  }

  if (transaction.profileBefore) {
    revertedSettings.smartSettingsProfile = { ...transaction.profileBefore };
  }

  transaction.status = 'undone';

  if (typeof updateFn === 'function') {
    updateFn(revertedSettings);
  }

  return revertedSettings;
}

/**
 * Generated Settings Summary Calculator (Req 20).
 * Returns summary statistics of managed, overridden, locked, conflict, and live match safety status.
 */
export function getSmartSettingsSummaryStats(
  profile: SmartSettingsProfile,
  currentSettings: GameSettingsState,
  plan?: SmartSettingsPlan
): SmartSettingsSummaryStats {
  const lockedKeys = profile.lockedSettingKeys || [];
  const lockedCats = profile.lockedCategories || [];

  const lockedCount = SMART_CONTROLLABLE_SETTINGS_REGISTRY.filter(
    s => lockedKeys.includes(s.key) || lockedCats.includes(s.category)
  ).length;

  const overriddenCount = profile.manualOverrides && profile.manualOverrides.length > 0 
    ? profile.manualOverrides.length 
    : (profile.customOverridesDetected ? 1 : 0);

  if (plan) {
    const safeLiveChangesCount = plan.changes.filter(c => c.safetyStatus === 'safe').length;
    const deferredUnsafeChangesCount = plan.changes.filter(c => c.safetyStatus === 'unsafe_deferred').length;
    const unresolvedConflictsCount = plan.conflicts.length;
    const managedCount = plan.changes.length;

    return {
      managedCount,
      overriddenCount,
      lockedCount,
      unresolvedConflictsCount,
      safeLiveChangesCount,
      deferredUnsafeChangesCount
    };
  }

  const safeLiveChangesCount = SMART_CONTROLLABLE_SETTINGS_REGISTRY.filter(s => s.isLiveSafe !== false).length;
  const deferredUnsafeChangesCount = SMART_CONTROLLABLE_SETTINGS_REGISTRY.filter(s => s.isLiveSafe === false).length;

  return {
    managedCount: SMART_CONTROLLABLE_SETTINGS_REGISTRY.length,
    overriddenCount,
    lockedCount,
    unresolvedConflictsCount: 0,
    safeLiveChangesCount,
    deferredUnsafeChangesCount
  };
}

