export const SMART_SETTINGS_SCHEMA_VERSION = '1.0';

/**
 * Validates an Auto Mode action against SmartSettings boundaries (Req 2, 3, 12).
 * Ensures Director intent and Auto Mode boundaries remain distinct and enforced.
 */
export function validateAutoModeActionAgainstSmartBoundaries(
  actionType: string,
  profile: SmartSettingsProfile,
  autoModeSettings: AutoModeGlobalSettings
): { allowed: boolean; reason?: string } {
  // Master toggle checks
  if (!profile || profile.enabled === false) {
    return { allowed: false, reason: 'SmartSettingsProfile is disabled' };
  }

  const isAutoModeEnabled = autoModeSettings?.autoModeEnabled ?? autoModeSettings?.enabled ?? false;
  if (!isAutoModeEnabled || autoModeSettings?.permission === 'disabled' || autoModeSettings?.permission === 'locked') {
    return { allowed: false, reason: 'Auto Mode is disabled or locked in global settings' };
  }

  if (profile.automation === 'manual') {
    return { allowed: false, reason: 'Automation set to manual in SmartSettingsProfile' };
  }

  // Category and Key locks check
  const lockedCats = profile.lockedCategories || [];
  const lockedKeys = profile.lockedSettingKeys || [];

  if (lockedKeys.includes(actionType)) {
    return { allowed: false, reason: `Setting key '${actionType}' is locked in SmartSettingsProfile` };
  }

  if (actionType.includes('economic') || actionType.includes('economy') || actionType.includes('grant') || actionType.includes('relief') || actionType.includes('subsidy')) {
    if (lockedCats.includes('economy' as SmartSettingsCategory)) {
      return { allowed: false, reason: `Action type '${actionType}' is locked in SmartSettingsProfile` };
    }
  }

  if (actionType.includes('ai') || actionType.includes('difficulty') || actionType.includes('intelligence') || actionType.includes('fairness')) {
    if (lockedCats.includes('ai' as SmartSettingsCategory) || lockedCats.includes('teams' as SmartSettingsCategory) || lockedCats.includes('difficulty' as SmartSettingsCategory)) {
      return { allowed: false, reason: `Action type '${actionType}' is locked in SmartSettingsProfile` };
    }
  }

  // Specific Auto Mode permission boundary checks
  const typeLower = actionType.toLowerCase();

  if ((typeLower.includes('strategy') || typeLower.includes('strategy_change')) && autoModeSettings.allowStrategyChanges === false) {
    return { allowed: false, reason: 'Strategy changes disallowed by Auto Mode boundary settings' };
  }

  if (typeLower.includes('cash_grant') && autoModeSettings.allowCashGrants === false) {
    return { allowed: false, reason: 'Cash grants disallowed by Auto Mode boundary settings' };
  }

  if (typeLower.includes('tax_relief') && autoModeSettings.allowTaxRelief === false) {
    return { allowed: false, reason: 'Tax relief disallowed by Auto Mode boundary settings' };
  }

  if (typeLower.includes('tariff_protection') && autoModeSettings.allowTariffProtection === false) {
    return { allowed: false, reason: 'Tariff protection disallowed by Auto Mode boundary settings' };
  }

  if (typeLower.includes('infrastructure_subsidy') && autoModeSettings.allowInfrastructureSubsidy === false) {
    return { allowed: false, reason: 'Infrastructure subsidy disallowed by Auto Mode boundary settings' };
  }

  if (typeLower.includes('sanction_relief') && autoModeSettings.allowSanctionRelief === false) {
    return { allowed: false, reason: 'Sanction relief disallowed by Auto Mode boundary settings' };
  }

  if (typeLower.includes('resource_grant') && autoModeSettings.allowResourceGrant === false) {
    return { allowed: false, reason: 'Resource grants disallowed by Auto Mode boundary settings' };
  }

  if ((typeLower.includes('economy') || typeLower.includes('economic')) && autoModeSettings.allowEconomyChanges === false) {
    return { allowed: false, reason: 'Economy changes disallowed by Auto Mode boundary settings' };
  }

  if ((typeLower.includes('action_management') || typeLower.includes('action_limit')) && autoModeSettings.allowActionManagementChanges === false) {
    return { allowed: false, reason: 'Action management changes disallowed by Auto Mode boundary settings' };
  }

  if (typeLower.includes('opportunity') && autoModeSettings.allowOpportunityGeneration === false) {
    return { allowed: false, reason: 'Opportunity generation disallowed by Auto Mode boundary settings' };
  }

  if ((typeLower.includes('numerical') || typeLower.includes('stat_modifier')) && autoModeSettings.allowNumericalModifiers === false) {
    return { allowed: false, reason: 'Numerical modifiers disallowed by Auto Mode boundary settings' };
  }

  if ((typeLower.includes('difficulty') || typeLower.includes('fairness')) && autoModeSettings.allowDifficultyAdjustments === false) {
    return { allowed: false, reason: 'Difficulty adjustments disallowed by Auto Mode boundary settings' };
  }

  if ((typeLower.includes('human_autopilot') || typeLower.includes('autopilot')) && autoModeSettings.allowHumanAutopilot === false) {
    return { allowed: false, reason: 'Human autopilot disallowed by Auto Mode boundary settings' };
  }

  return { allowed: true };
}

export function isSmartSettingsManagedKey(key: string): boolean { return typeof key === 'string' && (key.startsWith('smartSettingsProfile') || key.startsWith('autoMode')); }

export function evaluateContractRisk(
  context: GuardianEvaluationContext
): readonly GuardianDetectedRisk[] {
  const risks: GuardianDetectedRisk[] = [];
  const actor = extractActorState(context);
  const payload = context.actionPayload || {};
  const normAction = context.actionType.toLowerCase();

  const gs = context.gameState as Record<string, unknown>;
  const regionalContracts = (gs?.regionalContracts || {}) as Record<string, Record<string, unknown>>;
  const activeContractIds = context.activeContracts;

  // Rule 1: Selling Contract-Reserved Resources
  if (['sell_resources', 'sell'].includes(normAction)) {
    const resName = typeof payload.resource === 'string' ? payload.resource : typeof payload.resourceType === 'string' ? payload.resourceType : '';
    const sellQty = typeof payload.quantity === 'number' ? payload.quantity : 1;

    if (resName) {
      let reservedAmount = 0;
      activeContractIds.forEach((cId) => {
        const contract = regionalContracts[cId];
        if (contract && contract.status === 'active') {
          const reqRes = contract.requiredResources as Record<string, number> | undefined;
          if (reqRes && typeof reqRes[resName] === 'number') {
            reservedAmount += reqRes[resName];
          }
        }
      });

      if (reservedAmount > 0) {
        const inventory = extractActorInventory(actor);
        const currentResQty = inventory.filter((r) => r === resName).length;
        if (currentResQty - sellQty < reservedAmount) {
          risks.push({
            id: `risk_contract_res_${context.actorId}_t${context.turn}_${resName}`,
            category: 'contract',
            severity: 'critical',
            title: 'Contract Resource Reservation Breach',
            description: `Selling ${sellQty} unit(s) of '${resName}' drops inventory below active contract requirement (${reservedAmount} required).`,
            evidence: [
              `Current '${resName}' inventory: ${currentResQty}`,
              `Selling quantity: ${sellQty}`,
              `Active contract reserved quantity: ${reservedAmount}`,
            ],
            assumptions: ['Contract fulfillment requires retaining specified resource units in inventory.'],
            probability: 0.90,
            estimatedImpact: reservedAmount * 200,
            confidence: 0.95,
            reversible: true,
            immediate: true,
            triggeredSettingKeys: ['evaluators.contract'],
            systemIds: ['contracts', 'inventory'],
          });
        }
      }
    }
  }

  // Rule 2: Travel / Turn-End Causing Contract Expiration
  if (['travel', 'expedition_begin', 'end_turn'].includes(normAction)) {
    const travelDays = typeof payload.travelDays === 'number' ? payload.travelDays : (normAction === 'end_turn' ? 1 : 2);

    activeContractIds.forEach((cId) => {
      const contract = regionalContracts[cId];
      if (contract && contract.status === 'active') {
        const turnsRemaining = typeof contract.turnsRemaining === 'number' ? contract.turnsRemaining : 2;
        const isFulfilled = Boolean(contract.isFulfilled);

        if (!isFulfilled && turnsRemaining <= travelDays) {
          const title = typeof contract.title === 'string' ? contract.title : cId;
          const penalty = typeof contract.penaltyMoney === 'number' ? contract.penaltyMoney : 1000;

          risks.push({
            id: `risk_contract_expiry_${context.actorId}_t${context.turn}_${cId}`,
            category: 'contract',
            severity: 'critical',
            title: 'Contract Expiration Warning',
            description: `Action duration (${travelDays} turns/days) will cause active contract '${title}' to expire in ${turnsRemaining} turn(s), incurring a ${penalty} fine.`,
            evidence: [
              `Contract: '${title}'`,
              `Turns remaining: ${turnsRemaining}`,
              `Action duration: ${travelDays} day(s)`,
              `Default penalty: ${penalty}`,
            ],
            assumptions: ['Contract cannot be fulfilled while traveling or after turn advance.'],
            probability: 0.95,
            estimatedImpact: penalty,
            confidence: 0.90,
            reversible: false,
            immediate: false,
            triggeredSettingKeys: ['evaluators.contract'],
            systemIds: ['contracts'],
          });
        }
      }
    });
  }

  return risks;
}

/**
 * Requirement #16: Infrastructure Protection Evaluator
 */
export function evaluateInfrastructureRisk(
  context: GuardianEvaluationContext
): readonly GuardianDetectedRisk[] {
  const risks: GuardianDetectedRisk[] = [];
  const normAction = context.actionType.toLowerCase();

  if (!['infrastructure_project', 'start_infrastructure_project', 'startinfrastructure', 'upgrade_regional_dev_level', 'infrastructure_build'].includes(normAction)) {
    return risks;
  }

  const actor = extractActorState(context);
  const currentCash = context.currentCash;
  const payload = context.actionPayload || {};
  const cost = typeof payload.cost === 'number' ? payload.cost : typeof payload.investmentAmount === 'number' ? payload.investmentAmount : 3000;

  // Rule 1: Unaffordable Construction Cost
  if (cost > currentCash) {
    risks.push({
      id: `risk_infra_cost_${context.actorId}_t${context.turn}`,
      category: 'infrastructure',
      severity: 'critical',
      title: 'Unaffordable Infrastructure Project',
      description: `Project cost (${cost}) exceeds current cash reserves (${Math.round(currentCash)}).`,
      evidence: [`Required cash: ${cost}`, `Available cash: ${Math.round(currentCash)}`],
      assumptions: ['Project requires upfront cash payment.'],
      probability: 1.0,
      estimatedImpact: cost,
      confidence: 1.0,
      reversible: false,
      immediate: true,
      triggeredSettingKeys: ['evaluators.infrastructure'],
      systemIds: ['infrastructure', 'economy'],
    });
  } else if (currentCash - cost < 1000) {
    risks.push({
      id: `risk_infra_reserve_${context.actorId}_t${context.turn}`,
      category: 'infrastructure',
      severity: 'serious',
      title: 'Infrastructure Reserves Depletion',
      description: `Building this project leaves only ${Math.round(currentCash - cost)} liquid cash, below the $1,000 safety threshold.`,
      evidence: [`Post-build cash: ${Math.round(currentCash - cost)}`, `Reserve threshold: $1,000`],
      assumptions: ['Ongoing maintenance will be incurred next turn.'],
      probability: 0.70,
      estimatedImpact: 1000 - (currentCash - cost),
      confidence: 0.85,
      reversible: false,
      immediate: true,
      triggeredSettingKeys: ['evaluators.infrastructure'],
      systemIds: ['infrastructure'],
    });
  }

  return risks;
}

/**
 * Requirement #17: Expedition Protection Evaluator
 */
export function evaluateExpeditionRisk(
  context: GuardianEvaluationContext
): readonly GuardianDetectedRisk[] {
  const risks: GuardianDetectedRisk[] = [];
  const normAction = context.actionType.toLowerCase();

  if (!['expedition_begin', 'launch_expedition', 'launchexpedition', 'expedition_advance', 'expedition_choice', 'expedition_objective'].includes(normAction)) {
    return risks;
  }

  const actor = extractActorState(context);
  const suppliesInfo = extractActorSupplies(actor);
  const condition = extractActorCondition(actor);
  const payload = context.actionPayload || {};

  // Compute required safe return supplies:
  // S_req = (remainingLegs * 10 * burnMult) + (dangerRating * 5)
  const dangerRating = typeof payload.dangerRating === 'number' ? payload.dangerRating : 2;
  const burnMult = typeof payload.burnMult === 'number' ? payload.burnMult : 1.0;
  const remainingLegs = typeof payload.remainingLegs === 'number' ? payload.remainingLegs : 2;
  const safeReturnSuppliesReq = Math.round(remainingLegs * 10 * burnMult + dangerRating * 5);

  // Rule 1: Supply Exhaustion vs Safe Return Requirement
  if (['expedition_advance', 'expedition_choice'].includes(normAction)) {
    if (suppliesInfo.currentSupplies < safeReturnSuppliesReq) {
      risks.push({
        id: `risk_expedition_supplies_${context.actorId}_t${context.turn}`,
        category: 'expedition',
        severity: 'critical',
        title: 'Expedition Supply Exhaustion Risk',
        description: `Current supplies (${suppliesInfo.currentSupplies}) fall below safe return requirement (${safeReturnSuppliesReq}). Advancing risks forced retreat and complete progress loss.`,
        evidence: [
          `Current supplies: ${suppliesInfo.currentSupplies}/${suppliesInfo.maxSupplies}`,
          `Safe return requirement: ${safeReturnSuppliesReq}`,
          `Danger rating: ${dangerRating}`,
        ],
        assumptions: ['Retreating requires supply consumption based on remaining route legs.'],
        probability: 0.90,
        estimatedImpact: 1500,
        confidence: 0.95,
        reversible: false,
        immediate: true,
        triggeredSettingKeys: ['evaluators.expedition'],
        systemIds: ['expeditions'],
      });
    }
  }

  // Rule 2: Critical Condition Flag
  if (condition === 'critical' && ['expedition_begin', 'launch_expedition', 'expedition_advance'].includes(normAction)) {
    risks.push({
      id: `risk_expedition_condition_${context.actorId}_t${context.turn}`,
      category: 'expedition',
      severity: 'critical',
      title: 'Critical Physical Condition Hazard',
      description: 'Actor condition is CRITICAL. Continuing or starting an expedition risks immediate emergency collapse.',
      evidence: [
        `Actor condition: CRITICAL`,
        `Supplies ratio: ${Math.round(suppliesInfo.ratio * 100)}%`,
      ],
      assumptions: ['Critical condition multiplies hazard check failures by 1.6x.'],
      probability: 0.95,
      estimatedImpact: 2000,
      confidence: 0.95,
      reversible: false,
      immediate: true,
      triggeredSettingKeys: ['evaluators.expedition'],
      systemIds: ['expeditions'],
    });
  }

  // Rule 3: Missing Required Expedition Equipment
  if (['expedition_begin', 'launch_expedition'].includes(normAction)) {
    const requiredGear = Array.isArray(payload.requiredEquipment)
      ? payload.requiredEquipment.filter((g): g is string => typeof g === 'string')
      : [];
    if (requiredGear.length > 0) {
      const equipment = extractActorEquipment(actor);
      const missingGear = requiredGear.filter((g) => !equipment.includes(g));
      if (missingGear.length > 0) {
        risks.push({
          id: `risk_expedition_gear_${context.actorId}_t${context.turn}`,
          category: 'equipment',
          severity: 'serious',
          title: 'Missing Required Expedition Gear',
          description: `Missing required gear (${missingGear.join(', ')}). Expedition hazard severity will be multiplied by 1.6x.`,
          evidence: [
            `Required gear: ${requiredGear.join(', ')}`,
            `Missing gear: ${missingGear.join(', ')}`,
          ],
          assumptions: ['Unfitted gear incurs severe hazard penalties.'],
          probability: 0.80,
          estimatedImpact: 1000,
          confidence: 0.90,
          reversible: true,
          immediate: true,
          triggeredSettingKeys: ['evaluators.expedition', 'evaluators.equipment'],
          systemIds: ['expeditions', 'inventory'],
        });
      }
    }
  }

  return risks;
}

/**
 * Requirement #18: Travel Protection Evaluator
 */
export function evaluateTravelRisk(
  context: GuardianEvaluationContext
): readonly GuardianDetectedRisk[] {
  const risks: GuardianDetectedRisk[] = [];
  const normAction = context.actionType.toLowerCase();

  if (normAction !== 'travel') return risks;

  const actor = extractActorState(context);
  const currentCash = context.currentCash;
  const payload = context.actionPayload || {};
  const travelCost = typeof payload.cost === 'number' ? payload.cost : typeof payload.travelCost === 'number' ? payload.travelCost : 300;
  const travelDays = typeof payload.travelDays === 'number' ? payload.travelDays : 2;
  const destination = typeof payload.destinationRegion === 'string' ? payload.destinationRegion : typeof payload.destination === 'string' ? payload.destination : 'remote';

  // Rule 1: Final AP Travel Warning
  if (context.currentActionTokens === 1) {
    risks.push({
      id: `risk_travel_final_ap_${context.actorId}_t${context.turn}`,
      category: 'action_tokens',
      severity: 'caution',
      title: 'Final Action Point Spent on Travel',
      description: 'Spending final Action Point on travel leaves 0 AP to gather, trade, or fulfill contracts in destination region before turn end.',
      evidence: [
        `Current AP: 1`,
        `Proposed action: travel to ${destination}`,
      ],
      assumptions: ['Arriving at destination with 0 AP prevents immediate interaction.'],
      probability: 0.70,
      estimatedImpact: 300,
      confidence: 0.85,
      reversible: false,
      immediate: true,
      triggeredSettingKeys: ['evaluators.travel', 'evaluators.actionTokens'],
      systemIds: ['travel', 'action_tokens'],
    });
  }

  // Rule 2: Unaffordable Travel & Liquidity Deficit
  const debtInfo = extractActorDebt(actor);
  const dailyMaintenance = typeof actor?.maintenanceCost === 'number' ? actor.maintenanceCost : 100;
  const mandatoryTurnExpenses = dailyMaintenance + debtInfo.dailyLoanInterest;
  const postTravelCash = currentCash - travelCost;

  if (postTravelCash < mandatoryTurnExpenses) {
    risks.push({
      id: `risk_travel_liquidity_${context.actorId}_t${context.turn}`,
      category: 'liquidity',
      severity: 'serious',
      title: 'Travel Expenses Impair Turn Maintenance',
      description: `Travel cost (${travelCost}) reduces cash to ${Math.round(postTravelCash)}, below mandatory turn maintenance (${Math.round(mandatoryTurnExpenses)}).`,
      evidence: [
        `Current cash: ${Math.round(currentCash)}`,
        `Travel cost: ${travelCost}`,
        `Post-travel cash: ${Math.round(postTravelCash)}`,
        `Turn maintenance: ${Math.round(mandatoryTurnExpenses)}`,
      ],
      assumptions: ['Turn maintenance will be billed at turn end.'],
      probability: 0.85,
      estimatedImpact: mandatoryTurnExpenses - postTravelCash,
      confidence: 0.90,
      reversible: true,
      immediate: true,
      triggeredSettingKeys: ['evaluators.travel', 'evaluators.liquidity'],
      systemIds: ['travel', 'economy'],
    });
  }

  // Rule 3: Remote Territory Stranding Hazard
  const isExternal = Boolean(payload.isExternalTerritory || ['TAS', 'NT', 'WA_OUTBACK', 'ANTARCTICA'].includes(destination.toUpperCase()));
  if (isExternal) {
    const returnCost = travelCost * 1.5;
    if (postTravelCash < returnCost) {
      risks.push({
        id: `risk_travel_stranding_${context.actorId}_t${context.turn}`,
        category: 'travel',
        severity: 'critical',
        title: 'Remote Territory Stranding Risk',
        description: `Traveling to ${destination} leaves ${Math.round(postTravelCash)}, which is less than return journey cost (${Math.round(returnCost)}), risking actor stranding.`,
        evidence: [
          `Destination: ${destination}`,
          `Post-travel cash: ${Math.round(postTravelCash)}`,
          `Estimated return journey cost: ${Math.round(returnCost)}`,
        ],
        assumptions: ['External territory return travel incurs 1.5x standard travel fare.'],
        probability: 0.90,
        estimatedImpact: returnCost - postTravelCash,
        confidence: 0.90,
        reversible: false,
        immediate: false,
        triggeredSettingKeys: ['evaluators.travel'],
        systemIds: ['travel'],
      });
    }
  }

  return risks;
}

