const instantiateAiAlgorithmTemplate = (templateId: string, day: number): AiAlgorithmConfig | null => {
  const template = AI_ALGORITHM_TEMPLATES[templateId];
  if (!template) return null;
  return {
    configId: nextDecisionId(globalDeterministicCounters, 'algo'),
    revision: 0,
    name: template.label,
    description: template.description,
    editorMode: template.editorMode,
    validationStatus: 'draft',
    lastTestResult: null,
    createdByPlayer: false,
    createdDay: Math.max(0, Math.floor(day)),
    active: false,
    situationAnalysisConfig: template.situationAnalysisConfig,
    goalSelectionConfig: template.goalSelectionConfig,
    candidateGenerationConfig: template.candidateGenerationConfig,
    outcomePredictionConfig: template.outcomePredictionConfig,
    planConstructionConfig: template.planConstructionConfig,
    utilityEvaluationConfig: template.utilityEvaluationConfig,
    actionSelectionConfig: template.actionSelectionConfig,
    replanningConfig: template.replanningConfig,
    fallbackBehaviorConfig: template.fallbackBehaviorConfig,
    explanationOutputConfig: template.explanationOutputConfig
  };
};

// AB7: safe-activation validation gate. Pure, reuses the exact same closed vocabularies the
// sanitizers already validate against (AI_ALGORITHM_MAX_CANDIDATES_CONSIDERED, AI_PLANNER_GOAL_KINDS,
// TEAM_MODE_ACTION_CATEGORIES, AI_ALGORITHM_SITUATION_INFO_SOURCES) rather than inventing a second
// set of bounds. Errors block activation; warnings are informational only. Since this schema has no
// stage-to-stage jump/reference pointers (unlike Sequences' fallbackJumpToStepId), there is nothing
// structurally capable of forming a cycle — "circular-stage detection" is a stated non-issue for this
// schema shape, not silently skipped.
interface AiAlgorithmValidationResult { errors: string[]; warnings: string[]; }
const validateAiAlgorithmConfig = (config: AiAlgorithmConfig): AiAlgorithmValidationResult => {
  const errors: string[] = [];
  const warnings: string[] = [];
  if (!config.name || !config.name.trim()) errors.push('Config must have a name.');
  if (config.situationAnalysisConfig?.informationSources?.some(s => !AI_ALGORITHM_SITUATION_INFO_SOURCES.includes(s))) {
    errors.push('Situation Analysis references an unsupported information source.');
  }
  if (config.goalSelectionConfig?.goalPriorities) {
    const unknownGoals = Object.keys(config.goalSelectionConfig.goalPriorities).filter(k => !AI_PLANNER_GOAL_KINDS.includes(k as AiPlannerGoalKind));
    if (unknownGoals.length > 0) errors.push('Goal Selection references an unsupported goal kind.');
  }
  if (config.candidateGenerationConfig?.allowedActionCategories?.some(c => !TEAM_MODE_ACTION_CATEGORIES.includes(c))) {
    errors.push('Candidate Generation references an unsupported action category.');
  }
  if (config.planConstructionConfig) {
    const cap = config.planConstructionConfig.maxCandidatesConsidered;
    // 0 is the documented "consider every candidate" sentinel (see constructAiAlgorithmPlan),
    // so the valid range is {0} union [1, AI_ALGORITHM_MAX_CANDIDATES_CONSIDERED], not just [1, N].
    if (typeof cap !== 'number' || !Number.isFinite(cap) || cap < 0 || cap > AI_ALGORITHM_MAX_CANDIDATES_CONSIDERED) {
      errors.push(`Plan Construction's max candidates considered must be 0 (unlimited) or between 1 and ${AI_ALGORITHM_MAX_CANDIDATES_CONSIDERED}.`);
    }
  }
  if (config.utilityEvaluationConfig) {
    const bonus = config.utilityEvaluationConfig.goalServedBonus;
    if (typeof bonus !== 'number' || !Number.isFinite(bonus) || bonus < 0 || bonus > 100) {
      errors.push("Utility Evaluation's goal-served bonus must be between 0 and 100.");
    }
  }
  const allStagesNull = !config.situationAnalysisConfig && !config.goalSelectionConfig && !config.candidateGenerationConfig
    && !config.outcomePredictionConfig && !config.planConstructionConfig && !config.utilityEvaluationConfig
    && !config.actionSelectionConfig && !config.replanningConfig && !config.fallbackBehaviorConfig && !config.explanationOutputConfig;
  if (allStagesNull) {
    warnings.push('No stages are configured yet — this algorithm will fall back to the built-in Planner at every stage.');
  }
  return { errors, warnings };
};

// AB2: the three stage-evaluator functions, one per stage config. All three are pure, reuse
// existing computed data rather than re-deriving anything, and are uncalled by any real
// turn-execution path this phase — no custom-algorithm execution engine exists yet to invoke them
// (that wiring, once AB6's CRUD gives players a way to create/activate a config, is later-phase
// work, stated explicitly rather than silently assumed). Written now, reviewable now, exactly like
// every "engine adapter written but uncalled" precedent used earlier in the AE track.

// Situation Analysis stage: an inclusion-only summary over AiSituationSnapshot's own fields — never
// a second data-collection pass. `null`/empty config means "include everything," matching the
// built-in Planner's own AE5 default.
const summarizeAiAlgorithmSituation = (config: AiAlgorithmSituationAnalysisConfig | null, snapshot: AiSituationSnapshot): string => {
  const sources = config?.informationSources?.length ? config.informationSources : AI_ALGORITHM_SITUATION_INFO_SOURCES;
  const parts: string[] = [`Day ${snapshot.day}, ${snapshot.daysRemaining} days remaining.`];
  if (sources.includes('finances')) parts.push(`$${Math.round(snapshot.spendableCash)} spendable, ${snapshot.economicPhase} phase.`);
  if (sources.includes('inventory')) parts.push(`Inventory: ${snapshot.inventory.length ? snapshot.inventory.join(', ') : 'empty'}.`);
  if (sources.includes('resource_prices')) parts.push(`Tracking ${Object.keys(snapshot.resourcePrices).length} resource prices.`);
  if (sources.includes('weather_events')) parts.push(`Weather: ${snapshot.weather}, ${snapshot.activeEventCount} active event(s).`);
  if (sources.includes('treasury') && snapshot.treasuryAvailable !== null) parts.push(`Treasury available: $${Math.round(snapshot.treasuryAvailable)}.`);
  if (sources.includes('teammates')) parts.push(`${snapshot.teammateIds.length} teammate(s).`);
  if (sources.includes('opponents')) parts.push(`${snapshot.opponentIds.length} opponent(s).`);
  if (sources.includes('regional_control')) parts.push(`Regions controlled: ${snapshot.regionsControlled}.`);
  if (sources.includes('win_condition')) parts.push(`${snapshot.winCondition}: ${Math.round(snapshot.ownMetricValue)} vs opponent ${Math.round(snapshot.opponentMetricValue)}.`);
  return parts.join(' ');
};

// Goal Selection stage: when the player has configured explicit weights, primary = the
// highest-weighted goal (ties broken by AI_PLANNER_GOAL_KINDS' own declared order), secondary =
// every other nonzero-weighted goal (highest first). Falls back to the built-in Planner's own
// selectAiPlannerGoals (AE5) — reused, never re-derived — whenever no weights are configured.
const selectAiAlgorithmGoals = (config: AiAlgorithmGoalSelectionConfig | null, snapshot: AiSituationSnapshot): AiPlannerGoalSelection => {
  const weighted = AI_PLANNER_GOAL_KINDS
    .map(kind => ({ kind, weight: config?.goalPriorities?.[kind] || 0 }))
    .filter(entry => entry.weight > 0)
    .sort((a, b) => b.weight - a.weight);
  if (weighted.length === 0) return selectAiPlannerGoals(snapshot);
  return { primary: weighted[0].kind, secondary: weighted.slice(1).map(entry => entry.kind) };
};

// Candidate Generation stage: a thin allow-list filter over the SAME candidates
// generatePlannerCandidates (AE6) already produced via getRankedTeamAiDecisions — never a second
// candidate-generation pass. Empty/absent allowedActionCategories means "no restriction."
const filterAiAlgorithmCandidates = (config: AiAlgorithmCandidateGenerationConfig | null, candidates: ScoredTeamAiDecision[]): ScoredTeamAiDecision[] => {
  if (!config?.allowedActionCategories?.length) return candidates;
  const allowed = new Set(config.allowedActionCategories);
  return candidates.filter(candidate => allowed.has(candidate.type as TeamModeActionCategory));
};

// AB3: three more pure stage-evaluator functions, same "uncalled by any real turn-execution path
// this phase" status as AB2's — each parameterizes an already-existing AE6/AE7 pure function
// rather than re-deriving its logic.

// Outcome Prediction stage: reuses predictAiCandidateOutcome (AE6) verbatim for the actual
// expected/worst-case text, adding only an interpretive risk note driven by the configured
// behavior — never a second probability/EV calculation.
const predictAiAlgorithmCandidateOutcome = (config: AiAlgorithmOutcomePredictionConfig | null, candidate: ScoredTeamAiDecision): AiCandidateOutcomePrediction & { riskNote: string } => {
  const base = predictAiCandidateOutcome(candidate);
  const behavior = config?.riskBehavior || 'balanced';
  const riskNote = behavior === 'conservative'
    ? `Conservative: weighs the worst case (${base.worstCaseOutcome}) heavily before proceeding.`
    : behavior === 'aggressive'
    ? `Aggressive: favors the expected upside (${base.expectedOutcome}) even if the worst case is costly.`
    : `Balanced: weighs expected and worst-case outcomes evenly.`;
  return { ...base, riskNote };
};

// Plan Construction stage: reuses constructAiPlan (AE7) verbatim, only parameterizing its depth
// input and, per maxCandidatesConsidered, truncating the candidate list BEFORE handing it to
// constructAiPlan — never re-implementing plan-building logic.
const constructAiAlgorithmPlan = (config: AiAlgorithmPlanConstructionConfig | null, candidates: ScoredTeamAiDecision[]): ScoredTeamAiDecision[] => {
  const depth = config?.planningDepth || 'balanced';
  const limit = config?.maxCandidatesConsidered && config.maxCandidatesConsidered > 0
    ? Math.min(config.maxCandidatesConsidered, AI_ALGORITHM_MAX_CANDIDATES_CONSIDERED)
    : candidates.length;
  return constructAiPlan(candidates.slice(0, limit), depth);
};

// Utility Evaluation stage: identical shape to evaluateAiPlanUtility (AE7), reading the SAME
// shared AI_PLANNER_GOAL_CATEGORY_MAP — the only difference is a player-configurable bonus
// magnitude in place of the built-in Planner's own fixed +20 (which stays untouched).
const evaluateAiAlgorithmPlanUtility = (config: AiAlgorithmUtilityEvaluationConfig | null, plan: ScoredTeamAiDecision[], goals: AiPlannerGoalSelection): number => {
  const bonus = typeof config?.goalServedBonus === 'number' ? Math.max(0, Math.min(100, config.goalServedBonus)) : 20;
  const relevantCategories = new Set<string>([
    ...(AI_PLANNER_GOAL_CATEGORY_MAP[goals.primary] || []),
    ...goals.secondary.flatMap(g => AI_PLANNER_GOAL_CATEGORY_MAP[g] || [])
  ]);
  return plan.reduce((total, step) => total + (step.score || 0) + (relevantCategories.has(step.type) ? bonus : 0), 0);
};

// AB4: the final four pure stage-evaluator functions, completing the 10-stage pipeline. Same
// "uncalled by any real turn-execution path this phase" status as AB2/AB3's — no custom-algorithm
// execution engine exists yet to invoke any of these.

// Action Selection stage: 'highest_score' takes the plan's own first step as-is (the built-in
// Planner's own AE8 behavior); 'highest_utility' re-sorts the SAME plan's steps by their already-
// computed .score before picking the first — a selection-order choice over existing scores, never
// a second scoring pass.
const selectAiAlgorithmAction = (config: AiAlgorithmActionSelectionConfig | null, plan: ScoredTeamAiDecision[]): ScoredTeamAiDecision | null => {
  if (plan.length === 0) return null;
  if (config?.method === 'highest_utility') {
    return [...plan].sort((a, b) => (b.score || 0) - (a.score || 0))[0];
  }
  return plan[0];
};

// Replanning stage: a pure yes/no over whether to discard an in-progress multi-step plan and
// build fresh this turn — the actual continuation/discard mechanics reuse AE9's own
// aiPlannerActivePlanRef machinery once this is wired into a real execution engine; this function
// only answers the policy question.
const shouldReplanAiAlgorithm = (config: AiAlgorithmReplanningConfig | null): boolean => {
  return Boolean(config?.replanEveryTurn);
};

// Fallback Behavior stage: given the already-generated candidate list and the one that just
// failed pre-execution revalidation (the same check AE9 already performs), either walk the list
// for the next legal candidate or signal "abandon" so the caller hands off to the mandatory AE4
// fallback chain (custom -> Planner -> Classic) immediately. Never itself bypasses that chain.
const resolveAiAlgorithmFallbackCandidate = (config: AiAlgorithmFallbackBehaviorConfig | null, candidates: ScoredTeamAiDecision[], invalidCandidate: ScoredTeamAiDecision): ScoredTeamAiDecision | null => {
  if ((config?.onInvalidCandidate || 'try_next_candidate') === 'abandon_immediately') return null;
  const nextIndex = candidates.indexOf(invalidCandidate) + 1;
  return candidates[nextIndex] || null;
};

// Explanation Output stage: reuses explainAiPlannerDecision (AE8) verbatim for the standard
// sentence, only varying how much is appended around it — never a second explanation generator.
const explainAiAlgorithmDecision = (config: AiAlgorithmExplanationOutputConfig | null, selected: ScoredTeamAiDecision, plan: ScoredTeamAiDecision[], goals: AiPlannerGoalSelection): string => {
  const base = explainAiPlannerDecision(selected, plan, goals);
  const detailLevel = config?.detailLevel || 'standard';
  if (detailLevel === 'brief') return `Chose ${selected.type}.`;
  if (detailLevel === 'verbose') {
    return `${base} Secondary goals considered: ${goals.secondary.length ? goals.secondary.join(', ') : 'none'}. Score: ${Math.round(selected.score || 0)}.`;
  }
  return base;
};

