/**
 * Evaluates whether an active takeover session should prompt the user for confirmation before performing manual gameplay intervention.
 */
export function shouldPromptCoPilotTakeoverIntervention(
  takeoverSession: CoPilotTakeoverSession | null | undefined
): boolean {
  if (!takeoverSession) return false;
  if (typeof isCoPilotManuallyStopped === 'function' && isCoPilotManuallyStopped(takeoverSession)) return false;
  const status = takeoverSession.status;
  // Waiting for other actors is not a manual-control prompt: Quick Actions on turn-return
  // must not be able to accidentally latch Stop / PAUSED.
  return status === 'active' || status === 'active_player_turn' || status === 'executing' || status === 'planning' || status === 'replanning';
}

