export interface EffectiveCoPilotAuthorityResult {
  enabled: boolean;
  mode: CoPilotAuthorityMode;
  isExecuting: boolean;
  guardianBlocked: boolean;
  guardianBlockedReason?: string;
  spendingCapsEnforced: boolean;
  minimumCashReserveFloor: number;
  debtLimitsEnforced: boolean;
  activeLocks: string[];
  takeoverDurationIsolated: boolean;
  reason?: string;
}

export function resolveEffectiveCoPilotAuthority(
  arg1?: any,
  arg2?: any,
  arg3?: any
): EffectiveCoPilotAuthorityResult {
  let settings: Partial<CoPilotSettings> | any = undefined;
  let state: any = undefined;
  let player: any = undefined;

  if (arg1 && (arg1.gameSettings || arg1.players || arg1.day !== undefined || arg1.turnCounter !== undefined)) {
    state = arg1;
    player = arg2 || arg1.player || arg1.players?.[0];
    settings = arg3 || arg1.gameSettings?.coPilotSettings || arg1.coPilotSettings;
  } else {
    settings = arg1;
    state = arg2;
    player = arg2?.player || arg2?.players?.[0];
  }

  if (!settings && state?.gameSettings?.coPilotSettings) {
    settings = state.gameSettings.coPilotSettings;
  }

  const mode: CoPilotAuthorityMode = settings?.authorityMode || state?.gameSettings?.coPilotAuthorityMode || state?.coPilotAuthorityMode || 'off';
  const enabled = Boolean(settings?.coPilotEnabled ?? mode !== 'off');
  const executingModes: CoPilotAuthorityMode[] = ['ask_before_acting', 'automatic_rescue', 'full_co_pilot'];
  const isExecuting = enabled && executingModes.includes(mode);

  let guardianBlocked = false;
  let guardianBlockedReason: string | undefined = undefined;

  if (state) {
    try {
      const guardianSettings = createDefaultGuardianAiSettings();
      const evalCtx = {
        settings: guardianSettings,
        gameState: state,
        actorId: player?.id || 'player',
        actionType: 'evaluate_authority',
        actionPayload: {},
        source: 'human_direct' as const,
        day: state.day || 1,
        turn: state.turn || 1,
        currentActionTokens: player?.actionPoints || 3,
        currentCash: player?.money || 0,
        activeContracts: [],
        activeExpeditions: [],
        activePlans: [],
        isReplay: false
      };
      const guardianEval = evaluateGuardianRiskPipeline(evalCtx);
      if (guardianEval && (String(guardianEval.highestSeverity) === 'critical' || String(guardianEval.highestSeverity) === 'emergency' || String((guardianEval as any).overallRiskLevel) === 'emergency')) {
        guardianBlocked = true;
        guardianBlockedReason = 'Guardian AI Emergency Lockout';
      }
    } catch {
      // Safe fallback if state context is mock
    }
  }

  const spendingCapsEnforced = Boolean(settings?.spendingCaps);
  const minimumCashReserveFloor = settings?.spendingCaps?.minimumCashReserve ?? 1000;
  const debtLimitsEnforced = Boolean(settings?.spendingCaps?.maximumDebtIncrease != null);

  const activeLocks: string[] = [];
  if (settings?.categoryToggles) {
    for (const [cat, enabledFlag] of Object.entries(settings.categoryToggles)) {
      if (enabledFlag === false) {
        activeLocks.push(cat);
      }
    }
  }

  let reason = 'Normal authority resolved';
  if (!enabled) reason = 'Co-Pilot disabled';
  else if (guardianBlocked) reason = `Guardian AI Blocked: ${guardianBlockedReason}`;
  else if (activeLocks.length > 0) reason = `Active category locks: ${activeLocks.length}`;

  return {
    enabled,
    mode,
    isExecuting,
    guardianBlocked,
    guardianBlockedReason,
    spendingCapsEnforced,
    minimumCashReserveFloor,
    debtLimitsEnforced,
    activeLocks,
    takeoverDurationIsolated: true,
    reason
  };
}

export function validateCoPilotSessionToken(
  session: CoPilotTakeoverSession | null | undefined,
  callbackToken: string,
  actionToken?: string
): boolean {
  if (!session || session.status === 'interrupted' || session.status === 'terminated' || session.status === 'completed' || session.status === 'failed' || session.status === 'disabled') return false;
  if (!COPILOT_EXECUTABLE_STATUSES.includes(session.status) && session.status !== 'paused') return false;
  if (!callbackToken || session.sessionToken !== callbackToken) return false;
  if (actionToken && session.executedActionTokens && session.executedActionTokens.includes(actionToken)) {
    return false;
  }
  return true;
}

