  lastEvaluationTimestamp: number;
  evaluationCount: number;
  currentPlanId?: string;
  currentPlanStep?: number;
  totalPlanSteps?: number;
  planStatus?: string;
  lastExecutionTimestamp?: number;
  lastActionType?: string;
