export interface SettingsHubSearchEntry {
  id: string;
  tab: SettingsHubTabId;
  label: string;
  keywords: string;
  _searchText?: string;
  key?: string;
  category?: string;
  isSmartManaged?: boolean;
  isSection?: boolean;
  description?: string;
  tags?: SettingsHubTag[];
  chips?: SettingsHubChip[];
  advancedOnly?: boolean;
  sectionTitle?: string;
  title?: string;
  minLevel?: SettingsExperienceLevel;
  sectionId?: string;
}

// SH1: Convert camelCase setting key into space-delimited humanized terms for search indexing.
const humanizeSettingKey = (key: string): string => key.replace(/(?<!^)(?=[A-Z])/g, ' ');

// SH1: Settings Hub Search Index with complete Haystack Folding across fields, sections, raw keys, and humanized terms.
export function buildSettingsHubSearchIndex(): SettingsHubSearchEntry[] {
  const entries: SettingsHubSearchEntry[] = [];
  
  // SH1: Fold raw keys, humanized keys, labels, descriptions, tags, and chips for field metadata entries.
  Object.values(SETTINGS_HUB_FIELD_META).forEach(meta => {
    const rawKey = meta.key;
    const humanizedKey = humanizeSettingKey(meta.key);
    const chipsStr = meta.chips ? meta.chips.join(' ') : '';
    const tagsStr = meta.tags ? meta.tags.join(' ') : '';
    const keywords = `${rawKey} ${humanizedKey} ${meta.label} ${meta.description} ${tagsStr} ${chipsStr}`.toLowerCase();
    const isSmartManaged = typeof isSmartSettingsManagedKey === 'function' ? isSmartSettingsManagedKey(meta.key) : false;
    const _searchText = `${rawKey} ${humanizedKey} ${meta.label} ${meta.description} ${tagsStr} ${chipsStr} ${meta.tab} ${keywords}`.toLowerCase();
    entries.push({
      id: meta.key,
      key: meta.key,
      tab: meta.tab,
      label: meta.label,
      description: meta.description,
      tags: meta.tags,
      chips: meta.chips,
      advancedOnly: meta.advancedOnly,
      category: meta.tags[0] || 'general',
      isSmartManaged,
      keywords,
      _searchText
    });
  });

  // Index all Smart Controllable Settings Registry entries
  if (typeof SMART_CONTROLLABLE_SETTINGS_REGISTRY !== 'undefined' && Array.isArray(SMART_CONTROLLABLE_SETTINGS_REGISTRY)) {
    SMART_CONTROLLABLE_SETTINGS_REGISTRY.forEach(def => {
      let existing = entries.find(e => e.key === def.key || e.id === def.key);
      if (existing) {
        existing.key = def.key;
        existing.category = def.category;
        existing.isSmartManaged = true;
        if (def.description) existing.description = def.description;
        existing._searchText = `${existing.id || ''} ${existing.key || ''} ${existing.label || ''} ${existing.description || ''} ${existing.category || ''} ${existing.tab || ''} ${(existing.tags || []).join(' ')} ${existing.keywords || ''}`.toLowerCase();
      } else {
        const rawKey = def.key;
        const humanizedKey = humanizeSettingKey(def.key);
        const keywords = `${rawKey} ${humanizedKey} ${def.label} ${def.description} ${def.category}`.toLowerCase();
        const _searchText = `${def.key} ${rawKey} ${humanizedKey} ${def.label} ${def.description} ${def.category} aiTeams ${keywords}`.toLowerCase();
        entries.push({
          id: def.key,
          key: def.key,
          tab: 'aiTeams',
          label: def.label,
          description: def.description,
          category: def.category,
          isSmartManaged: true,
          keywords,
          _searchText
        });
      }
    });
  }

  // SH1: Fold section titles, tags, explicit keywords, section chips, raw field keys, and humanized field key terms.
  SETTINGS_HUB_SECTION_INDEX.forEach(section => {
    const rawFieldKeys = section.fieldKeys.map(String).join(' ');
    const humanizedFieldKeys = section.fieldKeys.map(fk => humanizeSettingKey(String(fk))).join(' ');
    const chipsStr = section.chips ? section.chips.join(' ') : '';
    const tagsStr = section.tags ? section.tags.join(' ') : '';
    const keywords = `${section.title} ${tagsStr} ${section.keywords || ''} ${chipsStr} ${rawFieldKeys} ${humanizedFieldKeys}`.toLowerCase();
    const _searchText = `${section.id} ${section.title} ${section.keywords || ''} ${section.tab} ${tagsStr} ${chipsStr} ${rawFieldKeys} ${humanizedFieldKeys} ${keywords}`.toLowerCase();
    entries.push({
      id: section.id,
      tab: section.tab,
      title: section.title,
      sectionTitle: section.title,
      label: section.title,
      description: section.keywords || section.title,
      tags: section.tags,
      chips: section.chips,
      isSection: true,
      keywords,
      _searchText
    });
  });

  return entries;
}

const rawSearchIndexTarget: SettingsHubSearchEntry[] = [];
export const SETTINGS_HUB_SEARCH_INDEX: SettingsHubSearchEntry[] = new Proxy(rawSearchIndexTarget, {
  get(target, prop, receiver) {
    if (target.length === 0) {
      target.push(...buildSettingsHubSearchIndex());
    }
    return Reflect.get(target, prop, receiver);
  }
});

