export function evalSettingsSearchFilter(
  entry: SettingsHubSearchEntry,
  query: string,
  scope: SettingsSearchScope = 'all',
  stateFilters: SettingsStateFilter[] = [],
  featureFilters: SettingsFeatureFilter[] = [],
  availabilityFilters: SettingsAvailabilityFilter[] = [],
  gameSettings?: GameSettingsState,
  draftSettings?: Partial<GameSettingsState> | null,
  depReport?: any,
  isLiveMatch: boolean = false
): boolean {
  const q = (query || '').trim().toLowerCase();
  if (q.length > 0) {
    const tokens = q.split(/\s+/).filter(Boolean);
    let haystack = '';
    const rawKey = entry.key || entry.id;
    const humanizedKey = humanizeSettingKey(rawKey);

    switch (scope) {
      case 'label':
        haystack = (entry.label || '').toLowerCase();
        break;
      case 'description':
        haystack = (entry.description || '').toLowerCase();
        break;
      case 'key':
        haystack = `${rawKey} ${humanizedKey}`.toLowerCase();
        break;
      case 'category':
      case 'current_category':
        haystack = `${entry.category || ''} ${entry.tab || ''} ${SETTINGS_HUB_TAB_LABELS[entry.tab] || ''}`.toLowerCase();
        break;
      case 'section_names':
        haystack = `${entry.sectionTitle || ''} ${entry.sectionId || ''} ${entry.title || ''} ${entry.isSection ? entry.label || '' : ''}`.toLowerCase();
        break;
      case 'individual_settings':
        haystack = `${entry.label || ''} ${rawKey} ${humanizedKey} ${entry.description || ''}`.toLowerCase();
        break;
      case 'tags':
        haystack = (entry.tags || []).join(' ').toLowerCase();
        break;
      case 'all':
      default:
        haystack = `${entry.id} ${rawKey} ${humanizedKey} ${entry.label} ${entry.description || ''} ${entry.keywords || ''} ${entry.tags ? entry.tags.join(' ') : ''} ${SETTINGS_HUB_TAB_LABELS[entry.tab] || ''} ${entry.sectionTitle || ''} ${entry.sectionId || ''}`.toLowerCase();
        break;
    }

    const matchesAllTokens = tokens.every(token => haystack.includes(token));
    if (!matchesAllTokens) return false;
  }

  if (!q && stateFilters.length === 0 && featureFilters.length === 0 && availabilityFilters.length === 0) {
    return true;
  }

  const keyStr = entry.key || entry.id;
  const currentSettingsObj = (draftSettings && Object.keys(draftSettings).length > 0)
    ? { ...gameSettings, ...draftSettings }
    : gameSettings;

  const defaultVal = DEFAULT_GAME_SETTINGS[keyStr as keyof GameSettingsState];
  const curVal = currentSettingsObj ? (currentSettingsObj as any)[keyStr] : undefined;
  const isModified = defaultVal !== undefined && curVal !== undefined && (typeof settingsValuesEqual === 'function' ? !settingsValuesEqual(curVal, defaultVal) : curVal !== defaultVal);

  if (stateFilters.length > 0) {
    const matchesState = stateFilters.every(sf => {
      switch (sf) {
        case 'modified':
          return isModified;
        case 'default':
          return !isModified;
        case 'locked':
          return Boolean(entry.isSmartManaged || (gameSettings?.smartSettingsProfile?.lockedSettingKeys || []).includes(keyStr as keyof GameSettingsState));
        case 'overridden':
          return (gameSettings?.smartSettingsProfile?.manualOverrides || []).some(o => o.settingKey === keyStr);
        case 'system':
          return entry.tab === 'oversight' || entry.tab === 'replayDiag';
        case 'custom':
          return isModified;
        case 'smart_managed':
          return Boolean(entry.isSmartManaged || (typeof isSmartSettingsManagedKey === 'function' && isSmartSettingsManagedKey(keyStr)));
        case 'inert':
          return Boolean(depReport && depReport.violations && depReport.violations.some((v: any) => v.settingKey === keyStr));
        case 'active':
          return curVal === true || (typeof curVal === 'number' && curVal > 0) || (typeof curVal === 'string' && curVal !== 'classic' && curVal !== 'off');
        case 'conflicted':
          return Boolean(depReport && depReport.conflicts && depReport.conflicts.some((c: any) => c.settingA === keyStr || c.settingB === keyStr));
        case 'has_warning':
          return Boolean(depReport && ((depReport.violations && depReport.violations.some((v: any) => v.settingKey === keyStr)) || (depReport.conflicts && depReport.conflicts.some((c: any) => c.settingA === keyStr || c.settingB === keyStr))));
        case 'basic_only':
          return !entry.advancedOnly;
        case 'advanced_only':
          return Boolean(entry.advancedOnly);
        case 'experimental':
          return Boolean((entry.chips || []).includes('Experimental') || (entry.tags || []).includes('Experimental') || (entry.chips || []).includes('Extreme'));
        case 'restart_required':
          return Boolean(entry.tab === 'quickSetup' || keyStr === 'totalDays' || keyStr === 'winCondition');
        case 'preset_controlled':
          return Boolean(gameSettings?.uxAssistPackEnabled && gameSettings?.settingsPresetsEnabled);
        case 'unsaved':
          if (!draftSettings) return false;
          const appliedVal = gameSettings ? (gameSettings as any)[keyStr] : undefined;
          const draftVal = (draftSettings as any)[keyStr];
          return draftVal !== undefined && (typeof settingsValuesEqual === 'function' ? !settingsValuesEqual(draftVal, appliedVal) : draftVal !== appliedVal);
        default:
          return true;
      }
    });
    if (!matchesState) return false;
  }

  if (featureFilters.length > 0) {
    const entryTags = entry.tags || [];
    const entryTab = entry.tab;
    const matchesFeature = featureFilters.some(ff => {
      switch (ff) {
        case 'ux_assist':
          return entryTab === 'interfaceAcc' || entryTags.includes('UX') || entryTags.includes('Presets');
        case 'ai_behavior':
          return entryTab === 'aiTeams' || entryTags.includes('AI');
        case 'team_brain':
          return entryTags.includes('Team Mode') || entry.keywords.includes('brain');
        case 'economy':
          return entryTab === 'economy' || entryTags.includes('Economy');
        case 'loans_credit':
          return entryTags.includes('Loans') || entry.keywords.includes('loan');
        case 'sabotage':
          return entryTags.includes('Sabotage') || entry.keywords.includes('sabotage');
        case 'investments':
          return entryTags.includes('Economy') || entry.keywords.includes('investment');
        case 'regional_control':
          return entryTab === 'competition' || entryTags.includes('Travel');
        case 'negotiations':
          return entry.keywords.includes('negotiation');
        case 'automation':
          return entryTab === 'automation' || entryTags.includes('Automation');
        case 'governance':
          return entryTab === 'oversight' || entryTags.includes('Core');
        case 'replay_safety':
          return entryTab === 'replayDiag' || entryTags.includes('Replay');
        case 'diagnostics':
          return entryTags.includes('Diagnostics');
        case 'accessibility':
          return entryTags.includes('Accessibility');
        case 'appearance':
          return keyStr === 'teamOverviewDensity' || entry.keywords.includes('theme') || entry.keywords.includes('appearance');
        case 'notifications':
          return entryTags.includes('Notifications') || entry.keywords.includes('notification');
        case 'win_conditions':
          return keyStr === 'winCondition' || entry.tab === 'quickSetup';
        case 'action_limits':
          return keyStr === 'actionLimitsEnabled' || entry.keywords.includes('action limit');
        default:
          return true;
      }
    });
    if (!matchesFeature) return false;
  }

  if (availabilityFilters.length > 0) {
    const matchesAvailability = availabilityFilters.some(af => {
      switch (af) {
        case 'all_modes':
          return true;
        case 'live_match_only':
          return isLiveMatch;
        case 'pre_match_only':
          return !isLiveMatch || keyStr === 'totalDays' || keyStr === 'winCondition';
        case 'singleplayer':
          return true;
        case 'multiplayer':
          return Boolean(gameSettings?.teamModeAiSystemsEnabled);
        case 'co_pilot_active':
          return Boolean(gameSettings?.coPilotSettings?.coPilotEnabled || gameSettings?.humanAutomationEnabled);
        case 'overseer_active':
          return Boolean(gameSettings?.teamAiOverseerSystemEnabled);
        case 'sandbox_only':
          return Boolean(gameSettings?.balanceLabSandboxMode);
        case 'developer_only':
          return Boolean(entry.advancedOnly || entry.tags?.includes('Diagnostics'));
        case 'unlocked_by_career':
          return true;
        case 'requires_ux_pack':
          return Boolean(gameSettings?.uxAssistPackEnabled);
        case 'requires_team_mode':
          return Boolean(gameSettings?.teamModeAiSystemsEnabled);
        default:
          return true;
      }
    });
    if (!matchesAvailability) return false;
  }

  return true;
}

export function assertSettingsHubBiDirectionalCoverage(): void {
  if (typeof process !== 'undefined' && (process as any)?.env?.NODE_ENV !== 'production') {
    const coveredFieldKeys = new Set<keyof GameSettingsState>();
    SETTINGS_HUB_SECTION_INDEX.forEach(section => {
      section.fieldKeys.forEach(fk => coveredFieldKeys.add(fk as keyof GameSettingsState));
    });

    const uncoveredKeys = Object.keys((typeof DEFAULT_GAME_SETTINGS !== "undefined" && DEFAULT_GAME_SETTINGS as any) || {}).filter(
      k => !coveredFieldKeys.has(k as keyof GameSettingsState)
    );

    const phantomKeys = Array.from(coveredFieldKeys).filter(
      k => !(k in DEFAULT_GAME_SETTINGS)
    );

    if (uncoveredKeys.length > 0) {
      console.warn(
        `[Settings Hub Assertion Warning] ${uncoveredKeys.length} key(s) in DEFAULT_GAME_SETTINGS are not mapped to any section in SETTINGS_HUB_SECTION_INDEX:`,
        uncoveredKeys
      );
    }

    if (phantomKeys.length > 0) {
      console.warn(
        `[Settings Hub Assertion Warning] ${phantomKeys.length} key(s) in SETTINGS_HUB_SECTION_INDEX fieldKeys do not exist in DEFAULT_GAME_SETTINGS:`,
        phantomKeys
      );
    }
  }
}

