export function getDiplomaticStanceFromTrustScore(trustScore: TrustScore): DiplomaticStance {
  if (trustScore >= 80) return 'allied';
  if (trustScore >= 40) return 'neutral';
  if (trustScore >= 20) return 'suspicious';
  if (trustScore >= 1) return 'rival';
  return 'nemesis';
}

