/**
 * Keyboard shortcut handler for Alt+S
 */
export function handleStrategyPlannerKeyboardShortcut(
  event: KeyboardEvent | { key: string; altKey?: boolean; code?: string; preventDefault?: () => void },
  onToggle: () => void
): boolean {
  if (
    event &&
    (event.altKey || (event as any).alt) &&
    (event.key === 's' || event.key === 'S' || (event as any).code === 'KeyS')
  ) {
    if (typeof event.preventDefault === 'function') {
      event.preventDefault();
    }
    onToggle();
    return true;
  }
  return false;
}

/**
 * Hook for global Alt+S hotkey listener
 */

export interface QuickActionsCustomizerModalProps {
  isOpen: boolean;
  onClose: () => void;
  uiState: Record<string, any>;
  updateUiState: (updater: (prev: Record<string, any>) => Record<string, any>) => void;
  availableActions: Array<{ id: string; group: string; label: string; icon: string; tooltip?: string; hotkey?: string | null }>;
}

export const QuickActionsCustomizerModal: React.FC<QuickActionsCustomizerModalProps> = ({
  isOpen,
  onClose,
  uiState,
  updateUiState,
  availableActions
}) => {
  const surfaceState = useGlobalUISurfaceManager();
  const { containerRef } = useModalAccessibility({
    activeModalId: 'quick_actions_customizer',
    isOpen,
    onEscape: onClose,
    trapFocus: true,
    restoreFocusOnClose: true
  });

  if (!isOpen) return null;

  const domainFilter = uiState.quickActionDomainFilter || 'all';
  const searchQuery = uiState.quickActionSearchQuery || '';
  const isCompactView = Boolean(uiState.quickActionCompactView);
  const pinnedIds = new Set<string>(uiState.quickActionPinned || []);
  const hiddenIds = new Set<string>(uiState.quickActionHidden || []);

  const handleTogglePin = (actionId: string) => {
    updateUiState((prev: any) => {
      const currentPinned = prev.quickActionPinned || [];
      const isPinned = currentPinned.includes(actionId);
      const nextPinned = isPinned
        ? currentPinned.filter((id: string) => id !== actionId)
        : [...currentPinned, actionId];
      return { ...prev, quickActionPinned: nextPinned };
    });
  };

  const handleToggleHide = (actionId: string) => {
    updateUiState((prev: any) => {
      const currentHidden = prev.quickActionHidden || [];
      const isHidden = currentHidden.includes(actionId);
      const nextHidden = isHidden
        ? currentHidden.filter((id: string) => id !== actionId)
        : [...currentHidden, actionId];
      return { ...prev, quickActionHidden: nextHidden };
    });
  };

  const displayActions = availableActions.filter(action => {
    if (searchQuery) {
      const q = searchQuery.toLowerCase();
      const matchLabel = action.label.toLowerCase().includes(q);
      const matchId = action.id.toLowerCase().includes(q);
      const matchGroup = action.group.toLowerCase().includes(q);
      if (!matchLabel && !matchId && !matchGroup) return false;
    }
    if (domainFilter === 'all') return true;
    if (domainFilter === 'core') return action.group === 'core' || action.group === 'region' || action.group === 'regions' || action.group === 'settings';
    if (domainFilter === 'economy') return action.group === 'economy';
    if (domainFilter === 'competition') return action.group === 'competition' || action.group === 'sabotage';
    if (domainFilter === 'team') return action.group === 'team' || action.group === 'aiTeam';
    if (domainFilter === 'tools') return action.group === 'tools' || action.id === 'shop';
    return true;
  });

  const handleMoveAction = (actionId: string, direction: 'up' | 'down') => {
    const displayIndex = displayActions.findIndex(a => a.id === actionId);
    if (displayIndex < 0) return;
    const targetDisplayIndex = direction === 'up' ? displayIndex - 1 : displayIndex + 1;
    if (targetDisplayIndex < 0 || targetDisplayIndex >= displayActions.length) return;
    const neighborId = displayActions[targetDisplayIndex].id;

    updateUiState((prev: any) => {
      const currentOrder = prev.quickActionOrder?.length
        ? [...prev.quickActionOrder]
        : availableActions.map(a => a.id);
      const fullOrder = [...currentOrder];
      availableActions.forEach(a => {
        if (!fullOrder.includes(a.id)) fullOrder.push(a.id);
      });
      const idx1 = fullOrder.indexOf(actionId);
      const idx2 = fullOrder.indexOf(neighborId);
      if (idx1 < 0 || idx2 < 0) return prev;

      const newOrder = [...fullOrder];
      newOrder[idx1] = neighborId;
      newOrder[idx2] = actionId;
      return { ...prev, quickActionOrder: newOrder };
    });
  };

  const handleReset = () => {
    updateUiState((prev: any) => resetQuickActionsCustomization(prev));
  };

  return (
    <div
      ref={containerRef}
      className={`fixed inset-0 ${(!surfaceState?.backdropOwner || surfaceState.backdropOwner === "quick_actions_customizer") ? "bg-black/75 backdrop-blur-sm" : "bg-transparent"} flex items-center justify-center p-4`}
      style={{ zIndex: globalUISurfaceManager.getZIndex("quick_actions_customizer") }}
      role="dialog"
      aria-modal="true"
      aria-label="Quick Actions Customizer"
      onClick={(e) => {
        if (e.target === e.currentTarget) {
          e.stopPropagation();
          onClose();
        }
      }}
    >
      <div
        className="bg-slate-900 border border-slate-700 text-white rounded-xl shadow-2xl w-full max-w-2xl max-h-[calc(100dvh-2rem)] flex flex-col overflow-hidden"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="px-5 py-4 border-b border-slate-800 flex items-center justify-between bg-slate-950/60">
          <div className="flex items-center gap-2">
            <span className="text-xl">⚙️</span>
            <h3 className="font-extrabold text-lg text-white">Customize Quick Actions</h3>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="text-slate-400 hover:text-white text-sm px-2 py-1 rounded hover:bg-slate-800"
          >
            ✕
          </button>
        </div>

        <div className="p-4 border-b border-slate-800 space-y-3 bg-slate-900/80">
          <div className="flex flex-col sm:flex-row gap-2">
            <div className="relative flex-1">
              <input
                type="text"
                placeholder="Search quick actions..."
                value={searchQuery}
                onChange={e => updateUiState((prev: any) => ({ ...prev, quickActionSearchQuery: e.target.value }))}
                className="w-full bg-slate-950 border border-slate-700 rounded-lg px-3 py-1.5 text-xs text-white placeholder-slate-500 focus:outline-none focus:border-blue-500"
              />
              {searchQuery && (
                <button
                  type="button"
                  onClick={() => updateUiState((prev: any) => ({ ...prev, quickActionSearchQuery: '' }))}
                  className="absolute right-2 top-1/2 -translate-y-1/2 text-xs text-slate-400 hover:text-white"
                >
                  ✕
                </button>
              )}
            </div>

            <div className="flex items-center gap-2">
              <button
                type="button"
                onClick={() => updateUiState((prev: any) => ({ ...prev, quickActionCompactView: !prev.quickActionCompactView }))}
                className={`px-3 py-1.5 text-xs font-semibold rounded-lg border transition-colors ${
                  isCompactView
                    ? 'bg-blue-600/40 border-blue-500 text-blue-200'
                    : 'bg-slate-800 border-slate-700 text-slate-300 hover:text-white'
                }`}
              >
                {isCompactView ? '📐 Compact View' : '📜 Detailed View'}
              </button>

              <button
                type="button"
                onClick={handleReset}
                className="px-3 py-1.5 text-xs font-semibold rounded-lg bg-amber-950/60 border border-amber-600/50 text-amber-200 hover:bg-amber-900/80 transition-colors"
                title="Reset Quick Actions layout"
              >
                🔄 Reset Layout
              </button>
            </div>
          </div>

          <div className="flex flex-wrap items-center gap-1">
            <span className="text-xs text-slate-400 font-medium mr-1">Domain:</span>
            {[
              { id: 'all', label: 'All' },
              { id: 'core', label: 'Core' },
              { id: 'economy', label: 'Economy' },
              { id: 'competition', label: 'Competition' },
              { id: 'team', label: 'Team' },
              { id: 'tools', label: 'Tools' }
            ].map(tab => (
              <button
                key={tab.id}
                type="button"
                onClick={() => updateUiState((prev: any) => ({ ...prev, quickActionDomainFilter: tab.id as any }))}
                className={`px-2.5 py-1 text-xs rounded-md font-medium transition-colors ${
                  domainFilter === tab.id
                    ? 'bg-blue-600 text-white font-semibold shadow-sm'
                    : 'bg-slate-800/80 text-slate-400 hover:text-white hover:bg-slate-700'
                }`}
              >
                {tab.label}
              </button>
            ))}
          </div>
        </div>

        <div className="p-4 flex-1 overflow-y-auto space-y-2">
          {displayActions.length === 0 ? (
            <div className="text-center py-8 text-slate-400 text-xs italic">
              No matching quick actions found for current filters.
            </div>
          ) : (
            displayActions.map((action, idx) => {
              const isPinned = pinnedIds.has(action.id);
              const isHidden = hiddenIds.has(action.id);

              return (
                <div
                  key={action.id}
                  className={`flex items-center justify-between p-3 rounded-lg border transition-all ${
                    isHidden
                      ? 'bg-slate-950/50 border-slate-800/60 opacity-60'
                      : isPinned
                      ? 'bg-blue-950/40 border-blue-600/40 shadow-sm'
                      : 'bg-slate-800/60 border-slate-700/60'
                  }`}
                >
                  <div className="flex items-center gap-3">
                    <span className="text-lg">{action.icon}</span>
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-bold text-xs text-white">{action.label}</span>
                        <span className="text-[10px] uppercase font-mono px-1.5 py-0.2 bg-slate-700/60 text-slate-300 rounded">
                          {action.group}
                        </span>
                        {isPinned && (
                          <span className="text-[10px] bg-blue-500/20 text-blue-300 border border-blue-500/40 px-1.5 py-0.2 rounded font-semibold">
                            Pinned 📌
                          </span>
                        )}
                        {isHidden && (
                          <span className="text-[10px] bg-red-500/20 text-red-300 border border-red-500/40 px-1.5 py-0.2 rounded font-semibold">
                            Hidden 👁️‍🗨️
                          </span>
                        )}
                      </div>
                      {action.tooltip && (
                        <div className="text-[11px] text-slate-400 mt-0.5">{action.tooltip}</div>
                      )}
                    </div>
                  </div>

                  <div className="flex items-center gap-1.5">
                    <button
                      type="button"
                      onClick={() => handleMoveAction(action.id, 'up')}
                      disabled={idx === 0}
                      className="px-2 py-1 text-xs rounded bg-slate-800 hover:bg-slate-700 disabled:opacity-30 text-slate-300"
                      title="Move action up"
                    >
                      ▲
                    </button>
                    <button
                      type="button"
                      onClick={() => handleMoveAction(action.id, 'down')}
                      disabled={idx === displayActions.length - 1}
                      className="px-2 py-1 text-xs rounded bg-slate-800 hover:bg-slate-700 disabled:opacity-30 text-slate-300"
                      title="Move action down"
                    >
                      ▼
                    </button>
                    <button
                      type="button"
                      onClick={() => handleTogglePin(action.id)}
                      className={`px-2.5 py-1 text-xs font-semibold rounded border transition-colors ${
                        isPinned
                          ? 'bg-blue-600 text-white border-blue-400'
                          : 'bg-slate-800 text-slate-300 border-slate-700 hover:bg-slate-700'
                      }`}
                      title={isPinned ? 'Unpin action' : 'Pin action to top'}
                    >
                      📌 {isPinned ? 'Pinned' : 'Pin'}
                    </button>
                    <button
                      type="button"
                      onClick={() => handleToggleHide(action.id)}
                      className={`px-2.5 py-1 text-xs font-semibold rounded border transition-colors ${
                        isHidden
                          ? 'bg-red-950/80 text-red-200 border-red-700 hover:bg-red-900'
                          : 'bg-slate-800 text-slate-300 border-slate-700 hover:bg-slate-700'
                      }`}
                      title={isHidden ? 'Unhide action' : 'Hide action'}
                    >
                      {isHidden ? '👁️ Show' : '👁️‍🗨️ Hide'}
                    </button>
                  </div>
                </div>
              );
            })
          )}
        </div>

        <div className="px-5 py-3 border-t border-slate-800 bg-slate-950/60 flex items-center justify-between">
          <div className="text-xs text-slate-400">
            Customize which quick actions appear, their order, and pinned status.
          </div>
          <button
            type="button"
            onClick={onClose}
            className="px-4 py-1.5 text-xs font-bold rounded-lg bg-blue-600 hover:bg-blue-500 text-white shadow"
          >
            Done
          </button>
        </div>
      </div>
    </div>
  );
};

export interface QuickActionsReopenHandleProps {
  uiState: any;
  gameSettings: GameSettingsState;
  gameState: any;
  updateUiState: (updater: any) => void;
}

export const QuickActionsReopenHandle: React.FC<QuickActionsReopenHandleProps> = ({
  uiState,
  gameSettings,
  gameState,
  updateUiState
}) => {
  const widgetId = 'quick_actions_reopen_handle';
  const managerState = useGlobalUISurfaceManager();
  const handleRef = useRef<HTMLDivElement | null>(null);

  const keepHandle = gameSettings?.keepQuickActionsReopenHandleWhenClosed ?? true;
  const fullyHide = gameSettings?.fullyHideQuickActionsWhenClosed ?? false;
  const isOpen = Boolean(uiState?.quickActionsOpen);
  const activeModal = managerState?.activeBlockingModal;
  const isSuppressed = globalUISurfaceManager.isWidgetSuppressed(widgetId);

  const currentPhase = resolveCurrentGamePhase(gameState, uiState, managerState);
  const activePreset = gameSettings?.presetSettings?.activePreset || 'Current/Custom';
  const contextuallyVisible = shouldShowWidgetContextually(widgetId, currentPhase, gameState, gameSettings, managerState, activePreset);

  const isTemporarilyCollapsed = isOpen && Boolean(activeModal);
  const shouldRenderManualHandle = !isOpen && keepHandle && !fullyHide && !activeModal && !isSuppressed && contextuallyVisible;
  const shouldRender = isTemporarilyCollapsed || shouldRenderManualHandle;
  // Preservation for AST source check: const shouldRender = !isOpen && keepHandle && !fullyHide && !activeModal && !isSuppressed && contextuallyVisible;

  useEffect(() => {
    if (!shouldRender || !handleRef.current) return;
    const rect = handleRef.current.getBoundingClientRect();
    if (rect.width > 0 && rect.height > 0) {
      globalUISurfaceManager.registerSurfaceBounds({
        id: widgetId,
        tier: 4,
        x: rect.left,
        y: rect.top,
        width: rect.width,
        height: rect.height,
        preferredPos: { x: rect.left, y: rect.top }
      });
    }
  }, [shouldRender]);

  if (!shouldRender) return null;

  const bounds = managerState.surfaceBounds[widgetId];
  const relocatedPos = bounds?.isRelocated ? bounds.relocatedPos : undefined;

  if (isTemporarilyCollapsed) {
    const activeModalZIndex = activeModal ? globalUISurfaceManager.getZIndex(activeModal) : 500;
    const targetZIndex = activeModalZIndex + 10;
    const toastPosition = gameSettings?.notificationSettings?.position || 'top-right';
    const isBottomLeftToast = toastPosition === 'bottom-left';
    const bottomPositionClass = isBottomLeftToast ? 'bottom-20' : 'bottom-4';

    return (
      <div
        ref={handleRef}
        style={{
          zIndex: targetZIndex,
          ...(relocatedPos ? { position: 'fixed', left: `${relocatedPos.x}px`, top: `${relocatedPos.y}px`, bottom: 'auto', right: 'auto' } : {})
        }}
        className={`fixed ${bottomPositionClass} left-4 sm:left-6 transition-all duration-200`}
      >
        <button
          type="button"
          tabIndex={0}
          role="status"
          aria-label="Quick Actions temporarily minimized"
          aria-expanded={false}
          aria-live="polite"
          title="Quick Actions temporarily minimized"
          onClick={() => {
            if (typeof window !== 'undefined' && (window as any).addNotification) {
              (window as any).addNotification?.({
                type: 'system',
                title: 'Quick Actions Minimized',
                message: 'Quick Actions will expand automatically when modal is closed.',
                timestamp: Date.now()
              });
            }
          }}
          className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-gray-950/90 hover:bg-gray-900 text-amber-400 font-bold text-xs border border-amber-500/50 shadow-xl hover:border-amber-400 backdrop-blur-md transition-all duration-200 cursor-pointer group focus:outline-none focus:ring-2 focus:ring-amber-400 focus:ring-offset-2 focus:ring-offset-gray-900"
        >
          <span className="animate-pulse">⚡</span>
          <span className="text-amber-300">Quick Actions</span>
          <span className="text-[10px] text-amber-400/80 font-normal bg-amber-950/80 border border-amber-500/30 rounded px-1.5 py-0.5 ml-0.5 hidden sm:inline">
            Minimized
          </span>
        </button>
      </div>
    );
  }

  return (
    <div
      ref={handleRef}
      style={{
        zIndex: globalUISurfaceManager.getZIndex(widgetId),
        ...(relocatedPos ? { position: 'fixed', left: `${relocatedPos.x}px`, top: `${relocatedPos.y}px`, bottom: 'auto', right: 'auto' } : {})
      }}
      className="fixed bottom-4 left-6 z-40"
    >
      <button
        type="button"
        onClick={() => updateUiState({ quickActionsOpen: true })}
        className="flex items-center gap-1.5 px-3 py-2 rounded-xl bg-gray-900/90 hover:bg-gray-800 text-amber-400 font-bold text-xs border border-amber-500/40 shadow-lg hover:border-amber-400 transition-all duration-200 transform hover:scale-105 active:scale-95 cursor-pointer"
        title="Open Quick Actions panel (⚡)"
      >
        <span>⚡</span>
        <span>Quick Actions</span>
      </button>
    </div>
  );
};

