export function getMinLevelForSetting(keyOrItem: string | any): SettingsExperienceLevel {
  if (typeof keyOrItem === 'object' && keyOrItem?.minLevel) return keyOrItem.minLevel;
  const key = typeof keyOrItem === 'string' ? keyOrItem : (keyOrItem?.key || keyOrItem?.id || '');
  const tags = typeof keyOrItem === 'object' && Array.isArray(keyOrItem.tags) ? keyOrItem.tags : [];
  const text = (key + " " + (keyOrItem?.label || "") + " " + tags.join(" ")).toLowerCase();

  if (text.includes('candidate') || text.includes('window') || text.includes('threshold') || text.includes('prng') || text.includes('seed') || text.includes('pipeline') || text.includes('diagnostic') || text.includes('override') || text.includes('expert')) {
    return 'expert';
  }
  if (text.includes('governor') || text.includes('approval') || text.includes('parallel') || text.includes('advanced') || text.includes('policy')) {
    return 'advanced';
  }
  if (text.includes('preset') || text.includes('simple') || text.includes('quick')) {
    return 'simple';
  }
  return 'guided';
}

export function isSettingVisibleAtLevel(
  settingMinLevel: SettingsExperienceLevel | undefined,
  selectedLevel: SettingsExperienceLevel
): boolean {
  if (!settingMinLevel) return true;
  const settingRank = EXPERIENCE_LEVEL_HIERARCHY[settingMinLevel] || 1;
  const selectedRank = EXPERIENCE_LEVEL_HIERARCHY[selectedLevel] || 2;
  return settingRank <= selectedRank;
}

export interface SettingsHubSearchOptions {
  scope?: 'all' | 'sectionNames' | 'individualSettings' | 'currentCategory' | 'descriptions' | 'tagsKeywords' | 'current_category' | 'section_names' | 'individual_settings' | SettingsSearchScope | string;
  state?: 'all' | 'changed' | 'default' | 'enabled' | 'disabled' | 'locked' | 'dependencyWarning' | 'conflict';
  currentCategoryTab?: SettingsHubTabId | string;
  feature?: string;
  gameMode?: string;
  gameSettings?: GameSettingsState;
  depReport?: any;
}

export function searchSettingsHub(
  query: string,
  profile?: SmartSettingsProfile,
  level?: SettingsExperienceLevel,
  options?: SettingsHubSearchOptions
): SettingsHubSearchItem[] {
  const normalized = query.trim().toLowerCase();
  const effectiveLevel = level || profile?.interfaceLevel || 'guided';
  const lockedKeys = profile?.lockedSettingKeys || [];
  const lockedCats = profile?.lockedCategories || [];

  const scope = options?.scope || 'all';
  const state = options?.state || 'all';
  const currentCategoryTab = options?.currentCategoryTab;
  const feature = options?.feature;
  const featureLower = feature && feature !== 'all' ? feature.toLowerCase() : null;
  const gameMode = options?.gameMode;
  const gameModeLower = gameMode && gameMode !== 'all' ? gameMode.toLowerCase() : null;
  const currentSettings = options?.gameSettings || DEFAULT_GAME_SETTINGS;
  const depReport = options?.depReport;

  if (rawSearchIndexTarget.length === 0) {
    rawSearchIndexTarget.push(...buildSettingsHubSearchIndex());
  }
  const searchIndex = rawSearchIndexTarget;

  const results: SettingsHubSearchItem[] = [];
  const seenKeys = new Set<string>();

  for (let i = 0; i < searchIndex.length; i++) {
    const item: any = searchIndex[i];

    if ((scope === 'sectionNames' || scope === 'section_names') && !item.isSection) continue;
    if ((scope === 'individualSettings' || scope === 'individual_settings') && item.isSection) continue;
    if ((scope === 'currentCategory' || scope === 'current_category') && currentCategoryTab && item.tab !== currentCategoryTab) continue;

    if (!item.isSection) {
      const itemMinLevel = item.minLevel || (typeof getMinLevelForSetting === 'function' ? getMinLevelForSetting(item) : 'simple');
      if (typeof isSettingVisibleAtLevel === 'function' && !isSettingVisibleAtLevel(itemMinLevel, effectiveLevel)) {
        continue;
      }
    }

    const itemSearchText = item._searchText || '';

    if (featureLower) {
      if (!itemSearchText.includes(featureLower)) continue;
    }

    if (gameModeLower) {
      if (gameMode === 'solo') {
        if (!itemSearchText.includes('solo') && (itemSearchText.includes('team_only') || itemSearchText.includes('multiplayer_only'))) continue;
      } else if (!itemSearchText.includes(gameModeLower)) {
        continue;
      }
    }

    if (state && state !== 'all' && !item.isSection) {
      const key = item.key || item.id;
      const currentValue = currentSettings ? (currentSettings as any)[key] : (DEFAULT_GAME_SETTINGS as any)[key];
      const defaultValue = (DEFAULT_GAME_SETTINGS as any)[key];
      const isChanged = typeof settingsValuesEqual === 'function' ? !settingsValuesEqual(currentValue, defaultValue) : currentValue !== defaultValue;

      if (state === 'changed' && !isChanged) continue;
      if (state === 'default' && isChanged) continue;
      if (state === 'enabled' && currentValue !== true) continue;
      if (state === 'disabled' && currentValue !== false) continue;
      if (state === 'locked') {
        const isLocked = lockedKeys.includes(key) || lockedCats.includes(item.category as SmartSettingsCategory);
        if (!isLocked) continue;
      }
      if (state === 'dependencyWarning') {
        if (!depReport) continue;
        const hasDepWarn = depReport.violations?.some((v: any) => v.settingKey === key || v.dependentMasterKey === key);
        if (!hasDepWarn) continue;
      }
      if (state === 'conflict') {
        if (!depReport) continue;
        const hasConflict = depReport.conflicts?.some((c: any) => c.settingA === key || c.settingB === key);
        if (!hasConflict) continue;
      }
    }

    if (normalized) {
      if (scope === 'descriptions') {
        const meta = SETTINGS_HUB_FIELD_META[item.key || item.id] || item;
        const descText = String(meta.description || item.description || '').toLowerCase();
        if (!descText.includes(normalized)) continue;
      } else if (scope === 'tagsKeywords') {
        const tagsKeywordsStr = ((item.tags || []).join(' ') + ' ' + (item.keywords || '')).toLowerCase();
        if (!tagsKeywordsStr.includes(normalized)) continue;
      } else {
        if (!itemSearchText.includes(normalized)) continue;
      }
    }

    const key = item.key || item.id || 'unknown';
    const category = item.category || item.tab || 'ai';

    let mappedItem: SettingsHubSearchItem;
    if (item.isSection) {
      const sectionMeta = SETTINGS_HUB_SECTION_INDEX.find(s => s.id === item.id);
      const sectionKeywords = item.keywords || sectionMeta?.keywords || '';
      const sectionTitleVal = item.title || item.sectionTitle || sectionMeta?.title || item.label || key;
      mappedItem = {
        key,
        category: item.tab || category,
        title: sectionTitleVal,
        sectionTitle: sectionTitleVal,
        label: item.label || sectionTitleVal,
        description: item.description || `Section in category: ${SETTINGS_HUB_TAB_LABELS[item.tab as SettingsHubTabId] || item.tab || ''}${sectionKeywords ? ' ' + sectionKeywords : ''}`,
        tab: item.tab || 'home',
        sectionId: item.id || key,
        tags: sectionMeta?.tags || ['Section'],
        keywords: sectionKeywords,
        minLevel: 'simple' as SettingsExperienceLevel,
        isSmartManaged: false,
        isLocked: false,
        isOverridden: false,
        isSection: true,
        fieldKeys: sectionMeta?.fieldKeys || []
      };
    } else {
      const isLocked = lockedKeys.includes(key) || lockedCats.includes(category as SmartSettingsCategory);
      const isOverridden = Boolean(profile?.customOverridesDetected);
      const meta = SETTINGS_HUB_FIELD_META[key] || item;
      const currentValue = currentSettings ? (currentSettings as any)[key] : (DEFAULT_GAME_SETTINGS as any)[key];
      const defaultValue = (DEFAULT_GAME_SETTINGS as any)[key];
      const isChanged = typeof settingsValuesEqual === 'function' ? !settingsValuesEqual(currentValue, defaultValue) : currentValue !== defaultValue;

      const hasDepWarn = depReport?.violations?.some((v: any) => v.settingKey === key || v.dependentMasterKey === key) ?? false;
      const hasConflict = depReport?.conflicts?.some((c: any) => c.settingA === key || c.settingB === key) ?? false;

      mappedItem = {
        key,
        category,
        title: item.title,
        sectionTitle: item.sectionTitle,
        label: meta.label || item.label || item.title || key,
        description: meta.description || item.description || item.keywords || '',
        tab: meta.tab || item.tab || 'home',
        sectionId: item.sectionId || key,
        tags: meta.tags || item.tags || [],
        keywords: item.keywords || '',
        minLevel: item.minLevel || (typeof getMinLevelForSetting === 'function' ? getMinLevelForSetting(item) : 'simple'),
        isSmartManaged: item.isSmartManaged ?? true,
        isLocked,
        isOverridden,
        isSection: false,
        fieldKeys: undefined,
        currentValue,
        isChanged,
        hasDependencyWarning: hasDepWarn,
        hasConflict
      };
    }

    const uniqueKey = mappedItem.isSection ? `section_${mappedItem.sectionId}` : mappedItem.key;
    if (!seenKeys.has(uniqueKey)) {
      seenKeys.add(uniqueKey);
      results.push(mappedItem);
    }
  }

  return results;
}

