export interface ModalAccessibilityOptions {
  activeModalId?: string | null;
  isOpen: boolean;
  onEscape?: () => void;
  trapFocus?: boolean;
  restoreFocusOnClose?: boolean;
}

export function useModalAccessibility(options: ModalAccessibilityOptions) {
  const { activeModalId, isOpen, onEscape, trapFocus = true, restoreFocusOnClose = true } = options;
  const containerRef = useRef<HTMLDivElement | null>(null);
  const openerRef = useRef<HTMLElement | null>(null);

  useEffect(() => {
    if (isOpen && typeof document !== 'undefined' && document.activeElement instanceof HTMLElement) {
      if (!openerRef.current || !containerRef.current?.contains(openerRef.current)) {
        openerRef.current = document.activeElement;
      }
    }
  }, [isOpen]);

  // `onEscape` is almost always an inline arrow from the caller, so including
  // it in the deps below re-ran this effect on every render and re-stole focus.
  // Read it through a ref instead.
  const onEscapeRef = useRef(onEscape);
  useEffect(() => { onEscapeRef.current = onEscape; }, [onEscape]);

  // Autofocus: once per open.
  useEffect(() => {
    if (!isOpen || !containerRef.current || !trapFocus) return;
    const focusableSelector = 'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])';
    const first = containerRef.current.querySelector<HTMLElement>(focusableSelector);
    if (first) first.focus();
  }, [isOpen, trapFocus]);

  useEffect(() => {
    if (!isOpen || !containerRef.current || !trapFocus) return;

    const element = containerRef.current;
    const focusableSelector = 'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])';
    const focusables = Array.from(element.querySelectorAll<HTMLElement>(focusableSelector));

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && onEscapeRef.current) {
        if (restoreFocusOnClose && openerRef.current && typeof openerRef.current.focus === 'function') {
          try {
            openerRef.current.focus();
          } catch (_) {}
        }
        onEscapeRef.current();
        return;
      }

      if (e.key === 'Tab' && focusables.length > 0) {
        const first = focusables[0];
        const last = focusables[focusables.length - 1];
        if (e.shiftKey) {
          if (document.activeElement === first) {
            e.preventDefault?.();
            last.focus();
          }
        } else {
          if (document.activeElement === last) {
            e.preventDefault?.();
            first.focus();
          }
        }
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, trapFocus, restoreFocusOnClose]);

  const prevIsOpenRef = useRef(isOpen);
  useEffect(() => {
    if (prevIsOpenRef.current && !isOpen) {
      if (restoreFocusOnClose && openerRef.current && typeof openerRef.current.focus === 'function') {
        try {
          openerRef.current.focus();
        } catch (_) {}
      }
    }
    prevIsOpenRef.current = isOpen;
  }, [isOpen, restoreFocusOnClose]);

  useEffect(() => {
    return () => {
      if (restoreFocusOnClose && openerRef.current && typeof openerRef.current.focus === 'function') {
        try {
          openerRef.current.focus();
        } catch (_) {}
      }
    };
  }, [restoreFocusOnClose]);

  return { containerRef, openerRef };
}

