export function runGlobalUISurfaceManagerDevTests(): { total: number; passed: number; failed: number; results: Array<{ name: string; status: 'passed' | 'failed'; message: string }> } {
  const results: Array<{ name: string; status: 'passed' | 'failed'; message: string }> = [];

  const manager = new GlobalUISurfaceManager();

  // Test 1: Z-Index tiers mapping
  const tier1Z = manager.getZIndex(1);
  const tier6Z = manager.getZIndex(6);
  const tier8Z = manager.getZIndex(8);
  const expectedTier8Z = UI_Z_INDEX_TIERS[8] || 700;
  if (tier1Z === 10 && tier6Z === 500 && tier8Z === expectedTier8Z) {
    results.push({ name: 'Z-Index Tier Hierarchy Mapping', status: 'passed', message: `Tiers 1, 6, 8 returned exact Z-Index constants (10, 500, ${expectedTier8Z})` });
  } else {
    results.push({ name: 'Z-Index Tier Hierarchy Mapping', status: 'failed', message: `Expected 10, 500, ${expectedTier8Z} got ${tier1Z}, ${tier6Z}, ${tier8Z}` });
  }

  // Test 2: Single Blocking Modal Rule & Modal Stack
  manager.openSurface('settings_hub');
  const state1 = manager.getState();
  manager.openSurface('approval_dialog');
  const state2 = manager.getState();
  if (state1.activeBlockingModal === 'settings_hub' && state2.activeBlockingModal === 'approval_dialog' && state2.modalStack.includes('settings_hub')) {
    results.push({ name: 'Single Blocking Modal & Stack Preservation', status: 'passed', message: 'Modal stack suspended previous settings_hub and activated approval_dialog' });
  } else {
    results.push({ name: 'Single Blocking Modal & Stack Preservation', status: 'failed', message: `Stack state mismatch: active=${state2.activeBlockingModal}, stack=${JSON.stringify(state2.modalStack)}` });
  }

  // Test 3: Closing surface resumes stacked modal
  manager.closeSurface('approval_dialog');
  const state3 = manager.getState();
  if (state3.activeBlockingModal === 'settings_hub') {
    results.push({ name: 'Modal Stack Resume on Close', status: 'passed', message: 'Closing approval_dialog cleanly resumed suspended settings_hub' });
  } else {
    results.push({ name: 'Modal Stack Resume on Close', status: 'failed', message: `Expected active settings_hub got ${state3.activeBlockingModal}` });
  }

  // Test 4: Background Blocking & Floating Widget Suppression
  if (state3.isBackgroundBlocked && state3.suppressedFloatingWidgets.includes('guardian_floating_button')) {
    results.push({ name: 'Background Blocking & Floating Widget Suppression', status: 'passed', message: 'Background interaction blocked and floating widgets suppressed during modal open' });
  } else {
    results.push({ name: 'Background Blocking & Floating Widget Suppression', status: 'failed', message: 'Background or widget suppression failed' });
  }

  // Test 5: Escape Key Handling & State Restoration
  const escaped = manager.handleEscapeKey();
  const state4 = manager.getState();
  if (escaped && state4.activeBlockingModal === null && !state4.isBackgroundBlocked) {
    results.push({ name: 'Escape Key Handling & State Restoration', status: 'passed', message: 'Escape key closed remaining modal and restored background scrolling' });
  } else {
    results.push({ name: 'Escape Key Handling & State Restoration', status: 'failed', message: 'Escape key handling failed' });
  }

  // Test 6: Multi-modal state synchronization & missing surfaces
  manager.syncWithUIState({ showSettings: true, showApprovalDialog: true, showStrategyPlanner: true });
  const stateMulti = manager.getState();
  if (stateMulti.modalStack.length >= 2 && Boolean(stateMulti.activeBlockingModal)) {
    results.push({ name: 'Multi-Modal State Synchronization', status: 'passed', message: 'syncWithUIState evaluated all active flags and populated modal stack' });
  } else {
    results.push({ name: 'Multi-Modal State Synchronization', status: 'failed', message: `Expected stacked modals, got active=${stateMulti.activeBlockingModal}, stack=${JSON.stringify(stateMulti.modalStack)}` });
  }

  // Test 7: Out-of-Order Modal Stack Removal
  manager.closeSurface('settings_hub');
  const stateUnwound = manager.getState();
  if (!stateUnwound.modalStack.includes('settings_hub')) {
    results.push({ name: 'Out-of-Order Modal Stack Removal', status: 'passed', message: 'Closing suspended parent surface cleanly removed it from modalStack' });
  } else {
    results.push({ name: 'Out-of-Order Modal Stack Removal', status: 'failed', message: `settings_hub still present in modalStack: ${JSON.stringify(stateUnwound.modalStack)}` });
  }

  // Test 8: Memory Leak Prevention in closeAllSurfaces
  manager.openSurface('save_load_modal');
  manager.closeAllSurfaces();
  const stateCleared = manager.getState();
  if (Object.keys(stateCleared.focusRestorationMap).length === 0) {
    results.push({ name: 'Memory Leak Prevention', status: 'passed', message: 'closeAllSurfaces cleanly reset focusRestorationMap' });
  } else {
    results.push({ name: 'Memory Leak Prevention', status: 'failed', message: 'focusRestorationMap was not reset on closeAllSurfaces' });
  }

  const passed = results.filter(r => r.status === 'passed').length;
  const failed = results.filter(r => r.status === 'failed').length;

  return {
    total: results.length,
    passed,
    failed,
    results
  };
}

