/**
 * Safely assigns a setting value to a partial or full GameSettingsState object
 * without triggering TypeScript indexed assignment diagnostics.
 */
function assignPartialSetting<K extends keyof GameSettingsState>(
  target: Partial<GameSettingsState> | GameSettingsState,
  key: K,
  value: GameSettingsState[K]
): GameSettingsState {
  (target as Record<string, unknown>)[key] = value;
  return target as GameSettingsState;
}

