  const managerState = useGlobalUISurfaceManager();
  const [isCollapsed, setIsCollapsed] = useState(settings?.positionMode === 'auto_collapsing_dock');
  const collapseTimerRef = useRef<any>(null);

  useEffect(() => {
    if (settings?.positionMode === 'auto_collapsing_dock') {
      if (collapseTimerRef.current) clearTimeout(collapseTimerRef.current);
      collapseTimerRef.current = setTimeout(() => {
        setIsCollapsed(true);
      }, settings.autoCollapseTimerMs || 3000);
    } else {
      setIsCollapsed(false);
    }
    return () => {
      if (collapseTimerRef.current) clearTimeout(collapseTimerRef.current);
    };
  }, [settings?.positionMode, settings?.autoCollapseTimerMs]);

  if (!settings?.enabled || managerState.activeBlockingModal !== null || globalUISurfaceManager.isWidgetSuppressed('floating_widget_dock')) return null;

  const mode = settings.positionMode;

