export function isCriticalNotification(n: any): boolean {
  if (!n) return false;
  if (n.persistent === true) return true;
  if (Boolean(n.guardianRiskId || n.guardianEvaluationId)) return true;

  const severityStr = String(n.severity || n.type || n.notificationType || "").toLowerCase();
  if (["critical", "emergency", "guardian", "rescue", "super_critical"].includes(severityStr)) {
    return true;
  }

  const notifTypeStr = String(n.notificationType || "").toLowerCase();
  if (["expedition_risk", "rival_threat", "emergency_rescue_triggered", "critical", "emergency", "guardian", "rescue"].includes(notifTypeStr)) {
    return true;
  }

  const titleOrMsg = (String(n.title || "") + " " + String(n.message || "")).toLowerCase();
  if (
    titleOrMsg.includes("[guardian ai]") ||
    titleOrMsg.includes("[rescue]") ||
    titleOrMsg.includes("[emergency]") ||
    titleOrMsg.includes("[co-pilot rescue]") ||
    titleOrMsg.includes("[critical]") ||
    titleOrMsg.includes("bankrupt") ||
    titleOrMsg.includes("contract fail") ||
    titleOrMsg.includes("expedition emergency")
  ) {
    return true;
  }

  return false;
}

// --- 11. Notification Lane Manager Component ---
export const NotificationLaneManager: React.FC<NotificationLaneManagerProps> = ({
  settings,
  notifications = [],
  onDismiss,
  surfaceManagerState,
  uiState: uiStateProp
}) => {
  const globalSurfaceState = useGlobalUISurfaceManager();
  const surfaceState = surfaceManagerState || globalSurfaceState;

  if (!notifications || notifications.length === 0) return null;

  const currentUiState = uiStateProp !== undefined ? uiStateProp : uiState;
  const anchor = settings?.anchor || "top_right";
  const avoidCoveringModals = settings?.avoidCoveringModals ?? true;
  const isBlockingModalOpen = globalUISurfaceManager.hasBlockingModal() || Boolean(surfaceState?.activeBlockingModal) || ((surfaceState?.modalStack?.length ?? 0) > 0) || Boolean(surfaceState?.isBackgroundBlocked) || Boolean(currentUiState?.showQuickActionsCustomizer);

  // V7.2 R1 & R2: Hide ordinary notification toasts during active blocking modals while preserving critical alerts
  let activeToasts = notifications;
  if (isBlockingModalOpen) {
    activeToasts = notifications.filter(n => isCriticalNotification(n));
  }

  if (activeToasts.length === 0) return null;

  const visibleToasts = activeToasts.slice(0, settings?.maxVisibleToasts || 4);

  const isCoPilotHudActive = Boolean(
    (surfaceState as any)?.activeSurfaces?.["copilot_hud"] ||
    (surfaceState as any)?.reservedScreenZones?.["copilot_hud"] ||
    currentUiState?.coPilotManualOverride ||
    (currentUiState as any)?.takeoverSession
  );

  let positionClasses = isCoPilotHudActive ? "top-36 right-4 flex-col items-end z-[600]" : "top-16 right-4 flex-col items-end z-[600]";

  if (isBlockingModalOpen) {
    // V7.2 R2: Reposition critical notifications to safe area bottom-8 right-8 z-[1000] during active blocking modals
    positionClasses = "bottom-8 right-8 flex-col items-end z-[1000]";
  } else {
    if (anchor === "top_center") positionClasses = "top-16 left-1/2 -translate-x-1/2 flex-col items-center z-[600]";
    else if (anchor === "bottom_right") positionClasses = "bottom-16 right-4 flex-col items-end z-[600]";
    else if (anchor === "bottom_center") positionClasses = "bottom-16 left-1/2 -translate-x-1/2 flex-col items-center z-[600]";
    else if (anchor === "dedicated_rail") positionClasses = "top-24 right-2 flex-col items-end max-w-xs z-[600]";
    else positionClasses = isCoPilotHudActive ? "top-36 right-4 flex-col items-end z-[600]" : "top-16 right-4 flex-col items-end z-[600]";
  }

  return (
    <div
      className={`fixed ${positionClasses} flex gap-2 pointer-events-none max-w-sm w-full p-2`}
      data-testid="notification-lane-manager"
    >
      {visibleToasts.map(n => (
        <div
          key={n.id}
          className="pointer-events-auto w-full p-3 rounded-xl bg-slate-900/95 border border-slate-700 text-slate-100 shadow-2xl backdrop-blur-md flex items-start justify-between gap-3 animate-slideIn"
        >
          <div>
            <div className="font-bold text-xs text-indigo-300">{n.title}</div>
            <div className="text-xs text-slate-300 mt-0.5 break-words">{n.message}</div>
          </div>
          {onDismiss && (
            <button
              type="button"
              onClick={() => onDismiss(n.id)}
              className="text-slate-400 hover:text-white text-xs font-bold p-1"
            >
              ✕
            </button>
          )}
        </div>
      ))}
    </div>
  );
};

