export function getPriorityTierZIndex(tierNumber: number): number {
  const tierDef = PRIORITY_TIERS.find(t => t.tier === tierNumber);
  return tierDef ? (tierDef.collisionRank ?? tierDef.canonicalZIndex ?? 500) : 500;
}

export interface ResolvedLayerPosition {
  surfaceId: string;
  tier: number;
  collisionRank: number;
  canonicalZIndex?: number;
  finalZIndex: number;
  stackOffset: number;
  relocationTarget?: string;
  isRelocated: boolean;
  viewportConflict: boolean;
}

export function resolveLayerPosition(
  surfaceId: string,
  tierNumber: number,
  stackIndex: number = 0,
  hasConflict: boolean = false
): ResolvedLayerPosition {
  const tierDef = PRIORITY_TIERS.find(t => t.tier === tierNumber) || PRIORITY_TIERS.find(t => t.tier === 5) || PRIORITY_TIERS[0];
  const rank = tierDef.collisionRank ?? tierDef.canonicalZIndex ?? 500;
  const stackOffset = stackIndex * 5;
  const finalZIndex = rank + stackOffset;

  return {
    surfaceId,
    tier: tierDef.tier,
    collisionRank: rank,
    canonicalZIndex: rank,
    finalZIndex,
    stackOffset,
    relocationTarget: hasConflict && tierDef.relocationRule !== 'Fixed / Non-relocatable' && tierDef.relocationRule !== 'never' ? tierDef.relocationRule : undefined,
    isRelocated: hasConflict && tierDef.relocationRule !== 'Fixed / Non-relocatable' && tierDef.relocationRule !== 'never',
    viewportConflict: hasConflict,
  };
}

export interface UiPriorityRegistryEngine {
  registerSurface: (surfaceId: string, tier: number) => void;
  unregisterSurface: (surfaceId: string) => void;
  resolveSurfacePosition: (surfaceId: string) => ResolvedLayerPosition | undefined;
  resolveAllPositions: () => ResolvedLayerPosition[];
  detectConflicts: () => Array<{ surfaceA: string; surfaceB: string; tier: number }>;
  relocateConflictingSurfaces: () => Map<string, string>;
  getSurfaceZIndex: (surfaceId: string) => number;
  getSurfaceCollisionRank: (surfaceId: string) => number;
}

export function createUiPriorityRegistryEngine(): UiPriorityRegistryEngine {
  const registeredSurfaces = new Map<string, number>();

  const detectConflicts = (): Array<{ surfaceA: string; surfaceB: string; tier: number }> => {
    const conflicts: Array<{ surfaceA: string; surfaceB: string; tier: number }> = [];
    const entries = Array.from(registeredSurfaces.entries());
    for (let i = 0; i < entries.length; i++) {
      for (let j = i + 1; j < entries.length; j++) {
        const [idA, tierA] = entries[i];
        const [idB, tierB] = entries[j];
        if (tierA === tierB) {
          conflicts.push({ surfaceA: idA, surfaceB: idB, tier: tierA });
        }
      }
    }
    return conflicts;
  };

  const relocateConflictingSurfaces = (): Map<string, string> => {
    const relocations = new Map<string, string>();
    const conflicts = detectConflicts();
    const conflictSet = new Set<string>();
    for (const c of conflicts) {
      conflictSet.add(c.surfaceA);
      conflictSet.add(c.surfaceB);
    }
    for (const surfaceId of conflictSet) {
      const tier = registeredSurfaces.get(surfaceId);
      if (tier !== undefined) {
        const pos = resolveLayerPosition(surfaceId, tier, 0, true);
        if (pos.isRelocated && pos.relocationTarget) {
          relocations.set(surfaceId, pos.relocationTarget);
        }
      }
    }
    return relocations;
  };

  return {
    registerSurface: (surfaceId: string, tier: number) => {
      registeredSurfaces.set(surfaceId, tier);
    },
    unregisterSurface: (surfaceId: string) => {
      registeredSurfaces.delete(surfaceId);
    },
    resolveSurfacePosition: (surfaceId: string): ResolvedLayerPosition | undefined => {
      const tier = registeredSurfaces.get(surfaceId);
      if (tier === undefined) return undefined;

      let stackIndex = 0;
      for (const [id, t] of registeredSurfaces.entries()) {
        if (id === surfaceId) break;
        if (t === tier) stackIndex++;
      }

      const conflicts = detectConflicts();
      const hasConflict = conflicts.some(c => c.surfaceA === surfaceId || c.surfaceB === surfaceId);
      return resolveLayerPosition(surfaceId, tier, stackIndex, hasConflict);
    },
    resolveAllPositions: (): ResolvedLayerPosition[] => {
      const positions: ResolvedLayerPosition[] = [];
      const conflicts = detectConflicts();
      const tierCounts = new Map<number, number>();

      for (const [surfaceId, tier] of registeredSurfaces.entries()) {
        const stackIndex = tierCounts.get(tier) || 0;
        tierCounts.set(tier, stackIndex + 1);
        const hasConflict = conflicts.some(c => c.surfaceA === surfaceId || c.surfaceB === surfaceId);
        positions.push(resolveLayerPosition(surfaceId, tier, stackIndex, hasConflict));
      }

      return positions;
    },
    detectConflicts,
    relocateConflictingSurfaces,
    getSurfaceZIndex: (surfaceId: string): number => {
      const tier = registeredSurfaces.get(surfaceId);
      if (tier === undefined) return 500;
      const pos = resolveLayerPosition(surfaceId, tier);
      return pos.finalZIndex;
    },
    getSurfaceCollisionRank: (surfaceId: string): number => {
      const tier = registeredSurfaces.get(surfaceId);
      if (tier === undefined) return 500;
      const tierDef = PRIORITY_TIERS.find(t => t.tier === tier) || PRIORITY_TIERS.find(t => t.tier === 5);
      return tierDef ? (tierDef.collisionRank ?? tierDef.canonicalZIndex ?? 500) : 500;
    },
  };
}



export function sanitizePriorityMatrix(matrix?: Record<string, number>): Record<string, number> {
  const defaults: Record<string, number> = {};
  for (let i = 1; i <= 11; i++) {
    defaults[String(i)] = i;
  }
  if (!matrix || typeof matrix !== 'object') {
    return defaults;
  }
  const entries: Array<[number, number]> = [];
  for (let i = 1; i <= 11; i++) {
    const rawVal = matrix[String(i)] ?? matrix[i] ?? i;
    const clamped = Math.max(1, Math.min(11, Math.round(Number(rawVal) || i)));
    entries.push([i, clamped]);
  }
  const ranksSeen = new Set<number>();
  const sanitized: Record<string, number> = {};
  for (const [tier, rank] of entries) {
    let finalRank = rank;
    while (ranksSeen.has(finalRank) && finalRank <= 11) {
      finalRank++;
    }
    if (finalRank > 11) {
      finalRank = 1;
      while (ranksSeen.has(finalRank) && finalRank <= 11) {
        finalRank++;
      }
    }
    ranksSeen.add(finalRank);
    sanitized[String(tier)] = finalRank;
  }
  return sanitized;
}

export function swapPriorityTiers(
  matrix: Record<string, number>,
  tierA: number,
  tierB: number
): Record<string, number> {
  const result = { ...matrix };
  const keyA = String(tierA);
  const keyB = String(tierB);
  const valA = result[keyA] ?? tierA;
  const valB = result[keyB] ?? tierB;
  result[keyA] = valB;
  result[keyB] = valA;
  return sanitizePriorityMatrix(result);
}

const SettingsSectionCtx = createContext<SettingsSectionCtxValue | null>(null);


export function useGlobalUISurfaceManager(): GlobalUISurfaceManagerState {
  const [state, setState] = useState(() => globalUISurfaceManager.getState());
  useEffect(() => {
    const unsubscribe = globalUISurfaceManager.subscribe(newState => {
      setState(newState);
    });
    return unsubscribe;
  }, []);
  return state;
}

