// AI Operations Auditor Phase AA16 (final phase): AI+AI independence audit, mirroring Team AI
// Overseer System Phase O10's own independence-audit comment above TeamOverseerState. Directly read
// the full body of runAuditorDetectionPass, every function in AUDITOR_DETECTION_RULES
// (detectAiTurnLifecycleStall, detectOrphanedApprovalRequest, detectRepeatedRejectedProposals,
// detectActionBudgetMismatch, detectOrphanedActionToken, detectUnusedOverrideGrant,
// detectSequenceHealthDegraded, detectTreasuryRequestUnresolved, detectRepeatedGovernorDeadlock,
// detectPartialExecutionWithinTurn, detectActorTurnOrderOverlap, detectNoProgressInconclusive,
// detectOverseerDirectiveConflict, detectPostLoadInactivity, detectUiStateDesyncObserved,
// detectSequenceRetryStorm), upsertAiOperationsIncident, resolveAiOperationsIncident, and
// appendAiOperationsEvent. Conclusion: no code path anywhere reads or is influenced by another
// team's AiOperationsAuditorState — every one of these functions resolves strictly via its own
// teamId/team.id parameter, with zero reads of teamsByIdRef.current[otherTeamId] anywhere in the
// Auditor's own code. detectActorTurnOrderOverlap's own pre-existing comment (AA9) already states
// it can only ever detect same-team actor-turn overlaps, since a true cross-team overlap is
// structurally undetectable from a single team's log — a stated scope boundary, not a leak. This is
// a documentation/audit deliverable, not a fix — no leak was found, so none is "fixed."
//
// Per-team Auditor state — genuinely separate from TeamOverseerState (never folded into it), so
// the Auditor's inertness can be proven independently of the Overseer's own state.
interface AiOperationsAuditorState {
  mode: AiOperationsAuditorMode;
  incidents: AiOperationsIncident[];
  incidentHistory: AiOperationsIncident[];
  eventLog: AiOperationsEvent[];
  categoryAuthority: Record<AiOperationsIncidentCategory, AiOperationsCategoryAuthority>;
  metrics: {
    totalIncidentsDetected: number;
    totalRecoveriesAttempted: number;
    totalRecoveriesSucceeded: number;
    totalRecoveriesFailed: number;
  };
  cooldowns: Record<string, number>;
  safeModeActive: boolean;
  safeModeReason: string;
  lastEvaluationDay: number;
  lastEvaluationTurn: number;
  proposalSignatureCounts: Record<string, number>;
  // AI Operations Auditor Phase AA12: automatic-recovery daily-limit counter — reset whenever
  // automaticRecoveryCountDay no longer matches the current day, mirroring
  // TeamComboTrackingState.comboCountToday/comboCountDay's exact daily-reset shape.
  automaticRecoveryCountToday: number;
  automaticRecoveryCountDay: number;
}

const createDefaultAiOperationsAuditorState = (): AiOperationsAuditorState => ({
  mode: 'off',
  incidents: [],
  incidentHistory: [],
  eventLog: [],
  categoryAuthority: {
    // Read-only/observation-only categories default to 'monitor' (harmless); everything that
    // touches budgets/tokens/overrides/treasury/governor/execution/state-invariants/recovery
    // itself defaults 'locked' — per the spec's own "default every category to Locked or
    // Monitor-only" instruction. Enabling the master toggle never changes any of these.
    turn_lifecycle: 'monitor', approval_flow: 'monitor', action_proposal: 'monitor',
    action_execution: 'locked', action_budget: 'locked', action_token: 'locked',
    override: 'locked', sequence: 'locked', treasury: 'locked', economy_governor: 'locked',
    overseer: 'monitor', save_load: 'monitor', parallel_execution: 'monitor',
    state_invariant: 'locked', performance: 'monitor', ui_synchronization: 'monitor',
    recovery_failure: 'locked'
  },
  metrics: { totalIncidentsDetected: 0, totalRecoveriesAttempted: 0, totalRecoveriesSucceeded: 0, totalRecoveriesFailed: 0 },
  cooldowns: {},
  safeModeActive: false,
  safeModeReason: '',
  lastEvaluationDay: 0,
  lastEvaluationTurn: 0,
  proposalSignatureCounts: {},
  automaticRecoveryCountToday: 0,
  automaticRecoveryCountDay: 0
});

// Deliberately more conservative than every other sanitizer in this file: only `mode` is trusted
// from a persisted save (validated against the closed union); every other field always resets to
// its default regardless of what's stored, since AA1 has no code path that could have produced a
// legitimate non-default value yet, and the spec requires the Auditor to "never replay old
// recoveries, revalidate/expire stale incidents rather than trusting them." Later phases may
// selectively loosen specific fields once real incident-revalidation logic exists to make
// trusting them safe — a deliberate one-way ratchet in the opposite direction of this file's
// usual "trust unless malformed" sanitizers, justified by how much riskier stale Auditor
// recovery/incident state would be to silently trust than stale gameplay state.
const sanitizeAiOperationsAuditorState = (value: unknown): AiOperationsAuditorState => {
  const defaults = createDefaultAiOperationsAuditorState();
  if (!value || typeof value !== 'object') return defaults;
  const source = value as Partial<AiOperationsAuditorState>;
  return {
    mode: (['off', 'monitor', 'recommend', 'approval', 'automatic'] as AiOperationsAuditorMode[]).includes(source.mode as AiOperationsAuditorMode)
      ? (source.mode as AiOperationsAuditorMode)
      : defaults.mode,
    incidents: [],
    incidentHistory: [],
    eventLog: [],
    categoryAuthority: defaults.categoryAuthority,
    metrics: defaults.metrics,
    cooldowns: {},
    safeModeActive: false,
    safeModeReason: '',
    lastEvaluationDay: 0,
    lastEvaluationTurn: 0,
    proposalSignatureCounts: {},
    automaticRecoveryCountToday: 0,
    automaticRecoveryCountDay: 0
  };
};

// Team AI Overseer System Phase O2: pure diagnostic — reads only existing state (win-metric gap,
// Governor-restricted actor count, endgame timing) and picks which AdaptiveStrategyMode currently
// applies. Coordination Repair's real signal doesn't exist until Strategic Command ships (O5+); the
// caller always passes hasCoordinationConflict=false until then — a stated, honest gap rather than
// a faked signal, matching this file's own convention of disclosing structural limits inline.
const computeAdaptiveStrategyModeSignal = (params: {
  teamMetricValue: number;
  opponentMetricValue: number;
  restrictedActorCount: number;
  hasCoordinationConflict: boolean;
  endgameActive: boolean;
  currentMode: AdaptiveStrategyMode;
  settings: GameSettingsState;
}): { candidateMode: AdaptiveStrategyMode; confidence: number; evidence: string[] } => {
  const { teamMetricValue, opponentMetricValue, restrictedActorCount, hasCoordinationConflict, endgameActive, currentMode, settings } = params;
  const referenceValue = Math.max(teamMetricValue, opponentMetricValue, 1);
  const percentBehind = teamMetricValue < opponentMetricValue ? ((opponentMetricValue - teamMetricValue) / referenceValue) * 100 : 0;
  const percentAhead = teamMetricValue > opponentMetricValue ? ((teamMetricValue - opponentMetricValue) / referenceValue) * 100 : 0;

  if (restrictedActorCount > 0) {
    return {
      candidateMode: 'recovery',
      confidence: Math.min(0.95, 0.6 + restrictedActorCount * 0.1),
      evidence: [`${restrictedActorCount} teammate(s) at or above the Governor-restricted-turns threshold.`]
    };
  }

  const comebackThreshold = currentMode === 'comeback' ? settings.teamAiAdaptiveOverseerComebackExitPercent : settings.teamAiAdaptiveOverseerComebackEnterPercent;
  if (percentBehind >= comebackThreshold) {
    if (settings.overseerWinConditionCounterStrategyEnabled) {
      const winCond = settings.winCondition || 'money';
      const counterMode: AdaptiveStrategyMode = winCond === 'money'
        ? 'counter_money_leader'
        : winCond === 'regions'
          ? 'counter_region_leader'
          : winCond === 'challenges'
            ? 'counter_challenge_leader'
            : 'counter_net_worth_leader';
      return {
        candidateMode: counterMode,
        confidence: Math.min(0.95, 0.5 + (percentBehind / Math.max(1, comebackThreshold)) * 0.25),
        evidence: [`Team is ${percentBehind.toFixed(1)}% behind on ${winCond} win condition. Overseer counter-strategy engaged.`]
      };
    }
    return {
      candidateMode: 'comeback',
      confidence: Math.min(0.95, 0.5 + (percentBehind / Math.max(1, comebackThreshold)) * 0.25),
      evidence: [`Team is ${percentBehind.toFixed(1)}% behind the opponent on the active win-condition metric.`]
    };
  }

  const protectLeadThreshold = currentMode === 'protect_lead' ? settings.teamAiAdaptiveOverseerProtectLeadExitPercent : settings.teamAiAdaptiveOverseerProtectLeadEnterPercent;
  if (percentAhead >= protectLeadThreshold) {
    return {
      candidateMode: 'protect_lead',
      confidence: Math.min(0.95, 0.5 + (percentAhead / Math.max(1, protectLeadThreshold)) * 0.25),
      evidence: [`Team is ${percentAhead.toFixed(1)}% ahead of the opponent on the active win-condition metric.`]
    };
  }

  if (endgameActive) {
    return {
      candidateMode: 'endgame_push',
      confidence: 0.7,
      evidence: ['The match has entered its endgame window.']
    };
  }

  if (hasCoordinationConflict) {
    return {
      candidateMode: 'coordination_repair',
      confidence: 0.6,
      evidence: ['Repeated coordination conflicts detected between teammates.']
    };
  }

  return { candidateMode: 'stable', confidence: 0.5, evidence: ['No strategy-mode trigger currently active.'] };
};
// Team AI Overseer System Phase O2: applies Part 11's stability rules — a non-Recovery mode change
// must wait teamAiAdaptiveOverseerMinimumStrategyDurationDays since the last change; Recovery is
// the spec's stated emergency exception and can pre-empt immediately.
const resolveAdaptiveStrategyModeTransition = (
  candidateMode: AdaptiveStrategyMode,
  currentMode: AdaptiveStrategyMode,
  strategyModeSinceDay: number,
  currentDay: number,
  minimumDurationDays: number
): boolean => {
  if (candidateMode === currentMode) return false;
  if (candidateMode === 'recovery') return true;
  return (currentDay - strategyModeSinceDay) >= minimumDurationDays;
};

// Team AI Overseer System Phase O4: lightweight outcome review, called from every path that
// ends a PolicyOverlay's active life (daily no-candidate revert, manual Revert Now, Dismiss).
// Reuses the overlay's own startMetricValue (captured once at creation time) rather than
// re-deriving a baseline — pure, no closures, matching this file's module-level-helper convention.
const computeOverlayOutcomeNote = (overlay: PolicyOverlay, currentMetricValue: number): string => {
  if (typeof overlay.startMetricValue !== 'number' || !isFinite(overlay.startMetricValue)) {
    return 'Outcome unavailable (no baseline metric was recorded when this overlay began).';
  }
  const delta = currentMetricValue - overlay.startMetricValue;
  const direction = delta > 0 ? 'increased' : delta < 0 ? 'decreased' : 'stayed the same';
  return `Team's win-condition metric ${direction} from $${Math.round(overlay.startMetricValue)} to $${Math.round(currentMetricValue)} while this was active.`;
};

// Team AI Overseer System Phase O9 (GD5): a pure filtered/merged view over TeamOverseerState's own
// arrays — no new AI subsystem, just .filter()+.concat()+.sort(), reusing the exact same
// approvalStatus/status values O3/O5/O6 already produce.
const getOverseerPendingRecommendations = (overseer: TeamOverseerState): Array<{ kind: 'overlay' | 'directive'; item: PolicyOverlay | TeamDirective }> => {
  const pendingOverlays = (overseer.policyOverlays || [])
    .filter(o => o.approvalStatus === 'pending')
    .map(o => ({ kind: 'overlay' as const, item: o, day: o.startDay }));
  const pendingDirectives = (overseer.strategicDirectives || [])
    .filter(d => d.status === 'proposed' || d.status === 'awaiting_approval')
    .map(d => ({ kind: 'directive' as const, item: d, day: d.createdDay }));
  return [...pendingOverlays, ...pendingDirectives]
    .sort((a, b) => b.day - a.day)
    .map(({ kind, item }) => ({ kind, item }));
};

// Team AI Overseer System Phase O9: Performance tab filter — only ever shows the already-shipped
// Strategic Command DecisionScoreStage tag (Phase O6, id 'strategic_command_directive_v67'), plus a
// best-effort text match for Adaptive Overseer's economyReserveStrength overlay (which changes a
// SETTING rather than emitting its own scoring stage, so no exact id tag exists for it yet).
const filterOverseerScoreStages = (stages: DecisionScoreStage[] | undefined): DecisionScoreStage[] => {
  if (!Array.isArray(stages)) return [];
  return stages.filter(stage =>
    stage.id === 'strategic_command_directive_v67' ||
    stage.label === 'Strategic Command' ||
    /economyReserveStrength|reserve strength/i.test(stage.reason || '')
  );
};

const sanitizeActionRequirement = (value: unknown): ActionRequirement | null => {
  if (!value || typeof value !== 'object') return null;
  const source = value as Partial<ActionRequirement>;
  if (typeof source.id !== 'string' || typeof source.label !== 'string') return null;
  if (!ACTION_REQUIREMENT_KINDS.includes(source.kind as ActionRequirementKind)) return null;
  if (!ACTION_REQUIREMENT_COMPARATORS.includes(source.comparator as ActionRequirement['comparator'])) return null;
  if (!ACTION_REQUIREMENT_FAILURE_BEHAVIORS.includes(source.failureBehavior as ActionRequirementFailureBehavior)) return null;
  const scopeSource = (source.scope && typeof source.scope === 'object') ? source.scope as Partial<ActionRequirementScope> : {};
  const scopeKind = ACTION_REQUIREMENT_SCOPE_KINDS.includes(scopeSource.kind as ActionRequirementScopeKind) ? scopeSource.kind as ActionRequirementScopeKind : 'all_teammates';
  const value_ = (typeof source.value === 'number' && isFinite(source.value)) || typeof source.value === 'string'
    ? source.value
    : (Array.isArray(source.value) ? source.value.filter(v => typeof v === 'string') : 0);
  return {
    id: source.id,
    enabled: Boolean(source.enabled),
    strictness: source.strictness === 'soft' ? 'soft' : 'hard',
    scope: {
      kind: scopeKind,
      actorId: typeof scopeSource.actorId === 'string' ? scopeSource.actorId : undefined,
      teamId: typeof scopeSource.teamId === 'string' ? scopeSource.teamId : undefined,
      actionType: typeof scopeSource.actionType === 'string' ? scopeSource.actionType as TeamModeActionCategory : undefined,
      region: typeof scopeSource.region === 'string' ? scopeSource.region : undefined,
      phase: typeof scopeSource.phase === 'string' ? scopeSource.phase as EconomicPhase : undefined,
      sequenceId: typeof scopeSource.sequenceId === 'string' ? scopeSource.sequenceId : undefined,
      stepId: typeof scopeSource.stepId === 'string' ? scopeSource.stepId : undefined,
      compareActorId: typeof scopeSource.compareActorId === 'string' ? scopeSource.compareActorId : undefined
    },
    kind: source.kind as ActionRequirementKind,
    comparator: source.comparator as ActionRequirement['comparator'],
    value: value_,
    failureBehavior: source.failureBehavior as ActionRequirementFailureBehavior,
    label: source.label
  };
};

// Recursively sanitizes a RequirementGroup, dropping malformed items and truncating anything past
// the hard depth limit (never throws on a corrupted/deeper-than-allowed saved structure).
const sanitizeRequirementGroup = (value: unknown, depth: number = 1): RequirementGroup | null => {
  if (!value || typeof value !== 'object') return null;
  const source = value as Partial<RequirementGroup>;
  if (typeof source.id !== 'string') return null;
  const mode = source.mode === 'any_may_pass' ? 'any_may_pass' : 'all_must_pass';
  const items = Array.isArray(source.items)
    ? source.items.reduce<(ActionRequirement | RequirementGroup)[]>((acc, item) => {
        if (!item || typeof item !== 'object') return acc;
        const isNestedGroup = Array.isArray((item as Partial<RequirementGroup>).items);
        if (isNestedGroup) {
          if (depth >= ACTION_REQUIREMENT_MAX_GROUP_DEPTH) return acc; // drop anything past the depth cap
          const nested = sanitizeRequirementGroup(item, depth + 1);
          if (nested) acc.push(nested);
        } else {
          const requirement = sanitizeActionRequirement(item);
          if (requirement) acc.push(requirement);
        }
        return acc;
      }, [])
    : [];
  return { id: source.id, mode, items };
};

const sanitizeRequirementGroups = (value: unknown): RequirementGroup[] => {
  if (!Array.isArray(value)) return [];
  return value.map(entry => sanitizeRequirementGroup(entry)).filter((g): g is RequirementGroup => Boolean(g));
};

// V6.9 Phase F4: extracted from evaluateActionRequirements's own internals (pure refactor, zero
// behavior change to that call site) so Sequence step conditions (GD3) can reuse the exact same
// group/requirement tree-walk — the scope-match/leaf-value logic stays with each caller via
// `evalLeaf`, this function only owns the all/any + strictness-filter + depth traversal semantics.
// Recursively evaluates a group/requirement node, considering only leaves whose strictness matches
// `strictnessFilter` — leaves of the other strictness (or scope mismatch, reported by `evalLeaf`
// returning applicable:false) are skipped (neither pass nor fail), so a mixed-strictness group tree
// can be evaluated twice (once per strictness) without cross-contaminating hard/soft results.
let hasWarnedRequirementDepthCap = false;
const evaluateRequirementGroupTree = (
  node: ActionRequirement | RequirementGroup,
  strictnessFilter: 'hard' | 'soft',
  evalLeaf: (req: ActionRequirement) => { applicable: boolean; passed: boolean },
  depth: number = 0
): { applicable: boolean; passed: boolean; failing: ActionRequirement[] } => {
  // Bugfix (post-F5 review, GD3): the UI and sanitizer both cap nesting at
  // ACTION_REQUIREMENT_MAX_GROUP_DEPTH, but the evaluator itself had no defensive backstop of its
  // own — a save file bypassing those two layers (e.g. direct storage tampering) would recurse
  // unbounded instead of the documented fail-closed(hard)/fail-open(soft) behavior.
  if (depth > ACTION_REQUIREMENT_MAX_GROUP_DEPTH) {
    if (!hasWarnedRequirementDepthCap) {
      console.warn('Action Requirements: a group exceeded the maximum nesting depth and was treated as fail-closed (hard) / fail-open (soft).');
      hasWarnedRequirementDepthCap = true;
    }
    return strictnessFilter === 'hard'
      ? { applicable: true, passed: false, failing: [] }
      : { applicable: false, passed: true, failing: [] };
  }
  const isGroup = Array.isArray((node as RequirementGroup).items);
  if (!isGroup) {
    const req = node as ActionRequirement;
    const reqStrictness: 'hard' | 'soft' = req.strictness === 'soft' ? 'soft' : 'hard';
    if (!req.enabled || reqStrictness !== strictnessFilter) {
      return { applicable: false, passed: true, failing: [] };
    }
    const { applicable, passed } = evalLeaf(req);
    if (!applicable) return { applicable: false, passed: true, failing: [] };
    return { applicable: true, passed, failing: passed ? [] : [req] };
  }
  const group = node as RequirementGroup;
  const results = group.items.map(item => evaluateRequirementGroupTree(item, strictnessFilter, evalLeaf, depth + 1));
  const applicableResults = results.filter(r => r.applicable);
  if (applicableResults.length === 0) return { applicable: false, passed: true, failing: [] };
  const failing = applicableResults.reduce<ActionRequirement[]>((acc, r) => acc.concat(r.failing), []);
  const passed = group.mode === 'any_may_pass'
    ? applicableResults.some(r => r.passed)
    : applicableResults.every(r => r.passed);
  return { applicable: true, passed, failing: passed ? [] : failing };
};

// Bugfix (post-F5 review, informational only — see the plan's Item 2 for why this is a UI warning
// rather than an evaluator redesign): an any_may_pass group's hard-pass and soft-pass are evaluated
// independently (GD7's deliberate non-cross-contamination design), so a group mixing hard and soft
// direct children can't express "hard OR soft" the way "ANY may pass" reads at a glance — a failing
// hard child still hard-rejects regardless of a passing soft sibling. This never changes evaluation
// behavior; it only flags the combination so the player understands what will actually happen.
const hasMixedStrictnessAnyGroup = (group: RequirementGroup): boolean => {
  if (group.mode !== 'any_may_pass') return false;
  const leafItems = group.items.filter(item => !Array.isArray((item as RequirementGroup).items)) as ActionRequirement[];
  const hasHard = leafItems.some(r => r.strictness !== 'soft');
  const hasSoft = leafItems.some(r => r.strictness === 'soft');
  return hasHard && hasSoft;
};

const ACTION_REQUIREMENT_MAX_RETRIES = 3;
// Shared, pure dispatch used identically by both execution chokepoints (performTeamAiTurn's main
// loop and runApprovedOverrideBonusActions) so their Requirements-rejection handling never drifts.
// 'retry_next_turn'/'reject'/'allow_normal_ai'/'pause_or_cancel' all resolve to 'end_turn' this
// phase (see ActionRequirementFailureBehavior's doc comment for why they currently collapse).
const resolveRequirementFailureAction = (
  behavior: ActionRequirementFailureBehavior,
  retryCount: number
): 'end_turn' | 'retry' | 'fallback' => {
  switch (behavior) {
    case 'retry_next_action':
      return retryCount < ACTION_REQUIREMENT_MAX_RETRIES ? 'retry' : 'end_turn';
    case 'use_fallback_action':
      return 'fallback';
    case 'retry_next_turn':
    case 'reject':
    case 'allow_normal_ai':
    case 'pause_or_cancel':
    default:
      return 'end_turn';
  }
};

// V6.9 Phase F3: AI Action Approval — an optional, off-by-default gate that pauses an AI
// teammate's proposed action for player review (approve/reject/edit) before it executes, layered
// as a THIRD condition alongside (never replacing) token revalidation and Action Requirements at
// both existing execution chokepoints.
type ApprovalMode = 'approve_every_action' | 'approve_selected_types' | 'approve_high_risk' | 'approve_sequence_actions_only' | 'mixed';
interface ApprovalHighRiskThresholds {
  wagerMin: number;
  costMin: number;
  percentCashAtRiskMin: number;
}
interface ApprovalTeammateOverride {
  actorId: string;
  mode: ApprovalMode;
  selectedTypes?: TeamModeActionCategory[];
  highRiskThresholds?: ApprovalHighRiskThresholds;
}
interface ApprovalPolicy {
  mode: ApprovalMode;
  selectedTypes: TeamModeActionCategory[];
  highRiskThresholds: ApprovalHighRiskThresholds;
  teammateOverrides: ApprovalTeammateOverride[];
}
// Reuses ActionRequirementFailureBehavior/SequenceStepFallbackAction's overlapping vocabulary
// ('use_fallback_action'→'use_fallback', 'retry_next_turn', 'allow_normal_ai') plus F3-specific
// values; 'pause_sequence'/'cancel_sequence' are sequence-only, inert, never offered in the picker.
type ApprovalRejectionOutcome = 'propose_again' | 'use_fallback' | 'skip' | 'allow_normal_ai' | 'wait_next_action' | 'wait_next_turn' | 'end_turn' | 'pause_sequence' | 'cancel_sequence';
// Full control vocabulary modeled now; only 9 are rendered as buttons this phase (see the Settings
// Hub/approval card) — 'skip_step'/'return_to_normal_ai'/'pause_sequence'/'cancel_sequence' are
// sequence-only and inert until Phase F4/F5, kept only for save-format/schema stability.
type ApprovalControlAction = 'approve' | 'reject' | 'edit_and_approve' | 'approve_lower_wager' | 'approve_once' | 'always_approve_similar' | 'reject_once' | 'always_reject_similar' | 'use_fallback' | 'skip_step' | 'return_to_normal_ai' | 'pause_sequence' | 'cancel_sequence';
// Team Treasury Phase T2 (GD2): distinct control vocabulary for a treasury_withdrawal request —
// replaces (never appears alongside) the 9 ordinary ApprovalControlAction buttons for this one
// request kind, matching the spec's "distinguish a funding request from an action-execution
// request" requirement.
type TreasuryApprovalControlAction = 'approve_full' | 'approve_minimum' | 'approve_partial' | 'edit_amount' | 'reject' | 'ask_cheaper' | 'emergency_only';
// Team Treasury Phase T4 (GD6): distinct control vocabulary for a governor_exception request —
// replaces (never appears alongside) the ordinary 9 ApprovalControlAction buttons or the Treasury
// 7-button row for this one request kind, mirroring T2's own requestKind-gated button-row precedent.
type GovernorExceptionControlAction = 'approve_once' | 'approve_lower' | 'use_treasury' | 'approve_current_turn' | 'lower_reserve' | 'reject_strict' | 'reject_end_turn';
interface AutomaticApprovalRuleThreshold {
  enabled: boolean;
  threshold: number;
}
interface AutomaticApprovalRules {
  autoApproveWagerBelow: AutomaticApprovalRuleThreshold;
  autoApproveLeavesMinReserve: { enabled: boolean };
  autoApproveSuccessProbabilityAbove: AutomaticApprovalRuleThreshold;
  autoApproveTravelCostBelow: AutomaticApprovalRuleThreshold;
  autoApproveSupportBelow: AutomaticApprovalRuleThreshold;
  autoRejectLoans: { enabled: boolean };
  autoRejectSabotage: { enabled: boolean };
  autoRejectRecoverySpending: { enabled: boolean };
}
// V6.9.1 bugfix: explicit lifecycle for an ApprovalRequest, replacing purely-inferred-from-array-
// membership status. Enables idempotent resolution (resolveApprovalRequest no-ops once resolved/
// cancelled) and lets the approval queue processor know exactly which request is currently on screen.
type ApprovalRequestStatus = 'pending' | 'displayed' | 'resolved' | 'cancelled';

interface ApprovalRequest {
  id: string;
  actorId: string;
  teamId: string;
  decision: any;
  actionSummary: string;
  targetLabel: string;
  cost: number | null;
  wager: number | null;
  percentCashAtRisk: number | null;
  expectedReward: number | null;
  successProbability: number | null;
  minCashRemaining: number | null;
  vaultEffect: string;
  governorRuling: string;
  requirementsSummary: string;
  aiExplanation: string;
  fallbackAvailable: boolean;
  actionsRemaining: number;
  categoryBucket: TeamModeActionCategory;
  createdAtTurn: number;
  // V6.9 Phase F5 (GD6): set only when the wrapped decision came from findExecutableSequenceStepDecision.
  // Gives the approval card's 4 sequence-only controls (below) a real referent, and gives
  // 'approve_sequence_actions_only' mode a real signal to discriminate on.
  sequenceId?: string;
  sequenceStepId?: string;
  metadata?: { sequenceId?: string; stepId?: string; [key: string]: any };
  // V6.9.1 bugfix: explicit lifecycle status, see ApprovalRequestStatus above.
  status: ApprovalRequestStatus;
  // Team Treasury Phase T2/T4: discriminates an ordinary action-execution request from a Treasury
  // funding-request/withdrawal request, or (T4) a Governor exception proposal, all reusing this
  // same queue/dialog machinery (GD1/GD2) — never a second approval engine. Defaults 'ai_action'
  // at every existing construction site.
  requestKind: 'ai_action' | 'treasury_withdrawal' | 'governor_exception' | 'overseer_adaptive_policy' | 'overseer_directive' | 'operations_recovery' | 'human_automation' | 'governance_proposal';
  treasuryRequestId?: string;
  // Team Treasury Phase T4: set only when requestKind === 'governor_exception'.
  governorExceptionId?: string;
  // Team AI Overseer System Phase O3: set only when requestKind === 'overseer_adaptive_policy'.
  overseerOverlayId?: string;
  // Team AI Overseer System Phase O6: set only when requestKind === 'overseer_directive'.
  overseerDirectiveId?: string;
  // AI Operations Auditor Phase AA11: set only when requestKind === 'operations_recovery'. Both
  // reference the incident/recovery-action this request is asking the player to approve/reject —
  // structurally distinct from every other requestKind (this is the Auditor asking permission to
  // touch OTHER systems' state on the player's behalf, never an ordinary gameplay-action proposal).
  auditorIncidentId?: string;
  auditorRecoveryActionId?: string;
  // Human Player Automation Phase HA2: set only when requestKind === 'human_automation' — the
  // automation this request is asking the player to confirm ('confirm_before_running' mode only).
  humanAutomationId?: string;
  // Phase 8: Governance Control Surface (Task 8.3)
  governanceProposalId?: string;
}

// V6.9.1 bugfix: one authoritative, ref-backed source for an actor's in-progress turn state,
// surviving the approval-pause `return` that would otherwise discard performTeamAiTurn's local
// variables. Deliberately does NOT duplicate actionsCompleted — every comparison reads
// actor.actionsUsedThisTurn fresh, since that field is already the single durable source the HUD
// itself uses and is incremented exactly once per successful execution regardless of which of the
// three turn-driving functions performs it.
interface ActiveAiTurnSession {
  actorId: string;
  teamId: string;
  totalActionBudget: number;
  pendingTokenQueue: string[];
  currentProposal?: ScoredTeamAiDecision | null;
  currentApprovalRequestId?: string | null;
  currentProposalTokenId?: string;
  currentSequenceId?: string | null;
  currentSequenceStepId?: string | null;
  currentOnRejection?: ApprovalRejectionOutcome;
  isPausedForApproval: boolean;
  isProcessing: boolean;
  isFinished: boolean;
}

const APPROVAL_MODES: ApprovalMode[] = ['approve_every_action', 'approve_selected_types', 'approve_high_risk', 'approve_sequence_actions_only', 'mixed'];
const APPROVAL_REJECTION_OUTCOMES: ApprovalRejectionOutcome[] = ['propose_again', 'use_fallback', 'skip', 'allow_normal_ai', 'wait_next_action', 'wait_next_turn', 'end_turn', 'pause_sequence', 'cancel_sequence'];
const sanitizeApprovalHighRiskThresholds = (value: unknown): ApprovalHighRiskThresholds => {
  const source = (value && typeof value === 'object') ? value as Partial<ApprovalHighRiskThresholds> : {};
  return {
    wagerMin: typeof source.wagerMin === 'number' && isFinite(source.wagerMin) ? Math.max(0, source.wagerMin) : 200,
    costMin: typeof source.costMin === 'number' && isFinite(source.costMin) ? Math.max(0, source.costMin) : 300,
    percentCashAtRiskMin: typeof source.percentCashAtRiskMin === 'number' && isFinite(source.percentCashAtRiskMin) ? Math.max(0, Math.min(1, source.percentCashAtRiskMin)) : 0.25
  };
};

const sanitizeApprovalTeammateOverride = (value: unknown): ApprovalTeammateOverride | null => {
  if (!value || typeof value !== 'object') return null;
  const source = value as Partial<ApprovalTeammateOverride>;
  if (typeof source.actorId !== 'string') return null;
  if (!APPROVAL_MODES.includes(source.mode as ApprovalMode)) return null;
  return {
    actorId: source.actorId,
    mode: source.mode as ApprovalMode,
    selectedTypes: Array.isArray(source.selectedTypes) ? source.selectedTypes.filter(t => typeof t === 'string') as TeamModeActionCategory[] : undefined,
    highRiskThresholds: source.highRiskThresholds ? sanitizeApprovalHighRiskThresholds(source.highRiskThresholds) : undefined
  };
};

const sanitizeApprovalTeammateOverrides = (value: unknown): ApprovalTeammateOverride[] => {
  if (!Array.isArray(value)) return [];
  return value.map(entry => sanitizeApprovalTeammateOverride(entry)).filter((o): o is ApprovalTeammateOverride => Boolean(o));
};

const sanitizeAutomaticApprovalRuleThreshold = (value: unknown, defaultThreshold: number): AutomaticApprovalRuleThreshold => {
  const source = (value && typeof value === 'object') ? value as Partial<AutomaticApprovalRuleThreshold> : {};
  return {
    enabled: Boolean(source.enabled),
    threshold: typeof source.threshold === 'number' && isFinite(source.threshold) ? Math.max(0, source.threshold) : defaultThreshold
  };
};

const sanitizeAutomaticApprovalRules = (value: unknown): AutomaticApprovalRules => {
  const source = (value && typeof value === 'object') ? value as Partial<AutomaticApprovalRules> : {};
  return {
    autoApproveWagerBelow: sanitizeAutomaticApprovalRuleThreshold(source.autoApproveWagerBelow, 0),
    autoApproveLeavesMinReserve: { enabled: Boolean(source.autoApproveLeavesMinReserve?.enabled) },
    autoApproveSuccessProbabilityAbove: sanitizeAutomaticApprovalRuleThreshold(source.autoApproveSuccessProbabilityAbove, 0.9),
    autoApproveTravelCostBelow: sanitizeAutomaticApprovalRuleThreshold(source.autoApproveTravelCostBelow, 0),
    autoApproveSupportBelow: sanitizeAutomaticApprovalRuleThreshold(source.autoApproveSupportBelow, 0),
    autoRejectLoans: { enabled: Boolean(source.autoRejectLoans?.enabled) },
    autoRejectSabotage: { enabled: Boolean(source.autoRejectSabotage?.enabled) },
    autoRejectRecoverySpending: { enabled: Boolean(source.autoRejectRecoverySpending?.enabled) }
  };
};

// V6.9 Phase F3: trigger evaluator for whether a decision needs player approval — no-op (false)
// whenever the master toggles are off, matching every prior gate's off-switch idiom. Plain
// module-level pure function, structurally typed (mirrors evaluateEconomySpendingApproval's own
// convention) so it's callable regardless of where ActorState/ScoredTeamAiDecision are declared.
const needsApproval = (
  actor: { id: string },
  decision: { type: string; data?: any },
  policy: ApprovalPolicy,
  settings: GameSettingsState,
  context?: { cost?: number; wager?: number; percentCashAtRisk?: number; isSequenceSourced?: boolean }
): boolean => {
  if (!settings.teamCompetitiveAiEnabled || !settings.aiActionApprovalEnabled) return false;
  const override = policy.teammateOverrides.find(o => o.actorId === actor.id);
  if (policy.mode === 'mixed') {
    if (override) {
      return needsApproval(actor, decision, {
        mode: override.mode,
        selectedTypes: override.selectedTypes || policy.selectedTypes,
        highRiskThresholds: override.highRiskThresholds || policy.highRiskThresholds,
        teammateOverrides: []
      }, settings, context);
    }
    // No override for this teammate under Mixed mode — default to the safest behavior
    // (approve every action) rather than silently meaning "never approve anything."
    return true;
  }
  switch (policy.mode) {
    case 'approve_every_action':
      return true;
    case 'approve_selected_types':
      return policy.selectedTypes.includes(decision.type as TeamModeActionCategory);
    case 'approve_high_risk': {
      const { wagerMin, costMin, percentCashAtRiskMin } = policy.highRiskThresholds;
      if (context?.wager !== undefined && context.wager >= wagerMin) return true;
      if (context?.cost !== undefined && context.cost >= costMin) return true;
      if (context?.percentCashAtRisk !== undefined && context.percentCashAtRisk >= percentCashAtRiskMin) return true;
      return false;
    }
    case 'approve_sequence_actions_only':
      // V6.9 Phase F5: real as of this phase — approval is required only for sequence-sourced
      // decisions (context.isSequenceSourced, threaded in from the chokepoint that already knows
      // whether the decision came from findExecutableSequenceStepDecision); every other decision
      // proceeds without approval.
      return context?.isSequenceSourced === true;
    default:
      return true;
  }
};

// V6.9 Phase F3: automatic approval/rejection rules — gated by their OWN separate opt-in
// (aiActionApprovalAutoRulesEnabled), never activated merely by enabling Approval itself or
// Advanced Settings. Auto-reject rules are checked first (always win over an auto-approve rule if
// both would somehow match, matching the spec's stated conservatism). Never shown in the visible
// queue — an auto-resolved decision is only ever logged via a trace note, never blocked/consumed.
const resolveAutomaticApprovalRules = (
  actor: { money: number; protectedCash?: number; inEconomicRecovery?: boolean },
  decision: { type: string; data?: any },
  settings: GameSettingsState,
  currentDay: number,
  context?: { cost?: number; wager?: number; successProbability?: number; travelCost?: number; requestKind?: 'ai_action' | 'treasury_withdrawal' }
): { outcome: 'approve' | 'reject' | 'none'; reason: string } => {
  if (!settings.teamCompetitiveAiEnabled || !settings.aiActionApprovalEnabled || !settings.aiActionApprovalAutoRulesEnabled) {
    return { outcome: 'none', reason: 'Automatic Approval Rules is off.' };
  }
  // Team Treasury Phase T2 (GD3): a Treasury withdrawal request must NEVER be auto-approved/
  // auto-rejected by an ordinary-action rule (e.g. "always approve challenges" must not imply
  // "always approve every Treasury withdrawal used for a challenge") — always routed through the
  // normal ApprovalPolicy check instead.
  if (context?.requestKind === 'treasury_withdrawal') {
    return { outcome: 'none', reason: 'Automatic Approval Rules never apply to Treasury funding requests.' };
  }
  const rules = settings.aiActionApprovalAutoRules;
  if (rules.autoRejectLoans.enabled && (decision.type === 'take_advanced_loan' || decision.type === 'loan')) {
    return { outcome: 'reject', reason: 'Auto-reject rule: loans.' };
  }
  if (rules.autoRejectSabotage.enabled && decision.type === 'sabotage') {
    return { outcome: 'reject', reason: 'Auto-reject rule: sabotage.' };
  }
  if (rules.autoRejectRecoverySpending.enabled && actor.inEconomicRecovery && (decision.type === 'invest' || decision.type === 'buy_equipment')) {
    return { outcome: 'reject', reason: 'Auto-reject rule: recovery-phase spending.' };
  }
  if (rules.autoApproveWagerBelow.enabled && context?.wager !== undefined && context.wager < rules.autoApproveWagerBelow.threshold) {
    return { outcome: 'approve', reason: 'Auto-approve rule: wager below threshold.' };
  }
  if (rules.autoApproveLeavesMinReserve.enabled) {
    const spendableCash = getActorSpendableCash(actor, settings.teamCashVaultEnabled);
    const endgameActive = isEndgamePeriod(currentDay, settings.totalDays, settings.teamAiEndgameStartPercent);
    const phase = computeEconomicPhase(actor, spendableCash, settings, endgameActive);
    const reserve = computeDynamicReserve(phase, spendableCash, settings);
    const cost = context?.cost ?? context?.wager ?? 0;
    if ((spendableCash - cost) >= reserve) {
      return { outcome: 'approve', reason: 'Auto-approve rule: leaves minimum reserve.' };
    }
  }
  if (rules.autoApproveSupportBelow.enabled && (decision.type === 'give_cash' || decision.type === 'give_resource') && context?.cost !== undefined && context.cost < rules.autoApproveSupportBelow.threshold) {
    return { outcome: 'approve', reason: 'Auto-approve rule: small support transfer.' };
  }
  return { outcome: 'none', reason: 'Default manual approval requirement.' };
}

// Milestone 4: AI Learning, Opponent Models, Plan Stability & Governance Types & Helpers
// TeamGovernanceMode type derived directly from TEAM_GOVERNANCE_MODES above
export interface OpponentModel {
  opponentId: string;
  totalActionsObserved: number;
  aggressiveness: number;
  expansionRate: number;
  sabotagePropensity: number;
  investmentBias?: number;
  actionCategoryCounts: Record<string, number>;
  lastObservedDay: number;
}

export interface CounterfactualEvaluation {
  candidateType: string;
  rawScore: number;
  counterfactualUtilityDelta: number;
}

export interface AiTacticalIntelligenceParams {
  lookaheadDepth: number;
  candidateEvaluationWidth: number;
  planningBreadth?: string | any;
  useCounterfactuals?: boolean;
  useOpponentModeling?: boolean;
}

export interface AiEconomicCheatBonuses {
  bonusStartingCash: number;
  yieldBoostMultiplier: number;
  costDiscountMultiplier: number;
  extraActionPointsPerTurn: number;
}

interface AiTacticalIntelligenceBoost {
  bonusStartingCash: number;
  costDiscountMultiplier: number;
  extraActionPointsPerTurn: number;
  candidateEvaluationWidth?: number;
}
export const getAiCalibrationMultiplier = (actor: any, category: string): number => {
  if (!actor || !actor.actionCalibrationMultipliers) return 1.0;
  const raw = actor.actionCalibrationMultipliers[category];
  if (typeof raw !== 'number' || !isFinite(raw)) return 1.0;
  return Math.max(0.85, Math.min(1.15, raw));
};

export const calculateCalibratedUtility = (rawScore: number, actor: any, category: string): number => {
  const mult = getAiCalibrationMultiplier(actor, category);
  return rawScore * mult;
};

export const updatePostActionCalibration = (
  actor: any,
  category: string,
  success: boolean,
  context?: { predictedUtility?: number; actualDelta?: number }
): void => {
  if (!actor) return;
  if (!actor.actionCalibrationMultipliers) {
    actor.actionCalibrationMultipliers = {};
  }
  const current = getAiCalibrationMultiplier(actor, category);
  let adjustment = 0;
  if (success) {
    adjustment = 0.01;
  } else {
    adjustment = -0.015;
  }
  actor.actionCalibrationMultipliers[category] = Math.max(0.85, Math.min(1.15, current + adjustment));
};

const recordObservedOpponentAction = (
  observerActor: any,
  opponentId: string,
  actionType: string,
  day: number,
  settings: any
): Record<string, OpponentModel> => {
  const existingModels = observerActor?.opponentModels || {};
  const skipInfo = getPersistentOpponentModelSkipReason(settings);
  if (skipInfo.skipped) return existingModels;

  const currentModel: OpponentModel = existingModels[opponentId] || {
    opponentId,
    totalActionsObserved: 0,
    aggressiveness: 0.2,
    expansionRate: 0.2,
    sabotagePropensity: 0.1,
    investmentBias: 0.3,
    actionCategoryCounts: {},
    lastObservedDay: day
  };

  const daysElapsed = Math.max(0, day - (currentModel.lastObservedDay ?? day));
  const decayRate = typeof settings.opponentModelDecayRate === 'number' ? settings.opponentModelDecayRate : 0.05;
  const decayFactor = daysElapsed > 0 && decayRate > 0 ? Math.pow(1 - decayRate, daysElapsed) : 1;

  const decayedTotal = currentModel.totalActionsObserved * decayFactor;
  const decayedCounts: Record<string, number> = {};
  for (const [k, v] of Object.entries(currentModel.actionCategoryCounts || {})) {
    decayedCounts[k] = (v as number) * decayFactor;
  }

  const total = decayedTotal + 1;
  const counts = { ...decayedCounts, [actionType]: (decayedCounts[actionType] || 0) + 1 };
  
  const aggressiveCount = (counts['challenge'] || 0) + (counts['sabotage'] || 0);
  const expansionCount = (counts['travel'] || 0) + (counts['region_deposit'] || 0);
  const sabotageCount = (counts['sabotage'] || 0);
  const investmentCount = (counts['invest'] || 0) + (counts['buy_equipment'] || 0) + (counts['buy_market'] || 0);

  const updatedModel: OpponentModel = {
    opponentId,
    totalActionsObserved: total,
    aggressiveness: Math.min(1.0, aggressiveCount / total),
    expansionRate: Math.min(1.0, expansionCount / total),
    sabotagePropensity: Math.min(1.0, sabotageCount / total),
    investmentBias: Math.min(1.0, investmentCount / total),
    actionCategoryCounts: counts,
    lastObservedDay: day
  };

  return { ...existingModels, [opponentId]: updatedModel };
};

export const getPersistentOpponentModelSkipReason = (settings?: GameSettingsState): { skipped: boolean; reason?: string } => {
  if (!settings || !settings.enablePersistentOpponentModels) {
    return { skipped: true, reason: 'Persistent opponent models disabled (enablePersistentOpponentModels setting is false)' };
  }
  return { skipped: false };
};

export const updateOpponentModel = recordObservedOpponentAction;

export const getOpponentTendencyBonus = (
  observerActor: any,
  candidateAction: any,
  settings: any
): number => {
  const weight = typeof settings?.opponentModelWeight === 'number'
    ? settings.opponentModelWeight
    : 15;

  if (weight <= 0) return 0;

  const weightMultiplier = weight / 15;
  const models: Record<string, OpponentModel> = observerActor?.opponentModels || {};
  let totalBonus = 0;

  const targetId = candidateAction?.data?.targetActorId || candidateAction?.targetActorId;
  const relevantModels = targetId && models[targetId] ? [models[targetId]] : Object.values(models);

  for (const model of relevantModels) {
    if (!model || model.totalActionsObserved < 2) continue;

    // Aggressive opponent: bonus to counter/defend/challenge
    if (model.aggressiveness > 0.4 && (candidateAction.type === 'challenge' || candidateAction.type === 'sabotage' || candidateAction.type === 'buy_equipment')) {
      totalBonus += Math.round(model.aggressiveness * 15);
    }
    // High sabotage propensity: bonus to protective investments or counter-sabotage
    if (model.sabotagePropensity > 0.25 && (candidateAction.type === 'invest' || candidateAction.type === 'buy_equipment')) {
      totalBonus += Math.round(model.sabotagePropensity * 20);
    }
    // High expansion rate: bonus to travel / region_deposit to compete for regions
    if (model.expansionRate > 0.4 && (candidateAction.type === 'travel' || candidateAction.type === 'region_deposit')) {
      totalBonus += Math.round(model.expansionRate * 12);
    }
    // High investment bias: bonus to invest / cashout / economic competition
    if ((model.investmentBias ?? 0) > 0.4 && (candidateAction.type === 'invest' || candidateAction.type === 'buy_market')) {
      totalBonus += Math.round((model.investmentBias ?? 0) * 10);
    }
  }

  return Math.round(totalBonus * weightMultiplier);
};

export const computeCounterfactualEvaluations = (
  chosen: any,
  candidates: any[]
): CounterfactualEvaluation[] => {
  if (!chosen || !Array.isArray(candidates)) return [];
  const chosenScore = chosen.score || 0;
  const nonChosen = candidates.filter(c => c !== chosen && c.type !== chosen.type).slice(0, 3);
  return nonChosen.map(c => ({
    candidateType: c.type,
    rawScore: c.score || 0,
    counterfactualUtilityDelta: (c.score || 0) - chosenScore
  }));
};

export const getTeamGovernanceMode = (
  teamId: string,
  settings?: GameSettingsState
): TeamGovernanceOverrideMode | TeamGovernanceMode => {
  if (!settings) return 'LEADER_DECIDES';
  const overrides = settings.teamGovernanceModeOverrides;
  if (overrides && typeof overrides === 'object' && teamId in overrides && overrides[teamId]) {
    return overrides[teamId] as unknown as "CONSENSUS_REQUIREMENT" | "LEADER_DECIDES" | "OVERSEER_ARBITRATION" | "WEIGHTED_VOTE" | "directive_only" | "full_control" | "monitor_only" | "recommendation_only";
  }
  const normalizedSlot = teamId.toLowerCase().includes('player') ? 'team_player' : teamId.toLowerCase().includes('ai') ? 'team_ai' : teamId;
  if (overrides && normalizedSlot in overrides && overrides[normalizedSlot]) {
    return overrides[normalizedSlot] as unknown as "CONSENSUS_REQUIREMENT" | "LEADER_DECIDES" | "OVERSEER_ARBITRATION" | "WEIGHTED_VOTE" | "directive_only" | "full_control" | "monitor_only" | "recommendation_only";
  }
  return (settings.teamGovernanceMode as TeamGovernanceOverrideMode | TeamGovernanceMode) || 'LEADER_DECIDES';
};

export const normalizeSignaturePayload = (obj: any): string => {
  if (obj === null || obj === undefined) return '';
  if (typeof obj !== 'object') return JSON.stringify(obj);
  if (Array.isArray(obj)) {
    return '[' + obj.map(normalizeSignaturePayload).join(',') + ']';
  }
  const keys = Object.keys(obj).sort();
  return '{' + keys.map(k => `${JSON.stringify(k)}:${normalizeSignaturePayload(obj[k])}`).join(',') + '}';
};

export const getDecisionSignature = (decision: any): string => {
  if (!decision) return 'null';
  if (typeof decision === 'string') return decision;
  if (decision.signature && typeof decision.signature === 'string') return decision.signature;
  const typeStr = decision.type || decision.actionType || 'unknown';
  const dataPayload = decision.data ? normalizeSignaturePayload(decision.data) : (decision.payload ? normalizeSignaturePayload(decision.payload) : '');
  return `${typeStr}:${dataPayload}`;
};

export const recordGovernanceLogEntry = (
  gameState: any,
  entry: GovernanceLogEntry
): void => {
  if (!gameState) return;
  if (!gameState.governanceLog) gameState.governanceLog = [];
  gameState.governanceLog.push(entry);
  if (gameState.governanceLog.length > 50) {
    gameState.governanceLog = gameState.governanceLog.slice(-50);
  }
};

export const evaluateGovernanceProposal = (
  proposal: any,
  proposingActor: any,
  members: any[],
  mode: TeamGovernanceMode | TeamGovernanceOverrideMode = 'LEADER_DECIDES',
  settings?: Partial<GameSettingsState>,
  humanVetoInput?: { vetoed: boolean; vetoedBy?: string },
  gameState?: any
): GovernanceProposalResolution => {
  const safeMembers = Array.isArray(members) ? members.filter(m => Boolean(m && typeof m === 'object')) : [];
  if (!proposal) {
    return {
      approved: false,
      status: 'rejected',
      mode,
      reason: 'Invalid proposal object.',
      voteBreakdown: {},
      voteWeights: {},
      forWeight: 0,
      totalWeight: 0,
      approvalRatio: 0
    };
  }
  if (!proposingActor || safeMembers.length === 0) {
    return {
      approved: false,
      status: 'rejected',
      mode,
      reason: 'Invalid proposing actor or empty team member list.',
      voteBreakdown: {},
      voteWeights: {},
      forWeight: 0,
      totalWeight: 0,
      approvalRatio: 0
    };
  }

  // 1. Human Veto Check (Phase 8 Task 8.3 & 8.5)
  const isVetoed = Boolean(humanVetoInput?.vetoed || proposal?.humanVetoApplied);
  if (isVetoed) {
    const vetoedBy = humanVetoInput?.vetoedBy || proposal?.vetoedBy || 'Human Veto';
    return {
      approved: false,
      status: 'vetoed',
      mode,
      reason: `Proposal vetoed by ${vetoedBy}.`,
      voteBreakdown: {},
      voteWeights: {},
      forWeight: 0,
      totalWeight: 0,
      approvalRatio: 0,
      vetoedBy
    };
  }

  // 2. Extract Tunable Governance Weights (Phase 8 Task 8.2)
  const defaultWeights = DEFAULT_GAME_SETTINGS.governanceWeightSettings || { leaderWeight: 2, consensusWeight: 0.5, riskWeight: 1.0, economicWeight: 1.0, memberWeight: 1 };
  const weights: GovernanceWeightSettings = {
    leaderWeight: settings?.governanceWeightSettings?.leaderWeight ?? settings?.governanceLeaderVoteWeight ?? DEFAULT_GAME_SETTINGS.governanceLeaderVoteWeight ?? 2,
    consensusWeight: settings?.governanceWeightSettings?.consensusWeight ?? settings?.governanceVoteThreshold ?? DEFAULT_GAME_SETTINGS.governanceVoteThreshold ?? 0.5,
    riskWeight: settings?.governanceWeightSettings?.riskWeight ?? defaultWeights.riskWeight ?? 1.0,
    economicWeight: settings?.governanceWeightSettings?.economicWeight ?? defaultWeights.economicWeight ?? 1.0,
    memberWeight: settings?.governanceWeightSettings?.memberWeight ?? settings?.governanceMemberVoteWeight ?? DEFAULT_GAME_SETTINGS.governanceMemberVoteWeight ?? 1
  };
  const consensusRequirementThreshold = settings?.governanceConsensusThreshold ?? DEFAULT_GAME_SETTINGS.governanceConsensusThreshold ?? 1.0;

  // Helper for computing leader standing bonus
  const getLeaderStandingBonus = (leaderId: string): number => {
    if (!gameState || !gameState.standingPerActor || !leaderId) return 0;
    const s = gameState.standingPerActor[leaderId];
    let standingValue = 0;
    if (typeof s === 'number') {
      standingValue = s;
    } else if (typeof s === 'object' && s !== null) {
      const regionKey = proposal?.data?.region;
      if (regionKey && typeof s[regionKey] === 'number') {
        standingValue = s[regionKey];
      } else {
        const vals = Object.values(s).filter((v): v is number => typeof v === 'number');
        if (vals.length > 0) standingValue = Math.max(...vals);
      }
    }
    return standingValue > 0 ? Math.floor(standingValue / 25) : 0;
  };

  // 3. Member Vote Evaluation Helper with Tunable Weight Scaling
  const evaluateMemberVote = (member: any): { vote: boolean; score: number; reason: string } => {
    let score = 0;
    const role = member?.role || 'member';
    const riskTolerance = member?.riskTolerance ?? (role === 'aggressor' ? 0.8 : role === 'defender' ? 0.3 : 0.5);

    if (proposal?.type === 'challenge' || proposal?.type === 'sabotage') {
      score += (riskTolerance - 0.5) * 20 * weights.riskWeight;
    } else if (proposal?.type === 'invest' || proposal?.type === 'buy_equipment') {
      if (role === 'defender' || role === 'investor') {
        score += 10 * weights.economicWeight;
      }
    }

    if (proposal?.data?.region && member?.currentRegion === proposal.data.region) {
      score += 8;
    }

    const threshold = role === 'leader' ? 8 : role === 'defender' ? 5 : 0;
    const vote = score >= threshold;
    const reason = vote
      ? `Agreed (score ${score.toFixed(1)} >= ${threshold})`
      : `Disagreed (score ${score.toFixed(1)} < ${threshold})`;

    return { vote, score, reason };
  };

  const voteBreakdown: Record<string, boolean> = {};
  const voteWeights: Record<string, number> = {};

  // 4. Resolution Logic per Team Governance Mode
  switch (mode) {
    case 'LEADER_DECIDES': {
      const leader = safeMembers.find(m => m.role === 'leader') || safeMembers.find(m => m.id === proposingActor.id) || safeMembers[0] || proposingActor;
      const leaderWeight = weights.leaderWeight + getLeaderStandingBonus(leader.id);
      const leaderEval = evaluateMemberVote(leader);

      voteBreakdown[leader.id] = leaderEval.vote;
      voteWeights[leader.id] = leaderWeight;

      const approved = leaderEval.vote;
      const forWeight = approved ? leaderWeight : 0;
      const approvalRatio = approved ? 1.0 : 0.0;

      return {
        approved,
        status: approved ? 'approved' : 'rejected',
        mode,
        reason: approved
          ? `Leader (${leader.displayName || leader.name || leader.id}) approved decision.`
          : `Leader (${leader.displayName || leader.name || leader.id}) rejected decision (${leaderEval.reason}).`,
        voteBreakdown,
        voteWeights,
        forWeight,
        totalWeight: leaderWeight,
        approvalRatio
      };
    }

    case 'WEIGHTED_VOTE': {
      let positiveWeight = 0;
      let totalWeight = 0;

      safeMembers.forEach(member => {
        const evalRes = evaluateMemberVote(member);
        voteBreakdown[member.id] = evalRes.vote;
        const w = (member.role === 'leader' ? weights.leaderWeight + getLeaderStandingBonus(member.id) : weights.memberWeight);
        voteWeights[member.id] = w;
        totalWeight += w;
        if (evalRes.vote) positiveWeight += w;
      });

      const approvalRatio = positiveWeight / Math.max(1, totalWeight);
      const approved = approvalRatio >= weights.consensusWeight;
      return {
        approved,
        status: approved ? 'approved' : 'rejected',
        mode,
        reason: approved
          ? `Weighted vote passed (${positiveWeight.toFixed(1)}/${totalWeight.toFixed(1)}, ratio ${approvalRatio.toFixed(2)} >= threshold ${weights.consensusWeight.toFixed(2)}).`
          : `Weighted vote failed (${positiveWeight.toFixed(1)}/${totalWeight.toFixed(1)}, ratio ${approvalRatio.toFixed(2)} < threshold ${weights.consensusWeight.toFixed(2)}).`,
        voteBreakdown,
        voteWeights,
        forWeight: positiveWeight,
        totalWeight,
        approvalRatio
      };
    }

    case 'CONSENSUS_REQUIREMENT': {
      let positiveCount = 0;

      safeMembers.forEach(member => {
        const evalRes = evaluateMemberVote(member);
        voteBreakdown[member.id] = evalRes.vote;
        voteWeights[member.id] = weights.memberWeight;
        if (evalRes.vote) positiveCount++;
      });

      const approvalRatio = positiveCount / Math.max(1, safeMembers.length);
      const approved = approvalRatio >= consensusRequirementThreshold;
      return {
        approved,
        status: approved ? 'approved' : 'rejected',
        mode,
        reason: approved
          ? `Consensus achieved across team members (${positiveCount}/${safeMembers.length}, ${(approvalRatio * 100).toFixed(0)}% >= ${(consensusRequirementThreshold * 100).toFixed(0)}%).`
          : `Consensus failed — insufficient member approval (${positiveCount}/${safeMembers.length}, ${(approvalRatio * 100).toFixed(0)}% < ${(consensusRequirementThreshold * 100).toFixed(0)}%).`,
        voteBreakdown,
        voteWeights,
        forWeight: positiveCount * weights.memberWeight,
        totalWeight: safeMembers.length * weights.memberWeight,
        approvalRatio
      };
    }

    case 'OVERSEER_ARBITRATION':
    default: {
      safeMembers.forEach(member => {
        const evalRes = evaluateMemberVote(member);
        voteBreakdown[member.id] = evalRes.vote;
        voteWeights[member.id] = weights.memberWeight;
      });

      return {
        approved: true,
        status: 'approved',
        mode,
        reason: 'Overseer arbitration mode active — proposal passed oversight check.',
        voteBreakdown,
        voteWeights,
        forWeight: safeMembers.length * weights.memberWeight,
        totalWeight: safeMembers.length * weights.memberWeight,
        approvalRatio: 1.0
      };
    }
  }
};

export const evaluateTeamGovernanceApproval = (
  decision: any,
  teamState: any,
  leaderActorId: string,
  settings: any,
  gameState?: any
): { approved: boolean; mode: TeamGovernanceMode; votes: Record<string, boolean>; reason: string; resolution?: GovernanceProposalResolution } => {
  if (settings && settings.governanceControlSurfaceEnabled === false && !settings.teamGovernanceEnabled) {
    const mode = (settings?.teamGovernanceMode || 'LEADER_DECIDES') as TeamGovernanceMode;
    const disabledResolution: GovernanceProposalResolution = {
      approved: true,
      status: 'approved',
      mode,
      reason: 'Governance disabled via control surface settings.',
      voteBreakdown: {},
      voteWeights: {},
      forWeight: 0,
      totalWeight: 0,
      approvalRatio: 1.0
    };
    return {
      approved: true,
      mode,
      votes: {},
      reason: 'Governance disabled via control surface settings.',
      resolution: disabledResolution
    };
  }

  const effectiveMode = getTeamGovernanceMode(teamState?.id || decision?.teamId || 'default', settings);
  const mode: TeamGovernanceMode = (['LEADER_DECIDES', 'WEIGHTED_VOTE', 'CONSENSUS_REQUIREMENT', 'OVERSEER_ARBITRATION'].includes(effectiveMode) ? effectiveMode : settings?.teamGovernanceMode || 'LEADER_DECIDES') as TeamGovernanceMode;
  
  const actualLeaderId = teamState?.leaderId || leaderActorId || decision?.actorId;
  const memberIds: string[] = teamState?.actorIds && teamState.actorIds.length > 0 ? teamState.actorIds : [decision?.actorId || actualLeaderId];
  
  const members = memberIds.map(id => ({
    id,
    role: id === actualLeaderId ? 'leader' : (teamState?.members?.find((m: any) => m.id === id)?.role || 'member'),
    currentRegion: decision?.data?.region
  }));

  const proposingActorId = decision?.actorId || actualLeaderId;
  const proposingActor = members.find(m => m.id === proposingActorId) || { id: proposingActorId, role: proposingActorId === actualLeaderId ? 'leader' : 'member' };

  const proposal = {
    id: decision?.id || nextDecisionId(globalDeterministicCounters, 'prop'),
    type: decision?.type || 'action',
    actorId: decision?.actorId || proposingActor.id || leaderActorId,
    teamId: teamState?.id || decision?.teamId,
    data: decision?.data
  };

  const resolution = evaluateGovernanceProposal(proposal, proposingActor, members, mode, settings, undefined, gameState);

  return {
    approved: resolution.approved,
    mode: resolution.mode as TeamGovernanceMode,
    votes: resolution.voteBreakdown,
    reason: resolution.reason,
    resolution
  };
};

export const evaluatePlanSwitchingCost = (
  newPlanUtility: number,
  currentPlanUtility: number,
  switchingCostSetting?: number
): { shouldSwitch: boolean; utilityDelta: number; threshold: number } => {
  const threshold = switchingCostSetting ?? 15.0;
  const utilityDelta = newPlanUtility - currentPlanUtility;
  const shouldSwitch = currentPlanUtility <= 0 || utilityDelta >= threshold;
  return { shouldSwitch, utilityDelta, threshold };
};

export const getEffectiveTacticalIntelligence = (
  actor: any,
  globalSettings?: GameSettingsState
): AiTacticalIntelligenceBoost => {
  const baseDepth = globalSettings?.teamAiTacticalLookaheadDepth ?? 2;
  const baseWidth = globalSettings?.teamAiCandidateEvaluationWidth ?? 5;
  const bonusCash = (actor?.level || 1) * 25;
  const discount = Math.max(0.7, 1.0 - ((actor?.level || 1) * 0.02));
  const extraAp = (actor?.level || 1) >= 5 ? 1 : 0;
  return {
    bonusStartingCash: bonusCash,
    costDiscountMultiplier: discount,
    extraActionPointsPerTurn: extraAp
  };
};

const getAiEconomicCheatBonuses = (
  settings: any,
  aiDifficulty: string
): AiEconomicCheatBonuses => {
  if (!settings?.aiAffectsEconomy) {
    return { bonusStartingCash: 0, yieldBoostMultiplier: 1.0, costDiscountMultiplier: 1.0, extraActionPointsPerTurn: 0 };
  }
  const custom = settings?.aiEconomicCheats;
  const diffMultiplier = aiDifficulty === 'expert' ? 1.25 : aiDifficulty === 'hard' ? 1.15 : aiDifficulty === 'medium' ? 1.05 : 1.0;
  return {
    bonusStartingCash: custom?.bonusStartingCash ?? (aiDifficulty === 'expert' ? 500 : aiDifficulty === 'hard' ? 250 : 0),
    yieldBoostMultiplier: custom?.yieldBoostMultiplier ?? diffMultiplier,
    costDiscountMultiplier: custom?.costDiscountMultiplier ?? (aiDifficulty === 'expert' ? 0.9 : 1.0),
    extraActionPointsPerTurn: custom?.extraActionPointsPerTurn ?? 0
  };
};
export const getEffectiveEconomicCheats = getAiEconomicCheatBonuses;

// V6.9 Phase F3: rejection-outcome dispatch, mirroring resolveRequirementFailureAction's exact
// shape and reusing the same overlapping vocabulary. 'skip'/'wait_next_action' collapse to the
// same 'retry' behavior pre-sequences (no step position or alternate decision source exists yet
// to distinguish them), matching F2's own stated collapsing convention.
const resolveApprovalRejectionOutcome = (
  outcome: ApprovalRejectionOutcome,
  revisionCount: number
): 'end_turn' | 'retry' | 'fallback' => {
  switch (outcome) {
    case 'propose_again':
      return revisionCount < APPROVAL_MAX_REVISED_PROPOSALS ? 'retry' : 'end_turn';
    case 'use_fallback':
      return 'fallback';
    case 'skip':
    case 'wait_next_action':
      return 'retry';
    case 'wait_next_turn':
    case 'end_turn':
    case 'allow_normal_ai':
    case 'pause_sequence':
    case 'cancel_sequence':
    default:
      return 'end_turn';
  }
};

// V6.9 Phase F4: Teammate Action Sequences (core) — a player-authored ordered/prioritized action
// plan per teammate. Storage lives on TeamState.sequences (the authored library), not
// GameSettingsState, matching where activeTeamPlan/teamPlanHistory already live. No ActorState
// field is added — all progress (active step, repeat counters) is carried on the
// TeammateSequence/SequenceStep records themselves, mirroring TeamPlanStep.status's own precedent.
type SequenceMode = 'strict' | 'adaptive' | 'priority';
// 'whole_team' is declared now for schema stability but is NEVER selectable in the F4 Settings Hub
// UI and structurally cannot be looked up (assignedActorId always null for it) — Phase F5's job.
type SequenceScope = 'one_actor' | 'whole_team';
type SupportKind = 'give_cash' | 'give_resource';
type LoanStepAction = 'take' | 'repay' | 'refinance';
interface SequenceWagerRule {
  mode: 'fixed' | 'percentage_of_cash' | 'target_profit' | 'ai_selected_within_limits';
  fixedAmount?: number;
  percentage?: number;
  targetProfit?: number;
  minWager?: number;
  maxWager?: number;
}
interface SequenceSpendingRule {
  costCapAbsolute?: number;
  costCapPercentage?: number;
  minExpectedReturn?: number;
  maxTravelCost?: number;
  maxEquipmentCost?: number;
  maxInvestmentCost?: number;
  maxPaybackPeriod?: number;
  allowRecoverySpending: boolean;
}
export interface SequenceStep {
  id: string;
  order: number;
  priorityRank: number;
  actionCategory: TeamModeActionCategory;
  supportKind?: SupportKind;
  loanStepAction?: LoanStepAction;
  targetKind?: TeamReservationTargetKind;
  targetId?: string;
  targetTeammateId?: string;
  wagerRule?: SequenceWagerRule;
  spendingRule?: SequenceSpendingRule;
  conditionGroup: RequirementGroup | null;
  fallbackBehavior: SequenceStepFallbackAction;
  fallbackJumpToStepId?: string;
  status: 'pending' | 'in_progress' | 'done' | 'skipped' | 'failed';
  stepRepeatCount: number;
}
type SequenceRepeatScope = 'full_sequence' | 'single_step' | 'step_range';
type SequenceRepeatUntil = 'fixed_count' | 'cash_target' | 'net_worth_target' | 'inventory_target' | 'condition_false' | 'phase_change';
interface SequenceRepeatRule {
  enabled: boolean;
  scope: SequenceRepeatScope;
  stepRangeStartId?: string;
  stepRangeEndId?: string;
  until: SequenceRepeatUntil;
  fixedCount?: number;
  cashTarget?: number;
  netWorthTarget?: number;
  inventoryTarget?: { resource: string; amount: number };
  conditionGroup?: RequirementGroup | null;
  targetPhase?: EconomicPhase;
  maxRepeats: number;
}
// V6.9 Phase F5: reuses EMERGENCY_ACTIONS's condition-tag/cooldown/threshold gating shape (GD2),
// with the tag/score-threshold both replaced by Sequences' own existing boolean RequirementGroup
// evaluator — one condition vocabulary across the whole feature, not a parallel scoring system.
interface SequenceInterrupt {
  id: string;
  label: string;
  enabled: boolean;
  triggerConditionGroup: RequirementGroup | null;
  cooldownDays: number;
  lastTriggeredDay: number;
  action: 'pause_sequence' | 'cancel_sequence' | 'jump_to_step' | 'allow_normal_ai_once';
  jumpToStepId?: string;
}
interface TeammateSequence {
  id: string;
  name: string;
  mode: SequenceMode;
  scope: SequenceScope;
  assignedActorId: string | null;
  active: boolean;
  createdByPlayer: boolean;
  steps: SequenceStep[];
  repeatRule: SequenceRepeatRule;
  interrupts: SequenceInterrupt[];
  activeStepId: string | null;
  sequenceRepeatCount: number;
  createdDay: number;
}
// V6.9 Phase F5: binds an actor's active sequence to the game's existing EconomicPhase (Phase C),
// reusing computeEconomicPhase/activateSequenceForActor verbatim — no new phase-detection or
// switching mutation logic, just a daily comparison + a minimum-commitment cooldown on top.
interface PhaseSequenceAssignment {
  actorId: string;
  bindings: Partial<Record<EconomicPhase, string>>;
  minimumCommitmentDays: number;
  lastSwitchDay: number;
  enabled: boolean;
}

const SEQUENCE_MODES: SequenceMode[] = ['strict', 'adaptive', 'priority'];
const SEQUENCE_STEP_FALLBACK_ACTIONS: SequenceStepFallbackAction[] = ['retry_next_action', 'retry_next_turn', 'skip_step', 'jump_to_step', 'use_fallback_action', 'allow_normal_ai', 'pause_sequence', 'end_turn', 'cancel_sequence'];
const SEQUENCE_STEP_MAX_RETRIES = 3;
const SEQUENCE_MAX_JUMP_HOPS = 5;
const SEQUENCE_MAX_REPEATS = 20;

const createNewSequenceStep = (): SequenceStep => ({
  id: nextBranchId(globalDeterministicCounters, 'seqstep'),
  order: 0,
  priorityRank: 0,
  actionCategory: 'challenge',
  conditionGroup: null,
  fallbackBehavior: 'use_fallback_action',
  status: 'pending',
  stepRepeatCount: 0
});

const createNewTeammateSequence = (): TeammateSequence => ({
  id: nextBranchId(globalDeterministicCounters, 'seq'),
  name: 'New Sequence',
  mode: 'adaptive',
  scope: 'one_actor',
  assignedActorId: null,
  active: false,
  createdByPlayer: true,
  steps: [],
  repeatRule: { enabled: false, scope: 'full_sequence', until: 'fixed_count', fixedCount: 1, maxRepeats: 1 },
  interrupts: [],
  activeStepId: null,
  sequenceRepeatCount: 0,
  createdDay: 0
});

const createNewSequenceInterrupt = (): SequenceInterrupt => ({
  id: nextBranchId(globalDeterministicCounters, 'seqint'),
  label: 'New Interrupt',
  enabled: true,
  triggerConditionGroup: null,
  cooldownDays: 3,
  lastTriggeredDay: -1,
  action: 'pause_sequence'
});

export const sanitizeSequenceSpendingRule = (value: unknown): SequenceSpendingRule | undefined => {
  if (!value || typeof value !== 'object') return undefined;
  const src = value as Record<string, any>;
  const parseNum = (v: any, min = 0, max = Infinity) => typeof v === 'number' && isFinite(v) ? Math.max(min, Math.min(max, v)) : undefined;
  return {
    allowRecoverySpending: Boolean(src.allowRecoverySpending),
    costCapAbsolute: parseNum(src.costCapAbsolute, 0),
    costCapPercentage: parseNum(src.costCapPercentage, 0, 100),
    minExpectedReturn: parseNum(src.minExpectedReturn, 0),
    maxTravelCost: parseNum(src.maxTravelCost, 0),
    maxEquipmentCost: parseNum(src.maxEquipmentCost, 0),
    maxInvestmentCost: parseNum(src.maxInvestmentCost, 0),
    maxPaybackPeriod: parseNum(src.maxPaybackPeriod, 0)
  };
};

export const sanitizeSequenceStep = (value: unknown): SequenceStep | null => {
  if (!value || typeof value !== 'object') return null;
  const source = value as Partial<SequenceStep>;
  if (typeof source.id !== 'string') return null;
  const statuses = ['pending', 'in_progress', 'done', 'skipped', 'failed'];
  return {
    id: source.id,
    order: typeof source.order === 'number' && isFinite(source.order) ? source.order : 0,
    priorityRank: typeof source.priorityRank === 'number' && isFinite(source.priorityRank) ? source.priorityRank : 0,
    actionCategory: typeof source.actionCategory === 'string' ? source.actionCategory as TeamModeActionCategory : 'wait',
    supportKind: (source.supportKind === 'give_cash' || source.supportKind === 'give_resource') ? source.supportKind : undefined,
    loanStepAction: (source.loanStepAction === 'take' || source.loanStepAction === 'repay' || source.loanStepAction === 'refinance') ? source.loanStepAction : undefined,
    targetKind: TEAM_RESERVATION_TARGET_KINDS.includes(source.targetKind as TeamReservationTargetKind) ? source.targetKind as TeamReservationTargetKind : undefined,
    targetId: typeof source.targetId === 'string' ? source.targetId : undefined,
    targetTeammateId: typeof source.targetTeammateId === 'string' ? source.targetTeammateId : undefined,
    wagerRule: (source.wagerRule && typeof source.wagerRule === 'object') ? source.wagerRule as SequenceWagerRule : undefined,
    spendingRule: sanitizeSequenceSpendingRule(source.spendingRule),
    conditionGroup: source.conditionGroup ? sanitizeRequirementGroup(source.conditionGroup) : null,
    fallbackBehavior: SEQUENCE_STEP_FALLBACK_ACTIONS.includes(source.fallbackBehavior as SequenceStepFallbackAction) ? source.fallbackBehavior as SequenceStepFallbackAction : 'use_fallback_action',
    fallbackJumpToStepId: typeof source.fallbackJumpToStepId === 'string' ? source.fallbackJumpToStepId : undefined,
    status: statuses.includes(source.status as string) ? source.status as SequenceStep['status'] : 'pending',
    stepRepeatCount: typeof source.stepRepeatCount === 'number' && isFinite(source.stepRepeatCount) ? Math.max(0, source.stepRepeatCount) : 0
  };
};

const SEQUENCE_INTERRUPT_ACTIONS: SequenceInterrupt['action'][] = ['pause_sequence', 'cancel_sequence', 'jump_to_step', 'allow_normal_ai_once'];

const sanitizeSequenceInterrupt = (value: unknown): SequenceInterrupt | null => {
  if (!value || typeof value !== 'object') return null;
  const source = value as Partial<SequenceInterrupt>;
  if (typeof source.id !== 'string') return null;
  return {
    id: source.id,
    label: typeof source.label === 'string' ? source.label : 'Interrupt',
    enabled: Boolean(source.enabled),
    triggerConditionGroup: source.triggerConditionGroup ? sanitizeRequirementGroup(source.triggerConditionGroup) : null,
    cooldownDays: typeof source.cooldownDays === 'number' && isFinite(source.cooldownDays) ? Math.max(0, source.cooldownDays) : 3,
    lastTriggeredDay: typeof source.lastTriggeredDay === 'number' && isFinite(source.lastTriggeredDay) ? source.lastTriggeredDay : -1,
    action: SEQUENCE_INTERRUPT_ACTIONS.includes(source.action as SequenceInterrupt['action']) ? source.action as SequenceInterrupt['action'] : 'pause_sequence',
    jumpToStepId: typeof source.jumpToStepId === 'string' ? source.jumpToStepId : undefined
  };
};

const sanitizeTeammateSequence = (value: unknown): TeammateSequence | null => {
  if (!value || typeof value !== 'object') return null;
  const source = value as Partial<TeammateSequence>;
  if (typeof source.id !== 'string' || typeof source.name !== 'string') return null;
  const steps = Array.isArray(source.steps)
    ? source.steps.map(s => sanitizeSequenceStep(s)).filter((s): s is SequenceStep => Boolean(s))
    : [];
  const interrupts = Array.isArray(source.interrupts)
    ? source.interrupts.map(i => sanitizeSequenceInterrupt(i)).filter((i): i is SequenceInterrupt => Boolean(i))
    : [];
  const repeatRuleSource = (source.repeatRule && typeof source.repeatRule === 'object') ? source.repeatRule as Partial<SequenceRepeatRule> : {};
  return {
    id: source.id,
    name: source.name,
    mode: SEQUENCE_MODES.includes(source.mode as SequenceMode) ? source.mode as SequenceMode : 'adaptive',
    scope: source.scope === 'whole_team' ? 'whole_team' : 'one_actor',
    assignedActorId: typeof source.assignedActorId === 'string' ? source.assignedActorId : null,
    active: Boolean(source.active),
    createdByPlayer: source.createdByPlayer !== false,
    steps,
    repeatRule: {
      enabled: Boolean(repeatRuleSource.enabled),
      scope: (['full_sequence', 'single_step', 'step_range'].includes(repeatRuleSource.scope as string)) ? repeatRuleSource.scope as SequenceRepeatScope : 'full_sequence',
      stepRangeStartId: typeof repeatRuleSource.stepRangeStartId === 'string' ? repeatRuleSource.stepRangeStartId : undefined,
      stepRangeEndId: typeof repeatRuleSource.stepRangeEndId === 'string' ? repeatRuleSource.stepRangeEndId : undefined,
      until: (['fixed_count', 'cash_target', 'net_worth_target', 'inventory_target', 'condition_false', 'phase_change'].includes(repeatRuleSource.until as string)) ? repeatRuleSource.until as SequenceRepeatUntil : 'fixed_count',
      fixedCount: typeof repeatRuleSource.fixedCount === 'number' ? repeatRuleSource.fixedCount : undefined,
      cashTarget: typeof repeatRuleSource.cashTarget === 'number' ? repeatRuleSource.cashTarget : undefined,
      netWorthTarget: typeof repeatRuleSource.netWorthTarget === 'number' ? repeatRuleSource.netWorthTarget : undefined,
      inventoryTarget: (repeatRuleSource.inventoryTarget && typeof repeatRuleSource.inventoryTarget === 'object') ? repeatRuleSource.inventoryTarget : undefined,
      conditionGroup: repeatRuleSource.conditionGroup ? sanitizeRequirementGroup(repeatRuleSource.conditionGroup) : null,
      targetPhase: typeof repeatRuleSource.targetPhase === 'string' ? repeatRuleSource.targetPhase as EconomicPhase : undefined,
      maxRepeats: Math.min(SEQUENCE_MAX_REPEATS, typeof repeatRuleSource.maxRepeats === 'number' && isFinite(repeatRuleSource.maxRepeats) ? Math.max(1, repeatRuleSource.maxRepeats) : 1)
    },
    interrupts,
    activeStepId: typeof source.activeStepId === 'string' ? source.activeStepId : null,
    sequenceRepeatCount: typeof source.sequenceRepeatCount === 'number' && isFinite(source.sequenceRepeatCount) ? Math.max(0, source.sequenceRepeatCount) : 0,
    createdDay: typeof source.createdDay === 'number' && isFinite(source.createdDay) ? Math.max(0, source.createdDay) : 0
  };
};

const sanitizeTeammateSequences = (value: unknown): TeammateSequence[] => {
  if (!Array.isArray(value)) return [];
  return value.map(entry => sanitizeTeammateSequence(entry)).filter((s): s is TeammateSequence => Boolean(s));
};

// Human Player Automation and Action Rules System, Phase HA1: pure schema/scaffolding, matching this
// project's own established "types + inert toggle first, real wiring later" discipline for the first
// phase of every major track (AA1/O1/AB1/F1/GL1). No automation ever executes and none can even be
// created this phase (no CRUD UI exists yet) — HA2 wires real trigger detection + the mandatory
// evaluateActionRequirements/needsApproval gate-call chokepoint + the *ForActor execution dispatch;
// HA3 builds the Automation Dashboard/10 templates/Test-Against-Current-State mode. Deliberately
// separate storage from TeammateSequence (this is for the human player specifically, in every game
// mode, never Team-Mode-AI-scoped) — reuses RequirementGroup/SequenceWagerRule/SequenceSpendingRule/
// SequenceStepFallbackAction/TeamModeActionCategory directly rather than inventing parallel types.
export type HumanAutomationTriggerType =
  | 'turn_start' | 'day_start'
  | 'cash_below_threshold' | 'cash_above_threshold'
  | 'resource_quantity_at_least' | 'resource_quantity_at_most'
  | 'arrived_in_region' | 'challenge_available_in_region'
  | 'recipe_craftable' | 'market_price_at_or_below' | 'market_price_at_or_above'
  | 'manual_test_only'
  | 'day_number_at_or_above' | 'turn_number_at_or_above' | 'challenge_completed' | 'level_at_or_above'
  | 'opponent_aggressiveness_at_or_above' | 'opponent_expansion_at_or_above' | 'opponent_sabotage_risk_at_or_above';
export interface HumanAutomationTrigger {
  type: HumanAutomationTriggerType;
  region?: string;
  resource?: string;
  thresholdAmount?: number;
  recipeId?: string;
}
// Deliberately distinct from OverseerAuthorityMode — this gates whether an already-conditions-satisfied
// automation actually executes without a popup, not whether an AI recommendation is shown at all.
type HumanAutomationAuthorityMode = 'confirm_before_running' | 'notify_after_running' | 'silent_autorun' | 'disabled';
interface HumanAutomationExecutionLimits {
  maxRunsPerDay: number;
  maxRunsTotal: number | null;
  cooldownTurns: number;
}
interface HumanAutomationSafetyLimits {
  maxCostPerRun: number | null;
  minCashRemainingAfterRun: number | null;
  stopIfNoStateChangeCount: number;
}
interface HumanAutomationExecutionStats {
  totalRuns: number;
  totalSuccesses: number;
  totalSkipped: number;
  totalFailed: number;
  lastRunDay: number | null;
  lastRunTurn: number | null;
  lastResultSummary: string;
  // HA2 additions: per-day run counting (maxRunsPerDay enforcement) and a consecutive-no-change
  // counter (stopIfNoStateChangeCount enforcement) — both additive to the HA1 schema.
  runsToday: number;
  runsTodayDay: number;
  consecutiveNoChangeCount: number;
}
export interface HumanAutomationRunLogEntry {
  id: string;
  timestamp: number;
  day: number;
  turn: number;
  ruleId: string;
  ruleName: string;
  triggerType: HumanAutomationTriggerType;
  actionType: TeamModeActionCategory;
  status: 'success' | 'failed' | 'skipped';
  resultMessage: string;
  error?: string;
}
export interface HumanAutomation {
  id: string;
  name: string;
  enabled: boolean;
  trigger: HumanAutomationTrigger;
  conditions: RequirementGroup | null;
  action: TeamModeActionCategory;
  actionParameters: {
    region?: string;
    resource?: string;
    recipeId?: string;
    challengeId?: string;
    itemId?: string;
    amount?: number;
    wagerRule?: SequenceWagerRule;
    spendingRule?: SequenceSpendingRule;
    sequenceId?: string;
  };
  priority: number;
  authorityMode: HumanAutomationAuthorityMode;
  executionLimits: HumanAutomationExecutionLimits;
  safetyLimits: HumanAutomationSafetyLimits;
  fallbackBehavior: SequenceStepFallbackAction | 'disable_automation';
  createdDay: number;
  createdByPlayer: boolean;
  lastEditedDay: number;
  executionStats: HumanAutomationExecutionStats;
  activeFromDay?: number;
  activeUntilDay?: number;
  runHistory?: HumanAutomationRunLogEntry[];
}

export const HUMAN_AUTOMATION_TRIGGER_TYPES: HumanAutomationTriggerType[] = [
  'turn_start', 'day_start', 'cash_below_threshold', 'cash_above_threshold',
  'resource_quantity_at_least', 'resource_quantity_at_most', 'arrived_in_region',
  'challenge_available_in_region', 'recipe_craftable', 'market_price_at_or_below',
  'market_price_at_or_above', 'manual_test_only',
  'day_number_at_or_above', 'turn_number_at_or_above', 'challenge_completed', 'level_at_or_above',
  'opponent_aggressiveness_at_or_above', 'opponent_expansion_at_or_above', 'opponent_sabotage_risk_at_or_above'
];
const HUMAN_AUTOMATION_AUTHORITY_MODES: HumanAutomationAuthorityMode[] = ['confirm_before_running', 'notify_after_running', 'silent_autorun', 'disabled'];
const HUMAN_AUTOMATION_MAX_COUNT = 20;

export const getHumanAutomationMaxSlots = (actorLevel: number, settings: GameSettingsState): number =>
  settings.automationSlotProgressionEnabled ? Math.min(20, Math.max(4, 4 + (actorLevel - 1))) : HUMAN_AUTOMATION_MAX_COUNT;

// Extended HA actions including Part C missing actions & sequence launch
const HUMAN_AUTOMATION_ACTIONS: TeamModeActionCategory[] = ['travel', 'challenge', 'sell', 'craft', 'buy_market', 'region_deposit', 'invest', 'buy_equipment', 'end_turn', 'wait', 'cashout_region', 'loan', 'launch_sequence' as TeamModeActionCategory];

