// --- Auto Mode Proposal Lifecycle Types ---
// Extended status supports full lifecycle: pending → surfaced → dismissed/snoozed/approved/rejected/superseded/expired
export type AutoModeProposalStatus = 'pending' | 'surfaced' | 'approved' | 'rejected' | 'auto_applied' | 'expired' | 'dismissed' | 'snoozed' | 'superseded';

// Recommendation severity determines notification behavior (inbox vs interrupt)
export type AutoModeRecommendationSeverity = 'info' | 'suggestion' | 'important' | 'critical';

// Player-facing notification preference controlling how Auto Mode recommendations are surfaced
export type AutoModeRecommendationNotificationLevel = 'critical_only' | 'important_and_critical' | 'all' | 'off';

export type AutoModeProposal = {
  id: string;
  priorityRank?: number;
  actorId?: number | string;
  targetActorId?: number | string;
  targetTeam?: string;
  targetTeamId?: string;
  performanceState: AutoModePerformanceState;
  category: AutoModeCategory;
  packageId?: string;
  title: string;
  description: string;
  rationale: string;
  proposedPackage: AutoModeAdjustmentPackage;
  previousValues: Record<string, unknown>;
  timestamp?: number;
  proposedTurn: number;
  changesSummary?: string[];
  status: AutoModeProposalStatus;
  payload?: Record<string, unknown>;
  // --- Proposal Lifecycle Metadata (all optional for backward compatibility) ---
  /** Stable semantic identity for deduplication: derived from actorId + category + recommendation family.
   *  Does NOT include timestamps, turn numbers, or temporary IDs. */
  fingerprint?: string;
  /** Notification severity level: determines inbox vs interrupt behavior */
  severity?: AutoModeRecommendationSeverity;
  /** Turn when this proposal was last re-evaluated for staleness */
  lastEvaluatedTurn?: number;
  /** Turn after which this proposal auto-expires if not acted upon */
  expiresTurn?: number;
  /** Performance state at time of proposal creation, for staleness detection */
  performanceStateAtCreation?: AutoModePerformanceState;
  /** ID of the proposal that superseded this one */
  supersededBy?: string;
  /** Turn until which this proposal is snoozed/dismissed (will not resurface before this turn) */
  dismissedUntilTurn?: number;
  /** Grouping key for consolidating related proposals into a single plan */
  consolidationGroup?: string;
  /** If this proposal was escalated from a previously dismissed one, reference the original */
  escalatedFrom?: string;
  /** True if this proposal represents a consolidated high-level plan grouping multiple micro-adjustments */
  isConsolidatedPlan?: boolean;
  /** List of individual micro-adjustment packages included in this consolidated plan */
  microAdjustments?: AutoModeAdjustmentPackage[];
  /** Subcategory/family identifier for recommendation grouping */
  family?: string;
  /** Alias for proposedPackage */
  actionPackage?: AutoModeAdjustmentPackage;
  /** Alias for proposedTurn */
  turnCreated?: number;
  /** Alias for expiresTurn */
  turnExpires?: number;
  /** Alias for dismissedUntilTurn */
  snoozeUntilTurn?: number;
};

