export function sanitizeActorAutoModePolicy(input: unknown): ActorAutoModePolicy {
  const validPermissions: AutoModePermission[] = ['locked', 'observe', 'recommend', 'assist_only', 'challenge_only', 'full_adaptive', 'disabled', 'recommend_only', 'auto_apply_non_intrusive', 'full_auto'];
  const validCategories: AutoModeCategory[] = [
    'pricing', 'capacity', 'route_expansion', 'borrowing', 'debt_repayment',
    'marketing', 'alliance', 'tax_relief', 'subsidy', 'dividend',
    'research', 'economic', 'governance', 'infrastructure', 'emergency',
    'progression', 'regional', 'expedition', 'equipment', 'risk_management',
    'cost_reduction', 'reward_boost', 'dice_favorability', 'income_subsidy',
    'ai_aggression', 'price_inflation', 'handicap_penalty', 'economy_stimulus',
    'opportunity', 'action_boost', 'strategy_shift'
  ];
  const validIntensities: AutoModeIntensity[] = ['gentle', 'balanced', 'responsive', 'director', 'subtle', 'standard', 'aggressive', 'dynamic'];

  if (!input || typeof input !== 'object') {
    return createDefaultActorAutoModePolicy('default');
  }
  const src = input as Record<string, unknown>;
  const actorId = (typeof src.actorId === 'string' || typeof src.actorId === 'number') ? src.actorId : 'default';

  const disabledCategories = Array.isArray(src.disabledCategories)
    ? (src.disabledCategories.filter((cat): cat is AutoModeCategory => typeof cat === 'string' && (validCategories as string[]).includes(cat)))
    : [];

  const allowedAdjustmentCategories = Array.isArray(src.allowedAdjustmentCategories)
    ? (src.allowedAdjustmentCategories.filter((cat): cat is AutoModeCategory => typeof cat === 'string' && (validCategories as string[]).includes(cat)))
    : undefined;

  const permissionRaw = normalizePermissionMode(
    typeof src.permissionMode === 'string' && (validPermissions as string[]).includes(src.permissionMode)
      ? src.permissionMode
      : (typeof src.permission === 'string' && (validPermissions as string[]).includes(src.permission)
        ? src.permission
        : 'full_adaptive')
  );

  const intensityRaw = normalizeAutoModeIntensity(
    typeof src.intensity === 'string' && (validIntensities as string[]).includes(src.intensity)
      ? src.intensity
      : 'balanced'
  );

  return {
    ...src,
    actorId,
    actorName: typeof src.actorName === 'string' ? src.actorName : undefined,
    enabled: typeof src.enabled === 'boolean' ? src.enabled : true,
    permission: permissionRaw,
    permissionMode: permissionRaw,
    disabledCategories,
    ...(allowedAdjustmentCategories !== undefined ? { allowedAdjustmentCategories } : {}),
    intensity: intensityRaw,
  } as ActorAutoModePolicy;
}

