// 3. ExperiencePresetSelector
export const ExperiencePresetSelector: React.FC<ExperiencePresetSelectorProps> = ({
  activePresetId = 'balanced_default',
  onSelectPreset,
  presets = SMART_SETTINGS_PRESETS,
  isDark = true,
  isRetro = false
}) => {
  return (
    <div className={`experience-preset-selector p-4 rounded-xl border space-y-3 ${
      isRetro ? 'bg-amber-900/50 border-amber-700' : isDark ? 'bg-slate-800/80 border-slate-700' : 'bg-white border-slate-300 shadow-xs'
    }`}>
      <div className="flex items-center justify-between">
        <h3 className={`font-bold text-sm flex items-center gap-2 ${
          isRetro ? 'text-amber-300' : isDark ? 'text-sky-400' : 'text-sky-700 font-bold'
        }`}>
          <span>🎯 Experience Presets</span>
          <span className="text-xs font-normal opacity-70">({presets.length} Presets Available)</span>
        </h3>
      </div>
      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-2.5">
        {presets.map(p => {
          const isSelected = p.id === activePresetId;
          const presetName = p.label || p.name || p.id;
          const btnClass = isSelected
            ? isRetro ? 'bg-amber-950 border-amber-400 shadow-md ring-1 ring-amber-400 text-amber-100' : isDark ? 'bg-sky-950/80 border-sky-400 shadow-md ring-1 ring-sky-400' : 'bg-sky-50 border-sky-500 shadow-md ring-1 ring-sky-500'
            : isRetro ? 'bg-amber-950/60 border-amber-800 hover:border-amber-600 hover:bg-amber-900/40 text-amber-200' : isDark ? 'bg-slate-900/60 border-slate-700 hover:border-slate-500 hover:bg-slate-850' : 'bg-slate-50 border-slate-200 hover:border-slate-400 hover:bg-slate-100';
          return (
            <button
              key={p.id}
              type="button"
              onClick={() => onSelectPreset(p.id)}
              className={`p-3 rounded-lg border text-left transition-all flex flex-col justify-between gap-1.5 ${btnClass}`}
            >
              <div>
                <div className={`font-bold text-xs flex items-center justify-between gap-1 ${
                  isRetro ? 'text-amber-100' : isDark ? 'text-white' : 'text-slate-900'
                }`}>
                  <span>{presetName}</span>
                  {isSelected && <span className={isRetro ? 'text-amber-400 text-xs font-bold' : isDark ? 'text-sky-400 text-xs' : 'text-sky-600 text-xs font-bold'}>✓</span>}
                </div>
                <p className={`text-[11px] line-clamp-2 mt-1 leading-tight ${
                  isRetro ? 'text-amber-200/80' : isDark ? 'text-slate-300 opacity-75' : 'text-slate-700'
                }`}>{p.description}</p>
              </div>
              <div className={`text-[10px] font-mono pt-1 border-t ${
                isRetro ? 'border-amber-800/80 text-amber-300/70' : isDark ? 'border-slate-800 opacity-60 text-slate-400' : 'border-slate-200 text-slate-600'
              }`}>
                Pace: {p.profile?.gamePace || 'normal'} • AI: {p.profile?.aiIntelligence || 'capable'}
              </div>
            </button>
          );
        })}
      </div>
    </div>
  );
};

