// 6. ExperiencePlanPreview
export const ExperiencePlanPreview: React.FC<ExperiencePlanPreviewProps> = ({
  plan,
  isOpen = true,
  onApplyPlan,
  onClose,
  isLiveMatch = false
}) => {
  if (!isOpen || !plan) return null;

  const changesCount = plan.changes?.length || 0;
  const conflictsCount = plan.conflicts?.length || 0;

  return (
    <div className="experience-plan-preview fixed inset-0 bg-black/60 backdrop-blur-xs flex items-center justify-center p-4 overflow-hidden" style={{ zIndex: globalUISurfaceManager.getZIndex("settings_hub") }}>
      <div className="bg-slate-900 border border-slate-700 rounded-xl max-w-2xl w-full flex flex-col max-h-[calc(100dvh-2rem)] shadow-2xl">
        <div className="p-4 border-b border-slate-700 flex items-center justify-between bg-slate-850">
          <h3 className="font-bold text-base text-sky-400 flex items-center gap-2">
            <span>📋 Smart Settings Plan Preview</span>
            <span className="text-xs px-2 py-0.5 rounded bg-sky-950 text-sky-300 font-mono">
              {changesCount} change{changesCount !== 1 ? 's' : ''}
            </span>
          </h3>
          {onClose && (
            <button type="button" onClick={onClose} className="text-slate-400 hover:text-white text-lg font-bold px-2">
              ✕
            </button>
          )}
        </div>
        <div className="p-4 overflow-y-auto space-y-3 flex-1 text-xs">
          {conflictsCount > 0 && (
            <div className="p-3 bg-amber-950/40 border border-amber-700/60 rounded-lg text-amber-200">
              <strong className="block mb-1 font-semibold">⚠️ {conflictsCount} Conflict(s) Detected:</strong>
              {plan.conflicts.map((c, i) => (
                <div key={i} className="mt-1 opacity-90">• {c.settingKey}: {c.reason}</div>
              ))}
            </div>
          )}
          <div className="space-y-2">
            {changesCount === 0 ? (
              <p className="opacity-70 italic text-center py-4">No settings changes are proposed in this plan.</p>
            ) : (
              plan.changes.map((chg, idx) => {
                const prevVal = chg.previousValue !== undefined ? chg.previousValue : chg.oldValue;
                const propVal = chg.proposedValue !== undefined ? chg.proposedValue : chg.newValue;
                const status = chg.safetyStatus || chg.safetyClassification || 'safe';
                return (
                  <div key={idx} className="p-3 bg-slate-800/80 rounded-lg border border-slate-700 flex justify-between items-center gap-3">
                    <div>
                      <div className="font-semibold text-white text-xs">{chg.settingKey}</div>
                      <div className="text-[11px] opacity-70 mt-0.5">Category: {chg.category}</div>
                      {chg.sourcePreference && <div className="text-[11px] text-sky-300 mt-0.5">{chg.sourcePreference}</div>}
                    </div>
                    <div className="text-right shrink-0">
                      <div className="font-mono text-xs">
                        <span className="opacity-60 line-through mr-1">{String(prevVal)}</span>
                        <span className="text-emerald-400 font-bold">→ {String(propVal)}</span>
                      </div>
                      {isLiveMatch && status && (
                        <span className={`text-[10px] px-1.5 py-0.5 rounded font-mono mt-1 inline-block ${
                          status === 'safe' || status === 'safe_live' ? 'bg-emerald-950 text-emerald-300' : 'bg-amber-950 text-amber-300'
                        }`}>
                          {status}
                        </span>
                      )}
                    </div>
                  </div>
                );
              })
            )}
          </div>
        </div>
        <div className="p-4 border-t border-slate-700 flex justify-end items-center gap-2 bg-slate-850">
          {onClose && (
            <button type="button" onClick={onClose} className="px-3 py-1.5 rounded bg-slate-800 hover:bg-slate-700 text-slate-200 text-xs transition-colors">
              Cancel
            </button>
          )}
          {onApplyPlan && (
            <button
              type="button"
              onClick={() => {
                onApplyPlan(plan);
                if (onClose) onClose();
              }}
              className="px-4 py-1.5 rounded bg-sky-600 hover:bg-sky-500 text-white text-xs font-semibold transition-colors"
            >
              Apply Plan ({changesCount})
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

