// ============================================================================
// MILESTONE 2: 10-CARD VISUAL HIERARCHY & EXPERIENCE DIRECTOR PANEL COMPONENTS
// ============================================================================

// Major Transition Risk Evaluation Engine (R3)
export interface TransitionRiskItem {
  dimension: 'Auto Mode' | 'Co-Pilot AI' | 'Guardian AI' | 'Rival AI';
  key: 'automation' | 'coPilotMode' | 'guardianLevel' | 'aiIntelligence';
  fromValue: string;
  toValue: string;
  severity: 'CRITICAL' | 'HIGH';
  description: string;
}

export interface TransitionRiskAssessment {
  isHighRisk: boolean;
  risks: TransitionRiskItem[];
  affectedSettingsCount: number;
  parameterDiffs: { key: string; label: string; fromValue: any; toValue: any }[];
}

export function evaluateTransitionRisk(
  fromProfile: SmartSettingsProfile,
  toProfile: SmartSettingsProfile,
  plan?: SmartSettingsPlan
): TransitionRiskAssessment {
  const risks: TransitionRiskItem[] = [];

  // 1. Auto Mode: manual / recommendations -> mostly_automatic / full_auto
  const fromAuto = fromProfile.automation || 'recommendations';
  const toAuto = toProfile.automation || 'recommendations';
  const lowAuto = ['manual', 'recommendations'];
  const highAuto = ['mostly_automatic', 'full_auto'];
  if (lowAuto.includes(fromAuto) && highAuto.includes(toAuto)) {
    risks.push({
      dimension: 'Auto Mode',
      key: 'automation',
      fromValue: fromAuto,
      toValue: toAuto,
      severity: (toAuto as string) === 'full_auto' ? 'CRITICAL' : 'HIGH',
      description: `Auto Mode transitioning to '${toAuto}': match management and strategic decisions will be executed automatically with reduced player confirmation.`
    });
  }

  // 2. Co-Pilot AI: off / advisor -> active_assistant / takeover_requested / autonomous_takeover
  const fromCopilot = fromProfile.coPilotMode || 'off';
  const toCopilot = toProfile.coPilotMode || 'off';
  const lowCopilot = ['off', 'advisor'];
  const highCopilot = ['active_assistant', 'takeover_requested', 'autonomous_takeover'];
  if (lowCopilot.includes(fromCopilot) && highCopilot.includes(toCopilot)) {
    risks.push({
      dimension: 'Co-Pilot AI',
      key: 'coPilotMode',
      fromValue: fromCopilot,
      toValue: toCopilot,
      severity: ['takeover_requested', 'autonomous_takeover'].includes(toCopilot) ? 'CRITICAL' : 'HIGH',
      description: `Co-Pilot AI transitioning to '${toCopilot}': assistant AI will execute turn actions and take over player control.`
    });
  }

  // 3. Guardian AI: off / critical_only -> strong_protection / maximum_protection
  const fromGuardian = fromProfile.guardianLevel || 'off';
  const toGuardian = toProfile.guardianLevel || 'off';
  const lowGuardian = ['off', 'critical_only'];
  const highGuardian = ['strong_protection', 'maximum_protection'];
  if (lowGuardian.includes(fromGuardian) && highGuardian.includes(toGuardian)) {
    risks.push({
      dimension: 'Guardian AI',
      key: 'guardianLevel',
      fromValue: fromGuardian,
      toValue: toGuardian,
      severity: toGuardian === 'maximum_protection' ? 'CRITICAL' : 'HIGH',
      description: `Guardian AI transitioning to '${toGuardian}': strict blunder guardrails will actively block high-risk moves.`
    });
  }

  // 4. Rival AI: casual / capable -> expert / maximum
  const fromRival = fromProfile.aiIntelligence || 'casual';
  const toRival = toProfile.aiIntelligence || 'casual';
  const lowRival = ['casual', 'capable'];
  const highRival = ['expert', 'maximum'];
  if (lowRival.includes(fromRival) && highRival.includes(toRival)) {
    risks.push({
      dimension: 'Rival AI',
      key: 'aiIntelligence',
      fromValue: fromRival,
      toValue: toRival,
      severity: toRival === 'maximum' ? 'CRITICAL' : 'HIGH',
      description: `Rival AI transitioning to '${toRival}': opponent AI will deploy optimal decision making and aggressive strategy.`
    });
  }

  const profileKeys: (keyof SmartSettingsProfile)[] = [
    'automation', 'coPilotMode', 'guardianLevel', 'aiIntelligence',
    'aiFairness', 'gamePace', 'complexity', 'randomness', 'teamCoordination', 'guidance', 'experienceStyle'
  ];

  const parameterDiffs: { key: string; label: string; fromValue: any; toValue: any }[] = [];
  for (const k of profileKeys) {
    const vFrom = (fromProfile as any)[k];
    const vTo = (toProfile as any)[k];
    if (vFrom !== undefined && vTo !== undefined && vFrom !== vTo) {
      parameterDiffs.push({
        key: k,
        label: k.replace(/([A-Z])/g, ' $1').replace(/^./, str => str.toUpperCase()),
        fromValue: vFrom,
        toValue: vTo
      });
    }
  }

  const affectedSettingsCount = plan ? plan.changes.length : (parameterDiffs.length || risks.length);

  return {
    isHighRisk: risks.length > 0,
    risks,
    affectedSettingsCount,
    parameterDiffs
  };
}

const HIGH_RISK_DIMENSION_SETTING_KEYS: Record<string, string[]> = {
  coPilotMode: ['coPilotEnabled', 'coPilotAuthorityMode'],
  automation: ['autoModeEnabled', 'permissionMode', 'humanAutomationEnabled'],
  guardianLevel: ['guardianAiEnabled', 'guardianAiProtectionLevel', 'guardianAiResponseMode'],
  aiIntelligence: [
    'aiPlanningDepth',
    'aiThinkingDepth',
    'teamAiTacticalLookaheadDepth',
    'teamAiCandidateEvaluationWidth',
    'teamAiPlanMaximumDurationDays',
    'projectedOutcomeHorizon'
  ]
};

export function slimHighRiskTransitionPlan(
  plan: SmartSettingsPlan | null | undefined,
  profile: SmartSettingsProfile | null | undefined,
  risks: TransitionRiskItem[] | null | undefined
): SmartSettingsPlan | null {
  if (!plan && !profile) return null;
  const allowed = new Set<string>();
  const riskList = Array.isArray(risks) ? risks : [];
  for (const risk of riskList) {
    const keys = HIGH_RISK_DIMENSION_SETTING_KEYS[risk.key];
    if (keys) keys.forEach(k => allowed.add(k));
  }
  if (allowed.size === 0) {
    HIGH_RISK_DIMENSION_SETTING_KEYS.coPilotMode.forEach(k => allowed.add(k));
  }
  const profileAfter = {
    ...(plan?.profile || {}),
    ...(profile || {})
  } as SmartSettingsProfile;
  const changes: SmartSettingsChange[] = (plan?.changes || []).filter(c => allowed.has(c.settingKey));
  if (allowed.has('coPilotAuthorityMode') && profileAfter.coPilotMode && typeof mapConceptualModeToTechnicalSettings === 'function') {
    const mapped = mapConceptualModeToTechnicalSettings(profileAfter.coPilotMode);
    if (!changes.some(c => c.settingKey === 'coPilotEnabled')) {
      changes.push({
        settingKey: 'coPilotEnabled',
        category: 'ai',
        previousValue: undefined,
        proposedValue: mapped.coPilotEnabled,
        sourcePreference: `coPilotMode:${profileAfter.coPilotMode}`,
        safetyStatus: 'safe'
      });
    }
    if (!changes.some(c => c.settingKey === 'coPilotAuthorityMode')) {
      changes.push({
        settingKey: 'coPilotAuthorityMode',
        category: 'ai',
        previousValue: undefined,
        proposedValue: mapped.authorityMode,
        sourcePreference: `coPilotMode:${profileAfter.coPilotMode}`,
        safetyStatus: 'safe'
      });
    }
  }
  return {
    planId: plan?.planId || `high_risk_${Date.now()}`,
    timestamp: plan?.timestamp || Date.now(),
    profile: profileAfter,
    changes,
    conflicts: plan?.conflicts || [],
    autoModeBoundaries: plan?.autoModeBoundaries || {},
    fairnessSummary: plan?.fairnessSummary || '',
    summary: `High-risk transition: ${changes.length} setting(s) for ${riskList.map(r => r.dimension).join(', ') || 'Co-Pilot'}.`
  };
}

export function isHighRiskCoPilotOnlyPlan(plan: SmartSettingsPlan | null | undefined): boolean {
  if (!plan) return false;
  const mode = plan.profile?.coPilotMode;
  if (mode !== 'autonomous_takeover' && mode !== 'takeover_requested') return false;
  const keys = (plan.changes || []).map(c => c.settingKey);
  if (keys.length === 0) return true;
  const allowed = new Set([
    'coPilotEnabled',
    'coPilotAuthorityMode',
    'coPilotMode',
    'experienceStyle',
    'customOverridesDetected',
    'activePresetId'
  ]);
  return keys.every(k => allowed.has(k) || String(k).toLowerCase().includes('copilot'));
}

export function applyHighRiskCoPilotSettingsPatch(
  prev: GameSettingsState,
  plan: SmartSettingsPlan | null | undefined
): GameSettingsState {
  const mode = plan?.profile?.coPilotMode;
  const mapped = mode && typeof mapConceptualModeToTechnicalSettings === 'function'
    ? mapConceptualModeToTechnicalSettings(mode)
    : null;
  const nextCp = {
    ...(prev.coPilotSettings || createDefaultCoPilotSettings()),
    ...(mapped ? { coPilotEnabled: mapped.coPilotEnabled, authorityMode: mapped.authorityMode } : {}),
    // On Request maps to authority 'automatic_rescue', which is only executable when its own
    // automaticRescueEnabled switch is on (default off) — so Start Co-Pilot silently did nothing.
    ...(mapped?.authorityMode === 'automatic_rescue' ? { automaticRescueEnabled: true } : {})
  };
  return {
    ...prev,
    coPilotSettings: nextCp,
    smartSettingsProfile: {
      ...(prev.smartSettingsProfile || createDefaultSmartSettingsProfile()),
      ...(plan?.profile || {}),
      lastAppliedPlanId: plan?.planId
    }
  };
}

export function startCoPilotAutonomousTakeover(input: {
  player?: any;
  gameState: any;
  gameSettings?: any;
  takeoverSession?: CoPilotTakeoverSession | null;
  actorsById?: any;
  aiPlayer?: any;
    teamsById?: any;
  appendReplayEvent?: (category: any, fields: any) => void;
  skipClaim?: boolean;
}): CoPilotTakeoverSession | null {
  try {
    const player = input.player || input.gameState?.player;
    const gameSettings = input.gameSettings || input.gameState?.gameSettings;
    const cpSettings = resolveCanonicalCoPilotSettings(
      gameSettings?.coPilotSettings || input.gameState?.coPilotSettings,
      input.gameState,
      gameSettings
    );
    if (!isCoPilotAuthorityExecutable(cpSettings)) return null;
    const actorId = player?.id || input.gameState?.humanPlayerId || 'player';
    const turn = input.gameState?.turnCounter || input.gameState?.turn || 1;
    const dummyRec: CoPilotRecommendation = {
      id: `rec_explicit_start_${turn}`,
      type: 'tactical_optimization',
      title: 'Autonomous Mode Active',
      description: 'Co-Pilot autonomous takeover started from Start Co-Pilot.',
      confidenceScore: 90,
      reasoningSummary: 'Player started Autonomous Co-Pilot from the HUD.',
      multiTurnPlanSequence: [],
      teachingExplanation: 'Co-Pilot actively managing player operations in autonomous mode.',
      targetActorId: actorId,
      generatedTurn: turn,
      priorityWeight: 90,
      category: 'economy'
    };
    const dummyObj: CoPilotRecoveryObjective = {
      id: `obj_explicit_start_${turn}`,
      actorId,
      type: 'rebuild_team_economy',
      description: 'Autonomous Mode Turn Operations',
      priority: 'high',
      targetMetrics: {},
      maxTurns: 10,
      maxSpendAllowed: 10000,
      allowedActionCategories: [],
      status: 'active',
      progressPercentage: 0,
      targetTurn: turn + 10,
      createdTurn: turn
    };
    const context = createCoPilotRuntimeContext(
      player,
      input.gameState,
      gameSettings,
      input.takeoverSession,
      input.actorsById,
      input.aiPlayer,
      input.teamsById
    );
    // On Request ("1-click takeover") plays the current turn and hands control back; Autonomous runs
    // until the player takes control.
    const scope: CoPilotTakeoverScope = cpSettings.authorityMode === 'automatic_rescue' ? 'current_turn' : 'continuous';
    return initiateCoPilotTakeover(
      context,
      dummyRec,
      dummyObj,
      scope,
      cpSettings,
      {
        ...(input.appendReplayEvent ? { appendReplayEvent: input.appendReplayEvent } : {}),
        skipClaim: Boolean(input.skipClaim)
      }
    );
  } catch (err) {
    console.error('[startCoPilotAutonomousTakeover] failed', err);
    return null;
  }
}

