                  <span className="font-mono">
                    <span className="text-slate-400">{String(diff.fromValue)}</span>
                    <span className="mx-1 text-slate-500">→</span>
                    <span className="text-amber-300 font-semibold">{String(diff.toValue)}</span>
                  </span>
