// Card 3: AutoModeCard
export interface AutoModeCardProps {
  profile: SmartSettingsProfile;
  gameSettings?: GameSettingsState;
  onChangeAutomation: (level: AutomationPreference) => void;
  onChangeAutonomyLevel?: (level: AutonomyLevel) => void;
  onChangePrimaryGoal?: (goal: AutoModePrimaryGoalId) => void;
  onToggleAutoMode?: (enabled: boolean) => void;
  onOpenAdvancedAutoMode?: () => void;
  isDark?: boolean;
  isRetro?: boolean;
}

export const AutoModeCard: React.FC<AutoModeCardProps> = ({
  profile,
  gameSettings,
  onChangeAutomation,
  onChangeAutonomyLevel,
  onChangePrimaryGoal,
  onToggleAutoMode,
  onOpenAdvancedAutoMode,
  isDark = true,
  isRetro = false
}) => {
  const currentAuto = profile?.automation || 'recommendations';
  const isLocked = (profile?.lockedSettingKeys || []).includes('automation') || (profile?.lockedCategories || []).includes('automation');

  const authority = resolveEffectiveAutonomyAuthority(gameSettings, profile);
  const currentAutonomyLevel: AutonomyLevel = authority.level;
  const masterEnabled = authority.masterEnabled;

  const goalFromProps = (gameSettings?.autoModeSettings as any)?.primaryGoal || (profile as any)?.autoModePrimaryGoal || 'balanced_strategy';
  const [selectedGoalId, setSelectedGoalId] = safeUseState<AutoModePrimaryGoalId>(goalFromProps);

  safeUseEffect(() => {
    if (goalFromProps && goalFromProps !== selectedGoalId) {
      setSelectedGoalId(goalFromProps);
    }
  }, [goalFromProps]);

  const activeGoal = AUTO_MODE_PRIMARY_GOALS[selectedGoalId] || AUTO_MODE_PRIMARY_GOALS['balanced_strategy'];

  // Status Badge Logic
  let statusBadge = { label: '🟢 Active', colorClass: 'bg-emerald-950/80 border-emerald-800 text-emerald-300' };
  if (!masterEnabled || currentAutonomyLevel === 'off') {
    statusBadge = { label: '🔴 Disabled', colorClass: 'bg-rose-950/80 border-rose-800 text-rose-300' };
  } else if (authority.sourceConflictResolved || (authority.conflictDetails || []).length > 0) {
    statusBadge = { label: '⚠️ Conflict', colorClass: 'bg-amber-950/80 border-amber-800 text-amber-300' };
  } else if (currentAutonomyLevel === 'observe') {
    statusBadge = { label: '⏸️ Paused', colorClass: 'bg-slate-900/80 border-slate-700 text-slate-300' };
  }

  const levels: { level: AutonomyLevel; label: string; legacyAuto: AutomationPreference; desc: string }[] = [
    { level: 'off', label: 'Off', legacyAuto: 'manual', desc: 'Manual control' },
    { level: 'observe', label: 'Observe', legacyAuto: 'recommendations', desc: 'Monitor & logs' },
    { level: 'recommend', label: 'Recommend', legacyAuto: 'recommendations', desc: 'Action hints' },
    { level: 'assist', label: 'Assist', legacyAuto: 'assisted', desc: 'Routine helper' },
    { level: 'supervised_auto', label: 'Supervised Auto', legacyAuto: 'mostly_automatic', desc: 'Bounded execution' },
    { level: 'full_auto', label: 'Full Auto', legacyAuto: 'mostly_automatic', desc: 'Hands-free' }
  ];

  const handleLevelSelect = (lvl: AutonomyLevel, legacyAuto: AutomationPreference) => {
    if (isLocked) return;
    if (onChangeAutonomyLevel) {
      onChangeAutonomyLevel(lvl);
    } else {
      onChangeAutomation(legacyAuto);
    }
  };

  const handleMasterToggle = () => {
    if (isLocked) return;
    const newMasterState = !masterEnabled;
    if (onToggleAutoMode) {
      onToggleAutoMode(newMasterState);
    } else {
      if (!newMasterState) {
        handleLevelSelect('off', 'manual');
      } else {
        handleLevelSelect('recommend', 'recommendations');
      }
    }
  };

  const handleGoalChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const goalId = e.target.value as AutoModePrimaryGoalId;
    setSelectedGoalId(goalId);
    if (onChangePrimaryGoal) {
      onChangePrimaryGoal(goalId);
    }
  };

  // Live Plan telemetry summary
  const livePlan = (gameSettings?.autoModeSettings as any)?.activePlan as AutoModePlan | undefined;
  const planStatus = livePlan?.status || (masterEnabled && currentAutonomyLevel !== 'off' ? 'active' : 'idle');
  const confidenceScore = livePlan?.confidenceScore ?? (masterEnabled ? 88 : 0);
  const currentStep = livePlan?.steps?.[livePlan.currentStepIndex || 0];

  return (
    <div className={`auto-mode-card p-4 rounded-xl border space-y-3.5 ${
      isRetro ? 'bg-amber-900/60 border-amber-700 text-amber-100' : isDark ? 'bg-slate-800/90 border-slate-700 text-slate-100' : 'bg-white border-slate-300 text-slate-900 shadow-xs'
    }`}>
      {/* Header: Title, Status Badge, Master On/Off Toggle */}
      <div className="flex items-center justify-between flex-wrap gap-2">
        <div className="flex items-center gap-2">
          <h3 className="font-bold text-sm flex items-center gap-2 text-cyan-400">
            <span>🤖 Auto Mode 2.0</span>
            {isLocked && <span className="text-xs text-purple-400">🔒 Locked</span>}
          </h3>
          <span className={`text-xs px-2.5 py-0.5 rounded-full border font-semibold ${statusBadge.colorClass}`}>
            {statusBadge.label}
          </span>
        </div>
        <div className="flex items-center gap-2">
          <span className="text-xs text-slate-400 font-medium">Master Switch:</span>
          <button
            type="button"
            disabled={isLocked}
            onClick={handleMasterToggle}
            className={`px-3 py-1 rounded-lg text-xs font-bold transition-all cursor-pointer border ${
              masterEnabled
                ? 'bg-emerald-600 hover:bg-emerald-500 text-white border-emerald-500 shadow-sm'
                : 'bg-slate-700 hover:bg-slate-600 text-slate-300 border-slate-600'
            } ${isLocked ? 'opacity-50 cursor-not-allowed' : ''}`}
          >
            {masterEnabled ? 'ON' : 'OFF'}
          </button>
        </div>
      </div>

      {/* 6 Autonomy Level Selector Button Group */}
      <div className="space-y-1">
        <div className="text-[11px] font-semibold text-slate-400 uppercase tracking-wider">Autonomy Level:</div>
        <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-1.5">
          {levels.map(lvl => {
            const isSelected = currentAutonomyLevel === lvl.level;
            return (
              <button
                key={lvl.level}
                type="button"
                disabled={isLocked}
                onClick={() => handleLevelSelect(lvl.level, lvl.legacyAuto)}
                className={`p-2 rounded-lg border text-center transition-all cursor-pointer ${
                  isSelected
                    ? 'bg-cyan-950 border-cyan-500 text-cyan-200 ring-1 ring-cyan-500 font-bold shadow-xs'
                    : 'bg-slate-900/70 border-slate-700 text-slate-300 hover:border-slate-500'
                } ${isLocked ? 'opacity-50 cursor-not-allowed' : ''}`}
              >
                <div className="text-xs font-semibold">{lvl.label}</div>
                <div className="text-[10px] opacity-75 mt-0.5 truncate">{lvl.desc}</div>
              </button>
            );
          })}
        </div>
      </div>

      {/* 10 Primary Goals Selector Dropdown */}
      <div className="space-y-1">
        <label className="text-[11px] font-semibold text-slate-400 uppercase tracking-wider flex items-center justify-between">
          <span>Primary Strategic Goal:</span>
          <span className="text-[11px] text-cyan-300 font-normal">{activeGoal.icon} {activeGoal.label}</span>
        </label>
        <select
          value={activeGoal.id}
          disabled={isLocked}
          onChange={handleGoalChange}
          className={`w-full text-xs p-2 rounded-lg border bg-slate-900 text-slate-100 border-slate-700 focus:border-cyan-500 focus:outline-none cursor-pointer ${
            isLocked ? 'opacity-50 cursor-not-allowed' : ''
          }`}
        >
          {Object.values(AUTO_MODE_PRIMARY_GOALS).map(g => (
            <option key={g.id} value={g.id}>
              {g.icon} {g.label} — {g.description}
            </option>
          ))}
        </select>
      </div>

      {/* Compact Live Plan Display */}
      <div className={`p-2.5 rounded-lg border space-y-1.5 ${isDark ? 'bg-slate-900/80 border-slate-700/80' : 'bg-slate-50 border-slate-200'}`}>
        <div className="flex items-center justify-between text-xs">
          <div className="flex items-center gap-1.5 font-medium">
            <span>📋 Live Plan:</span>
            <span className={`px-1.5 py-0.5 rounded text-[10px] uppercase font-bold ${
              planStatus === 'active' ? 'bg-emerald-950 text-emerald-300 border border-emerald-800' :
              planStatus === 'replanning' ? 'bg-amber-950 text-amber-300 border border-amber-800' :
              'bg-slate-800 text-slate-400 border border-slate-700'
            }`}>
              {planStatus}
            </span>
          </div>
          {confidenceScore > 0 && (
            <span className="text-[11px] font-mono text-cyan-300 font-semibold">
              {confidenceScore}% confidence
            </span>
          )}
        </div>
        <div className="text-[11px] text-slate-300 truncate">
          {currentStep ? (
            <span>Step {(livePlan?.currentStepIndex || 0) + 1}/{livePlan?.steps.length || 1}: {currentStep.title}</span>
          ) : (
            <span className="opacity-70 italic">Goal: {activeGoal.label} ({activeGoal.description})</span>
          )}
        </div>
      </div>

      {/* Footer Navigation */}
      <div className="flex items-center justify-between text-xs pt-2 border-t border-slate-700/50">
        <span className="text-slate-400 text-[11px]">
          Authority: {authority.effectivePermissionMode}
        </span>
        {onOpenAdvancedAutoMode && (
          <button
            type="button"
            onClick={onOpenAdvancedAutoMode}
            className="text-cyan-400 hover:text-cyan-300 font-semibold flex items-center gap-1 transition-colors cursor-pointer"
          >
            <span>Advanced Auto Mode Settings</span>
            <span>→</span>
          </button>
        )}
      </div>
    </div>
  );
};

// Card 4: CoPilotAiCard
export interface CoPilotAiCardProps {
  profile: SmartSettingsProfile;
  gameSettings?: GameSettingsState;
  onChangeCoPilotMode: (mode: string) => void;
  onOpenAdvancedCoPilot?: () => void;
  selectedMode?: string;
  isDark?: boolean;
  isRetro?: boolean;
}

export const CoPilotAiCard: React.FC<CoPilotAiCardProps> = ({
  profile,
  gameSettings,
  onChangeCoPilotMode,
  onOpenAdvancedCoPilot,
  selectedMode = 'standard',
  isDark = true,
  isRetro = false
}) => {
  const isAiVsAi = selectedMode === 'team_ai_vs_ai';
  const currentMode = profile.coPilotMode || 'advisor';
  const isLocked = (profile.lockedSettingKeys || []).includes('coPilot') || (profile.lockedCategories || []).includes('copilot');

  const modes = [
    { value: 'off', label: 'Manual', desc: 'You play everything' },
    { value: 'advisor', label: 'Advisor', desc: 'Recommends only' },
    { value: 'active_assistant', label: 'Assistant', desc: 'Asks before acting' },
    { value: 'takeover_requested', label: 'Rescue', desc: '1-click / emergency takeover' },
    { value: 'autonomous_takeover', label: 'Autonomous', desc: 'Plays after Start' }
  ];

  return (
    <div className={`copilot-ai-card p-4 rounded-xl border space-y-3 ${
      isRetro ? 'bg-amber-900/60 border-amber-700 text-amber-100' : isDark ? 'bg-slate-800/90 border-slate-700 text-slate-100' : 'bg-white border-slate-300 text-slate-900 shadow-xs'
    }`}>
      <div className="flex items-center justify-between">
        <h3 className="font-bold text-sm flex items-center gap-2 text-indigo-400">
          <span>🧠 Co-Pilot AI (Human Assistant)</span>
          {isLocked && <span className="text-xs text-purple-400">🔒 Locked</span>}
        </h3>
        <span className="text-xs px-2 py-0.5 rounded bg-indigo-950 border border-indigo-800 text-indigo-300 capitalize font-mono">
          {String(currentMode).replace(/_/g, ' ')}
        </span>
      </div>

      {isAiVsAi && (
        <div className="p-2 rounded bg-amber-950/70 border border-amber-800 text-amber-300 text-xs flex items-center gap-2">
          <span>⚠️</span>
          <span>Human Co-Pilot is non-applicable in AI-vs-AI mode (all actors are AI controlled).</span>
        </div>
      )}

      <div className="grid grid-cols-1 sm:grid-cols-5 gap-2">
        {modes.map(m => {
          const isSelected = currentMode === m.value;
          return (
            <button
              key={m.value}
              type="button"
              disabled={isAiVsAi || isLocked}
              onClick={() => onChangeCoPilotMode(m.value)}
              className={`p-2 rounded-lg border text-center transition-all ${
                isSelected
                  ? 'bg-indigo-950 border-indigo-500 text-indigo-200 ring-1 ring-indigo-500 font-bold'
                  : 'bg-slate-900/70 border-slate-700 text-slate-300 hover:border-slate-500'
              } ${(isAiVsAi || isLocked) ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer'}`}
            >
              <div className="text-xs font-semibold">{m.label}</div>
              <div className="text-[10px] opacity-75 mt-0.5">{m.desc}</div>
            </button>
          );
        })}
      </div>

      <div className="flex items-center justify-between text-xs pt-1 border-t border-slate-700/50">
        <span className="text-slate-400">Spending Cap: $2,500/action • Min Reserve: $250</span>
        {onOpenAdvancedCoPilot && (
          <button
            type="button"
            onClick={onOpenAdvancedCoPilot}
            className="text-indigo-400 hover:text-indigo-300 font-semibold flex items-center gap-1 transition-colors"
          >
            <span>Advanced Co-Pilot Settings</span>
            <span>→</span>
          </button>
        )}
      </div>
    </div>
  );
};

