// ============================================================================
// TASK 14 & 15: SETTINGS SEARCH RESULT CARDS & SAFE INLINE EDITING
// ============================================================================

export interface SettingsSearchResultCardProps {
  entry: SettingsHubSearchEntry;
  gameSettings: GameSettingsState;
  draftSettings?: Partial<GameSettingsState> | null;
  onUpdateSetting: (key: keyof GameSettingsState, value: any) => void;
  onOpenSection: (tab: SettingsHubTabId, sectionId: string, fieldKey?: string) => void;
  depReport?: any;
  themeStyles: any;
}

export const SettingsSearchResultCard: React.FC<SettingsSearchResultCardProps> = ({
  entry,
  gameSettings,
  draftSettings,
  onUpdateSetting,
  onOpenSection,
  depReport,
  themeStyles
}) => {
  const keyStr = (entry.key || entry.id) as keyof GameSettingsState;
  const section = SETTINGS_HUB_SECTION_INDEX.find(s => s.id === entry.id || s.fieldKeys.includes(keyStr));
  const meta = SETTINGS_HUB_FIELD_META[keyStr as string];

  const currentSettingsObj = (draftSettings && Object.keys(draftSettings).length > 0)
    ? { ...gameSettings, ...draftSettings }
    : gameSettings;

  const defaultVal = DEFAULT_GAME_SETTINGS[keyStr];
  const curVal = currentSettingsObj ? (currentSettingsObj as any)[keyStr] : undefined;
  const isModified = defaultVal !== undefined && curVal !== undefined && (typeof settingsValuesEqual === 'function' ? !settingsValuesEqual(curVal, defaultVal) : curVal !== defaultVal);
  const isSmartManaged = Boolean(entry.isSmartManaged || (typeof isSmartSettingsManagedKey === 'function' && isSmartSettingsManagedKey(keyStr as string)));
  const isInert = Boolean(depReport && depReport.violations && depReport.violations.some((v: any) => v.settingKey === keyStr));
  const isConflicted = Boolean(depReport && depReport.conflicts && depReport.conflicts.some((c: any) => c.settingA === keyStr || c.settingB === keyStr));
  const isDraftUnsaved = Boolean(draftSettings && draftSettings[keyStr] !== undefined && (typeof settingsValuesEqual === 'function' ? !settingsValuesEqual(draftSettings[keyStr], gameSettings[keyStr]) : draftSettings[keyStr] !== gameSettings[keyStr]));

  const breadcrumbTab = SETTINGS_HUB_TAB_LABELS[entry.tab] || entry.tab;
  const breadcrumbSection = section?.title || entry.category || 'General';
  const label = entry.label || meta?.label || String(keyStr);
  const description = entry.description || meta?.description || section?.keywords || '';

  const valType = typeof defaultVal;
  const isBoolean = valType === 'boolean';
  const isOption = (keyStr as string) === 'winCondition' || (keyStr as string) === 'teamBrainModeV63' || (keyStr as string) === 'teamOverviewDensity' || (keyStr as string) === 'settingsCategoryNavigationMode' || (keyStr as string) === 'teamModeAiDifficultyPreset';
  const isNumber = valType === 'number' && !entry.isSection;
  const isComplex = entry.isSection || (typeof curVal === 'object' && curVal !== null && !Array.isArray(curVal));

  return (
    <div className={`p-2 sm:p-2.5 rounded-lg border ${themeStyles.border || 'border-slate-700'} bg-black/40 hover:bg-black/60 transition-all flex flex-col gap-1.5 shadow-sm text-xs`}>
      {/* Top Bar: Breadcrumb Trail & State Badges */}
      <div className="flex flex-wrap items-center justify-between gap-1.5">
        <div className="flex items-center gap-1 text-[11px] font-medium opacity-80 text-sky-300 truncate max-w-[65%]">
          <span className="truncate">{breadcrumbTab}</span>
          <span>›</span>
          <span className="truncate">{breadcrumbSection}</span>
          {label !== breadcrumbSection && (
            <>
              <span>›</span>
              <span className="font-bold text-white truncate">{label}</span>
            </>
          )}
        </div>

        {/* State Badges */}
        <div className="flex flex-wrap items-center gap-1 shrink-0">
          {isModified && (
            <span className="px-1.5 py-0.5 rounded text-[10px] uppercase font-bold bg-amber-500/20 text-amber-300 border border-amber-500/40">
              Modified
            </span>
          )}
          {isDraftUnsaved && (
            <span className="px-1.5 py-0.5 rounded text-[10px] uppercase font-bold bg-purple-500/20 text-purple-300 border border-purple-500/40">
              Unsaved Draft
            </span>
          )}
          {isSmartManaged && (
            <span className="px-1.5 py-0.5 rounded text-[10px] uppercase font-bold bg-sky-500/20 text-sky-300 border border-sky-500/40">
              Smart Managed
            </span>
          )}
          {isInert && (
            <span className="px-1.5 py-0.5 rounded text-[10px] uppercase font-bold bg-amber-600/30 text-amber-200 border border-amber-600/50">
              Inert Warning
            </span>
          )}
          {isConflicted && (
            <span className="px-1.5 py-0.5 rounded text-[10px] uppercase font-bold bg-red-500/20 text-red-300 border border-red-500/40">
              Conflict
            </span>
          )}
          {entry.advancedOnly && (
            <span className="px-1.5 py-0.5 rounded text-[10px] uppercase font-bold bg-slate-700 text-slate-300 border border-slate-600">
              Advanced
            </span>
          )}
        </div>
      </div>

      {/* Main Row: Title, Description, Inline Control & Jump to Setting Button */}
      <div className="flex items-center justify-between gap-2 pt-1 border-t border-white/5">
        <div className="flex-1 min-w-0 pr-2">
          <div className="font-bold text-slate-100 flex items-center gap-1.5 text-xs truncate">
            <span className="truncate">{label}</span>
            <span className="text-[10px] font-mono opacity-50 font-normal shrink-0">({String(keyStr)})</span>
          </div>
          {description && (
            <p className="text-[11px] opacity-75 line-clamp-1 mt-0.5">{description}</p>
          )}
        </div>

        {/* Inline Controls & Jump to Setting Button */}
        <div className="flex items-center gap-2 shrink-0">
          {isBoolean && (
            <button
              type="button"
              onClick={() => onUpdateSetting(keyStr, !curVal)}
              className={`px-2 py-0.5 rounded text-[11px] font-bold transition-all shadow ${
                curVal
                  ? 'bg-emerald-600 hover:bg-emerald-500 text-white border border-emerald-400/30'
                  : 'bg-slate-700 hover:bg-slate-600 text-slate-200 border border-slate-600'
              }`}
            >
              {curVal ? 'ON' : 'OFF'}
            </button>
          )}

          {isOption && (
            <select
              value={String(curVal)}
              onChange={(e) => onUpdateSetting(keyStr, e.target.value)}
              className="rounded px-1.5 py-0.5 text-[11px] font-semibold bg-slate-800 border border-slate-600 text-white max-w-[130px]"
            >
              {(keyStr as string) === 'winCondition' && WIN_METRIC_OPTIONS.map(opt => (
                <option key={opt} value={opt}>{WIN_METRIC_LABELS[opt] || opt}</option>
              ))}
              {(keyStr as string) === 'teamBrainModeV63' && TEAM_BRAIN_MODE_OPTIONS_V63.map(mode => (
                <option key={mode} value={mode}>{TEAM_BRAIN_MODE_LABELS_V63[mode] || mode}</option>
              ))}
              {(keyStr as string) === 'teamOverviewDensity' && ['comfortable', 'compact'].map(d => (
                <option key={d} value={d}>{d}</option>
              ))}
              {(keyStr as string) === 'settingsCategoryNavigationMode' && ['full', 'collapsed_active', 'compact', 'current_only', 'category_dropdown', 'hidden'].map(m => (
                <option key={m} value={m}>{m}</option>
              ))}
              {(keyStr as string) === 'teamModeAiDifficultyPreset' && TEAM_MODE_AI_DIFFICULTY_PRESET_OPTIONS.map(d => (
                <option key={d} value={d}>{TEAM_MODE_AI_DIFFICULTY_PRESET_CONFIG[d]?.label || d}</option>
              ))}
            </select>
          )}

          {isNumber && !isOption && (
            <input
              type="number"
              value={curVal ?? 0}
              onChange={(e) => onUpdateSetting(keyStr, Number(e.target.value))}
              className="w-16 px-1.5 py-0.5 text-[11px] font-semibold bg-slate-800 border border-slate-600 rounded text-white"
            />
          )}

          {/* Jump to Setting 📍 Button */}
          <button
            type="button"
            onClick={() => onOpenSection(entry.tab, section?.id || entry.id, String(keyStr))}
            className="px-2.5 py-1 rounded text-xs font-bold bg-amber-600 hover:bg-amber-500 text-white shadow transition-all flex items-center gap-1 shrink-0"
            title="Jump to Setting in Main Workspace"
          >
            <span>Jump to Setting 📍</span>
          </button>
        </div>
      </div>
    </div>
  );
};

