export const SettingsImportExportModal: React.FC<SettingsImportExportModalProps> = ({
  isOpen,
  onClose,
  currentSettings,
  onApplyImportedSettings,
  themeStyles
}) => {
  const [activeTab, setActiveTab] = React.useState<'export' | 'import'>('export');
  const [importJsonText, setImportJsonText] = React.useState<string>('');
  const [importResult, setImportResult] = React.useState<{ success: boolean; settings?: Partial<GameSettingsState>; error?: string; diffCount?: number } | null>(null);
  const [copyFeedback, setCopyFeedback] = React.useState<boolean>(false);

  if (!isOpen) return null;

  const exportJsonStr = exportSettingsToJson(currentSettings);

  const handleCopyExport = () => {
    navigator.clipboard.writeText(exportJsonStr);
    setCopyFeedback(true);
    setTimeout(() => setCopyFeedback(false), 2500);
  };

  const handleDownloadExport = () => {
    const blob = new Blob([exportJsonStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `antigravity_settings_${new Date().toISOString().slice(0, 10)}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleValidateImport = () => {
    const res = importSettingsFromJson(importJsonText);
    setImportResult(res);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (evt) => {
      const text = evt.target?.result as string;
      if (text) {
        setImportJsonText(text);
        setImportResult(importSettingsFromJson(text));
      }
    };
    reader.readAsText(file);
  };

  return (
    <div className="fixed inset-0 z-[1050] bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
      <div className="bg-slate-900 border border-sky-500/40 rounded-xl shadow-2xl w-full max-w-3xl flex flex-col max-h-[calc(100dvh-2rem)] overflow-hidden text-slate-100">
        <div className="p-4 border-b border-white/10 flex items-center justify-between bg-slate-950">
          <div className="flex items-center gap-3">
            <h3 className="font-bold text-lg text-sky-400">📥 Import &amp; Export All Settings</h3>
            <div className="flex bg-slate-800 rounded p-0.5 border border-slate-700">
              <button
                type="button"
                onClick={() => setActiveTab('export')}
                className={`px-3 py-1 text-xs font-bold rounded ${activeTab === 'export' ? 'bg-sky-600 text-white' : 'text-slate-400 hover:text-slate-200'}`}
              >
                📤 Export Settings
              </button>
              <button
                type="button"
                onClick={() => setActiveTab('import')}
                className={`px-3 py-1 text-xs font-bold rounded ${activeTab === 'import' ? 'bg-sky-600 text-white' : 'text-slate-400 hover:text-slate-200'}`}
              >
                📥 Import Settings
              </button>
            </div>
          </div>
          <button type="button" onClick={onClose} className="text-slate-400 hover:text-white p-1 rounded">✕</button>
        </div>

        <div className="p-4 flex-1 overflow-y-auto space-y-4">
          {activeTab === 'export' ? (
            <div className="space-y-3">
              <p className="text-xs text-slate-300">
                Copy or download your complete current Antigravity game configuration as JSON.
              </p>
              <div className="relative">
                <textarea
                  readOnly
                  value={exportJsonStr}
                  rows={14}
                  className="w-full p-3 font-mono text-xs bg-slate-950 border border-slate-800 rounded-lg text-sky-300 focus:outline-none"
                />
              </div>
              <div className="flex justify-end gap-2">
                <button
                  type="button"
                  onClick={handleCopyExport}
                  className="px-4 py-2 rounded text-xs font-bold bg-slate-800 hover:bg-slate-700 text-sky-300 border border-sky-500/30 flex items-center gap-1.5"
                >
                  <span>{copyFeedback ? '✅ Copied to Clipboard!' : '📋 Copy JSON'}</span>
                </button>
                <button
                  type="button"
                  onClick={handleDownloadExport}
                  className="px-4 py-2 rounded text-xs font-bold bg-sky-600 hover:bg-sky-500 text-white flex items-center gap-1.5"
                >
                  <span>💾 Download JSON File</span>
                </button>
              </div>
            </div>
          ) : (
            <div className="space-y-4">
              <div className="p-3 bg-slate-950 border border-slate-800 rounded-lg space-y-2">
                <label className="block text-xs font-bold text-sky-300">Option 1: Upload Settings JSON File</label>
                <input
                  type="file"
                  accept=".json,application/json"
                  onChange={handleFileUpload}
                  className="block w-full text-xs text-slate-400 file:mr-3 file:py-1.5 file:px-3 file:rounded file:border-0 file:text-xs file:font-bold file:bg-sky-600 file:text-white hover:file:bg-sky-500"
                />
              </div>

              <div className="space-y-2">
                <label className="block text-xs font-bold text-sky-300">Option 2: Paste Settings JSON Content</label>
                <textarea
                  value={importJsonText}
                  onChange={e => { setImportJsonText(e.target.value); setImportResult(null); }}
                  placeholder="Paste Antigravity settings JSON here..."
                  rows={8}
                  className="w-full p-3 font-mono text-xs bg-slate-950 border border-slate-800 rounded-lg text-slate-200"
                />
                <button
                  type="button"
                  onClick={handleValidateImport}
                  className="px-4 py-1.5 rounded text-xs font-bold bg-sky-700 hover:bg-sky-600 text-white"
                >
                  Validate JSON Format
                </button>
              </div>

              {importResult && (
                <div className={`p-3.5 rounded-lg border text-xs space-y-2 ${importResult.success ? 'bg-emerald-950/40 border-emerald-500/40 text-emerald-200' : 'bg-red-950/40 border-red-500/40 text-red-200'}`}>
                  {importResult.success ? (
                    <div>
                      <div className="font-bold flex items-center gap-1 text-emerald-400">
                        <span>✅ Validated JSON schema successfully!</span>
                      </div>
                      <p className="mt-1">Found <strong>{importResult.diffCount}</strong> recognized setting keys to apply.</p>
                      <button
                        type="button"
                        onClick={() => {
                          if (importResult.settings) {
                            onApplyImportedSettings(importResult.settings);
                            onClose();
                          }
                        }}
                        className="mt-3 px-4 py-2 font-bold rounded bg-emerald-600 hover:bg-emerald-500 text-white"
                      >
                        Apply Imported Settings Now
                      </button>
                    </div>
                  ) : (
                    <div>
                      <div className="font-bold text-red-400">❌ Import Validation Failed</div>
                      <p className="mt-1">{importResult.error}</p>
                    </div>
                  )}
                </div>
              )}
            </div>
          )}
        </div>

        <div className="p-4 border-t border-white/10 flex justify-end bg-slate-950">
          <button type="button" onClick={onClose} className="px-4 py-2 rounded text-xs font-bold bg-slate-800 hover:bg-slate-700 text-slate-200">
            Close
          </button>
        </div>
      </div>
    </div>
  );
};


export interface UnsavedInterfacePreviewModalProps {
  isOpen: boolean;
  onClose: () => void;
  gameSettings: GameSettingsState;
  draftSettings: Partial<GameSettingsState>;
  onApplyChanges: () => void;
  onDiscardDrafts: () => void;
  onDiscardSingleField: (key: keyof GameSettingsState) => void;
  themeStyles: any;
  depReport?: any;
}

export const UnsavedInterfacePreviewModal: React.FC<UnsavedInterfacePreviewModalProps> = ({
  isOpen,
  onClose,
  gameSettings,
  draftSettings,
  onApplyChanges,
  onDiscardDrafts,
  onDiscardSingleField,
  themeStyles,
  depReport
}) => {
  if (!isOpen) return null;

  const modifiedKeys = (Object.keys(draftSettings) as (keyof GameSettingsState)[]).filter(k => {
    const cur = gameSettings[k];
    const draft = draftSettings[k];
    return draft !== undefined && (typeof settingsValuesEqual === 'function' ? !settingsValuesEqual(cur, draft) : cur !== draft);
  });

  return (
    <div className="fixed inset-0 z-[1000] bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
      <div className="bg-slate-900 border border-amber-500/40 rounded-xl shadow-2xl w-full max-w-3xl flex flex-col max-h-[calc(100dvh-2rem)] overflow-hidden text-slate-100">
        {/* Header */}
        <div className="p-4 border-b border-white/10 flex items-center justify-between bg-amber-950/40">
          <div className="flex items-center gap-2 font-bold text-lg text-amber-300">
            <span>🛡️ Unsaved Interface Preview</span>
            <span className="text-xs px-2.5 py-0.5 rounded-full bg-amber-500/20 text-amber-200 border border-amber-500/30 font-semibold">
              {modifiedKeys.length} Setting{modifiedKeys.length !== 1 ? 's' : ''} Modified
            </span>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="text-slate-400 hover:text-white p-1 rounded text-sm transition-colors"
          >
            ✕
          </button>
        </div>

        {/* Diff List Body */}
        <div className="p-4 overflow-y-auto space-y-3 flex-1">
          {modifiedKeys.length === 0 ? (
            <div className="text-sm opacity-75 py-8 text-center">No unsaved draft changes pending.</div>
          ) : (
            modifiedKeys.map(keyStr => {
              const meta = SETTINGS_HUB_FIELD_META[keyStr as string];
              const section = SETTINGS_HUB_SECTION_INDEX.find(s => s.fieldKeys.includes(keyStr));
              const appliedVal = gameSettings[keyStr];
              const draftVal = draftSettings[keyStr];

              const defaultVal = DEFAULT_GAME_SETTINGS[keyStr];
              const isResetToDefault = (typeof settingsValuesEqual === 'function' ? settingsValuesEqual(draftVal, defaultVal) : draftVal === defaultVal);

              const isInert = Boolean(depReport && depReport.violations && depReport.violations.some((v: any) => v.settingKey === keyStr));
              const isConflicted = Boolean(depReport && depReport.conflicts && depReport.conflicts.some((c: any) => c.settingA === keyStr || c.settingB === keyStr));

              return (
                <div key={String(keyStr)} className="p-3 rounded-lg border border-slate-700 bg-black/40 flex flex-col gap-2 text-xs">
                  <div className="flex flex-wrap items-center justify-between gap-2 border-b border-white/10 pb-1.5">
                    <div className="font-bold text-sm text-sky-300">
                      {meta?.label || section?.title || String(keyStr)}
                      <span className="text-[10px] font-mono opacity-50 font-normal ml-2">({String(keyStr)})</span>
                    </div>
                    <div className="flex items-center gap-1.5">
                      {isResetToDefault ? (
                        <span className="px-2 py-0.5 rounded text-[10px] uppercase font-bold bg-blue-500/20 text-blue-300 border border-blue-500/30">
                          Reset to Default
                        </span>
                      ) : (
                        <span className="px-2 py-0.5 rounded text-[10px] uppercase font-bold bg-amber-500/20 text-amber-300 border border-amber-500/30">
                          Custom Edit
                        </span>
                      )}
                      {isInert && (
                        <span className="px-2 py-0.5 rounded text-[10px] uppercase font-bold bg-amber-600/30 text-amber-200 border border-amber-600/50">
                          Inert Warning
                        </span>
                      )}
                      {isConflicted && (
                        <span className="px-2 py-0.5 rounded text-[10px] uppercase font-bold bg-red-500/20 text-red-300 border border-red-500/30">
                          Conflict Rule
                        </span>
                      )}
                      <button
                        type="button"
                        onClick={() => onDiscardSingleField(keyStr)}
                        className="px-2 py-0.5 rounded text-[11px] bg-slate-700 hover:bg-slate-600 text-slate-300 transition"
                        title="Revert draft change for this field"
                      >
                        Revert
                      </button>
                    </div>
                  </div>

                  {/* Side-by-Side Comparison */}
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-3 pt-1">
                    <div className="p-2 rounded bg-slate-800/80 border border-slate-700">
                      <span className="text-[11px] font-semibold text-slate-400 block mb-1">Applied (Current Baseline):</span>
                      <div className="font-mono text-xs text-red-300 break-all">
                        {typeof appliedVal === 'object' ? JSON.stringify(appliedVal) : String(appliedVal)}
                      </div>
                    </div>
                    <div className="p-2 rounded bg-amber-950/40 border border-amber-500/30">
                      <span className="text-[11px] font-semibold text-amber-300 block mb-1">Draft (Unsaved Preview):</span>
                      <div className="font-mono text-xs text-emerald-300 break-all">
                        {typeof draftVal === 'object' ? JSON.stringify(draftVal) : String(draftVal)}
                      </div>
                    </div>
                  </div>
                </div>
              );
            })
          )}
        </div>

        {/* Footer Actions */}
        <div className="p-4 border-t border-white/10 flex flex-wrap items-center justify-between gap-2 bg-slate-950">
          <button
            type="button"
            onClick={onDiscardDrafts}
            className="px-4 py-2 rounded text-xs font-semibold bg-slate-800 hover:bg-slate-700 text-slate-300 transition"
          >
            Discard All Drafts
          </button>
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 rounded text-xs font-semibold bg-slate-800 hover:bg-slate-700 text-slate-200 transition"
            >
              Continue Editing
            </button>
            <button
              type="button"
              onClick={() => {
                onApplyChanges();
                onClose();
              }}
              className="px-4 py-2 rounded text-xs font-bold bg-amber-600 hover:bg-amber-500 text-white shadow transition"
            >
              Apply All Changes
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export interface UnsavedInterfacePreviewBannerProps {
  currentSettings: GameSettingsState;
  savedSettings: GameSettingsState;
  onApplyChanges?: () => void;
  onResetUnsaved?: () => void;
  onOpenDiffModal?: () => void;
  className?: string;
}

export const UnsavedInterfacePreviewBannerComponent: React.FC<UnsavedInterfacePreviewBannerProps> = ({
  currentSettings,
  savedSettings,
  onApplyChanges,
  onResetUnsaved,
  onOpenDiffModal,
  className
}) => {
  const dirtyChanges = useMemo(() => {
    const keys = Object.keys(currentSettings) as (keyof GameSettingsState)[];
    return keys.filter(k => {
      const cur = currentSettings[k];
      const sav = savedSettings[k];
      return typeof settingsValuesEqual === 'function' ? !settingsValuesEqual(cur, sav) : cur !== sav;
    });
  }, [currentSettings, savedSettings]);

  if (dirtyChanges.length === 0) {
    return null;
  }

  return (
    <div className={`bg-amber-950/90 border border-amber-500/50 text-amber-100 px-4 py-2.5 rounded-lg flex flex-wrap items-center justify-between gap-2 shadow-lg ${className || ''}`}>
      <div className="flex items-center space-x-2">
        <span className="text-amber-400 font-bold">⚠️ Unsaved Preview Changes</span>
        <span className="text-xs text-amber-200 font-semibold">
          ({dirtyChanges.length} setting{dirtyChanges.length > 1 ? 's' : ''} modified in draft)
        </span>
      </div>
      <div className="flex items-center space-x-2">
        {onOpenDiffModal && (
          <button
            type="button"
            onClick={onOpenDiffModal}
            className="px-2.5 py-1 text-xs bg-amber-700/80 hover:bg-amber-600 text-white rounded font-semibold transition-colors flex items-center gap-1"
          >
            <span>👁️ Preview Diffs</span>
          </button>
        )}
        <button
          type="button"
          onClick={onResetUnsaved}
          className="px-2.5 py-1 text-xs bg-gray-800 hover:bg-gray-700 text-gray-200 rounded font-medium transition-colors"
        >
          Discard Draft
        </button>
        <button
          type="button"
          onClick={onApplyChanges}
          className="px-3 py-1 text-xs bg-amber-600 hover:bg-amber-500 text-white rounded font-semibold transition-colors shadow"
        >
          Apply Changes
        </button>
      </div>
    </div>
  );
};

export const SettingsSectionFinder = SectionFinderComponent;
export const UnsavedInterfacePreviewBanner = UnsavedInterfacePreviewBannerComponent;




