                            return toggle.key === 'aiStrategyLabSafeRangesEnabled' || toggle.key === 'aiStrategyLabExtremeModeEnabled'
                              ? clampTeamBrainSlidersForSettings(nextSettingsWithClampedAiFactors)
                              : nextSettingsWithClampedAiFactors;
