                        <div>
                          <SettingsSlider label={(v) => <>Member Vote Weight: {v}</>} id="setting-slider-governance-member-vote-weight" min="0.5" max="5.0" step="0.1" value={gameSettings.governanceMemberVoteWeight} onChange={(val) => trackedSetGameSettings("direct_player_change", "Governance", prev => ({ ...prev, governanceMemberVoteWeight: val }))} className="w-full" />
                        </div>
                        <div>
